    /// <summary>
    /// Edit MSI - Phase 1: browse every table of an MSI database
    /// and generate a .mst transform from staged Property-table changes.
    /// Uses the Windows Installer COM automation API (msi.dll) — no external tools.
    /// </summary>
    public partial class EditMSIPage : Page
    {
        private string _msiPath = "";
        private readonly ObservableCollection<PropChange> _changes = new();

        // Per-table edit state: cached DataTable (RowState tracks edits), key columns,
        // column types ('i' int / 's' string / 'v' binary) — preserved across table switches.
        private sealed class TableState
        {
            public DataTable Data = new();
            public List<string> KeyCols = new();
            public Dictionary<string, char> ColKind = new(StringComparer.OrdinalIgnoreCase);
            public int RowCount;

            // Columns the MSI schema marks nullable (an uppercase type letter). A nullable column
            // can still be part of the primary key - LockPermissions.Domain is one - and a blank
            // one there is a complete row, not an unfinished one.
            public HashSet<string> NullableCols = new(StringComparer.OrdinalIgnoreCase);

            // The MSI type token as reported for each column (s72, S255, i2, v0 ...). Kept whole
            // rather than reduced to a kind letter so the grid can say what a column will accept.
            public Dictionary<string, string> ColType = new(StringComparer.OrdinalIgnoreCase);

            // Set only for a table SwiftPack invented because the package does not have it. Holds
            // the CREATE TABLE that has to run before any of its rows can be inserted; empty for
            // every table read out of the MSI.
            public string CreateSql = "";

            // Rows the user marked for deletion. They stay live (and visible) in the
            // grid as red, struck-through "ghosts" until the transform is applied or
            // saved, at which point they become real DELETEs. Tracked by reference.
            public HashSet<DataRow> MarkedDelete = new();
        }
        private readonly Dictionary<string, TableState> _tables = new(StringComparer.OrdinalIgnoreCase);

        // Copy Row / Paste Row clipboard (Tables view). Holds the source table name and the copied
        // row's cell values by column name, so Paste can recreate the row in the same (or a
        // column-compatible) table. Null when nothing has been copied yet.
        private string _copiedRowTable = "";
        private Dictionary<string, string>? _copiedRowValues;

        // File key -> source path on disk for files added via the Files view, so Save
        // can embed their bytes into a cabinet inside the saved MSI.
        private readonly Dictionary<string, string> _addedFileSources = new(StringComparer.OrdinalIgnoreCase);

        // Icon name -> source path on disk for icons added through the icon picker's Browse. An
        // icon is a stream in the Icon table, and stream bytes cannot travel through SQL, so the
        // row goes in now and its bytes are written at save time (see EmbedAddedStreams).
        private readonly Dictionary<string, string> _addedIconSources = new(StringComparer.OrdinalIgnoreCase);

        // Binary name -> source path on disk for binaries brought in through the picker's Browse.
        // Same arrangement as the icons above, and for the same reason: Binary.Data is a stream.
        private readonly Dictionary<string, string> _addedBinarySources = new(StringComparer.OrdinalIgnoreCase);

        /// <summary>Where an added file's bytes end up once the package is saved.</summary>
        private enum FileMedia
        {
            StreamedCab,    // a new cabinet stored inside the MSI
            ExternalCab,    // a new .cab written beside the MSI
            Uncompressed    // loose files written beside the MSI in their install layout
        }

        private readonly Dictionary<string, FileMedia> _addedFileMedia = new(StringComparer.OrdinalIgnoreCase);
        private string _currentTable = "";
        private int _preloadGeneration = 0;
        private System.Windows.Threading.DispatcherTimer? _preloadTimer;
        private bool _preloadComplete = false;

        // Property list + per-property value options/defaults. Loaded from
        // Templates\EditMSI.json (Properties section); falls back to these
        // built-ins when the file is missing or unreadable.
        private readonly Dictionary<string, (List<string> Options, string Default)> _propOptions =
            new(StringComparer.OrdinalIgnoreCase)
        {
            ["ALLUSERS"]      = (new List<string> { "1", "2", "" }, "1"),
            ["REBOOT"]        = (new List<string> { "ReallySuppress", "Suppress", "Force", "" }, "ReallySuppress"),
            ["ARPNOMODIFY"]   = (new List<string> { "1", "0", "" }, "1"),
            ["ARPNOREPAIR"]   = (new List<string> { "1", "0", "" }, "1"),
            ["ARPNOREMOVE"]   = (new List<string> { "1", "0", "" }, "1"),
            ["REINSTALLMODE"] = (new List<string> { "omus", "vomus", "" }, "omus"),
        };

        private void LoadPropertyConfig()
        {
            try
            {
                const string path = @"C:\Program Files\Smekal\SwiftPack Studio\Templates\EditMSI.json";
                string p2 = Path.Combine(AppContext.BaseDirectory, "Resources", "EditMSI.json");
                string use = File.Exists(path) ? path : (File.Exists(p2) ? p2 : "");
                if (use.Length == 0) return;
                using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(use),
                    new System.Text.Json.JsonDocumentOptions { AllowTrailingCommas = true });
                if (!doc.RootElement.TryGetProperty("Properties", out var props)) return;
                _propOptions.Clear();
                foreach (var pe in props.EnumerateObject())
                {
                    var opts = new List<string>();
                    string def = "";
                    if (pe.Value.TryGetProperty("Options", out var oArr))
                        foreach (var o in oArr.EnumerateArray()) opts.Add(o.GetString() ?? "");
                    if (pe.Value.TryGetProperty("Default", out var dEl)) def = dEl.GetString() ?? "";
                    _propOptions[pe.Name] = (opts, def);
                }
            }
            catch { /* keep built-in fallbacks */ }
        }

        public EditMSIPage()
        {
            InitializeComponent();
            this.Loaded += EditMSIPage_Loaded;
            this.PreviewMouseWheel += OnPreviewMouseWheel;
            LstValidation.ItemsSource = _validation;
            LstTransform.ItemsSource = _transformChanges;
            LoadPropertyConfig();
            // Plain strings, not ComboBoxItems: the page's ComboBox template is the editable one,
            // which shows the item's own text and has no content presenter to render a container.
            FsUac.Items.Add("Required");
            FsUac.Items.Add("Not required");
            GridRows.LoadingRow += (_, a) => PaintRow(a.Row);
            GridRows.AutoGeneratedColumns += GridRows_AutoGeneratedColumns;
            GridRows.SizeChanged += (_, _) => ScheduleFitLastColumn();
            FormGrid.AutoGeneratedColumns += FormGrid_AutoGeneratedColumns;
            FormGrid.RowEditEnding += (_, _) =>
                Dispatcher.BeginInvoke(new Action(UpdateEditCount),
                    System.Windows.Threading.DispatcherPriority.Background);
            GridRows.RowEditEnding += (_, _) => DeferRefreshVisuals();
            GridRows.CurrentCellChanged += GridRows_CurrentCellChanged;
            GridRows.SelectionChanged += (_, _) => UpdateRowButtonState();
            // Prevent editing a row that's marked for deletion (a ghost).
            GridRows.BeginningEdit += (_, a) =>
            {
                if (a.Row?.Item is DataRowView drv &&
                    _tables.TryGetValue(_currentTable, out var st) &&
                    st.MarkedDelete.Contains(drv.Row))
                    a.Cancel = true;
            };

            // No MSI is open yet — keep all editing affordances disabled.
            SetEditingLocked(true);
            SetViewMode(true);    // start in Form view; toggle reflects it
        }

        // Tracks the added row the caret currently sits on, so that when the user
        // clicks away to a different row we can check whether they left it incomplete.
        private DataRow? _watchedAddedRow;

        private void GridRows_CurrentCellChanged(object? sender, EventArgs e)
        {
            DeferRefreshVisuals();
            if (_promptingIncomplete) return;
            if (!_tables.TryGetValue(_currentTable, out var st)) return;

            DataRow? current = (GridRows.CurrentItem as DataRowView)?.Row;

            // Find any incomplete added row in this table that the caret is NOT
            // currently sitting on. Moving to a different row (even within the same
            // table) should trigger the prompt for the row just left.
            DataRow? incomplete = null;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState != DataRowState.Added) continue;
                if (ReferenceEquals(r, current)) continue;     // still being edited — leave it
                if (IsRowIncomplete(st, r)) { incomplete = r; break; }
            }

            if (incomplete != null)
            {
                var leaving = incomplete;
                // Deferred so the grid finishes its own edit/commit bookkeeping
                // before a modal dialog appears.
                Dispatcher.BeginInvoke(new Action(() => CheckRowOnLeave(leaving)),
                    System.Windows.Threading.DispatcherPriority.Background);
            }

            // Keep a reference to the added row currently under the caret (used by
            // other validation paths).
            _watchedAddedRow = (current != null && current.RowState == DataRowState.Added) ? current : null;
        }

        /// <summary>True when an added row is entirely empty or missing a key value.</summary>
        private static bool IsRowIncomplete(TableState st, DataRow r)
        {
            if (r.RowState != DataRowState.Added) return false;
            var keys = st.KeyCols.Count > 0
                ? st.KeyCols
                : (st.Data.Columns.Count > 0 ? new List<string> { st.Data.Columns[0].ColumnName } : new List<string>());
            bool anyData = st.Data.Columns.Cast<DataColumn>()
                .Any(c => !string.IsNullOrWhiteSpace((r[c] ?? "").ToString()));
            bool keyMissing = keys.Any(k =>
                st.Data.Columns.Contains(k) && !st.NullableCols.Contains(k) &&
                string.IsNullOrWhiteSpace((r[k] ?? "").ToString()));
            return !anyData || keyMissing;
        }

        private bool _promptingIncomplete = false;

        /// <summary>Validate a single just-left added row; prompt if incomplete.</summary>
        private void CheckRowOnLeave(DataRow row)
        {
            if (_promptingIncomplete) return;
            if (!_tables.TryGetValue(_currentTable, out var st)) return;
            if (row.RowState != DataRowState.Added) return;          // already saved/deleted
            if (!IsRowIncomplete(st, row)) return;                   // row is fine

            _promptingIncomplete = true;
            try
            {
                string keyList = st.KeyCols.Count > 0 ? string.Join(", ", st.KeyCols) : "the required";
                var choice = MstMessage(
                    $"A newly added row in “{_currentTable}” is incomplete - {keyList} value(s) must be filled in.\n\n" +
                    "Click Yes to delete this empty row, or No to go back and fill it in.",
                    "Incomplete row", MessageBoxButton.YesNo, MessageBoxImage.Warning);

                if (choice == MessageBoxResult.Yes)
                {
                    if (row.RowState != DataRowState.Deleted) row.Delete();
                    DeferRefreshVisuals();
                }
                else
                {
                    var view = GridRows.ItemsSource as DataView;
                    if (view != null)
                        foreach (DataRowView drv in view)
                            if (ReferenceEquals(drv.Row, row))
                            {
                                GridRows.SelectedItem = drv;
                                GridRows.ScrollIntoView(drv);
                                _watchedAddedRow = row;   // keep watching until completed
                                break;
                            }
                }
            }
            finally { _promptingIncomplete = false; }
        }

        public class PropChange
        {
            public string Name   { get; set; } = "";
            public string Value  { get; set; } = "";
            public string Action { get; set; } = "";   // "Update" or "Add"
        }

        // ── COM helpers ──────────────────────────────────────────────────
        private static dynamic NewInstaller()
        {
            var t = Type.GetTypeFromProgID("WindowsInstaller.Installer")
                    ?? throw new InvalidOperationException("Windows Installer COM is not available.");
            return Activator.CreateInstance(t)!;
        }

        private static void Release(object? com)
        {
            try { if (com != null && Marshal.IsComObject(com)) Marshal.ReleaseComObject(com); }
            catch { }
        }

        private static string Esc(string s) => (s ?? "").Replace("'", "''");

        // ── Unsaved edits ────────────────────────────────────────────────
        // Browse and Apply MST both replace the open package outright, clearing every staged
        // row, so leaving without asking would throw the work away silently.

        /// <summary>Set by the two save paths so a caller can tell a real save from a cancelled
        /// or failed one, since both report through a dialog and return nothing.</summary>
        private bool _saveSucceeded;

        /// <summary>
        /// The staged state as it stood at the last successful save. A transform save cannot clear
        /// the staged edits the way an MSI save can - the transform is regenerated from them on
        /// every save, so they have to stay put - which left every later Browse claiming there was
        /// unsaved work. "Unsaved" is the difference from this mark rather than the presence of any
        /// edit at all.
        /// </summary>
        private string _savedEditMark = "";

        /// <summary>
        /// A fingerprint of everything staged. Counts alone were not enough: editing a cell on a
        /// row that was already modified leaves every count exactly where it was, and the package
        /// would then still look saved. Only rows carrying an edit are walked, so the cost follows
        /// the work in progress rather than the size of the package, and both dictionaries are read
        /// in key order so the same state always fingerprints the same way.
        /// </summary>
        private string EditStateMark()
        {
            var sb = new System.Text.StringBuilder();
            sb.Append(_changes.Count).Append('\u001E');
            foreach (uint pid in _summaryEdits.Keys.OrderBy(x => x))
                sb.Append(pid).Append('=').Append(_summaryEdits[pid]).Append('\u001F');
            sb.Append('\u001E');

            foreach (string name in _tables.Keys.OrderBy(x => x, StringComparer.Ordinal))
            {
                var st = _tables[name];
                foreach (DataRow r in st.Data.Rows)
                {
                    bool marked = st.MarkedDelete.Contains(r);
                    if (r.RowState == DataRowState.Unchanged && !marked) continue;
                    sb.Append(name).Append(':').Append((int)r.RowState).Append(marked ? "!" : ":");
                    if (r.RowState != DataRowState.Deleted && r.RowState != DataRowState.Detached)
                        foreach (DataColumn c in st.Data.Columns) sb.Append(Cv(r[c])).Append('\u001F');
                    sb.Append('\u001E');
                }
            }
            return sb.ToString();
        }

        /// <summary>True when something is staged that replacing the package would discard.</summary>
        private bool HasUnsavedEdits()
        {
            if (_msiPath.Length == 0) return false;
            if (_changes.Count == 0 && PendingEditCount() == 0 && _summaryEdits.Count == 0) return false;
            return EditStateMark() != _savedEditMark;
        }

        /// <summary>
        /// Clears the staged edits after they have been written into the open MSI. Only the MSI
        /// path calls this: those rows are now the file's own contents, so AcceptChanges is the
        /// truth. The added-file, icon and binary sources go too, since their bytes are in the
        /// package and a second save would otherwise embed them again.
        /// </summary>
        private void AcceptSavedEdits()
        {
            foreach (var st in _tables.Values)
            {
                st.MarkedDelete.Clear();
                st.Data.AcceptChanges();
            }
            _changes.Clear();
            // Carried across rather than dropped: the boxes still show what was just written, and
            // the next edit is compared against these to decide whether anything changed.
            foreach (var kv in _summaryEdits) _summaryOriginal[kv.Key] = kv.Value;
            _summaryEdits.Clear();
            _addedFileSources.Clear();
            _addedFileMedia.Clear();
            _addedIconSources.Clear();
            _addedBinarySources.Clear();
            // Dropped after a save too: a binary browsed in this session was not in the file when
            // the dialog canvas first looked for it, and the miss would otherwise be cached for good.
            _binaryImages.Clear();
            _watchedAddedRow = null;
            UpdateEditCount();
        }

        /// <summary>
        /// Asks what to do with staged edits before the open package is replaced. Returns false
        /// when the caller must stop: the user cancelled, or chose to save and the save did not
        /// go through, in which case the edits are still there to deal with.
        /// </summary>
        private bool ConfirmSaveBeforeLeaving(string action)
        {
            if (!HasUnsavedEdits()) return true;

            string what = _viewingTransform ? "transform" : "MSI";
            var answer = AskSaveDiscardCancel(
                "The open " + what + " has unsaved changes.\n\nSave them before " + action + "?",
                "Unsaved changes");

            if (answer == MessageBoxResult.Cancel) return false;
            if (answer == MessageBoxResult.No) return true;          // discard and carry on

            BtnSaveMsi_Click(this, new RoutedEventArgs());
            return _saveSucceeded;
        }

        /// <summary>
        /// Closes whatever is open and returns the page to the state it has when Edit MSI is first
        /// reached: no package, no staged edits, nothing cached. The same reset the open path does
        /// before loading a file, with no file to load afterwards - so it cannot drift from what
        /// opening a package actually clears.
        /// </summary>
        private void BtnMsiNew_Click(object sender, RoutedEventArgs e)
        {
            if (!ConfirmSaveBeforeLeaving("starting over")) return;

            _msiPath = "";
            _viewingTransform = false; TxtMsiPath.Tag = null;
            _transformOriginalMsi = ""; _appliedMstPath = "";
            _diffKeys = new(StringComparer.OrdinalIgnoreCase);
            _diffComputed = new(StringComparer.OrdinalIgnoreCase);
            _appliedTransformChanges = new();
            _watchedAddedRow = null;
            ClearValidation(); ClearTransformChanges();
            _transformAutoShown = false;

            TxtMsiPath.Text = "";
            LstTables.ItemsSource = null;
            UpdateTablesHeader();
            LstTables.SelectedItem = null;
            GridRows.ItemsSource = null;
            _changes.Clear();
            _savedEditMark = "";
            _tables.Clear(); _currentTable = "";
            _addedFileSources.Clear();
            _addedIconSources.Clear();
            _addedBinarySources.Clear();
            _binaryImages.Clear();
            _addedFileMedia.Clear();
            _msiTableNames.Clear();
            _dirRoots = null; _dirTreeBuiltFor = "\0";
            _regRoots = null; _regTreeBuiltFor = "\0";
            _scRoots = null;  _scTreeBuiltFor = "\0";
            _featRoots = null; _featTreeBuiltFor = "\0";

            _preloadComplete = false;
            _preloadTimer?.Stop();
            _preloadGeneration++;          // any load still in flight lands on a stale generation
            SetEditingLocked(true);
            BtnViewMst.IsEnabled = false;
            UpdateSearchEnabled();
            UpdateEditCount();

            PopulateProductInfo();
            PopulateSummaryInfo(false);
            if (LstCategories != null) LstCategories.SelectedIndex = 0;
            ShowCategory();

            TxtStatus.Text = "Ready. Browse for an MSI to edit.";
        }

        // ── Browse for MSI ───────────────────────────────────────────────
        private void BtnOpenMsi_Click(object sender, RoutedEventArgs e)
        {
            // Asked before the file picker, so the choice is not made after picking a file.
            if (!ConfirmSaveBeforeLeaving("opening another package")) return;

            var dlg = new OpenFileDialog
            {
                Title  = "Select MSI file",
                Filter = "Windows Installer Database (*.msi)|*.msi"
            };
            if (dlg.ShowDialog() != true) return;
            OpenMsiAt(dlg.FileName);
        }

        /// <summary>
        /// Opens a package, replacing whatever is loaded. Split out of the Browse handler so the
        /// merge-module flow can reload the file it just rewrote; asks nothing, so every caller
        /// settles unsaved edits first.
        /// </summary>
        private void OpenMsiAt(string path)
        {
            try
            {
                var tables = ReadTableNames(path);
                _msiPath = path;
                _viewingTransform = false; TxtMsiPath.Tag = null;
                _transformOriginalMsi = ""; _appliedMstPath = "";
                _diffKeys = new(StringComparer.OrdinalIgnoreCase);
                _diffComputed = new(StringComparer.OrdinalIgnoreCase);
                _appliedTransformChanges = new();
                _watchedAddedRow = null;
                ClearValidation(); ClearTransformChanges();
                _transformAutoShown = false;
                if (TabValidation != null) TabValidation.IsChecked = true;   // fresh MSI → Validation view
                TxtMsiPath.Text = _msiPath;
                LstTables.ItemsSource = BuildTableListing(tables);
                UpdateTablesHeader();
                GridRows.ItemsSource = null;
                _changes.Clear();
                _savedEditMark = "";               // a fresh package has never been saved from here
                _tables.Clear(); _currentTable = "";
                _addedFileSources.Clear();
                _addedIconSources.Clear();
                _addedBinarySources.Clear();
                _binaryImages.Clear();          // decoded from the old package, meaningless now
                _addedFileMedia.Clear();
                _dirRoots = null; _dirTreeBuiltFor = "\0";   // force Files tree rebuild
                _regRoots = null; _regTreeBuiltFor = "\0";   // force Registry tree rebuild
                _scRoots = null;  _scTreeBuiltFor = "\0";    // force Shortcuts tree rebuild
                _featRoots = null; _featTreeBuiltFor = "\0";  // force Features tree rebuild

                // Lock editing only briefly — until the database is open and the
                // first table is shown. Tables load lazily on demand (LoadTable),
                // so there is no need to read every row of every table up front
                // (that made large MSIs take many seconds to "upload").
                _preloadComplete = false;
                SetEditingLocked(true);
                BtnViewMst.IsEnabled = false; UpdateSearchEnabled();
                int gen = ++_preloadGeneration;
                _preloadTimer?.Stop();
                TxtStatus.Text = "Opening MSI…";
                // Re-selecting the same table name would not refire SelectionChanged,
                // so reset the selection and then load the first table explicitly.
                LstTables.SelectedItem = null;
                string first = tables.Contains("Property") ? "Property" : (tables.FirstOrDefault() ?? "");
                if (first.Length > 0)
                {
                    LstTables.SelectedItem = first;
                    if (GridRows.ItemsSource == null)
                    {
                        _currentTable = first;
                        var stFirst = LoadTable(first);
                        if (stFirst != null)
                        {
                            _tables[first] = stFirst;
                            GridRows.ItemsSource = stFirst.Data.DefaultView;
                            // Edit buttons unlock below once the MSI is ready.
                        }
                    }
                }

                // The MSI is open and the first table is shown — unlock editing.
                OnMsiReady(gen, tables.Count);
                if (_formMode) ShowCategory();
            }
            catch (Exception ex)
            {
                MstMessage("Could not open the MSI:\n\n" + ex.Message,
                    "Create MST", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        // ══ Merge modules ═════════════════════════════════════════════════
        // A form over mergemod.dll. Unlike every other category this one is not staged: mergemod
        // rewrites the package on disk in one transaction, so the flow is save-first, merge, then
        // reload the file that was just rewritten.

        private void ShowMergeModulesForm()
        {
            if (FormMergeModPanel == null) return;
            FormMergeModPanel.Visibility = Visibility.Visible;

            if (MmDirectory != null)
            {
                string keep = MmDirectory.SelectedItem as string ?? "TARGETDIR";
                MmDirectory.Items.Clear();
                foreach (var (value, _) in PackageDirs()) MmDirectory.Items.Add(value);
                int i = MmDirectory.Items.IndexOf(keep);
                if (i < 0) i = MmDirectory.Items.IndexOf("TARGETDIR");
                MmDirectory.SelectedIndex = i >= 0 ? i : (MmDirectory.Items.Count > 0 ? 0 : -1);
            }

            if (MmFeature != null)
            {
                string keep = MmFeature.SelectedItem as string ?? "";
                MmFeature.Items.Clear();
                var fst = EnsureTableCached("Feature");
                if (fst != null && fst.Data.Columns.Contains("Feature"))
                    foreach (DataRow r in fst.Data.Rows)
                        if (r.RowState != DataRowState.Deleted && Cv(r["Feature"]) is { Length: > 0 } f)
                            MmFeature.Items.Add(f);
                int i = keep.Length > 0 ? MmFeature.Items.IndexOf(keep) : -1;
                MmFeature.SelectedIndex = i >= 0 ? i : (MmFeature.Items.Count > 0 ? 0 : -1);
            }

            if (MmMedia != null && MmMedia.Items.Count == 0)
            {
                MmMedia.Items.Add("Embed a cabinet inside the MSI");
                MmMedia.Items.Add("Cabinet file next to the MSI");
                MmMedia.SelectedIndex = 0;
            }

            // What the package records about modules already merged into it. ModuleSignature rows
            // are ModuleID / Language / Version; a package merged by a tool that dropped the table
            // keeps the merged rows but no record of the module, so an empty list is not proof of
            // an unmerged package.
            var rows = new List<SetupRow>();
            var sig = EnsureTableCached("ModuleSignature");
            if (sig != null && sig.Data.Columns.Contains("ModuleID"))
                foreach (DataRow r in sig.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    rows.Add(new SetupRow(Cv(r["ModuleID"]),
                        sig.Data.Columns.Contains("Language") ? Cv(r["Language"]) : "",
                        sig.Data.Columns.Contains("Version")  ? Cv(r["Version"])  : "") { Row = r });
                }
            if (MmList != null) MmList.ItemsSource = rows;
            if (MmCount != null)
                MmCount.Text = rows.Count == 0 ? "no modules recorded"
                             : rows.Count == 1 ? "1 module recorded"
                             : $"{rows.Count} modules recorded";

            bool open = _msiPath.Length > 0 && !_viewingTransform;
            foreach (UIElement? el in new UIElement?[] { MmBrowse, MmDirectory, MmFeature, MmMedia, MmLanguage, MmMerge })
                if (el != null) el.IsEnabled = open;
        }

        private void MmBrowse_Click(object sender, RoutedEventArgs e)
        {
            var dlg = new OpenFileDialog
            {
                Title = "Select a merge module",
                Filter = "Merge modules (*.msm)|*.msm|All files (*.*)|*.*",
                CheckFileExists = true
            };
            if (dlg.ShowDialog() == true && MmPath != null) MmPath.Text = dlg.FileName;
        }

        private void MmMerge_Click(object sender, RoutedEventArgs e)
        {
            if (_msiPath.Length == 0) return;
            if (_viewingTransform)
            { MstMessage("A transform view is read-only, so nothing can be merged into it.", "Merge Modules", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            string msm = MmPath?.Text?.Trim() ?? "";
            if (msm.Length == 0 || !File.Exists(msm))
            { MstMessage("Pick a merge module (.msm) first.", "Merge Modules", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            string feature = MmFeature?.SelectedItem as string ?? "";
            if (feature.Length == 0)
            { MstMessage("This package has no features, and a merge module's components have to join one.", "Merge Modules", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            string redirect = MmDirectory?.SelectedItem as string ?? "TARGETDIR";
            bool embedCab = MmMedia == null || MmMedia.SelectedIndex != 1;
            if (!short.TryParse((MmLanguage?.Text ?? "0").Trim(), out short lang)) lang = 0;

            // The merge rewrites the file on disk, so anything staged here would afterwards be
            // describing a package that no longer matches it. Save-first, not merge-and-hope.
            if (HasUnsavedEdits())
            { MstMessage("Save your pending edits first.\n\nMerging rewrites the package on disk directly, and the edits staged here would then no longer match the file.", "Merge Modules", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            var t = Type.GetTypeFromProgID("Msm.Merge2");
            if (t == null)
            {
                MstMessage("mergemod.dll is not registered on this machine. It ships with the "
                         + "Windows SDK and with Visual Studio, not with Windows itself.",
                    "Merge Modules", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            string tempCab = System.IO.Path.Combine(System.IO.Path.GetTempPath(),
                "swiftpack-merge-" + Guid.NewGuid().ToString("N") + ".cab");
            dynamic? merge = null;
            try
            {
                TxtStatus.Text = "Merging " + System.IO.Path.GetFileName(msm) + "...";

                // What the File and Media tables hold before the merge, so the module's rows can
                // be told apart afterwards and sequenced after everything already there.
                var before = new HashSet<string>(StringComparer.Ordinal);
                int maxSeq = 0, maxDisk = 0;
                ReadFileAndMediaState(before, ref maxSeq, ref maxDisk);

                merge = Activator.CreateInstance(t) ?? throw new InvalidOperationException("mergemod could not start");
                merge.OpenDatabase(_msiPath);
                merge.OpenModule(msm, lang);
                // Redirecting to TARGETDIR is the same as not redirecting, and an empty string is
                // the way mergemod spells "leave it".
                merge.Merge(feature, string.Equals(redirect, "TARGETDIR", StringComparison.OrdinalIgnoreCase) ? "" : redirect);
                int conflicts = 0;
                try { foreach (object _ in merge.Errors) conflicts++; } catch { }
                try { merge.ExtractCAB(tempCab); } catch { /* a module with no files has no cabinet */ }
                merge.CloseModule();
                merge.CloseDatabase(true);
                Release(merge); merge = null;

                // The module's files arrived with the module's own sequence numbers, which say
                // nothing about this package. They are renumbered to follow everything already
                // here, and their cabinet becomes a new Media entry - without this the files are
                // rows the installer can never find bytes for.
                int added = SequenceMergedFiles(before, maxSeq, maxDisk, embedCab, tempCab);

                string what = System.IO.Path.GetFileNameWithoutExtension(msm);
                TxtStatus.Text = $"Merged {what}: {added} file(s) into feature {feature}, directory {redirect}."
                    + (conflicts > 0 ? $"  {conflicts} merge conflict(s) were recorded." : "");

                OpenMsiAt(_msiPath);
                ShowMergeModulesForm();
            }
            catch (Exception ex)
            {
                MstMessage("The merge failed.\n\n" + ex.Message
                         + "\n\nThe package may have been left unchanged; if in doubt, keep a copy "
                         + "before merging.",
                    "Merge Modules", MessageBoxButton.OK, MessageBoxImage.Error);
            }
            finally
            {
                if (merge != null) { try { merge.CloseDatabase(false); } catch { } Release(merge); }
                try { if (File.Exists(tempCab)) File.Delete(tempCab); } catch { }
            }
        }

        /// <summary>File keys, highest sequence and highest disk id as the package stands on disk.</summary>
        private void ReadFileAndMediaState(HashSet<string> fileKeys, ref int maxSeq, ref int maxDisk)
        {
            dynamic? inst = null, db = null, view = null, rec = null;
            try
            {
                inst = NewInstaller();
                db = inst.OpenDatabase(_msiPath, 0);
                try
                {
                    view = db.OpenView("SELECT `File`,`Sequence` FROM `File`");
                    view.Execute();
                    while ((rec = view.Fetch()) != null)
                    {
                        fileKeys.Add((string)rec.StringData(1));
                        if (int.TryParse((string)rec.StringData(2), out int sq) && sq > maxSeq) maxSeq = sq;
                        Release(rec); rec = null;
                    }
                    view.Close(); Release(view); view = null;
                }
                catch { }
                try
                {
                    view = db.OpenView("SELECT `DiskId`,`LastSequence` FROM `Media`");
                    view.Execute();
                    while ((rec = view.Fetch()) != null)
                    {
                        if (int.TryParse((string)rec.StringData(1), out int dk) && dk > maxDisk) maxDisk = dk;
                        if (int.TryParse((string)rec.StringData(2), out int ls) && ls > maxSeq) maxSeq = ls;
                        Release(rec); rec = null;
                    }
                    view.Close(); Release(view); view = null;
                }
                catch { }
            }
            finally
            {
                try { view?.Close(); } catch { }
                Release(rec); Release(view); Release(db); Release(inst);
            }
        }

        /// <summary>
        /// Renumbers the files the merge brought in to follow the package's existing sequences,
        /// adds the Media row that covers them, and puts their cabinet where that row says it is -
        /// embedded as a stream, or on disk beside the package. Returns how many files arrived.
        /// </summary>
        private int SequenceMergedFiles(HashSet<string> before, int maxSeq, int maxDisk,
            bool embedCab, string tempCab)
        {
            dynamic? inst = null, db = null, view = null, rec = null;
            try
            {
                inst = NewInstaller();
                db = inst.OpenDatabase(_msiPath, 1 /* transact */);

                var merged = new List<(string Key, int OldSeq)>();
                view = db.OpenView("SELECT `File`,`Sequence` FROM `File`");
                view.Execute();
                while ((rec = view.Fetch()) != null)
                {
                    string k = (string)rec.StringData(1);
                    if (!before.Contains(k))
                        merged.Add((k, int.TryParse((string)rec.StringData(2), out int sq) ? sq : 0));
                    Release(rec); rec = null;
                }
                view.Close(); Release(view); view = null;

                if (merged.Count == 0) { db.Commit(); return 0; }

                // Relative order is kept: a cabinet's files must appear in ascending sequence, and
                // the extracted cabinet is written in the module's own order.
                merged.Sort((a, b) => a.OldSeq.CompareTo(b.OldSeq));
                int seq = maxSeq;
                foreach (var (key, _) in merged)
                {
                    seq++;
                    view = db.OpenView($"UPDATE `File` SET `Sequence` = {seq} WHERE `File` = '{Esc(key)}'");
                    view.Execute();
                    view.Close(); Release(view); view = null;
                }

                string cabName = "mergecab" + (maxDisk + 1) + ".cab";
                string cabRef = embedCab ? "#" + cabName : cabName;
                view = db.OpenView("INSERT INTO `Media` (`DiskId`, `LastSequence`, `Cabinet`) "
                                 + $"VALUES ({maxDisk + 1}, {seq}, '{Esc(cabRef)}')");
                view.Execute();
                view.Close(); Release(view); view = null;

                if (embedCab)
                {
                    if (!File.Exists(tempCab))
                        throw new FileNotFoundException("The module's cabinet could not be extracted, "
                            + "so its files would have no bytes behind them.");
                    rec = inst.CreateRecord(1);
                    rec.SetStream(1, tempCab);
                    view = db.OpenView("INSERT INTO `_Streams` (`Name`, `Data`) VALUES ('" + Esc(cabName) + "', ?)");
                    view.Execute(rec);
                    view.Close(); Release(view); view = null;
                    Release(rec); rec = null;
                }
                else
                {
                    string dest = System.IO.Path.Combine(
                        System.IO.Path.GetDirectoryName(_msiPath) ?? "", cabName);
                    File.Copy(tempCab, dest, overwrite: true);
                }

                db.Commit();
                return merged.Count;
            }
            finally
            {
                try { view?.Close(); } catch { }
                Release(rec); Release(view); Release(db); Release(inst);
            }
        }

        /// <summary>
        /// Enables/disables all editing affordances. While locked (during table
        /// preload) the grid is read-only and the action buttons are disabled, so
        /// no change can be made against a half-loaded database.
        /// </summary>
        private void SetEditingLocked(bool locked)
        {
            // Transform view is now editable too — edits stack on top of the applied
            // transform (Create MST then produces a second-layer .mst; Save writes
            // the combined MSI).
            bool editable = !locked;
            _editingUnlocked = editable;
            GridRows.IsReadOnly    = locked;
            BtnAddRow.IsEnabled    = editable && !_formMode && !string.IsNullOrWhiteSpace(_currentTable);
            BtnDeleteRow.IsEnabled = editable && !_formMode && !string.IsNullOrWhiteSpace(_currentTable);
            UpdateRowButtonState();
            BtnRemoveDesktop.IsEnabled = editable;
            BtnApplyProps.IsEnabled = editable;
            BtnCreateMst.IsEnabled = editable;
            BtnSaveMsi.IsEnabled   = editable;
            // Apply MST is allowed only once loading is done.
            BtnViewMst.IsEnabled   = !locked;
            // Validate is available whenever an MSI is loaded (including transform view).
            BtnValidate.IsEnabled  = !locked;
            if (BtnViewChanges != null) BtnViewChanges.IsEnabled = !locked;
            // Export is available whenever an MSI is loaded.
            BtnExportPanel.IsEnabled = !locked;
            // Categories only mean something once a package is open, so on a freshly started
            // app the list is greyed out rather than inviting clicks that show nothing. The
            // items are disabled rather than the ListBox: a disabled ListBox paints its own
            // chrome with a light system brush, which is the white block that showed up under
            // the items in dark mode.
            bool canPick = editable && _msiPath.Length > 0;
            if (LstCategories != null)
                foreach (var obj in LstCategories.Items)
                    if (obj is ListBoxItem li) li.IsEnabled = canPick;
        }

        /// <summary>Called once the MSI is open and ready; unlocks editing.</summary>
        private void OnMsiReady(int gen, int tableCount)
        {
            if (gen != _preloadGeneration) return;     // a newer Browse superseded this
            _preloadComplete = true;
            SetEditingLocked(false);
            TxtStatus.Text = $"{tableCount} table(s). Select a table to view its rows, " +
                             "stage property changes below, then click Create MST.";
        }

        // ── The standard Windows Installer schema ──────────────────────────
        // _Tables lists only what the package actually has, which for a lean package is a small
        // fraction of the schema. Tools like InstallShield's Direct Editor list the whole schema
        // instead, so a table the package does not use yet is still visible and can be filled in.
        // SwiftPack does both: the package's own tables read normally, the rest of the schema is
        // faded, and selecting a faded one gives an empty grid with that table's real columns.
        //
        // Each entry is "column type" pairs separated by |, where the type is the same token the
        // MSI itself reports: s string, l localizable string, i integer, v binary stream; the case
        // of the letter is the nullability (upper = nullable) and the number is the length, 0
        // meaning unbounded. A trailing * marks a primary key column, and >Table.Column names the
        // foreign key a column points at, which is what fills its dropdown in the grid. Columns
        // that can point into several tables carry no target: there is no one list to offer.
        // Taken from the WiX toolset's table definitions rather than typed out by hand, so the
        // lengths, nullability, keys and references match what Windows Installer expects.
        private static readonly Dictionary<string, string> MsiTableSchemas =
            new(StringComparer.OrdinalIgnoreCase)
        {
