        // The tables the open package really has. The Tables list shows more than these, so
        // anything that has to read a table (search, validation) works from this instead.
        private List<string> _msiTableNames = new();

        /// <summary>
        /// The package's tables plus the rest of the standard schema, sorted together. They are
        /// all listed the same way, because they all behave the same way now: selecting one the
        /// package does not have gives an empty grid with that table's real columns. Which are
        /// which is in the header count and in the status bar on selection.
        /// </summary>
        private List<string> BuildTableListing(List<string> present)
        {
            _msiTableNames = present;
            var have = new HashSet<string>(present, StringComparer.OrdinalIgnoreCase);

            var all = new List<string>(present);
            foreach (string t in MsiTableSchemas.Keys)
                if (!have.Contains(t)) all.Add(t);
            all.Sort(StringComparer.OrdinalIgnoreCase);
            return all;
        }

        /// <summary>One column of a schema entry: its name, its MSI type token, whether it is part
        /// of the primary key, and the Table.Column it references (empty when it references
        /// nothing, or when it could reference several tables).</summary>
        private static List<(string Name, string Type, bool Key, string Ref)> ParseTableSchema(string schema)
        {
            var cols = new List<(string, string, bool, string)>();
            foreach (string part in schema.Split('|'))
            {
                int sp = part.IndexOf(' ');
                if (sp <= 0) continue;
                string name = part.Substring(0, sp);
                string type = part.Substring(sp + 1).Trim();

                string fk = "";
                int gt = type.IndexOf('>');
                if (gt >= 0) { fk = type.Substring(gt + 1); type = type.Substring(0, gt); }

                bool key = type.EndsWith("*", StringComparison.Ordinal);
                if (key) type = type.Substring(0, type.Length - 1);
                if (name.Length > 0 && type.Length > 1) cols.Add((name, type, key, fk));
            }
            return cols;
        }

        /// <summary>The table and column a column points at, or false when it points at nothing.
        /// Read from the schema, so it works for tables the package does not have yet as well as
        /// the ones it does.</summary>
        private static bool TryGetColumnReference(string table, string column,
            out string refTable, out string refColumn)
        {
            refTable = refColumn = "";
            if (!MsiTableSchemas.TryGetValue(table, out string? schema)) return false;
            foreach (var (name, _, _, fk) in ParseTableSchema(schema))
            {
                if (!string.Equals(name, column, StringComparison.OrdinalIgnoreCase)) continue;
                int dot = fk.IndexOf('.');
                if (dot <= 0) return false;
                refTable  = fk.Substring(0, dot);
                refColumn = fk.Substring(dot + 1);
                return refTable.Length > 0 && refColumn.Length > 0;
            }
            return false;
        }

        /// <summary>
        /// The values a foreign-key column can point at: everything live in the referenced column,
        /// plus anything this column already holds. The second half matters because a package can
        /// carry a reference to a row that is not there, and a dropdown that did not list it would
        /// render the cell blank and look like the value had been lost.
        /// </summary>
        private List<string> ForeignKeyChoices(string refTable, string refColumn, string ownColumn)
        {
            var seen = new HashSet<string>(StringComparer.Ordinal);
            var list = new List<string>();

            void Collect(TableState? source, string col)
            {
                if (source == null || !source.Data.Columns.Contains(col)) return;
                foreach (DataRow r in source.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string v = Cv(r[col]);
                    if (v.Length > 0 && seen.Add(v)) list.Add(v);
                }
            }

            Collect(EnsureTableCached(refTable), refColumn);
            if (_currentTable.Length > 0 && _tables.TryGetValue(_currentTable, out var own))
                Collect(own, ownColumn);

            list.Sort(StringComparer.OrdinalIgnoreCase);
            return list;
        }

        /// <summary>
        /// The CREATE TABLE that brings a standard table into a package that does not have it.
        /// Windows Installer's SQL wants the qualifiers in the order type, NOT NULL, LOCALIZABLE,
        /// the primary key columns declared first (which every standard table already does), and
        /// no explicit size above 255 - an unbounded string is LONGCHAR instead.
        /// </summary>
        private static string BuildCreateTableSql(string table,
            List<(string Name, string Type, bool Key, string Ref)> cols)
        {
            var defs = new List<string>();
            foreach (var (name, type, _, _) in cols)
            {
                char letter = type[0];
                char kind   = char.ToLowerInvariant(letter);
                int.TryParse(type.Substring(1), out int len);

                string sql = kind == 'i' ? (len == 2 ? "SHORT" : "LONG")
                           : kind == 'v' ? "OBJECT"
                           : (len <= 0 || len > 255 ? "LONGCHAR" : $"CHAR({len})");
                if (!char.IsUpper(letter)) sql += " NOT NULL";
                if (kind == 'l') sql += " LOCALIZABLE";
                defs.Add($"`{name}` {sql}");
            }
            string keys = string.Join(", ", cols.Where(c => c.Key).Select(c => $"`{c.Name}`"));
            return $"CREATE TABLE `{table}` ({string.Join(", ", defs)}  PRIMARY KEY {keys})";
        }

        /// <summary>
        /// An empty, editable table with the standard schema's real columns, staged so that adding
        /// a row to it creates the table in the package at Save or Create MST time. Null when the
        /// name is not one SwiftPack has a schema for.
        /// </summary>
        private TableState? CreateEmptyStandardTable(string name)
        {
            if (_msiPath.Length == 0) return null;
            if (!MsiTableSchemas.TryGetValue(name, out string? schema)) return null;

            var cols = ParseTableSchema(schema);
            if (cols.Count == 0 || !cols.Any(c => c.Key)) return null;

            var st = new TableState { CreateSql = BuildCreateTableSql(name, cols) };
            foreach (var (col, type, key, _) in cols)
            {
                st.Data.Columns.Add(col, typeof(string));
                char kind = char.ToLowerInvariant(type[0]);
                st.ColKind[col] = kind == 'i' ? 'i' : kind == 'v' ? 'v' : 's';
                st.ColType[col] = type;
                if (key) st.KeyCols.Add(col);
                if (char.IsUpper(type[0])) st.NullableCols.Add(col);
            }
            st.Data.AcceptChanges();
            _tables[name] = st;
            return st;
        }

        /// <summary>The cached table, falling back to an empty one built from the standard schema
        /// when the package does not have it.</summary>
        private TableState? EnsureTableOrCreate(string name)
            => EnsureTableCached(name) ?? CreateEmptyStandardTable(name);

        /// <summary>Sets the Tables header. The header itself stays a plain "Tables" label; the
        /// counts (how much of the schema this package uses) are surfaced only in the tooltip.</summary>
        private void UpdateTablesHeader()
        {
            if (TxtTablesHeader == null) return;
            int shown = LstTables?.Items.Count ?? 0;
            int have  = _msiTableNames.Count;
            TxtTablesHeader.Text = "Tables";
            if (shown == 0) { TxtTablesHeader.ToolTip = null; return; }
            TxtTablesHeader.ToolTip = have == shown
                ? $"{shown} table(s) in this package."
                : $"{have} table(s) in this package, out of {shown} listed. The faded names are "
                + "standard Windows Installer tables the package does not use.";
        }

        private static List<string> ReadTableNames(string msi)
        {
            dynamic? inst = null, db = null, view = null;
            var names = new List<string>();
            try
            {
                inst = NewInstaller();
                db   = inst.OpenDatabase(msi, 0 /* msiOpenDatabaseModeReadOnly */);
                view = db.OpenView("SELECT `Name` FROM `_Tables`");
                view.Execute();
                while (true)
                {
                    dynamic? rec = view.Fetch();
                    if (rec == null) break;
                    names.Add((string)rec.StringData(1));
                    Release(rec);
                }
                names.Sort(StringComparer.OrdinalIgnoreCase);
                return names;
            }
            finally
            {
                try { view?.Close(); } catch { }
                Release(view); Release(db); Release(inst);
            }
        }

        // ── Table viewer ─────────────────────────────────────────────────
        private bool _suppressTableValidation = false;

        private void LstTables_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            // Before leaving a table, make sure it has no incomplete added row.
            if (!_suppressTableValidation && !_viewingTransform &&
                e.RemovedItems.Count > 0 && e.RemovedItems[0] is string leaving &&
                _tables.TryGetValue(leaving, out var leftSt) &&
                HasIncompleteAddedRow(leftSt, out _))
            {
                // Re-select the table being left, prompt, and abort the switch.
                _suppressTableValidation = true;
                LstTables.SelectedItem = leaving;
                _suppressTableValidation = false;
                _currentTable = leaving;
                PromptIncompleteRow(leftSt);
                return;
            }

            string? table = LstTables.SelectedItem as string;
            if (string.IsNullOrWhiteSpace(table) || string.IsNullOrWhiteSpace(_msiPath)) return;
            _currentTable = table;

            // In transform view, compute this table's diff on first view (cached).
            if (_viewingTransform) EnsureDiffForTable(table);

            if (!_tables.TryGetValue(table, out var st))
            {
                st = LoadTable(table);
                if (st == null)
                {
                    // One of the faded entries: a standard table this package does not have. Give
                    // it an empty grid carrying that table's real columns so rows can be added
                    // straight away; the table itself is created in the package at Save or Create
                    // MST time, and only if rows were actually added to it.
                    st = CreateEmptyStandardTable(table);
                    if (st == null)
                    {
                        GridRows.ItemsSource = null;
                        TxtStatus.Text = $"{table} is not in this package, and SwiftPack does not "
                                       + "have its column layout, so there is nothing to edit.";
                        DeferRefreshVisuals();
                        return;
                    }
                    GridRows.ItemsSource = st.Data.DefaultView;
                    // Gated on the editing lock rather than the preload flag: a table built from
                    // the schema has no rows in the package to preload, so waiting on that left
                    // Add Row greyed out on exactly the tables that need it most.
                    BtnAddRow.IsEnabled = BtnDeleteRow.IsEnabled = _editingUnlocked && !_formMode;
                    UpdateRowButtonState();
                    TxtStatus.Text = $"{table}: not in this package yet. Fill in the blank row at "
                                   + "the bottom, and the table is created when you Save or Create MST.";
                    DeferRefreshVisuals();
                    UpdateEditCount();
                    return;
                }
                _tables[table] = st;
            }
            GridRows.ItemsSource = st.Data.DefaultView;
            // Enable row editing once tables are loaded (transform view is editable too).
            if (_preloadComplete)
                BtnAddRow.IsEnabled = BtnDeleteRow.IsEnabled = true;
            UpdateRowButtonState();
            if (_viewingTransform)
            {
                int n = _diffKeys.TryGetValue(table, out var ks) ? ks.Count : 0;
                TxtStatus.Text = n > 0
                    ? $"{table}: {st.RowCount} row(s) - {n} changed by the transform (highlighted in yellow)."
                    : $"{table}: {st.RowCount} row(s). No changes from the transform in this table.";
            }
            else if (!_preloadComplete)
            {
                TxtStatus.Text = $"{table}: {st.RowCount} row(s). Loading remaining tables… editing enabled once complete.";
            }
            else
            {
                TxtStatus.Text = $"{table}: {st.RowCount} row(s){(st.RowCount >= 5000 ? " (first 5000)" : "")}. Edit cells directly; changes go into the MST.";
            }
            DeferRefreshVisuals();
            UpdateEditCount();
        }

        private TableState? LoadTable(string table) => BuildTableState(_msiPath, table);

        // Reading a table through the Windows Installer COM automation layer makes
        // one late-bound IDispatch call per cell. A 4000-row File table is tens of
        // thousands of such calls and stalls the UI for several seconds on first view.
        // Try the flat msi.dll C API first (a plain vtable call per cell, loads the
        // same table in well under a second) and fall back to automation only if the
        // native path cannot read the table.
        private static TableState? BuildTableState(string msiPath, string table)
            => BuildTableStateNative(msiPath, table) ?? BuildTableStateCom(msiPath, table);

        // Direct msi.dll (flat C API) bindings used by the fast table loader.
        private static class MsiApi
        {
            [DllImport("msi.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
            public static extern uint MsiOpenDatabaseW(string szDatabasePath, IntPtr szPersist, out uint phDatabase);

            [DllImport("msi.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
            public static extern uint MsiDatabaseOpenViewW(uint hDatabase, string szQuery, out uint phView);

            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiViewExecute(uint hView, uint hRecord);

            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiViewFetch(uint hView, out uint phRecord);

            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiViewGetColumnInfo(uint hView, int eColumnInfo, out uint phRecord);

            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiViewClose(uint hView);

            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiRecordGetFieldCount(uint hRecord);

            [DllImport("msi.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
            public static extern uint MsiRecordGetStringW(uint hRecord, uint iField,
                System.Text.StringBuilder? szValueBuf, ref uint pcchValueBuf);

            [DllImport("msi.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
            public static extern uint MsiDatabaseGetPrimaryKeysW(uint hDatabase, string szTableName, out uint phRecord);

            // Stream columns. MsiRecordReadStream takes a byte buffer rather than a string, so it
            // has no W variant; MsiRecordDataSize is what says how big to make that buffer.
            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiRecordReadStream(uint hRecord, uint iField,
                byte[]? szDataBuf, ref uint pcbDataBuf);

            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiRecordDataSize(uint hRecord, uint iField);

            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiCloseHandle(uint hAny);

            [DllImport("msi.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
            public static extern uint MsiGetSummaryInformationW(uint hDatabase, string? szDatabasePath,
                uint uiUpdateCount, out uint phSummaryInfo);

            [DllImport("msi.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
            public static extern uint MsiSummaryInfoGetPropertyW(uint hSummaryInfo, uint uiProperty,
                out uint puiDataType, out int piValue, ref long pftValue,
                System.Text.StringBuilder? szValueBuf, ref uint pcchValueBuf);

            [DllImport("msi.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
            public static extern uint MsiSummaryInfoSetPropertyW(uint hSummaryInfo, uint uiProperty,
                uint uiDataType, int iValue, ref long pftValue, string? szValue);

            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiSummaryInfoPersist(uint hSummaryInfo);

            [DllImport("msi.dll", ExactSpelling = true)]
            public static extern uint MsiDatabaseCommit(uint hDatabase);

            public const uint ERROR_SUCCESS   = 0;
            public const uint ERROR_MORE_DATA = 234;
            public const int  MSICOLINFO_NAMES = 0;
            public const int  MSICOLINFO_TYPES = 1;

            // Summary Information property IDs.
            public const uint PID_CODEPAGE = 1;
            public const uint PID_TITLE    = 2;
            public const uint PID_SUBJECT  = 3;
            public const uint PID_AUTHOR   = 4;
            public const uint PID_KEYWORDS = 5;
            public const uint PID_COMMENTS = 6;
            // Template is "platform;langid", both halves in one string. Revision Number is the
            // package code, the GUID that identifies this exact build of the package.
            public const uint PID_TEMPLATE   = 7;
            public const uint PID_REVNUMBER  = 9;
            // Schema is the Page Count property: the lowest Windows Installer version the
            // package needs (200 = 2.0, 500 = 5.0).
            public const uint PID_PAGECOUNT = 14;
            // The Word Count property packs the source image flags. Bit 3 is the UAC one:
            // set means the package installs without elevated privileges.
            public const uint PID_WORDCOUNT = 15;
            public const int  SUMINFO_NO_ELEVATE = 8;
            // Property value data types returned by MsiSummaryInfoGetProperty.
            public const uint VT_I2    = 2;
            public const uint VT_I4    = 3;
            public const uint VT_LPSTR = 30;
        }

        // Read one record field as a string. Starts with a 256-char buffer (covers
        // the vast majority of MSI fields in a single call) and grows only when the
        // value is longer. A null field comes back as an empty string, matching the
        // automation layer's StringData behaviour.
        private static string MsiGetString(uint hRec, uint field)
        {
            uint cch = 256;
            var sb = new System.Text.StringBuilder((int)cch);
            uint rc = MsiApi.MsiRecordGetStringW(hRec, field, sb, ref cch);
            if (rc == MsiApi.ERROR_MORE_DATA)
            {
                cch++;                       // room for the terminating null
                sb.EnsureCapacity((int)cch);
                sb.Length = 0;
                rc = MsiApi.MsiRecordGetStringW(hRec, field, sb, ref cch);
            }
            return rc == MsiApi.ERROR_SUCCESS ? sb.ToString() : "";
        }

        // Fast table loader over the flat msi.dll API. Mirrors BuildTableStateCom
        // exactly (column kinds, primary keys, 5000-row safety cap, "(binary)"
        // placeholder for binary columns) so the result is a drop-in replacement.
        // Returns null on any failure so the caller can fall back to automation.
        private static TableState? BuildTableStateNative(string msiPath, string table)
        {
            uint hDb = 0, hView = 0, hNames = 0, hTypes = 0;
            try
            {
                if (MsiApi.MsiOpenDatabaseW(msiPath, IntPtr.Zero, out hDb) != MsiApi.ERROR_SUCCESS)
                    return null;
                if (MsiApi.MsiDatabaseOpenViewW(hDb, $"SELECT * FROM `{table}`", out hView) != MsiApi.ERROR_SUCCESS)
                    return null;
                if (MsiApi.MsiViewExecute(hView, 0) != MsiApi.ERROR_SUCCESS)
                    return null;

                var st = new TableState();

                // Column names + types (one record each).
                if (MsiApi.MsiViewGetColumnInfo(hView, MsiApi.MSICOLINFO_NAMES, out hNames) != MsiApi.ERROR_SUCCESS)
                    return null;
                if (MsiApi.MsiViewGetColumnInfo(hView, MsiApi.MSICOLINFO_TYPES, out hTypes) != MsiApi.ERROR_SUCCESS)
                    return null;

                int cols = (int)MsiApi.MsiRecordGetFieldCount(hNames);
                if (cols <= 0) return null;
                var kinds = new char[cols + 1];
                for (int i = 1; i <= cols; i++)
                {
                    string cname = MsiGetString(hNames, (uint)i);
                    string ctype = MsiGetString(hTypes, (uint)i);   // s72 / i2 / v0 / l255 …
                    char k = char.ToLowerInvariant(ctype.Length > 0 ? ctype[0] : 's');
                    // The case of the type letter is the nullability: S255 is nullable, s255 is
                    // required. Lowercasing it for ColKind threw that away, and a nullable key
                    // column then read as an unfinished row.
                    if (ctype.Length > 0 && char.IsUpper(ctype[0])) st.NullableCols.Add(cname);
                    kinds[i] = (k == 'i' || k == 'j') ? 'i' : (k == 'v' || k == 'o') ? 'v' : 's';
                    st.ColKind[cname] = kinds[i];
                    st.ColType[cname] = ctype;
                    st.Data.Columns.Add(cname, typeof(string));
                }

                // Primary key columns — needed for UPDATE/DELETE statements.
                if (MsiApi.MsiDatabaseGetPrimaryKeysW(hDb, table, out uint hKeys) == MsiApi.ERROR_SUCCESS && hKeys != 0)
                {
                    int kc = (int)MsiApi.MsiRecordGetFieldCount(hKeys);
                    for (int i = 1; i <= kc; i++) st.KeyCols.Add(MsiGetString(hKeys, (uint)i));
                    MsiApi.MsiCloseHandle(hKeys);
                }
                if (st.KeyCols.Count == 0 && st.Data.Columns.Count > 0)
                    st.KeyCols.Add(st.Data.Columns[0].ColumnName);

                int rows = 0;
                while (true)
                {
                    if (MsiApi.MsiViewFetch(hView, out uint hRec) != MsiApi.ERROR_SUCCESS || hRec == 0)
                        break;
                    var vals = new object[cols];
                    for (int i = 1; i <= cols; i++)
                        vals[i - 1] = kinds[i] == 'v' ? "(binary)" : MsiGetString(hRec, (uint)i);
                    st.Data.Rows.Add(vals);
                    MsiApi.MsiCloseHandle(hRec);
                    rows++;
                    if (rows >= 5000) break;   // safety cap for enormous File tables
                }
                st.Data.AcceptChanges();      // baseline — edits from here are tracked
                st.RowCount = rows;
                return st;
            }
            catch
            {
                return null;
            }
            finally
            {
                if (hNames != 0) MsiApi.MsiCloseHandle(hNames);
                if (hTypes != 0) MsiApi.MsiCloseHandle(hTypes);
                if (hView  != 0) { MsiApi.MsiViewClose(hView); MsiApi.MsiCloseHandle(hView); }
                if (hDb    != 0) MsiApi.MsiCloseHandle(hDb);
            }
        }

        private static TableState? BuildTableStateCom(string msiPath, string table)
        {
            dynamic? inst = null, db = null, view = null;
            try
            {
                inst = NewInstaller();
                db   = inst.OpenDatabase(msiPath, 0);
                view = db.OpenView($"SELECT * FROM `{table}`");
                view.Execute();

                var st = new TableState();
                dynamic namesRec = view.ColumnInfo[0];   // msiColumnInfoNames
                dynamic typesRec = view.ColumnInfo[1];   // msiColumnInfoTypes
                int cols = (int)namesRec.FieldCount;
                var kinds = new char[cols + 1];
                for (int i = 1; i <= cols; i++)
                {
                    string cname = (string)namesRec.StringData(i);
                    string ctype = (string)typesRec.StringData(i);   // s72 / i2 / v0 / l255 …
                    char k = char.ToLowerInvariant(ctype.Length > 0 ? ctype[0] : 's');
                    if (ctype.Length > 0 && char.IsUpper(ctype[0])) st.NullableCols.Add(cname);
                    kinds[i] = (k == 'i' || k == 'j') ? 'i' : (k == 'v' || k == 'o') ? 'v' : 's';
                    st.ColKind[cname] = kinds[i];
                    st.ColType[cname] = ctype;
                    st.Data.Columns.Add(cname, typeof(string));
                }
                Release(namesRec); Release(typesRec);

                // Primary key columns — needed for UPDATE/DELETE statements
                try
                {
                    dynamic keys = db.PrimaryKeys[table];
                    int kc = (int)keys.FieldCount;
                    for (int i = 1; i <= kc; i++) st.KeyCols.Add((string)keys.StringData(i));
                    Release(keys);
                }
                catch { }
                if (st.KeyCols.Count == 0 && st.Data.Columns.Count > 0)
                    st.KeyCols.Add(st.Data.Columns[0].ColumnName);

                int rows = 0;
                while (true)
                {
                    dynamic? rec = view.Fetch();
                    if (rec == null) break;
                    var vals = new object[cols];
                    for (int i = 1; i <= cols; i++)
                        vals[i - 1] = kinds[i] == 'v' ? "(binary)" : (string)rec.StringData(i);
                    st.Data.Rows.Add(vals);
                    rows++; Release(rec);
                    if (rows >= 5000) break;   // safety cap for enormous File tables
                }
                st.Data.AcceptChanges();      // baseline — edits from here are tracked
                st.RowCount = rows;
                return st;
            }
            catch
            {
                return null;
            }
            finally
            {
                try { view?.Close(); } catch { }
                Release(view); Release(db); Release(inst);
            }
        }

        private void GridRows_AutoGeneratingColumn(object sender, DataGridAutoGeneratingColumnEventArgs e)
        {
            if (!_tables.TryGetValue(_currentTable, out var st)) return;

            // Binary columns cannot be edited through the grid
            if (st.ColKind.TryGetValue(e.PropertyName, out char k) && k == 'v')
                e.Column.IsReadOnly = true;

            // A column that points at another table gets a dropdown of what it can point at, rather
            // than leaving the user to remember component keys and type them exactly. Built as a
            // template column with an editable ComboBox instead of a DataGridComboBoxColumn: that
            // one binds the selected item, so anything typed by hand that is not already in the
            // list is discarded, and referring to a row being added in the same session is
            // legitimate.
            bool hasRef = TryGetColumnReference(_currentTable, e.PropertyName, out string refTable, out string refCol);
            if (hasRef)
            {
                var choices = ForeignKeyChoices(refTable, refCol, e.PropertyName);
                if (choices.Count > 0)
                {
                    var display = new FrameworkElementFactory(typeof(TextBlock));
                    display.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding(e.PropertyName));
                    display.SetValue(FrameworkElement.MarginProperty, new Thickness(6, 0, 6, 0));
                    display.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center);

                    var editor = new FrameworkElementFactory(typeof(ComboBox));
                    editor.SetValue(ComboBox.IsEditableProperty, true);
                    editor.SetValue(ComboBox.IsTextSearchEnabledProperty, true);
                    editor.SetValue(ItemsControl.ItemsSourceProperty, choices);
                    editor.SetValue(FrameworkElement.MarginProperty, new Thickness(0));
                    // PropertyChanged rather than LostFocus: the grid can commit the cell while the
                    // ComboBox still has focus, and a LostFocus binding would not have written yet.
                    editor.SetBinding(ComboBox.TextProperty, new System.Windows.Data.Binding(e.PropertyName)
                    {
                        Mode = System.Windows.Data.BindingMode.TwoWay,
                        UpdateSourceTrigger = System.Windows.Data.UpdateSourceTrigger.PropertyChanged,
                    });

                    e.Column = new DataGridTemplateColumn
                    {
                        Header = e.PropertyName,
                        CellTemplate        = new DataTemplate { VisualTree = display },
                        CellEditingTemplate = new DataTemplate { VisualTree = editor },
                        SortMemberPath      = e.PropertyName,
                    };
                }
            }

            // What the column will actually take, as a tooltip rather than in the header text:
            // several handlers look a column up by its header, so renaming it would break them.
            if (st.ColType.TryGetValue(e.PropertyName, out string? type) && type.Length > 1)
            {
                string tip = $"{e.PropertyName}  ({type})";
                if (st.KeyCols.Contains(e.PropertyName, StringComparer.OrdinalIgnoreCase))
                    tip += "\nPart of the primary key.";
                tip += st.NullableCols.Contains(e.PropertyName) ? "\nOptional." : "\nRequired.";
                if (hasRef) tip += $"\nRefers to {refTable}.{refCol}.";

                var hs = new Style(typeof(System.Windows.Controls.Primitives.DataGridColumnHeader),
                                   GridRows.ColumnHeaderStyle);
                hs.Setters.Add(new Setter(FrameworkElement.ToolTipProperty, tip));
                e.Column.HeaderStyle = hs;
            }
        }

        /// <summary>
        /// After columns are generated, size each to its content (Auto) so nothing
        /// is clipped, then fit the last column: if the columns do not fill the grid
        /// width, the last one is stretched to absorb the leftover space so there is
        /// no empty filler "column" on the right (e.g. InstallExecuteSequence). Wide
        /// tables whose columns already fill or overflow the grid (e.g. File) are left
        /// content-sized so nothing is squeezed and horizontal scrolling works.
        /// </summary>
        private void GridRows_AutoGeneratedColumns(object? sender, EventArgs e)
        {
            int count = GridRows.Columns.Count;
            if (count == 0) return;
            for (int i = 0; i < count; i++)
            {
                GridRows.Columns[i].MinWidth = 44;   // never collapse to an unreadable sliver
                GridRows.Columns[i].Width = new DataGridLength(1, DataGridLengthUnitType.Auto);
            }
            ScheduleFitLastColumn();
        }

        private bool _fitScheduled;

        // Coalesces repeated fit requests (column generation + resize storms) into a
        // single deferred pass so the layout has settled before we measure.
        private void ScheduleFitLastColumn()
        {
            if (_fitScheduled) return;
            _fitScheduled = true;
            Dispatcher.BeginInvoke(new Action(() =>
            {
                _fitScheduled = false;
                FitLastColumn();
            }), System.Windows.Threading.DispatcherPriority.Loaded);
        }

        private void FitLastColumn()
        {
            int count = GridRows.Columns.Count;
            if (count == 0 || GridRows.ActualWidth <= 0) return;

            var last = GridRows.Columns[count - 1];

            // Reset the last column to its content width first so a previously
            // stretched width does not skew the measurement (avoids oscillation).
            last.Width = new DataGridLength(1, DataGridLengthUnitType.Auto);
            GridRows.UpdateLayout();

            double used = 0;
            for (int i = 0; i < count; i++) used += GridRows.Columns[i].ActualWidth;

            double avail = GridRows.ActualWidth;
            var sv = FindDescendantScrollViewer(GridRows);
            if (sv != null && sv.ComputedVerticalScrollBarVisibility == Visibility.Visible)
                avail -= SystemParameters.VerticalScrollBarWidth;

            // Only stretch when there is comfortable room left, so the last column is
            // never squeezed below its content; otherwise leave it content-sized.
            if (used + 32 < avail)
                last.Width = new DataGridLength(1, DataGridLengthUnitType.Star);
        }

        private void GridRows_CellEditEnding(object? sender, DataGridCellEditEndingEventArgs e)
        {
            if (e.EditAction == DataGridEditAction.Commit &&
                _tables.TryGetValue(_currentTable, out var st) &&
                e.Column?.Header is string col &&
                st.ColKind.TryGetValue(col, out char k) && k == 'i' &&
                e.EditingElement is TextBox tb)
            {
                string v = tb.Text.Trim();
                if (v.Length > 0 && !long.TryParse(v, out _))
                {
                    e.Cancel = true;
                    MstMessage($"\u201C{col}\u201D is an integer column - \u201C{v}\u201D is not a number.",
                        "Create MST", MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
            }
            DeferRefreshVisuals();
        }

        private static readonly System.Windows.Media.Brush AmberBrush =
            new System.Windows.Media.SolidColorBrush(
                System.Windows.Media.Color.FromArgb(60, 255, 196, 0));

        // Green tint for rows added by the staged edits (editable MSI).
        private static readonly System.Windows.Media.Brush AddBrush =
            new System.Windows.Media.SolidColorBrush(
                System.Windows.Media.Color.FromArgb(55, 67, 160, 71));

        // Yellow tint for rows changed by an applied transform (read-only view).
        private static readonly System.Windows.Media.Brush DiffBrush =
            new System.Windows.Media.SolidColorBrush(
                System.Windows.Media.Color.FromArgb(70, 255, 214, 10));

        // Red tint for rows the user marked for deletion (pending apply).
        private static readonly System.Windows.Media.Brush DeleteBrush =
            new System.Windows.Media.SolidColorBrush(
                System.Windows.Media.Color.FromArgb(55, 226, 75, 74));

        // Muted red foreground for the struck-through ghost text.
        private static readonly System.Windows.Media.Brush DeleteTextBrush =
            new System.Windows.Media.SolidColorBrush(
                System.Windows.Media.Color.FromArgb(200, 200, 60, 60));

        private void PaintRow(DataGridRow row)
        {
            if (row.Item is DataRowView drv)
            {
                // Marked-for-deletion ghost → red + strikethrough (takes precedence).
                if (_tables.TryGetValue(_currentTable, out var cst) && cst.MarkedDelete.Contains(drv.Row))
                {
                    row.Background = DeleteBrush;
                    row.Foreground = DeleteTextBrush;
                    row.SetValue(System.Windows.Controls.TextBlock.TextDecorationsProperty,
                                 System.Windows.TextDecorations.Strikethrough);
                    return;
                }
                // Not marked → clear any leftover strikethrough/foreground from a prior mark.
                row.ClearValue(DataGridRow.ForegroundProperty);
                row.ClearValue(System.Windows.Controls.TextBlock.TextDecorationsProperty);

                // Staged edits on an editable MSI: added → green, modified → amber.
                if (drv.Row.RowState == DataRowState.Added)
                { row.Background = AddBrush; return; }
                if (drv.Row.RowState == DataRowState.Modified)
                { row.Background = AmberBrush; return; }

                // Changed-by-transform row in read-only transformed view → yellow.
                if (_viewingTransform &&
                    _diffKeys.TryGetValue(_currentTable, out var keys) &&
                    _tables.TryGetValue(_currentTable, out var st) &&
                    keys.Contains(RowKeySignature(st, drv.Row)))
                { row.Background = DiffBrush; return; }
            }
            row.ClearValue(DataGridRow.BackgroundProperty);
        }

        /// <summary>Recolors all realized rows by RowState — safe during edit transactions.</summary>
        private void RefreshRowVisuals()
        {
            foreach (var item in GridRows.Items)
                if (GridRows.ItemContainerGenerator.ContainerFromItem(item) is DataGridRow row)
                    PaintRow(row);
            UpdateEditCount();
        }

        private void DeferRefreshVisuals() =>
            Dispatcher.BeginInvoke(new Action(RefreshRowVisuals),
                System.Windows.Threading.DispatcherPriority.Background);

        private void BtnAddRow_Click(object sender, RoutedEventArgs e)
        {
            if (!_tables.TryGetValue(_currentTable, out var st)) return;

            // Before adding another blank row, make sure any existing blank row
            // in this table has been completed (or removed) first.
            if (HasIncompleteAddedRow(st, out _))
            {
                PromptIncompleteRow(st);
                return;
            }

            var row = st.Data.NewRow();
            foreach (DataColumn c in st.Data.Columns) row[c] = "";
            st.Data.Rows.Add(row);
            GridRows.ScrollIntoView(st.Data.DefaultView[st.Data.DefaultView.Count - 1]);
            DeferRefreshVisuals();
        }

        /// <summary>
        /// A manually-added row counts as "incomplete" when any of its primary-key
        /// columns is still blank — such a row cannot be inserted into the MSI and
        /// is what produces "Execute,Params"-style errors during Create MST / Save.
        /// </summary>
        private static bool HasIncompleteAddedRow(TableState st, out DataRow? bad)
        {
            bad = null;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState != DataRowState.Added) continue;
                if (IsRowIncomplete(st, r)) { bad = r; return true; }
            }
            return false;
        }

        /// <summary>Asks the user to fill or delete an incomplete added row.</summary>
        private void PromptIncompleteRow(TableState st)
        {
            if (_promptingIncomplete) return;
            if (!HasIncompleteAddedRow(st, out var bad) || bad == null) return;

            _promptingIncomplete = true;
            try
            {
                string keyList = st.KeyCols.Count > 0 ? string.Join(", ", st.KeyCols) : "the required";
                var choice = MstMessage(
                    $"A newly added row in “{_currentTable}” is incomplete - {keyList} value(s) must be filled in.\n\n" +
                    "Click Yes to delete this empty row, or No to go back and fill it in.",
                    "Incomplete row", MessageBoxButton.YesNo, MessageBoxImage.Warning);

                if (choice == MessageBoxResult.Yes)
                {
                    bad.Delete();
                    DeferRefreshVisuals();
                }
                else
                {
                    // Put the cursor back on the offending row so the user can complete it.
                    var view = GridRows.ItemsSource as DataView;
                    if (view != null)
                    {
                        foreach (DataRowView drv in view)
                            if (ReferenceEquals(drv.Row, bad)) { GridRows.SelectedItem = drv; GridRows.ScrollIntoView(drv); break; }
                    }
                }
            }
            finally { _promptingIncomplete = false; }
        }

        /// <summary>
        /// Commits any in-progress cell edit and verifies the current table has no
        /// incomplete added rows. Returns false (and prompts) when one is found, so
        /// callers can stop before writing to the database.
        /// </summary>
        private bool CommitGridAndValidate()
        {
            try { GridRows.CommitEdit(DataGridEditingUnit.Cell, true); GridRows.CommitEdit(DataGridEditingUnit.Row, true); }
            catch { }

            foreach (var (name, st) in _tables.Select(kv => (kv.Key, kv.Value)))
            {
                if (HasIncompleteAddedRow(st, out _))
                {
                    // Switch to the offending table so the prompt's "fill it in"
                    // option lands the user on the right row.
                    if (!string.Equals(_currentTable, name, StringComparison.OrdinalIgnoreCase))
                    {
                        LstTables.SelectedItem = name;
                    }
                    PromptIncompleteRow(_tables.TryGetValue(_currentTable, out var cur) ? cur : st);
                    return false;
                }
            }
            return true;
        }

        private void BtnDeleteRow_Click(object sender, RoutedEventArgs e)
        {
            if (GridRows.SelectedItem is not DataRowView drv) return;
            if (!_tables.TryGetValue(_currentTable, out var st)) return;
            DataRow r = drv.Row;

            // A freshly added (unsaved) row that the user removes is a no-op — just
            // drop it outright rather than ghosting it.
            if (r.RowState == DataRowState.Added)
            {
                st.MarkedDelete.Remove(r);
                r.Delete();
            }
            else
            {
                // Toggle the deletion mark: the row stays live and visible as a
                // red, struck-through "ghost" until Create MST / Save applies it.
                if (!st.MarkedDelete.Add(r)) st.MarkedDelete.Remove(r);
            }
            DeferRefreshVisuals();
            UpdateEditCount();
        }

        // ── Copy Row / Paste Row (Tables view) ─────────────────────────────
        // Copy captures the selected row's cell values keyed by column name. Paste creates a new
        // row (same path as Add Row) and fills the matching columns, so it works within the source
        // table and any table that shares those column names. Paste never overwrites an existing
        // row - it always adds - and reuses the incomplete-row guard so a half-filled added row is
        // resolved first.
        private void BtnCopyRow_Click(object sender, RoutedEventArgs e)
        {
            if (GridRows.SelectedItem is not DataRowView drv) return;
            if (!_tables.TryGetValue(_currentTable, out var st)) return;

            var vals = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (DataColumn c in st.Data.Columns)
                vals[c.ColumnName] = (drv.Row[c] ?? "").ToString() ?? "";

            _copiedRowValues = vals;
            _copiedRowTable  = _currentTable;
            UpdateRowButtonState();
        }

        private void BtnPasteRow_Click(object sender, RoutedEventArgs e)
        {
            if (_copiedRowValues == null) return;
            if (!_tables.TryGetValue(_currentTable, out var st)) return;

            // Same guard Add Row uses: don't stack a second blank/incomplete added row.
            if (HasIncompleteAddedRow(st, out _))
            {
                PromptIncompleteRow(st);
                return;
            }

            var row = st.Data.NewRow();
            foreach (DataColumn c in st.Data.Columns)
                row[c] = _copiedRowValues.TryGetValue(c.ColumnName, out var v) ? v : "";
            st.Data.Rows.Add(row);

            // Select and reveal the pasted row so the user can adjust key values (a copy usually
            // needs a new primary key before it can be saved).
            var view = GridRows.ItemsSource as DataView;
            if (view != null)
                foreach (DataRowView d in view)
                    if (ReferenceEquals(d.Row, row)) { GridRows.SelectedItem = d; GridRows.ScrollIntoView(d); break; }

            DeferRefreshVisuals();
            UpdateEditCount();
        }

        // Keeps Copy/Paste enabled state in sync: Copy needs a selected row, Paste needs something
        // on the clipboard. Both also require an unlocked, non-form Tables view with a table open.
        private void UpdateRowButtonState()
        {
            bool baseOk = _editingUnlocked && !_formMode && !string.IsNullOrWhiteSpace(_currentTable);
            if (BtnCopyRow  != null) BtnCopyRow.IsEnabled  = baseOk && GridRows.SelectedItem is DataRowView;
            if (BtnPasteRow != null) BtnPasteRow.IsEnabled = baseOk && _copiedRowValues != null;
        }

        // Context menu on the rows grid: enable/disable items to mirror the toolbar buttons, then
        // route each item to the same handler the toolbar uses.
        private void GridRowsContextMenu_Opened(object sender, RoutedEventArgs e)
        {
            UpdateRowButtonState();
            bool baseOk = _editingUnlocked && !_formMode && !string.IsNullOrWhiteSpace(_currentTable);
            bool haveRow = GridRows.SelectedItem is DataRowView;
            if (CtxSearch        != null) CtxSearch.IsEnabled        = !_formMode;
            if (CtxSearchReplace != null) CtxSearchReplace.IsEnabled = !_formMode;
            if (CtxAddRow        != null) CtxAddRow.IsEnabled        = baseOk;
            if (CtxDeleteRow     != null) CtxDeleteRow.IsEnabled     = baseOk && haveRow;
            if (CtxCopyRow       != null) CtxCopyRow.IsEnabled       = baseOk && haveRow;
            if (CtxPasteRow      != null) CtxPasteRow.IsEnabled      = baseOk && _copiedRowValues != null;
        }

        private void CtxSearch_Click(object sender, RoutedEventArgs e)        => OpenFindReplaceDialog(false);
        private void CtxSearchReplace_Click(object sender, RoutedEventArgs e) => OpenFindReplaceDialog(true);

        private int PendingEditCount()
        {
            int n = 0;
            foreach (var st in _tables.Values)
                foreach (DataRow r in st.Data.Rows)
                    if (r.RowState != DataRowState.Unchanged || st.MarkedDelete.Contains(r)) n++;
            return n;
        }

        private void UpdateEditCount()
        {
            int n = PendingEditCount();
            TxtEditCount.Text = n == 0 ? "" : $"{n} pending row edit(s) across all tables";
            OnEditsChanged(n);
        }

        // Called whenever the staged-edit count may have changed. Surfaces the
        // Transform changes view automatically on the first edit and keeps it live.
        // Applies in both plain and transformed views (both are editable now).
        private void OnEditsChanged(int pendingCount)
        {
            if (TabTransform == null || TabValidation == null) return;   // during init

            if (pendingCount > 0)
            {
                bool firstChange = !_transformAutoShown;
                if (firstChange)
                {
                    _transformAutoShown = true;
                    if (_panelCollapsed) SetPanelCollapsed(false);
                    TabTransform.IsChecked = true;          // fires BottomView_Changed → refresh
                }
                else if (TabTransform.IsChecked == true)
                {
                    // Already on the Transform view — keep it live as edits continue.
                    RefreshTransformChanges();
                    int adds = _transformChanges.Count(c => c.Action == "Add");
                    int mods = _transformChanges.Count(c => c.Action == "Modify");
                    int dels = _transformChanges.Count(c => c.Action == "Delete");
                    TxtPanelSummary.Text = _transformChanges.Count == 0
                        ? "No changes."
                        : $"{_transformChanges.Count} change(s) · {adds} add · {mods} modify · {dels} delete";
                }
            }
            else
            {
                // No staged edits remain — allow auto-show to trigger again later.
                _transformAutoShown = false;
                if (TabTransform.IsChecked == true) RefreshTransformChanges();
            }
        }

        // True once we've auto-switched to the Transform view for the current
        // batch of edits, so we don't keep yanking focus on every keystroke.
        private bool _transformAutoShown = false;

        // ── Validation (Phase 3): built-in consistency checks ───────────
        //
        // When the package carries a _Validation table, these checks are driven by
        // the package's own declared rules (nullability, foreign keys, integer
        // ranges, enumerated sets, GUID/Language formats); otherwise they fall back
        // to a hardcoded reference set. They are NOT the full Microsoft ICE engine
        // (which would require running darice.cub), they validate the MSI with the
        // user's staged edits applied (in-memory), and they are informational only
        // (they never block Create MST / Save). Codes are labelled "<ICE>-like" /
        // "ICE-xxx" so they read familiarly without claiming to be the official engine.

        public sealed class ValidationIssue
        {
            public string Severity { get; set; } = "";   // "Error" / "Warning"
            public string Code     { get; set; } = "";
            public string Table    { get; set; } = "";
            public string RowKey   { get; set; } = "";
            public string Column   { get; set; } = "";
            public string Message  { get; set; } = "";
        }

        private readonly ObservableCollection<ValidationIssue> _validation = new();

        // Foreign-key map: (table, column) -> (referenced table, referenced key column).
        // Covers the common transform-relevant references. Comparisons are case-insensitive.
        private static readonly (string Table, string Col, string RefTable, string RefCol)[] _foreignKeys =
        {
            ("Component",        "Directory_",  "Directory", "Directory"),
            ("Directory",        "Directory_Parent", "Directory", "Directory"),
            ("File",             "Component_",  "Component", "Component"),
            ("Shortcut",         "Component_",  "Component", "Component"),
            ("Shortcut",         "Directory_",  "Directory", "Directory"),
            ("Registry",         "Component_",  "Component", "Component"),
            ("RemoveFile",       "Component_",  "Component", "Component"),
            ("RemoveRegistry",   "Component_",  "Component", "Component"),
            ("ServiceInstall",   "Component_",  "Component", "Component"),
            ("ServiceControl",   "Component_",  "Component", "Component"),
            ("Class",            "Component_",  "Component", "Component"),
            ("Extension",        "Component_",  "Component", "Component"),
            ("ProgId",           "Class_",      "Class",     "CLSID"),
            ("FeatureComponents","Feature_",    "Feature",   "Feature"),
            ("FeatureComponents","Component_",  "Component", "Component"),
            ("Feature",          "Feature_Parent","Feature", "Feature"),
            ("Condition",        "Feature_",    "Feature",   "Feature"),
            ("Icon",             "",            "",          ""),   // (placeholder, not used)
        };

        // Sequence tables whose Sequence numbers must be unique.
        private static readonly string[] _sequenceTables =
        {
            "InstallExecuteSequence", "InstallUISequence",
            "AdminExecuteSequence",   "AdminUISequence", "AdvtExecuteSequence",
        };

        private System.Threading.CancellationTokenSource? _validateCts;

        private void BtnValidate_Click(object sender, RoutedEventArgs e)
        {
            if (string.IsNullOrWhiteSpace(_msiPath)) return;

            // Bring the panel forward on the Validation view.
            ShowBottomPanel();
            if (TabValidation != null) TabValidation.IsChecked = true;

            // Commit any in-progress edit so the latest values are validated.
            try { GridRows.CommitEdit(DataGridEditingUnit.Cell, true); GridRows.CommitEdit(DataGridEditingUnit.Row, true); }
            catch { }

            // ── Phase 1 (UI thread): snapshot in-memory tables to plain data ──
            // This captures any unsaved grid edits and is a cheap memory copy.
            var edited = new Dictionary<string, TableSnapshot>(StringComparer.OrdinalIgnoreCase);
            foreach (var kv in _tables)
                edited[kv.Key] = SnapshotFromState(kv.Value);

            var available = _msiTableNames.Count > 0 ? new List<string>(_msiTableNames) : _tables.Keys.ToList();
            string msi = _msiPath;

            _validateCts?.Cancel();
            _validateCts?.Dispose();
            _validateCts = new System.Threading.CancellationTokenSource();
            var token = _validateCts.Token;

            SetValidatingState(true);
            System.Windows.Input.Mouse.OverrideCursor = System.Windows.Input.Cursors.Wait;
            TxtPanelSummary.Text = "Validating…";
            TxtStatus.Text = "Running validation… (you can Cancel)";

            // ── Phase 2 (background): read remaining tables + run checks ──
            System.Threading.Tasks.Task.Run(() =>
            {
                List<ValidationIssue> issues;
                bool cancelled = false;
                try { issues = RunValidationCore(msi, available, edited, token); }
                catch (OperationCanceledException)
                {
                    cancelled = true;
                    issues = new List<ValidationIssue>();
                }
                catch (Exception ex)
                {
                    issues = new List<ValidationIssue> { new ValidationIssue {
                        Severity = "Error", Code = "internal", Table = "", RowKey = "",
                        Column = "", Message = "Validation failed: " + ex.Message } };
                }

                // ── Phase 3 (UI thread): show results ──
                Dispatcher.BeginInvoke(new Action(() =>
                {
                    System.Windows.Input.Mouse.OverrideCursor = null;
                    SetValidatingState(false);

                    if (cancelled || token.IsCancellationRequested)
                    {
                        TxtPanelSummary.Text = "Validation cancelled.";
                        TxtStatus.Text = "Validation cancelled.";
                        return;
                    }

                    _validation.Clear();
                    foreach (var i in issues) _validation.Add(i);

                    TabValidation.IsChecked = true;   // bring the Validation view forward
                    int errors   = issues.Count(i => i.Severity == "Error");
                    int warnings = issues.Count(i => i.Severity == "Warning");
                    TxtPanelSummary.Text = issues.Count == 0
                        ? "No issues found."
                        : $"{errors} error(s), {warnings} warning(s).";
                    if (_panelCollapsed) SetPanelCollapsed(false);
                    TxtStatus.Text = issues.Count == 0
                        ? "Validation passed - no issues found by the built-in checks."
                        : $"Validation found {errors} error(s) and {warnings} warning(s). These are advisory and do not block Create MST / Save.";
                }));
            });
        }

        private void BtnCancelValidate_Click(object sender, RoutedEventArgs e)
        {
            _validateCts?.Cancel();
            BtnCancelValidate.IsEnabled = false;       // one click; result handler restores UI
            TxtStatus.Text = "Cancelling validation…";
        }

        /// <summary>
        /// Toggles the "validation running" UI: while busy, every action control is
        /// disabled and a Cancel button replaces Validate. When done, the normal
        /// enabled/disabled state is restored.
        /// </summary>
        private void SetValidatingState(bool busy)
        {
            AppBusy.SetManual("Edit MSI (validate)", busy);
            if (busy)
            {
                BtnOpenMsi.IsEnabled = BtnViewMst.IsEnabled = BtnSaveMsi.IsEnabled =
                    BtnCreateMst.IsEnabled = BtnAddRow.IsEnabled = BtnDeleteRow.IsEnabled =
                    BtnCopyRow.IsEnabled = BtnPasteRow.IsEnabled =
                    BtnRemoveDesktop.IsEnabled = BtnApplyProps.IsEnabled =
                    TxtSearch.IsEnabled = BtnSearchPrev.IsEnabled = BtnSearchNext.IsEnabled = false;
                LstTables.IsEnabled = GridRows.IsEnabled = false;
                BtnExportPanel.IsEnabled = false;
                if (BtnViewChanges != null) BtnViewChanges.IsEnabled = false;

                BtnValidate.Visibility       = Visibility.Collapsed;
                BtnCancelValidate.Visibility = Visibility.Visible;
                BtnCancelValidate.IsEnabled  = true;
            }
            else
            {
                // Restore normal enablement via the existing logic (transform view
                // is editable now, so the same path applies in both modes).
                LstTables.IsEnabled = GridRows.IsEnabled = true;
                BtnExportPanel.IsEnabled = !string.IsNullOrWhiteSpace(_msiPath);
                SetEditingLocked(!_preloadComplete);
                BtnOpenMsi.IsEnabled = true;
                UpdateSearchEnabled();

                BtnValidate.Visibility       = Visibility.Visible;
                BtnValidate.IsEnabled        = !string.IsNullOrWhiteSpace(_msiPath);
                if (BtnViewChanges != null) BtnViewChanges.IsEnabled = !string.IsNullOrWhiteSpace(_msiPath);
                BtnCancelValidate.Visibility = Visibility.Collapsed;
                BtnCancelValidate.IsEnabled  = false;
            }
        }

        /// <summary>Plain, thread-safe snapshot of a table for validation.</summary>
        private sealed class TableSnapshot
        {
            public List<string> Columns = new();
            public Dictionary<string, char> ColKind = new(StringComparer.OrdinalIgnoreCase);
            public Dictionary<string, int> ColMaxLen = new(StringComparer.OrdinalIgnoreCase);  // 0 = unknown/unbounded
            public List<string> KeyCols = new();
            public List<string[]> Rows = new();   // one string per column, in Columns order
            public bool Capped;                    // true if row-limited during read

            public int ColIndex(string name)
            {
                for (int i = 0; i < Columns.Count; i++)
                    if (string.Equals(Columns[i], name, StringComparison.OrdinalIgnoreCase)) return i;
                return -1;
            }
            public bool HasColumn(string name) => ColIndex(name) >= 0;
        }

        /// <summary>Copies a live TableState (with current values, dropping deleted rows) into a plain snapshot.</summary>
        private static TableSnapshot SnapshotFromState(TableState st)
        {
            var snap = new TableSnapshot { Capped = st.RowCount >= 5000 };
            foreach (DataColumn c in st.Data.Columns)
            {
                snap.Columns.Add(c.ColumnName);
                snap.ColKind[c.ColumnName] = st.ColKind.TryGetValue(c.ColumnName, out var k) ? k : 's';
            }
            snap.KeyCols = st.KeyCols.Count > 0
                ? new List<string>(st.KeyCols)
                : (snap.Columns.Count > 0 ? new List<string> { snap.Columns[0] } : new List<string>());
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (st.MarkedDelete.Contains(r)) continue;   // ghost = being removed
                var row = new string[snap.Columns.Count];
                for (int i = 0; i < snap.Columns.Count; i++) row[i] = (r[i] ?? "").ToString();
                snap.Rows.Add(row);
            }
            return snap;
        }

        /// <summary>Reads a table from the MSI file into a plain snapshot (background-safe).</summary>
        private static TableSnapshot? SnapshotFromFile(dynamic db, string table, System.Threading.CancellationToken token)
        {
            dynamic? view = null;
            try
            {
                view = db.OpenView($"SELECT * FROM `{table}`");
                view.Execute();
                var snap = new TableSnapshot();

                dynamic namesRec = view.ColumnInfo[0];
                dynamic typesRec = view.ColumnInfo[1];
                int cols = (int)namesRec.FieldCount;
                var kinds = new char[cols + 1];
                for (int i = 1; i <= cols; i++)
                {
                    string cname = (string)namesRec.StringData(i);
                    string ctype = (string)typesRec.StringData(i);
                    char k = char.ToLowerInvariant(ctype.Length > 0 ? ctype[0] : 's');
                    kinds[i] = (k == 'i' || k == 'j') ? 'i' : (k == 'v' || k == 'o') ? 'v' : 's';
                    snap.Columns.Add(cname);
                    snap.ColKind[cname] = kinds[i];
                    // Type string is like "s72" / "S255" / "i2" / "l0"; the trailing
                    // digits are the max length for string columns (0 = unbounded).
                    int len = 0;
                    for (int p = 1; p < ctype.Length; p++)
                        if (char.IsDigit(ctype[p])) len = len * 10 + (ctype[p] - '0');
                        else if (len > 0) break;
                    if (kinds[i] == 's' && len > 0) snap.ColMaxLen[cname] = len;
                }
                Release(namesRec); Release(typesRec);

                try
                {
                    dynamic keys = db.PrimaryKeys[table];
                    int kc = (int)keys.FieldCount;
                    for (int i = 1; i <= kc; i++) snap.KeyCols.Add((string)keys.StringData(i));
                    Release(keys);
                }
                catch { }
                if (snap.KeyCols.Count == 0 && snap.Columns.Count > 0)
                    snap.KeyCols.Add(snap.Columns[0]);

                int rows = 0;
                while (true)
                {
                    // Honour cancellation periodically while reading large tables.
                    if ((rows & 0x3FF) == 0) token.ThrowIfCancellationRequested();
                    dynamic? rec = view.Fetch();
                    if (rec == null) break;
                    var row = new string[cols];
                    for (int i = 1; i <= cols; i++)
                        row[i - 1] = kinds[i] == 'v' ? "(binary)" : (string)rec.StringData(i);
                    snap.Rows.Add(row);
                    rows++; Release(rec);
                    if (rows >= 20000) { snap.Capped = true; break; }   // higher cap for validation
                }
                return snap;
            }
            catch (OperationCanceledException) { throw; }
            catch { return null; }
            finally { try { view?.Close(); } catch { } Release(view); }
        }

        /// <summary>
        /// Runs all built-in checks. Uses the in-memory <paramref name="edited"/>
        /// snapshots (which carry unsaved edits) and reads any other needed tables
        /// from the file. Fully thread-safe — touches no UI/DataTable state.
        /// </summary>
        private static List<ValidationIssue> RunValidationCore(
            string msiPath, List<string> available,
            Dictionary<string, TableSnapshot> edited,
            System.Threading.CancellationToken token)
        {
            var issues = new List<ValidationIssue>();
            var cache = new Dictionary<string, TableSnapshot>(edited, StringComparer.OrdinalIgnoreCase);
            var availSet = new HashSet<string>(available, StringComparer.OrdinalIgnoreCase);

            // Open the MSI for any file reads we still need. Native (msi.dll) is the
            // fast path; the automation handle is a lazily-opened fallback.
            uint hNativeDb = 0;
            dynamic? inst = null, db = null;
            try
            {
                TableSnapshot? Get(string name)
                {
                    if (string.IsNullOrEmpty(name)) return null;
                    if (cache.TryGetValue(name, out var s)) return s;
                    if (!availSet.Contains(name)) return null;   // table not in this MSI

                    TableSnapshot? loaded = null;
                    if (hNativeDb == 0 &&
                        MsiApi.MsiOpenDatabaseW(msiPath, IntPtr.Zero, out hNativeDb) != MsiApi.ERROR_SUCCESS)
                        hNativeDb = 0;
                    if (hNativeDb != 0)
                        loaded = SnapshotTableNative(hNativeDb, name, ValidationRowCap, token);

                    if (loaded == null)   // native could not read it — fall back to automation
                    {
                        if (db == null) { inst = NewInstaller(); db = inst.OpenDatabase(msiPath, 0); }
                        loaded = SnapshotFromFile(db, name, token);
                    }
                    if (loaded != null) cache[name] = loaded;
                    return loaded;
                }

                // Determine which tables to read: those involved in any check.
                var wanted = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "Property" };
                foreach (var fk in _foreignKeys)
                { if (fk.Table.Length > 0) wanted.Add(fk.Table); if (fk.RefTable.Length > 0) wanted.Add(fk.RefTable); }
                foreach (var t in _sequenceTables) wanted.Add(t);
                // Plus any already-edited tables (so structural checks cover them).
                foreach (var t in edited.Keys) wanted.Add(t);

                var snaps = new Dictionary<string, TableSnapshot>(StringComparer.OrdinalIgnoreCase);
                foreach (var t in wanted)
                {
                    token.ThrowIfCancellationRequested();
                    var s = Get(t);
                    if (s != null) snaps[t] = s;
                }

                // Read the MSI's own _Validation table. When present it declares the
                // real per-column constraints (nullability, foreign keys, integer
                // ranges, enumerated sets, categories) for this exact package.
                var constraints = ReadColumnConstraints(msiPath, token);
                bool useValidationTable = constraints.Count > 0;

                // Primary-key columns that are allowed to be empty. Some key columns
                // are nullable despite being part of a composite key — most notably
                // the Upgrade table's VersionMin/VersionMax/Language. The MSI schema
                // permits empty values there, so they must not be flagged. Driven by
                // the package's _Validation table, with a baseline for the well-known
                // case so it still holds when no _Validation table is present.
                var nullablePk = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                {
                    "Upgrade\u001FVersionMin", "Upgrade\u001FVersionMax", "Upgrade\u001FLanguage"
                };
                foreach (var con in constraints)
                    if (string.Equals(con.Nullable, "Y", StringComparison.OrdinalIgnoreCase))
                        nullablePk.Add(con.Table + "\u001F" + con.Column);

                // 1) Structural + 2) type checks over every snapshot we have.
                foreach (var kv in snaps)
                {
                    token.ThrowIfCancellationRequested();
                    CheckPrimaryKeys(kv.Key, kv.Value, issues, nullablePk);
                    CheckIntegerColumns(kv.Key, kv.Value, issues);
                }

                // 2b) _Validation-driven checks. When the package ships a _Validation
                // table these supersede the hardcoded foreign-key list and the
                // empty-property heuristic with the package's own declared rules,
                // and add nullability, range, enumerated-set and format checks.
                if (useValidationTable)
                    CheckFromValidationTable(constraints, Get, issues, token);

                // 3) Foreign-key integrity. Hardcoded references, used only when the
                // package has no _Validation table to drive a complete FK check.
                if (!useValidationTable)
                foreach (var fk in _foreignKeys)
                {
                    token.ThrowIfCancellationRequested();
                    if (fk.RefTable.Length == 0) continue;
                    if (!snaps.TryGetValue(fk.Table, out var src) || !src.HasColumn(fk.Col)) continue;
                    if (!snaps.TryGetValue(fk.RefTable, out var refSt) || !refSt.HasColumn(fk.RefCol)) continue;
                    if (refSt.Capped) continue;   // can't be sure a missing key isn't beyond the cap

                    int rci = refSt.ColIndex(fk.RefCol);
                    var validKeys = new HashSet<string>(StringComparer.Ordinal);
                    foreach (var rr in refSt.Rows) validKeys.Add(rr[rci]);

                    int sci = src.ColIndex(fk.Col);
                    foreach (var sr in src.Rows)
                    {
                        string val = sr[sci];
                        if (string.IsNullOrWhiteSpace(val)) continue;
                        if (!validKeys.Contains(val))
                            issues.Add(new ValidationIssue
                            {
                                Severity = "Error", Code = "ICE03-like", Table = fk.Table,
                                RowKey = RowKeyOf(src, sr), Column = fk.Col,
                                Message = $"“{val}” does not exist in {fk.RefTable}.{fk.RefCol}."
                            });
                    }
                }

                // 4) Sequence-number collisions.
                foreach (var t in _sequenceTables)
                {
                    if (!snaps.TryGetValue(t, out var st) || !st.HasColumn("Sequence")) continue;
                    int sqi = st.ColIndex("Sequence");
                    int aci = st.ColIndex("Action");
                    var seen = new Dictionary<string, string>(StringComparer.Ordinal);
                    foreach (var r in st.Rows)
                    {
                        string seq = r[sqi].Trim();
                        if (seq.Length == 0 || seq == "0") continue;
                        string action = aci >= 0 ? r[aci] : "";
                        if (seen.TryGetValue(seq, out var other))
                            issues.Add(new ValidationIssue
                            {
                                Severity = "Warning", Code = "ICE-seq", Table = t,
                                RowKey = action, Column = "Sequence",
                                Message = $"Sequence {seq} is shared with “{other}”."
                            });
                        else seen[seq] = action;
                    }
                }

                // 5) Property smell: empty value (fallback — the _Validation pass
                // covers Property.Value nullability when that table is present).
                if (!useValidationTable &&
                    snaps.TryGetValue("Property", out var propSt) &&
                    propSt.HasColumn("Property") && propSt.HasColumn("Value"))
                {
                    int pn = propSt.ColIndex("Property"), pv = propSt.ColIndex("Value");
                    foreach (var r in propSt.Rows)
                    {
                        string name = r[pn], val = r[pv];
                        if (name.Length > 0 && string.IsNullOrWhiteSpace(val))
                            issues.Add(new ValidationIssue
                            {
                                Severity = "Warning", Code = "ICE-prop", Table = "Property",
                                RowKey = name, Column = "Value", Message = "Property has an empty value."
                            });
                    }
                }

                token.ThrowIfCancellationRequested();

                // 6) Orphaned components — a Component referenced by no Feature
                // (via FeatureComponents). Such components never install. (ICE-orphan)
                if (snaps.TryGetValue("Component", out var compSt) && compSt.HasColumn("Component") &&
                    !compSt.Capped)
                {
                    var used = new HashSet<string>(StringComparer.Ordinal);
                    bool fcReliable = true;
                    if (snaps.TryGetValue("FeatureComponents", out var fcSt) && fcSt.HasColumn("Component_"))
                    {
                        if (fcSt.Capped) fcReliable = false;
                        int ci = fcSt.ColIndex("Component_");
                        foreach (var r in fcSt.Rows) used.Add(r[ci]);
                    }
                    int cci = compSt.ColIndex("Component");
                    if (fcReliable)
                        foreach (var r in compSt.Rows)
                        {
                            string comp = r[cci];
                            if (comp.Length > 0 && !used.Contains(comp))
                                issues.Add(new ValidationIssue
                                {
                                    Severity = "Warning", Code = "ICE-orphan", Table = "Component",
                                    RowKey = comp, Column = "Component",
                                    Message = "Component is not referenced by any Feature (won't install)."
                                });
                        }
                }

                token.ThrowIfCancellationRequested();

                // 7) Duplicate Component GUIDs (ICE08-like). The same ComponentId
                // used by more than one Component row is usually a packaging error.
                if (snaps.TryGetValue("Component", out var compSt2) &&
                    compSt2.HasColumn("Component") && compSt2.HasColumn("ComponentId") && !compSt2.Capped)
                {
                    int idi = compSt2.ColIndex("ComponentId");
                    int ki  = compSt2.ColIndex("Component");
                    var byGuid = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                    foreach (var r in compSt2.Rows)
                    {
                        string guid = r[idi].Trim();
                        if (guid.Length == 0) continue;   // null GUID = non-managed component, allowed
                        if (byGuid.TryGetValue(guid, out var firstComp))
                            issues.Add(new ValidationIssue
                            {
                                Severity = "Warning", Code = "ICE08-like", Table = "Component",
                                RowKey = r[ki], Column = "ComponentId",
                                Message = $"GUID {guid} is also used by component “{firstComp}”."
                            });
                        else byGuid[guid] = r[ki];
                    }
                }

                token.ThrowIfCancellationRequested();

                // 8) KeyPath sanity — a Component's KeyPath should point at a row in
                // File (or Registry, when the component is registry-keyed). We flag a
                // KeyPath that matches neither. (ICE-keypath)
                if (snaps.TryGetValue("Component", out var compSt3) &&
                    compSt3.HasColumn("Component") && compSt3.HasColumn("KeyPath") && !compSt3.Capped)
                {
                    var fileKeys = new HashSet<string>(StringComparer.Ordinal);
                    if (snaps.TryGetValue("File", out var fileSt) && fileSt.HasColumn("File") && !fileSt.Capped)
                    { int fi = fileSt.ColIndex("File"); foreach (var r in fileSt.Rows) fileKeys.Add(r[fi]); }

                    var regKeys = new HashSet<string>(StringComparer.Ordinal);
                    if (snaps.TryGetValue("Registry", out var regSt) && regSt.HasColumn("Registry") && !regSt.Capped)
                    { int ri = regSt.ColIndex("Registry"); foreach (var r in regSt.Rows) regKeys.Add(r[ri]); }

                    // Only meaningful when we actually have at least one of the target tables.
                    if (fileKeys.Count > 0 || regKeys.Count > 0)
                    {
                        int kpi = compSt3.ColIndex("KeyPath");
                        int kci = compSt3.ColIndex("Component");
                        foreach (var r in compSt3.Rows)
                        {
                            string kp = r[kpi].Trim();
                            if (kp.Length == 0) continue;   // empty KeyPath = directory-keyed, allowed
                            if (!fileKeys.Contains(kp) && !regKeys.Contains(kp))
                                issues.Add(new ValidationIssue
                                {
                                    Severity = "Warning", Code = "ICE-keypath", Table = "Component",
                                    RowKey = r[kci], Column = "KeyPath",
                                    Message = $"KeyPath “{kp}” matches no File or Registry row."
                                });
                        }
                    }
                }

                token.ThrowIfCancellationRequested();

                // 9) Column-length violations — a string value longer than the
                // column's declared maximum (e.g. an s72 holding 80 chars). (ICE-len)
                foreach (var kv in snaps)
                {
                    var st = kv.Value;
                    foreach (var col in st.Columns)
                    {
                        if (!st.ColMaxLen.TryGetValue(col, out int max) || max <= 0) continue;
                        int ci = st.ColIndex(col);
                        foreach (var r in st.Rows)
                        {
                            string v = r[ci];
                            if (v.Length > max)
                                issues.Add(new ValidationIssue
                                {
                                    Severity = "Warning", Code = "ICE-len", Table = kv.Key,
                                    RowKey = RowKeyOf(st, r), Column = col,
                                    Message = $"Value is {v.Length} chars; column max is {max}."
                                });
                        }
                    }
                }
            }
            finally
            {
                if (hNativeDb != 0) MsiApi.MsiCloseHandle(hNativeDb);
                Release(db); Release(inst);
                GC.Collect(); GC.WaitForPendingFinalizers();
            }

            return issues
                .OrderBy(i => i.Severity == "Error" ? 0 : 1)
                .ThenBy(i => i.Table, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static void CheckPrimaryKeys(string table, TableSnapshot st, List<ValidationIssue> issues,
                                             HashSet<string> nullablePk)
        {
            var keys = st.KeyCols.Count > 0 ? st.KeyCols
                       : (st.Columns.Count > 0 ? new List<string> { st.Columns[0] } : new List<string>());
            if (keys.Count == 0) return;
            var keyIdx = keys.Select(k => st.ColIndex(k)).Where(ix => ix >= 0).ToArray();
            if (keyIdx.Length == 0) return;

            // MSI primary keys are case-SENSITIVE → compare with Ordinal, else
            // distinct keys differing only in case are wrongly flagged duplicates.
            var seen = new HashSet<string>(StringComparer.Ordinal);
            foreach (var r in st.Rows)
            {
                // Empty key value — except for key columns that are nullable (e.g.
                // Upgrade.VersionMin/VersionMax/Language), where empty is permitted.
                foreach (var ix in keyIdx)
                    if (string.IsNullOrWhiteSpace(r[ix]) &&
                        !nullablePk.Contains(table + "\u001F" + st.Columns[ix]))
                        issues.Add(new ValidationIssue
                        {
                            Severity = "Error", Code = "ICE-key", Table = table,
                            RowKey = RowKeyOf(st, r), Column = st.Columns[ix],
                            Message = "Primary-key column is empty."
                        });

                // Duplicate composite key.
                string sig = string.Join("\u001F", keyIdx.Select(ix => r[ix]));
                if (sig.Trim('\u001F').Length > 0 && !seen.Add(sig))
                    issues.Add(new ValidationIssue
                    {
                        Severity = "Error", Code = "ICE-dup", Table = table,
                        RowKey = sig.Replace('\u001F', '/'), Column = string.Join("+", keys),
                        Message = "Duplicate primary key."
                    });
            }
        }

        private static void CheckIntegerColumns(string table, TableSnapshot st, List<ValidationIssue> issues)
        {
            for (int ci = 0; ci < st.Columns.Count; ci++)
            {
                if (!st.ColKind.TryGetValue(st.Columns[ci], out char k) || k != 'i') continue;
                foreach (var r in st.Rows)
                {
                    string v = r[ci].Trim();
                    if (v.Length == 0) continue;
                    if (!long.TryParse(v, out _))
                        issues.Add(new ValidationIssue
                        {
                            Severity = "Error", Code = "ICE-type", Table = table,
                            RowKey = RowKeyOf(st, r), Column = st.Columns[ci],
                            Message = $"Integer column holds non-numeric value “{v}”."
                        });
                }
            }
        }

        private static string RowKeyOf(TableSnapshot st, string[] r)
        {
            var keys = st.KeyCols.Count > 0 ? st.KeyCols
                       : (st.Columns.Count > 0 ? new List<string> { st.Columns[0] } : new List<string>());
            return string.Join("/", keys.Select(k => st.ColIndex(k)).Where(ix => ix >= 0).Select(ix => r[ix]));
        }

        // Validation reads can go deeper than the 5000-row grid cap; the native
        // reader is fast enough that a higher cap rarely disables a check.
        private const int ValidationRowCap = 50000;

        /// <summary>
        /// Reads a table from an open native database into a plain TableSnapshot
        /// (columns, kinds, declared string max-lengths, primary keys, rows). Honours
        /// cancellation. Returns null on failure so callers can fall back to automation.
        /// </summary>
        private static TableSnapshot? SnapshotTableNative(uint hDb, string table, int cap,
            System.Threading.CancellationToken token)
        {
            uint hView = 0, hNames = 0, hTypes = 0;
            try
            {
                if (MsiApi.MsiDatabaseOpenViewW(hDb, $"SELECT * FROM `{table}`", out hView) != MsiApi.ERROR_SUCCESS)
                    return null;
                if (MsiApi.MsiViewExecute(hView, 0) != MsiApi.ERROR_SUCCESS)
                    return null;
                if (MsiApi.MsiViewGetColumnInfo(hView, MsiApi.MSICOLINFO_NAMES, out hNames) != MsiApi.ERROR_SUCCESS)
                    return null;
                if (MsiApi.MsiViewGetColumnInfo(hView, MsiApi.MSICOLINFO_TYPES, out hTypes) != MsiApi.ERROR_SUCCESS)
                    return null;

                int cols = (int)MsiApi.MsiRecordGetFieldCount(hNames);
                if (cols <= 0) return null;
                var snap = new TableSnapshot();
                var kinds = new char[cols + 1];
                for (int i = 1; i <= cols; i++)
                {
                    string cname = MsiGetString(hNames, (uint)i);
                    string ctype = MsiGetString(hTypes, (uint)i);   // s72 / S255 / i2 / l0 …
                    char k = char.ToLowerInvariant(ctype.Length > 0 ? ctype[0] : 's');
                    kinds[i] = (k == 'i' || k == 'j') ? 'i' : (k == 'v' || k == 'o') ? 'v' : 's';
                    snap.Columns.Add(cname);
                    snap.ColKind[cname] = kinds[i];
                    // Trailing digits of the type string are the max length for string
                    // columns (0 = unbounded).
                    int len = 0;
                    for (int p = 1; p < ctype.Length; p++)
                        if (char.IsDigit(ctype[p])) len = len * 10 + (ctype[p] - '0');
                        else if (len > 0) break;
                    if (kinds[i] == 's' && len > 0) snap.ColMaxLen[cname] = len;
                }

                if (MsiApi.MsiDatabaseGetPrimaryKeysW(hDb, table, out uint hKeys) == MsiApi.ERROR_SUCCESS && hKeys != 0)
                {
                    int kc = (int)MsiApi.MsiRecordGetFieldCount(hKeys);
                    for (int i = 1; i <= kc; i++) snap.KeyCols.Add(MsiGetString(hKeys, (uint)i));
                    MsiApi.MsiCloseHandle(hKeys);
                }
                if (snap.KeyCols.Count == 0 && snap.Columns.Count > 0) snap.KeyCols.Add(snap.Columns[0]);

                int rows = 0;
                while (true)
                {
                    if ((rows & 0x3FF) == 0) token.ThrowIfCancellationRequested();
                    if (MsiApi.MsiViewFetch(hView, out uint hRec) != MsiApi.ERROR_SUCCESS || hRec == 0)
                        break;
                    var row = new string[cols];
                    for (int i = 1; i <= cols; i++)
                        row[i - 1] = kinds[i] == 'v' ? "(binary)" : MsiGetString(hRec, (uint)i);
                    snap.Rows.Add(row);
                    MsiApi.MsiCloseHandle(hRec);
                    rows++;
                    if (rows >= cap) { snap.Capped = true; break; }
                }
                return snap;
            }
            catch (OperationCanceledException) { throw; }
            catch { return null; }
            finally
            {
                if (hNames != 0) MsiApi.MsiCloseHandle(hNames);
                if (hTypes != 0) MsiApi.MsiCloseHandle(hTypes);
                if (hView  != 0) { MsiApi.MsiViewClose(hView); MsiApi.MsiCloseHandle(hView); }
            }
        }

        // One column's declared constraints, as carried by the MSI _Validation table.
        private sealed class ColConstraint
        {
            public string Table = "";
            public string Column = "";
            public string Nullable = "";    // "Y" / "N"
            public string MinValue = "";    // integer bounds (blank = no bound)
            public string MaxValue = "";
            public string KeyTable = "";    // foreign key target(s); may be ";"-separated
            public string KeyColumn = "";   // 1-based ordinal of the referenced column
            public string Category = "";    // GUID / Version / Language / Identifier / …
            public string Set = "";         // ";"-separated enumerated allowed values
        }

        /// <summary>Reads the MSI's _Validation table into per-column constraints.
        /// Returns an empty list when the package has no usable _Validation table.</summary>
        private static List<ColConstraint> ReadColumnConstraints(string msiPath,
            System.Threading.CancellationToken token)
        {
            var list = new List<ColConstraint>();
            uint hDb = 0;
            try
            {
                if (MsiApi.MsiOpenDatabaseW(msiPath, IntPtr.Zero, out hDb) != MsiApi.ERROR_SUCCESS)
                    return list;
                var v = SnapshotTableNative(hDb, "_Validation", 100000, token);
                if (v == null) return list;
                int iT = v.ColIndex("Table"), iC = v.ColIndex("Column");
                if (iT < 0 || iC < 0) return list;   // not a usable _Validation table
                int iN = v.ColIndex("Nullable"), iMin = v.ColIndex("MinValue"), iMax = v.ColIndex("MaxValue");
                int iKT = v.ColIndex("KeyTable"), iKC = v.ColIndex("KeyColumn");
                int iCat = v.ColIndex("Category"), iSet = v.ColIndex("Set");
                string Cell(string[] r, int ix) => ix >= 0 && ix < r.Length ? r[ix] : "";
                foreach (var r in v.Rows)
                    list.Add(new ColConstraint
                    {
                        Table = Cell(r, iT), Column = Cell(r, iC), Nullable = Cell(r, iN),
                        MinValue = Cell(r, iMin), MaxValue = Cell(r, iMax),
                        KeyTable = Cell(r, iKT), KeyColumn = Cell(r, iKC),
                        Category = Cell(r, iCat), Set = Cell(r, iSet),
                    });
                return list;
            }
            catch (OperationCanceledException) { throw; }
            catch { return list; }
            finally { if (hDb != 0) MsiApi.MsiCloseHandle(hDb); }
        }

        // Conservative, high-signal category formats. Only columns whose category is
        // unambiguous (a GUID column always holds a GUID, a Language column always
        // holds LCIDs) are format-checked, to avoid false positives on the looser
        // categories (Identifier, Filename, Path, Version-or-companion-file, …).
        private static readonly System.Text.RegularExpressions.Regex _reGuid =
            new(@"^\{[0-9A-Fa-f]{8}-([0-9A-Fa-f]{4}-){3}[0-9A-Fa-f]{12}\}$",
                System.Text.RegularExpressions.RegexOptions.Compiled);
        private static readonly System.Text.RegularExpressions.Regex _reLanguage =
            new(@"^\d+(,\d+)*$", System.Text.RegularExpressions.RegexOptions.Compiled);

        // Categories whose value is not a plain key even when _Validation names a
        // KeyTable. File.Version (category Version) is either a version string or a
        // companion-file key; Formatted/Template/Condition columns hold expressions,
        // not literal keys. Treating these as strict foreign keys produces large
        // numbers of false "does not exist" errors (e.g. every real File.Version).
        private static bool IsNonKeyCategory(string category) =>
            string.Equals(category, "Version",   StringComparison.OrdinalIgnoreCase) ||
            string.Equals(category, "Formatted", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(category, "Template",  StringComparison.OrdinalIgnoreCase) ||
            string.Equals(category, "Condition", StringComparison.OrdinalIgnoreCase);

        /// <summary>
        /// Checks every table/column against the rules its own _Validation table
        /// declares: required (Nullable=N) cells, foreign-key references
        /// (KeyTable/KeyColumn), integer ranges (MinValue/MaxValue), enumerated values
        /// (Set), and GUID/Language formats (Category). Loads referenced tables on
        /// demand through <paramref name="get"/>.
        /// </summary>
        private static void CheckFromValidationTable(
            List<ColConstraint> constraints,
            Func<string, TableSnapshot?> get,
            List<ValidationIssue> issues,
            System.Threading.CancellationToken token)
        {
            foreach (var con in constraints)
            {
                token.ThrowIfCancellationRequested();
                if (con.Table.Length == 0 || con.Column.Length == 0) continue;
                // System/metadata tables (_Validation, _Columns, _Tables, _Streams …)
                // are schema, not package data; validating them against themselves is
                // meaningless (e.g. _Validation.Category legitimately holds "DefaultDir").
                if (con.Table[0] == '_') continue;
                var src = get(con.Table);
                if (src == null || !src.HasColumn(con.Column)) continue;
                int sci = src.ColIndex(con.Column);

                bool required = string.Equals(con.Nullable, "N", StringComparison.OrdinalIgnoreCase);
                bool isKey = src.KeyCols.Any(k => string.Equals(k, con.Column, StringComparison.OrdinalIgnoreCase));
                bool isInt = (src.ColKind.TryGetValue(con.Column, out var kk) && kk == 'i')
                             || string.Equals(con.Category, "Integer", StringComparison.OrdinalIgnoreCase)
                             || string.Equals(con.Category, "DoubleInteger", StringComparison.OrdinalIgnoreCase);
                bool hasMin = long.TryParse(con.MinValue, out long min);
                bool hasMax = long.TryParse(con.MaxValue, out long max);
                var allowed = con.Set.Length > 0
                    ? new HashSet<string>(con.Set.Split(';'), StringComparer.Ordinal) : null;

                // Foreign-key target value sets (union across candidate key tables).
                // Skip columns whose category means the value is not a plain key
                // (Version/Formatted/Template/Condition) to avoid false positives.
                List<HashSet<string>>? fkSets = null;
                bool fkReliable = true;
                if (con.KeyTable.Length > 0 && !IsNonKeyCategory(con.Category))
                {
                    int keyOrd = int.TryParse(con.KeyColumn, out var ko) && ko > 0 ? ko : 1;
                    fkSets = new List<HashSet<string>>();
                    foreach (var raw in con.KeyTable.Split(';'))
                    {
                        string kt = raw.Trim();
                        if (kt.Length == 0) continue;
                        var refSt = get(kt);
                        if (refSt == null) { fkReliable = false; continue; }
                        if (refSt.Capped) fkReliable = false;
                        if (keyOrd > refSt.Columns.Count) { fkReliable = false; continue; }
                        var set = new HashSet<string>(StringComparer.Ordinal);
                        foreach (var rr in refSt.Rows) set.Add(rr[keyOrd - 1]);
                        fkSets.Add(set);
                    }
                    if (fkSets.Count == 0) fkSets = null;
                }

                string cat = con.Category;
                foreach (var r in src.Rows)
                {
                    string val = sci < r.Length ? r[sci] : "";

                    // Required-but-empty (primary keys are covered by the PK check).
                    if (required && !isKey && string.IsNullOrEmpty(val))
                    {
                        issues.Add(new ValidationIssue
                        {
                            Severity = "Warning", Code = "ICE-null", Table = con.Table,
                            RowKey = RowKeyOf(src, r), Column = con.Column,
                            Message = "Required column (Nullable=N) is empty."
                        });
                        continue;
                    }
                    if (string.IsNullOrEmpty(val)) continue;   // optional & empty → done

                    // Foreign key: value must exist in at least one referenced table.
                    if (fkSets != null && fkReliable && !fkSets.Any(s => s.Contains(val)))
                        issues.Add(new ValidationIssue
                        {
                            Severity = "Error", Code = "ICE03-like", Table = con.Table,
                            RowKey = RowKeyOf(src, r), Column = con.Column,
                            Message = $"“{Trunc(val)}” does not exist in {con.KeyTable}."
                        });

                    // Integer range.
                    if (isInt && (hasMin || hasMax) && long.TryParse(val.Trim(), out long iv)
                        && ((hasMin && iv < min) || (hasMax && iv > max)))
                        issues.Add(new ValidationIssue
                        {
                            Severity = "Warning", Code = "ICE-range", Table = con.Table,
                            RowKey = RowKeyOf(src, r), Column = con.Column,
                            Message = $"Value {iv} is outside the declared range " +
                                      $"[{(hasMin ? min.ToString() : "*")}, {(hasMax ? max.ToString() : "*")}]."
                        });

                    // Enumerated set.
                    if (allowed != null && !allowed.Contains(val))
                        issues.Add(new ValidationIssue
                        {
                            Severity = "Warning", Code = "ICE-set", Table = con.Table,
                            RowKey = RowKeyOf(src, r), Column = con.Column,
                            Message = $"Value “{Trunc(val)}” is not one of: {Trunc(con.Set)}."
                        });

                    // Category format (GUID / Language only — unambiguous categories).
                    bool badFormat =
                        (string.Equals(cat, "GUID", StringComparison.OrdinalIgnoreCase) && !_reGuid.IsMatch(val)) ||
                        (string.Equals(cat, "Language", StringComparison.OrdinalIgnoreCase) && !_reLanguage.IsMatch(val));
                    if (badFormat)
                        issues.Add(new ValidationIssue
                        {
                            Severity = "Warning", Code = "ICE-fmt", Table = con.Table,
                            RowKey = RowKeyOf(src, r), Column = con.Column,
                            Message = $"Value “{Trunc(val)}” is not a valid {cat}."
                        });
                }
            }
        }

        // ── Validation panel UI ─────────────────────────────────────────
        private bool _panelCollapsed = false;

        private void ShowBottomPanel()
        {
            if (BottomPanel != null) BottomPanel.Visibility = Visibility.Visible;
            if (_panelCollapsed) SetPanelCollapsed(false);
        }

        private void BtnViewChanges_Click(object sender, RoutedEventArgs e)
        {
            ShowBottomPanel();
            if (TabTransform == null) return;
            if (TabTransform.IsChecked == true)
                BottomView_Changed(TabTransform, new RoutedEventArgs());   // already selected -> refresh
            else
                TabTransform.IsChecked = true;                              // fires BottomView_Changed
        }

        private void BtnPanelClose_Click(object sender, RoutedEventArgs e)
        {
            if (BottomPanel != null) BottomPanel.Visibility = Visibility.Collapsed;
        }

        private void BtnPanelToggle_Click(object sender, RoutedEventArgs e)
            => SetPanelCollapsed(!_panelCollapsed);

        private void SetPanelCollapsed(bool collapsed)
        {
            _panelCollapsed = collapsed;
            if (PanelBody != null)
                PanelBody.Visibility = collapsed ? Visibility.Collapsed : Visibility.Visible;
            if (BtnPanelToggle != null)
                BtnPanelToggle.Content = collapsed ? "▸" : "▾";
        }

        private void LstValidation_DoubleClick(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            if (LstValidation.SelectedItem is not ValidationIssue issue) return;
            if (string.IsNullOrEmpty(issue.Table)) return;

            // Select the offending table (loads its grid), then find + select the row.
            if (!string.Equals(_currentTable, issue.Table, StringComparison.OrdinalIgnoreCase))
                LstTables.SelectedItem = issue.Table;

            Dispatcher.BeginInvoke(new Action(() =>
            {
                if (GridRows.ItemsSource is not DataView dv) return;
                if (!_tables.TryGetValue(issue.Table, out var st)) return;
                foreach (DataRowView drv in dv)
                {
                    if (string.Equals(RowKeyOfState(st, drv.Row), issue.RowKey, StringComparison.Ordinal))
                    {
                        GridRows.SelectedItem = drv;
                        GridRows.ScrollIntoView(drv);
                        break;
                    }
                }
            }), System.Windows.Threading.DispatcherPriority.Background);
        }

        /// <summary>Row-key signature for a live DataRow (used to locate a row in the grid).</summary>
        private static string RowKeyOfState(TableState st, DataRow r)
        {
            var keys = st.KeyCols.Count > 0 ? st.KeyCols
                       : (st.Data.Columns.Count > 0 ? new List<string> { st.Data.Columns[0].ColumnName } : new List<string>());
            return string.Join("/", keys.Where(k => st.Data.Columns.Contains(k))
                                        .Select(k => (r[k] ?? "").ToString()));
        }

        private void ClearValidation()
        {
            _validation.Clear();
            if (TxtPanelSummary != null && TabValidation?.IsChecked == true) TxtPanelSummary.Text = "";
        }

        // ── Transform changes summary ───────────────────────────────────
        //
        // A flat list of everything this transform does, populated either from
        // an applied .mst (original vs. transformed MSI) or from the staged grid
        // edits (original vs. current in-memory rows). Informational; reuses the
        // bottom panel and the click-to-jump mechanic.

        public sealed class TransformChange
        {
            public string Action { get; set; } = "";   // "Add" / "Modify" / "Delete"
            public string Table  { get; set; } = "";
            public string RowKey { get; set; } = "";
            public string Column { get; set; } = "";
            public string Change { get; set; } = "";    // "old → new" / "(new) val" / "(removed)"
        }

        private readonly ObservableCollection<TransformChange> _transformChanges = new();

        // Changes the applied .mst itself records against the MSI (added/modified/
        // deleted rows). Computed once when a transform is applied and shown as the
        // base of the Transform changes panel; empty when no transform is applied.
        private List<TransformChange> _appliedTransformChanges = new();

        private void BottomView_Changed(object sender, RoutedEventArgs e)
        {
            if (ViewValidation == null || ViewTransform == null) return;   // during init
            bool transform = TabTransform.IsChecked == true;
            ViewValidation.Visibility = transform ? Visibility.Collapsed : Visibility.Visible;
            ViewTransform.Visibility  = transform ? Visibility.Visible   : Visibility.Collapsed;

            if (transform)
            {
                // Populates the list from in-memory staged edits (synchronous), then
                // shows the add/modify/delete summary.
                RefreshTransformChanges();
                int adds = _transformChanges.Count(c => c.Action == "Add");
                int mods = _transformChanges.Count(c => c.Action == "Modify");
                int dels = _transformChanges.Count(c => c.Action == "Delete");
                TxtPanelSummary.Text = _transformChanges.Count == 0
                    ? "No changes."
                    : $"{_transformChanges.Count} change(s) · {adds} add · {mods} modify · {dels} delete";
            }
            else
            {
                // Restore the validation summary text.
                int errors = _validation.Count(i => i.Severity == "Error");
                int warns  = _validation.Count(i => i.Severity == "Warning");
                TxtPanelSummary.Text = _validation.Count == 0 ? "" : $"{errors} error(s), {warns} warning(s).";
            }
        }

        /// <summary>Recomputes the Transform changes list for the current state.</summary>
        private void RefreshTransformChanges()
        {
            try { GridRows.CommitEdit(DataGridEditingUnit.Cell, true); GridRows.CommitEdit(DataGridEditingUnit.Row, true); }
            catch { }

            // The panel shows the changes the applied transform itself records
            // (added/modified/deleted rows vs the MSI), plus any NEW edits the user
            // is staging in-memory on top of it. With no transform applied the
            // applied-changes set is empty, so only staged edits appear.
            _transformChanges.Clear();
            foreach (var c in _appliedTransformChanges) _transformChanges.Add(c);
            ComputeStagedChanges();
        }

        /// <summary>Changes produced by an applied .mst: diff original vs. transformed MSI. Thread-safe.</summary>
        private static List<TransformChange> ComputeAppliedTransformChangesCore(
            string origMsi, string tranMsi, List<string> tableList)
        {
            var changes = new List<TransformChange>();

            // Snapshot each database once (rows + column/key names in the same pass),
            // rather than reopening per table and reading shapes through automation.
            var origDb = SnapshotDatabaseNative(origMsi, tableList);
            var tranDb = SnapshotDatabaseNative(tranMsi, tableList);

            foreach (var table in tableList)
            {
                origDb.TryGetValue(table, out var oSnap);
                tranDb.TryGetValue(table, out var tSnap);
                if (oSnap == null && tSnap == null) continue;

                var orig = oSnap?.Rows ?? new(StringComparer.Ordinal);
                var tran = tSnap?.Rows ?? new(StringComparer.Ordinal);
                var shape = tSnap ?? oSnap!;
                var cols = shape.Cols;
                var keyCols = shape.KeyCols;

                foreach (var kv in tran)
                {
                    if (!orig.TryGetValue(kv.Key, out var ov))
                        changes.Add(new TransformChange {
                            Action = "Add", Table = table, RowKey = kv.Key.Replace('\u001F', '/'),
                            Column = "", Change = "(new) " + FirstNonKeyValue(kv.Value, cols, keyCols) });
                    else if (ov != kv.Value)
                        AddModifyRowsStatic(changes, table, kv.Key, ov, kv.Value, cols);
                }
                foreach (var kv in orig)
                    if (!tran.ContainsKey(kv.Key))
                        changes.Add(new TransformChange {
                            Action = "Delete", Table = table, RowKey = kv.Key.Replace('\u001F', '/'),
                            Column = "", Change = "(removed)" });
            }
            return changes
                .OrderBy(c => c.Action == "Add" ? 0 : c.Action == "Modify" ? 1 : 2)
                .ThenBy(c => c.Table, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        /// <summary>Changes staged in the grid: compare original vs. current in-memory rows.</summary>
        private void ComputeStagedChanges()
        {
            foreach (var (table, st) in _tables.Select(kv => (kv.Key, kv.Value)))
            {
                var cols = st.Data.Columns.Cast<DataColumn>().Select(c => c.ColumnName).ToList();
                foreach (DataRow r in st.Data.Rows)
                {
                    // A marked-for-deletion ghost is reported as a Delete regardless of
                    // its underlying RowState (it may also carry edits we ignore).
                    if (st.MarkedDelete.Contains(r))
                    {
                        _transformChanges.Add(new TransformChange {
                            Action = "Delete", Table = table,
                            RowKey = RowKeyOfState(st, r), Column = "", Change = "(removed)" });
                        continue;
                    }
                    switch (r.RowState)
                    {
                        case DataRowState.Added:
                            _transformChanges.Add(new TransformChange {
                                Action = "Add", Table = table, RowKey = RowKeyOfState(st, r),
                                Column = "", Change = "(new) " + FirstCellValue(r, st) });
                            break;
                        case DataRowState.Deleted:
                            _transformChanges.Add(new TransformChange {
                                Action = "Delete", Table = table,
                                RowKey = RowKeyOfStateDeleted(st, r), Column = "", Change = "(removed)" });
                            break;
                        case DataRowState.Modified:
                            foreach (var c in cols)
                            {
                                string ov = (r[c, DataRowVersion.Original] ?? "").ToString();
                                string nv = (r[c, DataRowVersion.Current]  ?? "").ToString();
                                if (ov != nv)
                                    _transformChanges.Add(new TransformChange {
                                        Action = "Modify", Table = table, RowKey = RowKeyOfState(st, r),
                                        Column = c, Change = Trunc(ov) + " → " + Trunc(nv) });
                            }
                            break;
                    }
                }
            }
            SortTransformChanges();
        }

        private static void AddModifyRowsStatic(List<TransformChange> changes, string table, string key,
            string origRow, string tranRow, List<string> cols)
        {
            var o = origRow.Split('\u001F');
            var n = tranRow.Split('\u001F');
            int count = Math.Max(o.Length, n.Length);
            for (int i = 0; i < count; i++)
            {
                string ov = i < o.Length ? o[i] : "";
                string nv = i < n.Length ? n[i] : "";
                if (ov == nv) continue;
                changes.Add(new TransformChange {
                    Action = "Modify", Table = table, RowKey = key.Replace('\u001F', '/'),
                    Column = i < cols.Count ? cols[i] : $"col{i + 1}",
                    Change = Trunc(ov) + " → " + Trunc(nv) });
            }
        }

        private void SortTransformChanges()
        {
            var ordered = _transformChanges
                .OrderBy(c => c.Action == "Add" ? 0 : c.Action == "Modify" ? 1 : 2)
                .ThenBy(c => c.Table, StringComparer.OrdinalIgnoreCase)
                .ToList();
            _transformChanges.Clear();
            foreach (var c in ordered) _transformChanges.Add(c);
        }

        private static string Trunc(string s) => s.Length <= 60 ? s : s.Substring(0, 57) + "…";

        private static (List<string> cols, List<string> keys) ReadTableShape(string msiPath, string table)
        {
            var cols = new List<string>(); var keys = new List<string>();
            dynamic? inst = null, db = null, view = null;
            try
            {
                inst = NewInstaller();
                db   = inst.OpenDatabase(msiPath, 0);
                view = db.OpenView($"SELECT * FROM `{table}`");
                view.Execute();
                dynamic namesRec = view.ColumnInfo[0];
                int n = (int)namesRec.FieldCount;
                for (int i = 1; i <= n; i++) cols.Add((string)namesRec.StringData(i));
                Release(namesRec);
                try
                {
                    dynamic k = db.PrimaryKeys[table];
                    int kc = (int)k.FieldCount;
                    for (int i = 1; i <= kc; i++) keys.Add((string)k.StringData(i));
                    Release(k);
                }
                catch { }
            }
            catch { }
            finally { try { view?.Close(); } catch { } Release(view); Release(db); Release(inst); }
            return (cols, keys);
        }

        private static string FirstNonKeyValue(string rowSig, List<string> cols, List<string> keyCols)
        {
            var parts = rowSig.Split('\u001F');
            for (int i = 0; i < parts.Length && i < cols.Count; i++)
                if (!keyCols.Contains(cols[i]) && parts[i].Length > 0) return Trunc(parts[i]);
            return parts.Length > 0 ? Trunc(parts[0]) : "";
        }

        private static string FirstCellValue(DataRow r, TableState st)
        {
            var keys = new HashSet<string>(st.KeyCols, StringComparer.OrdinalIgnoreCase);
            foreach (DataColumn c in st.Data.Columns)
                if (!keys.Contains(c.ColumnName))
                {
                    string v = (r[c] ?? "").ToString();
                    if (v.Length > 0) return Trunc(v);
                }
            return st.Data.Columns.Count > 0 ? Trunc((r[0] ?? "").ToString()) : "";
        }

        private static string RowKeyOfStateDeleted(TableState st, DataRow r)
        {
            var keys = st.KeyCols.Count > 0 ? st.KeyCols
                       : (st.Data.Columns.Count > 0 ? new List<string> { st.Data.Columns[0].ColumnName } : new List<string>());
            return string.Join("/", keys.Where(k => st.Data.Columns.Contains(k))
                                        .Select(k => (r[k, DataRowVersion.Original] ?? "").ToString()));
        }

        private void LstTransform_DoubleClick(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            if (LstTransform.SelectedItem is not TransformChange ch || string.IsNullOrEmpty(ch.Table)) return;

            if (!string.Equals(_currentTable, ch.Table, StringComparison.OrdinalIgnoreCase))
                LstTables.SelectedItem = ch.Table;

            Dispatcher.BeginInvoke(new Action(() =>
            {
                if (GridRows.ItemsSource is not DataView dv) return;
                if (!_tables.TryGetValue(ch.Table, out var st)) return;
                string want = ch.RowKey.Replace('/', '\u001F');
                foreach (DataRowView drv in dv)
                {
                    string have = RowKeyOfState(st, drv.Row).Replace('/', '\u001F');
                    if (string.Equals(have, want, StringComparison.Ordinal))
                    {
                        GridRows.SelectedItem = drv;
                        GridRows.ScrollIntoView(drv);
                        break;
                    }
                }
            }), System.Windows.Threading.DispatcherPriority.Background);
        }

        private void ClearTransformChanges()
        {
            _transformChanges.Clear();
            if (TabTransform?.IsChecked == true && TxtPanelSummary != null) TxtPanelSummary.Text = "";
        }

        // ── Export (validation results + transform changes → one CSV) ───
        private void BtnExportPanel_Click(object sender, RoutedEventArgs e)
        {
            if (string.IsNullOrWhiteSpace(_msiPath))
            { MstMessage("Open an MSI first.", "Export", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            // Make sure the transform-changes list reflects the latest state.
            // (Staged edits refresh synchronously; an applied-MST diff may be async,
            // but the current contents are exported either way.)
            if (!_viewingTransform)
            {
                _transformChanges.Clear();
                ComputeStagedChanges();
            }

            if (_validation.Count == 0 && _transformChanges.Count == 0)
            { MstMessage("Nothing to export yet - run Validate and/or stage some changes first.",
                  "Export", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var dlg = new SaveFileDialog
            {
                Title = "Export validation & transform report",
                Filter = "CSV file (*.csv)|*.csv",
                FileName = Path.GetFileNameWithoutExtension(_msiPath) + "_report.csv",
                InitialDirectory = SafeDir(_msiPath),
                OverwritePrompt = false
            };
            if (dlg.ShowDialog() != true) return;
            if (!ConfirmOverwrite(dlg.FileName, "Export")) return;

            try
            {
                var sb = new System.Text.StringBuilder();

                sb.AppendLine("# Validation results");
                sb.AppendLine(CsvRow("Severity", "Code", "Table", "Row", "Column", "Message"));
                if (_validation.Count == 0)
                    sb.AppendLine(CsvRow("(none)", "", "", "", "", ""));
                else
                    foreach (var v in _validation)
                        sb.AppendLine(CsvRow(v.Severity, v.Code, v.Table, v.RowKey, v.Column, v.Message));

                sb.AppendLine();
                sb.AppendLine("# Transform changes");
                sb.AppendLine(CsvRow("Action", "Table", "Row/Key", "Column", "Old -> New"));
                if (_transformChanges.Count == 0)
                    sb.AppendLine(CsvRow("(none)", "", "", "", ""));
                else
                    foreach (var c in _transformChanges)
                        sb.AppendLine(CsvRow(c.Action, c.Table, c.RowKey, c.Column, c.Change));

                // UTF-8 BOM so Excel renders unicode (arrows, accents) correctly.
                File.WriteAllText(dlg.FileName, sb.ToString(), new System.Text.UTF8Encoding(true));
                TxtStatus.Text = $"Exported report to {dlg.FileName} " +
                                 $"({_validation.Count} validation row(s), {_transformChanges.Count} change(s)).";
            }
            catch (Exception ex)
            {
                MstMessage("Could not write the CSV file:\n" + ex.Message, "Export",
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private static string SafeDir(string path)
        {
            try { return Path.GetDirectoryName(path) ?? ""; } catch { return ""; }
        }

        /// <summary>Builds one CSV line with RFC-4180 quoting.</summary>
        private static string CsvRow(params string[] fields)
            => string.Join(",", fields.Select(CsvField));

        private static string CsvField(string? f)
        {
            f ??= "";
            bool needsQuote = f.IndexOfAny(new[] { ',', '"', '\n', '\r' }) >= 0;
            if (needsQuote) f = "\"" + f.Replace("\"", "\"\"") + "\"";
            return f;
        }

        // ── Search across all tables (Create Package-style live search) ──────
        // The search box runs live as the user types: it scans every table's
        // cells, records one hit per matching row, and jumps to / highlights the
        // current one. ◀ ▶ (and Enter / Shift+Enter) walk the hits; at either end
        // a styled "search again?" prompt offers to wrap around. Esc / ✕ clears.
        private List<(string Table, int Row, string Col)> _searchHits = new();
        private int    _searchIndex    = -1;
        private string _lastSearchTerm = "";

        private void TxtSearch_TextChanged(object sender, TextChangedEventArgs e)
        {
            string term = TxtSearch.Text ?? "";

            // Placeholder shows only when empty; ✕ shows only when there is text.
            if (TxtSearchPlaceholder != null)
                TxtSearchPlaceholder.Visibility = term.Length == 0
                    ? Visibility.Visible : Visibility.Collapsed;
            if (BtnClearSearch != null)
                BtnClearSearch.Visibility = term.Length == 0
                    ? Visibility.Collapsed : Visibility.Visible;

            if (term.Trim().Length == 0) { ClearSearchState(); return; }
            RunSearch(term.Trim(), resetIndex: true);
        }

        private void TxtSearch_KeyDown(object sender, System.Windows.Input.KeyEventArgs e)
        {
            if (e.Key == System.Windows.Input.Key.Return ||
                e.Key == System.Windows.Input.Key.Enter)
            {
                if ((System.Windows.Input.Keyboard.Modifiers &
                     System.Windows.Input.ModifierKeys.Shift) != 0)
                    NavigateSearch(-1);
                else
                    NavigateSearch(+1);
                e.Handled = true;
            }
            else if (e.Key == System.Windows.Input.Key.Escape)
            {
                BtnClearSearch_Click(sender, e);
                e.Handled = true;
            }
        }

        private void BtnClearSearch_Click(object sender, RoutedEventArgs e)
        {
            TxtSearch.Clear();      // fires TextChanged → ClearSearchState
            TxtSearch.Focus();
        }

        // ── Core search engine ──────────────────────────────────────────────
        // Scans every table (loading any not yet cached) and records one hit per
        // matching row. The first search of a freshly opened MSI loads all tables;
        // later searches reuse the cache and are instant.
        private void RunSearch(string term, bool resetIndex)
        {
            _lastSearchTerm = term;
            var hits = new List<(string Table, int Row, string Col)>();

            if (_msiTableNames.Count > 0)
            {
                System.Windows.Input.Mouse.OverrideCursor = System.Windows.Input.Cursors.Wait;
                try
                {
                    foreach (var t in _msiTableNames)
                    {
                        if (!_tables.TryGetValue(t, out var st))
                        {
                            st = LoadTable(t);
                            if (st == null) continue;
                            _tables[t] = st;
                        }
                        for (int ri = 0; ri < st.Data.Rows.Count; ri++)
                        {
                            var r = st.Data.Rows[ri];
                            if (r.RowState == DataRowState.Deleted) continue;
                            foreach (DataColumn col in st.Data.Columns)
                                // Cv, not a cast: an empty MSI cell reads back as DBNull.Value,
                                // which is not null, so "?? \"\"" never fired and casting it to
                                // string threw. Every table here has at least one nullable column,
                                // so the first keystroke in the search box hit it.
                                if (Cv(r[col]).IndexOf(term, StringComparison.OrdinalIgnoreCase) >= 0)
                                { hits.Add((t, ri, col.ColumnName)); break; }
                        }
                    }
                }
                finally { System.Windows.Input.Mouse.OverrideCursor = null; }
            }

            _searchHits = hits;
            if (resetIndex) _searchIndex = hits.Count > 0 ? 0 : -1;

            if (hits.Count == 0)
            {
                RestoreLastHit();
                UpdateSearchNavUI();
                TxtStatus.Text = $"\u201C{term}\u201D not found in any table.";
                return;
            }

            var byTable = hits.GroupBy(h => h.Table)
                .Select(g => $"{g.Key} ({g.Count()})").ToList();
            TxtStatus.Text = $"\u201C{term}\u201D: {hits.Count} row(s) in {byTable.Count} table(s) - " +
                             string.Join(", ", byTable.Take(8)) + (byTable.Count > 8 ? ", …" : "");

            if (resetIndex) SelectHit(_searchIndex);
            else UpdateSearchNavUI();
        }

        // Walks to the next/previous hit. At either end, offers a styled
        // "search again?" prompt to wrap around (matching Create Package).
        private void NavigateSearch(int direction)
        {
            if (_searchHits.Count == 0)
            {
                // Enter pressed before a live scan produced hits - run it once.
                string term = (TxtSearch.Text ?? "").Trim();
                if (term.Length > 0) RunSearch(term, resetIndex: true);
                return;
            }

            int newIndex = _searchIndex + direction;
            if (newIndex >= _searchHits.Count || newIndex < 0)
            {
                if (ShowSearchWrapDialog("Search completed. Do you want to search again?"))
                    _searchIndex = direction > 0 ? 0 : _searchHits.Count - 1;
                else
                    return;
            }
            else
            {
                _searchIndex = newIndex;
            }

            SelectHit(_searchIndex);
        }

        private void SelectHit(int idx)
        {
            if (_searchHits.Count == 0) return;
            _searchIndex = ((idx % _searchHits.Count) + _searchHits.Count) % _searchHits.Count;
            var (table, row, colName) = _searchHits[_searchIndex];
            LstTables.SelectedItem = table;
            // Bring the selected table into view in the Tables list (it may be
            // scrolled out of sight), so the highlighted table is visible too.
            LstTables.ScrollIntoView(table);
            if (_tables.TryGetValue(table, out var st) && row < st.Data.DefaultView.Count)
            {
                var item = st.Data.DefaultView[row];
                // Highlight only the matched cell, not the whole row. Selecting the
                // row (or making its cell current under full-row selection) lights up
                // the entire line in the selection colour, which buries the match and
                // looks like the whole line is highlighted. Clear any selection and
                // tint just the one matched cell instead.
                GridRows.UnselectAll();
                var col = GridRows.Columns.FirstOrDefault(cl =>
                    string.Equals(cl.Header as string, colName, StringComparison.OrdinalIgnoreCase));
                if (col != null)
                {
                    GridRows.ScrollIntoView(item, col);
                    Dispatcher.BeginInvoke(new Action(() => HighlightCell(item, col)),
                        System.Windows.Threading.DispatcherPriority.Background);
                }
                else GridRows.ScrollIntoView(item);
            }
            UpdateSearchNavUI();
        }

        // Updates the inline N/M counter inside the box and the ◀ ▶ buttons.
        private void UpdateSearchNavUI()
        {
            int total = _searchHits.Count;
            bool hasMatches = total > 0;

            if (BtnSearchPrev != null) BtnSearchPrev.IsEnabled = hasMatches;
            if (BtnSearchNext != null) BtnSearchNext.IsEnabled = hasMatches;
            if (TxtSearchCount == null) return;

            if (hasMatches)
            {
                TxtSearchCount.Text       = $"{_searchIndex + 1}/{total}";
                TxtSearchCount.Visibility = Visibility.Visible;
                TxtSearchCount.Foreground = TryFindResource("AccentBlueBrush") as System.Windows.Media.Brush
                                            ?? System.Windows.Media.Brushes.SteelBlue;
            }
            else
            {
                TxtSearchCount.Text       = "0/0";
                TxtSearchCount.Visibility = Visibility.Visible;
                TxtSearchCount.Foreground = System.Windows.Media.Brushes.OrangeRed;
            }
        }

        // The current match is highlighted by recoloring just the matched run of
        // text inside its cell's TextBlock (not the whole cell), so a wide column
        // does not look like the entire line is highlighted. We keep a reference to
        // restore the plain bound text when moving to the next match.
        private System.Windows.Controls.TextBlock? _lastHitText;
        private System.Windows.Data.BindingBase? _lastHitBinding;
        private string _lastHitOriginal = "";

        private void ClearSearchState()
        {
            RestoreLastHit();
            _searchHits.Clear(); _searchIndex = -1; _lastSearchTerm = "";
            if (BtnSearchPrev  != null) BtnSearchPrev.IsEnabled   = false;
            if (BtnSearchNext  != null) BtnSearchNext.IsEnabled   = false;
            if (TxtSearchCount != null) TxtSearchCount.Visibility = Visibility.Collapsed;
            UpdateEditCount();
        }

        // Styled "search again?" prompt, matching the Create Package dialog.
        private bool ShowSearchWrapDialog(string message)
        {
            bool result = false;
            var win = BuildNewDialog("Search");
            win.Width = 360; win.MaxWidth = 360;
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, "Search");
            int r = 0;
            NdAddRow(cg, r++, "Status", message, lblFg, boxBg, boxBdr, valFg, false);
            NdAddSpacer(cg, r++);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var rowIcon = NdDecisionIcon();
            Grid.SetRow(rowIcon, r); Grid.SetColumn(rowIcon, 0);
            cg.Children.Add(rowIcon);
            var btns = NdMakeButtons(sec,
                ("✔ Yes", () => { result = true;  win.Close(); }),
                ("✕ No",  () => { result = false; win.Close(); })
            );
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1);
            cg.Children.Add(btns);
            win.ShowDialog();
            return result;
        }

        // Highlights only the matched substring inside the cell's TextBlock by
        // splitting its text into runs and tinting the matched run. This mirrors
        // the Create Package script search (highlight the found text, not the whole
        // line). On virtualization recycle the binding re-pulls the plain text, so
        // stale highlights self-clear; we also restore explicitly when navigating.
        private void HighlightCell(object item, DataGridColumn col)
        {
            try
            {
                RestoreLastHit();
                if (string.IsNullOrEmpty(_lastSearchTerm)) return;
                if (GridRows.ItemContainerGenerator.ContainerFromItem(item) is not DataGridRow row) return;
                var presenter = FindChild<System.Windows.Controls.Primitives.DataGridCellsPresenter>(row);
                if (presenter?.ItemContainerGenerator.ContainerFromIndex(col.DisplayIndex) is not DataGridCell cell) return;
                var tb = FindChild<System.Windows.Controls.TextBlock>(cell);
                if (tb == null) return;

                string text = tb.Text ?? "";
                int i = text.IndexOf(_lastSearchTerm, StringComparison.OrdinalIgnoreCase);
                if (i < 0) return;

                _lastHitText = tb;
                _lastHitOriginal = text;

                int end = i + _lastSearchTerm.Length;
                tb.Inlines.Clear();
                if (i > 0) tb.Inlines.Add(new System.Windows.Documents.Run(text.Substring(0, i)));
                tb.Inlines.Add(new System.Windows.Documents.Run(text.Substring(i, _lastSearchTerm.Length))
                {
                    Background = new System.Windows.Media.SolidColorBrush(
                        System.Windows.Media.Color.FromArgb(210, 255, 165, 0)),
                    Foreground = System.Windows.Media.Brushes.Black
                });
                if (end < text.Length) tb.Inlines.Add(new System.Windows.Documents.Run(text.Substring(end)));
            }
            catch { }
        }

        // Restores the last-highlighted cell's TextBlock to its plain bound text.
        private void RestoreLastHit()
        {
            try
            {
                if (_lastHitText != null)
                {
                    _lastHitText.Inlines.Clear();
                    _lastHitText.Text = _lastHitOriginal;
                    // Re-pull from the column's binding so the cell tracks data again.
                    _lastHitText.GetBindingExpression(System.Windows.Controls.TextBlock.TextProperty)?.UpdateTarget();
                }
            }
            catch { }
            _lastHitText = null;
            _lastHitOriginal = "";
        }

        private static T? FindChild<T>(DependencyObject parent) where T : DependencyObject
        {
            for (int i = 0; i < System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent); i++)
            {
                var ch = System.Windows.Media.VisualTreeHelper.GetChild(parent, i);
                if (ch is T t) return t;
                var deep = FindChild<T>(ch);
                if (deep != null) return deep;
            }
            return null;
        }

        private void BtnRemoveDesktop_Click(object sender, RoutedEventArgs e)
        {
            // Block incomplete manually-added rows before staging more edits.
            if (!CommitGridAndValidate()) return;

            if (!_tables.TryGetValue("Shortcut", out var st))
            {
                var s0 = LoadTable("Shortcut");
                if (s0 == null)
                {
                    TxtStatus.Text = "This MSI has no Shortcut table.";
                    MstMessage("This MSI has no Shortcut table, so there are no desktop shortcuts to remove.",
                        "Remove Desktop Shortcuts", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                _tables["Shortcut"] = st = s0;
            }
            int n = 0;
            foreach (DataRow r in st.Data.Rows.Cast<DataRow>().ToList())
            {
                if (r.RowState == DataRowState.Deleted) continue;
                // Cv, not a cast: Directory_ is nullable in the Shortcut table, and DBNull.Value
                // is not null, so the same InvalidCastException was waiting here.
                string dir = Cv(r["Directory_"]);
                if (dir.IndexOf("Desktop", StringComparison.OrdinalIgnoreCase) >= 0) { r.Delete(); n++; }
            }

            if (n == 0)
            {
                TxtStatus.Text = "No desktop shortcut rows found.";
                MstMessage("No desktop shortcuts were found in this MSI - nothing to remove.",
                    "Remove Desktop Shortcuts", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            LstTables.SelectedItem = "Shortcut";
            DeferRefreshVisuals();
            TxtStatus.Text = $"{n} desktop shortcut row(s) staged for deletion - included in the next Create MST / Save.";
            MstMessage(
                $"{n} desktop shortcut row(s) were removed (staged for deletion).\n\n" +
                "The change is included in the next Create MST or Save.",
                "Remove Desktop Shortcuts", MessageBoxButton.OK, MessageBoxImage.Information);
        }

        // ── Apply Properties (from EditMSI.json) ──────────────────────────
        // Stages every configured property whose name is not already present in
        // the Property table, using its Default value. Existing rows are left
        // untouched - values are never overwritten. Staged adds are written by
        // the next Create MST / Save, exactly like a manual property Add.
        private void BtnApplyProps_Click(object sender, RoutedEventArgs e)
        {
            if (string.IsNullOrWhiteSpace(_msiPath))
            {
                MstMessage("Open an MSI first.", "Apply Properties",
                    MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            // Block incomplete manually-added rows before staging more edits.
            if (!CommitGridAndValidate()) return;

            // Re-read the configured properties so the latest EditMSI.json is used.
            LoadPropertyConfig();
            if (_propOptions.Count == 0)
            {
                TxtStatus.Text = "No properties are configured in EditMSI.json.";
                MstMessage("EditMSI.json has no Properties to apply.",
                    "Apply Properties", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            // Ensure the Property table is loaded into the cache.
            if (!_tables.TryGetValue("Property", out var st))
            {
                var s0 = LoadTable("Property");
                if (s0 == null)
                {
                    TxtStatus.Text = "This MSI has no Property table.";
                    MstMessage("This MSI has no Property table to apply properties to.",
                        "Apply Properties", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                _tables["Property"] = st = s0;
            }

            // Resolve the Property/Value column names (handles unusual casing).
            string nameCol = st.Data.Columns.Contains("Property") ? "Property"
                            : (st.Data.Columns.Count > 0 ? st.Data.Columns[0].ColumnName : "");
            string valCol  = st.Data.Columns.Contains("Value") ? "Value"
                            : (st.Data.Columns.Count > 1 ? st.Data.Columns[1].ColumnName : "");
            if (nameCol.Length == 0 || valCol.Length == 0)
            {
                MstMessage("Could not locate the Property and Value columns.",
                    "Apply Properties", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            // For each configured property: add it when the name is missing, or
            // restage its value when the name exists but the value differs from
            // EditMSI.json. Matching values are left alone (no transform change).
            int added = 0, updated = 0, same = 0, blank = 0;
            DataRow? lastTouched = null;
            foreach (var kv in _propOptions)
            {
                string prop = (kv.Key ?? "").Trim();
                string def  = (kv.Value.Default ?? "").Trim();
                if (prop.Length == 0) continue;
                if (def.Length == 0) { blank++; continue; }   // no default - nothing to apply

                DataRow? existing = st.Data.Rows.Cast<DataRow>().FirstOrDefault(r =>
                    r.RowState != DataRowState.Deleted && !st.MarkedDelete.Contains(r) &&
                    string.Equals((r[nameCol] ?? "").ToString(), prop, StringComparison.OrdinalIgnoreCase));

                if (existing != null)
                {
                    // Same name: only restage when the value differs.
                    if (string.Equals((existing[valCol] ?? "").ToString(), def, StringComparison.Ordinal))
                    {
                        same++;
                        continue;
                    }
                    existing[valCol] = def;
                    // If the new value matches the row's original there is no real
                    // diff for the transform to record - revert so the grid, the
                    // count and the generated transform all agree.
                    if (existing.RowState == DataRowState.Modified && !RowHasRealEdit(st, existing))
                    {
                        existing.RejectChanges();
                        same++;
                        continue;
                    }
                    lastTouched = existing;
                    updated++;
                    continue;
                }

                var row = st.Data.NewRow();
                foreach (DataColumn c in st.Data.Columns) row[c] = "";
                row[nameCol] = prop;
                row[valCol]  = def;
                st.Data.Rows.Add(row);
                lastTouched = row;
                added++;
            }

            if (added == 0 && updated == 0)
            {
                TxtStatus.Text = same > 0
                    ? $"All {same} configured propert(ies) already match EditMSI.json - nothing to change."
                    : "No properties from EditMSI.json were applicable.";
                MstMessage(
                    same > 0
                        ? $"All {same} configured propert(ies) already match EditMSI.json, so nothing was changed."
                        : "No properties from EditMSI.json were applicable.",
                    "Apply Properties", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            // Surface the change on the Property table and refresh row tints.
            if (!string.Equals(_currentTable, "Property", StringComparison.OrdinalIgnoreCase))
            {
                _suppressTableValidation = true;
                LstTables.SelectedItem = "Property";
                _suppressTableValidation = false;
            }
            Dispatcher.BeginInvoke(new Action(() =>
            {
                if (lastTouched != null && GridRows.ItemsSource is DataView dv)
                    foreach (DataRowView drv in dv)
                        if (ReferenceEquals(drv.Row, lastTouched))
                        {
                            GridRows.SelectedItem = drv;
                            GridRows.ScrollIntoView(drv);
                            break;
                        }
                DeferRefreshVisuals();
            }), System.Windows.Threading.DispatcherPriority.Background);

            TxtStatus.Text = $"Apply Properties: {added} added, {updated} updated, {same} unchanged" +
                             (blank > 0 ? $", {blank} skipped (no default)" : "") +
                             " - included in the next Create MST / Save.";
            MstMessage(
                $"{added} added, {updated} updated from EditMSI.json (staged)." +
                (same > 0 ? $"\n{same} already matched." : "") +
                (blank > 0 ? $"\n{blank} skipped (no default value)." : "") +
                "\n\nThe change is included in the next Create MST or Save.",
                "Apply Properties", MessageBoxButton.OK, MessageBoxImage.Information);
        }

        // ── Settings: edit EditMSI.json (the Apply Properties list) ────────
        // Modal editor over EditMSI.json. Loads the Properties section (each is a name, a
        // default value, and a comma-separated list of value options), lets the user add /
        // edit / delete entries, and writes the changes back with any other keys preserved
        // via a JsonNode round-trip. Mirrors the Auto Package / Validate Source dialogs.
        private void BtnMsiSettings_Click(object sender, RoutedEventArgs e) => OpenEditMsiSettings();

        private void OpenEditMsiSettings()
        {
            // Same resolution as LoadPropertyConfig: Templates folder first, Resources fallback.
            string pfPath  = @"C:\Program Files\Smekal\SwiftPack Studio\Templates\EditMSI.json";
            string resPath = Path.Combine(AppContext.BaseDirectory, "Resources", "EditMSI.json");
            string cfgPath = File.Exists(pfPath) ? pfPath : (File.Exists(resPath) ? resPath : pfPath);

            System.Text.Json.Nodes.JsonObject root;
            try
            {
                var docOpts = new System.Text.Json.JsonDocumentOptions { AllowTrailingCommas = true, CommentHandling = System.Text.Json.JsonCommentHandling.Skip };
                root = (File.Exists(cfgPath)
                    ? System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(cfgPath), null, docOpts)?.AsObject()
                    : null) ?? new System.Text.Json.Nodes.JsonObject();
            }
            catch
            {
                MstMessage("EditMSI.json is not valid JSON. Fix the file, then try again.\n\n" + cfgPath,
                    "Settings", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            var winBg      = Application.Current.TryFindResource("WindowBgBrush")      as Brush ?? Brushes.White;
            var borderClr  = Application.Current.TryFindResource("BorderMainBrush")    as Brush ?? Brushes.LightGray;
            var boxBg      = Application.Current.TryFindResource("InputBgBrush")       as Brush ?? new SolidColorBrush(Color.FromRgb(0xF0, 0xF1, 0xF8));
            var boxBdr     = Application.Current.TryFindResource("BorderMainBrush")    as Brush ?? new SolidColorBrush(Color.FromRgb(0xDD, 0xDF, 0xEA));
            var lblFg      = Application.Current.TryFindResource("TextSecondaryBrush") as Brush ?? Brushes.Gray;
            var valFg      = Application.Current.TryFindResource("TextPrimaryBrush")   as Brush ?? Brushes.Black;
            var sec        = Application.Current.TryFindResource("SecondaryButtonStyle") as Style;
            var titleBarBg = new SolidColorBrush(Color.FromRgb(0x53, 0x56, 0x63));

            var cwin = new Window
            {
                Width = 600, SizeToContent = SizeToContent.Height,
                MaxHeight = Math.Max(480, SystemParameters.WorkArea.Height - 48),
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = Window.GetWindow(this), ResizeMode = ResizeMode.NoResize,
                WindowStyle = WindowStyle.None, AllowsTransparency = true,
                Background = Brushes.Transparent,
                FontFamily = new FontFamily("Segoe UI"), ShowInTaskbar = false
            };
            var outer = new Border { Background = winBg, BorderBrush = borderClr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(10), Effect = new System.Windows.Media.Effects.DropShadowEffect { BlurRadius = 16, ShadowDepth = 2, Opacity = 0.18, Color = Colors.Black } };
            cwin.Content = outer;
            var og = new Grid();
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            og.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            outer.Child = og;

            // Title bar
            var tb = new Border { Background = titleBarBg, CornerRadius = new CornerRadius(10, 10, 0, 0), Padding = new Thickness(16, 6, 12, 6) };
            tb.MouseLeftButtonDown += (_, _) => cwin.DragMove();
            Grid.SetRow(tb, 0);
            var tg = new Grid();
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            var ti = new TextBlock { Text = "⚙", FontSize = 13, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
            var tt = new TextBlock { Text = "Edit MSI - Settings", FontSize = 13, FontWeight = FontWeights.SemiBold, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center };
            var tcl = new Button { Content = "✕", FontSize = 11, Foreground = new SolidColorBrush(Color.FromArgb(0xCC, 0xFF, 0xFF, 0xFF)), Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = Cursors.Hand, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(6, 2, 6, 2) };
            tcl.Click += (_, _) => cwin.Close();
            Grid.SetColumn(ti, 0); Grid.SetColumn(tt, 1); Grid.SetColumn(tcl, 2);
            tg.Children.Add(ti); tg.Children.Add(tt); tg.Children.Add(tcl);
            tb.Child = tg; og.Children.Add(tb);

            var form = new StackPanel { Margin = new Thickness(16, 12, 16, 8) };
            var scroll = new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Content = form };
            Grid.SetRow(scroll, 1); og.Children.Add(scroll);

            string ReadStr(System.Text.Json.Nodes.JsonNode? n)
            {
                if (n == null) return "";
                try { return n.GetValue<string>(); } catch { }
                try { return n.ToJsonString().Trim('"'); } catch { }
                return "";
            }

            form.Children.Add(new TextBlock { Text = "Properties", FontSize = 12, FontWeight = FontWeights.Bold, Foreground = valFg, Margin = new Thickness(0, 0, 0, 2) });
            form.Children.Add(new TextBlock { Text = "The MSI properties offered by Apply Properties. Options is a comma-separated list of allowed values (add a trailing comma to include a blank option).", FontSize = 10.5, Foreground = lblFg, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 8) });

            // Column header
            var hdr = new Grid { Margin = new Thickness(0, 0, 0, 4) };
            hdr.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(150) });
            hdr.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(110) });
            hdr.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            hdr.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(32) });
            TextBlock Hd(string t) => new TextBlock { Text = t, FontSize = 10.5, FontWeight = FontWeights.SemiBold, Foreground = lblFg, Margin = new Thickness(2, 0, 0, 0) };
            var h0 = Hd("Name"); var h1 = Hd("Default"); var h2 = Hd("Options (comma-separated)");
            Grid.SetColumn(h0, 0); Grid.SetColumn(h1, 1); Grid.SetColumn(h2, 2);
            hdr.Children.Add(h0); hdr.Children.Add(h1); hdr.Children.Add(h2);
            form.Children.Add(hdr);

            var rowsPanel = new StackPanel();
            form.Children.Add(rowsPanel);
            var rows = new System.Collections.Generic.List<(TextBox name, TextBox def, TextBox opts)>();

            Border MkBox(TextBox tx)
                => new Border { Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(8, 2, 6, 2), Margin = new Thickness(0, 0, 6, 0), Child = tx };

            void AddPropRow(string name, string def, string opts)
            {
                var rg = new Grid { Margin = new Thickness(0, 0, 0, 4) };
                rg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(150) });
                rg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(110) });
                rg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                rg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                var nTx = new TextBox { Text = name, FontSize = 11, MinHeight = 26, BorderThickness = new Thickness(0), Background = Brushes.Transparent, Foreground = valFg, VerticalContentAlignment = VerticalAlignment.Center };
                var dTx = new TextBox { Text = def,  FontSize = 11, MinHeight = 26, BorderThickness = new Thickness(0), Background = Brushes.Transparent, Foreground = valFg, VerticalContentAlignment = VerticalAlignment.Center };
                var oTx = new TextBox { Text = opts, FontSize = 11, MinHeight = 26, BorderThickness = new Thickness(0), Background = Brushes.Transparent, Foreground = valFg, VerticalContentAlignment = VerticalAlignment.Center };
                var nWrap = MkBox(nTx); var dWrap = MkBox(dTx); var oWrap = MkBox(oTx);
                var del = new Button { Content = "✕", FontSize = 11, Width = 26, Height = 26, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Foreground = lblFg, Cursor = Cursors.Hand, ToolTip = "Remove this property" };
                var entry = (nTx, dTx, oTx);
                del.Click += (_, _) => { rowsPanel.Children.Remove(rg); rows.Remove(entry); };
                Grid.SetColumn(nWrap, 0); Grid.SetColumn(dWrap, 1); Grid.SetColumn(oWrap, 2); Grid.SetColumn(del, 3);
                rg.Children.Add(nWrap); rg.Children.Add(dWrap); rg.Children.Add(oWrap); rg.Children.Add(del);
                rowsPanel.Children.Add(rg);
                rows.Add(entry);
            }

            if (root["Properties"] is System.Text.Json.Nodes.JsonObject propsObj)
                foreach (var kv in propsObj.OrderBy(kv => kv.Key, StringComparer.OrdinalIgnoreCase))
                {
                    var o = kv.Value as System.Text.Json.Nodes.JsonObject;
                    string def = ReadStr(o?["Default"]);
                    var optList = new System.Collections.Generic.List<string>();
                    if (o?["Options"] is System.Text.Json.Nodes.JsonArray oa)
                        foreach (var it in oa) optList.Add(ReadStr(it));
                    AddPropRow(kv.Key, def, string.Join(", ", optList));
                }

            var addBtn = new Button { Content = "＋  Add Property", Style = sec, Height = 26, Padding = new Thickness(10, 0, 10, 0), HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 2, 0, 2) };
            addBtn.Click += (_, _) => AddPropRow("", "", "");
            form.Children.Add(addBtn);

            // Button bar
            var btnBar = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(16, 4, 16, 14) };
            Grid.SetRow(btnBar, 2);
            var bCancel = new Button { Content = "✕  Cancel", Style = sec, Height = 30, Padding = new Thickness(12, 0, 12, 0), Margin = new Thickness(0, 0, 8, 0), VerticalAlignment = VerticalAlignment.Center };
            bCancel.Click += (_, _) => cwin.Close();
            var bSave = new Button { Content = "💾  Save", Style = sec, Height = 30, Padding = new Thickness(12, 0, 12, 0), VerticalAlignment = VerticalAlignment.Center };
            NdApplyPrimaryLook(bSave);
            bSave.Click += (_, _) =>
            {
                try
                {
                    // Rebuild the Properties object from the rows (skip rows with no name).
                    var outProps = new System.Text.Json.Nodes.JsonObject();
                    foreach (var (nTx, dTx, oTx) in rows)
                    {
                        string nm = nTx.Text.Trim();
                        if (nm.Length == 0) continue;
                        var optsArr = new System.Text.Json.Nodes.JsonArray();
                        if (oTx.Text.Trim().Length > 0)
                            foreach (var part in oTx.Text.Split(','))
                                optsArr.Add(part.Trim());
                        outProps[nm] = new System.Text.Json.Nodes.JsonObject
                        {
                            ["Default"] = dTx.Text.Trim(),
                            ["Options"] = optsArr,
                        };
                    }
                    root["Properties"] = outProps;

                    // Serialise with a Utf8JsonWriter (JsonNode.ToJsonString with a bare
                    // JsonSerializerOptions throws in .NET 8 - the node write path needs no
                    // resolver). Build the bytes in memory first so a failure cannot corrupt
                    // the file.
                    byte[] jsonBytes;
                    using (var ms = new MemoryStream())
                    {
                        using (var jw = new System.Text.Json.Utf8JsonWriter(ms, new System.Text.Json.JsonWriterOptions { Indented = true }))
                            root.WriteTo(jw);
                        jsonBytes = ms.ToArray();
                    }
                    File.WriteAllBytes(cfgPath, jsonBytes);

                    // Refresh the in-memory config so the change reaches Apply Properties without
                    // a restart.
                    LoadPropertyConfig();

                    cwin.Close();
                    MstMessage("Settings written to EditMSI.json.\nThe updated properties are used by Apply Properties.",
                        "Settings", MessageBoxButton.OK, MessageBoxImage.Information);
                }
                catch (Exception ex)
                {
                    MstMessage("Save failed:\n" + ex.Message + "\n\n" + cfgPath,
                        "Settings", MessageBoxButton.OK, MessageBoxImage.Warning);
                }
            };
            btnBar.Children.Add(bCancel); btnBar.Children.Add(bSave);
            og.Children.Add(btnBar);

            cwin.ShowDialog();
        }

        private void BtnSaveMsi_Click(object sender, RoutedEventArgs e)
        {
            if (string.IsNullOrWhiteSpace(_msiPath)) return;
            _saveSucceeded = false;

            // Don't let an incomplete manually-added row reach the database.
            if (!CommitGridAndValidate()) return;

            // MSI + applied MST → Save writes the transform (.mst) standalone against
            // the original MSI (the applied transform plus any edits you made on top).
            if (_viewingTransform) { SaveAsMst(); return; }

            // Plain MSI → Save writes the edits back into the open .msi (in place).
            if (_changes.Count == 0 && PendingEditCount() == 0 && _summaryEdits.Count == 0)
            { MstMessage("No changes to save.", "Save", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            // Save directly back into the open MSI - no Save As dialog, no new file.
            // The edits are applied to a temp copy first, then the temp replaces the
            // open file, so a failed save can never corrupt it.
            string tempOut = Path.Combine(Path.GetTempPath(),
                "SwiftPackSave_" + Guid.NewGuid().ToString("N") + ".msi");
            dynamic? inst = null, db = null;
            bool saved = false;
            Mouse.OverrideCursor = Cursors.Wait;     // cabbing a large file is not instant
            try
            {
                File.Copy(_msiPath, tempOut, true);
                File.SetAttributes(tempOut, File.GetAttributes(tempOut) & ~FileAttributes.ReadOnly);
                inst = NewInstaller();
                db   = inst.OpenDatabase(tempOut, 1);
                // Staged property changes are already in the Property grid and are
                // applied by ApplyTableEdits, so they are not replayed separately.
                ApplyTableEdits(db);
                EmbedAddedStreams(db, inst);   // icon and binary streams, row and bytes together
                EmbedAddedFiles(db, inst);   // bake added-file bytes into a new cabinet
                db.Commit();
                Release(db); db = null; Release(inst); inst = null;
                GC.Collect(); GC.WaitForPendingFinalizers();   // release the COM lock on tempOut

                // Overwrite the open MSI with the edited copy.
                File.SetAttributes(_msiPath, File.GetAttributes(_msiPath) & ~FileAttributes.ReadOnly);
                File.Copy(tempOut, _msiPath, true);
                saved = true;
            }
            catch (Exception ex)
            { Mouse.OverrideCursor = null; MstMessage("Save failed:\n\n" + ex.Message, "Save", MessageBoxButton.OK, MessageBoxImage.Error); }
            finally
            {
                Mouse.OverrideCursor = null;
                Release(db); Release(inst); GC.Collect(); GC.WaitForPendingFinalizers();
                try { if (File.Exists(tempOut)) File.Delete(tempOut); } catch { }
            }

            if (saved)
            {
                // The COM database is released and the file is unlocked - apply any
                // staged Summary Information edits to the saved MSI now.
                WriteSummaryToFile(_msiPath);
                _saveSucceeded = true;
                // The rows are in the file now, so nothing is staged any more. Without this the
                // next Browse still found pending edits and asked to save them again.
                AcceptSavedEdits();
                _savedEditMark = EditStateMark();
                TxtStatus.Text = "Saved: " + _msiPath;
                MstMessage("Saved:\n\n" + _msiPath, "Save",
                    MessageBoxButton.OK, MessageBoxImage.Information);
            }
        }

        /// <summary>
        /// Save in transformed view: writes a .mst that captures the current state
        /// (the applied transform plus any edits made on top), diffed against the
        /// ORIGINAL MSI — so the resulting transform is standalone against it.
        /// </summary>
        private void SaveAsMst()
        {
            if (string.IsNullOrWhiteSpace(_transformOriginalMsi) || !File.Exists(_transformOriginalMsi))
            { MstMessage("The original MSI is no longer available.", "Save",
                  MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            // Save writes a transform here, and a transform carries no _Streams, so the same rule
            // applies as in Create MST: a cabinet embedded in the package cannot travel in one.
            int embedded = PendingEmbeddedFileCount();
            if (embedded > 0)
            {
                MstMessage(
                    (embedded == 1 ? "A file was added" : embedded + " files were added")
                  + " with its bytes inside the package, and Save writes a transform while a "
                  + "transform is open. A transform cannot carry an embedded cabinet.\n\nRemove "
                  + "them and add them again choosing a cabinet or uncompressed files beside the "
                  + "package, which a transform can point at.",
                    "Save", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            // Save writes back to the transform that is already open, exactly as Save on a plain
            // MSI writes back into that MSI. Asking for a filename and then asking again whether to
            // replace it is Save As behaviour, and there is a separate Create MST for that.
            //
            // The dialog is only used when there is no transform to write back to: the view was
            // reached without an applied .mst, or the file it came from has since been moved or its
            // folder removed, in which case saving silently would fail.
            string mstPath;
            bool haveTarget = _appliedMstPath.Length > 0
                              && Directory.Exists(Path.GetDirectoryName(_appliedMstPath) ?? "");
            if (haveTarget)
            {
                mstPath = _appliedMstPath;
            }
            else
            {
                var dlg = new SaveFileDialog
                {
                    Title    = "Save transform (.mst) as",
                    Filter   = "Transform (*.mst)|*.mst",
                    FileName = _appliedMstPath.Length > 0
                                ? Path.GetFileName(_appliedMstPath)
                                : Path.GetFileNameWithoutExtension(_transformOriginalMsi) + ".mst",
                    InitialDirectory = SafeDir(_appliedMstPath.Length > 0 ? _appliedMstPath : _transformOriginalMsi),
                    OverwritePrompt = false
                };
                if (dlg.ShowDialog() != true) return;
                mstPath = dlg.FileName;
                if (!ConfirmOverwrite(mstPath, "Save")) return;
            }

            // Work on a temp copy of the transformed MSI so any edits made on top of
            // the applied transform are baked in before we diff against the original.
            string tempCopy = Path.Combine(Path.GetTempPath(),
                "SwiftPackMst_" + Guid.NewGuid().ToString("N") + ".msi");

            dynamic? inst = null, dbRef = null, dbMod = null;
            Mouse.OverrideCursor = Cursors.Wait;     // cabbing a large file is not instant
            try
            {
                File.Copy(_msiPath, tempCopy, true);
                File.SetAttributes(tempCopy, File.GetAttributes(tempCopy) & ~FileAttributes.ReadOnly);

                inst  = NewInstaller();
                dbMod = inst.OpenDatabase(tempCopy, 1 /* transact */);
                ApplyTableEdits(dbMod);        // bake in edits made on top of the transform
                EmbedAddedStreams(dbMod, inst);
                EmbedAddedFiles(dbMod, inst, false);   // cab or loose files beside the package
                dbMod.Commit();

                dbRef = inst.OpenDatabase(_transformOriginalMsi, 0 /* original = diff base */);

                if (File.Exists(mstPath)) File.Delete(mstPath);
                bool different = (bool)dbMod.GenerateTransform(dbRef, mstPath);
                if (!different)
                {
                    TxtStatus.Text = "No differences from the original MSI - nothing to save as a transform.";
                    MstMessage("The current state matches the original MSI, so there is nothing to save as a transform.",
                        "Save", MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
                dbMod.CreateTransformSummaryInfo(dbRef, mstPath, 0, 0);

                // Adopt the path, so that if this save did go through the dialog, every later Save
                // writes straight back here without asking again.
                _appliedMstPath = mstPath;

                _saveSucceeded = true;
                // The edits stay staged - the next Save regenerates the whole transform from them -
                // so the state is marked as saved instead of being cleared.
                _savedEditMark = EditStateMark();
                TxtStatus.Text = "Transform saved: " + mstPath;
                MstMessage("Transform saved:\n\n" + mstPath, "Save",
                    MessageBoxButton.OK, MessageBoxImage.Information);
            }
            catch (Exception ex)
            { Mouse.OverrideCursor = null;
              MstMessage("Saving the transform failed:\n\n" + ex.Message, "Save",
                  MessageBoxButton.OK, MessageBoxImage.Error); }
            finally
            {
                Mouse.OverrideCursor = null;
                Release(dbMod); Release(dbRef); Release(inst);
                GC.Collect(); GC.WaitForPendingFinalizers();
                try { if (File.Exists(tempCopy)) File.Delete(tempCopy); } catch { }
            }
        }

        private void BtnSearchPrev_Click(object sender, RoutedEventArgs e) => NavigateSearch(-1);
        private void BtnSearchNext_Click(object sender, RoutedEventArgs e) => NavigateSearch(+1);

        // ── Form view (Master Packager-style categorized editor) ────────────
        // A friendly front end over the same staged-edit engine the grid uses:
        // every field reads from, and writes into, the cached Property/Directory
        // DataTables, so Create MST / Apply MST / Validate work unchanged. The raw
        // grid lives on under the "Tables" toggle.
        private bool   _formMode      = false;   // true = Form view, false = Tables view
        private bool   _editingUnlocked = false; // mirrors SetEditingLocked, for view toggle
        private bool   _loadingForm   = false;   // suppress write-back while populating
        private string _placeholderTable = "";   // table the current placeholder maps to

        private void BtnFormView_Click(object sender, RoutedEventArgs e)   => SetViewMode(true);
        private void BtnTablesView_Click(object sender, RoutedEventArgs e) => SetViewMode(false);

        private void SetViewMode(bool form)
        {
            _formMode = form;
            if (FormViewRoot   != null) FormViewRoot.Visibility   = form ? Visibility.Visible : Visibility.Collapsed;
            if (TablesViewRoot != null) TablesViewRoot.Visibility = form ? Visibility.Collapsed : Visibility.Visible;

            // Active state via Tag so the SegToggleStyle triggers (DynamicResource)
            // handle the colours - and keep working when the theme changes.
            if (BtnFormView   != null) BtnFormView.Tag   = form ? "Active" : "";
            if (BtnTablesView != null) BtnTablesView.Tag = form ? "" : "Active";

            // The all-tables search and the Add Row / Delete Row buttons apply only
            // to the Tables grid, so hide them entirely in Form mode.
            var tablesOnly = form ? Visibility.Collapsed : Visibility.Visible;
            if (SearchBox     != null) SearchBox.Visibility     = tablesOnly;
            if (BtnSearchPrev != null) BtnSearchPrev.Visibility = tablesOnly;
            if (BtnSearchNext != null) BtnSearchNext.Visibility = tablesOnly;
            if (BtnAddRow     != null) BtnAddRow.Visibility     = tablesOnly;
            if (BtnDeleteRow  != null) BtnDeleteRow.Visibility  = tablesOnly;
            if (BtnCopyRow    != null) BtnCopyRow.Visibility    = tablesOnly;
            if (BtnPasteRow   != null) BtnPasteRow.Visibility   = tablesOnly;

            // The Tables-only Add Row / Delete Row buttons don't apply in Form mode
            // (the Form views have their own), so disable them there.
            if (BtnAddRow != null)
                BtnAddRow.IsEnabled    = _editingUnlocked && !form && !string.IsNullOrWhiteSpace(_currentTable);
            if (BtnDeleteRow != null)
                BtnDeleteRow.IsEnabled = _editingUnlocked && !form && !string.IsNullOrWhiteSpace(_currentTable);

            if (form)
            {
                if (LstCategories != null && LstCategories.SelectedItem == null && LstCategories.Items.Count > 0)
                    LstCategories.SelectedIndex = 0;     // default to Product information
                else
                    ShowCategory();
            }

            UpdateSearchEnabled();
        }

        // Search runs against the Tables grid, so it is available only in Tables
        // mode with an MSI loaded; in Form mode the box and arrows are disabled.
        private void UpdateSearchEnabled()
        {
            bool on = !_formMode && !string.IsNullOrWhiteSpace(_msiPath);
            if (SearchBox != null) SearchBox.IsEnabled = on;
            if (TxtSearch != null) TxtSearch.IsEnabled = on;
            if (!on)
            {
                if (BtnSearchPrev != null) BtnSearchPrev.IsEnabled = false;
                if (BtnSearchNext != null) BtnSearchNext.IsEnabled = false;
            }
        }

        private void LstCategories_SelectionChanged(object sender, SelectionChangedEventArgs e) => ShowCategory();

        // Switches the content area to the selected category. Only Product
        // information is a real form so far; the rest show a friendly pointer to
        // the Tables view until their own views are built in later phases.
        private string _formGridTable = "";
        private DataView? _gridView;     // dedicated view bound to FormGrid (filterable)
        private DataView? _propsView;    // dedicated view for the friendly Properties list

        // Clear every per-panel search box (text, matches, counter) so switching
        // category never carries a stale search word into another panel.
        private void ClearAllPanelSearches()
        {
            foreach (var tb in new[] { PropSearch, FileSearch, RegSearch, FeatSearch, CaSearch, SeqSearch })
                if (tb != null && tb.Text.Length > 0) tb.Text = "";
        }

        /// <summary>
        /// The plain name of a category, for the messages that mention it by name. The items carry
        /// a vector icon beside their text now rather than a glyph inside it, so the label is the
        /// text of the panel's TextBlock; the old "glyph  Label" form is still read in case an item
        /// is ever declared that way again.
        /// </summary>
        private static string CategoryLabel(ListBoxItem item)
        {
            if (item.Content is Panel panel)
                foreach (var child in panel.Children)
                    if (child is TextBlock tb && tb.Text.Trim().Length > 0)
                        return tb.Text.Trim();

            string content = item.Content as string ?? "";
            int sep = content.IndexOf("  ", StringComparison.Ordinal);   // "glyph  Label"
            string label = (sep >= 0 ? content.Substring(sep + 2) : content).Trim();
            return label.Length > 0 ? label : "This";
        }

        // ── Multi-table categories ─────────────────────────────────────────
        // Several of the views a packaging tool is expected to have are not one table but a
        // family of them: Services is ServiceInstall plus ServiceControl, System Search is
        // AppSearch plus five locator tables. Each of these shows a strip of its tables over the
        // same editable grid the single-table categories use, so Add Row, Delete Row, the filter
        // and the foreign-key dropdowns all come for free.
        private static readonly Dictionary<string, (string[] Tables, string Note)> CategoryTableGroups =
            new(StringComparer.OrdinalIgnoreCase)
        {
            // The two that are not standard Windows Installer at all. Both are listed because the
            // reference tool has them, and both say plainly what they can and cannot be here.
            ["mergemod"] = (new[] { "ModuleSignature", "ModuleComponents", "ModuleDependency",
                                    "ModuleExclusion", "ModuleIgnoreTable", "ModuleSubstitution" },
                "These tables live in a merge module (.msm), not in the MSI built from one. Merging "
              + "happens at build time, so a finished package keeps the merged rows but no record "
              + "of the module they came from."),
        };

        /// <summary>
        /// Shows a table-group category: a strip of its tables over the shared grid. Tables the
        /// package does not have are still listed, faintly, and open as an empty editable grid
        /// when a schema exists for them.
        /// </summary>
        private void ShowTableGroup(string tag, string label)
        {
            if (!CategoryTableGroups.TryGetValue(tag, out var group)) return;

            if (FormGroupStrip != null)
            {
                FormGroupStrip.Children.Clear();
                foreach (string t in group.Tables)
                {
                    var cached = _tables.TryGetValue(t, out var got) ? got : EnsureTableCached(t);
                    int rows = cached?.Data.Rows.Cast<DataRow>().Count(r => r.RowState != DataRowState.Deleted) ?? -1;
                    bool known = cached != null || MsiTableSchemas.ContainsKey(t);

                    var btn = new Button
                    {
                        Content = rows >= 0 ? $"{t}  {rows}" : t,
                        Tag = t, FontSize = 11, Height = 24, Cursor = Cursors.Hand,
                        Margin = new Thickness(0, 0, 6, 0), Padding = new Thickness(9, 0, 9, 0),
                        Opacity = rows > 0 ? 1.0 : known ? 0.72 : 0.45,
                        ToolTip = rows >= 0 ? $"{t}: {rows} row(s) in this package"
                                : known ? $"{t}: not in this package. Adding a row creates it."
                                        : $"{t}: not in this package, and not a table SwiftPack has a schema for."
                    };
                    btn.Click += GroupTable_Click;
                    FormGroupStrip.Children.Add(btn);
                }
            }
            if (FormGroupStripHost != null) FormGroupStripHost.Visibility = Visibility.Visible;

            // Open on the first table that actually holds something, so the view lands on content
            // rather than on an empty first tab.
            string first = group.Tables.FirstOrDefault(t =>
                (_tables.TryGetValue(t, out var s2) ? s2 : EnsureTableCached(t)) is { } s3
                && s3.Data.Rows.Cast<DataRow>().Any(r => r.RowState != DataRowState.Deleted))
                ?? group.Tables[0];
            BindGroupTable(first);

            if (TxtStatus != null) TxtStatus.Text = $"{label}: {group.Note}";
        }

        private void GroupTable_Click(object sender, RoutedEventArgs e)
        {
            if (sender is Button b && b.Tag is string t) BindGroupTable(t);
        }

        private void BindGroupTable(string table)
        {
            var st = EnsureTableCached(table) ?? CreateEmptyStandardTable(table);
            if (st == null)
            {
                _formGridTable = ""; _gridView = null;
                FormGrid.ItemsSource = null;
                if (FormGridTitle != null)
                    FormGridTitle.Text = $"{table} - not in this package, and no built-in schema";
                if (FormGridPanel != null) FormGridPanel.Visibility = Visibility.Visible;
                return;
            }

            _formGridTable = table;
            _gridView = new DataView(st.Data);
            FormGrid.ItemsSource = _gridView;
            if (TxtGridFilter != null) TxtGridFilter.Text = "";
            if (FormGridTitle != null) FormGridTitle.Text = $"{table} - {_gridView.Count} row(s)";
            if (FormGridPanel != null) FormGridPanel.Visibility = Visibility.Visible;

            // Mark which table in the strip is showing.
            if (FormGroupStrip != null)
                foreach (var child in FormGroupStrip.Children)
                    if (child is Button b)
                        b.FontWeight = (b.Tag as string) == table ? FontWeights.Bold : FontWeights.Normal;
        }


        // ══ Environment variables ═══════════════════════════════════════════
        // The Environment table hides everything that matters in punctuation: the Name column
        // carries the action, the uninstall behaviour and the user/system choice as leading
        // characters, and the Value column encodes append or prepend by where it puts [~], which
        // stands for whatever the variable already holds. Encoding here follows WiX's compiler:
        //   Name  = action + uninstall + system + name      e.g. "=-*PATH"
        //   Value = text | text+sep+"[~]" (prepend) | "[~]"+sep+text (append)
        private sealed class EnvData
        {
            public string Key = "", Name = "", Value = "", Component = "";
            public string Action = "=";        // "=" set, "+" create if absent, "!" remove now
            public string Part = "all";        // all / first (prepend) / last (append)
            public string Separator = ";";
            public bool System;                // "*" prefix
            public bool RemoveOnUninstall = true;   // "-" prefix
        }

        private static EnvData ReadEnvRow(DataRow r)
        {
            var d = new EnvData
            {
                Key = Cv(r["Environment"]),
                Component = r.Table.Columns.Contains("Component_") ? Cv(r["Component_"]) : "",
            };

            // Prefix characters may arrive in any order from a third-party package, so they are
            // consumed as a set rather than in WiX's fixed order.
            string raw = r.Table.Columns.Contains("Name") ? Cv(r["Name"]) : "";
            bool sawAction = false, sawUninstall = false;
            int i = 0;
            for (; i < raw.Length; i++)
            {
                char c = raw[i];
                if (c == '*') { d.System = true; continue; }
                if (c == '-') { sawUninstall = true; continue; }
                if ((c == '=' || c == '+' || c == '!') && !sawAction) { d.Action = c.ToString(); sawAction = true; continue; }
                break;
            }
            d.Name = raw.Substring(i);
            // A bare "-Name" with no action character means remove-on-uninstall only.
            d.RemoveOnUninstall = sawUninstall;
            if (!sawAction && sawUninstall) d.Action = "=";

            string val = r.Table.Columns.Contains("Value") ? Cv(r["Value"]) : "";
            const string Tilde = "[~]";
            if (val.StartsWith(Tilde, StringComparison.Ordinal))
            {
                // "[~]" first: the existing value leads, so this appends.
                d.Part = "last";
                string rest = val.Substring(Tilde.Length);
                d.Separator = rest.Length > 0 ? rest.Substring(0, 1) : ";";
                d.Value = rest.Length > 0 ? rest.Substring(1) : "";
            }
            else if (val.EndsWith(Tilde, StringComparison.Ordinal))
            {
                d.Part = "first";
                string rest = val.Substring(0, val.Length - Tilde.Length);
                d.Separator = rest.Length > 0 ? rest.Substring(rest.Length - 1) : ";";
                d.Value = rest.Length > 0 ? rest.Substring(0, rest.Length - 1) : "";
            }
            else { d.Part = "all"; d.Value = val; }

            return d;
        }

        private static (string name, string value) EncodeEnv(EnvData d)
        {
            string name = d.Action
                        + (d.RemoveOnUninstall ? "-" : "")
                        + (d.System ? "*" : "")
                        + d.Name;

            string sep = d.Separator.Length > 0 ? d.Separator.Substring(0, 1) : ";";
            string value = d.Part switch
            {
                "first" => d.Value + sep + "[~]",     // new value leads: prepend
                "last"  => "[~]" + sep + d.Value,     // existing leads: append
                _       => d.Value
            };
            return (name, value);
        }

        private static void WriteEnvRow(DataRow r, EnvData d)
        {
            var (name, value) = EncodeEnv(d);
            if (r.Table.Columns.Contains("Environment")) r["Environment"] = d.Key;
            if (r.Table.Columns.Contains("Name"))        r["Name"] = name;
            if (r.Table.Columns.Contains("Value"))
                r["Value"] = value.Length > 0 ? (object)value : DBNull.Value;
            if (r.Table.Columns.Contains("Component_"))  r["Component_"] = d.Component;
        }

        /// <summary>A one-line description of what the row does, for the tree.</summary>
        private static string EnvSummary(EnvData d)
        {
            string what = d.Action switch
            {
                "+" => "create if absent",
                "!" => "remove on install",
                _   => d.Part switch { "first" => "prepend", "last" => "append", _ => "set" }
            };
            return $"{(d.System ? "system" : "user")}  ·  {what}"
                 + (d.RemoveOnUninstall ? "  ·  removed on uninstall" : "");
        }

        private TableState? _envSt;
        private DataRow? _envEditRow;
        private bool _envEditorLoading;

        private void ShowEnvironmentForm(TableState envSt)
        {
            _envSt = envSt;
            var items = new List<EnvItem>();
            foreach (DataRow r in envSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                var d = ReadEnvRow(r);
                if (d.Name.Length == 0 && d.Key.Length == 0) continue;
                items.Add(new EnvItem(r, d.Name.Length > 0 ? d.Name : d.Key, EnvSummary(d)));
            }
            items.Sort((a, b) => string.Compare(a.Name, b.Name, StringComparison.OrdinalIgnoreCase));

            // A package can arrive with Environment rows and neither action sequenced, and New
            // Variable never runs on that path. Said on the root rather than fixed silently, since
            // browsing to a category should not stage an edit on its own.
            string countText = items.Count == 1 ? "1 variable" : $"{items.Count} variables";
            string warn = items.Count > 0 && EnvActionsMissing()
                ? "  \u00B7  WriteEnvironmentStrings or RemoveEnvironmentStrings is missing"
                : "";
            var root = new EnvItem(null, "Environment Variables", countText + warn)
            { IsRoot = true, IsExpanded = true };
            foreach (var it in items) root.Children.Add(it);

            if (EnvTree != null)
                EnvTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<EnvItem> { root };
            if (EnvCount != null) EnvCount.Text = countText;
            ClearEnvEditor();
            if (FormEnvPanel != null) FormEnvPanel.Visibility = Visibility.Visible;
            if (root.Children.Count > 0) root.Children[0].IsSelected = true;
        }

        private void EnvTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is EnvItem it && !it.IsRoot && it.Row != null) ShowEnvEditor(it.Row);
            else ClearEnvEditor();
        }

        private void ClearEnvEditor()
        {
            _envEditRow = null;
            if (EnvEditorHost != null) EnvEditorHost.Content = null;
        }

        private void EnvMenu_Opened(object sender, RoutedEventArgs e)
        {
            bool onVar = EnvTree?.SelectedItem is EnvItem sel && !sel.IsRoot;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiEnvNew, !onVar);
            V(MiEnvDelete, onVar);
        }

        /// <summary>
        /// The numbers Windows Installer documents for the two actions that read the Environment
        /// table. Placing them anywhere else would put them on the wrong side of InstallFiles or
        /// RemoveFiles, so the documented positions are the ones used.
        /// </summary>
        private const int SeqRemoveEnvironmentStrings = 3300;
        private const int SeqWriteEnvironmentStrings  = 5200;

        /// <summary>
        /// Makes sure a standard action is in InstallExecuteSequence, adding it at its documented
        /// number when it is not. Returns true only when a row was added.
        ///
        /// A package that already sequences the action is left alone whatever number it uses: an
        /// author who moved an action deliberately should not have it moved back.
        /// </summary>
        private bool EnsureExecuteAction(string action, int sequence)
        {
            var st = EnsureTableOrCreate("InstallExecuteSequence");
            if (st == null || !st.Data.Columns.Contains("Action")) return false;
            if (FindCaSeqRow(st, action) != null) return false;

            var nr = st.Data.NewRow();
            nr["Action"] = action;
            if (st.Data.Columns.Contains("Sequence")) nr["Sequence"] = sequence.ToString();
            st.Data.Rows.Add(nr);
            return true;
        }

        /// <summary>
        /// True when the package has Environment rows but is missing an action that would act on
        /// them, which is the state where the variables are written into the table and then never
        /// applied on the target machine.
        /// </summary>
        private bool EnvActionsMissing()
        {
            var st = EnsureTableCached("InstallExecuteSequence");
            if (st == null) return true;
            return FindCaSeqRow(st, "WriteEnvironmentStrings") == null
                || FindCaSeqRow(st, "RemoveEnvironmentStrings") == null;
        }

        private void EnvNew_Click(object sender, RoutedEventArgs e)
        {
            var st = _envSt ?? EnsureTableOrCreate("Environment");
            if (st == null)
            { MstMessage("This MSI has no Environment table.", "New Variable", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            // No name prompt: the variable is created with a default name and its fields are shown,
            // which is where the name is edited along with everything else. Environment.Name is the
            // variable Windows writes, so the default is made unique rather than letting a second
            // New Variable collide with the first.
            var usedNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (st.Data.Columns.Contains("Name"))
                foreach (DataRow er in st.Data.Rows)
                {
                    if (er.RowState == DataRowState.Deleted) continue;
                    // Name carries the action prefix (=, +, -, *, !) and an optional trailing
                    // separator; strip both so the comparison is on the variable name itself.
                    string en = Cv(er["Name"]).TrimStart('=', '+', '-', '*', '!').Trim(';');
                    if (en.Length > 0) usedNames.Add(en);
                }
            string varName = "MY_VARIABLE";
            for (int n = 2; usedNames.Contains(varName); n++) varName = "MY_VARIABLE_" + n;

            var d = new EnvData
            {
                Key = UniqueKey(st.Data, "Environment", SanitizeKey("env_" + varName)),
                Name = varName,
                Component = FirstComponentKey(),
            };
            var nr = st.Data.NewRow();
            WriteEnvRow(nr, d);
            st.Data.Rows.Add(nr);

            // The Environment table does nothing on its own - the two standard actions are what
            // read it - and a package that has never carried a variable often sequences neither.
            // The row then saves cleanly and the variable is simply never written on the target
            // machine, which is the failure that looks like the feature working and not working.
            var seeded = new List<string>();
            if (EnsureExecuteAction("RemoveEnvironmentStrings", SeqRemoveEnvironmentStrings))
                seeded.Add("RemoveEnvironmentStrings");
            if (EnsureExecuteAction("WriteEnvironmentStrings", SeqWriteEnvironmentStrings))
                seeded.Add("WriteEnvironmentStrings");

            UpdateEditCount();
            ShowEnvironmentForm(st);
            SelectEnvByName(d.Name);
            if (seeded.Count > 0 && TxtStatus != null)
                TxtStatus.Text = "Added " + d.Name + ". "
                    + string.Join(" and ", seeded)
                    + (seeded.Count == 1 ? " was missing from InstallExecuteSequence and has"
                                         : " were missing from InstallExecuteSequence and have")
                    + " been added, or the variable would never have been written.";
        }

        private void EnvDelete_Click(object sender, RoutedEventArgs e)
        {
            if (EnvTree?.SelectedItem is not EnvItem it || it.IsRoot || it.Row == null) return;
            var st = _envSt ?? EnsureTableCached("Environment");
            if (st == null) return;
            if (MstMessage($"Delete environment variable \u201C{it.Name}\u201D?",
                    "Delete Variable", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
            if (it.Row.RowState != DataRowState.Deleted) it.Row.Delete();
            UpdateEditCount();
            ShowEnvironmentForm(st);
        }

        private void SelectEnvByName(string name)
        {
            if (EnvTree?.ItemsSource is not System.Collections.IEnumerable roots) return;
            foreach (var o in roots)
            {
                if (o is not EnvItem root) continue;
                root.IsExpanded = true;
                foreach (var it in root.Children)
                    if (string.Equals(it.Name, name, StringComparison.OrdinalIgnoreCase))
                    { it.IsSelected = true; return; }
            }
        }

        /// <summary>Any component, for a new row that has to belong to one. The user changes it in
        /// the form; this only avoids writing a row with a dangling reference.</summary>
        private string FirstComponentKey()
        {
            var st = EnsureTableCached("Component");
            if (st == null || !st.Data.Columns.Contains("Component")) return "";
            foreach (DataRow r in st.Data.Rows)
                if (r.RowState != DataRowState.Deleted) return Cv(r["Component"]);
            return "";
        }

        private void ShowEnvEditor(DataRow row)
        {
            if (EnvEditorHost == null) return;
            _envEditorLoading = true;
            _envEditRow = row;
            var data = ReadEnvRow(row);

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(112) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            int rr = 0;
            void AddRow(string label, FrameworkElement field, bool required = false)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top,
                    TextWrapping = TextWrapping.Wrap
                };
                l.Inlines.Add(new System.Windows.Documents.Run(label));
                // The same red asterisk the Intune detection rows use. Only the columns the MSI
                // schema marks non-nullable carry it.
                if (required)
                    l.Inlines.Add(new System.Windows.Documents.Run(" *")
                    { Foreground = new SolidColorBrush(Color.FromRgb(0xE5, 0x39, 0x35)), FontWeight = FontWeights.Bold });
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }
            ComboBox Combo((string tag, string label)[] opts, string current)
            {
                var cb = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
                };
                foreach (var (tag, label) in opts) cb.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
                int ix = Array.FindIndex(opts, x => x.tag == current);
                cb.SelectedIndex = ix >= 0 ? ix : 0;
                return cb;
            }
            CheckBox Chk(string label, bool on) => new CheckBox
            {
                Content = label, IsChecked = on, Foreground = valFg, FontSize = 12,
                Margin = new Thickness(0, 6, 16, 6), VerticalContentAlignment = VerticalAlignment.Center
            };

            var (nameField, nameBox) = MakeRoundedField(data.Name, boxBg, boxBdr, valFg, false, null);
            AddRow("Name", nameField, required: true);

            var (valField, valBox) = MakeRoundedField(data.Value, boxBg, boxBdr, valFg, true, null);
            AddRow("Value", valField);

            var compBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = data.Component
            };
            foreach (var (v, _) in KeysFrom("Component", "Component")) compBox.Items.Add(v);
            AddRow("Component", RoundWrapControl(compBox, boxBg, boxBdr), required: true);

            var actBox = Combo(new[]
            {
                ("=", "Set the value (create it if absent)"),
                ("+", "Create only if it does not already exist"),
                ("!", "Remove the variable during install"),
            }, data.Action);
            AddRow("On install", RoundWrapControl(actBox, boxBg, boxBdr));

            var partBox = Combo(new[]
            {
                ("all",   "Replace the whole value"),
                ("last",  "Append to the existing value"),
                ("first", "Prepend to the existing value"),
            }, data.Part);
            var partWrap = RoundWrapControl(partBox, boxBg, boxBdr);
            AddRow("Placement", partWrap);

            var (sepField, sepBox) = MakeRoundedField(data.Separator, boxBg, boxBdr, valFg, false, null);
            sepBox.ToolTip = "Character placed between the existing value and the new one.";
            AddRow("Separator", sepField);

            var cSystem = Chk("System variable (all users)", data.System);
            var cRemove = Chk("Remove on uninstall", data.RemoveOnUninstall);
            var opts2 = new WrapPanel { Orientation = Orientation.Horizontal };
            opts2.Children.Add(cSystem); opts2.Children.Add(cRemove);
            AddRow("Options", opts2);

            // What actually goes in the table. The punctuation is the whole encoding, so it is
            // shown rather than left to be deduced from the form above.
            var rawText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
            };
            AddRow("Table row", rawText);

            EnvData ReadControls() => new EnvData
            {
                Key = data.Key,
                Name = nameBox.Text.Trim(),
                Value = valBox.Text,
                Component = compBox.Text.Trim(),
                Action = (actBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "=",
                Part = (partBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "all",
                Separator = sepBox.Text.Length > 0 ? sepBox.Text : ";",
                System = cSystem.IsChecked == true,
                RemoveOnUninstall = cRemove.IsChecked == true,
            };

            void Refresh(EnvData d)
            {
                // WiX rejects a placement on a create-if-absent variable, and it is meaningless:
                // there is nothing to append to when the variable is only written when absent.
                bool canPart = d.Action == "=";
                partBox.IsEnabled = canPart;
                partWrap.Opacity = canPart ? 1.0 : 0.5;
                partWrap.ToolTip = canPart ? null
                    : "Only a variable being set can be appended to. Create-if-absent writes the "
                    + "whole value, and remove does not write one at all.";

                bool needSep = canPart && d.Part != "all";
                sepBox.IsEnabled = needSep;
                sepField.Opacity = needSep ? 1.0 : 0.5;

                bool hasValue = d.Action != "!";
                valBox.IsEnabled = hasValue;
                valField.Opacity = hasValue ? 1.0 : 0.5;

                var (n, v) = EncodeEnv(d);
                rawText.Text = $"Name   {n}\nValue  {(v.Length > 0 ? v : "(none)")}";

                if (EnvTree?.SelectedItem is EnvItem it && !it.IsRoot)
                    it.Update(d.Name.Length > 0 ? d.Name : d.Key, EnvSummary(d));
            }

            void Commit()
            {
                if (_envEditorLoading || _envEditRow == null) return;
                var d = ReadControls();
                if (d.Name.Length == 0) return;   // a nameless variable is not a row worth writing
                WriteEnvRow(_envEditRow, d);
                UpdateEditCount();
                Refresh(d);
            }

            nameBox.TextChanged += (_, _) => Commit();
            valBox.TextChanged  += (_, _) => Commit();
            sepBox.TextChanged  += (_, _) => Commit();
            compBox.LostFocus   += (_, _) => Commit();
            compBox.SelectionChanged += (_, _) => Commit();
            actBox.SelectionChanged  += (_, _) => Commit();
            partBox.SelectionChanged += (_, _) => Commit();
            cSystem.Checked += (_, _) => Commit(); cSystem.Unchecked += (_, _) => Commit();
            cRemove.Checked += (_, _) => Commit(); cRemove.Unchecked += (_, _) => Commit();

            EnvEditorHost.Content = grid;
            _envEditorLoading = false;
            Refresh(data);
        }


        // ══ Services ════════════════════════════════════════════════════════
        // ServiceInstall and ServiceControl describe one service between them, so the tree lists
        // service names and the editor shows both halves. A name may have only a control row -
        // that is how a package starts or stops a service Windows already provides.
        //
        // Constants below are the Msidb values from WiX's MsiInterop, not inferred from samples.
        private const int SvcOwnProcess   = 0x0010;
        private const int SvcShareProcess = 0x0020;
        private const int SvcInteractive  = 0x0100;

        private const int SvcAutoStart   = 0x0002;
        private const int SvcDemandStart = 0x0003;
        private const int SvcDisabled    = 0x0004;

        private const int SvcErrorIgnore   = 0x0000;
        private const int SvcErrorNormal   = 0x0001;
        private const int SvcErrorCritical = 0x0003;
        private const int SvcErrorVital    = 0x8000;

        private const int SvcEvtStart           = 0x0001;
        private const int SvcEvtStop            = 0x0002;
        private const int SvcEvtDelete          = 0x0008;
        private const int SvcEvtUninstallStart  = 0x0010;
        private const int SvcEvtUninstallStop   = 0x0020;
        private const int SvcEvtUninstallDelete = 0x0080;

        private sealed class SvcData
        {
            public string Key = "", Name = "", DisplayName = "", Description = "";
            public string Component = "", Arguments = "", StartName = "", Password = "", LoadOrderGroup = "";
            public string Dependencies = "";     // one per line in the editor, [~] separated in the table
            public bool OwnProcess = true, Interactive;
            public int StartType = SvcDemandStart;
            public int ErrorControl = SvcErrorNormal;
            public bool Vital;
        }

        private sealed class SvcCtlData
        {
            public string Key = "", Name = "", Component = "", Arguments = "";
            public bool StartInstall, StopInstall, DeleteInstall;
            public bool StartUninstall, StopUninstall, DeleteUninstall;
            public bool Wait = true;
        }

        // A [~] separated list is shown one entry per line and written back the same way.
        private static string SvcListToLines(string packed) =>
            string.Join("\n", packed.Split(new[] { "[~]" }, StringSplitOptions.None)
                                    .Where(x => x.Length > 0));
        private static string SvcLinesToList(string lines) =>
            string.Join("[~]", lines.Replace("\r", "").Split('\n')
                                    .Select(x => x.Trim()).Where(x => x.Length > 0));

        private static SvcData ReadSvcRow(DataRow r)
        {
            string C(string c) => r.Table.Columns.Contains(c) ? Cv(r[c]) : "";
            int I(string c) => int.TryParse(C(c), out var v) ? v : 0;

            int type = I("ServiceType");
            int err  = I("ErrorControl");
            return new SvcData
            {
                Key = C("ServiceInstall"), Name = C("Name"), DisplayName = C("DisplayName"),
                Description = C("Description"), Component = C("Component_"), Arguments = C("Arguments"),
                StartName = C("StartName"), Password = C("Password"), LoadOrderGroup = C("LoadOrderGroup"),
                Dependencies = SvcListToLines(C("Dependencies")),
                OwnProcess = (type & SvcShareProcess) == 0,
                Interactive = (type & SvcInteractive) != 0,
                StartType = I("StartType"),
                ErrorControl = err & ~SvcErrorVital,
                Vital = (err & SvcErrorVital) != 0,
            };
        }

        private static void WriteSvcRow(DataRow r, SvcData d)
        {
            void S(string c, string v, bool required = false)
            {
                if (!r.Table.Columns.Contains(c)) return;
                r[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
            }
            S("ServiceInstall", d.Key, true);
            S("Name", d.Name, true);
            S("DisplayName", d.DisplayName);
            S("Description", d.Description);
            S("Component_", d.Component, true);
            S("Arguments", d.Arguments);
            S("StartName", d.StartName);
            S("Password", d.Password);
            S("LoadOrderGroup", d.LoadOrderGroup);
            S("Dependencies", SvcLinesToList(d.Dependencies));

            int type = (d.OwnProcess ? SvcOwnProcess : SvcShareProcess) | (d.Interactive ? SvcInteractive : 0);
            S("ServiceType", type.ToString(), true);
            S("StartType", d.StartType.ToString(), true);
            S("ErrorControl", (d.ErrorControl | (d.Vital ? SvcErrorVital : 0)).ToString(), true);
        }

        private static SvcCtlData ReadSvcCtlRow(DataRow r)
        {
            string C(string c) => r.Table.Columns.Contains(c) ? Cv(r[c]) : "";
            int ev = int.TryParse(C("Event"), out var v) ? v : 0;
            string w = C("Wait");
            return new SvcCtlData
            {
                Key = C("ServiceControl"), Name = C("Name"), Component = C("Component_"),
                Arguments = SvcListToLines(C("Arguments")),
                StartInstall    = (ev & SvcEvtStart) != 0,
                StopInstall     = (ev & SvcEvtStop) != 0,
                DeleteInstall   = (ev & SvcEvtDelete) != 0,
                StartUninstall  = (ev & SvcEvtUninstallStart) != 0,
                StopUninstall   = (ev & SvcEvtUninstallStop) != 0,
                DeleteUninstall = (ev & SvcEvtUninstallDelete) != 0,
                Wait = w.Length == 0 || w != "0",
            };
        }

        private static int SvcCtlEvents(SvcCtlData d) =>
            (d.StartInstall ? SvcEvtStart : 0) | (d.StopInstall ? SvcEvtStop : 0)
          | (d.DeleteInstall ? SvcEvtDelete : 0) | (d.StartUninstall ? SvcEvtUninstallStart : 0)
          | (d.StopUninstall ? SvcEvtUninstallStop : 0) | (d.DeleteUninstall ? SvcEvtUninstallDelete : 0);

        private static void WriteSvcCtlRow(DataRow r, SvcCtlData d)
        {
            void S(string c, string v, bool required = false)
            {
                if (!r.Table.Columns.Contains(c)) return;
                r[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
            }
            S("ServiceControl", d.Key, true);
            S("Name", d.Name, true);
            S("Component_", d.Component, true);
            S("Event", SvcCtlEvents(d).ToString(), true);
            S("Arguments", SvcLinesToList(d.Arguments));
            S("Wait", d.Wait ? "1" : "0", true);
        }

        private TableState? _svcSt, _svcCtlSt;
        private SvcItem? _svcSel;
        private bool _svcEditorLoading;

        private void ShowServicesForm(TableState svcSt)
        {
            _svcSt = svcSt;
            _svcCtlSt = EnsureTableCached("ServiceControl");

            // One node per service name, taking installs and controls together: a control-only
            // name is a Windows service the package touches without owning.
            var byName = new Dictionary<string, SvcItem>(StringComparer.OrdinalIgnoreCase);
            SvcItem Node(string name)
            {
                if (!byName.TryGetValue(name, out var it))
                { it = new SvcItem(name, ""); byName[name] = it; }
                return it;
            }

            foreach (DataRow r in svcSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string n = Cv(r["Name"]);
                if (n.Length == 0) continue;
                Node(n).InstallRow = r;
            }
            if (_svcCtlSt != null)
                foreach (DataRow r in _svcCtlSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string n = Cv(r["Name"]);
                    if (n.Length == 0) continue;
                    var it = Node(n);
                    if (it.ControlRow == null) it.ControlRow = r; else it.ExtraControlRows++;
                }

            var items = byName.Values.OrderBy(x => x.Name, StringComparer.OrdinalIgnoreCase).ToList();
            foreach (var it in items) it.Update(it.Name, SvcSummary(it));

            var root = new SvcItem("Services", items.Count == 1 ? "1 service" : $"{items.Count} services")
            { IsRoot = true, IsExpanded = true };
            foreach (var it in items) root.Children.Add(it);

            if (SvcTree != null)
                SvcTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<SvcItem> { root };
            if (SvcCount != null) SvcCount.Text = root.Summary;
            ClearSvcEditor();
            if (FormServicesPanel != null) FormServicesPanel.Visibility = Visibility.Visible;
            if (root.Children.Count > 0) root.Children[0].IsSelected = true;
        }

        private static string SvcSummary(SvcItem it)
        {
            var parts = new List<string>();
            if (it.InstallRow != null)
            {
                var d = ReadSvcRow(it.InstallRow);
                parts.Add(d.StartType switch
                {
                    SvcAutoStart => "automatic",
                    SvcDisabled  => "disabled",
                    _            => "manual"
                });
                if (d.Interactive) parts.Add("interactive");
            }
            else parts.Add("controlled only, not installed by this package");

            if (it.ControlRow != null)
            {
                var c = ReadSvcCtlRow(it.ControlRow);
                var acts = new List<string>();
                if (c.StartInstall) acts.Add("start");
                if (c.StopInstall) acts.Add("stop");
                if (c.DeleteInstall) acts.Add("delete");
                if (acts.Count > 0) parts.Add("on install: " + string.Join("/", acts));
            }
            return string.Join("  ·  ", parts);
        }

        private void SvcTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            _svcSel = e.NewValue as SvcItem;
            if (_svcSel != null && !_svcSel.IsRoot) ShowSvcEditor(_svcSel);
            else ClearSvcEditor();
        }

        private void ClearSvcEditor()
        {
            _svcSel = null;
            if (SvcEditorHost != null) SvcEditorHost.Content = null;
        }

        private void SvcMenu_Opened(object sender, RoutedEventArgs e)
        {
            bool onSvc = SvcTree?.SelectedItem is SvcItem sel && !sel.IsRoot;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiSvcNew, !onSvc);
            V(MiSvcDelete, onSvc);
        }

        private void SvcNew_Click(object sender, RoutedEventArgs e)
        {
            var st = _svcSt ?? EnsureTableOrCreate("ServiceInstall");
            if (st == null)
            { MstMessage("This MSI has no ServiceInstall table.", "New Service", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            // No name prompt: the service is created with a default name and its fields are shown,
            // which is where the name is edited along with everything else. ServiceInstall.Name is
            // what Windows registers the service under, so the default is made unique rather than
            // letting a second New Service collide with the first.
            var usedNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (DataRow sr in st.Data.Rows)
            {
                if (sr.RowState == DataRowState.Deleted) continue;
                if (!st.Data.Columns.Contains("Name")) break;
                string sn = Cv(sr["Name"]);
                if (sn.Length > 0) usedNames.Add(sn);
            }
            string name = "MyService";
            for (int n = 2; usedNames.Contains(name); n++) name = "MyService" + n;

            var d = new SvcData
            {
                Key = UniqueKey(st.Data, "ServiceInstall", SanitizeKey("svc_" + name)),
                Name = name, DisplayName = name,
                Component = FirstComponentKey(),
            };
            var nr = st.Data.NewRow();
            WriteSvcRow(nr, d);
            st.Data.Rows.Add(nr);
            UpdateEditCount();
            ShowServicesForm(st);
            SelectSvcByName(name);
        }

        private void SvcDelete_Click(object sender, RoutedEventArgs e)
        {
            if (SvcTree?.SelectedItem is not SvcItem it || it.IsRoot) return;
            var st = _svcSt ?? EnsureTableCached("ServiceInstall");
            if (st == null) return;
            if (MstMessage($"Delete service \u201C{it.Name}\u201D, including its control row?",
                    "Delete Service", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
            if (it.InstallRow is { } ir && ir.RowState != DataRowState.Deleted) ir.Delete();
            if (it.ControlRow is { } cr && cr.RowState != DataRowState.Deleted) cr.Delete();
            UpdateEditCount();
            ShowServicesForm(st);
        }

        private void SelectSvcByName(string name)
        {
            if (SvcTree?.ItemsSource is not System.Collections.IEnumerable roots) return;
            foreach (var o in roots)
            {
                if (o is not SvcItem root) continue;
                root.IsExpanded = true;
                foreach (var it in root.Children)
                    if (string.Equals(it.Name, name, StringComparison.OrdinalIgnoreCase))
                    { it.IsSelected = true; return; }
            }
        }

        private void ShowSvcEditor(SvcItem item)
        {
            if (SvcEditorHost == null) return;
            _svcEditorLoading = true;

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(118) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            int rr = 0;

            void AddRow(string label, FrameworkElement field, bool required = false)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top,
                    TextWrapping = TextWrapping.Wrap
                };
                l.Inlines.Add(new System.Windows.Documents.Run(label));
                // The same red asterisk the Intune detection rows use, so "this one has to be
                // filled in" reads the same way across the app. Only the columns the MSI schema
                // marks non-nullable carry it.
                if (required)
                    l.Inlines.Add(new System.Windows.Documents.Run(" *")
                    { Foreground = new SolidColorBrush(Color.FromRgb(0xE5, 0x39, 0x35)), FontWeight = FontWeights.Bold });
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }
            void AddHeading(string text)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var h = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.Bold, Foreground = valFg,
                    Margin = new Thickness(0, rr == 0 ? 0 : 14, 0, 2)
                };
                Grid.SetRow(h, rr); Grid.SetColumn(h, 0); Grid.SetColumnSpan(h, 2);
                grid.Children.Add(h); rr++;
            }
            ComboBox Combo((int tag, string label)[] opts, int current)
            {
                var cb = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
                };
                foreach (var (tag, label) in opts) cb.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
                int ix = Array.FindIndex(opts, x => x.tag == current);
                cb.SelectedIndex = ix >= 0 ? ix : 0;
                return cb;
            }
            CheckBox Chk(string label, bool on) => new CheckBox
            {
                // MinWidth, not Width: a fixed 168 clipped "Can interact with the desktop" and
                // "Wait for the service to settle" mid-word. The columns still line up, because
                // the shorter labels are the ones that sit at the minimum.
                Content = label, IsChecked = on, Foreground = valFg, FontSize = 12, MinWidth = 168,
                Margin = new Thickness(0, 5, 10, 5), VerticalContentAlignment = VerticalAlignment.Center
            };

            // ── Install settings ──
            var d0 = item.InstallRow != null ? ReadSvcRow(item.InstallRow) : null;
            TextBox? dispBox = null, descBox = null, argBox = null, acctBox = null, pwdBox = null,
                     grpBox = null, depBox = null, svcNameBox = null;
            ComboBox? compBox = null, procBox = null, startBox = null, errBox = null;
            CheckBox? cInteractive = null, cVital = null;

            if (d0 != null)
            {
                AddHeading("Install settings");

                // ServiceInstall.Name is what Windows registers the service under, and it was only
                // ever settable from the New Service prompt. With that prompt gone this is the
                // only place it can be changed, so it is a field rather than a tree-only label.
                var (svcNameF, svcNameB) = MakeRoundedField(d0.Name, boxBg, boxBdr, valFg, false, null);
                svcNameBox = svcNameB;
                svcNameB.ToolTip = "The service name Windows registers, as used by sc.exe and "
                                 + "net start. Not the friendly name shown in services.msc.";
                AddRow("Service name", svcNameF, required: true);

                var (dispF, dispB) = MakeRoundedField(d0.DisplayName, boxBg, boxBdr, valFg, false, null);
                dispBox = dispB; AddRow("Display name", dispF);

                var (descF, descB) = MakeRoundedField(d0.Description, boxBg, boxBdr, valFg, true, null);
                descBox = descB; AddRow("Description", descF);

                compBox = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = d0.Component
                };
                foreach (var (v, _) in KeysFrom("Component", "Component")) compBox.Items.Add(v);
                compBox.ToolTip = "The service executable must be this component's key path.";
                AddRow("Component", RoundWrapControl(compBox, boxBg, boxBdr), required: true);

                var (argF, argB) = MakeRoundedField(d0.Arguments, boxBg, boxBdr, valFg, false, null);
                argBox = argB; AddRow("Arguments", argF);

                procBox = Combo(new[]
                {
                    (SvcOwnProcess,   "Runs in its own process"),
                    (SvcShareProcess, "Shares a process with other services"),
                }, d0.OwnProcess ? SvcOwnProcess : SvcShareProcess);
                AddRow("Service type", RoundWrapControl(procBox, boxBg, boxBdr), required: true);

                startBox = Combo(new[]
                {
                    (SvcAutoStart,   "Automatic (starts at boot)"),
                    (SvcDemandStart, "Manual (started on demand)"),
                    (SvcDisabled,    "Disabled"),
                }, d0.StartType);
                AddRow("Start type", RoundWrapControl(startBox, boxBg, boxBdr), required: true);

                errBox = Combo(new[]
                {
                    (SvcErrorIgnore,   "Ignore a start failure"),
                    (SvcErrorNormal,   "Log a start failure and carry on"),
                    (SvcErrorCritical, "Critical: restart or fail the boot"),
                }, d0.ErrorControl);
                AddRow("On failure", RoundWrapControl(errBox, boxBg, boxBdr), required: true);

                var (acctF, acctB) = MakeRoundedField(d0.StartName, boxBg, boxBdr, valFg, false, null);
                acctBox = acctB;
                acctB.ToolTip = "Blank runs as LocalSystem. Otherwise DOMAIN\\User, "
                              + "NT AUTHORITY\\LocalService or NT AUTHORITY\\NetworkService.";
                AddRow("Run as", acctF);

                var (pwdF, pwdB) = MakeRoundedField(d0.Password, boxBg, boxBdr, valFg, false, null);
                pwdBox = pwdB; AddRow("Password", pwdF);

                var (grpF, grpB) = MakeRoundedField(d0.LoadOrderGroup, boxBg, boxBdr, valFg, false, null);
                grpBox = grpB; AddRow("Load order group", grpF);

                var (depF, depB) = MakeRoundedField(d0.Dependencies, boxBg, boxBdr, valFg, true, null);
                depBox = depB;
                depB.ToolTip = "One per line. Prefix a load-order group with + to depend on the group "
                             + "rather than on a service. Stored as a [~] separated list.";
                AddRow("Depends on", depF);

                cInteractive = Chk("Can interact with the desktop", d0.Interactive);
                cVital = Chk("Failure to start is fatal", d0.Vital);
                var wrap = new WrapPanel();
                wrap.Children.Add(cInteractive); wrap.Children.Add(cVital);
                AddRow("Options", wrap);
            }
            else
            {
                AddHeading("Install settings");
                AddRow("", new TextBlock
                {
                    Text = "This package does not install " + item.Name
                         + ". It only controls a service that is expected to be there already.",
                    FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap
                });
            }

            // ── Control settings ──
            AddHeading("Control settings");
            var c0 = item.ControlRow != null ? ReadSvcCtlRow(item.ControlRow) : new SvcCtlData { Name = item.Name };

            var cStartI  = Chk("Start on install",  c0.StartInstall);
            var cStopI   = Chk("Stop on install",   c0.StopInstall);
            var cDelI    = Chk("Delete on install", c0.DeleteInstall);
            var cStartU  = Chk("Start on uninstall",  c0.StartUninstall);
            var cStopU   = Chk("Stop on uninstall",   c0.StopUninstall);
            var cDelU    = Chk("Delete on uninstall", c0.DeleteUninstall);
            var evWrap = new WrapPanel();
            foreach (var c in new[] { cStartI, cStopI, cDelI, cStartU, cStopU, cDelU }) evWrap.Children.Add(c);
            AddRow("Events", evWrap);

            var (ctlArgF, ctlArgB) = MakeRoundedField(c0.Arguments, boxBg, boxBdr, valFg, true, null);
            ctlArgB.ToolTip = "Passed to the service when it is started. One per line; stored as a [~] list.";
            AddRow("Start arguments", ctlArgF);

            var cWait = Chk("Wait for the service to settle", c0.Wait);
            AddRow("", cWait);

            if (item.ExtraControlRows > 0)
                AddRow("", new TextBlock
                {
                    Text = $"{item.ExtraControlRows} further ServiceControl row(s) exist for this name. "
                         + "This editor changes the first; the rest are in the Tables view.",
                    FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap
                });

            var rawText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
            };
            AddRow("Table values", rawText);

            void Commit()
            {
                if (_svcEditorLoading) return;

                // SvcItem.Name has a private setter - Update is the class's way in, and it runs at
                // the end of this method. Until then the new name lives here, so the ServiceControl
                // row below writes the same name the ServiceInstall row just got.
                string svcName = item.Name;

                if (item.InstallRow != null && d0 != null)
                {
                    // A blank name would write an incomplete ServiceInstall row, so the last good
                    // one is kept until something is typed.
                    svcName = svcNameBox!.Text.Trim();
                    if (svcName.Length == 0) svcName = item.Name;

                    var d = new SvcData
                    {
                        Key = d0.Key, Name = svcName,
                        DisplayName = dispBox!.Text.Trim(), Description = descBox!.Text.Trim(),
                        Component = compBox!.Text.Trim(), Arguments = argBox!.Text,
                        StartName = acctBox!.Text.Trim(), Password = pwdBox!.Text,
                        LoadOrderGroup = grpBox!.Text.Trim(), Dependencies = depBox!.Text,
                        OwnProcess = ((procBox!.SelectedItem as ComboBoxItem)?.Tag as int? ?? SvcOwnProcess) == SvcOwnProcess,
                        Interactive = cInteractive!.IsChecked == true,
                        StartType = (startBox!.SelectedItem as ComboBoxItem)?.Tag as int? ?? SvcDemandStart,
                        ErrorControl = (errBox!.SelectedItem as ComboBoxItem)?.Tag as int? ?? SvcErrorNormal,
                        Vital = cVital!.IsChecked == true,
                    };
                    WriteSvcRow(item.InstallRow, d);
                }

                var ctl = new SvcCtlData
                {
                    // ServiceControl.Name has to match ServiceInstall.Name or the row controls a
                    // service that is not there, so it follows a rename in the same commit.
                    Key = c0.Key, Name = svcName,
                    Component = item.InstallRow != null && compBox != null ? compBox.Text.Trim() : c0.Component,
                    Arguments = ctlArgB.Text,
                    StartInstall = cStartI.IsChecked == true, StopInstall = cStopI.IsChecked == true,
                    DeleteInstall = cDelI.IsChecked == true, StartUninstall = cStartU.IsChecked == true,
                    StopUninstall = cStopU.IsChecked == true, DeleteUninstall = cDelU.IsChecked == true,
                    Wait = cWait.IsChecked == true,
                };

                // A control row is only worth having when it does something; ticking the first
                // event creates it, clearing them all takes it away again.
                if (item.ControlRow == null && SvcCtlEvents(ctl) != 0)
                {
                    var ctlSt = _svcCtlSt ?? EnsureTableOrCreate("ServiceControl");
                    if (ctlSt != null)
                    {
                        _svcCtlSt = ctlSt;
                        ctl.Key = UniqueKey(ctlSt.Data, "ServiceControl", SanitizeKey("ctl_" + item.Name));
                        if (ctl.Component.Length == 0) ctl.Component = FirstComponentKey();
                        var nr = ctlSt.Data.NewRow();
                        WriteSvcCtlRow(nr, ctl);
                        ctlSt.Data.Rows.Add(nr);
                        item.ControlRow = nr;
                    }
                }
                else if (item.ControlRow != null)
                {
                    if (SvcCtlEvents(ctl) == 0)
                    { if (item.ControlRow.RowState != DataRowState.Deleted) item.ControlRow.Delete(); item.ControlRow = null; }
                    else
                    {
                        // The key comes from the row being written, not from c0. c0 is read once
                        // when the editor opens, so for a service that had no control row yet it
                        // holds an empty key - and the branch above may have created the row since,
                        // on the first event ticked. Writing c0.Key back would blank the primary
                        // key of a row created moments earlier, which surfaces later as
                        // "a newly added row in ServiceControl is incomplete".
                        string liveKey = item.ControlRow.Table.Columns.Contains("ServiceControl")
                            ? Cv(item.ControlRow["ServiceControl"]) : "";
                        if (liveKey.Length > 0) ctl.Key = liveKey;
                        else if (ctl.Key.Length == 0)
                        {
                            var ctlSt2 = _svcCtlSt ?? EnsureTableOrCreate("ServiceControl");
                            ctl.Key = ctlSt2 != null
                                ? UniqueKey(ctlSt2.Data, "ServiceControl", SanitizeKey("ctl_" + item.Name))
                                : SanitizeKey("ctl_" + item.Name);
                        }
                        if (ctl.Component.Length == 0) ctl.Component = FirstComponentKey();
                        WriteSvcCtlRow(item.ControlRow, ctl);
                    }
                }

                UpdateEditCount();
                item.Update(svcName, SvcSummary(item));

                string typeStr = item.InstallRow != null
                    ? $"ServiceType {Cv(item.InstallRow["ServiceType"])}  StartType {Cv(item.InstallRow["StartType"])}  ErrorControl {Cv(item.InstallRow["ErrorControl"])}"
                    : "no ServiceInstall row";
                rawText.Text = typeStr + "\nEvent " + (item.ControlRow != null ? Cv(item.ControlRow["Event"]) : "no ServiceControl row");
            }

            foreach (var b in new[] { svcNameBox, dispBox, descBox, argBox, acctBox, pwdBox, grpBox, depBox, ctlArgB })
                if (b != null) b.TextChanged += (_, _) => Commit();
            foreach (var cb in new[] { compBox, procBox, startBox, errBox })
                if (cb != null) cb.SelectionChanged += (_, _) => Commit();
            if (compBox != null) compBox.LostFocus += (_, _) => Commit();
            foreach (var c in new[] { cInteractive, cVital, cStartI, cStopI, cDelI, cStartU, cStopU, cDelU, cWait })
                if (c != null) { c.Checked += (_, _) => Commit(); c.Unchecked += (_, _) => Commit(); }

            SvcEditorHost.Content = grid;
            _svcEditorLoading = false;
            Commit();
        }


        // ══ INI file changes ════════════════════════════════════════════════
        // IniFile and RemoveIniFile share a shape and differ only in which actions they carry:
        // WiX routes RemoveLine and RemoveTag to RemoveIniFile and everything else to IniFile, so
        // changing the action here moves the row between the two tables rather than writing a
        // value the table is not allowed to hold.
        private const int IniAddLine    = 0;   // create the entry, or update it if it is there
        private const int IniCreateLine = 1;   // only write it if it is not there already
        private const int IniRemoveLine = 2;
        private const int IniAddTag     = 3;   // append a comma-separated value to the entry
        private const int IniRemoveTag  = 4;

        private static bool IniActionRemoves(int a) => a == IniRemoveLine || a == IniRemoveTag;
        private static string IniTableFor(int a) => IniActionRemoves(a) ? "RemoveIniFile" : "IniFile";

        private static string IniActionText(int a) => a switch
        {
            IniCreateLine => "create if absent",
            IniRemoveLine => "remove entry",
            IniAddTag     => "append tag",
            IniRemoveTag  => "remove tag",
            _             => "set"
        };

        private sealed class IniData
        {
            public string Key = "", FileName = "", DirProperty = "", Section = "",
                          Name = "", Value = "", Component = "";
            public int Action = IniAddLine;
        }

        private static IniData ReadIniRow(DataRow r, bool inRemoveTable)
        {
            string C(string c) => r.Table.Columns.Contains(c) ? Cv(r[c]) : "";
            return new IniData
            {
                Key = C(inRemoveTable ? "RemoveIniFile" : "IniFile"),
                FileName = C("FileName"), DirProperty = C("DirProperty"), Section = C("Section"),
                Name = C("Key"), Value = C("Value"), Component = C("Component_"),
                Action = int.TryParse(C("Action"), out var v) ? v : IniAddLine,
            };
        }

        private static void WriteIniRow(DataRow r, IniData d, bool inRemoveTable)
        {
            void S(string c, string v, bool required = false)
            {
                if (!r.Table.Columns.Contains(c)) return;
                r[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
            }
            S(inRemoveTable ? "RemoveIniFile" : "IniFile", d.Key, true);
            S("FileName", d.FileName, true);
            S("DirProperty", d.DirProperty);
            S("Section", d.Section, true);
            S("Key", d.Name, true);
            // A remove-line row does not need a value; an add-tag row's value is the tag.
            S("Value", d.Value, !inRemoveTable && d.Action != IniRemoveLine);
            S("Action", d.Action.ToString(), true);
            S("Component_", d.Component, true);
        }

        private TableState? _iniSt, _iniRemoveSt;
        private bool _iniEditorLoading;

        private void ShowIniForm(TableState iniSt)
        {
            _iniSt = iniSt;
            _iniRemoveSt = EnsureTableCached("RemoveIniFile");

            // Grouped file, then section, then entry: the shape of an .ini file rather than the
            // shape of the table.
            var files = new Dictionary<string, IniItem>(StringComparer.OrdinalIgnoreCase);
            var order = new List<IniItem>();
            int total = 0;

            void Add(DataRow r, bool remove)
            {
                var d = ReadIniRow(r, remove);
                if (d.FileName.Length == 0 && d.Name.Length == 0) return;
                total++;

                string fileKey = d.FileName + "|" + d.DirProperty;
                if (!files.TryGetValue(fileKey, out var fileNode))
                {
                    string disp = d.FileName.Length > 0 ? d.FileName : "(unnamed)";
                    fileNode = new IniItem(IniLevel.File, disp,
                        d.DirProperty.Length > 0 ? "in [" + d.DirProperty + "]" : "in the Windows folder")
                    { FileName = d.FileName, DirProperty = d.DirProperty, IsExpanded = true };
                    files[fileKey] = fileNode; order.Add(fileNode);
                }

                var secNode = fileNode.Children.FirstOrDefault(x =>
                    string.Equals(x.Section, d.Section, StringComparison.OrdinalIgnoreCase));
                if (secNode == null)
                {
                    secNode = new IniItem(IniLevel.Section,
                        "[" + (d.Section.Length > 0 ? d.Section : "?") + "]", "")
                    { FileName = d.FileName, DirProperty = d.DirProperty, Section = d.Section, IsExpanded = true };
                    fileNode.Children.Add(secNode);
                }

                var entry = new IniItem(IniLevel.Entry, d.Name.Length > 0 ? d.Name : "(no key)",
                    IniActionText(d.Action) + (d.Value.Length > 0 ? "  ·  " + d.Value : ""))
                { Row = r, InRemoveTable = remove, FileName = d.FileName, DirProperty = d.DirProperty, Section = d.Section };
                secNode.Children.Add(entry);
            }

            foreach (DataRow r in iniSt.Data.Rows)
                if (r.RowState != DataRowState.Deleted) Add(r, false);
            if (_iniRemoveSt != null)
                foreach (DataRow r in _iniRemoveSt.Data.Rows)
                    if (r.RowState != DataRowState.Deleted) Add(r, true);

            order.Sort((a, b) => string.Compare(a.Name, b.Name, StringComparison.OrdinalIgnoreCase));
            var root = new IniItem(IniLevel.Root, "INI Files",
                total == 1 ? "1 change" : $"{total} changes") { IsExpanded = true };
            foreach (var f in order) root.Children.Add(f);

            if (IniTree != null)
                IniTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<IniItem> { root };
            if (IniCount != null) IniCount.Text = root.Summary;
            ClearIniEditor();
            if (FormIniPanel != null) FormIniPanel.Visibility = Visibility.Visible;

            var first = order.FirstOrDefault()?.Children.FirstOrDefault()?.Children.FirstOrDefault();
            if (first != null) first.IsSelected = true;
        }

        private void IniTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is IniItem it && it.Level == IniLevel.Entry && it.Row != null) ShowIniEditor(it);
            else ClearIniEditor();
        }

        private void ClearIniEditor()
        {
            if (IniEditorHost != null) IniEditorHost.Content = null;
        }

        private void IniMenu_Opened(object sender, RoutedEventArgs e)
        {
            var lvl = (IniTree?.SelectedItem as IniItem)?.Level ?? IniLevel.Root;
            void V(UIElement? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiIniNewFile,    lvl == IniLevel.Root);
            V(MiIniImport,     lvl == IniLevel.Root);
            V(MiIniNewSection, lvl == IniLevel.File);
            V(MiIniNewEntry,   lvl == IniLevel.Section);
            // A file and a section are the values written on their entries rather than rows of
            // their own, so renaming or deleting one acts on everything under it. The root is not
            // a thing in the package at all, so it gets neither.
            V(MiIniRename,     lvl != IniLevel.Root);
            V(MiIniDelete,     lvl != IniLevel.Root);
            V(MiIniSep,        lvl == IniLevel.File || lvl == IniLevel.Section);
        }

        /// <summary>
        /// Adds one entry. A file and a section have no rows of their own in MSI, so creating
        /// either means creating the first entry inside it.
        /// </summary>
        private void AddIniEntry(string fileName, string dirProperty, string section, string key)
        {
            var st = _iniSt ?? EnsureTableOrCreate("IniFile");
            if (st == null)
            { MstMessage("This MSI has no IniFile table.", "New INI Entry", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            var d = new IniData
            {
                Key = UniqueKey(st.Data, "IniFile", SanitizeKey("ini_" + key)),
                FileName = fileName, DirProperty = dirProperty, Section = section,
                Name = key, Value = "", Action = IniAddLine, Component = FirstComponentKey(),
            };
            var nr = st.Data.NewRow();
            WriteIniRow(nr, d, false);
            st.Data.Rows.Add(nr);
            UpdateEditCount();
            ShowIniForm(st);
            SelectIniEntry(fileName, section, key);
        }

        /// <summary>
        /// A name none of the used ones matches, numbered from 2. For a file name the number goes
        /// before the extension, so a second settings.ini is settings2.ini rather than
        /// settings.ini2.
        /// </summary>
        private static string UniqueIniName(HashSet<string> used, string baseName, bool isFileName)
        {
            if (!used.Contains(baseName)) return baseName;
            string stem = baseName, ext = "";
            if (isFileName)
            {
                int dot = baseName.LastIndexOf('.');
                if (dot > 0) { stem = baseName.Substring(0, dot); ext = baseName.Substring(dot); }
            }
            for (int i = 2; i < 1000; i++)
            {
                string cand = stem + i + ext;
                if (!used.Contains(cand)) return cand;
            }
            return baseName;
        }

        /// <summary>Values already in use at one level of the INI tree, for the defaults above.</summary>
        private HashSet<string> IniNamesInUse(string col, string? fileName, string? section)
        {
            var used = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var st = _iniSt ?? EnsureTableCached("IniFile");
            if (st == null || !st.Data.Columns.Contains(col)) return used;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (fileName != null && !string.Equals(Cv(r["FileName"]), fileName, StringComparison.OrdinalIgnoreCase)) continue;
                if (section  != null && !string.Equals(Cv(r["Section"]),  section,  StringComparison.OrdinalIgnoreCase)) continue;
                string v = Cv(r[col]);
                if (v.Length > 0) used.Add(v);
            }
            return used;
        }

        // The three New entries create the row with workable defaults and select it, rather than
        // asking for the same values through a chain of one-question dialogs first. The editor on
        // the right already carries every field - file name, directory, section, key, value, action
        // and component - so answering three of them in sequence only delayed reaching the rest.
        private void IniNewFile_Click(object sender, RoutedEventArgs e)
            => AddIniEntry(UniqueIniName(IniNamesInUse("FileName", null, null), "settings.ini", true),
                           "", "Settings", "Key");

        private void IniNewSection_Click(object sender, RoutedEventArgs e)
        {
            if (IniTree?.SelectedItem is not IniItem f || f.Level != IniLevel.File) return;
            AddIniEntry(f.FileName, f.DirProperty,
                        UniqueIniName(IniNamesInUse("Section", f.FileName, null), "Settings", false), "Key");
        }

        private void IniNewEntry_Click(object sender, RoutedEventArgs e)
        {
            if (IniTree?.SelectedItem is not IniItem sec || sec.Level != IniLevel.Section) return;
            AddIniEntry(sec.FileName, sec.DirProperty, sec.Section,
                        UniqueIniName(IniNamesInUse("Key", sec.FileName, sec.Section), "Key", false));
        }

        /// <summary>
        /// Reads an .ini from this machine and turns every key it holds into an IniFile row, so a
        /// file that already says what it should say does not have to be retyped a key at a time.
        ///
        /// Entries the package already writes are skipped rather than duplicated: two IniFile rows
        /// for one file, section and key are two instructions for the same line, and which one wins
        /// depends on sequence rather than on anything visible here.
        /// </summary>
        private void IniImport_Click(object sender, RoutedEventArgs e)
        {
            var dlg = new OpenFileDialog
            {
                Title = "Import INI File",
                Filter = "INI files (*.ini)|*.ini|Configuration files (*.cfg;*.conf)|*.cfg;*.conf"
                       + "|All files (*.*)|*.*",
                CheckFileExists = true
            };
            if (dlg.ShowDialog() != true) return;

            string[] lines;
            try { lines = File.ReadAllLines(dlg.FileName); }
            catch (Exception ex)
            {
                MstMessage("That file could not be read.\n\n" + ex.Message,
                    "Import INI File", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            var st = _iniSt ?? EnsureTableOrCreate("IniFile");
            if (st == null)
            { MstMessage("This MSI has no IniFile table.", "Import INI File", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            string fileName = System.IO.Path.GetFileName(dlg.FileName);
            string comp = FirstComponentKey();

            // What the package already writes into this file, so a re-import adds only what is new.
            var existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (!string.Equals(Cv(r["FileName"]), fileName, StringComparison.OrdinalIgnoreCase)) continue;
                existing.Add(Cv(r["Section"]) + "\n" + Cv(r["Key"]));
            }

            string section = "";
            int added = 0, skipped = 0, orphaned = 0;
            string firstSection = "", firstKey = "";

            foreach (string raw in lines)
            {
                string line = raw.Trim();
                if (line.Length == 0 || line[0] == ';' || line[0] == '#') continue;

                if (line[0] == '[' && line[line.Length - 1] == ']')
                { section = line.Substring(1, line.Length - 2).Trim(); continue; }

                int eq = line.IndexOf('=');
                if (eq <= 0) continue;
                string key   = line.Substring(0, eq).Trim();
                string value = line.Substring(eq + 1).Trim();
                if (key.Length == 0) continue;

                // A key above the first [Section] header has nowhere to go: Section is required in
                // the IniFile table, and inventing one would write the line somewhere the source
                // file never had it.
                if (section.Length == 0) { orphaned++; continue; }
                if (!existing.Add(section + "\n" + key)) { skipped++; continue; }

                var d = new IniData
                {
                    Key = UniqueKey(st.Data, "IniFile", SanitizeKey("ini_" + key)),
                    FileName = fileName, DirProperty = "", Section = section,
                    Name = key, Value = value, Action = IniAddLine, Component = comp,
                };
                var nr = st.Data.NewRow();
                WriteIniRow(nr, d, false);
                st.Data.Rows.Add(nr);
                if (added == 0) { firstSection = section; firstKey = key; }
                added++;
            }

            if (added == 0)
            {
                MstMessage(skipped > 0
                        ? $"Every entry in {fileName} is already in this package, so nothing was added."
                        : $"No entries were found in {fileName}. A line has to sit under a "
                        + "[Section] header and read key=value to be one.",
                    "Import INI File", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            UpdateEditCount();
            ShowIniForm(st);
            SelectIniEntry(fileName, firstSection, firstKey);

            string note = $"Imported {added} entr" + (added == 1 ? "y" : "ies") + $" from {fileName}.";
            if (skipped  > 0) note += $" {skipped} already in the package, left alone.";
            if (orphaned > 0) note += $" {orphaned} above the first section header, skipped.";
            if (TxtStatus != null) TxtStatus.Text = note;
        }

        /// <summary>
        /// The rows a node stands for. A file and a section have no rows of their own in MSI: they
        /// are the file name and section written on each entry, so acting on one means acting on
        /// every entry under it. Both IniFile and RemoveIniFile are scanned, since the tree merges
        /// the two and a node can stand for rows in either.
        /// </summary>
        private System.Collections.Generic.List<DataRow> IniRowsFor(IniItem it)
        {
            var outp = new System.Collections.Generic.List<DataRow>();
            if (it.Level == IniLevel.Entry)
            {
                if (it.Row != null && it.Row.RowState != DataRowState.Deleted) outp.Add(it.Row);
                return outp;
            }
            if (it.Level == IniLevel.Root) return outp;

            void Scan(TableState? st, bool remove)
            {
                if (st == null) return;
                foreach (DataRow r in st.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    var d = ReadIniRow(r, remove);
                    if (!string.Equals(d.FileName, it.FileName, StringComparison.OrdinalIgnoreCase)) continue;
                    if (!string.Equals(d.DirProperty, it.DirProperty, StringComparison.OrdinalIgnoreCase)) continue;
                    if (it.Level == IniLevel.Section
                        && !string.Equals(d.Section, it.Section, StringComparison.OrdinalIgnoreCase)) continue;
                    outp.Add(r);
                }
            }
            Scan(_iniSt ?? EnsureTableCached("IniFile"), false);
            Scan(_iniRemoveSt, true);
            return outp;
        }

        private void IniRename_Click(object sender, RoutedEventArgs e)
        {
            if (IniTree?.SelectedItem is not IniItem it || it.Level == IniLevel.Root) return;
            var st = _iniSt ?? EnsureTableCached("IniFile");
            if (st == null) return;

            var (label, current, col) = it.Level switch
            {
                IniLevel.File    => ("File name", it.FileName, "FileName"),
                IniLevel.Section => ("Section",   it.Section,  "Section"),
                _                => ("Key",       it.Name,     "Key"),
            };

            string? typed = PromptText("Rename", label, current);
            if (string.IsNullOrWhiteSpace(typed)) return;
            string name = typed.Trim();
            if (string.Equals(name, current, StringComparison.Ordinal)) return;

            // Two entries with one key in one section are two instructions for the same line, and
            // which of them wins depends on sequence rather than on anything visible here. Renaming
            // a file or a section onto an existing one is a merge, which is a reasonable thing to
            // ask for; renaming a key onto its neighbour is not.
            if (it.Level == IniLevel.Entry
                && IniNamesInUse("Key", it.FileName, it.Section).Contains(name)
                && !string.Equals(name, current, StringComparison.OrdinalIgnoreCase))
            {
                MstMessage($"[{it.Section}] already has a key called \u201C{name}\u201D in "
                         + $"{it.FileName}. Two entries for one key write the same line twice.",
                    "Rename", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            var rows = IniRowsFor(it);
            if (rows.Count == 0) return;
            foreach (var r in rows)
                if (r.Table.Columns.Contains(col)) r[col] = name;

            UpdateEditCount();
            ShowIniForm(st);
            SelectIniEntry(it.Level == IniLevel.File    ? name : it.FileName,
                           it.Level == IniLevel.Section ? name : it.Section,
                           it.Level == IniLevel.Entry   ? name : "");
        }

        private void IniDelete_Click(object sender, RoutedEventArgs e)
        {
            if (IniTree?.SelectedItem is not IniItem it || it.Level == IniLevel.Root) return;
            var st = _iniSt ?? EnsureTableCached("IniFile");
            if (st == null) return;

            var rows = IniRowsFor(it);
            if (rows.Count == 0) return;

            string what = it.Level switch
            {
                IniLevel.File    => $"INI file \u201C{it.Name}\u201D",
                IniLevel.Section => $"section \u201C{it.Section}\u201D",
                _                => $"INI entry \u201C{it.Name}\u201D",
            };
            string ask = it.Level == IniLevel.Entry || rows.Count == 1
                ? $"Delete {what}?"
                : $"Delete {what} and the {rows.Count} entries in it?";
            if (MstMessage(ask, "Delete", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;

            foreach (var r in rows)
                if (r.RowState != DataRowState.Deleted && r.RowState != DataRowState.Detached) r.Delete();
            UpdateEditCount();
            ShowIniForm(st);
        }

        private void SelectIniEntry(string fileName, string section, string key)
        {
            if (IniTree?.ItemsSource is not System.Collections.IEnumerable roots) return;
            foreach (var o in roots)
            {
                if (o is not IniItem root) continue;
                foreach (var f in root.Children)
                {
                    if (!string.Equals(f.FileName, fileName, StringComparison.OrdinalIgnoreCase)) continue;
                    f.IsExpanded = true;
                    foreach (var sec in f.Children)
                    {
                        if (!string.Equals(sec.Section, section, StringComparison.OrdinalIgnoreCase)) continue;
                        sec.IsExpanded = true;
                        foreach (var en in sec.Children)
                            if (string.Equals(en.Name, key, StringComparison.OrdinalIgnoreCase))
                            { en.IsSelected = true; return; }
                    }
                }
            }
        }

        private void ShowIniEditor(IniItem item)
        {
            if (IniEditorHost == null || item.Row == null) return;
            _iniEditorLoading = true;
            var d0 = ReadIniRow(item.Row, item.InRemoveTable);

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(112) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
                };
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }

            var (fileF, fileB) = MakeRoundedField(d0.FileName, boxBg, boxBdr, valFg, false, null);
            AddRow("File name", fileF);

            var dirBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = d0.DirProperty
            };
            foreach (var dd in PackageDirs()) dirBox.Items.Add(dd.value);
            dirBox.ToolTip = "Directory the file lives in. Blank puts it in the Windows folder.";
            AddRow("In directory", RoundWrapControl(dirBox, boxBg, boxBdr));

            var (secF, secB) = MakeRoundedField(d0.Section, boxBg, boxBdr, valFg, false, null);
            AddRow("Section", secF);

            var (keyF, keyB) = MakeRoundedField(d0.Name, boxBg, boxBdr, valFg, false, null);
            AddRow("Key", keyF);

            var (valF, valB) = MakeRoundedField(d0.Value, boxBg, boxBdr, valFg, true, null);
            AddRow("Value", valF);

            var actBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            (int tag, string label)[] acts =
            {
                (IniAddLine,    "Set the value, replacing any existing entry"),
                (IniCreateLine, "Write it only if the entry is not there already"),
                (IniAddTag,     "Append a comma-separated tag to the entry"),
                (IniRemoveLine, "Remove the entry"),
                (IniRemoveTag,  "Remove one comma-separated tag from the entry"),
            };
            foreach (var (tag, label) in acts) actBox.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
            int ai = Array.FindIndex(acts, x => x.tag == d0.Action);
            actBox.SelectedIndex = ai >= 0 ? ai : 0;
            AddRow("Action", RoundWrapControl(actBox, boxBg, boxBdr));

            var compBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = d0.Component
            };
            foreach (var (v, _) in KeysFrom("Component", "Component")) compBox.Items.Add(v);
            AddRow("Component", RoundWrapControl(compBox, boxBg, boxBdr));

            var previewText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
            };
            AddRow("Result", previewText);

            IniData ReadControls() => new IniData
            {
                Key = d0.Key,
                FileName = fileB.Text.Trim(), DirProperty = dirBox.Text.Trim(),
                Section = secB.Text.Trim(), Name = keyB.Text.Trim(), Value = valB.Text,
                Component = compBox.Text.Trim(),
                Action = (actBox.SelectedItem as ComboBoxItem)?.Tag as int? ?? IniAddLine,
            };

            void Commit()
            {
                if (_iniEditorLoading || item.Row == null) return;
                var d = ReadControls();
                if (d.Name.Length == 0 || d.Section.Length == 0) return;

                bool wantRemove = IniActionRemoves(d.Action);
                if (wantRemove != item.InRemoveTable)
                {
                    // The action decides the table, so this row has to move rather than be
                    // written into a table that is not allowed to carry it.
                    string target = IniTableFor(d.Action);
                    var to = EnsureTableOrCreate(target);
                    if (to == null)
                    {
                        MstMessage($"This package has no {target} table and SwiftPack could not create one.",
                            "INI Entry", MessageBoxButton.OK, MessageBoxImage.Warning);
                        return;
                    }
                    if (item.Row.RowState != DataRowState.Deleted) item.Row.Delete();

                    d.Key = UniqueKey(to.Data, target, SanitizeKey("ini_" + d.Name));
                    var moved = to.Data.NewRow();
                    WriteIniRow(moved, d, wantRemove);
                    to.Data.Rows.Add(moved);

                    item.Row = moved;
                    item.InRemoveTable = wantRemove;
                    if (wantRemove) _iniRemoveSt = to; else _iniSt = to;
                }
                else WriteIniRow(item.Row, d, item.InRemoveTable);

                UpdateEditCount();
                item.Update(d.Name.Length > 0 ? d.Name : "(no key)",
                    IniActionText(d.Action) + (d.Value.Length > 0 ? "  ·  " + d.Value : ""));

                string line = d.Action switch
                {
                    IniRemoveLine => $"[{d.Section}]\n{d.Name}=          (entry removed)",
                    IniRemoveTag  => $"[{d.Section}]\n{d.Name}=...       (tag \u201C{d.Value}\u201D removed)",
                    IniAddTag     => $"[{d.Section}]\n{d.Name}=...,{d.Value}",
                    _             => $"[{d.Section}]\n{d.Name}={d.Value}"
                };
                previewText.Text = $"{(d.DirProperty.Length > 0 ? "[" + d.DirProperty + "]" : "[WindowsFolder]")}{d.FileName}\n{line}"
                                 + $"\n\nRow lives in {(item.InRemoveTable ? "RemoveIniFile" : "IniFile")}, Action {d.Action}";
            }

            foreach (var b in new[] { fileB, secB, keyB, valB }) b.TextChanged += (_, _) => Commit();
            dirBox.LostFocus += (_, _) => Commit(); dirBox.SelectionChanged += (_, _) => Commit();
            compBox.LostFocus += (_, _) => Commit(); compBox.SelectionChanged += (_, _) => Commit();
            actBox.SelectionChanged += (_, _) => Commit();

            IniEditorHost.Content = grid;
            _iniEditorLoading = false;
            Commit();
        }


        // ══ System search ═══════════════════════════════════════════════════
        // A search is spread over three tables and nothing joins them on screen: AppSearch says
        // "set this property from that signature", one of four locator tables says where to look,
        // and Signature optionally constrains which file counts as a match. The signature name is
        // the thread through all of them, so that is what this tree lists.
        //
        // Locator Type values are the Msidb constants; 64-bit is a flag OR'd onto RegLocator only.
        private const int LocTypeDirectory = 0;
        private const int LocTypeFileName  = 1;
        private const int LocTypeRawValue  = 2;
        private const int LocType64bit     = 16;

        private static readonly (string kind, string table, string label)[] SearchKinds =
        {
            ("reg",  "RegLocator",  "Registry value"),
            ("ini",  "IniLocator",  "INI file entry"),
            ("comp", "CompLocator", "Installed component"),
            ("dir",  "DrLocator",   "Directory or file on disk"),
        };

        private sealed class SearchData
        {
            public string Signature = "", Property = "";
            public string Kind = "reg";

            public int RegRoot = 2; public string RegKey = "", RegName = ""; public int RegType = LocTypeFileName; public bool Reg64;
            public string IniFile = "", IniSection = "", IniKey = "", IniField = ""; public int IniType = LocTypeFileName;
            public string CompId = ""; public int CompType = LocTypeFileName;
            public string DrParent = "", DrPath = "", DrDepth = "";

            public bool HasSignature;
            public string FileName = "", MinVersion = "", MaxVersion = "",
                          MinSize = "", MaxSize = "", Languages = "";
            public bool Ccp;
        }

        private TableState? _srchAppSt;
        private bool _srchEditorLoading;

        private static string Col(DataRow r, string c) =>
            r.Table.Columns.Contains(c) ? Cv(r[c]) : "";

        private SearchData ReadSearch(SearchItem it)
        {
            var d = new SearchData { Signature = it.Signature, Kind = it.LocatorKind };
            if (it.AppSearchRow != null) d.Property = Col(it.AppSearchRow, "Property");
            d.Ccp = it.CcpRow != null;

            if (it.LocatorRow is { } lr)
                switch (it.LocatorKind)
                {
                    case "reg":
                    {
                        int.TryParse(Col(lr, "Root"), out int root); d.RegRoot = root;
                        d.RegKey = Col(lr, "Key"); d.RegName = Col(lr, "Name");
                        int.TryParse(Col(lr, "Type"), out int t);
                        d.Reg64 = (t & LocType64bit) != 0;
                        d.RegType = t & ~LocType64bit;
                        break;
                    }
                    case "ini":
                        d.IniFile = Col(lr, "FileName"); d.IniSection = Col(lr, "Section");
                        d.IniKey = Col(lr, "Key"); d.IniField = Col(lr, "Field");
                        d.IniType = int.TryParse(Col(lr, "Type"), out int it2) ? it2 : LocTypeFileName;
                        break;
                    case "comp":
                        d.CompId = Col(lr, "ComponentId");
                        d.CompType = int.TryParse(Col(lr, "Type"), out int ct) ? ct : LocTypeFileName;
                        break;
                    default:
                        d.DrParent = Col(lr, "Parent"); d.DrPath = Col(lr, "Path"); d.DrDepth = Col(lr, "Depth");
                        break;
                }

            if (it.SignatureRow is { } sr)
            {
                d.HasSignature = true;
                d.FileName = Col(sr, "FileName"); d.MinVersion = Col(sr, "MinVersion");
                d.MaxVersion = Col(sr, "MaxVersion"); d.MinSize = Col(sr, "MinSize");
                d.MaxSize = Col(sr, "MaxSize"); d.Languages = Col(sr, "Languages");
            }
            return d;
        }

        private static string SearchSummary(SearchItem it, SearchData d)
        {
            string where = SearchKinds.FirstOrDefault(k => k.kind == it.LocatorKind).label ?? "no locator";
            if (it.LocatorRow == null) where = "no locator row, so nothing is searched for";
            return d.Property.Length > 0
                ? $"sets {d.Property}  ·  {where}"
                : $"no property set, so this search has no effect  ·  {where}";
        }

        private void ShowSearchForm(TableState appSt)
        {
            _srchAppSt = appSt;

            var byName = new Dictionary<string, SearchItem>(StringComparer.OrdinalIgnoreCase);
            SearchItem Node(string sig)
            {
                if (!byName.TryGetValue(sig, out var it))
                { it = new SearchItem(sig, ""); byName[sig] = it; }
                return it;
            }

            foreach (DataRow r in appSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string sig = Col(r, "Signature_");
                if (sig.Length > 0) Node(sig).AppSearchRow = r;
            }

            foreach (var (kind, table, _) in SearchKinds)
            {
                var st = EnsureTableCached(table);
                if (st == null) continue;
                foreach (DataRow r in st.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string sig = Col(r, "Signature_");
                    if (sig.Length == 0) continue;
                    var it = Node(sig);
                    if (it.LocatorRow == null) { it.LocatorRow = r; it.LocatorKind = kind; }
                }
            }

            var sigSt = EnsureTableCached("Signature");
            if (sigSt != null)
                foreach (DataRow r in sigSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string sig = Col(r, "Signature");
                    if (sig.Length > 0) Node(sig).SignatureRow = r;
                }

            var ccpSt = EnsureTableCached("CCPSearch");
            if (ccpSt != null)
                foreach (DataRow r in ccpSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string sig = Col(r, "Signature_");
                    if (sig.Length > 0) Node(sig).CcpRow = r;
                }

            var items = byName.Values.OrderBy(x => x.Signature, StringComparer.OrdinalIgnoreCase).ToList();
            foreach (var it in items) it.Update(it.Signature, SearchSummary(it, ReadSearch(it)));

            var root = new SearchItem("System Search",
                items.Count == 1 ? "1 search" : $"{items.Count} searches") { IsRoot = true, IsExpanded = true };
            foreach (var it in items) root.Children.Add(it);

            if (SrchTree != null)
                SrchTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<SearchItem> { root };
            if (SrchCount != null) SrchCount.Text = root.Summary;
            ClearSearchEditor();
            if (FormSearchPanel != null) FormSearchPanel.Visibility = Visibility.Visible;
            if (root.Children.Count > 0) root.Children[0].IsSelected = true;
        }

        private void SrchTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is SearchItem it && !it.IsRoot) ShowSearchEditor(it);
            else ClearSearchEditor();
        }

        private void ClearSearchEditor()
        {
            if (SrchEditorHost != null) SrchEditorHost.Content = null;
        }

        private void SrchMenu_Opened(object sender, RoutedEventArgs e)
        {
            bool onSearch = SrchTree?.SelectedItem is SearchItem sel && !sel.IsRoot;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiSrchNew, !onSearch);
            V(MiSrchDelete, onSearch);
        }

        private void SrchNew_Click(object sender, RoutedEventArgs e)
        {
            var appSt = _srchAppSt ?? EnsureTableOrCreate("AppSearch");
            var regSt = EnsureTableOrCreate("RegLocator");
            if (appSt == null || regSt == null)
            { MstMessage("This MSI has no AppSearch table.", "New Search", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            string? prop = PromptText("New System Search", "Property to set", "MYSEARCH");
            if (string.IsNullOrWhiteSpace(prop)) return;
            string property = SanitizeKey(prop.Trim()).ToUpperInvariant();   // a public property must be upper case
            string sig = UniqueKey(regSt.Data, "Signature_", SanitizeKey("sig_" + property));

            var ar = appSt.Data.NewRow();
            ar["Property"] = property; ar["Signature_"] = sig;
            appSt.Data.Rows.Add(ar);

            var lr = regSt.Data.NewRow();
            lr["Signature_"] = sig;
            if (regSt.Data.Columns.Contains("Root")) lr["Root"] = "2";
            if (regSt.Data.Columns.Contains("Key"))  lr["Key"] = "Software\\";
            if (regSt.Data.Columns.Contains("Type")) lr["Type"] = LocTypeRawValue.ToString();
            regSt.Data.Rows.Add(lr);

            UpdateEditCount();
            ShowSearchForm(appSt);
            SelectSearchBySignature(sig);
        }

        private void SrchDelete_Click(object sender, RoutedEventArgs e)
        {
            if (SrchTree?.SelectedItem is not SearchItem it || it.IsRoot) return;
            var appSt = _srchAppSt ?? EnsureTableCached("AppSearch");
            if (appSt == null) return;
            if (MstMessage($"Delete the search \u201C{it.Signature}\u201D and everything that refers to it?",
                    "Delete Search", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
            foreach (var r in new[] { it.AppSearchRow, it.LocatorRow, it.SignatureRow, it.CcpRow })
                if (r is { } row && row.RowState != DataRowState.Deleted) row.Delete();
            UpdateEditCount();
            ShowSearchForm(appSt);
        }

        private void SelectSearchBySignature(string sig)
        {
            if (SrchTree?.ItemsSource is not System.Collections.IEnumerable roots) return;
            foreach (var o in roots)
            {
                if (o is not SearchItem root) continue;
                root.IsExpanded = true;
                foreach (var it in root.Children)
                    if (string.Equals(it.Signature, sig, StringComparison.OrdinalIgnoreCase))
                    { it.IsSelected = true; return; }
            }
        }

        private void ShowSearchEditor(SearchItem item)
        {
            if (SrchEditorHost == null) return;
            _srchEditorLoading = true;
            var d0 = ReadSearch(item);

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(118) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            int rr = 0;
            var rowsFor = new Dictionary<string, List<FrameworkElement>>();

            void AddRow(string label, FrameworkElement field, string? group = null)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
                };
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                if (group != null)
                {
                    if (!rowsFor.TryGetValue(group, out var lst)) rowsFor[group] = lst = new List<FrameworkElement>();
                    lst.Add(l); lst.Add(field);
                }
                rr++;
            }
            void AddHeading(string text)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var h = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.Bold, Foreground = valFg,
                    Margin = new Thickness(0, rr == 0 ? 0 : 14, 0, 2)
                };
                Grid.SetRow(h, rr); Grid.SetColumn(h, 0); Grid.SetColumnSpan(h, 2);
                grid.Children.Add(h); rr++;
            }
            ComboBox Combo((int tag, string label)[] opts, int current)
            {
                var cb = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
                };
                foreach (var (tag, label) in opts) cb.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
                int ix = Array.FindIndex(opts, x => x.tag == current);
                cb.SelectedIndex = ix >= 0 ? ix : 0;
                return cb;
            }

            AddHeading("Result");
            var (propF, propB) = MakeRoundedField(d0.Property, boxBg, boxBdr, valFg, false, null);
            propB.ToolTip = "The property the search writes into. Clearing it removes the AppSearch "
                          + "row, which leaves the search defined but never run.";
            AddRow("Sets property", propF);

            var kindBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            foreach (var (kind, _, label) in SearchKinds)
                kindBox.Items.Add(new ComboBoxItem { Content = label, Tag = kind });
            int ki = Array.FindIndex(SearchKinds, x => x.kind == d0.Kind);
            kindBox.SelectedIndex = ki >= 0 ? ki : 0;
            AddRow("Look in", RoundWrapControl(kindBox, boxBg, boxBdr));

            // ── Registry ──
            AddHeading("Where to look");
            var rootBox = Combo(new[]
            {
                (0, "HKEY_CLASSES_ROOT"), (1, "HKEY_CURRENT_USER"),
                (2, "HKEY_LOCAL_MACHINE"), (3, "HKEY_USERS"),
            }, d0.RegRoot);
            AddRow("Root", RoundWrapControl(rootBox, boxBg, boxBdr), "reg");
            var (rkeyF, rkeyB) = MakeRoundedField(d0.RegKey, boxBg, boxBdr, valFg, false, null);
            AddRow("Key", rkeyF, "reg");
            var (rnameF, rnameB) = MakeRoundedField(d0.RegName, boxBg, boxBdr, valFg, false, null);
            rnameB.ToolTip = "Value name. Blank reads the key's default value.";
            AddRow("Value name", rnameF, "reg");
            var rtypeBox = Combo(new[]
            {
                (LocTypeRawValue,  "Take the value as it is"),
                (LocTypeFileName,  "The value is a path to a file"),
                (LocTypeDirectory, "The value is a path to a directory"),
            }, d0.RegType);
            AddRow("Value holds", RoundWrapControl(rtypeBox, boxBg, boxBdr), "reg");
            var cReg64 = new CheckBox
            {
                Content = "Read the 64-bit registry view", IsChecked = d0.Reg64,
                Foreground = valFg, FontSize = 12, Margin = new Thickness(0, 6, 0, 6)
            };
            AddRow("", cReg64, "reg");

            // ── INI ──
            var (ifileF, ifileB) = MakeRoundedField(d0.IniFile, boxBg, boxBdr, valFg, false, null);
            AddRow("File name", ifileF, "ini");
            var (isecF, isecB) = MakeRoundedField(d0.IniSection, boxBg, boxBdr, valFg, false, null);
            AddRow("Section", isecF, "ini");
            var (ikeyF, ikeyB) = MakeRoundedField(d0.IniKey, boxBg, boxBdr, valFg, false, null);
            AddRow("Key", ikeyF, "ini");
            var (ifldF, ifldB) = MakeRoundedField(d0.IniField, boxBg, boxBdr, valFg, false, null);
            ifldB.ToolTip = "Which comma-separated field of the value to read. 0 or blank takes the whole line.";
            AddRow("Field", ifldF, "ini");
            var itypeBox = Combo(new[]
            {
                (LocTypeRawValue,  "Take the value as it is"),
                (LocTypeFileName,  "The value is a path to a file"),
                (LocTypeDirectory, "The value is a path to a directory"),
            }, d0.IniType);
            AddRow("Value holds", RoundWrapControl(itypeBox, boxBg, boxBdr), "ini");

            // ── Component ──
            var (cidF, cidB) = MakeRoundedField(d0.CompId, boxBg, boxBdr, valFg, false, null);
            cidB.ToolTip = "The component GUID to look up, not a component key from this package.";
            AddRow("Component ID", cidF, "comp");
            var ctypeBox = Combo(new[]
            {
                (LocTypeFileName,  "Its key file"),
                (LocTypeDirectory, "Its directory"),
            }, d0.CompType);
            AddRow("Find", RoundWrapControl(ctypeBox, boxBg, boxBdr), "comp");

            // ── Directory ──
            var (dparF, dparB) = MakeRoundedField(d0.DrParent, boxBg, boxBdr, valFg, false, null);
            dparB.ToolTip = "Signature of another search to start from, or a property name. "
                          + "Blank searches the whole system, which is slow.";
            AddRow("Start from", dparF, "dir");
            var (dpathF, dpathB) = MakeRoundedField(d0.DrPath, boxBg, boxBdr, valFg, false, null);
            AddRow("Path", dpathF, "dir");
            var (ddepF, ddepB) = MakeRoundedField(d0.DrDepth, boxBg, boxBdr, valFg, false, null);
            ddepB.ToolTip = "How many subdirectory levels below the path to search. Blank or 0 means the path itself.";
            AddRow("Depth", ddepF, "dir");

            // ── File constraints ──
            AddHeading("Match only a file like this (optional)");
            var (sfnF, sfnB) = MakeRoundedField(d0.FileName, boxBg, boxBdr, valFg, false, null);
            sfnB.ToolTip = "Leave every field here blank and no Signature row is written, which "
                         + "means anything found counts as a match.";
            AddRow("File name", sfnF);
            var (minvF, minvB) = MakeRoundedField(d0.MinVersion, boxBg, boxBdr, valFg, false, null);
            AddRow("Min version", minvF);
            var (maxvF, maxvB) = MakeRoundedField(d0.MaxVersion, boxBg, boxBdr, valFg, false, null);
            AddRow("Max version", maxvF);
            var (minsF, minsB) = MakeRoundedField(d0.MinSize, boxBg, boxBdr, valFg, false, null);
            AddRow("Min size", minsF);
            var (maxsF, maxsB) = MakeRoundedField(d0.MaxSize, boxBg, boxBdr, valFg, false, null);
            AddRow("Max size", maxsF);
            var (langF, langB) = MakeRoundedField(d0.Languages, boxBg, boxBdr, valFg, false, null);
            AddRow("Languages", langF);

            var cCcp = new CheckBox
            {
                Content = "Include in the ready-to-run compliance check (CCPSearch)", IsChecked = d0.Ccp,
                Foreground = valFg, FontSize = 12, Margin = new Thickness(0, 6, 0, 6)
            };
            AddRow("", cCcp);

            var rawText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
            };
            AddRow("Tables", rawText);

            string SelectedKind() => (kindBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "reg";

            void ShowKindRows()
            {
                string k = SelectedKind();
                foreach (var (kind, _, _) in SearchKinds)
                    if (rowsFor.TryGetValue(kind, out var lst))
                        foreach (var el in lst)
                            el.Visibility = kind == k ? Visibility.Visible : Visibility.Collapsed;
            }

            void Commit()
            {
                if (_srchEditorLoading) return;
                string kind = SelectedKind();
                string sig = item.Signature;

                // ── locator, moved between tables when the kind changes ──
                string table = SearchKinds.First(x => x.kind == kind).table;
                if (item.LocatorKind != kind || item.LocatorRow == null)
                {
                    if (item.LocatorRow is { } old && old.RowState != DataRowState.Deleted) old.Delete();
                    var to = EnsureTableOrCreate(table);
                    if (to == null) return;
                    var nr = to.Data.NewRow();
                    nr["Signature_"] = sig;
                    to.Data.Rows.Add(nr);
                    item.LocatorRow = nr; item.LocatorKind = kind;
                }
                var lr = item.LocatorRow!;
                void L(string c, string v, bool required = false)
                {
                    if (!lr.Table.Columns.Contains(c)) return;
                    lr[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
                }
                switch (kind)
                {
                    case "reg":
                        L("Root", ((rootBox.SelectedItem as ComboBoxItem)?.Tag as int? ?? 2).ToString(), true);
                        L("Key", rkeyB.Text.Trim(), true);
                        L("Name", rnameB.Text.Trim());
                        L("Type", (((rtypeBox.SelectedItem as ComboBoxItem)?.Tag as int? ?? LocTypeRawValue)
                                   | (cReg64.IsChecked == true ? LocType64bit : 0)).ToString());
                        break;
                    case "ini":
                        L("FileName", ifileB.Text.Trim(), true);
                        L("Section", isecB.Text.Trim(), true);
                        L("Key", ikeyB.Text.Trim(), true);
                        L("Field", ifldB.Text.Trim());
                        L("Type", ((itypeBox.SelectedItem as ComboBoxItem)?.Tag as int? ?? LocTypeFileName).ToString());
                        break;
                    case "comp":
                        L("ComponentId", cidB.Text.Trim(), true);
                        L("Type", ((ctypeBox.SelectedItem as ComboBoxItem)?.Tag as int? ?? LocTypeFileName).ToString());
                        break;
                    default:
                        L("Parent", dparB.Text.Trim());
                        L("Path", dpathB.Text.Trim());
                        L("Depth", ddepB.Text.Trim());
                        break;
                }

                // ── AppSearch: no property means no row, and no row means the search never runs ──
                string property = propB.Text.Trim();
                var appSt = _srchAppSt ?? EnsureTableOrCreate("AppSearch");
                if (property.Length == 0)
                {
                    if (item.AppSearchRow is { } ar0 && ar0.RowState != DataRowState.Deleted) ar0.Delete();
                    item.AppSearchRow = null;
                }
                else if (appSt != null)
                {
                    if (item.AppSearchRow == null)
                    {
                        var ar = appSt.Data.NewRow();
                        ar["Signature_"] = sig;
                        appSt.Data.Rows.Add(ar);
                        item.AppSearchRow = ar;
                    }
                    item.AppSearchRow["Property"] = property;
                }

                // ── Signature: written only when at least one constraint is filled in ──
                bool anySig = new[] { sfnB.Text, minvB.Text, maxvB.Text, minsB.Text, maxsB.Text, langB.Text }
                              .Any(x => x.Trim().Length > 0);
                var sigSt = EnsureTableOrCreate("Signature");
                if (!anySig)
                {
                    if (item.SignatureRow is { } sr0 && sr0.RowState != DataRowState.Deleted) sr0.Delete();
                    item.SignatureRow = null;
                }
                else if (sigSt != null)
                {
                    if (item.SignatureRow == null)
                    {
                        var sr = sigSt.Data.NewRow();
                        sr["Signature"] = sig;
                        sigSt.Data.Rows.Add(sr);
                        item.SignatureRow = sr;
                    }
                    var srow = item.SignatureRow;
                    void S(string c, string v, bool required = false)
                    {
                        if (!srow.Table.Columns.Contains(c)) return;
                        srow[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
                    }
                    S("FileName", sfnB.Text.Trim(), true);
                    S("MinVersion", minvB.Text.Trim()); S("MaxVersion", maxvB.Text.Trim());
                    S("MinSize", minsB.Text.Trim());    S("MaxSize", maxsB.Text.Trim());
                    S("Languages", langB.Text.Trim());
                }

                // ── CCPSearch ──
                if (cCcp.IsChecked == true && item.CcpRow == null)
                {
                    var ccpSt = EnsureTableOrCreate("CCPSearch");
                    if (ccpSt != null)
                    {
                        var cr = ccpSt.Data.NewRow();
                        cr["Signature_"] = sig;
                        ccpSt.Data.Rows.Add(cr);
                        item.CcpRow = cr;
                    }
                }
                else if (cCcp.IsChecked != true && item.CcpRow != null)
                {
                    if (item.CcpRow.RowState != DataRowState.Deleted) item.CcpRow.Delete();
                    item.CcpRow = null;
                }

                UpdateEditCount();
                var d = ReadSearch(item);
                item.Update(sig, SearchSummary(item, d));

                rawText.Text = $"AppSearch   {(item.AppSearchRow != null ? property + "  <-  " + sig : "none, so it never runs")}"
                             + $"\n{table,-11} {sig}"
                             + $"\nSignature   {(item.SignatureRow != null ? "constrained" : "none, anything found matches")}"
                             + $"\nCCPSearch   {(item.CcpRow != null ? "included" : "not included")}";
            }

            kindBox.SelectionChanged += (_, _) => { ShowKindRows(); Commit(); };
            foreach (var b in new[] { propB, rkeyB, rnameB, ifileB, isecB, ikeyB, ifldB, cidB,
                                      dparB, dpathB, ddepB, sfnB, minvB, maxvB, minsB, maxsB, langB })
                b.TextChanged += (_, _) => Commit();
            foreach (var cb in new[] { rootBox, rtypeBox, itypeBox, ctypeBox })
                cb.SelectionChanged += (_, _) => Commit();
            foreach (var c in new[] { cReg64, cCcp })
            { c.Checked += (_, _) => Commit(); c.Unchecked += (_, _) => Commit(); }

            SrchEditorHost.Content = grid;
            ShowKindRows();
            _srchEditorLoading = false;
            Commit();
        }


        // ══ ODBC resources ══════════════════════════════════════════════════
        // Five tables: drivers and translators name a file, data sources name a driver, and two
        // attribute tables hang name/value pairs off drivers and data sources. The one thing worth
        // knowing is that ODBCDataSource.DriverDescription points at a driver's Description text
        // rather than its key, so renaming a driver's description silently orphans its DSNs.
        private const int OdbcPerMachine = 0;
        private const int OdbcPerUser    = 1;

        private TableState? _odbcDrvSt;
        private bool _odbcEditorLoading;
        private DataView? _odbcAttrView;

        private static string SqlLit(string v) => "'" + v.Replace("'", "''") + "'";

        private void ShowOdbcForm(TableState drvSt)
        {
            _odbcDrvSt = drvSt;
            var trSt  = EnsureTableCached("ODBCTranslator");
            var dsSt  = EnsureTableCached("ODBCDataSource");

            OdbcItem Group(string name) => new OdbcItem(OdbcKind.Group, name, "") { IsExpanded = true };
            var drivers     = Group("Drivers");
            var translators = Group("Translators");
            var sources     = Group("Data sources");

            void Fill(TableState? st, string keyCol, OdbcItem into, OdbcKind kind)
            {
                if (st == null) return;
                var rows = st.Data.Rows.Cast<DataRow>()
                    .Where(r => r.RowState != DataRowState.Deleted)
                    .OrderBy(r => Col(r, "Description"), StringComparer.OrdinalIgnoreCase);
                foreach (var r in rows)
                {
                    string desc = Col(r, "Description");
                    string sub = kind == OdbcKind.DataSource
                        ? "driver: " + (Col(r, "DriverDescription") is { Length: > 0 } dd ? dd : "not set")
                          + (Col(r, "Registration") == OdbcPerUser.ToString() ? "  ·  per user" : "  ·  per machine")
                        : "file: " + (Col(r, "File_") is { Length: > 0 } f ? f : "not set");
                    into.Children.Add(new OdbcItem(kind, desc.Length > 0 ? desc : Col(r, keyCol), sub) { Row = r });
                }
            }
            Fill(drvSt, "Driver", drivers, OdbcKind.Driver);
            Fill(trSt, "Translator", translators, OdbcKind.Translator);
            Fill(dsSt, "DataSource", sources, OdbcKind.DataSource);

            int total = drivers.Children.Count + translators.Children.Count + sources.Children.Count;
            var root = new OdbcItem(OdbcKind.Root, "ODBC Resources",
                total == 1 ? "1 resource" : $"{total} resources") { IsExpanded = true };
            foreach (var g in new[] { drivers, translators, sources })
            {
                g.Update(g.Name, g.Children.Count == 1 ? "1 entry" : $"{g.Children.Count} entries");
                root.Children.Add(g);
            }

            if (OdbcTree != null)
                OdbcTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<OdbcItem> { root };
            if (OdbcCount != null) OdbcCount.Text = root.Summary;
            ClearOdbcEditor();
            if (FormOdbcPanel != null) FormOdbcPanel.Visibility = Visibility.Visible;

            var first = root.Children.SelectMany(g => g.Children).FirstOrDefault();
            if (first != null) first.IsSelected = true;
        }

        private void OdbcTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is OdbcItem it && it.Row != null) ShowOdbcEditor(it);
            else ClearOdbcEditor();
        }

        private void ClearOdbcEditor()
        {
            _odbcAttrView = null;
            if (OdbcEditorHost != null) OdbcEditorHost.Content = null;
            if (OdbcAttrGrid != null) OdbcAttrGrid.ItemsSource = null;
            if (OdbcAttrTitle != null) OdbcAttrTitle.Text = "Attributes";
        }

        private void OdbcMenu_Opened(object sender, RoutedEventArgs e)
        {
            var it = OdbcTree?.SelectedItem as OdbcItem;
            bool onGroup = it?.Kind == OdbcKind.Group;
            bool onItem  = it?.Row != null;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiOdbcNew, onGroup);
            if (MiOdbcNew != null && onGroup) MiOdbcNew.Header = "New " + (it!.Name.TrimEnd('s')) + "...";
            V(MiOdbcDelete, onItem);
        }

        private void OdbcNew_Click(object sender, RoutedEventArgs e)
        {
            if (OdbcTree?.SelectedItem is not OdbcItem g || g.Kind != OdbcKind.Group) return;
            (string table, string keyCol) = g.Name switch
            {
                "Translators"  => ("ODBCTranslator", "Translator"),
                "Data sources" => ("ODBCDataSource", "DataSource"),
                _              => ("ODBCDriver", "Driver"),
            };
            var st = EnsureTableOrCreate(table);
            if (st == null)
            { MstMessage($"This MSI has no {table} table.", "New ODBC Resource", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            string? typed = PromptText("New " + g.Name.TrimEnd('s'), "Description", "My " + g.Name.TrimEnd('s'));
            if (string.IsNullOrWhiteSpace(typed)) return;
            string desc = typed.Trim();

            var nr = st.Data.NewRow();
            nr[keyCol] = UniqueKey(st.Data, keyCol, SanitizeKey("odbc_" + desc));
            if (st.Data.Columns.Contains("Description")) nr["Description"] = desc;
            if (st.Data.Columns.Contains("Component_")) nr["Component_"] = FirstComponentKey();
            if (table == "ODBCDataSource" && st.Data.Columns.Contains("Registration"))
                nr["Registration"] = OdbcPerMachine.ToString();
            st.Data.Rows.Add(nr);

            UpdateEditCount();
            ShowOdbcForm(_odbcDrvSt ?? EnsureTableOrCreate("ODBCDriver")!);
            SelectOdbcByDescription(desc);
        }

        private void OdbcDelete_Click(object sender, RoutedEventArgs e)
        {
            if (OdbcTree?.SelectedItem is not OdbcItem it || it.Row == null) return;
            if (MstMessage($"Delete \u201C{it.Name}\u201D and its attributes?",
                    "Delete ODBC Resource", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;

            // The attribute rows are keyed on this one, so they go with it.
            var (attrTable, parentCol, keyCol) = OdbcAttrTarget(it.Kind);
            if (attrTable.Length > 0)
            {
                string parent = Col(it.Row, keyCol);
                var ast = EnsureTableCached(attrTable);
                if (ast != null)
                    foreach (DataRow ar in ast.Data.Rows)
                        if (ar.RowState != DataRowState.Deleted &&
                            string.Equals(Col(ar, parentCol), parent, StringComparison.OrdinalIgnoreCase))
                            ar.Delete();
            }
            if (it.Row.RowState != DataRowState.Deleted) it.Row.Delete();
            UpdateEditCount();
            ShowOdbcForm(_odbcDrvSt ?? EnsureTableOrCreate("ODBCDriver")!);
        }

        private static (string table, string parentCol, string keyCol) OdbcAttrTarget(OdbcKind k) => k switch
        {
            OdbcKind.Driver     => ("ODBCAttribute", "Driver_", "Driver"),
            OdbcKind.DataSource => ("ODBCSourceAttribute", "DataSource_", "DataSource"),
            _                   => ("", "", ""),   // translators carry no attributes
        };

        private void SelectOdbcByDescription(string desc)
        {
            if (OdbcTree?.ItemsSource is not System.Collections.IEnumerable roots) return;
            foreach (var o in roots)
            {
                if (o is not OdbcItem root) continue;
                foreach (var g in root.Children)
                {
                    g.IsExpanded = true;
                    foreach (var it in g.Children)
                        if (string.Equals(it.Name, desc, StringComparison.OrdinalIgnoreCase))
                        { it.IsSelected = true; return; }
                }
            }
        }

        private void ShowOdbcEditor(OdbcItem item)
        {
            if (OdbcEditorHost == null || item.Row == null) return;
            _odbcEditorLoading = true;
            var row = item.Row;

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(118) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
                };
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }

            var (descF, descB) = MakeRoundedField(Col(row, "Description"), boxBg, boxBdr, valFg, false, null);
            if (item.Kind == OdbcKind.Driver)
                descB.ToolTip = "Data sources point at a driver by this text, so changing it breaks "
                              + "any DSN that names the old description.";
            AddRow("Description", descF);

            var compBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = Col(row, "Component_")
            };
            foreach (var (v, _) in KeysFrom("Component", "Component")) compBox.Items.Add(v);
            AddRow("Component", RoundWrapControl(compBox, boxBg, boxBdr));

            ComboBox? fileBox = null, setupBox = null, drvBox = null, regBox = null;

            if (item.Kind == OdbcKind.Driver || item.Kind == OdbcKind.Translator)
            {
                var files = KeysFrom("File", "File").Select(x => x.value).ToList();

                fileBox = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = Col(row, "File_")
                };
                foreach (var f in files) fileBox.Items.Add(f);
                fileBox.ToolTip = "The driver DLL, as a key from the File table.";
                AddRow("Driver file", RoundWrapControl(fileBox, boxBg, boxBdr));

                setupBox = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = Col(row, "File_Setup")
                };
                foreach (var f in files) setupBox.Items.Add(f);
                setupBox.ToolTip = "Setup DLL. Blank means the driver file handles setup itself.";
                AddRow("Setup file", RoundWrapControl(setupBox, boxBg, boxBdr));
            }
            else
            {
                drvBox = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr,
                    Text = Col(row, "DriverDescription")
                };
                var drvSt = EnsureTableCached("ODBCDriver");
                if (drvSt != null)
                    foreach (DataRow dr in drvSt.Data.Rows)
                        if (dr.RowState != DataRowState.Deleted && Col(dr, "Description") is { Length: > 0 } dd)
                            drvBox.Items.Add(dd);
                drvBox.ToolTip = "Matched against the driver's Description text, not its key. It may "
                               + "also name a driver already installed on the machine.";
                AddRow("Uses driver", RoundWrapControl(drvBox, boxBg, boxBdr));

                regBox = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
                };
                regBox.Items.Add(new ComboBoxItem { Content = "Per machine (system DSN)", Tag = OdbcPerMachine });
                regBox.Items.Add(new ComboBoxItem { Content = "Per user", Tag = OdbcPerUser });
                regBox.SelectedIndex = Col(row, "Registration") == OdbcPerUser.ToString() ? 1 : 0;
                AddRow("Registration", RoundWrapControl(regBox, boxBg, boxBdr));
            }

            void Commit()
            {
                if (_odbcEditorLoading) return;
                void S(string c, string v, bool required = false)
                {
                    if (!row.Table.Columns.Contains(c)) return;
                    row[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
                }
                S("Description", descB.Text.Trim(), true);
                S("Component_", compBox.Text.Trim(), true);
                if (fileBox != null)  S("File_", fileBox.Text.Trim(), true);
                if (setupBox != null) S("File_Setup", setupBox.Text.Trim());
                if (drvBox != null)   S("DriverDescription", drvBox.Text.Trim(), true);
                if (regBox != null)
                    S("Registration", ((regBox.SelectedItem as ComboBoxItem)?.Tag as int? ?? OdbcPerMachine).ToString(), true);

                UpdateEditCount();
                string sub = item.Kind == OdbcKind.DataSource
                    ? "driver: " + (drvBox!.Text.Trim() is { Length: > 0 } dd2 ? dd2 : "not set")
                      + (regBox != null && (regBox.SelectedItem as ComboBoxItem)?.Tag as int? == OdbcPerUser
                         ? "  ·  per user" : "  ·  per machine")
                    : "file: " + (fileBox!.Text.Trim() is { Length: > 0 } f2 ? f2 : "not set");
                item.Update(descB.Text.Trim(), sub);
            }

            descB.TextChanged += (_, _) => Commit();
            foreach (var cb in new[] { compBox, fileBox, setupBox, drvBox, regBox })
                if (cb != null)
                { cb.SelectionChanged += (_, _) => Commit(); cb.LostFocus += (_, _) => Commit(); }

            OdbcEditorHost.Content = grid;
            _odbcEditorLoading = false;

            BindOdbcAttributes(item);
        }

        /// <summary>Binds the attribute grid to the rows keyed on the selected driver or data
        /// source. Translators have no attribute table, so the grid is emptied instead.</summary>
        private void BindOdbcAttributes(OdbcItem item)
        {
            _odbcAttrView = null;
            if (OdbcAttrGrid == null || item.Row == null) return;

            var (attrTable, parentCol, keyCol) = OdbcAttrTarget(item.Kind);
            if (attrTable.Length == 0)
            {
                OdbcAttrGrid.ItemsSource = null;
                if (OdbcAttrTitle != null) OdbcAttrTitle.Text = "Attributes - translators do not have any";
                if (OdbcAttrAdd != null) OdbcAttrAdd.IsEnabled = false;
                if (OdbcAttrDel != null) OdbcAttrDel.IsEnabled = false;
                return;
            }

            var st = EnsureTableOrCreate(attrTable);
            if (st == null) { OdbcAttrGrid.ItemsSource = null; return; }

            string parent = Col(item.Row, keyCol);
            _odbcAttrView = new DataView(st.Data)
            {
                RowFilter = $"{parentCol} = {SqlLit(parent)}",
                Sort = "Attribute",
            };
            OdbcAttrGrid.ItemsSource = _odbcAttrView;
            if (OdbcAttrTitle != null)
                OdbcAttrTitle.Text = $"Attributes  ({attrTable}, {_odbcAttrView.Count})";
            if (OdbcAttrAdd != null) OdbcAttrAdd.IsEnabled = true;
            if (OdbcAttrDel != null) OdbcAttrDel.IsEnabled = true;
        }

        private void OdbcAttrAdd_Click(object sender, RoutedEventArgs e)
        {
            if (OdbcTree?.SelectedItem is not OdbcItem item || item.Row == null) return;
            var (attrTable, parentCol, keyCol) = OdbcAttrTarget(item.Kind);
            if (attrTable.Length == 0) return;
            var st = EnsureTableOrCreate(attrTable);
            if (st == null) return;

            string? name = PromptText("New Attribute", "Attribute name", "Attribute");
            if (string.IsNullOrWhiteSpace(name)) return;

            // The parent key is filled in here rather than left to the grid: a row whose parent
            // column is blank would vanish from the filtered view the moment it was added.
            var nr = st.Data.NewRow();
            nr[parentCol] = Col(item.Row, keyCol);
            nr["Attribute"] = name.Trim();
            st.Data.Rows.Add(nr);
            UpdateEditCount();
            BindOdbcAttributes(item);
        }

        private void OdbcAttrDel_Click(object sender, RoutedEventArgs e)
        {
            if (OdbcAttrGrid?.SelectedItem is not DataRowView drv) return;
            if (OdbcTree?.SelectedItem is not OdbcItem item) return;
            if (drv.Row.RowState != DataRowState.Deleted) drv.Row.Delete();
            UpdateEditCount();
            BindOdbcAttributes(item);
        }


        // ══ Dialogs ═════════════════════════════════════════════════════════
        // Control.Attributes is two fields sharing one integer. The low bits (0x01 to 0x80) mean
        // the same thing on every control; everything above 0xFFFF is overloaded by control type,
        // so 0x10000 is Transparent on a Text, Multiline on an Edit, Sorted on a ListBox and
        // ImageHandle on a PushButton. The editor therefore offers the type's own names, and any
        // bit it does not recognise for that type is carried through untouched rather than lost.
        private static readonly (int bit, string label)[] DlgAttrBits =
        {
            (0x0001, "Visible"), (0x0002, "Modal"), (0x0004, "Minimize button"),
            (0x0008, "System modal"), (0x0010, "Keep modeless dialogs alive"),
            (0x0020, "Track disk space"), (0x0040, "Use custom palette"),
            (0x00010000, "Error dialog"),
        };

        private static readonly (int bit, string label)[] CtlCommonBits =
        {
            (0x0001, "Visible"), (0x0002, "Enabled"), (0x0004, "Sunken"),
            (0x0008, "Indirect property"), (0x0010, "Integer property"),
            (0x0020, "Right to left reading"), (0x0040, "Right aligned"), (0x0080, "Left scrollbar"),
        };

        /// <summary>The named bits above 0xFFFF for one control type. Anything not listed here for
        /// that type is preserved rather than shown, because its meaning is not knowable.</summary>
        private static (int bit, string label)[] CtlTypeBits(string type) => type.ToLowerInvariant() switch
        {
            "text" or "scrollabletext" => new[]
            {
                (0x00010000, "Transparent"), (0x00020000, "No prefix"), (0x00040000, "No wrap"),
                (0x00080000, "Format as size"), (0x00100000, "User's language"),
            },
            "edit" or "maskededit" => new[]
            {
                (0x00010000, "Multiline"), (0x00200000, "Password input"),
            },
            "listbox" or "listview" or "selectiontree" => new[] { (0x00010000, "Sorted") },
            "combobox" => new[] { (0x00010000, "Sorted"), (0x00020000, "Drop-down list only") },
            "pushbutton" => new[]
            {
                (0x00010000, "Image is a handle"), (0x00040000, "Bitmap"), (0x00080000, "Icon"),
                (0x00100000, "Fixed size"), (0x00800000, "Elevation shield"), (0x01000000, "Has border"),
            },
            "checkbox" or "radiobuttongroup" => new[]
            {
                (0x00010000, "Image is a handle"), (0x00020000, "Push-like"),
                (0x00040000, "Bitmap"), (0x00080000, "Icon"), (0x01000000, "Has border"),
            },
            "icon" or "bitmap" => new[]
            {
                (0x00010000, "Image is a handle"), (0x00100000, "Fixed size"),
            },
            "volumeselectcombo" or "volumecostlist" or "directorycombo" or "directorylist" => new[]
            {
                (0x00010000, "Removable drives"), (0x00020000, "Fixed drives"),
                (0x00040000, "Network drives"), (0x00080000, "CD-ROM drives"),
                (0x00100000, "RAM disks"), (0x00200000, "Floppy drives"),
            },
            _ => System.Array.Empty<(int, string)>(),
        };

        private static readonly string[] CtlTypes =
        {
            "Billboard", "Bitmap", "CheckBox", "ComboBox", "DirectoryCombo", "DirectoryList",
            "Edit", "GroupBox", "Icon", "Line", "ListBox", "ListView", "MaskedEdit", "PathEdit",
            "ProgressBar", "PushButton", "RadioButtonGroup", "ScrollableText", "SelectionTree",
            "Text", "VolumeCostList", "VolumeSelectCombo",
        };

        private TableState? _dlgSt;
        private bool _dlgEditorLoading;
        private string _dlgSubTab = "events";

        private void ShowDialogsForm(TableState dlgSt)
        {
            _dlgSt = dlgSt;
            var ctlSt = EnsureTableCached("Control");

            var byDialog = new Dictionary<string, DlgItem>(StringComparer.OrdinalIgnoreCase);
            var order = new List<DlgItem>();
            foreach (DataRow r in dlgSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string name = Col(r, "Dialog");
                if (name.Length == 0) continue;
                string title = Col(r, "Title");
                var node = new DlgItem(DlgKind.Dialog, name,
                    (title.Length > 0 ? title + "  ·  " : "") + Col(r, "Width") + " x " + Col(r, "Height"))
                { Row = r, DialogName = name };
                byDialog[name] = node; order.Add(node);
            }

            int controls = 0;
            if (ctlSt != null)
                foreach (DataRow r in ctlSt.Data.Rows.Cast<DataRow>()
                            .Where(x => x.RowState != DataRowState.Deleted)
                            .OrderBy(x => Col(x, "Control"), StringComparer.OrdinalIgnoreCase))
                {
                    string dlg = Col(r, "Dialog_");
                    if (!byDialog.TryGetValue(dlg, out var parent)) continue;
                    parent.Children.Add(new DlgItem(DlgKind.Control, Col(r, "Control"), Col(r, "Type"))
                    { Row = r, DialogName = dlg });
                    controls++;
                }

            order.Sort((a, b) => string.Compare(a.Name, b.Name, StringComparison.OrdinalIgnoreCase));
            var root = new DlgItem(DlgKind.Root, "Dialogs",
                $"{order.Count} dialog(s), {controls} control(s)") { IsExpanded = true };
            foreach (var d in order) root.Children.Add(d);

            if (DlgTree != null)
                DlgTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<DlgItem> { root };
            if (DlgCount != null) DlgCount.Text = root.Summary;
            ClearDlgEditor();
            if (FormDialogsPanel != null) FormDialogsPanel.Visibility = Visibility.Visible;
            if (root.Children.Count > 0) root.Children[0].IsSelected = true;
        }

        private void DlgTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is DlgItem it && it.Row != null) ShowDlgEditor(it);
            else ClearDlgEditor();
            if (DlgCanvasArea?.Visibility == Visibility.Visible) RenderDlgCanvas();
        }

        private void ClearDlgEditor()
        {
            if (DlgEditorHost != null) DlgEditorHost.Content = null;
            if (DlgSubGrid != null) { DlgSubGrid.ItemsSource = null; DlgSubGrid.Columns.Clear(); }
            if (DlgSubTitle != null) DlgSubTitle.Text = "Behaviour";
        }

        private void DlgMenu_Opened(object sender, RoutedEventArgs e)
        {
            var it = DlgTree?.SelectedItem as DlgItem;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiDlgNewDialog,  it == null || it.Kind == DlgKind.Root);
            V(MiDlgNewControl, it?.Kind == DlgKind.Dialog);
            V(MiDlgDelete,     it?.Row != null);
        }

        private void DlgNewDialog_Click(object sender, RoutedEventArgs e)
        {
            var st = _dlgSt ?? EnsureTableOrCreate("Dialog");
            if (st == null) return;
            string? typed = PromptText("New Dialog", "Dialog name", "MyDialog");
            if (string.IsNullOrWhiteSpace(typed)) return;
            string name = SanitizeKey(typed.Trim());
            if (FindLiveRow(st, "Dialog", name) != null)
            { MstMessage($"{name} already exists.", "New Dialog", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            var nr = st.Data.NewRow();
            nr["Dialog"] = name;
            void S(string c, string v) { if (st.Data.Columns.Contains(c)) nr[c] = v; }
            S("HCentering", "50"); S("VCentering", "50");
            S("Width", "370"); S("Height", "270");
            S("Attributes", "3");            // visible + modal, the usual starting point
            S("Title", name);
            S("Control_First", "");
            st.Data.Rows.Add(nr);
            UpdateEditCount();
            ShowDialogsForm(st);
            SelectDlgNode(name, null);
        }

        private void DlgNewControl_Click(object sender, RoutedEventArgs e)
        {
            if (DlgTree?.SelectedItem is not DlgItem d || d.Kind != DlgKind.Dialog) return;
            var ctlSt = EnsureTableOrCreate("Control");
            if (ctlSt == null) return;
            string? typed = PromptText("New Control", "Control name", "MyControl");
            if (string.IsNullOrWhiteSpace(typed)) return;
            string name = SanitizeKey(typed.Trim());

            var nr = ctlSt.Data.NewRow();
            void S(string c, string v) { if (ctlSt.Data.Columns.Contains(c)) nr[c] = v; }
            S("Dialog_", d.DialogName); S("Control", name); S("Type", "Text");
            S("X", "10"); S("Y", "10"); S("Width", "100"); S("Height", "17");
            S("Attributes", "3");            // visible + enabled
            ctlSt.Data.Rows.Add(nr);
            UpdateEditCount();
            ShowDialogsForm(_dlgSt!);
            SelectDlgNode(d.DialogName, name);
        }

        private void DlgDelete_Click(object sender, RoutedEventArgs e)
        {
            if (DlgTree?.SelectedItem is not DlgItem it || it.Row == null) return;
            bool isDialog = it.Kind == DlgKind.Dialog;
            string what = isDialog
                ? $"Delete dialog \u201C{it.Name}\u201D with all of its controls, events and conditions?"
                : $"Delete control \u201C{it.Name}\u201D and its events and conditions?";
            if (MstMessage(what, "Delete", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;

            // Everything keyed on the dialog or control goes with it; a Control row pointing at a
            // dialog that is gone is the classic way to break the UI sequence.
            foreach (string t in new[] { "Control", "ControlEvent", "ControlCondition", "EventMapping" })
            {
                var st = EnsureTableCached(t);
                if (st == null) continue;
                foreach (DataRow r in st.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (!string.Equals(Col(r, "Dialog_"), it.DialogName, StringComparison.OrdinalIgnoreCase)) continue;
                    if (isDialog || string.Equals(Col(r, t == "Control" ? "Control" : "Control_"), it.Name,
                                                  StringComparison.OrdinalIgnoreCase))
                        r.Delete();
                }
            }
            if (it.Row.RowState != DataRowState.Deleted) it.Row.Delete();
            UpdateEditCount();
            ShowDialogsForm(_dlgSt!);
        }

        private void SelectDlgNode(string dialog, string? control)
        {
            if (DlgTree?.ItemsSource is not System.Collections.IEnumerable roots) return;
            foreach (var o in roots)
            {
                if (o is not DlgItem root) continue;
                foreach (var d in root.Children)
                {
                    if (!string.Equals(d.Name, dialog, StringComparison.OrdinalIgnoreCase)) continue;
                    if (control == null) { d.IsSelected = true; return; }
                    d.IsExpanded = true;
                    foreach (var c in d.Children)
                        if (string.Equals(c.Name, control, StringComparison.OrdinalIgnoreCase))
                        { c.IsSelected = true; return; }
                    return;
                }
            }
        }

        private void ShowDlgEditor(DlgItem item)
        {
            if (DlgEditorHost == null || item.Row == null) return;
            _dlgEditorLoading = true;
            var row = item.Row;

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(112) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
                };
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }
            TextBox Num(string col, string label)
            {
                var (f, b) = MakeRoundedField(Col(row, col), boxBg, boxBdr, valFg, false, null);
                b.ToolTip = "In installer units: one horizontal unit is a twelfth of the dialog font's "
                          + "average character width, not a pixel.";
                AddRow(label, f);
                return b;
            }

            var attrBoxes = new List<(CheckBox box, int bit)>();
            int rawAttr = int.TryParse(Col(row, "Attributes"), out var av) ? av : 0;

            WrapPanel BitPanel((int bit, string label)[] bits)
            {
                var wrap = new WrapPanel();
                foreach (var (bit, label) in bits)
                {
                    var cb = new CheckBox
                    {
                        Content = label, IsChecked = (rawAttr & bit) == bit, Foreground = valFg,
                        FontSize = 12, Width = 172, Margin = new Thickness(0, 5, 8, 5),
                        VerticalContentAlignment = VerticalAlignment.Center
                    };
                    attrBoxes.Add((cb, bit));
                    wrap.Children.Add(cb);
                }
                return wrap;
            }

            TextBox? titleB = null, wB = null, hB = null, hcB = null, vcB = null;
            TextBox? xB = null, yB = null, cwB = null, chB = null, propB = null, textB = null,
                     nextB = null, helpB = null;
            ComboBox? typeBox = null, firstBox = null, defBox = null, cancelBox = null;
            var rawText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
            };

            if (item.Kind == DlgKind.Dialog)
            {
                var (tF, tB) = MakeRoundedField(Col(row, "Title"), boxBg, boxBdr, valFg, false, null);
                titleB = tB; AddRow("Title", tF);
                wB  = Num("Width", "Width");
                hB  = Num("Height", "Height");
                hcB = Num("HCentering", "Centre across");
                vcB = Num("VCentering", "Centre down");

                AddRow("Attributes", BitPanel(DlgAttrBits));

                var names = item.Children.Select(c => c.Name).ToList();
                ComboBox CtlPicker(string col, string label, string tip)
                {
                    var cb = new ComboBox
                    {
                        FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                        Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = Col(row, col),
                        ToolTip = tip
                    };
                    foreach (var n in names) cb.Items.Add(n);
                    AddRow(label, RoundWrapControl(cb, boxBg, boxBdr));
                    return cb;
                }
                firstBox  = CtlPicker("Control_First", "First control", "Takes focus when the dialog opens. Required.");
                defBox    = CtlPicker("Control_Default", "Default", "Activated by Enter.");
                cancelBox = CtlPicker("Control_Cancel", "Cancel", "Activated by Escape.");
            }
            else
            {
                typeBox = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = Col(row, "Type")
                };
                foreach (var t in CtlTypes) typeBox.Items.Add(t);
                AddRow("Type", RoundWrapControl(typeBox, boxBg, boxBdr));

                xB  = Num("X", "X");
                yB  = Num("Y", "Y");
                cwB = Num("Width", "Width");
                chB = Num("Height", "Height");

                var (pF, pB) = MakeRoundedField(Col(row, "Property"), boxBg, boxBdr, valFg, false, null);
                propB = pB;
                pB.ToolTip = "The property this control reads and writes.";
                AddRow("Property", pF);

                var (txF, txB) = MakeRoundedField(Col(row, "Text"), boxBg, boxBdr, valFg, true, null);
                textB = txB; AddRow("Text", txF);

                var (nF, nB) = MakeRoundedField(Col(row, "Control_Next"), boxBg, boxBdr, valFg, false, null);
                nextB = nB;
                nB.ToolTip = "Next control in the tab order.";
                AddRow("Next control", nF);

                var (hF, hB2) = MakeRoundedField(Col(row, "Help"), boxBg, boxBdr, valFg, false, null);
                helpB = hB2; AddRow("Help", hF);

                AddRow("Attributes", BitPanel(CtlCommonBits));

                var typeBits = CtlTypeBits(Col(row, "Type"));
                if (typeBits.Length > 0) AddRow("For this type", BitPanel(typeBits));
                else AddRow("For this type", new TextBlock
                {
                    Text = "No type-specific flags are documented for this control type. Any set on "
                         + "it are left as they are.",
                    FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap
                });
            }

            AddRow("Raw", rawText);

            void Commit()
            {
                if (_dlgEditorLoading) return;
                void S(string c, string v, bool required = false)
                {
                    if (!row.Table.Columns.Contains(c)) return;
                    row[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
                }

                // Only the bits with a checkbox are rewritten; everything else in the original
                // value survives, which is what keeps a type's own flags intact.
                int known = 0;
                foreach (var (_, bit) in attrBoxes) known |= bit;
                int attr = rawAttr & ~known;
                foreach (var (cb, bit) in attrBoxes) if (cb.IsChecked == true) attr |= bit;
                S("Attributes", attr.ToString(), true);

                if (item.Kind == DlgKind.Dialog)
                {
                    S("Title", titleB!.Text);
                    S("Width", wB!.Text.Trim(), true); S("Height", hB!.Text.Trim(), true);
                    S("HCentering", hcB!.Text.Trim(), true); S("VCentering", vcB!.Text.Trim(), true);
                    S("Control_First", firstBox!.Text.Trim(), true);
                    S("Control_Default", defBox!.Text.Trim());
                    S("Control_Cancel", cancelBox!.Text.Trim());
                    item.Update(item.Name,
                        (titleB.Text.Length > 0 ? titleB.Text + "  ·  " : "") + wB.Text + " x " + hB.Text);
                }
                else
                {
                    S("Type", typeBox!.Text.Trim(), true);
                    S("X", xB!.Text.Trim(), true); S("Y", yB!.Text.Trim(), true);
                    S("Width", cwB!.Text.Trim(), true); S("Height", chB!.Text.Trim(), true);
                    S("Property", propB!.Text.Trim());
                    S("Text", textB!.Text);
                    S("Control_Next", nextB!.Text.Trim());
                    S("Help", helpB!.Text.Trim());
                    item.Update(item.Name, typeBox.Text.Trim());
                }

                UpdateEditCount();
                rawText.Text = $"Attributes {attr}  (0x{attr:X})"
                             + (attr != (attr & known) ? $"\nkept from the original: 0x{rawAttr & ~known:X}" : "");
            }

            foreach (var b in new[] { titleB, wB, hB, hcB, vcB, xB, yB, cwB, chB, propB, textB, nextB, helpB })
                if (b != null) b.TextChanged += (_, _) => Commit();
            foreach (var cb in new[] { firstBox, defBox, cancelBox })
                if (cb != null) { cb.SelectionChanged += (_, _) => Commit(); cb.LostFocus += (_, _) => Commit(); }
            foreach (var (cb, _) in attrBoxes)
            { cb.Checked += (_, _) => Commit(); cb.Unchecked += (_, _) => Commit(); }
            if (typeBox != null)
            {
                // The type decides which high bits have names, so the panel is rebuilt for it.
                typeBox.SelectionChanged += (_, _) => { Commit(); ShowDlgEditor(item); };
                typeBox.LostFocus += (_, _) => Commit();
            }

            DlgEditorHost.Content = grid;
            _dlgEditorLoading = false;
            Commit();
            BindDlgSubTable(item);
        }

        private void DlgSubTab_Click(object sender, RoutedEventArgs e)
        {
            if (sender is Button b && b.Tag is string t) _dlgSubTab = t;
            if (DlgTree?.SelectedItem is DlgItem it) BindDlgSubTable(it);
        }

        /// <summary>
        /// Binds the lower grid to whichever of the three behaviour tables is selected, scoped to
        /// the dialog or the one control.
        /// </summary>
        private void BindDlgSubTable(DlgItem item)
        {
            if (DlgSubGrid == null || item.Row == null) return;
            (string table, string[] cols) = _dlgSubTab switch
            {
                "conditions" => ("ControlCondition", new[] { "Control_", "Action", "Condition" }),
                "mapping"    => ("EventMapping", new[] { "Control_", "Event", "Attribute" }),
                _            => ("ControlEvent", new[] { "Control_", "Event", "Argument", "Condition", "Ordering" }),
            };

            var st = EnsureTableOrCreate(table);
            if (st == null) { DlgSubGrid.ItemsSource = null; return; }

            string filter = $"Dialog_ = {SqlLit(item.DialogName)}";
            if (item.Kind == DlgKind.Control) filter += $" AND Control_ = {SqlLit(item.Name)}";

            var view = new DataView(st.Data) { RowFilter = filter, Sort = "Control_" };
            DlgSubGrid.Columns.Clear();
            foreach (var c in cols)
            {
                if (!st.Data.Columns.Contains(c)) continue;
                DlgSubGrid.Columns.Add(new DataGridTextColumn
                {
                    Header = c,
                    Binding = new System.Windows.Data.Binding(c),
                    Width = c == "Condition" || c == "Argument"
                        ? new DataGridLength(1.6, DataGridLengthUnitType.Star)
                        : new DataGridLength(1, DataGridLengthUnitType.Star),
                });
            }
            DlgSubGrid.ItemsSource = view;
            if (DlgSubTitle != null)
                DlgSubTitle.Text = $"{table}  ({view.Count})"
                                 + (item.Kind == DlgKind.Dialog ? "  for the whole dialog" : "  for this control");
        }

        private void DlgSubAdd_Click(object sender, RoutedEventArgs e)
        {
            if (DlgTree?.SelectedItem is not DlgItem item || item.Row == null) return;
            string table = _dlgSubTab switch
            {
                "conditions" => "ControlCondition",
                "mapping"    => "EventMapping",
                _            => "ControlEvent",
            };
            var st = EnsureTableOrCreate(table);
            if (st == null) return;

            // The keys are filled in here: a row without them would not match the filtered view
            // and would look as though nothing had been added.
            var nr = st.Data.NewRow();
            if (st.Data.Columns.Contains("Dialog_"))  nr["Dialog_"] = item.DialogName;
            if (st.Data.Columns.Contains("Control_"))
                nr["Control_"] = item.Kind == DlgKind.Control ? item.Name
                               : item.Children.FirstOrDefault()?.Name ?? "";
            st.Data.Rows.Add(nr);
            UpdateEditCount();
            BindDlgSubTable(item);
        }

        private void DlgSubDel_Click(object sender, RoutedEventArgs e)
        {
            if (DlgSubGrid?.SelectedItem is not DataRowView drv) return;
            if (DlgTree?.SelectedItem is not DlgItem item) return;
            if (drv.Row.RowState != DataRowState.Deleted) drv.Row.Delete();
            UpdateEditCount();
            BindDlgSubTable(item);
        }


        // ══ Scheduled tasks ═════════════════════════════════════════════════
        // Windows Installer has no scheduled-task table, and InstallShield's ISScheduledTask is an
        // authoring table that its build consumes, so it is not in a finished package either. A
        // task that works in any MSI is made by a custom action calling schtasks.exe, which is
        // what this view writes: one action to create the task on install and one to remove it on
        // uninstall, both deferred and without impersonation because the call needs elevation.
        //
        // Type 3106 = 34 (EXE from a directory) | 1024 (deferred) | 2048 (no impersonation).
        // The command line is a formatted string resolved when the install script is written, so
        // [INSTALLDIR] and friends work in it even though the action is deferred.
        private const int TaskCaType = 34 | 0x400 | 0x800;
        private const string TaskCreatePrefix = "SwpTaskCreate_";
        private const string TaskRemovePrefix = "SwpTaskRemove_";

        private static readonly (string tag, string label, bool interval, bool time)[] TaskSchedules =
        {
            ("ONCE",    "Once",              false, true),
            ("DAILY",   "Daily",             true,  true),
            ("WEEKLY",  "Weekly",            true,  true),
            ("MONTHLY", "Monthly",           true,  true),
            ("ONSTART", "When Windows starts", false, false),
            ("ONLOGON", "When a user logs on", false, false),
            ("ONIDLE",  "When the machine is idle", false, false),
        };

        private sealed class TaskData
        {
            public string Key = "", TaskName = "", Program = "", Arguments = "";
            public string Schedule = "DAILY", Interval = "1", StartTime = "09:00", StartDate = "";
            public string RunAs = "SYSTEM", Password = "";
            public bool Highest = true;
        }

        /// <summary>Pulls a /flag's value out of a schtasks command line, handling the quoting the
        /// generator uses. Best effort: a hand-edited command may not round-trip.</summary>
        private static string TaskFlag(string cmd, string flag)
        {
            int i = cmd.IndexOf(flag + " ", StringComparison.OrdinalIgnoreCase);
            if (i < 0) return "";
            int p = i + flag.Length + 1;
            while (p < cmd.Length && cmd[p] == ' ') p++;
            if (p >= cmd.Length) return "";
            if (cmd[p] == '"')
            {
                int end = p + 1;
                while (end < cmd.Length && !(cmd[end] == '"' && cmd[end - 1] != '\\')) end++;
                return cmd.Substring(p + 1, Math.Max(0, end - p - 1)).Replace("\\\"", "\"");
            }
            int sp = cmd.IndexOf(' ', p);
            return sp < 0 ? cmd.Substring(p) : cmd.Substring(p, sp - p);
        }

        private static TaskData ParseTaskCommand(string key, string cmd)
        {
            var d = new TaskData { Key = key, TaskName = TaskFlag(cmd, "/tn") };

            // /tr holds the program and its arguments, the program quoted when it has spaces.
            string tr = TaskFlag(cmd, "/tr").Trim();
            if (tr.StartsWith("\"", StringComparison.Ordinal))
            {
                int close = tr.IndexOf('"', 1);
                if (close > 0)
                {
                    d.Program = tr.Substring(1, close - 1);
                    d.Arguments = tr.Substring(close + 1).Trim();
                }
                else d.Program = tr.Trim('"');
            }
            else
            {
                int sp = tr.IndexOf(' ');
                d.Program = sp < 0 ? tr : tr.Substring(0, sp);
                d.Arguments = sp < 0 ? "" : tr.Substring(sp + 1).Trim();
            }

            string sc = TaskFlag(cmd, "/sc").ToUpperInvariant();
            if (sc.Length > 0) d.Schedule = sc;
            string mo = TaskFlag(cmd, "/mo"); if (mo.Length > 0) d.Interval = mo;
            string st = TaskFlag(cmd, "/st"); if (st.Length > 0) d.StartTime = st;
            d.StartDate = TaskFlag(cmd, "/sd");
            string ru = TaskFlag(cmd, "/ru"); if (ru.Length > 0) d.RunAs = ru;
            d.Password = TaskFlag(cmd, "/rp");
            d.Highest = TaskFlag(cmd, "/rl").Equals("HIGHEST", StringComparison.OrdinalIgnoreCase);
            return d;
        }

        private static string BuildTaskCreate(TaskData d)
        {
            var sch = TaskSchedules.FirstOrDefault(x => x.tag == d.Schedule);
            string tr = d.Arguments.Trim().Length > 0
                ? "\"\\\"" + d.Program + "\\\" " + d.Arguments.Trim() + "\""
                : "\"" + d.Program + "\"";

            var sb = new System.Text.StringBuilder();
            sb.Append("schtasks.exe /create /f");
            sb.Append(" /tn \"").Append(d.TaskName).Append('"');
            sb.Append(" /tr ").Append(tr);
            sb.Append(" /sc ").Append(d.Schedule);
            if (sch.interval && d.Interval.Trim().Length > 0) sb.Append(" /mo ").Append(d.Interval.Trim());
            if (sch.time && d.StartTime.Trim().Length > 0) sb.Append(" /st ").Append(d.StartTime.Trim());
            if (sch.time && d.StartDate.Trim().Length > 0) sb.Append(" /sd ").Append(d.StartDate.Trim());
            if (d.RunAs.Trim().Length > 0) sb.Append(" /ru \"").Append(d.RunAs.Trim()).Append('"');
            if (d.Password.Length > 0) sb.Append(" /rp \"").Append(d.Password).Append('"');
            if (d.Highest) sb.Append(" /rl HIGHEST");
            return sb.ToString();
        }

        private static string BuildTaskRemove(TaskData d) =>
            "schtasks.exe /delete /f /tn \"" + d.TaskName + "\"";

        private TableState? _taskCaSt;
        private bool _taskEditorLoading;

        private void ShowTasksForm(TableState caSt)
        {
            _taskCaSt = caSt;
            var mine = new List<TaskItem>();
            var others = new List<TaskItem>();

            foreach (DataRow r in caSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string action = Col(r, "Action");
                string target = Col(r, "Target");
                if (action.StartsWith(TaskCreatePrefix, StringComparison.OrdinalIgnoreCase))
                {
                    var d = ParseTaskCommand(action.Substring(TaskCreatePrefix.Length), target);
                    mine.Add(new TaskItem(d.TaskName.Length > 0 ? d.TaskName : action,
                        TaskSchedules.FirstOrDefault(x => x.tag == d.Schedule).label ?? d.Schedule)
                    { CreateRow = r, Key = d.Key, Managed = true });
                }
                else if (action.StartsWith(TaskRemovePrefix, StringComparison.OrdinalIgnoreCase))
                    continue;   // paired with its create action, not listed on its own
                else if (target.IndexOf("schtasks", StringComparison.OrdinalIgnoreCase) >= 0)
                    others.Add(new TaskItem(action, "custom action written elsewhere") { CreateRow = r });
            }

            // Pair each managed task with its removal action.
            foreach (var it in mine)
                foreach (DataRow r in caSt.Data.Rows)
                    if (r.RowState != DataRowState.Deleted &&
                        string.Equals(Col(r, "Action"), TaskRemovePrefix + it.Key, StringComparison.OrdinalIgnoreCase))
                    { it.RemoveRow = r; break; }

            mine.Sort((a, b) => string.Compare(a.Name, b.Name, StringComparison.OrdinalIgnoreCase));
            var root = new TaskItem("Scheduled Tasks",
                mine.Count == 1 ? "1 task" : $"{mine.Count} tasks") { IsRoot = true, IsExpanded = true };
            foreach (var it in mine) root.Children.Add(it);

            if (others.Count > 0)
            {
                var g = new TaskItem("Other schtasks custom actions",
                    $"{others.Count} found, not written by SwiftPack") { IsExpanded = true };
                foreach (var it in others) g.Children.Add(it);
                root.Children.Add(g);
            }

            if (TaskTree != null)
                TaskTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<TaskItem> { root };
            if (TaskCount != null) TaskCount.Text = root.Summary;
            ClearTaskEditor();
            if (FormTasksPanel != null) FormTasksPanel.Visibility = Visibility.Visible;
            if (root.Children.Count > 0 && root.Children[0].Managed) root.Children[0].IsSelected = true;
        }

        private void TaskTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is TaskItem it && it.CreateRow != null) ShowTaskEditor(it);
            else ClearTaskEditor();
        }

        private void ClearTaskEditor()
        {
            if (TaskEditorHost != null) TaskEditorHost.Content = null;
        }

        private void TaskMenu_Opened(object sender, RoutedEventArgs e)
        {
            var it = TaskTree?.SelectedItem as TaskItem;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiTaskNew, it == null || it.IsRoot);
            V(MiTaskDelete, it?.Managed == true);
        }

        /// <summary>Puts a task action in the execute sequence and gives it its condition.</summary>
        private void PlaceTaskAction(string action, string after, string condition)
        {
            ScheduleCa("InstallExecuteSequence", action, after);
            var st = EnsureTableCached("InstallExecuteSequence");
            var row = st == null ? null : FindCaSeqRow(st, action);
            if (row != null && row.Table.Columns.Contains("Condition")) row["Condition"] = condition;
        }

        private void TaskNew_Click(object sender, RoutedEventArgs e)
        {
            var caSt = _taskCaSt ?? EnsureTableOrCreate("CustomAction");
            if (caSt == null) return;
            string? typed = PromptText("New Scheduled Task", "Task name", "My Task");
            if (string.IsNullOrWhiteSpace(typed)) return;

            var d = new TaskData
            {
                Key = UniqueKey(caSt.Data, "Action", SanitizeKey(typed.Trim())).Replace(TaskCreatePrefix, ""),
                TaskName = typed.Trim(),
                Program = "[INSTALLDIR]",
            };

            void MakeCa(string action, string target)
            {
                var nr = caSt.Data.NewRow();
                nr["Action"] = action;
                if (caSt.Data.Columns.Contains("Type"))   nr["Type"] = TaskCaType.ToString();
                if (caSt.Data.Columns.Contains("Source")) nr["Source"] = "SystemFolder";
                if (caSt.Data.Columns.Contains("Target")) nr["Target"] = target;
                caSt.Data.Rows.Add(nr);
            }
            MakeCa(TaskCreatePrefix + d.Key, BuildTaskCreate(d));
            MakeCa(TaskRemovePrefix + d.Key, BuildTaskRemove(d));

            // Create after the files are on disk; remove before they are taken away again.
            PlaceTaskAction(TaskCreatePrefix + d.Key, "InstallFiles", "NOT Installed");
            PlaceTaskAction(TaskRemovePrefix + d.Key, "InstallInitialize", "REMOVE=\"ALL\"");

            UpdateEditCount();
            ShowTasksForm(caSt);
            SelectTaskByName(d.TaskName);
        }

        private void TaskDelete_Click(object sender, RoutedEventArgs e)
        {
            if (TaskTree?.SelectedItem is not TaskItem it || !it.Managed) return;
            var caSt = _taskCaSt ?? EnsureTableCached("CustomAction");
            if (caSt == null) return;
            if (MstMessage($"Delete the task \u201C{it.Name}\u201D and both of its custom actions?",
                    "Delete Task", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;

            foreach (string action in new[] { TaskCreatePrefix + it.Key, TaskRemovePrefix + it.Key })
            {
                var seqSt = EnsureTableCached("InstallExecuteSequence");
                var seqRow = seqSt == null ? null : FindCaSeqRow(seqSt, action);
                if (seqRow != null && seqRow.RowState != DataRowState.Deleted) seqRow.Delete();
            }
            foreach (var r in new[] { it.CreateRow, it.RemoveRow })
                if (r is { } row && row.RowState != DataRowState.Deleted) row.Delete();

            UpdateEditCount();
            ShowTasksForm(caSt);
        }

        private void SelectTaskByName(string name)
        {
            if (TaskTree?.ItemsSource is not System.Collections.IEnumerable roots) return;
            foreach (var o in roots)
            {
                if (o is not TaskItem root) continue;
                root.IsExpanded = true;
                foreach (var it in root.Children)
                    if (string.Equals(it.Name, name, StringComparison.OrdinalIgnoreCase))
                    { it.IsSelected = true; return; }
            }
        }

        private void ShowTaskEditor(TaskItem item)
        {
            if (TaskEditorHost == null || item.CreateRow == null) return;
            _taskEditorLoading = true;

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(118) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
                };
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }

            if (!item.Managed)
            {
                // A schtasks call this view did not author: shown, not taken over.
                AddRow("Custom action", new TextBlock
                {
                    Text = Col(item.CreateRow, "Action"), FontSize = 12, Foreground = valFg,
                    TextWrapping = TextWrapping.Wrap
                });
                AddRow("Command", new TextBlock
                {
                    Text = Col(item.CreateRow, "Target"), FontSize = 11,
                    FontFamily = new FontFamily("Consolas"), Foreground = valFg,
                    TextWrapping = TextWrapping.Wrap
                });
                AddRow("", new TextBlock
                {
                    Text = "This package already creates a task through its own custom action. "
                         + "Edit it under Custom actions; this view only manages the ones it wrote itself.",
                    FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap
                });
                TaskEditorHost.Content = grid;
                _taskEditorLoading = false;
                return;
            }

            var d0 = ParseTaskCommand(item.Key, Col(item.CreateRow, "Target"));

            var (nameF, nameB) = MakeRoundedField(d0.TaskName, boxBg, boxBdr, valFg, false, null);
            AddRow("Task name", nameF);

            var (progF, progB) = MakeRoundedField(d0.Program, boxBg, boxBdr, valFg, false, null);
            progB.ToolTip = "The program the task runs. Directory properties work here: the command "
                          + "line is resolved when the install script is written, not when it runs.";
            AddRow("Program", progF);

            var (argF, argB) = MakeRoundedField(d0.Arguments, boxBg, boxBdr, valFg, false, null);
            AddRow("Arguments", argF);

            var schedBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            foreach (var (tag, label, _, _) in TaskSchedules)
                schedBox.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
            int si = Array.FindIndex(TaskSchedules, x => x.tag == d0.Schedule);
            schedBox.SelectedIndex = si >= 0 ? si : 1;
            AddRow("Runs", RoundWrapControl(schedBox, boxBg, boxBdr));

            var (intF, intB) = MakeRoundedField(d0.Interval, boxBg, boxBdr, valFg, false, null);
            intB.ToolTip = "Every N days, weeks or months.";
            AddRow("Every", intF);

            var (timeF, timeB) = MakeRoundedField(d0.StartTime, boxBg, boxBdr, valFg, false, null);
            timeB.ToolTip = "24-hour HH:MM.";
            AddRow("At", timeF);

            var (dateF, dateB) = MakeRoundedField(d0.StartDate, boxBg, boxBdr, valFg, false, null);
            dateB.ToolTip = "Optional first run date, in the target machine's short date format.";
            AddRow("Starting", dateF);

            var (userF, userB) = MakeRoundedField(d0.RunAs, boxBg, boxBdr, valFg, false, null);
            userB.ToolTip = "SYSTEM needs no password. A named account does, and it is stored in "
                          + "the package in clear text unless you hide the target.";
            AddRow("Run as", userF);

            var (pwdF, pwdB) = MakeRoundedField(d0.Password, boxBg, boxBdr, valFg, false, null);
            AddRow("Password", pwdF);

            var cHighest = new CheckBox
            {
                Content = "Run with highest privileges", IsChecked = d0.Highest,
                Foreground = valFg, FontSize = 12, Margin = new Thickness(0, 6, 0, 6)
            };
            AddRow("", cHighest);

            var cmdText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
            };
            AddRow("Commands", cmdText);

            TaskData ReadControls() => new TaskData
            {
                Key = item.Key,
                TaskName = nameB.Text.Trim(), Program = progB.Text.Trim(), Arguments = argB.Text.Trim(),
                Schedule = (schedBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "DAILY",
                Interval = intB.Text.Trim(), StartTime = timeB.Text.Trim(), StartDate = dateB.Text.Trim(),
                RunAs = userB.Text.Trim(), Password = pwdB.Text,
                Highest = cHighest.IsChecked == true,
            };

            void Commit()
            {
                if (_taskEditorLoading || item.CreateRow == null) return;
                var d = ReadControls();
                if (d.TaskName.Length == 0) return;

                var sch = TaskSchedules.FirstOrDefault(x => x.tag == d.Schedule);
                intF.Opacity = sch.interval ? 1.0 : 0.5; intB.IsEnabled = sch.interval;
                timeF.Opacity = sch.time ? 1.0 : 0.5;    timeB.IsEnabled = sch.time;
                dateF.Opacity = sch.time ? 1.0 : 0.5;    dateB.IsEnabled = sch.time;
                bool needsPwd = !d.RunAs.Equals("SYSTEM", StringComparison.OrdinalIgnoreCase)
                             && d.RunAs.Length > 0;
                pwdF.Opacity = needsPwd ? 1.0 : 0.5; pwdB.IsEnabled = needsPwd;

                string create = BuildTaskCreate(d), remove = BuildTaskRemove(d);
                if (item.CreateRow.Table.Columns.Contains("Target")) item.CreateRow["Target"] = create;
                if (item.RemoveRow is { } rr2 && rr2.Table.Columns.Contains("Target")) rr2["Target"] = remove;

                UpdateEditCount();
                item.Update(d.TaskName, sch.label ?? d.Schedule);
                cmdText.Text = "install    " + create + "\nuninstall  " + remove
                             + $"\n\nCustomAction type {TaskCaType}, source SystemFolder, deferred without impersonation";
            }

            foreach (var b in new[] { nameB, progB, argB, intB, timeB, dateB, userB, pwdB })
                b.TextChanged += (_, _) => Commit();
            schedBox.SelectionChanged += (_, _) => Commit();
            cHighest.Checked += (_, _) => Commit(); cHighest.Unchecked += (_, _) => Commit();

            TaskEditorHost.Content = grid;
            _taskEditorLoading = false;
            Commit();
        }


        // ══ Dialog layout canvas ════════════════════════════════════════════
        // Controls are positioned in installer units, not pixels: one horizontal unit is a twelfth
        // of the dialog font's average character width and one vertical unit an eighth of its
        // height. What that comes to depends on the font the target machine resolves, so this
        // canvas is a proportional preview at a fixed scale rather than a promise about pixels.
        // Positions written back are exact; only the drawing is approximate.
        private const double DlgUnitScaleDefault = 1.5;

        private double _dlgScale = DlgUnitScaleDefault;
        private DlgItem? _dlgCanvasDialog;
        private readonly Dictionary<FrameworkElement, DlgItem> _dlgVisuals = new();
        private DlgItem? _dlgDragItem;
        private Point _dlgDragStart;
        private int _dlgDragX, _dlgDragY, _dlgDragW, _dlgDragH;
        private bool _dlgResizing;

        private static int UnitOf(DataRow r, string col) =>
            int.TryParse(Col(r, col), out var v) ? v : 0;

        private void DlgViewToggle_Click(object sender, RoutedEventArgs e)
        {
            bool layout = (sender as Button)?.Tag as string == "layout";
            if (DlgPropsArea != null) DlgPropsArea.Visibility = layout ? Visibility.Collapsed : Visibility.Visible;
            if (DlgCanvasArea != null) DlgCanvasArea.Visibility = layout ? Visibility.Visible : Visibility.Collapsed;
            if (layout) RenderDlgCanvas();
        }

        private void DlgZoom_Click(object sender, RoutedEventArgs e)
        {
            string dir = (sender as Button)?.Tag as string ?? "in";
            _dlgScale = dir switch
            {
                "in"  => Math.Min(4.0, _dlgScale + 0.25),
                "out" => Math.Max(0.5, _dlgScale - 0.25),
                _     => DlgUnitScaleDefault,
            };
            RenderDlgCanvas();
        }

        /// <summary>The dialog a canvas should show for the current selection: the dialog itself,
        /// or the one a selected control belongs to.</summary>
        private DlgItem? DlgForCanvas()
        {
            if (DlgTree?.SelectedItem is not DlgItem it) return null;
            if (it.Kind == DlgKind.Dialog) return it;
            if (it.Kind != DlgKind.Control) return null;
            if (DlgTree.ItemsSource is not System.Collections.IEnumerable roots) return null;
            foreach (var o in roots)
            {
                if (o is not DlgItem root) continue;
                foreach (var d in root.Children)
                    if (string.Equals(d.Name, it.DialogName, StringComparison.OrdinalIgnoreCase)) return d;
            }
            return null;
        }

        private void RenderDlgCanvas()
        {
            if (DlgCanvas == null) return;
            DlgCanvas.Children.Clear();
            _dlgVisuals.Clear();

            var dlg = DlgForCanvas();
            _dlgCanvasDialog = dlg;
            if (dlg?.Row == null)
            {
                if (DlgCanvasInfo != null) DlgCanvasInfo.Text = "Select a dialog to lay out.";
                DlgCanvas.Width = DlgCanvas.Height = 0;
                return;
            }

            int dw = UnitOf(dlg.Row, "Width"), dh = UnitOf(dlg.Row, "Height");
            if (dw <= 0) dw = 370;
            if (dh <= 0) dh = 270;

            double sc = _dlgScale;
            const double TitleH = 20;
            DlgCanvas.Width = dw * sc;
            DlgCanvas.Height = dh * sc + TitleH;

            Brush fg     = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;
            Brush muted  = (Application.Current.TryFindResource("TextMutedBrush")     as Brush) ?? Brushes.Gray;
            Brush bdr    = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            var faceBrush  = new SolidColorBrush(Color.FromArgb(0x18, 0x88, 0x88, 0x88));
            var titleBrush = new SolidColorBrush(Color.FromArgb(0x2A, 0x6C, 0x63, 0xFF));
            var selBrush   = new SolidColorBrush(Color.FromRgb(0x6C, 0x63, 0xFF));

            // Dialog face and a title strip, so the canvas reads as a window rather than a grid.
            var face = new Border
            {
                Width = dw * sc, Height = dh * sc + TitleH,
                Background = faceBrush, BorderBrush = bdr, BorderThickness = new Thickness(1),
            };
            Canvas.SetLeft(face, 0); Canvas.SetTop(face, 0);
            DlgCanvas.Children.Add(face);

            var titleBar = new Border
            {
                Width = dw * sc - 2, Height = TitleH, Background = titleBrush,
                Child = new TextBlock
                {
                    Text = DlgDisplayText(Col(dlg.Row, "Title")) is { Length: > 0 } t ? t : dlg.Name,
                    FontSize = 11, Margin = new Thickness(6, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center, Foreground = fg
                }
            };
            Canvas.SetLeft(titleBar, 1); Canvas.SetTop(titleBar, 1);
            DlgCanvas.Children.Add(titleBar);

            string selectedName = DlgTree?.SelectedItem is DlgItem sel && sel.Kind == DlgKind.Control
                ? sel.Name : "";

            // Controls parked on one spot. MSI dialogs stack runtime alternatives on top of each
            // other and show one at a time: ErrorDlg keeps its seven buttons on a single rectangle
            // and reveals the subset the message needs, ProgressDlg does the same with its status
            // lines. Drawn all at once they overtype each other into the garble the preview showed,
            // so each spot draws one control: the tree-selected one when it is in the pile,
            // otherwise the first the dialog initially shows, otherwise the first authored.
            static bool VisibleBit(DlgItem it)
                => it.Row != null && int.TryParse(Col(it.Row, "Attributes"), out var a) && (a & 0x1) != 0;

            var byRect = new Dictionary<string, List<DlgItem>>();
            foreach (var c in dlg.Children)
            {
                if (c.Row == null) continue;
                string k = UnitOf(c.Row, "X") + "," + UnitOf(c.Row, "Y") + ","
                         + Math.Max(1, UnitOf(c.Row, "Width")) + "," + Math.Max(1, UnitOf(c.Row, "Height"));
                if (!byRect.TryGetValue(k, out var pileList)) byRect[k] = pileList = new List<DlgItem>();
                pileList.Add(c);
            }

            foreach (var c in dlg.Children)
            {
                if (c.Row == null) continue;
                int x = UnitOf(c.Row, "X"), y = UnitOf(c.Row, "Y");
                int w = Math.Max(1, UnitOf(c.Row, "Width")), h = Math.Max(1, UnitOf(c.Row, "Height"));
                int attr = int.TryParse(Col(c.Row, "Attributes"), out var av) ? av : 0;
                bool visible = (attr & 0x1) != 0;
                bool isSel = string.Equals(c.Name, selectedName, StringComparison.OrdinalIgnoreCase);

                var pile = byRect[x + "," + y + "," + w + "," + h];
                if (pile.Count > 1)
                {
                    var rep = (selectedName.Length > 0
                              ? pile.FirstOrDefault(p => string.Equals(p.Name, selectedName, StringComparison.OrdinalIgnoreCase))
                              : null)
                           ?? pile.FirstOrDefault(VisibleBit)
                           ?? pile[0];
                    if (!ReferenceEquals(c, rep)) continue;
                }

                string ctype = Col(c.Row, "Type"), ctext = Col(c.Row, "Text");
                string tl = ctype.ToLowerInvariant();
                // Bitmap and Icon name a Binary row rather than carrying a caption, and so does a
                // push button carrying the Bitmap (0x40000) or Icon (0x80000) attribute - the Up
                // and New Folder buttons on BrowseDlg. The picture is fetched here where the
                // package is in reach; the builder itself is static.
                bool imageButton = tl == "pushbutton" && (attr & 0x000C0000) != 0;
                string imgNote = "";
                var img = tl == "bitmap" || tl == "icon" || imageButton
                    ? BinaryImage(ctext, out imgNote) : null;

                var vis = BuildControlVisual(ctype, ctext, c.Name,
                                             w * sc, h * sc, visible, isSel, fg, muted, bdr, selBrush, img);
                Canvas.SetLeft(vis, x * sc);
                Canvas.SetTop(vis, y * sc + TitleH);
                vis.Cursor = Cursors.SizeAll;
                vis.ToolTip = $"{c.Name}  ({Col(c.Row, "Type")})\n{x}, {y}  {w} x {h} units"
                            + (visible ? "" : "\nNot visible")
                            + (img == null && imgNote.Length > 0 ? "\nImage not shown: " + imgNote : "")
                            + (pile.Count > 1
                                ? "\nStacked with: "
                                  + string.Join(", ", pile.Where(p => !ReferenceEquals(p, c)).Select(p => p.Name))
                                  + "\nThe installer shows one of these at a time; select one in the tree to draw it."
                                : "");
                DlgCanvas.Children.Add(vis);
                _dlgVisuals[vis] = c;

                if (isSel)
                {
                    // One grip, bottom right: enough to resize without eight hit targets on a
                    // control that may only be a few units tall.
                    // Fully qualified: this file does not use System.Windows.Shapes, and adding
                    // the using would pull Path and Ellipse into scope alongside the IO and Media
                    // types already here.
                    var grip = new System.Windows.Shapes.Rectangle
                    {
                        Width = 8, Height = 8, Fill = selBrush, Cursor = Cursors.SizeNWSE,
                        Tag = "grip"
                    };
                    Canvas.SetLeft(grip, (x + w) * sc - 4);
                    Canvas.SetTop(grip, (y + h) * sc + TitleH - 4);
                    grip.MouseLeftButtonDown += (s2, e2) =>
                    {
                        _dlgDragItem = c; _dlgResizing = true;
                        _dlgDragStart = e2.GetPosition(DlgCanvas);
                        _dlgDragX = x; _dlgDragY = y; _dlgDragW = w; _dlgDragH = h;
                        DlgCanvas.CaptureMouse(); e2.Handled = true;
                    };
                    DlgCanvas.Children.Add(grip);
                }

                var cc = c;
                int cx = x, cy = y, cw = w, ch = h;
                vis.MouseLeftButtonDown += (s2, e2) =>
                {
                    cc.IsSelected = true;                 // keeps the tree and the canvas in step
                    _dlgDragItem = cc; _dlgResizing = false;
                    _dlgDragStart = e2.GetPosition(DlgCanvas);
                    _dlgDragX = cx; _dlgDragY = cy; _dlgDragW = cw; _dlgDragH = ch;
                    DlgCanvas.CaptureMouse(); e2.Handled = true;
                };
            }

            if (DlgCanvasInfo != null)
                DlgCanvasInfo.Text = $"{dlg.Name}  ·  {dw} x {dh} units  ·  {dlg.Children.Count} control(s)"
                                   + $"  ·  {_dlgScale:0.##}x preview";
        }

        // Decoded Binary rows, keyed by name. The canvas is rebuilt on every zoom step and every
        // selection change, and re-reading a bitmap out of the package each time would make both
        // feel slow. Cleared when a package is opened.
        private readonly Dictionary<string, (System.Windows.Media.ImageSource? Img, string Note)> _binaryImages =
            new(StringComparer.OrdinalIgnoreCase);

        /// <summary>
        /// The picture behind a Bitmap or Icon control, or null when the row is missing or holds
        /// something undecodable. A Bitmap control's Text column is not a caption: it is the name of
        /// the Binary row holding the image, which is why these controls used to render as the word
        /// "WixUI_Bmp_Banner" sitting in a box.
        /// </summary>
        private System.Windows.Media.ImageSource? BinaryImage(string binaryName, out string note)
        {
            note = "";
            if (binaryName.Length == 0) { note = "the control's Text names no Binary row"; return null; }
            if (_binaryImages.TryGetValue(binaryName, out var cached))
            { note = cached.Note; return cached.Img; }

            System.Windows.Media.ImageSource? img = null;
            try
            {
                // A binary browsed in this session has no row bytes to read yet, the same as the
                // icons: the source file it came from is the truth until the package is saved.
                byte[]? bytes = null;
                if (_addedBinarySources.TryGetValue(binaryName, out var src) && File.Exists(src))
                    bytes = File.ReadAllBytes(src);
                bytes ??= ReadTableStream(_msiPath, "Binary", "Name", binaryName, out note);
                if (bytes is { Length: > 0 })
                {
                    try
                    {
                        using var ms = new System.IO.MemoryStream(bytes);
                        var dec = System.Windows.Media.Imaging.BitmapDecoder.Create(ms,
                            System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,
                            System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);
                        if (dec.Frames.Count > 0)
                        {
                            var best = dec.Frames[0];
                            foreach (var f in dec.Frames)
                                if (f.PixelWidth * f.PixelHeight > best.PixelWidth * best.PixelHeight) best = f;
                            best.Freeze();
                            img = best;
                            note = "";
                        }
                        else note = "the row holds no image frames";
                    }
                    catch { note = "the row's bytes are not a picture Windows can decode"; }
                }
            }
            catch (Exception ex) { note = ex.Message; }
            _binaryImages[binaryName] = (img, note);   // failures cache too, so each is tried once
            return img;
        }

        /// <summary>
        /// The part of an MSI control's text a preview should actually draw.
        ///
        /// Two things in front of it are markup rather than content. A leading {\StyleName} picks a
        /// row of the TextStyle table for the rest of the string, which is why every WiX title read
        /// "{\WixUI_Font_Title}Custom Setup" here. And an ampersand marks the next character as the
        /// keyboard accelerator; Windows itself hides those until Alt is pressed, so dropping it is
        /// what the dialog normally looks like. A doubled ampersand is a literal one and survives.
        /// </summary>
        private static string DlgDisplayText(string text)
        {
            string s = text ?? "";
            while (s.Length > 2 && s[0] == '{' && (s[1] == '\\' || s[1] == '&'))
            {
                int end = s.IndexOf('}');
                if (end < 0) break;
                s = s.Substring(end + 1);
            }
            int nl = s.IndexOfAny(new[] { '\r', '\n' });
            if (nl >= 0) s = s.Substring(0, nl);
            return s.Replace("&&", "\u0001").Replace("&", "").Replace("\u0001", "&");
        }

        private static FrameworkElement BuildControlVisual(
            string type, string text, string name, double w, double h,
            bool visible, bool selected, Brush fg, Brush muted, Brush bdr, Brush sel,
            System.Windows.Media.ImageSource? image = null)
        {
            string label = DlgDisplayText(text);
            // No fallback to the control's name. An empty Text is what a runtime-populated control
            // looks like - PathEdit, DirectoryCombo, ActionText - and the preview printing its own
            // control names into them is what read as broken next to InstallShield's blank boxes.
            // The name stays in the tooltip and the tree.
            if (label.Length > 60) label = label.Substring(0, 60) + "...";

            string t = type.ToLowerInvariant();
            var inner = new TextBlock
            {
                Text = label, FontSize = 10, Foreground = visible ? fg : muted,
                TextTrimming = TextTrimming.CharacterEllipsis,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(3, 0, 3, 0),
                HorizontalAlignment = t == "pushbutton" ? HorizontalAlignment.Center : HorizontalAlignment.Left,
            };

            var box = new Border
            {
                Width = Math.Max(2, w), Height = Math.Max(2, h),
                BorderBrush = selected ? sel : bdr,
                BorderThickness = new Thickness(selected ? 2 : 1),
                Child = inner,
            };

            switch (t)
            {
                case "pushbutton":
                    box.CornerRadius = new CornerRadius(3);
                    box.Background = new SolidColorBrush(Color.FromArgb(0x30, 0x88, 0x88, 0x88));
                    if (image != null)
                    {
                        // A button with the Bitmap or Icon attribute names a Binary row in Text -
                        // BrowseDlg's Up and New Folder buttons - so the name is a lookup key, not
                        // a caption, and the picture is what the button shows.
                        box.Child = new Image
                        {
                            Source = image, Stretch = Stretch.Uniform, Margin = new Thickness(2)
                        };
                    }
                    break;
                case "edit": case "maskededit": case "pathedit":
                    box.Background = new SolidColorBrush(Color.FromArgb(0x22, 0xFF, 0xFF, 0xFF));
                    break;
                case "line":
                    box.Height = 1; box.BorderThickness = new Thickness(0, 1, 0, 0); box.Child = null;
                    break;
                case "groupbox":
                    box.Background = Brushes.Transparent;
                    inner.VerticalAlignment = VerticalAlignment.Top;
                    break;
                case "bitmap": case "icon":
                    if (image != null)
                    {
                        // Uniform, not Fill: Windows Installer stretches a bitmap to its control,
                        // but a banner squashed into the wrong aspect ratio reads as a layout fault
                        // that is not there. The control's own box still shows the real bounds.
                        box.Background = Brushes.Transparent;
                        box.Child = new Image
                        {
                            Source = image, Stretch = Stretch.Uniform,
                            HorizontalAlignment = HorizontalAlignment.Center,
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(1),
                        };
                    }
                    else
                    {
                        box.Background = new SolidColorBrush(Color.FromArgb(0x22, 0x4C, 0x9A, 0xFF));
                        inner.Text = label.Length > 0 ? label : "(image)";
                        inner.HorizontalAlignment = HorizontalAlignment.Center;
                    }
                    break;
                case "progressbar":
                    box.Background = new SolidColorBrush(Color.FromArgb(0x33, 0x34, 0xC7, 0x7B));
                    break;
                case "checkbox": case "radiobuttongroup":
                    box.Background = Brushes.Transparent;
                    inner.Text = "\u2610 " + label;
                    break;
                case "combobox": case "directorycombo":
                    box.Background = new SolidColorBrush(Color.FromArgb(0x22, 0xFF, 0xFF, 0xFF));
                    inner.Text = label.Length > 0 ? label + "  \u25be" : "\u25be";
                    inner.HorizontalAlignment = label.Length > 0
                        ? HorizontalAlignment.Left : HorizontalAlignment.Right;
                    break;
                case "listbox": case "listview":
                case "directorylist": case "selectiontree": case "volumecostlist":
                    // Runtime-filled panes. When Text is present at all ("Tree of selections") it
                    // is an accessible name rather than content, so the pane draws blank, which is
                    // what the installer first shows and what InstallShield draws.
                    box.Background = new SolidColorBrush(Color.FromArgb(0x22, 0xFF, 0xFF, 0xFF));
                    inner.Text = "";
                    break;
                case "text": case "scrollabletext":
                    box.Background = Brushes.Transparent;
                    box.BorderThickness = new Thickness(selected ? 2 : 0);
                    break;
                default:
                    box.Background = Brushes.Transparent;
                    break;
            }

            if (!visible)
            {
                // A control the dialog does not show is drawn as an outline so it can still be
                // found and moved, rather than being invisible here too.
                box.BorderBrush = muted;
                box.BorderThickness = new Thickness(selected ? 2 : 1);
                box.Opacity = 0.55;
            }
            return box;
        }

        private void DlgCanvas_MouseMove(object sender, MouseEventArgs e)
        {
            if (_dlgDragItem?.Row == null || e.LeftButton != MouseButtonState.Pressed) return;

            var now = e.GetPosition(DlgCanvas);
            int dx = (int)Math.Round((now.X - _dlgDragStart.X) / _dlgScale);
            int dy = (int)Math.Round((now.Y - _dlgDragStart.Y) / _dlgScale);
            var row = _dlgDragItem.Row;

            if (_dlgResizing)
            {
                SetUnit(row, "Width", Math.Max(1, _dlgDragW + dx));
                SetUnit(row, "Height", Math.Max(1, _dlgDragH + dy));
            }
            else
            {
                SetUnit(row, "X", Math.Max(0, _dlgDragX + dx));
                SetUnit(row, "Y", Math.Max(0, _dlgDragY + dy));
            }
            RenderDlgCanvas();
        }

        private static void SetUnit(DataRow r, string col, int v)
        {
            if (r.Table.Columns.Contains(col)) r[col] = v.ToString();
        }

        private void DlgCanvas_MouseUp(object sender, MouseButtonEventArgs e)
        {
            if (_dlgDragItem != null) UpdateEditCount();
            _dlgDragItem = null; _dlgResizing = false;
            DlgCanvas?.ReleaseMouseCapture();
        }

        private void DlgCanvas_KeyDown(object sender, KeyEventArgs e)
        {
            if (DlgTree?.SelectedItem is not DlgItem it || it.Kind != DlgKind.Control || it.Row == null) return;
            int step = (Keyboard.Modifiers & ModifierKeys.Shift) != 0 ? 5 : 1;
            bool sizing = (Keyboard.Modifiers & ModifierKeys.Control) != 0;

            string colX = sizing ? "Width" : "X", colY = sizing ? "Height" : "Y";
            int min = sizing ? 1 : 0;
            switch (e.Key)
            {
                case Key.Left:  SetUnit(it.Row, colX, Math.Max(min, UnitOf(it.Row, colX) - step)); break;
                case Key.Right: SetUnit(it.Row, colX, UnitOf(it.Row, colX) + step); break;
                case Key.Up:    SetUnit(it.Row, colY, Math.Max(min, UnitOf(it.Row, colY) - step)); break;
                case Key.Down:  SetUnit(it.Row, colY, UnitOf(it.Row, colY) + step); break;
                default: return;
            }
            UpdateEditCount();
            RenderDlgCanvas();
            e.Handled = true;
        }


        // ══ Certificates ════════════════════════════════════════════════════
        // Two different things share the name. A package can *carry* certificates, in
        // MsiDigitalCertificate, used to verify patches, the package itself or an external cab;
        // those are binary streams, and this editor writes rows as SQL, which cannot carry one, so
        // they are shown and can be removed but not added. A package can also *install* a
        // certificate into a Windows store, which is not a Windows Installer feature at all and is
        // done with certutil.exe from a custom action. That half is written here.
        //
        // The store scope decides the impersonation bit, and getting it wrong is silent: a
        // deferred action without impersonation runs as SYSTEM, so a "user" store would be
        // SYSTEM's store rather than the installing user's.
        private const int CertCaSystem = 34 | 0x400 | 0x800;   // 3106, machine store
        private const int CertCaUser   = 34 | 0x400;           // 1058, the installing user's store
        private const string CertAddPrefix = "SwpCertAdd_";
        private const string CertDelPrefix = "SwpCertDel_";

        private static readonly (string tag, string label)[] CertStores =
        {
            ("Root",             "Trusted Root Certification Authorities"),
            ("CA",               "Intermediate Certification Authorities"),
            ("My",               "Personal"),
            ("TrustedPublisher", "Trusted Publishers"),
            ("TrustedPeople",    "Trusted People"),
            ("AuthRoot",         "Third-Party Root Certification Authorities"),
            ("Disallowed",       "Untrusted Certificates"),
        };

        private sealed class CertData
        {
            public string Key = "", File = "", Store = "Root", RemoveBy = "";
            public bool MachineStore = true;
        }

        private static string BuildCertAdd(CertData d) =>
            "certutil.exe -f" + (d.MachineStore ? "" : " -user")
          + " -addstore \"" + d.Store + "\" \"" + d.File + "\"";

        private static string BuildCertDel(CertData d) =>
            "certutil.exe" + (d.MachineStore ? "" : " -user")
          + " -delstore \"" + d.Store + "\" \"" + d.RemoveBy + "\"";

        private static CertData ParseCertCommand(string key, string cmd)
        {
            var d = new CertData
            {
                Key = key,
                MachineStore = cmd.IndexOf(" -user", StringComparison.OrdinalIgnoreCase) < 0,
            };
            // Both forms end with two quoted arguments: the store, then the file or the name.
            var q = System.Text.RegularExpressions.Regex.Matches(cmd, "\"([^\"]*)\"");
            if (q.Count >= 1) d.Store = q[0].Groups[1].Value;
            if (q.Count >= 2) d.File = q[1].Groups[1].Value;
            return d;
        }

        private TableState? _certCaSt;
        private bool _certEditorLoading;

        private void ShowCertsForm(TableState caSt)
        {
            _certCaSt = caSt;
            var managed = new List<CertItem>();
            var foreign = new List<CertItem>();

            foreach (DataRow r in caSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string action = Col(r, "Action"), target = Col(r, "Target");
                if (action.StartsWith(CertAddPrefix, StringComparison.OrdinalIgnoreCase))
                {
                    var d = ParseCertCommand(action.Substring(CertAddPrefix.Length), target);
                    string store = CertStores.FirstOrDefault(x => x.tag == d.Store).label ?? d.Store;
                    managed.Add(new CertItem(CertKind.Managed,
                        d.File.Length > 0 ? System.IO.Path.GetFileName(d.File) : action,
                        store + (d.MachineStore ? "  ·  machine" : "  ·  current user"))
                    { AddRow = r, Key = d.Key });
                }
                else if (action.StartsWith(CertDelPrefix, StringComparison.OrdinalIgnoreCase)) continue;
                else if (target.IndexOf("certutil", StringComparison.OrdinalIgnoreCase) >= 0
                      || target.IndexOf("-addstore", StringComparison.OrdinalIgnoreCase) >= 0)
                    foreign.Add(new CertItem(CertKind.Foreign, action, "custom action written elsewhere")
                    { AddRow = r });
            }

            foreach (var it in managed)
                foreach (DataRow r in caSt.Data.Rows)
                    if (r.RowState != DataRowState.Deleted &&
                        string.Equals(Col(r, "Action"), CertDelPrefix + it.Key, StringComparison.OrdinalIgnoreCase))
                    { it.DelRow = r; break; }

            managed.Sort((a, b) => string.Compare(a.Name, b.Name, StringComparison.OrdinalIgnoreCase));
            var root = new CertItem(CertKind.Root, "Certificates",
                managed.Count == 1 ? "1 installed" : $"{managed.Count} installed") { IsExpanded = true };
            foreach (var it in managed) root.Children.Add(it);

            // The certificates the package carries, and what each one is for.
            var signing = new CertItem(CertKind.Group, "Signing certificates in the package", "")
            { IsExpanded = true };
            var certSt = EnsureTableCached("MsiDigitalCertificate");
            if (certSt != null)
                foreach (DataRow r in certSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string key = Col(r, "DigitalCertificate");
                    if (key.Length == 0) continue;
                    signing.Children.Add(new CertItem(CertKind.Signing, key, CertUsage(key))
                    { AddRow = r, Key = key });
                }
            // Added only when the package carries some, the way the "Other certutil" group below
            // already works. An empty group is a row that says "none" under a root that has just
            // said the same thing, and it cannot be opened or acted on.
            if (signing.Children.Count > 0)
            {
                signing.Update(signing.Name, $"{signing.Children.Count} carried");
                root.Children.Add(signing);
            }

            if (foreign.Count > 0)
            {
                var g = new CertItem(CertKind.Group, "Other certutil custom actions",
                    $"{foreign.Count} found, not written by SwiftPack") { IsExpanded = true };
                foreach (var it in foreign) g.Children.Add(it);
                root.Children.Add(g);
            }

            if (CertTree != null)
                CertTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<CertItem> { root };
            if (CertCount != null) CertCount.Text = root.Summary;
            ClearCertEditor();
            if (FormCertsPanel != null) FormCertsPanel.Visibility = Visibility.Visible;
            var first = root.Children.FirstOrDefault(c => c.Kind == CertKind.Managed);
            if (first != null) first.IsSelected = true;
        }

        /// <summary>What a carried certificate is used for, read from the three tables that can
        /// point at it.</summary>
        private string CertUsage(string key)
        {
            var uses = new List<string>();
            void Check(string table, string col, string what)
            {
                var st = EnsureTableCached(table);
                if (st == null || !st.Data.Columns.Contains(col)) return;
                foreach (DataRow r in st.Data.Rows)
                    if (r.RowState != DataRowState.Deleted &&
                        string.Equals(Col(r, col), key, StringComparison.OrdinalIgnoreCase))
                    { uses.Add(what); return; }
            }
            Check("MsiPatchCertificate", "DigitalCertificate_", "signs patches for this product");
            Check("MsiPackageCertificate", "DigitalCertificate_", "signs the package");
            Check("MsiDigitalSignature", "DigitalCertificate_", "signs an external cabinet");
            return uses.Count == 0 ? "carried but never referenced" : string.Join("  ·  ", uses);
        }

        private void CertTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is CertItem it && it.AddRow != null) ShowCertEditor(it);
            else ClearCertEditor();
        }

        private void ClearCertEditor()
        {
            if (CertEditorHost != null) CertEditorHost.Content = null;
        }

        private void CertMenu_Opened(object sender, RoutedEventArgs e)
        {
            var it = CertTree?.SelectedItem as CertItem;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiCertNew, it == null || it.Kind == CertKind.Root);
            V(MiCertDelete, it?.Kind == CertKind.Managed || it?.Kind == CertKind.Signing);
        }

        private void CertNew_Click(object sender, RoutedEventArgs e)
        {
            var caSt = _certCaSt ?? EnsureTableOrCreate("CustomAction");
            if (caSt == null) return;
            // The package's own file tree, not a disk browser: certutil reads the .cer at install
            // time on the target machine, so the file has to be one this package installs. The
            // picker returns [#FileKey], which Windows Installer resolves to wherever that file
            // actually lands - so the command keeps working if the folder is retargeted later.
            string? typed = PickFileFromPackage("Select a file", "");
            if (string.IsNullOrWhiteSpace(typed)) return;

            // Both custom actions below are type 34, whose Source column holds a DIRECTORY key
            // rather than a path, and both name SystemFolder. A package that never referenced
            // SystemFolder has no such row, and the action then resolves to nothing at install
            // time. SystemFolder is authored under WindowsFolder, so that has to exist too.
            EnsureSystemFolderDirectories();

            // RemoveBy is what "certutil -delstore" is handed, so it has to be a certificate
            // identifier rather than a file reference. Strip the [#...] wrapper first: left in,
            // the uninstall command would carry a File key that -delstore cannot match, and the
            // custom action name would be built from it too. It stays a starting point either
            // way, editable in the certificate editor, since a package whose File key is mangled
            // gives no better name to guess from than the old disk path did.
            string certRef  = typed.Trim();
            string certName = certRef.StartsWith("[#", StringComparison.Ordinal) && certRef.EndsWith("]", StringComparison.Ordinal)
                ? certRef.Substring(2, certRef.Length - 3)
                : certRef;

            var d = new CertData
            {
                File = certRef,
                Store = "Root",
                MachineStore = true,
                RemoveBy = System.IO.Path.GetFileNameWithoutExtension(certName),
            };
            // Compared in its PREFIXED form: Action holds "SwpCertAdd_<key>", so handing UniqueKey
            // the bare key matches nothing and it hands the same key back every time. Picking the
            // same .cer twice would then write two rows under one Action name.
            d.Key = UniqueKey(caSt.Data, "Action",
                CertAddPrefix + SanitizeKey(d.RemoveBy.Length > 0 ? d.RemoveBy : "cert")).Substring(CertAddPrefix.Length);

            void MakeCa(string action, string target)
            {
                var nr = caSt.Data.NewRow();
                nr["Action"] = action;
                if (caSt.Data.Columns.Contains("Type"))   nr["Type"] = CertCaSystem.ToString();
                if (caSt.Data.Columns.Contains("Source")) nr["Source"] = "SystemFolder";
                if (caSt.Data.Columns.Contains("Target")) nr["Target"] = target;
                caSt.Data.Rows.Add(nr);
            }
            MakeCa(CertAddPrefix + d.Key, BuildCertAdd(d));
            MakeCa(CertDelPrefix + d.Key, BuildCertDel(d));

            // The .cer has to be on disk before certutil reads it; removal does not need the file.
            PlaceTaskAction(CertAddPrefix + d.Key, "InstallFiles", "NOT Installed");
            PlaceTaskAction(CertDelPrefix + d.Key, "InstallInitialize", "REMOVE=\"ALL\"");

            UpdateEditCount();
            ShowCertsForm(caSt);
        }

        /// <summary>
        /// Puts WindowsFolder and SystemFolder in the Directory table when they are missing, which
        /// is what a type 34 custom action needs to resolve its Source. Both the certutil actions
        /// and the pnputil ones name SystemFolder, so both go through here. Both folders are
        /// standard Windows Installer folder properties, so they carry no DefaultDir of their own
        /// beyond the canonical authoring: WindowsFolder sits under TARGETDIR as ".", and
        /// SystemFolder sits under WindowsFolder as "System32".
        ///
        /// Rows already present are left exactly as they are, including a parent that differs from
        /// the canonical one: a package that authors these itself knows where they belong, and
        /// re-homing a folder other rows already point at would move real content.
        /// </summary>
        private void EnsureSystemFolderDirectories()
        {
            var dirSt = EnsureTableOrCreate("Directory");
            if (dirSt == null || !dirSt.Data.Columns.Contains("Directory")) return;

            // TARGETDIR is the root every package defines, but take the tree's root when it has
            // resolved to something else rather than inventing a parent that is not there.
            string rootKey = TargetDirNode()?.Key ?? "TARGETDIR";
            bool added = false;

            void Ensure(string key, string parent, string defaultDir)
            {
                // Directory is the table's key, so a second row under the same name could not be
                // written. Adopt a live row, and undelete one removed earlier in this session,
                // rather than staging a duplicate either way.
                if (FindLiveRow(dirSt, "Directory", key) != null) return;
                if (UndeleteDirRow(dirSt, key) != null) { added = true; return; }

                var nr = dirSt.Data.NewRow();
                nr["Directory"] = key;
                if (dirSt.Data.Columns.Contains("Directory_Parent")) nr["Directory_Parent"] = parent;
                if (dirSt.Data.Columns.Contains("DefaultDir"))       nr["DefaultDir"]       = defaultDir;
                dirSt.Data.Rows.Add(nr);
                added = true;
            }

            // WindowsFolder first: SystemFolder names it as its parent.
            Ensure("WindowsFolder", rootKey,         ".");
            Ensure("SystemFolder",  "WindowsFolder", "System32");

            // The Files tree is cached per MSI and updated in place by its own edits, so a row
            // added from here would not show until the package was reopened.
            if (added) { _dirRoots = null; _dirTreeBuiltFor = "\0"; }
        }

        private void CertDelete_Click(object sender, RoutedEventArgs e)
        {
            if (CertTree?.SelectedItem is not CertItem it || it.AddRow == null) return;
            var caSt = _certCaSt ?? EnsureTableCached("CustomAction");

            if (it.Kind == CertKind.Signing)
            {
                if (MstMessage($"Remove certificate \u201C{it.Key}\u201D and everything that refers to it?",
                        "Delete Certificate", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
                foreach (string t in new[] { "MsiPatchCertificate", "MsiPackageCertificate", "MsiDigitalSignature" })
                {
                    var st = EnsureTableCached(t);
                    if (st == null || !st.Data.Columns.Contains("DigitalCertificate_")) continue;
                    foreach (DataRow r in st.Data.Rows)
                        if (r.RowState != DataRowState.Deleted &&
                            string.Equals(Col(r, "DigitalCertificate_"), it.Key, StringComparison.OrdinalIgnoreCase))
                            r.Delete();
                }
                if (it.AddRow.RowState != DataRowState.Deleted) it.AddRow.Delete();
            }
            else
            {
                if (MstMessage($"Delete \u201C{it.Name}\u201D and both of its custom actions?",
                        "Delete Certificate", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
                foreach (string action in new[] { CertAddPrefix + it.Key, CertDelPrefix + it.Key })
                {
                    var seqSt = EnsureTableCached("InstallExecuteSequence");
                    var seqRow = seqSt == null ? null : FindCaSeqRow(seqSt, action);
                    if (seqRow != null && seqRow.RowState != DataRowState.Deleted) seqRow.Delete();
                }
                foreach (var r in new[] { it.AddRow, it.DelRow })
                    if (r is { } row && row.RowState != DataRowState.Deleted) row.Delete();
            }

            UpdateEditCount();
            if (caSt != null) ShowCertsForm(caSt);
        }

        private void ShowCertEditor(CertItem item)
        {
            if (CertEditorHost == null || item.AddRow == null) return;
            _certEditorLoading = true;

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(118) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
                };
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }
            TextBlock Note(string t) => new TextBlock
            {
                Text = t, FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap
            };

            if (item.Kind == CertKind.Signing)
            {
                AddRow("Key", new TextBlock { Text = item.Key, FontSize = 12, Foreground = valFg });
                AddRow("Used for", Note(CertUsage(item.Key)));
                AddRow("", Note("The certificate itself is a binary stream in MsiDigitalCertificate. "
                              + "SwiftPack writes table rows as SQL, which cannot carry a stream, so a "
                              + "certificate can be removed here but not added. To add one, import it "
                              + "with Orca or re-sign the package with the tool that produced it."));
                CertEditorHost.Content = grid;
                _certEditorLoading = false;
                return;
            }

            if (item.Kind == CertKind.Foreign)
            {
                AddRow("Custom action", new TextBlock
                { Text = Col(item.AddRow, "Action"), FontSize = 12, Foreground = valFg, TextWrapping = TextWrapping.Wrap });
                AddRow("Command", new TextBlock
                {
                    Text = Col(item.AddRow, "Target"), FontSize = 11,
                    FontFamily = new FontFamily("Consolas"), Foreground = valFg, TextWrapping = TextWrapping.Wrap
                });
                AddRow("", Note("This package already installs a certificate through its own custom "
                              + "action. Edit it under Custom actions; this view manages only the "
                              + "ones it wrote itself."));
                CertEditorHost.Content = grid;
                _certEditorLoading = false;
                return;
            }

            var d0 = ParseCertCommand(item.Key, Col(item.AddRow, "Target"));
            d0.RemoveBy = item.DelRow != null
                ? ParseCertCommand(item.Key, Col(item.DelRow, "Target")).File : "";

            // Same picker as Install a Certificate, so an existing entry can be repointed at
            // another file in the package. The field stays typeable, which is what a package whose
            // .cer arrives by some other route needs.
            var (fileF, fileB) = MakeRoundedField(d0.File, boxBg, boxBdr, valFg, false,
                () => PickFileFromPackage("Select a file", d0.File));
            fileB.ToolTip = "Path to the .cer on the target machine. Directory properties and [#FileKey] "
                          + "references both work: the command line is resolved when the install "
                          + "script is written.";
            AddRow("Certificate file", fileF);

            var storeBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            foreach (var (tag, label) in CertStores)
                storeBox.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
            int sIx = Array.FindIndex(CertStores, x => x.tag == d0.Store);
            storeBox.SelectedIndex = sIx >= 0 ? sIx : 0;
            AddRow("Store", RoundWrapControl(storeBox, boxBg, boxBdr));

            var scopeBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            scopeBox.Items.Add(new ComboBoxItem { Content = "Local machine (all users)", Tag = "machine" });
            scopeBox.Items.Add(new ComboBoxItem { Content = "The installing user", Tag = "user" });
            scopeBox.SelectedIndex = d0.MachineStore ? 0 : 1;
            AddRow("Install into", RoundWrapControl(scopeBox, boxBg, boxBdr));

            var (remF, remB) = MakeRoundedField(d0.RemoveBy, boxBg, boxBdr, valFg, false, null);
            remB.ToolTip = "certutil matches the certificate to delete by common name, serial number "
                         + "or thumbprint. The file name is not enough unless it happens to match.";
            AddRow("Remove by", remF);

            var cmdText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
            };
            AddRow("Commands", cmdText);

            void Commit()
            {
                if (_certEditorLoading || item.AddRow == null) return;
                bool machine = (scopeBox.SelectedItem as ComboBoxItem)?.Tag as string != "user";
                var d = new CertData
                {
                    Key = item.Key, File = fileB.Text.Trim(),
                    Store = (storeBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "Root",
                    MachineStore = machine, RemoveBy = remB.Text.Trim(),
                };

                string add = BuildCertAdd(d), del = BuildCertDel(d);
                int type = machine ? CertCaSystem : CertCaUser;
                void Write(DataRow? r, string target)
                {
                    if (r == null) return;
                    if (r.Table.Columns.Contains("Target")) r["Target"] = target;
                    if (r.Table.Columns.Contains("Type"))   r["Type"] = type.ToString();
                }
                Write(item.AddRow, add);
                Write(item.DelRow, del);

                UpdateEditCount();
                string store = CertStores.FirstOrDefault(x => x.tag == d.Store).label ?? d.Store;
                item.Update(d.File.Length > 0 ? System.IO.Path.GetFileName(d.File) : item.Key,
                    store + (machine ? "  ·  machine" : "  ·  current user"));

                cmdText.Text = "install    " + add + "\nuninstall  " + del
                             + $"\n\nCustomAction type {type}, source SystemFolder, deferred "
                             + (machine ? "without impersonation so it runs as SYSTEM and reaches the machine store"
                                        : "impersonated so it reaches the installing user's own store");
            }

            fileB.TextChanged += (_, _) => Commit();
            remB.TextChanged += (_, _) => Commit();
            storeBox.SelectionChanged += (_, _) => Commit();
            scopeBox.SelectionChanged += (_, _) => Commit();

            CertEditorHost.Content = grid;
            _certEditorLoading = false;
            Commit();
        }


        // ══ Drivers ═════════════════════════════════════════════════════════
        // Windows Installer cannot install a driver on its own. Two mechanisms exist.
        //
        // DIFxApp adds an MsiDriverPackages table, but the work is done by a custom action named
        // MsiProcessDrivers that comes from the DIFxApp merge module: rows in that table do
        // nothing at all unless the module was merged in, which is checked and reported here.
        //
        // pnputil.exe ships with Windows and needs nothing merged, so that is what this view
        // writes. Removal is the awkward half: pnputil identifies an installed driver by the
        // oemNN.inf name Windows assigns at install time, which is not knowable when the package
        // is built, so removing one means finding it by its original name first.
        private const int DrvCaType = 34 | 0x400 | 0x800;   // 3106: deferred, system context
        private const string DrvAddPrefix = "SwpDrvAdd_";
        private const string DrvDelPrefix = "SwpDrvDel_";

        // Flags in MsiDriverPackages, from WiX's DIFxApp extension. Two of the five are set when
        // the answer is *no*, so the labels below say what the bit does rather than what the
        // authoring attribute is called.
        private static readonly (int bit, string label)[] DrvFlagBits =
        {
            (0x01, "Force install even when a better driver is present"),
            (0x02, "Do not prompt to connect the device"),
            (0x04, "Hide the driver from Add/Remove Programs"),
            (0x08, "Legacy driver (not Plug and Play)"),
            (0x10, "Delete the driver files on uninstall"),
        };

        private sealed class DrvData
        {
            public string Key = "", Inf = "";
            public bool Subdirs, RemoveOnUninstall;
        }

        private static string BuildDrvAdd(DrvData d) =>
            "pnputil.exe /add-driver \"" + d.Inf + "\"" + (d.Subdirs ? " /subdirs" : "") + " /install";

        /// <summary>
        /// Removal has to match on the INF's original name because the published name is assigned
        /// at install time. Get-WindowsDriver reports both, so it is the practical way to bridge
        /// them. No square brackets in the command: MSI would read them as a property reference.
        ///
        /// Which is why a [#FileKey] Inf, as the package file picker returns, is reduced to the
        /// bare file name here. Left whole it breaks twice: MSI would expand it to the full
        /// installed path and the -like pattern would then match nothing, and PowerShell reads
        /// [ ] as a character class in the first place.
        /// </summary>
        private static string BuildDrvDel(DrvData d)
        {
            string leaf = d.Inf;
            if (leaf.StartsWith("[#", StringComparison.Ordinal) && leaf.EndsWith("]", StringComparison.Ordinal))
                leaf = leaf.Substring(2, leaf.Length - 3);
            int slash = leaf.LastIndexOfAny(new[] { '\\', '/' });
            if (slash >= 0) leaf = leaf.Substring(slash + 1);
            return "powershell.exe -NonInteractive -ExecutionPolicy Bypass -Command "
                 + "\"Get-WindowsDriver -Online | Where-Object { $_.OriginalFileName -like '*\\"
                 + leaf + "' } | ForEach-Object { pnputil.exe /delete-driver $_.Driver /uninstall /force }\"";
        }

        private static DrvData ParseDrvCommand(string key, string cmd)
        {
            var d = new DrvData { Key = key };
            var q = System.Text.RegularExpressions.Regex.Match(cmd, "/add-driver\\s+\"([^\"]*)\"");
            if (q.Success) d.Inf = q.Groups[1].Value;
            d.Subdirs = cmd.IndexOf("/subdirs", StringComparison.OrdinalIgnoreCase) >= 0;
            return d;
        }

        private TableState? _drvCaSt;
        private bool _drvEditorLoading;

        /// <summary>True when the package carries the custom action DIFxApp relies on.</summary>
        private bool HasDifxProcessDrivers()
        {
            var st = EnsureTableCached("CustomAction");
            if (st == null) return false;
            foreach (DataRow r in st.Data.Rows)
                if (r.RowState != DataRowState.Deleted &&
                    Col(r, "Action").IndexOf("MsiProcessDrivers", StringComparison.OrdinalIgnoreCase) >= 0)
                    return true;
            return false;
        }

        private void ShowDriversForm(TableState caSt)
        {
            _drvCaSt = caSt;
            var managed = new List<DrvItem>();
            var foreign = new List<DrvItem>();

            foreach (DataRow r in caSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string action = Col(r, "Action"), target = Col(r, "Target");
                if (action.StartsWith(DrvAddPrefix, StringComparison.OrdinalIgnoreCase))
                {
                    var d = ParseDrvCommand(action.Substring(DrvAddPrefix.Length), target);
                    string leaf = d.Inf;
                    int sl = leaf.LastIndexOfAny(new[] { '\\', '/' });
                    if (sl >= 0) leaf = leaf.Substring(sl + 1);
                    managed.Add(new DrvItem(DrvKind.Managed, leaf.Length > 0 ? leaf : action,
                        d.Subdirs ? "with subfolders" : "single INF") { AddRow = r, Key = d.Key });
                }
                else if (action.StartsWith(DrvDelPrefix, StringComparison.OrdinalIgnoreCase)) continue;
                else if (target.IndexOf("pnputil", StringComparison.OrdinalIgnoreCase) >= 0
                      || target.IndexOf("dpinst", StringComparison.OrdinalIgnoreCase) >= 0
                      || target.IndexOf("/add-driver", StringComparison.OrdinalIgnoreCase) >= 0)
                    foreign.Add(new DrvItem(DrvKind.Foreign, action, "custom action written elsewhere")
                    { AddRow = r });
            }

            foreach (var it in managed)
                foreach (DataRow r in caSt.Data.Rows)
                    if (r.RowState != DataRowState.Deleted &&
                        string.Equals(Col(r, "Action"), DrvDelPrefix + it.Key, StringComparison.OrdinalIgnoreCase))
                    { it.DelRow = r; break; }

            managed.Sort((a, b) => string.Compare(a.Name, b.Name, StringComparison.OrdinalIgnoreCase));
            var root = new DrvItem(DrvKind.Root, "Drivers",
                managed.Count == 1 ? "1 INF installed" : $"{managed.Count} INFs installed") { IsExpanded = true };
            foreach (var it in managed) root.Children.Add(it);

            var difx = new DrvItem(DrvKind.Group, "DIFxApp driver packages", "") { IsExpanded = true };
            var pkgSt = EnsureTableCached("MsiDriverPackages");
            if (pkgSt != null)
                foreach (DataRow r in pkgSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string comp = Col(r, "Component");
                    if (comp.Length == 0) continue;
                    int flags = int.TryParse(Col(r, "Flags"), out var fv) ? fv : 0;
                    difx.Children.Add(new DrvItem(DrvKind.Difx, comp,
                        $"flags {flags}" + (Col(r, "Sequence") is { Length: > 0 } sq ? $"  ·  sequence {sq}" : ""))
                    { AddRow = r, Key = comp });
                }
            // Added only when there are packages, matching the "Other driver" group below. An empty
            // group only repeats the root's own "0 INFs installed" and cannot be opened.
            if (difx.Children.Count > 0)
            {
                difx.Update(difx.Name, $"{difx.Children.Count} package(s)"
                    + (HasDifxProcessDrivers() ? "" : "  \u00B7  MsiProcessDrivers is missing"));
                root.Children.Add(difx);
            }

            if (foreign.Count > 0)
            {
                var g = new DrvItem(DrvKind.Group, "Other driver custom actions",
                    $"{foreign.Count} found, not written by SwiftPack") { IsExpanded = true };
                foreach (var it in foreign) g.Children.Add(it);
                root.Children.Add(g);
            }

            if (DrvTree != null)
                DrvTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<DrvItem> { root };
            if (DrvCount != null) DrvCount.Text = root.Summary;
            ClearDrvEditor();
            if (FormDriversPanel != null) FormDriversPanel.Visibility = Visibility.Visible;
            var first = root.Children.FirstOrDefault(c => c.Kind == DrvKind.Managed);
            if (first != null) first.IsSelected = true;
        }

        private void DrvTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is DrvItem it && it.AddRow != null) ShowDrvEditor(it);
            else ClearDrvEditor();
        }

        private void ClearDrvEditor()
        {
            if (DrvEditorHost != null) DrvEditorHost.Content = null;
        }

        private void DrvMenu_Opened(object sender, RoutedEventArgs e)
        {
            var it = DrvTree?.SelectedItem as DrvItem;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiDrvNew, it == null || it.Kind == DrvKind.Root);
            V(MiDrvDelete, it?.Kind == DrvKind.Managed || it?.Kind == DrvKind.Difx);
        }

        private void DrvNew_Click(object sender, RoutedEventArgs e)
        {
            var caSt = _drvCaSt ?? EnsureTableOrCreate("CustomAction");
            if (caSt == null) return;
            // The package's own file tree, not a disk browser: pnputil reads the .inf at install
            // time on the target machine, so the file has to be one this package installs. The
            // picker returns [#FileKey], which Windows Installer resolves to wherever that file
            // actually lands - so the command keeps working if the folder is retargeted later.
            string? typed = PickFileFromPackage("Select a file", "");
            if (string.IsNullOrWhiteSpace(typed)) return;

            // The custom action below is type 34, whose Source column holds a DIRECTORY key rather
            // than a path, and it names SystemFolder. A package that never referenced SystemFolder
            // has no such row, and the action then resolves to nothing at install time.
            EnsureSystemFolderDirectories();

            // Only the name matters for the action key; the [#...] wrapper is not part of it.
            string leaf = typed.Trim();
            if (leaf.StartsWith("[#", StringComparison.Ordinal) && leaf.EndsWith("]", StringComparison.Ordinal))
                leaf = leaf.Substring(2, leaf.Length - 3);
            int sl = leaf.LastIndexOfAny(new[] { '\\', '/' });
            if (sl >= 0) leaf = leaf.Substring(sl + 1);

            var d = new DrvData { Inf = typed.Trim() };
            // Compared in its PREFIXED form: Action holds "SwpDrvAdd_<key>", so handing UniqueKey
            // the bare key matches nothing and it hands the same key back every time. Picking the
            // same .inf twice would then write two rows under one Action name.
            d.Key = UniqueKey(caSt.Data, "Action", DrvAddPrefix
                + SanitizeKey(System.IO.Path.GetFileNameWithoutExtension(leaf) is { Length: > 0 } b ? b : "driver"))
                .Substring(DrvAddPrefix.Length);

            var nr = caSt.Data.NewRow();
            nr["Action"] = DrvAddPrefix + d.Key;
            if (caSt.Data.Columns.Contains("Type"))   nr["Type"] = DrvCaType.ToString();
            if (caSt.Data.Columns.Contains("Source")) nr["Source"] = "SystemFolder";
            if (caSt.Data.Columns.Contains("Target")) nr["Target"] = BuildDrvAdd(d);
            caSt.Data.Rows.Add(nr);

            PlaceTaskAction(DrvAddPrefix + d.Key, "InstallFiles", "NOT Installed");

            UpdateEditCount();
            ShowDriversForm(caSt);
        }

        private void DrvDelete_Click(object sender, RoutedEventArgs e)
        {
            if (DrvTree?.SelectedItem is not DrvItem it || it.AddRow == null) return;
            var caSt = _drvCaSt ?? EnsureTableCached("CustomAction");

            if (it.Kind == DrvKind.Difx)
            {
                if (MstMessage($"Remove the DIFxApp driver package on component \u201C{it.Key}\u201D?",
                        "Delete Driver Package", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
                if (it.AddRow.RowState != DataRowState.Deleted) it.AddRow.Delete();
            }
            else
            {
                if (MstMessage($"Delete \u201C{it.Name}\u201D and its custom action(s)?",
                        "Delete Driver", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
                foreach (string action in new[] { DrvAddPrefix + it.Key, DrvDelPrefix + it.Key })
                {
                    var seqSt = EnsureTableCached("InstallExecuteSequence");
                    var seqRow = seqSt == null ? null : FindCaSeqRow(seqSt, action);
                    if (seqRow != null && seqRow.RowState != DataRowState.Deleted) seqRow.Delete();
                }
                foreach (var r in new[] { it.AddRow, it.DelRow })
                    if (r is { } row && row.RowState != DataRowState.Deleted) row.Delete();
            }

            UpdateEditCount();
            if (caSt != null) ShowDriversForm(caSt);
        }

        private void ShowDrvEditor(DrvItem item)
        {
            if (DrvEditorHost == null || item.AddRow == null) return;
            _drvEditorLoading = true;

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(118) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
                };
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }
            TextBlock Note(string t) => new TextBlock
            { Text = t, FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap };

            if (item.Kind == DrvKind.Foreign)
            {
                AddRow("Custom action", new TextBlock
                { Text = Col(item.AddRow, "Action"), FontSize = 12, Foreground = valFg, TextWrapping = TextWrapping.Wrap });
                AddRow("Command", new TextBlock
                {
                    Text = Col(item.AddRow, "Target"), FontSize = 11,
                    FontFamily = new FontFamily("Consolas"), Foreground = valFg, TextWrapping = TextWrapping.Wrap
                });
                AddRow("", Note("This package already installs a driver through its own custom action. "
                              + "Edit it under Custom actions."));
                DrvEditorHost.Content = grid; _drvEditorLoading = false; return;
            }

            if (item.Kind == DrvKind.Difx)
            {
                var row = item.AddRow;
                int flags = int.TryParse(Col(row, "Flags"), out var fv) ? fv : 0;

                var compBox = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = Col(row, "Component")
                };
                foreach (var (v, _) in KeysFrom("Component", "Component")) compBox.Items.Add(v);
                compBox.ToolTip = "The component holding the driver's INF. Its key path should be the INF.";
                AddRow("Component", RoundWrapControl(compBox, boxBg, boxBdr));

                var (seqF, seqB) = MakeRoundedField(Col(row, "Sequence"), boxBg, boxBdr, valFg, false, null);
                seqB.ToolTip = "Order among the package's driver packages. Blank leaves it unordered.";
                AddRow("Sequence", seqF);

                var boxes = new List<(CheckBox box, int bit)>();
                var wrap = new WrapPanel();
                foreach (var (bit, label) in DrvFlagBits)
                {
                    var cb = new CheckBox
                    {
                        Content = label, IsChecked = (flags & bit) == bit, Foreground = valFg,
                        FontSize = 12, Width = 300, Margin = new Thickness(0, 5, 8, 5),
                        VerticalContentAlignment = VerticalAlignment.Center
                    };
                    boxes.Add((cb, bit)); wrap.Children.Add(cb);
                }
                AddRow("Options", wrap);

                var rawText = new TextBlock
                {
                    FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                    TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
                };
                AddRow("Raw", rawText);

                if (!HasDifxProcessDrivers())
                    AddRow("", Note("This package has no MsiProcessDrivers custom action, which is what "
                                  + "DIFxApp uses to act on this table. Without the DIFxApp merge module "
                                  + "these rows are inert. Installing through pnputil above avoids the "
                                  + "dependency entirely."));

                void CommitDifx()
                {
                    if (_drvEditorLoading) return;
                    int known = 0;
                    foreach (var (_, b) in boxes) known |= b;
                    int f = flags & ~known;
                    foreach (var (cb, b) in boxes) if (cb.IsChecked == true) f |= b;

                    if (row.Table.Columns.Contains("Component")) row["Component"] = compBox.Text.Trim();
                    if (row.Table.Columns.Contains("Flags")) row["Flags"] = f.ToString();
                    if (row.Table.Columns.Contains("Sequence"))
                        row["Sequence"] = seqB.Text.Trim().Length > 0 ? (object)seqB.Text.Trim() : DBNull.Value;

                    UpdateEditCount();
                    item.Update(compBox.Text.Trim(), $"flags {f}"
                        + (seqB.Text.Trim().Length > 0 ? $"  ·  sequence {seqB.Text.Trim()}" : ""));
                    rawText.Text = $"Flags {f}  (0x{f:X})";
                }
                compBox.SelectionChanged += (_, _) => CommitDifx();
                compBox.LostFocus += (_, _) => CommitDifx();
                seqB.TextChanged += (_, _) => CommitDifx();
                foreach (var (cb, _) in boxes)
                { cb.Checked += (_, _) => CommitDifx(); cb.Unchecked += (_, _) => CommitDifx(); }

                DrvEditorHost.Content = grid;
                _drvEditorLoading = false;
                CommitDifx();
                return;
            }

            var d0 = ParseDrvCommand(item.Key, Col(item.AddRow, "Target"));
            d0.RemoveOnUninstall = item.DelRow != null;

            // Same picker as Install a Driver, so an existing entry can be repointed at another
            // file in the package. The field stays typeable, which is what a package whose .inf
            // arrives by some other route needs.
            var (infF, infB) = MakeRoundedField(d0.Inf, boxBg, boxBdr, valFg, false,
                () => PickFileFromPackage("Select a file", d0.Inf));
            infB.ToolTip = "Path to the .inf on the target machine. Directory properties and [#FileKey] "
                         + "references both work: the command line is resolved when the install "
                         + "script is written.";
            AddRow("INF file", infF);

            var cSub = new CheckBox
            {
                Content = "Also search subfolders for INFs", IsChecked = d0.Subdirs,
                Foreground = valFg, FontSize = 12, Margin = new Thickness(0, 6, 0, 6)
            };
            AddRow("", cSub);

            var cRemove = new CheckBox
            {
                Content = "Remove the driver on uninstall", IsChecked = d0.RemoveOnUninstall,
                Foreground = valFg, FontSize = 12, Margin = new Thickness(0, 6, 0, 6),
                ToolTip = "Windows renames an installed INF to oemNN.inf, and that name is not known "
                        + "when the package is built. Removal therefore runs PowerShell to find the "
                        + "driver by its original name first, which is slower but reliable."
            };
            AddRow("", cRemove);

            var cmdText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
            };
            AddRow("Commands", cmdText);

            void Commit()
            {
                if (_drvEditorLoading || item.AddRow == null) return;
                var d = new DrvData
                {
                    Key = item.Key, Inf = infB.Text.Trim(),
                    Subdirs = cSub.IsChecked == true,
                    RemoveOnUninstall = cRemove.IsChecked == true,
                };

                if (item.AddRow.Table.Columns.Contains("Target")) item.AddRow["Target"] = BuildDrvAdd(d);

                var caSt = _drvCaSt ?? EnsureTableOrCreate("CustomAction");
                if (d.RemoveOnUninstall && item.DelRow == null && caSt != null)
                {
                    var nr = caSt.Data.NewRow();
                    nr["Action"] = DrvDelPrefix + d.Key;
                    if (caSt.Data.Columns.Contains("Type"))   nr["Type"] = DrvCaType.ToString();
                    if (caSt.Data.Columns.Contains("Source")) nr["Source"] = "SystemFolder";
                    if (caSt.Data.Columns.Contains("Target")) nr["Target"] = BuildDrvDel(d);
                    caSt.Data.Rows.Add(nr);
                    item.DelRow = nr;
                    PlaceTaskAction(DrvDelPrefix + d.Key, "InstallInitialize", "REMOVE=\"ALL\"");
                }
                else if (!d.RemoveOnUninstall && item.DelRow != null)
                {
                    var seqSt = EnsureTableCached("InstallExecuteSequence");
                    var seqRow = seqSt == null ? null : FindCaSeqRow(seqSt, DrvDelPrefix + d.Key);
                    if (seqRow != null && seqRow.RowState != DataRowState.Deleted) seqRow.Delete();
                    if (item.DelRow.RowState != DataRowState.Deleted) item.DelRow.Delete();
                    item.DelRow = null;
                }
                else if (item.DelRow is { } dr && dr.Table.Columns.Contains("Target"))
                    dr["Target"] = BuildDrvDel(d);

                UpdateEditCount();
                string leaf = d.Inf;
                int sl2 = leaf.LastIndexOfAny(new[] { '\\', '/' });
                if (sl2 >= 0) leaf = leaf.Substring(sl2 + 1);
                item.Update(leaf.Length > 0 ? leaf : item.Key, d.Subdirs ? "with subfolders" : "single INF");

                cmdText.Text = "install    " + BuildDrvAdd(d)
                             + (d.RemoveOnUninstall ? "\n\nuninstall  " + BuildDrvDel(d) : "\n\nuninstall  (driver left installed)")
                             + $"\n\nCustomAction type {DrvCaType}, source SystemFolder, deferred without impersonation";
            }

            infB.TextChanged += (_, _) => Commit();
            cSub.Checked += (_, _) => Commit(); cSub.Unchecked += (_, _) => Commit();
            cRemove.Checked += (_, _) => Commit(); cRemove.Unchecked += (_, _) => Commit();

            DrvEditorHost.Content = grid;
            _drvEditorLoading = false;
            Commit();
        }


        // ══ Firewall ════════════════════════════════════════════════════════
        // Windows Installer has no firewall table. WiX adds WixFirewallException, but the work is
        // done by WixSchedFirewallExceptionsInstall from the WiX firewall extension, so those rows
        // are inert unless the package carries that custom action; that is checked and reported.
        //
        // netsh advfirewall ships with every supported version of Windows and needs nothing added,
        // so that is what this view writes. Firewall changes need elevation, hence the deferred,
        // system-context custom action.
        private const int FwCaType = 34 | 0x400 | 0x800;   // 3106
        private const string FwAddPrefix = "SwpFwAdd_";
        private const string FwDelPrefix = "SwpFwDel_";

        // From WiX's FirewallConstants: IANA protocol numbers and the NET_FW_PROFILE2 bits.
        private const int FwProtoTcp = 6;
        private const int FwProtoUdp = 17;
        private const int FwProfileDomain  = 0x0001;
        private const int FwProfilePrivate = 0x0002;
        private const int FwProfilePublic  = 0x0004;
        private const int FwProfileAll     = 0x7FFFFFFF;

        private static readonly (int bit, string label, string netsh)[] FwProfiles =
        {
            (FwProfileDomain,  "Domain",  "domain"),
            (FwProfilePrivate, "Private", "private"),
            (FwProfilePublic,  "Public",  "public"),
        };

        private sealed class FwData
        {
            public string Key = "", Name = "", Program = "", Ports = "", RemoteIp = "any", Description = "";
            public string Direction = "in";     // in | out
            public string Action = "allow";     // allow | block
            public string Protocol = "any";     // any | TCP | UDP
            public bool Domain = true, Private = true, Public = true;
            public bool Enabled = true;
        }

        private static string FwProfileArg(FwData d)
        {
            if (d.Domain && d.Private && d.Public) return "any";
            var on = new List<string>();
            if (d.Domain) on.Add("domain");
            if (d.Private) on.Add("private");
            if (d.Public) on.Add("public");
            return on.Count == 0 ? "any" : string.Join(",", on);
        }

        private static string BuildFwAdd(FwData d)
        {
            var sb = new System.Text.StringBuilder();
            sb.Append("netsh.exe advfirewall firewall add rule");
            sb.Append(" name=\"").Append(d.Name).Append('"');
            sb.Append(" dir=").Append(d.Direction);
            sb.Append(" action=").Append(d.Action);
            sb.Append(" enable=").Append(d.Enabled ? "yes" : "no");
            sb.Append(" profile=").Append(FwProfileArg(d));
            if (d.Program.Trim().Length > 0) sb.Append(" program=\"").Append(d.Program.Trim()).Append('"');
            if (!d.Protocol.Equals("any", StringComparison.OrdinalIgnoreCase))
            {
                sb.Append(" protocol=").Append(d.Protocol);
                // localport is only meaningful once a transport protocol is named.
                if (d.Ports.Trim().Length > 0) sb.Append(" localport=").Append(d.Ports.Trim());
            }
            if (d.RemoteIp.Trim().Length > 0 && !d.RemoteIp.Equals("any", StringComparison.OrdinalIgnoreCase))
                sb.Append(" remoteip=").Append(d.RemoteIp.Trim());
            if (d.Description.Trim().Length > 0)
                sb.Append(" description=\"").Append(d.Description.Trim()).Append('"');
            return sb.ToString();
        }

        private static string BuildFwDel(FwData d) =>
            "netsh.exe advfirewall firewall delete rule name=\"" + d.Name + "\"";

        private static string FwArg(string cmd, string key)
        {
            var m = System.Text.RegularExpressions.Regex.Match(
                cmd, key + "=(\"([^\"]*)\"|([^\\s]+))", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            if (!m.Success) return "";
            return m.Groups[2].Success && m.Groups[2].Value.Length > 0 ? m.Groups[2].Value : m.Groups[3].Value;
        }

        private static FwData ParseFwCommand(string key, string cmd)
        {
            var d = new FwData { Key = key, Name = FwArg(cmd, "name") };
            string dir = FwArg(cmd, "dir"); if (dir.Length > 0) d.Direction = dir.ToLowerInvariant();
            string act = FwArg(cmd, "action"); if (act.Length > 0) d.Action = act.ToLowerInvariant();
            d.Enabled = !FwArg(cmd, "enable").Equals("no", StringComparison.OrdinalIgnoreCase);
            d.Program = FwArg(cmd, "program");
            string proto = FwArg(cmd, "protocol");
            d.Protocol = proto.Length > 0 ? proto.ToUpperInvariant() : "any";
            d.Ports = FwArg(cmd, "localport");
            string rip = FwArg(cmd, "remoteip"); d.RemoteIp = rip.Length > 0 ? rip : "any";
            d.Description = FwArg(cmd, "description");

            string prof = FwArg(cmd, "profile");
            if (prof.Length == 0 || prof.Equals("any", StringComparison.OrdinalIgnoreCase))
            { d.Domain = d.Private = d.Public = true; }
            else
            {
                d.Domain  = prof.IndexOf("domain", StringComparison.OrdinalIgnoreCase) >= 0;
                d.Private = prof.IndexOf("private", StringComparison.OrdinalIgnoreCase) >= 0;
                d.Public  = prof.IndexOf("public", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            return d;
        }

        private TableState? _fwCaSt;
        private bool _fwEditorLoading;

        private bool HasWixFirewallCa()
        {
            var st = EnsureTableCached("CustomAction");
            if (st == null) return false;
            foreach (DataRow r in st.Data.Rows)
                if (r.RowState != DataRowState.Deleted &&
                    Col(r, "Action").IndexOf("FirewallException", StringComparison.OrdinalIgnoreCase) >= 0)
                    return true;
            return false;
        }

        private void ShowFirewallForm(TableState caSt, string? selectKey = null)
        {
            _fwCaSt = caSt;
            var managed = new List<FwItem>();
            var foreign = new List<FwItem>();

            foreach (DataRow r in caSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string action = Col(r, "Action"), target = Col(r, "Target");
                if (action.StartsWith(FwAddPrefix, StringComparison.OrdinalIgnoreCase))
                {
                    var d = ParseFwCommand(action.Substring(FwAddPrefix.Length), target);
                    managed.Add(new FwItem(FwKind.Managed, d.Name.Length > 0 ? d.Name : action,
                        $"{d.Direction}bound  ·  {d.Action}"
                        + (d.Protocol != "any" ? $"  ·  {d.Protocol}" : "")
                        + (d.Ports.Length > 0 ? " " + d.Ports : ""))
                    { AddRow = r, Key = d.Key });
                }
                else if (action.StartsWith(FwDelPrefix, StringComparison.OrdinalIgnoreCase)) continue;
                else if (target.IndexOf("advfirewall", StringComparison.OrdinalIgnoreCase) >= 0
                      || target.IndexOf("NetFirewallRule", StringComparison.OrdinalIgnoreCase) >= 0)
                    foreign.Add(new FwItem(FwKind.Foreign, action, "custom action written elsewhere")
                    { AddRow = r });
            }

            foreach (var it in managed)
                foreach (DataRow r in caSt.Data.Rows)
                    if (r.RowState != DataRowState.Deleted &&
                        string.Equals(Col(r, "Action"), FwDelPrefix + it.Key, StringComparison.OrdinalIgnoreCase))
                    { it.DelRow = r; break; }

            managed.Sort((a, b) => string.Compare(a.Name, b.Name, StringComparison.OrdinalIgnoreCase));
            var root = new FwItem(FwKind.Root, "Firewall",
                managed.Count == 1 ? "1 rule" : $"{managed.Count} rules") { IsExpanded = true };
            foreach (var it in managed) root.Children.Add(it);

            var wix = new FwItem(FwKind.Group, "WiX firewall exceptions", "") { IsExpanded = true };
            var wixSt = EnsureTableCached("WixFirewallException");
            if (wixSt != null)
                foreach (DataRow r in wixSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string k = Col(r, "WixFirewallException");
                    if (k.Length == 0) continue;
                    int proto = int.TryParse(Col(r, "Protocol"), out var pv) ? pv : 0;
                    string ps = proto == FwProtoTcp ? "TCP" : proto == FwProtoUdp ? "UDP" : "any protocol";
                    wix.Children.Add(new FwItem(FwKind.Wix, Col(r, "Name") is { Length: > 0 } nm ? nm : k,
                        ps + (Col(r, "Port") is { Length: > 0 } pt ? "  ·  port " + pt : ""))
                    { AddRow = r, Key = k });
                }
            // Added only when there are exceptions, matching the "Other firewall" group below. An
            // empty group only repeats the root's own "0 rules" and cannot be opened.
            if (wix.Children.Count > 0)
            {
                wix.Update(wix.Name, $"{wix.Children.Count} exception(s)"
                    + (HasWixFirewallCa() ? "" : "  \u00B7  the WiX firewall action is missing"));
                root.Children.Add(wix);
            }

            if (foreign.Count > 0)
            {
                var g = new FwItem(FwKind.Group, "Other firewall custom actions",
                    $"{foreign.Count} found, not written by SwiftPack") { IsExpanded = true };
                foreach (var it in foreign) g.Children.Add(it);
                root.Children.Add(g);
            }

            if (FwTree != null)
                FwTree.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<FwItem> { root };
            if (FwCount != null) FwCount.Text = root.Summary;
            ClearFwEditor();
            if (FormFirewallPanel != null) FormFirewallPanel.Visibility = Visibility.Visible;
            // Rules are sorted by name, so a rule just created is rarely the first one. Selecting
            // it by key is what puts its fields in the editor pane; without that a new rule would
            // be added and some other rule's fields shown.
            var first = (selectKey != null
                    ? root.Children.FirstOrDefault(c => c.Kind == FwKind.Managed
                        && string.Equals(c.Key, selectKey, StringComparison.OrdinalIgnoreCase))
                    : null)
                ?? root.Children.FirstOrDefault(c => c.Kind == FwKind.Managed);
            if (first != null) first.IsSelected = true;
        }

        private void FwTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is FwItem it && it.AddRow != null) ShowFwEditor(it);
            else ClearFwEditor();
        }

        private void ClearFwEditor()
        {
            if (FwEditorHost != null) FwEditorHost.Content = null;
        }

        private void FwMenu_Opened(object sender, RoutedEventArgs e)
        {
            var it = FwTree?.SelectedItem as FwItem;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            V(MiFwNew, it == null || it.Kind == FwKind.Root);
            V(MiFwDelete, it?.Kind == FwKind.Managed || it?.Kind == FwKind.Wix);
        }

        private void FwNew_Click(object sender, RoutedEventArgs e)
        {
            var caSt = _fwCaSt ?? EnsureTableOrCreate("CustomAction");
            if (caSt == null) return;
            // No name prompt: the rule is created with the defaults straight away and its fields
            // are shown, which is where the name is edited along with everything else. The name
            // still has to be unique, because netsh matches rules by name and the uninstall
            // command is "delete rule name=..." - two rules sharing a name would mean removing
            // either one removed both.
            var existingNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (DataRow er in caSt.Data.Rows)
            {
                if (er.RowState == DataRowState.Deleted) continue;
                string act = Col(er, "Action");
                if (!act.StartsWith(FwAddPrefix, StringComparison.OrdinalIgnoreCase)) continue;
                string nm = ParseFwCommand(act.Substring(FwAddPrefix.Length), Col(er, "Target")).Name;
                if (nm.Length > 0) existingNames.Add(nm);
            }
            string ruleName = "My Application";
            for (int n = 2; existingNames.Contains(ruleName); n++) ruleName = "My Application " + n;

            // Both custom actions below are type 34, whose Source column holds a DIRECTORY key
            // rather than a path, and both name SystemFolder. A package that never referenced
            // SystemFolder has no such row, and the actions then resolve to nothing at install time.
            EnsureSystemFolderDirectories();

            var d = new FwData { Name = ruleName };
            // Compared in its PREFIXED form: Action holds "SwpFwAdd_<key>", so handing UniqueKey
            // the bare key matches nothing and it hands the same key back every time. Two rules
            // would then be written under one Action name, and the second would collide on save.
            d.Key = UniqueKey(caSt.Data, "Action", FwAddPrefix + SanitizeKey(d.Name)).Substring(FwAddPrefix.Length);

            void MakeCa(string action, string target)
            {
                var nr = caSt.Data.NewRow();
                nr["Action"] = action;
                if (caSt.Data.Columns.Contains("Type"))   nr["Type"] = FwCaType.ToString();
                if (caSt.Data.Columns.Contains("Source")) nr["Source"] = "SystemFolder";
                if (caSt.Data.Columns.Contains("Target")) nr["Target"] = target;
                caSt.Data.Rows.Add(nr);
            }
            MakeCa(FwAddPrefix + d.Key, BuildFwAdd(d));
            MakeCa(FwDelPrefix + d.Key, BuildFwDel(d));

            // The rule may name an installed program, so add it once the files are there.
            PlaceTaskAction(FwAddPrefix + d.Key, "InstallFiles", "NOT Installed");
            PlaceTaskAction(FwDelPrefix + d.Key, "InstallInitialize", "REMOVE=\"ALL\"");

            UpdateEditCount();
            ShowFirewallForm(caSt, d.Key);
        }

        private void FwDelete_Click(object sender, RoutedEventArgs e)
        {
            if (FwTree?.SelectedItem is not FwItem it || it.AddRow == null) return;
            var caSt = _fwCaSt ?? EnsureTableCached("CustomAction");

            if (it.Kind == FwKind.Wix)
            {
                if (MstMessage($"Remove the WiX firewall exception \u201C{it.Name}\u201D?",
                        "Delete Exception", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
                if (it.AddRow.RowState != DataRowState.Deleted) it.AddRow.Delete();
            }
            else
            {
                if (MstMessage($"Delete the rule \u201C{it.Name}\u201D and both of its custom actions?",
                        "Delete Rule", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
                foreach (string action in new[] { FwAddPrefix + it.Key, FwDelPrefix + it.Key })
                {
                    var seqSt = EnsureTableCached("InstallExecuteSequence");
                    var seqRow = seqSt == null ? null : FindCaSeqRow(seqSt, action);
                    if (seqRow != null && seqRow.RowState != DataRowState.Deleted) seqRow.Delete();
                }
                foreach (var r in new[] { it.AddRow, it.DelRow })
                    if (r is { } row && row.RowState != DataRowState.Deleted) row.Delete();
            }

            UpdateEditCount();
            if (caSt != null) ShowFirewallForm(caSt);
        }

        private void ShowFwEditor(FwItem item)
        {
            if (FwEditorHost == null || item.AddRow == null) return;
            _fwEditorLoading = true;

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")       as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")    as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(118) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
                };
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }
            TextBlock Note(string t) => new TextBlock
            { Text = t, FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap };
            ComboBox Combo((string tag, string label)[] opts, string current)
            {
                var cb = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
                };
                foreach (var (tag, label) in opts) cb.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
                int ix = Array.FindIndex(opts, x => string.Equals(x.tag, current, StringComparison.OrdinalIgnoreCase));
                cb.SelectedIndex = ix >= 0 ? ix : 0;
                return cb;
            }

            if (item.Kind == FwKind.Foreign)
            {
                AddRow("Custom action", new TextBlock
                { Text = Col(item.AddRow, "Action"), FontSize = 12, Foreground = valFg, TextWrapping = TextWrapping.Wrap });
                AddRow("Command", new TextBlock
                {
                    Text = Col(item.AddRow, "Target"), FontSize = 11,
                    FontFamily = new FontFamily("Consolas"), Foreground = valFg, TextWrapping = TextWrapping.Wrap
                });
                AddRow("", Note("This package already changes the firewall through its own custom "
                              + "action. Edit it under Custom actions."));
                FwEditorHost.Content = grid; _fwEditorLoading = false; return;
            }

            if (item.Kind == FwKind.Wix)
            {
                var row = item.AddRow;
                int proto = int.TryParse(Col(row, "Protocol"), out var pv) ? pv : 0;
                int prof = int.TryParse(Col(row, "Profile"), out var fv) ? fv : FwProfileAll;

                AddRow("Name", new TextBlock { Text = Col(row, "Name"), FontSize = 12, Foreground = valFg });
                AddRow("Program", new TextBlock { Text = Col(row, "Program"), FontSize = 12, Foreground = valFg, TextWrapping = TextWrapping.Wrap });
                AddRow("Port", new TextBlock { Text = Col(row, "Port"), FontSize = 12, Foreground = valFg });
                AddRow("Protocol", new TextBlock
                {
                    Text = proto == FwProtoTcp ? "TCP (6)" : proto == FwProtoUdp ? "UDP (17)" : "not set",
                    FontSize = 12, Foreground = valFg
                });
                AddRow("Remote", new TextBlock { Text = Col(row, "RemoteAddresses"), FontSize = 12, Foreground = valFg });
                string profText = prof == FwProfileAll ? "all profiles"
                    : string.Join(", ", FwProfiles.Where(x => (prof & x.bit) != 0).Select(x => x.label));
                AddRow("Profiles", new TextBlock
                { Text = profText.Length > 0 ? profText : $"none ({prof})", FontSize = 12, Foreground = valFg });
                AddRow("Component", new TextBlock { Text = Col(row, "Component_"), FontSize = 12, Foreground = valFg });

                if (!HasWixFirewallCa())
                    AddRow("", Note("This package has no WiX firewall custom action, so these rows are "
                                  + "inert. A netsh rule above does the same job without the dependency."));
                else
                    AddRow("", Note("Written by the WiX firewall extension. Shown here for reference; "
                                  + "delete it and author a netsh rule if you need to change it."));

                FwEditorHost.Content = grid; _fwEditorLoading = false; return;
            }

            var d0 = ParseFwCommand(item.Key, Col(item.AddRow, "Target"));

            var (nameF, nameB) = MakeRoundedField(d0.Name, boxBg, boxBdr, valFg, false, null);
            nameB.ToolTip = "The rule name Windows shows, and what the uninstall command matches on.";
            AddRow("Rule name", nameF);

            var dirBox = Combo(new[] { ("in", "Inbound"), ("out", "Outbound") }, d0.Direction);
            AddRow("Direction", RoundWrapControl(dirBox, boxBg, boxBdr));

            var actBox = Combo(new[] { ("allow", "Allow the connection"), ("block", "Block the connection") }, d0.Action);
            AddRow("Action", RoundWrapControl(actBox, boxBg, boxBdr));

            // Same picker as the certificate and driver file fields: the rule names an executable
            // on the TARGET machine, so it has to be one this package installs. [#FileKey] resolves
            // to wherever that file lands, and the field stays typeable for a program that is
            // already on the machine.
            var (progF, progB) = MakeRoundedField(d0.Program, boxBg, boxBdr, valFg, false,
                () => PickFileFromPackage("Select a file", d0.Program));
            progB.ToolTip = "Optional. Restricts the rule to one executable. Directory properties and "
                          + "[#FileKey] references both work.";
            AddRow("Program", progF);

            var protoBox = Combo(new[] { ("any", "Any protocol"), ("TCP", "TCP"), ("UDP", "UDP") }, d0.Protocol);
            AddRow("Protocol", RoundWrapControl(protoBox, boxBg, boxBdr));

            var (portF, portB) = MakeRoundedField(d0.Ports, boxBg, boxBdr, valFg, false, null);
            portB.ToolTip = "One port, a list like 80,443, or a range like 5000-5010.";
            AddRow("Local ports", portF);

            var (ripF, ripB) = MakeRoundedField(d0.RemoteIp, boxBg, boxBdr, valFg, false, null);
            ripB.ToolTip = "any, localsubnet, or an address or range.";
            AddRow("Remote address", ripF);

            var cDomain  = new CheckBox { Content = "Domain",  IsChecked = d0.Domain,  Foreground = valFg, FontSize = 12, Width = 110, Margin = new Thickness(0, 5, 8, 5) };
            var cPrivate = new CheckBox { Content = "Private", IsChecked = d0.Private, Foreground = valFg, FontSize = 12, Width = 110, Margin = new Thickness(0, 5, 8, 5) };
            var cPublic  = new CheckBox { Content = "Public",  IsChecked = d0.Public,  Foreground = valFg, FontSize = 12, Width = 110, Margin = new Thickness(0, 5, 8, 5) };
            var profWrap = new WrapPanel();
            foreach (var c in new[] { cDomain, cPrivate, cPublic }) profWrap.Children.Add(c);
            AddRow("Profiles", profWrap);

            var cEnabled = new CheckBox
            {
                Content = "Rule is enabled", IsChecked = d0.Enabled, Foreground = valFg,
                FontSize = 12, Margin = new Thickness(0, 6, 0, 6)
            };
            AddRow("", cEnabled);

            var (descF, descB) = MakeRoundedField(d0.Description, boxBg, boxBdr, valFg, true, null);
            AddRow("Description", descF);

            var cmdText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0)
            };
            AddRow("Commands", cmdText);

            void Commit()
            {
                if (_fwEditorLoading || item.AddRow == null) return;
                var d = new FwData
                {
                    Key = item.Key, Name = nameB.Text.Trim(),
                    Direction = (dirBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "in",
                    Action = (actBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "allow",
                    Program = progB.Text, Ports = portB.Text, RemoteIp = ripB.Text,
                    Protocol = (protoBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "any",
                    Description = descB.Text,
                    Domain = cDomain.IsChecked == true, Private = cPrivate.IsChecked == true,
                    Public = cPublic.IsChecked == true, Enabled = cEnabled.IsChecked == true,
                };
                if (d.Name.Length == 0) return;

                // netsh rejects localport unless a transport protocol is named.
                bool ports = !d.Protocol.Equals("any", StringComparison.OrdinalIgnoreCase);
                portB.IsEnabled = ports; portF.Opacity = ports ? 1.0 : 0.5;
                portF.ToolTip = ports ? null : "Choose TCP or UDP before setting ports: netsh will not take a port without one.";

                string add = BuildFwAdd(d), del = BuildFwDel(d);
                if (item.AddRow.Table.Columns.Contains("Target")) item.AddRow["Target"] = add;
                if (item.DelRow is { } dr && dr.Table.Columns.Contains("Target")) dr["Target"] = del;

                UpdateEditCount();
                item.Update(d.Name, $"{d.Direction}bound  ·  {d.Action}"
                    + (ports ? $"  ·  {d.Protocol}" : "")
                    + (ports && d.Ports.Trim().Length > 0 ? " " + d.Ports.Trim() : ""));

                cmdText.Text = "install    " + add + "\n\nuninstall  " + del
                             + $"\n\nCustomAction type {FwCaType}, source SystemFolder, deferred without impersonation";
            }

            foreach (var b in new[] { nameB, progB, portB, ripB, descB }) b.TextChanged += (_, _) => Commit();
            foreach (var cb in new[] { dirBox, actBox, protoBox }) cb.SelectionChanged += (_, _) => Commit();
            foreach (var c in new[] { cDomain, cPrivate, cPublic, cEnabled })
            { c.Checked += (_, _) => Commit(); c.Unchecked += (_, _) => Commit(); }

            FwEditorHost.Content = grid;
            _fwEditorLoading = false;
            Commit();
        }

        private void ShowCategory()
        {
            if (LstCategories?.SelectedItem is not ListBoxItem item) return;
            string tag = (item.Tag as string) ?? "";

            if (FormProductScroll != null) FormProductScroll.Visibility = Visibility.Collapsed;
            if (FormGridPanel     != null) FormGridPanel.Visibility     = Visibility.Collapsed;
            if (FormPropsPanel    != null) FormPropsPanel.Visibility     = Visibility.Collapsed;
            if (FormFilesPanel    != null) FormFilesPanel.Visibility     = Visibility.Collapsed;
            if (FormRegistryPanel != null) FormRegistryPanel.Visibility  = Visibility.Collapsed;
            if (FormShortcutsPanel != null) FormShortcutsPanel.Visibility = Visibility.Collapsed;
            if (FormFeaturesPanel != null) FormFeaturesPanel.Visibility  = Visibility.Collapsed;
            if (FormCustomActionsPanel != null) FormCustomActionsPanel.Visibility = Visibility.Collapsed;
            if (FormSequencesPanel != null) FormSequencesPanel.Visibility = Visibility.Collapsed;
            if (FormUpgradePanel != null) FormUpgradePanel.Visibility = Visibility.Collapsed;
            if (FormEnvPanel != null) FormEnvPanel.Visibility = Visibility.Collapsed;
            if (FormServicesPanel != null) FormServicesPanel.Visibility = Visibility.Collapsed;
            if (FormIniPanel != null) FormIniPanel.Visibility = Visibility.Collapsed;
            if (FormSearchPanel != null) FormSearchPanel.Visibility = Visibility.Collapsed;
            if (FormOdbcPanel != null) FormOdbcPanel.Visibility = Visibility.Collapsed;
            if (FormDialogsPanel != null) FormDialogsPanel.Visibility = Visibility.Collapsed;
            if (FormTasksPanel != null) FormTasksPanel.Visibility = Visibility.Collapsed;
            if (FormCertsPanel != null) FormCertsPanel.Visibility = Visibility.Collapsed;
            if (FormDriversPanel != null) FormDriversPanel.Visibility = Visibility.Collapsed;
            if (FormFirewallPanel != null) FormFirewallPanel.Visibility = Visibility.Collapsed;
            if (FormMergeModPanel != null) FormMergeModPanel.Visibility = Visibility.Collapsed;
            if (FormPlaceholder   != null) FormPlaceholder.Visibility   = Visibility.Collapsed;

            ClearAllPanelSearches();   // switching category resets every per-panel search

            if (tag == "product")
            {
                _placeholderTable = ""; _formGridTable = "";
                if (FormProductScroll != null) FormProductScroll.Visibility = Visibility.Visible;
                PopulateProductInfo();
                return;
            }

            if (tag == "sequences")
            {
                _formGridTable = "";
                ShowSequencesForm();
                return;
            }

            string label = CategoryLabel(item);

            // Merge modules get a form, not the module tables: those tables live in the .msm, so
            // a finished MSI showed six faint chips and an empty grid, which read as broken.
            if (tag == "group:mergemod")
            {
                _placeholderTable = ""; _formGridTable = "";
                if (FormGroupStripHost != null) FormGroupStripHost.Visibility = Visibility.Collapsed;
                ShowMergeModulesForm();
                return;
            }

            // The multi-table categories come first: they own the grid and its table strip.
            // Every panel was already collapsed above, so this only has to show its own.
            if (tag.StartsWith("group:", StringComparison.Ordinal))
            {
                _placeholderTable = "";
                ShowTableGroup(tag.Substring(6), label);
                return;
            }
            if (FormGroupStripHost != null) FormGroupStripHost.Visibility = Visibility.Collapsed;

            string table = tag.StartsWith("table:") ? tag.Substring(6) : "";
            _placeholderTable = table;

            // Not in the package is not the same as not editable. A standard table SwiftPack has
            // the schema for is created empty right here, so a category like Custom actions opens
            // ready to add to instead of dead-ending on a placeholder. Nothing reaches the package
            // unless a row is actually added, and the CREATE TABLE runs at Save or Create MST.
            // The scheduled-tasks view has no table of its own: the tasks it manages live in
            // CustomAction, so that is what it opens.
            if (string.Equals(table, "ScheduledTasks", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(table, "Certificates", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(table, "Drivers", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(table, "Firewall", StringComparison.OrdinalIgnoreCase))
                table = "CustomAction";

            var st = table.Length > 0 ? EnsureTableCached(table) : null;
            bool created = false;
            if (st == null && table.Length > 0)
            {
                st = CreateEmptyStandardTable(table);
                created = st != null;
            }

            if (st == null)
            {
                _formGridTable = ""; _gridView = null; _propsView = null;
                FormGrid.ItemsSource = null;
                if (PropList != null) PropList.ItemsSource = null;
                if (DirTree != null) DirTree.ItemsSource = null;
                if (DirFileList != null) DirFileList.ItemsSource = null;
                if (RegTree != null) RegTree.ItemsSource = null;
                if (RegValueList != null) RegValueList.ItemsSource = null;
                if (RegValueEditorHost != null) RegValueEditorHost.Content = null;
                if (ScTree != null) ScTree.ItemsSource = null;
                if (ScEditorHost != null) ScEditorHost.Content = null;
                if (FeatTree != null) FeatTree.ItemsSource = null;
                if (FeatCompList != null) FeatCompList.ItemsSource = null;
                if (CaList != null) CaList.ItemsSource = null;
                if (CaEditorHost != null) CaEditorHost.Content = null;
                if (SeqList != null) SeqList.ItemsSource = null;
                if (SeqEditorHost != null) SeqEditorHost.Content = null;
                if (UpgList != null) UpgList.ItemsSource = null;
                if (UpgEditorHost != null) UpgEditorHost.Content = null;
                if (FormPlaceholder != null) FormPlaceholder.Visibility = Visibility.Visible;
                if (FormPlaceholderText != null)
                    FormPlaceholderText.Text = _msiPath.Length == 0
                        ? $"Open an MSI to edit {label}."
                        : $"This package has no {label} table, and SwiftPack does not have its "
                        + "column layout to create one.";
                return;
            }

            // Properties and Files have purpose-built friendly editors; everything
            // else gets the filterable grid. All edit the same staged DataTable.
            if (string.Equals(table, "Property", StringComparison.OrdinalIgnoreCase))
            {
                _formGridTable = "Property";
                // Sorted on the view rather than the table, so the underlying rows and their
                // staged edits are untouched and a newly added property lands in its place in
                // the list instead of at the bottom. Guarded because the rest of this page
                // already allows for a package whose first column is not literally "Property",
                // and DataView.Sort throws on a column it cannot find.
                _propsView = new DataView(st.Data) { RowFilter = BuildPropFilter("") };
                if (st.Data.Columns.Contains("Property")) _propsView.Sort = "Property ASC";
                PropList.ItemsSource = _propsView;
                UpdatePropCount();
                _propFind.Go.Clear();
                if (PropSearchCount != null) PropSearchCount.Text = "";
                SearchPh(PropSearch, PropSearchPh);
                if (FormPropsPanel != null) FormPropsPanel.Visibility = Visibility.Visible;
            }
            else if (string.Equals(table, "File", StringComparison.OrdinalIgnoreCase))
            {
                ShowFilesForm(st);
            }
            else if (string.Equals(table, "Registry", StringComparison.OrdinalIgnoreCase))
            {
                ShowRegistryForm(st);
            }
            else if (string.Equals(table, "Shortcut", StringComparison.OrdinalIgnoreCase))
            {
                ShowShortcutsForm(st);
            }
            else if (string.Equals(table, "Feature", StringComparison.OrdinalIgnoreCase))
            {
                ShowFeaturesForm(st);
            }
            else if (string.Equals(tag, "table:ScheduledTasks", StringComparison.OrdinalIgnoreCase))
            {
                ShowTasksForm(st);
            }
            else if (string.Equals(tag, "table:Certificates", StringComparison.OrdinalIgnoreCase))
            {
                ShowCertsForm(st);
            }
            else if (string.Equals(tag, "table:Drivers", StringComparison.OrdinalIgnoreCase))
            {
                ShowDriversForm(st);
            }
            else if (string.Equals(tag, "table:Firewall", StringComparison.OrdinalIgnoreCase))
            {
                ShowFirewallForm(st);
            }
            else if (string.Equals(table, "CustomAction", StringComparison.OrdinalIgnoreCase))
            {
                ShowCustomActionsForm(st);
            }
            else if (string.Equals(table, "Upgrade", StringComparison.OrdinalIgnoreCase))
            {
                ShowUpgradeForm(st);
            }
            else if (string.Equals(table, "Environment", StringComparison.OrdinalIgnoreCase))
            {
                ShowEnvironmentForm(st);
            }
            else if (string.Equals(table, "ServiceInstall", StringComparison.OrdinalIgnoreCase))
            {
                ShowServicesForm(st);
            }
            else if (string.Equals(table, "IniFile", StringComparison.OrdinalIgnoreCase))
            {
                ShowIniForm(st);
            }
            else if (string.Equals(table, "AppSearch", StringComparison.OrdinalIgnoreCase))
            {
                ShowSearchForm(st);
            }
            else if (string.Equals(table, "ODBCDriver", StringComparison.OrdinalIgnoreCase))
            {
                ShowOdbcForm(st);
            }
            else if (string.Equals(table, "Dialog", StringComparison.OrdinalIgnoreCase))
            {
                ShowDialogsForm(st);
            }
            else
            {
                _formGridTable = table;
                _gridView = new DataView(st.Data);
                FormGrid.ItemsSource = _gridView;
                if (TxtGridFilter != null) TxtGridFilter.Text = "";
                FormGridTitle.Text = $"{table} - {_gridView.Count} row(s)";
                if (FormGridPanel != null) FormGridPanel.Visibility = Visibility.Visible;
            }

            if (created && TxtStatus != null)
                TxtStatus.Text = $"{label}: this package has no {table} table yet. Adding anything "
                               + "here creates it when you Save or Create MST.";
        }

        private void BtnGoTables_Click(object sender, RoutedEventArgs e)
        {
            SetViewMode(false);
            if (_placeholderTable.Length > 0 && LstTables.Items.Contains(_placeholderTable))
            {
                LstTables.SelectedItem = _placeholderTable;
                LstTables.ScrollIntoView(_placeholderTable);
            }
        }

        // ── Category grid (Files / Registry / Shortcuts / Upgrade / … ) ──────
        // An editable grid over the selected table. Cell edits, Add Row and Delete
        // Row all use the same staged DataTable as the Tables view, so Create MST /
        // Save / Validate pick them up unchanged.
        private void FormGrid_AutoGeneratingColumn(object sender, DataGridAutoGeneratingColumnEventArgs e)
        {
            if (_formGridTable.Length == 0 || !_tables.TryGetValue(_formGridTable, out var st)) return;

            if (st.ColKind.TryGetValue(e.PropertyName, out char k) && k == 'v')
                e.Column.IsReadOnly = true;   // binary streams cannot be edited as text

            // Same dropdowns and header tooltips as the Tables grid. These views need them more,
            // not less: ServiceInstall.Component_ and AppSearch.Property are exactly the columns
            // nobody remembers the exact spelling of.
            bool hasRef = TryGetColumnReference(_formGridTable, e.PropertyName, out string refTable, out string refCol);
            if (hasRef)
            {
                string keep = _currentTable;
                _currentTable = _formGridTable;                  // ForeignKeyChoices reads it
                var choices = ForeignKeyChoices(refTable, refCol, e.PropertyName);
                _currentTable = keep;

                if (choices.Count > 0)
                {
                    var display = new FrameworkElementFactory(typeof(TextBlock));
                    display.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding(e.PropertyName));
                    display.SetValue(FrameworkElement.MarginProperty, new Thickness(6, 0, 6, 0));
                    display.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center);

                    var editor = new FrameworkElementFactory(typeof(ComboBox));
                    editor.SetValue(ComboBox.IsEditableProperty, true);
                    editor.SetValue(ComboBox.IsTextSearchEnabledProperty, true);
                    editor.SetValue(ItemsControl.ItemsSourceProperty, choices);
                    editor.SetValue(FrameworkElement.MarginProperty, new Thickness(0));
                    editor.SetBinding(ComboBox.TextProperty, new System.Windows.Data.Binding(e.PropertyName)
                    {
                        Mode = System.Windows.Data.BindingMode.TwoWay,
                        UpdateSourceTrigger = System.Windows.Data.UpdateSourceTrigger.PropertyChanged,
                    });

                    e.Column = new DataGridTemplateColumn
                    {
                        Header = e.PropertyName,
                        CellTemplate        = new DataTemplate { VisualTree = display },
                        CellEditingTemplate = new DataTemplate { VisualTree = editor },
                        SortMemberPath      = e.PropertyName,
                    };
                }
            }

            if (st.ColType.TryGetValue(e.PropertyName, out string? type) && type.Length > 1)
            {
                string tip = $"{e.PropertyName}  ({type})";
                if (st.KeyCols.Contains(e.PropertyName, StringComparer.OrdinalIgnoreCase))
                    tip += "\nPart of the primary key.";
                tip += st.NullableCols.Contains(e.PropertyName) ? "\nOptional." : "\nRequired.";
                if (hasRef) tip += $"\nRefers to {refTable}.{refCol}.";

                var hs = new Style(typeof(System.Windows.Controls.Primitives.DataGridColumnHeader),
                                   FormGrid.ColumnHeaderStyle);
                hs.Setters.Add(new Setter(FrameworkElement.ToolTipProperty, tip));
                e.Column.HeaderStyle = hs;
            }
        }

        private void FormGrid_AutoGeneratedColumns(object? sender, EventArgs e)
        {
            int count = FormGrid.Columns.Count;
            if (count == 0) return;
            for (int i = 0; i < count; i++)
            {
                FormGrid.Columns[i].MinWidth = 44;
                FormGrid.Columns[i].Width = new DataGridLength(1, DataGridLengthUnitType.Auto);
            }
            Dispatcher.BeginInvoke(new Action(() =>
            {
                int c = FormGrid.Columns.Count;
                if (c == 0 || FormGrid.ActualWidth <= 0) return;
                var last = FormGrid.Columns[c - 1];
                last.Width = new DataGridLength(1, DataGridLengthUnitType.Auto);
                FormGrid.UpdateLayout();
                double used = 0;
                for (int i = 0; i < c; i++) used += FormGrid.Columns[i].ActualWidth;
                if (used + 32 < FormGrid.ActualWidth)
                    last.Width = new DataGridLength(1, DataGridLengthUnitType.Star);
            }), System.Windows.Threading.DispatcherPriority.Loaded);
        }

        private void FormAddRow_Click(object sender, RoutedEventArgs e)
        {
            if (_formGridTable.Length == 0 || !_tables.TryGetValue(_formGridTable, out var st)) return;
            var nr = st.Data.NewRow();
            st.Data.Rows.Add(nr);
            UpdateEditCount();
            int count = _gridView?.Count ?? st.Data.DefaultView.Count;
            FormGridTitle.Text = $"{_formGridTable} - {count} row(s)";
            if (count > 0) FormGrid.SelectedIndex = count - 1;
            if (FormGrid.SelectedItem != null) FormGrid.ScrollIntoView(FormGrid.SelectedItem);
        }

        private void FormDeleteRow_Click(object sender, RoutedEventArgs e)
        {
            if (FormGrid.SelectedItem is not DataRowView drv) return;
            drv.Row.Delete();
            UpdateEditCount();
            int count = _gridView?.Count ?? 0;
            FormGridTitle.Text = $"{_formGridTable} - {count} row(s)";
        }

        // Filter the generic grid across every string column.
        private void TxtGridFilter_TextChanged(object sender, TextChangedEventArgs e)
        {
            if (_gridView == null) return;
            string term = TxtGridFilter.Text?.Trim() ?? "";
            if (term.Length == 0) { _gridView.RowFilter = ""; }
            else
            {
                string esc = EscapeLike(term);
                var parts = _gridView.Table!.Columns.Cast<DataColumn>()
                    .Select(c => $"[{c.ColumnName}] LIKE '%{esc}%'");
                _gridView.RowFilter = string.Join(" OR ", parts);
            }
            FormGridTitle.Text = $"{_formGridTable} - {_gridView.Count} row(s)";
        }

        // ── Friendly Properties editor ──────────────────────────────────────
        // Per-panel search: highlight and step through matching properties (the
        // list is not filtered), matching the Files/Registry search behaviour.
        private void PropSearch_Changed(object sender, TextChangedEventArgs e)
        {
            SearchPh(PropSearch, PropSearchPh);
            _propFind.Go.Clear();
            string q = PropSearch?.Text?.Trim() ?? "";
            if (q.Length > 0 && _propsView != null)
            {
                foreach (System.Data.DataRowView drv in _propsView)
                {
                    string name = drv.Row.Table.Columns.Contains("Property") ? Cv(drv["Property"]) : "";
                    string val  = drv.Row.Table.Columns.Contains("Value")    ? Cv(drv["Value"])    : "";
                    if (Hit(name, q) || Hit(val, q))
                    {
                        var item = drv;
                        _propFind.Go.Add(() =>
                        {
                            if (PropList == null) return;
                            PropList.SelectedItem = item;
                            PropList.ScrollIntoView(item);
                        });
                    }
                }
            }
            FindReset(_propFind, PropSearchCount);
            if (q.Length == 0 && PropSearchCount != null) PropSearchCount.Text = "";
        }

        private void PropSearch_Key(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { FindStep(_propFind, PropSearchCount, 1); e.Handled = true; } }
        private void PropPrev_Click(object sender, RoutedEventArgs e) => FindStep(_propFind, PropSearchCount, -1);
        private void PropNext_Click(object sender, RoutedEventArgs e) => FindStep(_propFind, PropSearchCount, 1);

        private static string BuildPropFilter(string? text)
        {
            string term = text?.Trim() ?? "";
            if (term.Length == 0) return "";
            string esc = EscapeLike(term);
            return $"Property LIKE '%{esc}%' OR Value LIKE '%{esc}%'";
        }

        // Escapes a literal for use inside a DataView RowFilter LIKE pattern.
        private static string EscapeLike(string s)
        {
            var sb = new System.Text.StringBuilder();
            foreach (char c in s)
            {
                if (c == '%' || c == '*' || c == '[' || c == ']') sb.Append('[').Append(c).Append(']');
                else if (c == '\'') sb.Append("''");
                else sb.Append(c);
            }
            return sb.ToString();
        }

        private void UpdatePropCount()
        {
            if (PropCount == null) return;
            PropCount.Text = _propsView == null ? "" : $"{_propsView.Count} shown";
        }

        /// <summary>
        /// Selects a Property row in the friendly Properties list and scrolls it into view.
        /// The list is sorted by name, so a property that was just added does not land at the
        /// bottom next to the box it was typed into: it drops into its alphabetical place,
        /// usually off screen, and the click looked like it had done nothing. Deferred because
        /// adding a row re-sorts the view and rebuilds the very container this scrolls to.
        /// </summary>
        private void RevealPropertyRow(System.Data.DataRow? target)
        {
            if (target == null || PropList == null) return;
            Dispatcher.BeginInvoke(new Action(() =>
            {
                if (PropList?.ItemsSource is not System.Collections.IEnumerable items) return;
                foreach (var o in items)
                {
                    if (o is System.Data.DataRowView drv && ReferenceEquals(drv.Row, target))
                    {
                        PropList.SelectedItem = o;
                        PropList.UpdateLayout();
                        PropList.ScrollIntoView(o);
                        return;
                    }
                }
            }), System.Windows.Threading.DispatcherPriority.Background);
        }

        /// <summary>
        /// Brings the friendly Properties list on screen with <paramref name="target"/> selected.
        /// The toolbar Add can be clicked from any category, and it only ever navigated the Tables
        /// grid, which the Visual view keeps hidden, so there the staged row landed in a list the
        /// user was not looking at. Does nothing in Tables view, which already selects the row in
        /// the grid it is showing.
        /// </summary>
        private void RevealPropertyInFormView(System.Data.DataRow? target)
        {
            if (!_formMode || target == null) return;

            if (LstCategories != null)
            {
                foreach (var o in LstCategories.Items)
                {
                    if (o is ListBoxItem lbi &&
                        string.Equals(lbi.Tag as string, "table:Property", StringComparison.Ordinal))
                    {
                        // Re-selecting the current item raises nothing, which is what we want here:
                        // the list is already bound and its DataView has picked the new row up.
                        if (!ReferenceEquals(LstCategories.SelectedItem, lbi))
                            LstCategories.SelectedItem = lbi;   // fires ShowCategory, rebinds PropList
                        break;
                    }
                }
            }

            RevealPropertyRow(target);
        }

        private void PropValue_Lost(object sender, RoutedEventArgs e)
        {
            // The binding has pushed the new value into the row on LostFocus; defer
            // the recount so it sees the committed state.
            Dispatcher.BeginInvoke(new Action(UpdateEditCount),
                System.Windows.Threading.DispatcherPriority.Background);
        }

        private void PropDelete_Click(object sender, RoutedEventArgs e)
        {
            if ((sender as FrameworkElement)?.DataContext is not DataRowView drv) return;
            drv.Row.Delete();
            UpdateEditCount();
            UpdatePropCount();
        }

        private void BtnAddProp_Click(object sender, RoutedEventArgs e)
        {
            string name = TxtNewPropName.Text?.Trim() ?? "";
            string val  = TxtNewPropValue.Text?.Trim() ?? "";

            // These used to report through the status bar, which sits in a collapsed panel, so an
            // empty click looked like nothing happened at all. A blank value matters as much as a
            // blank name: SetProperty reads an empty value as "remove this property", so a name on
            // its own added nothing and said nothing either.
            if (name.Length == 0 || val.Length == 0)
            {
                string msg = name.Length == 0 && val.Length == 0
                    ? "Enter a property name and a value to add."
                    : name.Length == 0
                        ? "Enter a property name for this value."
                        : $"Enter a value for “{name}”.";
                MstMessage(msg, "Add property", MessageBoxButton.OK, MessageBoxImage.Warning);
                (name.Length == 0 ? TxtNewPropName : TxtNewPropValue).Focus();
                return;
            }

            if (GetProperty(name) == val)
            {
                MstMessage($"“{name}” already has the value “{val}”, so there is nothing to add.",
                    "Add property", MessageBoxButton.OK, MessageBoxImage.Warning);
                TxtNewPropValue.Focus();
                return;
            }

            SetProperty(name, val);   // adds, or overwrites the value of the existing property

            // Find the row that was just written so the list can show where it landed. The name
            // is the table's key, so this is the row SetProperty added or updated either way.
            var propSt = EnsureTableCached("Property");
            System.Data.DataRow? added = propSt == null ? null : FindLiveRow(propSt, "Property", name);

            TxtNewPropName.Clear();
            TxtNewPropValue.Clear();
            UpdatePropCount();
            RevealPropertyRow(added);
        }

        /// <summary>True when a live Property row other than <paramref name="except"/> already
        /// carries this name. Property is the table's key, so a duplicate cannot be written.</summary>
        private bool PropertyNameTaken(string name, DataRow? except)
        {
            if (!_tables.TryGetValue("Property", out var st) || !st.Data.Columns.Contains("Property"))
                return false;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted || st.MarkedDelete.Contains(r)) continue;
                if (ReferenceEquals(r, except)) continue;
                if (string.Equals(Cv(r["Property"]), name, StringComparison.OrdinalIgnoreCase)) return true;
            }
            return false;
        }

        /// <summary>
        /// Commits a renamed property. The name is the table's key, so a blank one or one another
        /// row already uses cannot be written and the box snaps back instead. The write itself is
        /// deferred because renaming re-sorts the list, which rebuilds the very row this event is
        /// running on.
        /// </summary>
        private void PropName_Lost(object sender, RoutedEventArgs e)
        {
            if (sender is not TextBox tb || tb.DataContext is not DataRowView drv) return;
            DataRow row = drv.Row;
            if (row.RowState == DataRowState.Deleted || !row.Table.Columns.Contains("Property")) return;

            string old  = Cv(row["Property"]);
            string want = (tb.Text ?? "").Trim();
            if (want == old) return;

            if (want.Length == 0)
            {
                tb.Text = old;
                MstMessage("A property needs a name.", "Property",
                    MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            if (PropertyNameTaken(want, row))
            {
                tb.Text = old;
                MstMessage($"“{want}” already exists in this package. A property name is the "
                         + "table's key, so it has to be unique.",
                    "Property", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            Dispatcher.BeginInvoke(new Action(() =>
            {
                if (row.RowState == DataRowState.Deleted) return;
                row["Property"] = want;
                UpdateEditCount();
                UpdatePropCount();
            }), System.Windows.Threading.DispatcherPriority.Background);
        }

        // Enter commits by moving on, which is what raises LostFocus above.
        private void PropName_KeyDown(object sender, System.Windows.Input.KeyEventArgs e)
        {
            if (e.Key != System.Windows.Input.Key.Enter && e.Key != System.Windows.Input.Key.Return) return;
            if (sender is TextBox tb)
                tb.MoveFocus(new System.Windows.Input.TraversalRequest(
                    System.Windows.Input.FocusNavigationDirection.Next));
            e.Handled = true;
        }

        // ── Files view: folder tree (left) + files in selected folder (right) ──
        private System.Collections.ObjectModel.ObservableCollection<FileRow>? _dirFileRows;

        // Standard MSI folder properties -> friendly Windows-style names.
        private static readonly Dictionary<string, string> StandardDirNames = new(StringComparer.OrdinalIgnoreCase)
        {
            ["TARGETDIR"]            = "Target Computer",
            ["ProgramFilesFolder"]   = "Program Files",
            ["ProgramFiles64Folder"] = "Program Files 64",
            ["CommonFilesFolder"]    = "Common Files",
            ["CommonFiles64Folder"]  = "Common Files 64",
            ["DesktopFolder"]        = "Desktop",
            ["StartMenuFolder"]      = "Start Menu",
            ["ProgramMenuFolder"]    = "Programs",
            ["StartupFolder"]        = "Startup",
            // Named the way Windows names these three, not the way the MSI property is spelled.
            // Nothing on screen said "ProgramData" while the property is CommonAppDataFolder, so
            // the folder read as missing when it was there under a name nobody searches for.
            ["AppDataFolder"]        = "Roaming AppData",
            ["LocalAppDataFolder"]   = "Local AppData",
            ["CommonAppDataFolder"]  = "ProgramData",
            ["PersonalFolder"]       = "Documents",
            ["MyPicturesFolder"]     = "Pictures",
            ["FavoritesFolder"]      = "Favorites",
            ["NetHoodFolder"]        = "Network Shortcuts",
            ["PrintHoodFolder"]      = "Printer Shortcuts",
            ["RecentFolder"]         = "Recent Items",
            ["SendToFolder"]         = "Send To",
            ["TemplateFolder"]       = "Templates",
            ["FontsFolder"]          = "Fonts",
            ["SystemFolder"]         = "System32",
            ["System64Folder"]       = "System64",
            ["System16Folder"]       = "System",
            ["WindowsFolder"]        = "Windows",
            ["WindowsVolume"]        = "Windows Volume",
            ["TempFolder"]           = "Temp",
            ["AdminToolsFolder"]     = "Administrative Tools",
            ["UserProfile"]          = "User Profile",
            ["PUBLIC"]               = "Public",
            ["GAC"]                  = "Global Assembly Cache",
            ["GlobalAssemblyCache"]  = "Global Assembly Cache"
        };

        // Friendly folder name. Standard folder keys always use their Windows name;
        // otherwise the real DefaultDir name, else a cleaned-up key (GUID suffix and
        // a leading "DIR_" removed).
        private static string FriendlyDir(string key, string longName)
        {
            if (StandardDirNames.TryGetValue(key, out var f1)) return f1;
            string baseKey = key;
            int dot = baseKey.IndexOf('.');
            if (dot > 0) baseKey = baseKey.Substring(0, dot);     // drop ".<guid>" disambiguator
            if (StandardDirNames.TryGetValue(baseKey, out var f2)) return f2;
            if (longName.Length > 0 && longName != ".") return longName;
            if (baseKey.StartsWith("DIR_", StringComparison.OrdinalIgnoreCase) && baseKey.Length > 4)
                baseKey = baseKey.Substring(4);
            return baseKey.Length > 0 ? baseKey : key;
        }

        private string _dirTreeBuiltFor = "\0";   // _msiPath the tree was built for

        private void ShowFilesForm(TableState fileSt)
        {
            // Already built for this MSI: keep the tree (and its expand state and
            // selection). Folder/file edits update it in place, so it stays current.
            if (_dirRoots != null && _dirTreeBuiltFor == _msiPath)
            {
                if (DirTree != null && DirTree.ItemsSource == null) DirTree.ItemsSource = _dirRoots;
                if (FormFilesPanel != null) FormFilesPanel.Visibility = Visibility.Visible;
                return;
            }

            static string Cell(DataRow r, string c) =>
                r.Table.Columns.Contains(c) && r[c] != DBNull.Value ? r[c].ToString() ?? "" : "";

            var dirSt  = EnsureTableCached("Directory");
            var compSt = EnsureTableCached("Component");

            // Component -> install directory
            var compDir = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (compSt != null)
                foreach (DataRow r in compSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string c = Cell(r, "Component");
                    if (c.Length > 0) compDir[c] = Cell(r, "Directory_");
                }

            // One node per directory (all directories are shown, like Explorer).
            var nodes = new Dictionary<string, DirNode>(StringComparer.OrdinalIgnoreCase);
            if (dirSt != null)
                foreach (DataRow r in dirSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string key = Cell(r, "Directory");
                    if (key.Length == 0) continue;
                    nodes[key] = new DirNode { Key = key, DefaultDir = Cell(r, "DefaultDir"), ParentKey = Cell(r, "Directory_Parent"), DirRow = r };
                }

            // Attach files to their directory; orphans to a synthetic bucket.
            DirNode? orphan = null;
            int total = 0;
            foreach (DataRow fr in fileSt.Data.Rows)
            {
                if (fr.RowState == DataRowState.Deleted) continue;
                total++;
                string dir = compDir.TryGetValue(Cell(fr, "Component_"), out var d) ? d : "";
                if (dir.Length > 0 && nodes.TryGetValue(dir, out var node)) node.Files.Add(fr);
                else { orphan ??= new DirNode { Key = "(unknown)" }; orphan.Files.Add(fr); }
            }

            // Wire the hierarchy; assign friendly names.
            var roots = new System.Collections.ObjectModel.ObservableCollection<DirNode>();
            foreach (var node in nodes.Values)
            {
                node.Display = FriendlyDir(node.Key, node.LongName);
                bool isRoot = node.ParentKey.Length == 0
                    || string.Equals(node.ParentKey, node.Key, StringComparison.OrdinalIgnoreCase)
                    || !nodes.ContainsKey(node.ParentKey);
                if (!isRoot && nodes.TryGetValue(node.ParentKey, out var p) && !ReferenceEquals(p, node))
                    { p.Children.Add(node); node.Parent = p; }
                else
                    roots.Add(node);
            }
            if (orphan != null) { orphan.Display = "(unknown)"; roots.Add(orphan); }

            SortNodes(roots);
            foreach (var r in roots) r.IsExpanded = true;   // open the top level only
            _dirRoots = roots;
            _dirTreeBuiltFor = _msiPath;

            DirTree.ItemsSource = roots;
            if (FileCount != null) FileCount.Text = total == 1 ? "1 file" : $"{total} files";
            _dirFileRows = null;
            if (DirFileList != null) DirFileList.ItemsSource = null;
            if (DirFilesTitle != null) DirFilesTitle.Text = "Select a folder";
            if (FormFilesPanel != null) FormFilesPanel.Visibility = Visibility.Visible;
        }

        // Sort each level alphabetically by folder name, like Windows Explorer.
        private static void SortNodes(System.Collections.ObjectModel.ObservableCollection<DirNode> list)
        {
            var ordered = list.OrderBy(n => n.Display, StringComparer.OrdinalIgnoreCase).ToList();
            list.Clear();
            foreach (var n in ordered) { SortNodes(n.Children); list.Add(n); }
        }

        private void DirTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is not DirNode node)
            {
                _dirFileRows = null;
                if (DirFileList != null) DirFileList.ItemsSource = null;
                if (DirFilesTitle != null) DirFilesTitle.Text = "Select a folder";
                return;
            }
            var rows = new System.Collections.ObjectModel.ObservableCollection<FileRow>();
            foreach (var dr in node.Files)
                if (dr.RowState != DataRowState.Deleted && dr.RowState != DataRowState.Detached)
                    rows.Add(new FileRow(dr, UpdateEditCount));
            MarkKeyPathFiles(rows);
            _dirFileRows = rows;
            DirFileList.ItemsSource = rows;
            UpdateDirTitle();
        }

        private void DirFileDelete_Click(object sender, RoutedEventArgs e)
        {
            if (DirFileList?.SelectedItem is not FileRow fr) return;

            // The folder keeps its own list of rows, and a refresh rebuilds from that, so the row
            // has to leave both. Deleting a row added in this session detaches it rather than
            // marking it Deleted, which the refresh filter would not have caught.
            string key = fr.Key;
            _dirFileRows?.Remove(fr);           // drop the binding first
            SelectedDir()?.Files.Remove(fr.Row);
            fr.Row.Delete();                    // then stage the delete
            if (key.Length > 0) { _addedFileSources.Remove(key); _addedFileMedia.Remove(key); }

            UpdateEditCount();
            UpdateDirTitle();
        }

        // Right-click selects the file under the cursor so the menu acts on it.
        private void DirFileList_RightDown(object sender, MouseButtonEventArgs e)
        {
            DependencyObject? d = e.OriginalSource as DependencyObject;
            while (d != null && d is not DataGridRow) d = VisualTreeHelper.GetParent(d);
            if (d is DataGridRow row)
            {
                row.IsSelected = true;
                if (DirFileList != null) DirFileList.SelectedItem = row.Item;
            }
        }

        // Make the selected file the KeyPath of its component.
        /// <summary>
        /// Asks before overwriting a component's key path. The wording is InstallShield's, kept
        /// word for word so a packager moving between the two tools reads the same question.
        /// True when there is nothing to replace or the replacement was agreed to.
        /// </summary>
        private bool ConfirmReplaceKeyPath(DataRow componentRow, string caption)
        {
            if (!componentRow.Table.Columns.Contains("KeyPath")) return true;
            if (Cv(componentRow["KeyPath"]).Length == 0) return true;

            return MstMessage(
                "You have already set a key file or a key path for this component. "
              + "Do you want to replace the current key?",
                caption, MessageBoxButton.YesNo, MessageBoxImage.Warning) == MessageBoxResult.Yes;
        }

        /// <summary>
        /// Drops a component's key path. With none set the installer treats the component's own
        /// folder as its key path, so the attribute bits that say the key path points at a
        /// registry entry or an ODBC data source have to go with it, or the component would be
        /// left claiming its key path is something it no longer has.
        /// </summary>
        private bool ClearComponentKeyPath(DataRow cr, string comp, string caption)
        {
            if (!cr.Table.Columns.Contains("KeyPath"))
            {
                MstMessage("The Component table has no KeyPath column.",
                    caption, MessageBoxButton.OK, MessageBoxImage.Warning);
                return false;
            }
            if (Cv(cr["KeyPath"]).Length == 0)
            {
                MstMessage($"\u201C{comp}\u201D has no key path set, so there is nothing to clear.",
                    caption, MessageBoxButton.OK, MessageBoxImage.Information);
                return false;
            }

            cr["KeyPath"] = "";
            if (cr.Table.Columns.Contains("Attributes"))
            {
                int a = int.TryParse(Cv(cr["Attributes"]), out var av) ? av : 0;
                a &= ~4;                     // msidbComponentAttributesRegistryKeyPath
                a &= ~32;                    // msidbComponentAttributesODBCDataSource
                cr["Attributes"] = a.ToString();
            }
            UpdateEditCount();
            return true;
        }

        private void FileClearKeyPath_Click(object sender, RoutedEventArgs e)
        {
            if (DirFileList?.SelectedItem is not FileRow fr) return;
            string comp = fr.Component;
            if (comp.Length == 0)
            { MstMessage("This file has no component to clear a key path on.", "Clear Key Path", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var cr = ComponentRow(comp);
            if (cr == null)
            { MstMessage($"Component \u201C{comp}\u201D was not found.", "Clear Key Path", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            if (!ClearComponentKeyPath(cr, comp, "Clear Key Path")) return;
            if (_dirFileRows != null) MarkKeyPathFiles(_dirFileRows);   // the key glyph goes with it
            TxtStatus.Text = $"Key path cleared for {comp}.";
        }

        private void RegClearKeyPath_Click(object sender, RoutedEventArgs e)
        {
            if (RegValueList?.SelectedItem is not RegValueRow vr) return;
            string comp = vr.Component;
            if (comp.Length == 0)
            { MstMessage("This entry has no component to clear a key path on.", "Clear Key Path", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var cr = ComponentRow(comp);
            if (cr == null)
            { MstMessage($"Component \u201C{comp}\u201D was not found.", "Clear Key Path", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            if (!ClearComponentKeyPath(cr, comp, "Clear Key Path")) return;
            if (_regValueRows != null) MarkKeyPathReg(_regValueRows);
            TxtStatus.Text = $"Key path cleared for {comp}.";
        }

        private void CompClearKeyPath_Click(object sender, RoutedEventArgs e)
        {
            if (_detailComp.Length == 0) return;
            var cr = ComponentRow(_detailComp);
            if (cr == null) return;

            if (!ClearComponentKeyPath(cr, _detailComp, "Clear Keypath")) return;
            if (_compDetailKind == "registry") ShowComponentRegistry(_detailComp);
            else                               ShowComponentFiles(_detailComp);
            TxtStatus.Text = $"Key path cleared for {_detailComp}.";
        }

        private void FileSetKeyPath_Click(object sender, RoutedEventArgs e)
        {
            if (DirFileList?.SelectedItem is not FileRow fr) return;
            string comp = fr.Component, fileKey = fr.Key;
            if (comp.Length == 0 || fileKey.Length == 0)
            { MstMessage("This file has no component to set a key path on.", "Set Key Path", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var compSt = EnsureTableCached("Component");
            if (compSt == null || !compSt.Data.Columns.Contains("KeyPath"))
            { MstMessage("The Component table has no KeyPath column.", "Set Key Path", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            DataRow? cr = null;
            foreach (DataRow r in compSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Component"]), comp, StringComparison.OrdinalIgnoreCase)) { cr = r; break; }
            }
            if (cr == null)
            { MstMessage($"Component \u201C{comp}\u201D was not found.", "Set Key Path", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            if (Cv(cr["KeyPath"]) == fileKey)
            { TxtStatus.Text = $"{fr.LongName} is already the key path for {comp}."; return; }

            if (!ConfirmReplaceKeyPath(cr, "Set Key Path")) return;

            cr["KeyPath"] = fileKey;
            UpdateEditCount();
            if (_dirFileRows != null) MarkKeyPathFiles(_dirFileRows);
            TxtStatus.Text = $"Key path for {comp} set to {fr.LongName}.";
        }

        private void UpdateDirTitle()
        {
            if (DirFilesTitle == null) return;
            int n = _dirFileRows?.Count ?? 0;
            DirFilesTitle.Text = n == 1 ? "1 file" : $"{n} files";
        }

        // ── Folder context-menu actions ────────────────────────────────────
        private System.Collections.ObjectModel.ObservableCollection<DirNode>? _dirRoots;

        private DirNode? SelectedDir() => DirTree?.SelectedItem as DirNode;

        /// <summary>
        /// Rename and Delete are dropped from the menu for a folder Windows Installer provides for
        /// itself. Program Files, Fonts, System64 and the rest are not the package's rows to alter:
        /// the key is what makes the folder resolve on the target machine, and deleting the row
        /// only removes the package's handle on a folder that still exists. Adding files to one and
        /// creating subfolders under it stay available, since those are ordinary things to do.
        /// </summary>
        private void DirTree_ContextMenuOpening(object sender, ContextMenuEventArgs e)
        {
            var n = SelectedDir();
            bool editable = n != null && !IsFixedFolder(n);

            static void Show(UIElement? el, bool on)
            { if (el != null) el.Visibility = on ? Visibility.Visible : Visibility.Collapsed; }

            Show(MiDirRename, editable);
            Show(MiDirDelete, editable);
        }

        // Right-click selects the folder under the cursor so the menu acts on it.
        private void DirTree_RightDown(object sender, MouseButtonEventArgs e)
        {
            DependencyObject? d = e.OriginalSource as DependencyObject;
            while (d != null && d is not TreeViewItem) d = VisualTreeHelper.GetParent(d);
            if (d is TreeViewItem tvi) { tvi.IsSelected = true; tvi.Focus(); }
        }

        private static void SetExpanded(DirNode n, bool ex)
        {
            n.IsExpanded = ex;
            foreach (var ch in n.Children) SetExpanded(ch, ex);
        }

        private void DirExpand_Click(object sender, RoutedEventArgs e)
        { if (SelectedDir() is { } n) SetExpanded(n, true); }

        private void DirCollapse_Click(object sender, RoutedEventArgs e)
        {
            if (SelectedDir() is not { } n) return;
            foreach (var ch in n.Children) SetExpanded(ch, false);
            n.IsExpanded = false;
        }

        private void DirRenameFolder_Click(object sender, RoutedEventArgs e)
        {
            var n = SelectedDir();
            if (n?.DirRow == null)
            { MstMessage("This folder cannot be renamed.", "Rename Folder", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            // Checked here and not only in the menu, because F2 reaches this without opening one.
            if (IsFixedFolder(n))
            {
                MstMessage($"\u201C{n.Display}\u201D is a folder Windows Installer resolves for "
                         + "itself on the target machine, so it has no name of this package's to "
                         + "change.",
                    "Rename Folder", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            string? name = PromptText("Rename Folder", "Name", n.Display);
            if (string.IsNullOrWhiteSpace(name)) return;
            name = name.Trim();
            if (n.DirRow.Table.Columns.Contains("DefaultDir"))
                n.DirRow["DefaultDir"] = MakeDefaultDir(name, n.DirRow["DefaultDir"]?.ToString() ?? "");
            n.Display = name;
            UpdateEditCount();
        }

        private void DirCreateFolder_Click(object sender, RoutedEventArgs e)
        {
            var n = SelectedDir();
            if (n == null) return;
            var dirSt = EnsureTableCached("Directory");
            if (dirSt == null)
            { MstMessage("This MSI has no Directory table.", "Create Folder", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            string? name = PromptText("Create Folder", "Name", "New Folder");
            if (string.IsNullOrWhiteSpace(name)) return;
            name = name.Trim();

            string key = UniqueKey(dirSt.Data, "Directory", SanitizeKey(name));
            var nr = dirSt.Data.NewRow();
            nr["Directory"] = key;
            if (dirSt.Data.Columns.Contains("Directory_Parent")) nr["Directory_Parent"] = n.Key;
            if (dirSt.Data.Columns.Contains("DefaultDir"))        nr["DefaultDir"]       = name;
            dirSt.Data.Rows.Add(nr);

            var child = new DirNode { Key = key, DefaultDir = name, ParentKey = n.Key, DirRow = nr, Display = name, Parent = n };
            int idx = 0;
            while (idx < n.Children.Count &&
                   string.Compare(n.Children[idx].Display, name, StringComparison.OrdinalIgnoreCase) < 0) idx++;
            n.Children.Insert(idx, child);
            n.IsExpanded = true;
            UpdateEditCount();
        }

        // ── Predefined folders ─────────────────────────────────────────────
        // The standard Windows locations a package installs into. Every one of these is a
        // child of TARGETDIR in the Directory table, which is why the submenu always works
        // from Target Computer whichever folder was right-clicked. An empty entry draws a
        // separator, so the groups below are the groups on screen.
        private static readonly string[] PredefinedDirKeys =
        {
            "ProgramFilesFolder", "ProgramFiles64Folder", "CommonFilesFolder", "CommonFiles64Folder",
            "",
            "CommonAppDataFolder", "AppDataFolder", "LocalAppDataFolder", "PersonalFolder", "MyPicturesFolder",
            "",
            "DesktopFolder", "ProgramMenuFolder", "StartMenuFolder", "StartupFolder", "AdminToolsFolder",
            "",
            "WindowsFolder", "SystemFolder", "System64Folder", "FontsFolder", "TempFolder",
            "",
            "UserProfile", "PUBLIC", "TemplateFolder", "FavoritesFolder",
        };

        /// <summary>
        /// The Target Computer node, which every predefined folder hangs off. TARGETDIR by key,
        /// falling back to the first root backed by a real Directory row so a package that names
        /// its root something else still works. The synthetic "(unknown)" bucket is skipped: it
        /// has no row, so nothing can be parented to it.
        /// </summary>
        private DirNode? TargetDirNode()
        {
            if (_dirRoots == null) return null;
            foreach (var r in _dirRoots)
                if (string.Equals(r.Key, "TARGETDIR", StringComparison.OrdinalIgnoreCase)) return r;
            foreach (var r in _dirRoots)
                if (r.DirRow != null) return r;
            return null;
        }

        /// <summary>The tree node for a Directory key, at any depth, or null when the package
        /// does not define that folder.</summary>
        private static DirNode? FindDirNode(System.Collections.Generic.IEnumerable<DirNode> list, string key)
        {
            foreach (var n in list)
            {
                if (string.Equals(n.Key, key, StringComparison.OrdinalIgnoreCase)) return n;
                var hit = FindDirNode(n.Children, key);
                if (hit != null) return hit;
            }
            return null;
        }

        /// <summary>
        /// Fills the Show Predefined Folder submenu each time it opens so the tick against a
        /// folder the package already defines is current. Built in code rather than declared in
        /// XAML because that state changes as folders are added and deleted.
        /// </summary>
        private void MiShowPredefined_Opened(object sender, RoutedEventArgs e)
        {
            if (sender is not MenuItem host) return;
            host.Items.Clear();

            if (TargetDirNode() == null || EnsureTableCached("Directory") == null)
            {
                host.Items.Add(new MenuItem { Header = "Open an MSI with a Directory table first.", IsEnabled = false });
                return;
            }

            bool wantSeparator = false;
            foreach (string key in PredefinedDirKeys)
            {
                if (key.Length == 0) { wantSeparator = host.Items.Count > 0; continue; }
                if (wantSeparator) { host.Items.Add(new Separator()); wantSeparator = false; }

                bool present = _dirRoots != null && FindDirNode(_dirRoots, key) != null;
                string friendly = StandardDirNames.TryGetValue(key, out var f) ? f : key;

                var mi = new MenuItem
                {
                    Header = $"{friendly}   [{key}]",
                    Tag = key,
                    ToolTip = present
                        ? "Already in this package. Selecting it jumps to the folder."
                        : "Not in this package yet. Selecting it adds the folder under Target Computer.",
                };

                // Only the folders already in the package carry a glyph, which makes the icon
                // column read as the tick column. The folder emoji that used to sit against the
                // rest drew clipped: it is taller than the 16x16 icon slot at any size worth
                // reading, and it said nothing the row was not already saying.
                if (present)
                    mi.Icon = new TextBlock
                    {
                        Text = "✔",
                        FontSize = 12,
                        HorizontalAlignment = HorizontalAlignment.Center,
                        VerticalAlignment = VerticalAlignment.Center,
                    };

                mi.Click += DirPredefinedFolder_Click;
                host.Items.Add(mi);
            }
        }

        private void DirPredefinedFolder_Click(object sender, RoutedEventArgs e)
        {
            if (sender is MenuItem mi && mi.Tag is string key && key.Length > 0) ShowPredefinedFolder(key);
        }

        /// <summary>
        /// Brings a standard Windows location onto the folder tree. Already defined: selects it,
        /// staging nothing. Not defined: adds a Directory row under TARGETDIR with DefaultDir "."
        /// (how a predefined folder is authored - the name is the property, and Windows Installer
        /// already knows where it resolves to) and puts the node in place.
        /// </summary>
        private void ShowPredefinedFolder(string key)
        {
            var root  = TargetDirNode();
            var dirSt = EnsureTableCached("Directory");
            if (root == null || dirSt == null)
            {
                MstMessage("Open an MSI with a Directory table first.", "Show Predefined Folder",
                    MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            // Already on the tree: this is a jump, not an edit.
            var shown = _dirRoots == null ? null : FindDirNode(_dirRoots, key);
            if (shown != null)
            {
                RevealDir(shown);
                if (TxtStatus != null)
                    TxtStatus.Text = $"{shown.Display} ({key}) is already in this package.";
                return;
            }

            // Directory is the table's key, so a second row under the same name could not be
            // written. Adopt a live row the tree somehow missed, and undelete one deleted earlier
            // in this session, rather than staging a duplicate either way.
            DataRow? row = FindLiveRow(dirSt, "Directory", key) ?? UndeleteDirRow(dirSt, key);
            bool staged = false;
            if (row == null)
            {
                row = dirSt.Data.NewRow();
                row["Directory"] = key;
                if (dirSt.Data.Columns.Contains("Directory_Parent")) row["Directory_Parent"] = root.Key;
                if (dirSt.Data.Columns.Contains("DefaultDir"))       row["DefaultDir"]       = ".";
                dirSt.Data.Rows.Add(row);
                staged = true;
            }

            // A new row is authored under TARGETDIR. A row that already existed keeps the parent
            // it records, so an undeleted folder goes back where it was rather than being
            // silently re-homed under Target Computer.
            DirNode parent = root;
            if (!staged && dirSt.Data.Columns.Contains("Directory_Parent") && _dirRoots != null)
            {
                string parentKey = Cv(row["Directory_Parent"]);
                if (parentKey.Length > 0) parent = FindDirNode(_dirRoots, parentKey) ?? root;
            }

            var node = new DirNode
            {
                Key        = key,
                DefaultDir = dirSt.Data.Columns.Contains("DefaultDir") ? Cv(row["DefaultDir"]) : ".",
                ParentKey  = parent.Key,
                DirRow     = row,
                Parent     = parent,
            };
            node.Display = FriendlyDir(key, node.LongName);

            int idx = 0;
            while (idx < parent.Children.Count &&
                   string.Compare(parent.Children[idx].Display, node.Display, StringComparison.OrdinalIgnoreCase) < 0) idx++;
            parent.Children.Insert(idx, node);
            parent.IsExpanded = true;

            UpdateEditCount();
            RevealDir(node);
            if (TxtStatus != null)
                TxtStatus.Text = staged
                    ? $"Added {node.Display} ({key}) under {parent.Display}."
                    : $"{node.Display} ({key}) is shown again under {parent.Display}.";
        }

        /// <summary>
        /// Restores a Directory row deleted earlier in this session and returns it, so re-showing
        /// a predefined folder brings the original row back instead of staging a second row that
        /// carries the same key. Returns null when no deleted row uses that name.
        /// </summary>
        private static DataRow? UndeleteDirRow(TableState st, string key)
        {
            if (!st.Data.Columns.Contains("Directory")) return null;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState != DataRowState.Deleted) continue;
                if (!string.Equals(Cv(r["Directory", DataRowVersion.Original]), key, StringComparison.OrdinalIgnoreCase))
                    continue;
                r.RejectChanges();
                return r;
            }
            return null;
        }

        private void DirDeleteFolder_Click(object sender, RoutedEventArgs e)
        {
            var n = SelectedDir();
            if (n?.DirRow == null)
            { MstMessage("This folder cannot be deleted.", "Delete Folder", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            // Checked here and not only in the menu, because Del reaches this without opening one.
            if (IsFixedFolder(n))
            {
                MstMessage($"\u201C{n.Display}\u201D is a folder Windows provides, not one this "
                         + "package created, so it cannot be deleted. What the package installs "
                         + "into it can still be deleted on its own.",
                    "Delete Folder", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            if (MstMessage($"Delete folder \u201C{n.Display}\u201D and all of its files and subfolders?",
                    "Delete Folder", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;

            DeleteSubtree(n);
            if (n.Parent != null) n.Parent.Children.Remove(n);
            else _dirRoots?.Remove(n);
            _dirFileRows = null;
            if (DirFileList != null) DirFileList.ItemsSource = null;
            if (DirFilesTitle != null) DirFilesTitle.Text = "Select a folder";
            UpdateEditCount();
        }

        private static void DeleteSubtree(DirNode n)
        {
            foreach (var f in n.Files)
                if (f.RowState != DataRowState.Deleted) f.Delete();
            foreach (var ch in n.Children) DeleteSubtree(ch);
            if (n.DirRow != null && n.DirRow.RowState != DataRowState.Deleted) n.DirRow.Delete();
        }

        private void DirAddFiles_Click(object sender, RoutedEventArgs e)
        {
            var n = SelectedDir();
            if (n?.DirRow == null)
            { MstMessage("Files cannot be added to this folder.", "Add Files", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            var fileSt = EnsureTableCached("File");
            if (fileSt == null)
            { MstMessage("This MSI has no File table.", "Add Files", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            var dlg = new OpenFileDialog { Title = "Add Files", Multiselect = true };
            if (dlg.ShowDialog() != true) return;

            // Where the bytes go is asked once per batch, before any row is staged, so backing
            // out here leaves nothing half-added.
            FileMedia? media = AskFileMedia(dlg.FileNames.Length);
            if (media == null) return;

            // One NEW component per batch, named after the first file selected. Not the folder's
            // existing component: a file added later has nothing to do with what is already there,
            // and sharing a component means it cannot be given its own key path, cannot be
            // conditioned on its own, and is removed only when the whole component is. A batch
            // shares one component because the files were chosen together and travel together.
            string firstName = System.IO.Path.GetFileName(dlg.FileNames[0]);
            string? comp = CreateComponentForFile(firstName, n.Key);
            if (comp == null)
            { MstMessage("Could not create a component for this folder.", "Add Files", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            int seq = NextSequence(fileSt.Data);
            bool any = false;
            string lastName = "", lastKey = "";
            int added = 0;
            foreach (string path in dlg.FileNames)
            {
                try
                {
                    var fi = new FileInfo(path);
                    string longName = fi.Name;
                    string key = UniqueKey(fileSt.Data, "File", FileKeyFromName(longName));
                    string ver = "";
                    try { ver = System.Diagnostics.FileVersionInfo.GetVersionInfo(path).FileVersion ?? ""; } catch { }

                    var nr = fileSt.Data.NewRow();
                    nr["File"] = key;
                    if (fileSt.Data.Columns.Contains("Component_")) nr["Component_"] = comp;
                    if (fileSt.Data.Columns.Contains("FileName"))   nr["FileName"]   = FileNameField(longName);
                    if (fileSt.Data.Columns.Contains("FileSize"))   nr["FileSize"]   = fi.Length.ToString();
                    if (fileSt.Data.Columns.Contains("Version") && ver.Length > 0) nr["Version"] = ver;
                    // Compressed when the bytes go into a cabinet, Noncompressed when they sit
                    // loose beside the package. Getting this wrong sends the installer looking
                    // in the wrong place at install time.
                    if (fileSt.Data.Columns.Contains("Attributes")) nr["Attributes"] = FileAttrsFor(media.Value);
                    if (fileSt.Data.Columns.Contains("Sequence"))   nr["Sequence"]   = (++seq).ToString();
                    fileSt.Data.Rows.Add(nr);
                    n.Files.Add(nr);
                    _addedFileSources[key] = path;
                    _addedFileMedia[key]   = media.Value;
                    any = true;
                    added++;
                    lastName = longName; lastKey = key;
                }
                catch { }
            }
            if (any)
            {
                UpdateEditCount();
                if (ReferenceEquals(DirTree?.SelectedItem, n)) RefreshDirFiles(n);
                if (TxtStatus != null)
                    TxtStatus.Text = added == 1
                        ? $"Added {lastName} (File key {lastKey}). Right-click it to set the key path."
                        : $"Added {added} files to {n.Display}.";
            }
        }

        private void RefreshDirFiles(DirNode n)
        {
            var rows = new System.Collections.ObjectModel.ObservableCollection<FileRow>();
            foreach (var dr in n.Files)
                if (dr.RowState != DataRowState.Deleted && dr.RowState != DataRowState.Detached)
                    rows.Add(new FileRow(dr, UpdateEditCount));
            MarkKeyPathFiles(rows);
            _dirFileRows = rows;
            if (DirFileList != null) DirFileList.ItemsSource = rows;
            UpdateDirTitle();
        }

        // ══ Permissions (LockPermissions table) ════════════════════════════
        // A file or folder is secured by one LockPermissions row per user: LockObject names the
        // File key or, for a folder, the Directory key, and Table says which of the two it is.
        // A folder goes through CreateFolder rather than Directory, so the folder also has to be
        // listed in the CreateFolder table before it can be secured.
        //
        // Worth knowing about this table, because both shape the dialog below: the rights it
        // writes replace the object's whole ACL instead of adding to it, so an object secured
        // without an administrators entry locks administrators out; and a package must not carry
        // both this table and MsiLockPermissionsEx, or Windows Installer 5.0 refuses to install
        // it with error 1941.

        // The rights Windows shows as named sets in its own permissions dialog, as file and folder
        // access masks. Every one is a subset of full control, so anything outside full control is
        // a right the named boxes cannot express and shows as "Special permissions" instead.
        private const int PermFull        = 0x001F01FF;   // FILE_ALL_ACCESS
        private const int PermModify      = 0x001301BF;
        private const int PermReadExecute = 0x001200A9;
        private const int PermRead        = 0x00120089;
        private const int PermWrite       = 0x00100116;

        // A registry key takes a different access mask entirely, which is why Windows shows a
        // shorter list of named rights on a key than on a file. These are the Win32 constants.
        private const int PermKeyAll   = 0x000F003F;      // KEY_ALL_ACCESS
        private const int PermKeyRead  = 0x00020019;      // KEY_READ
        private const int PermKeyWrite = 0x00020006;      // KEY_WRITE

        /// <summary>One row of LockPermissions as the dialog works with it.</summary>
        private sealed class PermEntry
        {
            public string Domain = "";
            public string User = "";
            public int Permission;
            public DataRow? Row;      // the row this came from, null for an entry added in the dialog
        }

        /// <summary>The LockPermissions table, or null with a message when this package should not
        /// be given one.</summary>
        private TableState? EnsureLockPermissionsTable()
        {
            if (EnsureTableCached("MsiLockPermissionsEx") != null)
            {
                MstMessage(
                    "This package already secures objects through the MsiLockPermissionsEx table.\n\n"
                  + "A package must not carry both that table and LockPermissions - Windows Installer "
                  + "refuses to install one that does, with error 1941 - so SwiftPack will not add "
                  + "permissions here. Edit the MsiLockPermissionsEx rows in the Tables view instead.",
                    "Permissions", MessageBoxButton.OK, MessageBoxImage.Warning);
                return null;
            }
            return EnsureTableOrCreate("LockPermissions");
        }

        /// <summary>
        /// Lists a folder in the CreateFolder table, which is what a folder's permissions actually
        /// hang off. Returns false when the package has no component that installs there and none
        /// could be created.
        /// </summary>
        private bool EnsureCreateFolderRow(string dirKey)
        {
            var st = EnsureTableOrCreate("CreateFolder");
            if (st == null || !st.Data.Columns.Contains("Directory_")) return false;

            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Directory_"]), dirKey, StringComparison.OrdinalIgnoreCase)) return true;
            }

            string? comp = FindOrCreateComponent(dirKey);
            if (comp == null) return false;
            var nr = st.Data.NewRow();
            nr["Directory_"] = dirKey;
            if (st.Data.Columns.Contains("Component_")) nr["Component_"] = comp;
            st.Data.Rows.Add(nr);
            return true;
        }

        /// <summary>The entries currently securing one object, in table order.</summary>
        private List<PermEntry> ReadLockPermissions(string lockObject, string tableName)
        {
            var list = new List<PermEntry>();
            var st = EnsureTableCached("LockPermissions");
            if (st == null) return list;
            var d = st.Data;
            if (!d.Columns.Contains("LockObject") || !d.Columns.Contains("Table")) return list;

            foreach (DataRow r in d.Rows)
            {
                if (r.RowState == DataRowState.Deleted || st.MarkedDelete.Contains(r)) continue;
                if (!string.Equals(Cv(r["LockObject"]), lockObject, StringComparison.OrdinalIgnoreCase)) continue;
                if (!string.Equals(Cv(r["Table"]), tableName, StringComparison.OrdinalIgnoreCase)) continue;

                int.TryParse(d.Columns.Contains("Permission") ? Cv(r["Permission"]) : "", out int mask);
                list.Add(new PermEntry
                {
                    Domain     = d.Columns.Contains("Domain") ? Cv(r["Domain"]) : "",
                    User       = d.Columns.Contains("User")   ? Cv(r["User"])   : "",
                    Permission = mask,
                    Row        = r,
                });
            }
            return list;
        }

        /// <summary>
        /// Makes the table match the dialog's list for one object. Entries that were already there
        /// keep their row, so an untouched user does not turn into a delete and an add in the
        /// transform for no reason.
        /// </summary>
        private bool WriteLockPermissions(string lockObject, string tableName, List<PermEntry> entries)
        {
            var st = EnsureLockPermissionsTable();
            if (st == null) return false;
            var d = st.Data;

            var kept = new HashSet<DataRow>();
            foreach (var e in entries)
            {
                string user = e.User.Trim();
                if (user.Length == 0) continue;
                string domain = e.Domain.Trim();
                string perm = e.Permission.ToString(System.Globalization.CultureInfo.InvariantCulture);

                if (e.Row != null && e.Row.RowState != DataRowState.Deleted && e.Row.Table == d)
                {
                    if (d.Columns.Contains("Domain")     && Cv(e.Row["Domain"])     != domain) e.Row["Domain"]     = domain;
                    if (d.Columns.Contains("User")       && Cv(e.Row["User"])       != user)   e.Row["User"]       = user;
                    if (d.Columns.Contains("Permission") && Cv(e.Row["Permission"]) != perm)   e.Row["Permission"] = perm;
                    kept.Add(e.Row);
                    continue;
                }

                var nr = d.NewRow();
                nr["LockObject"] = lockObject;
                nr["Table"]      = tableName;
                if (d.Columns.Contains("Domain"))     nr["Domain"]     = domain;
                if (d.Columns.Contains("User"))       nr["User"]       = user;
                if (d.Columns.Contains("Permission")) nr["Permission"] = perm;
                d.Rows.Add(nr);
                kept.Add(nr);
            }

            // Anything this object had that the dialog no longer lists is gone.
            foreach (DataRow r in d.Rows.Cast<DataRow>().ToList())
            {
                if (r.RowState == DataRowState.Deleted || kept.Contains(r)) continue;
                if (!string.Equals(Cv(r["LockObject"]), lockObject, StringComparison.OrdinalIgnoreCase)) continue;
                if (!string.Equals(Cv(r["Table"]), tableName, StringComparison.OrdinalIgnoreCase)) continue;
                r.Delete();
            }

            UpdateEditCount();
            return true;
        }

        /// <summary>
        /// The permissions editor: a list of users on top, the rights for whichever one is selected
        /// underneath. Rights are the named sets Windows itself shows, and every box works the same
        /// way - ticking one adds its bits, unticking one removes them, and every other box then
        /// re-reads itself from the resulting mask. That is why unticking Read also clears Modify:
        /// Modify contains Read, so once those bits are gone Modify is no longer granted either.
        /// </summary>
        private void ShowPermissionsDialog(string lockObject, string tableName, string display)
        {
            if (_msiPath.Length == 0) return;
            if (EnsureLockPermissionsTable() == null) return;   // reported its own reason

            bool isRegistry = string.Equals(tableName, "Registry", StringComparison.OrdinalIgnoreCase);
            int fullMask    = isRegistry ? PermKeyAll : PermFull;
            int addedMask   = isRegistry ? PermKeyRead : PermReadExecute;

            (string Label, int Mask, string Tip)[] rights = isRegistry
                ? new[]
                {
                    ("Full control", PermKeyAll,
                     "Read and write values, create and delete subkeys, and change the key's own permissions."),
                    ("Read", PermKeyRead,
                     "Read values and list subkeys."),
                    ("Write", PermKeyWrite,
                     "Set values and create subkeys, without being able to change permissions."),
                }
                : new[]
                {
                    ("Full control", PermFull,
                     "Everything below, plus changing the object's own permissions and owner."),
                    ("Modify", PermModify,
                     "Read, write, execute and delete, but not change permissions."),
                    ("Read & execute", PermReadExecute, "Read the contents and run it."),
                    ("Read", PermRead, "Read the contents, attributes and permissions."),
                    ("Write", PermWrite, "Write contents and attributes."),
                };

            var entries = ReadLockPermissions(lockObject, tableName);
            if (entries.Count == 0)
            {
                // These rights replace the object's whole ACL, so a list without administrators
                // locks administrators out of it. Microsoft's guidance is to put them in every
                // list, so a new one starts with them rather than leaving the trap open.
                entries.Add(new PermEntry { User = "Administrators", Permission = fullMask });
            }

            var win = BuildNewDialog("Permissions");
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, "Permissions");
            win.Width = 560; win.MaxWidth = 560;

            int r = 0;
            void AddStacked(string text, FrameworkElement field, bool first = false)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, Margin = new Thickness(0, first ? 0 : 10, 0, 4)
                };
                Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0); Grid.SetColumnSpan(lbl, 2);
                cg.Children.Add(lbl); r++;

                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(field, r); Grid.SetColumn(field, 0); Grid.SetColumnSpan(field, 2);
                cg.Children.Add(field); r++;
            }

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var intro = new TextBlock
            {
                Text = isRegistry
                    ? $"Rights to apply to the {display} registry key when it is created."
                    : tableName == "File"
                        ? $"Rights to apply to {display} when it is installed."
                        : $"Rights to apply to the {display} folder when it is created.",
                FontSize = 12, TextWrapping = TextWrapping.Wrap, Foreground = valFg,
                Margin = new Thickness(0, 2, 0, 0)
            };
            Grid.SetRow(intro, r); Grid.SetColumn(intro, 0); Grid.SetColumnSpan(intro, 2);
            cg.Children.Add(intro); r++;

            // ── Name(s) ─────────────────────────────────────────────────────────────────
            PermEntry? current = null;
            var rowBorders = new List<(PermEntry entry, Border border)>();
            var namesPanel = new StackPanel();
            var namesHost  = new Border
            {
                Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true, Padding = new Thickness(2)
            };
            namesHost.Child = new ScrollViewer
            {
                Content = namesPanel, MaxHeight = 132,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
            };

            var selectedBrush = new SolidColorBrush(Color.FromArgb(0x55, 0x6C, 0x63, 0xFF));
            void Highlight()
            {
                foreach (var (entry, border) in rowBorders)
                    border.Background = ReferenceEquals(entry, current) ? selectedBrush : Brushes.Transparent;
            }

            // Declared ahead of the rows so a row click can push the selection into the boxes.
            Action<PermEntry?> showRights = _ => { };
            Action rebuildNames = () => { };

            rebuildNames = () =>
            {
                namesPanel.Children.Clear();
                rowBorders.Clear();
                foreach (var entry in entries)
                {
                    var e2 = entry;
                    var border = new Border { Padding = new Thickness(6, 3, 4, 3), CornerRadius = new CornerRadius(4) };
                    var dock = new DockPanel();

                    var del = new Button
                    {
                        Content = "\u2715", Width = 22, Height = 22, FontSize = 10, Cursor = Cursors.Hand,
                        Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                        Foreground = lblFg, ToolTip = "Remove this user"
                    };
                    del.Click += (_, _) =>
                    {
                        entries.Remove(e2);
                        if (ReferenceEquals(current, e2)) current = entries.Count > 0 ? entries[0] : null;
                        rebuildNames();
                        showRights(current);
                    };
                    DockPanel.SetDock(del, Dock.Right);
                    dock.Children.Add(del);

                    var domBox = new TextBox
                    {
                        Text = e2.Domain, Width = 150, FontSize = 12, Foreground = valFg,
                        Background = Brushes.Transparent, BorderBrush = boxBdr,
                        BorderThickness = new Thickness(0, 0, 1, 0), Padding = new Thickness(4, 2, 4, 2),
                        VerticalContentAlignment = VerticalAlignment.Center,
                        ToolTip = "Domain or machine name. Leave blank for Everyone, Administrators, "
                                + "and other well-known names, which Windows Installer resolves on its own."
                    };
                    domBox.TextChanged += (_, _) => e2.Domain = domBox.Text;
                    DockPanel.SetDock(domBox, Dock.Left);
                    dock.Children.Add(domBox);

                    var userBox = new TextBox
                    {
                        Text = e2.User, FontSize = 12, Foreground = valFg,
                        Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                        Padding = new Thickness(6, 2, 4, 2),
                        VerticalContentAlignment = VerticalAlignment.Center,
                        ToolTip = "User or group name, resolved on the target machine at install time."
                    };
                    userBox.TextChanged += (_, _) => e2.User = userBox.Text;
                    dock.Children.Add(userBox);

                    border.Child = dock;
                    border.MouseLeftButtonDown += (_, _) => { current = e2; Highlight(); showRights(e2); };
                    domBox.GotFocus  += (_, _) => { current = e2; Highlight(); showRights(e2); };
                    userBox.GotFocus += (_, _) => { current = e2; Highlight(); showRights(e2); };

                    rowBorders.Add((e2, border));
                    namesPanel.Children.Add(border);
                }
                Highlight();
            };

            AddStacked("Name(s)", namesHost, true);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var addBtn = new Button
            {
                Content = "\u2795 Add user", Style = sec, FontSize = 11, Height = 26,
                Padding = new Thickness(8, 0, 8, 0), HorizontalAlignment = HorizontalAlignment.Left,
                Margin = new Thickness(0, 6, 0, 0), Cursor = Cursors.Hand
            };
            addBtn.Click += (_, _) =>
            {
                var added = new PermEntry { User = "Everyone", Permission = addedMask };
                entries.Add(added);
                current = added;
                rebuildNames();
                showRights(added);
            };
            Grid.SetRow(addBtn, r); Grid.SetColumn(addBtn, 0); Grid.SetColumnSpan(addBtn, 2);
            cg.Children.Add(addBtn); r++;

            // ── Permissions ─────────────────────────────────────────────────────────────
            var rightsPanel = new StackPanel { Margin = new Thickness(2) };
            var named = new List<(CheckBox box, int mask)>();
            bool syncing = false;

            void Right(string text, int mask, string tip)
            {
                var cb = new CheckBox
                {
                    Content = text, FontSize = 12, Foreground = valFg,
                    Margin = new Thickness(0, 0, 0, 5), ToolTip = tip
                };
                rightsPanel.Children.Add(cb);
                named.Add((cb, mask));
            }

            foreach (var (label, mask, tip) in rights) Right(label, mask, tip);

            var maskText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                Margin = new Thickness(0, 4, 0, 0)
            };
            rightsPanel.Children.Add(maskText);

            showRights = e2 =>
            {
                syncing = true;
                bool on = e2 != null;
                foreach (var (box, mask) in named)
                {
                    box.IsEnabled  = on;
                    box.IsChecked  = on && (e2!.Permission & mask) == mask;
                }
                maskText.Text = on
                    ? $"Permission = {e2!.Permission} (0x{e2!.Permission:X8})"
                    : "Select a name to set its rights.";
                syncing = false;
            };

            void Toggle(int mask, bool add)
            {
                if (syncing || current == null) return;

                // Once a box is touched the boxes are the whole truth. Rights outside them - the
                // generic bits some authoring tools write - are dropped rather than left sitting
                // in a mask the dialog is no longer describing. Until a box is touched the entry
                // keeps whatever the package had, so opening the dialog and closing it changes
                // nothing.
                int m = (current.Permission & fullMask);
                if (add) m |= mask;
                else     m &= ~mask;
                current.Permission = m;
                showRights(current);
            }

            foreach (var (box, mask) in named)
            {
                var m = mask; var b = box;
                b.Checked   += (_, _) => Toggle(m, true);
                b.Unchecked += (_, _) => Toggle(m, false);
            }
            var rightsHost = new Border
            {
                Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true,
                Padding = new Thickness(10, 8, 10, 8), Child = rightsPanel
            };
            AddStacked("Permissions", rightsHost);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var warn = new TextBlock
            {
                Text = "These rights replace the object's existing permissions rather than adding to "
                     + "them, and inherited entries are dropped. Keep an administrators entry in the "
                     + "list so the object stays maintainable.",
                FontSize = 11, TextWrapping = TextWrapping.Wrap, Foreground = lblFg,
                Margin = new Thickness(0, 8, 0, 0)
            };
            Grid.SetRow(warn, r); Grid.SetColumn(warn, 0); Grid.SetColumnSpan(warn, 2);
            cg.Children.Add(warn); r++;

            rebuildNames();
            current = entries.Count > 0 ? entries[0] : null;
            Highlight();
            showRights(current);

            NdAddSpacer(cg, r++);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);

            bool ok = false;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () => { ok = true; win.Close(); }),
                ("\u2715 Cancel", () => win.Close()));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);

            win.ShowDialog();
            if (!ok) return;

            // A named user with no rights secures nothing, and a row with no name cannot be
            // written at all, so both are dropped rather than staged as unusable rows.
            var final = entries.Where(x => x.User.Trim().Length > 0 && x.Permission != 0).ToList();

            // A folder is secured through CreateFolder, so it has to be listed there first.
            if (final.Count > 0 && tableName == "CreateFolder" && !EnsureCreateFolderRow(lockObject))
            {
                MstMessage(
                    "This folder could not be added to the CreateFolder table, which is what a "
                  + "folder's permissions hang off, because no component installs into it and none "
                  + "could be created.\n\nAdd a file to the folder first, then set its permissions.",
                    "Permissions", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            if (!WriteLockPermissions(lockObject, tableName, final)) return;

            if (TxtStatus != null)
                TxtStatus.Text = final.Count == 0
                    ? $"Permissions cleared on {display}."
                    : $"Permissions set on {display} for {final.Count} name(s).";
        }

        /// <summary>
        /// The Registry-table row that stands for a key, which is what LockPermissions actually
        /// points at: securing a key is done through a row that writes into it. Prefers the row
        /// that creates the key, falls back to any value row under it, and writes a key-creating
        /// row when the key has none. Returns "" when no component could carry it.
        /// </summary>
        private string EnsureRegistryLockObject(RegNode node)
        {
            var regSt = EnsureTableOrCreate("Registry");
            if (regSt == null || !regSt.Data.Columns.Contains("Registry")) return "";

            DataRow? best = null;
            foreach (var r in node.Values)
            {
                if (r.RowState == DataRowState.Deleted || r.RowState == DataRowState.Detached) continue;
                string name = r.Table.Columns.Contains("Name") ? Cv(r["Name"]) : "";
                // "+" is the row that creates the key, which is the natural thing to secure.
                if (name == "+" || name.Length == 0) { best = r; break; }
                best ??= r;
            }
            if (best != null) return Cv(best["Registry"]);

            string? comp = RegComponentFor(node);
            if (comp == null) return "";

            var nr = regSt.Data.NewRow();
            nr["Registry"] = UniqueKey(regSt.Data, "Registry",
                SanitizeKey("reg_" + (node.Display.Length > 0 ? node.Display : "key")));
            if (regSt.Data.Columns.Contains("Root"))       nr["Root"]       = node.Root.ToString();
            if (regSt.Data.Columns.Contains("Key"))        nr["Key"]        = node.FullPath;
            if (regSt.Data.Columns.Contains("Name"))       nr["Name"]       = "+";
            if (regSt.Data.Columns.Contains("Component_")) nr["Component_"] = comp;
            regSt.Data.Rows.Add(nr);
            node.Values.Add(nr);
            UpdateEditCount();
            return Cv(nr["Registry"]);
        }

        private void RegKeyPermissions_Click(object sender, RoutedEventArgs e)
        {
            var node = SelectedReg();
            if (node == null || node.IsHive)
            {
                MstMessage("Select a key rather than a hive. A hive is not created by the package, "
                         + "so there is nothing for it to secure.",
                    "Permissions", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            string lockObject = EnsureRegistryLockObject(node);
            if (lockObject.Length == 0)
            {
                MstMessage("This key could not be given a Registry-table row to secure, because no "
                         + "component is available to attach it to.",
                    "Permissions", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            ShowPermissionsDialog(lockObject, "Registry", node.Display);
        }

        private void DirFolderPermissions_Click(object sender, RoutedEventArgs e)
        {
            var n = SelectedDir();
            if (n?.DirRow == null)
            {
                MstMessage("Permissions can only be set on a folder the package defines.",
                    "Permissions", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            ShowPermissionsDialog(n.Key, "CreateFolder", n.Display);
        }

        private void FilePermissions_Click(object sender, RoutedEventArgs e)
        {
            if (DirFileList?.SelectedItem is not FileRow fr || fr.Key.Length == 0)
            {
                MstMessage("Select a file first.", "Permissions",
                    MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            ShowPermissionsDialog(fr.Key, "File", fr.LongName);
        }

        // Component of a file already present in this folder (not deleted, not just
        // added), or null. Such a component installs to this folder and is in a feature.
        private static string? ExistingFileComponent(DirNode n)
        {
            foreach (var dr in n.Files)
            {
                if (dr.RowState == DataRowState.Deleted || dr.RowState == DataRowState.Added) continue;
                if (dr.Table.Columns.Contains("Component_") && dr["Component_"] != DBNull.Value)
                {
                    string c = dr["Component_"].ToString() ?? "";
                    if (c.Length > 0) return c;
                }
            }
            return null;
        }

        // A component that already installs into the directory, or null when none does.
        private string? ComponentInDirectory(string dirKey)
        {
            var d = EnsureTableCached("Component")?.Data;
            if (d == null || !d.Columns.Contains("Component") || !d.Columns.Contains("Directory_")) return null;
            foreach (DataRow r in d.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (!string.Equals(Cv(r["Directory_"]), dirKey, StringComparison.OrdinalIgnoreCase)) continue;
                string c = Cv(r["Component"]);
                if (c.Length > 0) return c;
            }
            return null;
        }

        // A component installing into the directory, else a freshly created one
        // (with a Feature link so it actually installs).
        private string? FindOrCreateComponent(string dirKey)
        {
            var compSt = EnsureTableCached("Component");
            if (compSt == null) return null;
            var d = compSt.Data;
            if (ComponentInDirectory(dirKey) is { } found) return found;

            string comp = UniqueKey(d, "Component", SanitizeKey("comp_" + dirKey));
            var nc = d.NewRow();
            if (d.Columns.Contains("Component"))   nc["Component"]   = comp;
            if (d.Columns.Contains("ComponentId")) nc["ComponentId"] = "{" + Guid.NewGuid().ToString().ToUpperInvariant() + "}";
            if (d.Columns.Contains("Directory_"))  nc["Directory_"]  = dirKey;
            if (d.Columns.Contains("Attributes"))  nc["Attributes"]  = "0";
            d.Rows.Add(nc);

            var featSt     = EnsureTableCached("Feature");
            var featCompSt = EnsureTableCached("FeatureComponents");
            string? feat = null;
            if (featSt != null && featSt.Data.Columns.Contains("Feature"))
                foreach (DataRow fr in featSt.Data.Rows)
                    if (fr.RowState != DataRowState.Deleted) { feat = fr["Feature"]?.ToString(); break; }
            if (feat != null && featCompSt != null
                && featCompSt.Data.Columns.Contains("Feature_") && featCompSt.Data.Columns.Contains("Component_"))
            {
                var fc = featCompSt.Data.NewRow();
                fc["Feature_"]   = feat;
                fc["Component_"] = comp;
                featCompSt.Data.Rows.Add(fc);
            }
            return comp;
        }

        /// <summary>
        /// Creates one Component named after a file, installing into <paramref name="dirKey"/>, and
        /// joins it to a feature so it is actually installed. Returns the key, or null when the
        /// package carries no Component table.
        ///
        /// The name is the file name itself (periods are legal in an MSI identifier), which is how
        /// this package's own components are already named. A name in use gets "_comp" appended, as
        /// asked; a further clash falls through to UniqueKey's numeric suffix, because Component is
        /// the table's primary key and a duplicate could not be written at all.
        /// </summary>
        private string? CreateComponentForFile(string fileName, string dirKey)
        {
            var compSt = EnsureTableCached("Component");
            if (compSt == null || !compSt.Data.Columns.Contains("Component")) return null;
            var d = compSt.Data;

            bool Taken(string key)
            {
                foreach (DataRow r in d.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (string.Equals(Cv(r["Component"]), key, StringComparison.OrdinalIgnoreCase)) return true;
                }
                return false;
            }

            string wanted = FileKeyFromName(fileName);
            if (Taken(wanted)) wanted += "_comp";
            string comp = UniqueKey(d, "Component", wanted);

            var nc = d.NewRow();
            nc["Component"] = comp;
            if (d.Columns.Contains("ComponentId")) nc["ComponentId"] = "{" + Guid.NewGuid().ToString().ToUpperInvariant() + "}";
            if (d.Columns.Contains("Directory_"))  nc["Directory_"]  = dirKey;
            if (d.Columns.Contains("Attributes"))  nc["Attributes"]  = "0";
            d.Rows.Add(nc);

            // A component in no feature is never installed, so the files would be staged into a
            // package that quietly drops them. Prefer the feature the folder's existing files
            // already belong to; fall back to the first feature in the table.
            var featSt     = EnsureTableCached("Feature");
            var featCompSt = EnsureTableCached("FeatureComponents");
            string? feat = FeatureForDirectory(dirKey);
            if (feat == null && featSt != null && featSt.Data.Columns.Contains("Feature"))
                foreach (DataRow fr in featSt.Data.Rows)
                    if (fr.RowState != DataRowState.Deleted) { feat = Cv(fr["Feature"]); break; }
            if (feat != null && feat.Length > 0 && featCompSt != null
                && featCompSt.Data.Columns.Contains("Feature_") && featCompSt.Data.Columns.Contains("Component_"))
            {
                var fc = featCompSt.Data.NewRow();
                fc["Feature_"]   = feat;
                fc["Component_"] = comp;
                featCompSt.Data.Rows.Add(fc);
            }
            return comp;
        }

        /// <summary>The feature a component already installing into this folder belongs to, so a
        /// new component lands in the same one rather than in whichever feature happens to be
        /// first in the table.</summary>
        private string? FeatureForDirectory(string dirKey)
        {
            var compSt     = EnsureTableCached("Component");
            var featCompSt = EnsureTableCached("FeatureComponents");
            if (compSt == null || featCompSt == null) return null;
            if (!compSt.Data.Columns.Contains("Component") || !compSt.Data.Columns.Contains("Directory_")) return null;
            if (!featCompSt.Data.Columns.Contains("Feature_") || !featCompSt.Data.Columns.Contains("Component_")) return null;

            foreach (DataRow cr in compSt.Data.Rows)
            {
                if (cr.RowState == DataRowState.Deleted) continue;
                if (!string.Equals(Cv(cr["Directory_"]), dirKey, StringComparison.OrdinalIgnoreCase)) continue;
                string ck = Cv(cr["Component"]);
                if (ck.Length == 0) continue;
                foreach (DataRow fr in featCompSt.Data.Rows)
                {
                    if (fr.RowState == DataRowState.Deleted) continue;
                    if (string.Equals(Cv(fr["Component_"]), ck, StringComparison.OrdinalIgnoreCase))
                    {
                        string f = Cv(fr["Feature_"]);
                        if (f.Length > 0) return f;
                    }
                }
            }
            return null;
        }

        private static int NextSequence(DataTable t)
        {
            int max = 0;
            if (t.Columns.Contains("Sequence"))
                foreach (DataRow r in t.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (r["Sequence"] != DBNull.Value && int.TryParse(r["Sequence"].ToString(), out int s) && s > max) max = s;
                }
            return max;
        }

        private static string MakeDefaultDir(string newName, string old)
        {
            int colon = old.IndexOf(':');
            string target = colon >= 0 ? old.Substring(0, colon) : old;
            string rest   = colon >= 0 ? old.Substring(colon) : "";
            int bar = target.IndexOf('|');
            string shortPart = bar >= 0 ? target.Substring(0, bar) : "";
            string t = shortPart.Length > 0 ? shortPart + "|" + newName : newName;
            return t + rest;
        }

        private static string SanitizeKey(string s)
        {
            var sb = new System.Text.StringBuilder();
            foreach (char c in s) sb.Append(char.IsLetterOrDigit(c) ? c : '_');
            string k = sb.ToString().Trim('_');
            if (k.Length == 0) k = "Dir";
            if (!char.IsLetter(k[0]) && k[0] != '_') k = "_" + k;
            return k;
        }

        // A File-table key from a file name. Periods are kept (valid in MSI identifiers),
        // so the key carries the extension like the package's own keys (e.g. "filecompare.exe").
        private static string FileKeyFromName(string name)
        {
            var sb = new System.Text.StringBuilder();
            foreach (char c in name)
                sb.Append(char.IsLetterOrDigit(c) || c == '.' || c == '_' ? c : '_');
            string k = sb.ToString().Trim('_');
            if (k.Length == 0) k = "File";
            if (!char.IsLetter(k[0]) && k[0] != '_') k = "_" + k;
            return k;
        }

        // ══ Registry category (regedit-style key tree + values grid) ════════
        private System.Collections.ObjectModel.ObservableCollection<RegNode>? _regRoots;
        private string _regTreeBuiltFor = "\0";
        private System.Collections.ObjectModel.ObservableCollection<RegValueRow>? _regValueRows;

        // MSI Root code -> hive. -1 is HKLM or HKCU depending on the ALLUSERS property.
        private static string RootHiveName(int root) => root switch
        {
            0  => "HKEY_CLASSES_ROOT",
            1  => "HKEY_CURRENT_USER",
            2  => "HKEY_LOCAL_MACHINE",
            3  => "HKEY_USERS",
            -1 => "HKLM/HKCU",
            _  => "HKEY_LOCAL_MACHINE"
        };

        private static int ParseRoot(string s) => int.TryParse(s, out int v) ? v : 2;

        /// <summary>
        /// The hive-and-key tree for a set of Registry rows. Passing a component name narrows it to
        /// that component's rows, which is what the Features view needs: the same shape as the
        /// Registry category, scoped to one component. Every standard hive is seeded either way, so
        /// a key can be added under any of them.
        /// </summary>
        private System.Collections.ObjectModel.ObservableCollection<RegNode> BuildRegRoots(
            TableState regSt, string? componentFilter, out int total)
        {
            var hives  = new Dictionary<int, RegNode>();
            var byPath = new Dictionary<string, RegNode>(StringComparer.OrdinalIgnoreCase);
            var roots  = new System.Collections.ObjectModel.ObservableCollection<RegNode>();
            total = 0;

            RegNode HiveNode(int root)
            {
                if (!hives.TryGetValue(root, out var h))
                {
                    h = new RegNode { Root = root, FullPath = "", IsHive = true, Display = RootHiveName(root) };
                    hives[root] = h; byPath[root + "|"] = h; roots.Add(h);
                }
                return h;
            }

            RegNode KeyNode(int root, string path)
            {
                path = path.Trim('\\');
                if (path.Length == 0) return HiveNode(root);
                string id = root + "|" + path;
                if (byPath.TryGetValue(id, out var existing)) return existing;

                int slash = path.LastIndexOf('\\');
                string parentPath = slash >= 0 ? path.Substring(0, slash) : "";
                string seg        = slash >= 0 ? path.Substring(slash + 1) : path;
                RegNode parent = parentPath.Length == 0 ? HiveNode(root) : KeyNode(root, parentPath);
                var node = new RegNode { Root = root, FullPath = path, Display = seg, Parent = parent };
                parent.Children.Add(node); byPath[id] = node;
                return node;
            }

            // HKMU (-1) is deliberately not seeded: it only means anything once the package uses
            // it, and the lazy path above adds it then.
            foreach (int root in new[] { 0, 1, 2, 3 }) HiveNode(root);

            foreach (DataRow r in regSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (componentFilter != null && regSt.Data.Columns.Contains("Component_") &&
                    !string.Equals(Cv(r["Component_"]), componentFilter, StringComparison.OrdinalIgnoreCase))
                    continue;
                var node = KeyNode(ParseRoot(Cv(r["Root"])), Cv(r["Key"]));
                node.Values.Add(r);
                total++;
            }

            SortRegNodes(roots);
            return roots;
        }

        private void ShowRegistryForm(TableState regSt)
        {
            // Built for this MSI already: keep the tree, its expand state and selection.
            if (_regRoots != null && _regTreeBuiltFor == _msiPath)
            {
                if (RegTree != null && RegTree.ItemsSource == null) RegTree.ItemsSource = _regRoots;
                if (FormRegistryPanel != null) FormRegistryPanel.Visibility = Visibility.Visible;
                return;
            }

            var roots = BuildRegRoots(regSt, null, out int total);

            foreach (var h in roots) h.IsExpanded = false;   // start collapsed; expand on demand
            _regRoots = roots;
            _regTreeBuiltFor = _msiPath;

            RegTree.ItemsSource = roots;
            if (RegCount != null) RegCount.Text = total == 1 ? "1 entry" : $"{total} entries";
            _regValueRows = null;
            if (RegValueList != null) RegValueList.ItemsSource = null;
            if (RegValuesTitle != null) RegValuesTitle.Text = "Select a key";
            if (FormRegistryPanel != null) FormRegistryPanel.Visibility = Visibility.Visible;
        }

        // Hives first, then keys alphabetically (like regedit).
        private static void SortRegNodes(System.Collections.ObjectModel.ObservableCollection<RegNode> list)
        {
            var ordered = list.OrderBy(n => n.IsHive ? 0 : 1)
                              .ThenBy(n => n.Display, StringComparer.OrdinalIgnoreCase).ToList();
            list.Clear();
            foreach (var n in ordered) { SortRegNodes(n.Children); list.Add(n); }
        }

        /// <summary>
        /// The registry tree the actions apply to. The Features view has its own component-scoped
        /// tree over the same rows, so every handler below works on whichever one is on screen.
        /// IsVisible rather than Visibility, so a tree inside a collapsed panel does not win.
        /// </summary>
        private System.Windows.Controls.TreeView? ActiveRegTree()
            => FeatRegTree is { IsVisible: true } ? FeatRegTree : RegTree;

        private RegNode? SelectedReg() => ActiveRegTree()?.SelectedItem as RegNode;

        /// <summary>
        /// Brings the pane back in step after a registry edit. The two trees are separate RegNode
        /// sets built over the same table, so a change made through one leaves the other stale:
        /// the category tree is thrown away and rebuilt from the table next time it opens.
        /// </summary>
        private void RegRefreshAfterEdit(RegNode? node)
        {
            UpdateEditCount();
            if (FeatRegTree is not { IsVisible: true }) return;

            _regRoots = null; _regTreeBuiltFor = "\0";
            if (_detailComp.Length == 0) return;
            int total = 0;
            if (_featRegRoots != null) foreach (var h in _featRegRoots) total += CountRegRows(h);
            FillComponentRegistry(_detailComp, node, total);
        }

        private void RegTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is not RegNode node)
            {
                _regValueRows = null;
                if (RegValueList != null) RegValueList.ItemsSource = null;
                if (RegValuesTitle != null) RegValuesTitle.Text = "Select a key";
                ClearRegValueEditor();
                return;
            }
            RefreshRegValues(node);
        }

        private void RefreshRegValues(RegNode node)
        {
            // A Registry row whose Name is "+", "-" or "*" is the key-operation marker for the key
            // itself (create / remove / create+remove), not a value under it. The tree node already
            // represents it, so it is kept out of the values grid: a key that was just created reads
            // as empty, the way regedit shows it, instead of listing a "(key)" row with nothing to
            // edit and a count of 1 value.
            var rows = new System.Collections.ObjectModel.ObservableCollection<RegValueRow>();
            foreach (var r in node.Values)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                var vr = new RegValueRow(r);
                if (vr.IsKeyOp) continue;
                rows.Add(vr);
            }
            MarkKeyPathReg(rows);
            _regValueRows = rows;
            if (RegValueList != null) RegValueList.ItemsSource = rows;
            if (RegValuesTitle != null)
            {
                string where = node.IsHive ? node.Display : $"{RootHiveName(node.Root)}\\{node.FullPath}";
                RegValuesTitle.Text = $"{where}  ·  {rows.Count} value(s)";
            }
            ClearRegValueEditor();
            if (RegValueList != null && RegValueList.Items.Count > 0 && RegValueList.SelectedItem == null)
                RegValueList.SelectedIndex = 0;
        }

        // Right-click selects the node/row under the cursor so the menu acts on it.
        private void RegTree_RightDown(object sender, MouseButtonEventArgs e)
        {
            DependencyObject? d = e.OriginalSource as DependencyObject;
            while (d != null && d is not TreeViewItem) d = VisualTreeHelper.GetParent(d);
            if (d is TreeViewItem tvi) { tvi.IsSelected = true; tvi.Focus(); }
        }

        private void RegValueList_RightDown(object sender, MouseButtonEventArgs e)
        {
            DependencyObject? d = e.OriginalSource as DependencyObject;
            while (d != null && d is not DataGridRow) d = VisualTreeHelper.GetParent(d);
            if (d is DataGridRow row)
            {
                row.IsSelected = true;
                if (RegValueList != null) RegValueList.SelectedItem = row.Item;
            }
        }

        private static void SetRegExpanded(RegNode n, bool ex)
        {
            n.IsExpanded = ex;
            foreach (var ch in n.Children) SetRegExpanded(ch, ex);
        }

        private void RegExpand_Click(object sender, RoutedEventArgs e)
        { if (SelectedReg() is { } n) SetRegExpanded(n, true); }

        private void RegCollapse_Click(object sender, RoutedEventArgs e)
        {
            if (SelectedReg() is not { } n) return;
            foreach (var ch in n.Children) SetRegExpanded(ch, false);
            n.IsExpanded = false;
        }

        // A component to attach new registry entries to: one already used in this key,
        // else any registry component, else the first component in the package.
        private string? RegComponentFor(RegNode node)
        {
            foreach (var r in node.Values)
                if (r.RowState != DataRowState.Deleted)
                { string c = Cv(r["Component_"]); if (c.Length > 0) return c; }
            var regSt = EnsureTableCached("Registry");
            if (regSt != null)
                foreach (DataRow r in regSt.Data.Rows)
                    if (r.RowState != DataRowState.Deleted)
                    { string c = Cv(r["Component_"]); if (c.Length > 0) return c; }
            var compSt = EnsureTableCached("Component");
            if (compSt != null)
                foreach (DataRow r in compSt.Data.Rows)
                    if (r.RowState != DataRowState.Deleted)
                    { string c = Cv(r["Component"]); if (c.Length > 0) return c; }
            return null;
        }

        private void RegAddValue_Click(object sender, RoutedEventArgs e)
        {
            var node = SelectedReg();
            if (node == null) return;
            if (node.IsHive)
            { MstMessage("Select a key under the hive to add a value.", "New Value", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            var regSt = EnsureTableCached("Registry");
            if (regSt == null)
            { MstMessage("This MSI has no Registry table.", "New Value", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            string? comp = RegComponentFor(node);
            if (comp == null)
            { MstMessage("No component is available to attach the value to.", "New Value", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            var res = PromptRegValue("New Value", "", "REG_SZ", "");
            if (res == null) return;
            var (name, type, data) = res.Value;

            var nr = regSt.Data.NewRow();
            string baseKey = SanitizeKey("reg_" + (name.Length > 0 ? name : node.Display));
            nr["Registry"] = UniqueKey(regSt.Data, "Registry", baseKey);
            if (regSt.Data.Columns.Contains("Root"))       nr["Root"]       = node.Root.ToString();
            if (regSt.Data.Columns.Contains("Key"))        nr["Key"]        = node.FullPath;
            if (regSt.Data.Columns.Contains("Name"))       nr["Name"]       = name;
            if (regSt.Data.Columns.Contains("Value"))      nr["Value"]      = EncodeRegValue(type, data);
            if (regSt.Data.Columns.Contains("Component_")) nr["Component_"] = comp;
            regSt.Data.Rows.Add(nr);
            node.Values.Add(nr);

            RegRefreshAfterEdit(node);
            if (ReferenceEquals(RegTree?.SelectedItem, node)) { RefreshRegValues(node); SelectRegValueRow(nr); }
        }

        private void RegValueList_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (RegValueList?.SelectedItem is RegValueRow vr) ShowRegValueEditor(vr);
            else ClearRegValueEditor();
        }

        private RegValueRow? _regEditRow;
        private bool _regEditorLoading;

        private void ClearRegValueEditor()
        {
            _regEditRow = null;
            if (RegValueEditorHost != null) RegValueEditorHost.Content = null;
        }

        // Inline editor for a single registry value, shown below the value grid.
        // Compact layout: label beside field. Name and Data commit on focus loss and
        // keep the value's existing type. RefreshRegValues keeps key-operation rows
        // (+, -, *) out of the grid, so the note below is only a defensive guard.
        private void ShowRegValueEditor(RegValueRow vr)
        {
            if (RegValueEditorHost == null) return;
            _regEditorLoading = true;
            _regEditRow = vr;
            var row = vr.Row;

            // Application.Current.TryFindResource searches Application.Resources only, and that
            // dictionary holds the light palette; the dark one is merged further down the element
            // tree, which is where the surrounding XAML's {DynamicResource} lookups resolve from.
            // Asking the page instead walks the same chain as the XAML, so the editor gets the
            // palette that is actually on screen rather than a light box on a dark page.
            Brush boxBg  = (TryFindResource("InputBgBrush")      as Brush) ?? Brushes.White;
            Brush boxBdr = (TryFindResource("BorderMainBrush")   as Brush) ?? Brushes.Gray;
            Brush lblFg  = (TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            // A brush read once is a snapshot: toggling the theme while the editor is open would
            // leave it on the old palette until the row is reselected. SetResourceReference is the
            // code-behind form of {DynamicResource}, so these elements re-resolve on the switch.
            static void ThemeLabel(TextBlock t) =>
                t.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
            static void ThemeField(Border field, TextBox box)
            {
                field.SetResourceReference(Border.BackgroundProperty,  "InputBgBrush");
                field.SetResourceReference(Border.BorderBrushProperty, "BorderMainBrush");
                box.SetResourceReference(TextBox.ForegroundProperty,   "TextPrimaryBrush");
                box.SetResourceReference(TextBox.CaretBrushProperty,   "TextPrimaryBrush");
            }

            if (vr.IsKeyOp)
            {
                var note = new TextBlock
                {
                    Text = "This row is a key operation (+, -, or *) and has no editable value.",
                    FontSize = 12, TextWrapping = TextWrapping.Wrap, Foreground = lblFg,
                    Margin = new Thickness(12, 12, 12, 12)
                };
                ThemeLabel(note);
                RegValueEditorHost.Content = note;
                _regEditorLoading = false;
                return;
            }

            // Keep the value's existing type; only the name and data are editable.
            var (curType, curData) = DecodeRegValue(Cv(row["Value"]));

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(46) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            TextBlock Lbl(string t)
            {
                var tb = new TextBlock
                {
                    Text = t, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
                };
                ThemeLabel(tb);
                return tb;
            }

            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var nameLbl = Lbl("Name");
            var (nameField, nameBox) = MakeRoundedField(Cv(row["Name"]), boxBg, boxBdr, valFg, false, null);
            ThemeField(nameField, nameBox);
            nameField.Margin = new Thickness(0, 4, 0, 4);
            Grid.SetRow(nameLbl, 0); Grid.SetColumn(nameLbl, 0);
            Grid.SetRow(nameField, 0); Grid.SetColumn(nameField, 1);
            grid.Children.Add(nameLbl); grid.Children.Add(nameField);

            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dataLbl = Lbl("Data");
            var (dataField, dataBox) = MakeRoundedField(curData, boxBg, boxBdr, valFg, true, null);
            ThemeField(dataField, dataBox);
            dataField.Margin = new Thickness(0, 4, 0, 4);
            Grid.SetRow(dataLbl, 1); Grid.SetColumn(dataLbl, 0);
            Grid.SetRow(dataField, 1); Grid.SetColumn(dataField, 1);
            grid.Children.Add(dataLbl); grid.Children.Add(dataField);

            void Commit()
            {
                if (_regEditorLoading || _regEditRow == null) return;
                var rw = _regEditRow.Row;
                try
                {
                    if (rw.Table.Columns.Contains("Name"))  rw["Name"]  = nameBox.Text;
                    if (rw.Table.Columns.Contains("Value")) rw["Value"] = EncodeRegValue(curType, dataBox.Text);
                }
                catch { }
                UpdateEditCount();
                _regEditRow.Refresh();   // update the grid row in place
            }

            nameBox.LostFocus += (_, _) => Commit();
            dataBox.LostFocus += (_, _) => Commit();

            RegValueEditorHost.Content = grid;
            _regEditorLoading = false;
        }

        private void RegDeleteValue_Click(object sender, RoutedEventArgs e)
        {
            if (RegValueList?.SelectedItem is not RegValueRow vr) return;
            var node = SelectedReg();
            if (vr.Row.RowState != DataRowState.Deleted) vr.Row.Delete();
            node?.Values.Remove(vr.Row);
            UpdateEditCount();
            if (node != null) RefreshRegValues(node);
        }

        // Make the selected registry entry the KeyPath of its component. KeyPath then
        // holds the Registry-table key, so the registry-keypath attribute bit is set
        // (4) to tell the installer the key path is a registry key, not a file.
        private void RegSetKeyPath_Click(object sender, RoutedEventArgs e)
        {
            if (RegValueList?.SelectedItem is not RegValueRow vr) return;
            string comp   = vr.Component;
            string regKey = vr.Row.Table.Columns.Contains("Registry") ? Cv(vr.Row["Registry"]) : "";
            if (comp.Length == 0 || regKey.Length == 0)
            { MstMessage("This entry has no component to set a key path on.", "Set Key Path", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var compSt = EnsureTableCached("Component");
            if (compSt == null || !compSt.Data.Columns.Contains("KeyPath"))
            { MstMessage("The Component table has no KeyPath column.", "Set Key Path", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            DataRow? cr = null;
            foreach (DataRow r in compSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Component"]), comp, StringComparison.OrdinalIgnoreCase)) { cr = r; break; }
            }
            if (cr == null)
            { MstMessage($"Component \u201C{comp}\u201D was not found.", "Set Key Path", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            if (Cv(cr["KeyPath"]) == regKey)
            { TxtStatus.Text = $"Registry entry {regKey} is already the key path for {comp}."; return; }

            if (!ConfirmReplaceKeyPath(cr, "Set Key Path")) return;

            cr["KeyPath"] = regKey;
            if (compSt.Data.Columns.Contains("Attributes"))
            {
                int attr = int.TryParse(Cv(cr["Attributes"]), out int a) ? a : 0;
                attr |= 4;   // msidbComponentAttributesRegistryKeyPath
                cr["Attributes"] = attr.ToString();
            }
            UpdateEditCount();
            if (_regValueRows != null) MarkKeyPathReg(_regValueRows);
            TxtStatus.Text = $"Key path for {comp} set to registry entry {regKey}.";
        }

        private void RegAddKey_Click(object sender, RoutedEventArgs e)
        {
            var node = SelectedReg();
            if (node == null) return;
            var regSt = EnsureTableCached("Registry");
            if (regSt == null)
            { MstMessage("This MSI has no Registry table.", "New Key", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            string? name = PromptText("New Key", "Name", "NewKey");
            if (string.IsNullOrWhiteSpace(name)) return;
            name = name.Trim().Trim('\\');
            if (name.Length == 0) return;
            string? comp = RegComponentFor(node);
            if (comp == null)
            { MstMessage("No component is available to attach the key to.", "New Key", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            string newPath = node.IsHive ? name : node.FullPath + "\\" + name;
            // Name "+" marks the key for creation on install (an empty key).
            var nr = regSt.Data.NewRow();
            nr["Registry"] = UniqueKey(regSt.Data, "Registry", SanitizeKey("reg_" + name));
            if (regSt.Data.Columns.Contains("Root"))       nr["Root"]       = node.Root.ToString();
            if (regSt.Data.Columns.Contains("Key"))        nr["Key"]        = newPath;
            if (regSt.Data.Columns.Contains("Name"))       nr["Name"]       = "+";
            if (regSt.Data.Columns.Contains("Component_")) nr["Component_"] = comp;
            regSt.Data.Rows.Add(nr);

            var child = new RegNode { Root = node.Root, FullPath = newPath, Display = name, Parent = node };
            child.Values.Add(nr);
            int idx = 0;
            while (idx < node.Children.Count &&
                   string.Compare(node.Children[idx].Display, name, StringComparison.OrdinalIgnoreCase) < 0) idx++;
            node.Children.Insert(idx, child);
            node.IsExpanded = true;
            RegRefreshAfterEdit(child);
        }

        private void RegRenameKey_Click(object sender, RoutedEventArgs e)
        {
            var node = SelectedReg();
            if (node == null || node.IsHive)
            { MstMessage("Select a key (not a hive) to rename.", "Rename Key", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            var regSt = EnsureTableCached("Registry");
            if (regSt == null) return;
            string? name = PromptText("Rename Key", "Name", node.Display);
            if (string.IsNullOrWhiteSpace(name)) return;
            name = name.Trim().Trim('\\');
            if (name.Length == 0 || string.Equals(name, node.Display, StringComparison.Ordinal)) return;

            int slash = node.FullPath.LastIndexOf('\\');
            string parentPath = slash >= 0 ? node.FullPath.Substring(0, slash) : "";
            string newPath = parentPath.Length > 0 ? parentPath + "\\" + name : name;
            string oldPrefix = node.FullPath;

            foreach (DataRow r in regSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (ParseRoot(Cv(r["Root"])) != node.Root) continue;
                string k = Cv(r["Key"]);
                if (string.Equals(k, oldPrefix, StringComparison.OrdinalIgnoreCase))
                    r["Key"] = newPath;
                else if (k.StartsWith(oldPrefix + "\\", StringComparison.OrdinalIgnoreCase))
                    r["Key"] = newPath + k.Substring(oldPrefix.Length);
            }
            RebaseRegPaths(node, newPath);
            node.Display = name;
            RegRefreshAfterEdit(node);
            RefreshRegValues(node);
        }

        // Re-point a node and its descendants at a new base path after a rename.
        private static void RebaseRegPaths(RegNode node, string newPath)
        {
            node.FullPath = newPath;
            foreach (var ch in node.Children) RebaseRegPaths(ch, newPath + "\\" + ch.Display);
        }

        private void RegDeleteKey_Click(object sender, RoutedEventArgs e)
        {
            var node = SelectedReg();
            if (node == null || node.IsHive)
            { MstMessage("Select a key (not a hive) to delete.", "Delete Key", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            if (MstMessage($"Delete key \u201C{node.Display}\u201D and all of its values and subkeys?",
                    "Delete Key", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;

            DeleteRegSubtree(node);
            if (node.Parent != null) node.Parent.Children.Remove(node);
            else { _regRoots?.Remove(node); _featRegRoots?.Remove(node); }
            _regValueRows = null;
            if (RegValueList != null) RegValueList.ItemsSource = null;
            if (RegValuesTitle != null) RegValuesTitle.Text = "Select a key";
            RegRefreshAfterEdit(null);
        }

        private static void DeleteRegSubtree(RegNode n)
        {
            foreach (var r in n.Values)
                if (r.RowState != DataRowState.Deleted) r.Delete();
            foreach (var ch in n.Children) DeleteRegSubtree(ch);
        }

        // Hive roots are virtual containers, so renaming or deleting them is not
        // allowed; sub keys keep both actions. New Value / New Key are unaffected.
        private void RegMenu_Opened(object sender, RoutedEventArgs e)
        {
            bool isHive = SelectedReg()?.IsHive == true;
            if (MiRegRename != null) MiRegRename.IsEnabled = !isHive;
            if (MiRegDelete != null) MiRegDelete.IsEnabled = !isHive;
            // A hive is not created by the package, so there is nothing under it to secure.
            if (MiRegPermissions != null) MiRegPermissions.IsEnabled = !isHive;
        }

        // ── Import / export .reg files ──────────────────────────────────────
        private static int RegRootFromHive(string hive)
        {
            string h = hive.Trim().ToUpperInvariant();
            if (h is "HKEY_CLASSES_ROOT" or "HKCR") return 0;
            if (h is "HKEY_CURRENT_USER" or "HKCU") return 1;
            if (h is "HKEY_LOCAL_MACHINE" or "HKLM") return 2;
            if (h is "HKEY_USERS" or "HKU")          return 3;
            return int.MinValue;   // unsupported (e.g. HKEY_CURRENT_CONFIG)
        }

        private static string RegHiveForExport(int root) => root switch
        {
            0 => "HKEY_CLASSES_ROOT",
            1 => "HKEY_CURRENT_USER",
            3 => "HKEY_USERS",
            _ => "HKEY_LOCAL_MACHINE"   // 2 and HKMU (-1) export under HKLM
        };

        private void RegExport_Click(object sender, RoutedEventArgs e)
        {
            var node = SelectedReg();
            if (node == null)
            { MstMessage("Select a key or hive to export.", "Export Registry", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var dlg = new Microsoft.Win32.SaveFileDialog
            {
                Title = "Export Registry",
                Filter = "Registration files (*.reg)|*.reg|All files (*.*)|*.*",
                DefaultExt = ".reg",
                FileName = SanitizeKey(node.Display) + ".reg"
            };
            if (dlg.ShowDialog() != true) return;

            var sb = new System.Text.StringBuilder();
            sb.Append("Windows Registry Editor Version 5.00\r\n");
            int keys = 0;
            void Walk(RegNode n)
            {
                if (!n.IsHive)
                {
                    sb.Append("\r\n[").Append(RegHiveForExport(n.Root)).Append('\\').Append(n.FullPath).Append("]\r\n");
                    keys++;
                    foreach (var r in n.Values)
                    {
                        if (r.RowState == DataRowState.Deleted) continue;
                        string nm = Cv(r["Name"]);
                        if (nm == "+" || nm == "-" || nm == "*") continue;   // key markers; header already covers them
                        var (type, data) = DecodeRegValue(Cv(r["Value"]));
                        string left  = nm.Length == 0 ? "@" : "\"" + RegEscape(nm) + "\"";
                        sb.Append(left).Append('=').Append(RegDataLine(type, data)).Append("\r\n");
                    }
                }
                foreach (var ch in n.Children) Walk(ch);
            }
            Walk(node);

            try
            {
                System.IO.File.WriteAllText(dlg.FileName, sb.ToString(), System.Text.Encoding.Unicode);
                TxtStatus.Text = $"Exported {keys} key(s) to {System.IO.Path.GetFileName(dlg.FileName)}.";
            }
            catch (Exception ex)
            { MstMessage("Could not write the file: " + ex.Message, "Export Registry", MessageBoxButton.OK, MessageBoxImage.Warning); }
        }

        // Exports every hive in the registry tree to one .reg file (all roots, not just the
        // selected node). Opens the same Save dialog as Export Registry.
        private void RegExportAll_Click(object sender, RoutedEventArgs e)
        {
            if (_regRoots == null || _regRoots.Count == 0)
            { MstMessage("There are no registry entries to export.", "Export All Registry", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var dlg = new Microsoft.Win32.SaveFileDialog
            {
                Title = "Export All Registry",
                Filter = "Registration files (*.reg)|*.reg|All files (*.*)|*.*",
                DefaultExt = ".reg",
                FileName = "Registry.reg"
            };
            if (dlg.ShowDialog() != true) return;

            var sb = new System.Text.StringBuilder();
            sb.Append("Windows Registry Editor Version 5.00\r\n");
            int keys = 0;
            void Walk(RegNode n)
            {
                if (!n.IsHive)
                {
                    sb.Append("\r\n[").Append(RegHiveForExport(n.Root)).Append('\\').Append(n.FullPath).Append("]\r\n");
                    keys++;
                    foreach (var r in n.Values)
                    {
                        if (r.RowState == DataRowState.Deleted) continue;
                        string nm = Cv(r["Name"]);
                        if (nm == "+" || nm == "-" || nm == "*") continue;   // key markers; header already covers them
                        var (type, data) = DecodeRegValue(Cv(r["Value"]));
                        string left  = nm.Length == 0 ? "@" : "\"" + RegEscape(nm) + "\"";
                        sb.Append(left).Append('=').Append(RegDataLine(type, data)).Append("\r\n");
                    }
                }
                foreach (var ch in n.Children) Walk(ch);
            }
            foreach (var root in _regRoots) Walk(root);

            try
            {
                System.IO.File.WriteAllText(dlg.FileName, sb.ToString(), System.Text.Encoding.Unicode);
                TxtStatus.Text = $"Exported all registry ({keys} key(s)) to {System.IO.Path.GetFileName(dlg.FileName)}.";
            }
            catch (Exception ex)
            { MstMessage("Could not write the file: " + ex.Message, "Export All Registry", MessageBoxButton.OK, MessageBoxImage.Warning); }
        }

        private static string RegEscape(string s) => s.Replace("\\", "\\\\").Replace("\"", "\\\"");
        private static string RegUnescape(string s) =>
            s.Replace("\\\\", "\u0001").Replace("\\\"", "\"").Replace("\u0001", "\\");

        // Format an MSI-decoded value as the right-hand side of a .reg line.
        private static string RegDataLine(string type, string data)
        {
            switch (type)
            {
                case "REG_DWORD":
                {
                    long v = long.TryParse(data.Trim(), out var d) ? d : 0;
                    return "dword:" + ((uint)v).ToString("x8");
                }
                case "REG_BINARY":
                    return "hex:" + HexCommaWrap(HexStringToBytes(data));
                case "REG_EXPAND_SZ":
                    return "hex(2):" + HexCommaWrap(System.Text.Encoding.Unicode.GetBytes(data + "\0"));
                case "REG_MULTI_SZ":
                {
                    var ms = new System.Collections.Generic.List<byte>();
                    foreach (var part in data.Replace("\r\n", "\n").Split('\n'))
                        ms.AddRange(System.Text.Encoding.Unicode.GetBytes(part + "\0"));
                    ms.AddRange(new byte[] { 0, 0 });
                    return "hex(7):" + HexCommaWrap(ms.ToArray());
                }
                default:
                    return "\"" + RegEscape(data) + "\"";
            }
        }

        private static byte[] HexStringToBytes(string hex)
        {
            string h = HexNormalize(hex);
            if ((h.Length & 1) == 1) h = "0" + h;
            var b = new byte[h.Length / 2];
            for (int i = 0; i < b.Length; i++) b[i] = Convert.ToByte(h.Substring(i * 2, 2), 16);
            return b;
        }

        private static string HexNormalize(string hex)
        {
            var sb = new System.Text.StringBuilder();
            foreach (char c in hex) if (Uri.IsHexDigit(c)) sb.Append(c);
            return sb.ToString();
        }

        private static string HexCommaWrap(byte[] bytes)
        {
            var sb = new System.Text.StringBuilder();
            for (int i = 0; i < bytes.Length; i++)
            {
                if (i > 0) sb.Append(',');
                if (i > 0 && i % 25 == 0) sb.Append("\\\r\n  ");
                sb.Append(bytes[i].ToString("x2"));
            }
            return sb.ToString();
        }

        private void RegImport_Click(object sender, RoutedEventArgs e)
        {
            var regSt = EnsureTableCached("Registry");
            if (regSt == null)
            { MstMessage("This MSI has no Registry table.", "Import Registry", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            string? comp = RegComponentFor(SelectedReg() ?? new RegNode());
            if (comp == null)
            { MstMessage("No component is available to attach imported entries to.", "Import Registry", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            var dlg = new Microsoft.Win32.OpenFileDialog
            {
                Title = "Import Registry",
                Filter = "Registration files (*.reg)|*.reg|All files (*.*)|*.*",
                CheckFileExists = true
            };
            if (dlg.ShowDialog() != true) return;

            string[] rawLines;
            try
            {
                using var sr = new System.IO.StreamReader(dlg.FileName, System.Text.Encoding.Default, true);
                rawLines = sr.ReadToEnd().Replace("\r\n", "\n").Split('\n');
            }
            catch (Exception ex)
            { MstMessage("Could not read the file: " + ex.Message, "Import Registry", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            // Join continuation lines (hex values ending with a backslash).
            var lines = new System.Collections.Generic.List<string>();
            var cur = new System.Text.StringBuilder();
            foreach (var ln in rawLines)
            {
                string t = ln.TrimEnd();
                if (t.EndsWith("\\")) cur.Append(t.Substring(0, t.Length - 1).TrimEnd());
                else { cur.Append(t); lines.Add(cur.ToString()); cur.Clear(); }
            }
            if (cur.Length > 0) lines.Add(cur.ToString());

            int root = int.MinValue; string key = ""; int added = 0, skipped = 0;
            bool keyHadValue = false; bool keyHasMarker = false;

            void FlushEmptyKey()
            {
                if (root != int.MinValue && key.Length > 0 && !keyHadValue && !keyHasMarker)
                {
                    var kr = regSt.Data.NewRow();
                    kr["Registry"] = UniqueKey(regSt.Data, "Registry", SanitizeKey("reg_" + key));
                    if (regSt.Data.Columns.Contains("Root"))       kr["Root"]       = root.ToString();
                    if (regSt.Data.Columns.Contains("Key"))        kr["Key"]        = key;
                    if (regSt.Data.Columns.Contains("Name"))       kr["Name"]       = "+";
                    if (regSt.Data.Columns.Contains("Component_")) kr["Component_"] = comp;
                    regSt.Data.Rows.Add(kr); added++;
                }
            }

            foreach (var raw in lines)
            {
                string line = raw.Trim();
                if (line.Length == 0 || line.StartsWith(";")) continue;
                if (line.StartsWith("Windows Registry Editor", StringComparison.OrdinalIgnoreCase)) continue;
                if (line.Equals("REGEDIT4", StringComparison.OrdinalIgnoreCase)) continue;

                if (line.StartsWith("[") && line.EndsWith("]"))
                {
                    FlushEmptyKey();
                    string inner = line.Substring(1, line.Length - 2).Trim();
                    bool del = inner.StartsWith("-");
                    if (del) inner = inner.Substring(1).Trim();
                    int slash = inner.IndexOf('\\');
                    string hive = slash >= 0 ? inner.Substring(0, slash) : inner;
                    string kp   = slash >= 0 ? inner.Substring(slash + 1) : "";
                    root = RegRootFromHive(hive); key = kp.Trim('\\'); keyHadValue = false; keyHasMarker = false;
                    if (root == int.MinValue) { skipped++; continue; }
                    if (del && key.Length > 0)
                    {
                        var dr = regSt.Data.NewRow();
                        dr["Registry"] = UniqueKey(regSt.Data, "Registry", SanitizeKey("reg_" + key));
                        if (regSt.Data.Columns.Contains("Root"))       dr["Root"]       = root.ToString();
                        if (regSt.Data.Columns.Contains("Key"))        dr["Key"]        = key;
                        if (regSt.Data.Columns.Contains("Name"))       dr["Name"]       = "-";
                        if (regSt.Data.Columns.Contains("Component_")) dr["Component_"] = comp;
                        regSt.Data.Rows.Add(dr); added++; keyHasMarker = true;
                    }
                    continue;
                }

                if (root == int.MinValue || key.Length == 0) continue;

                int eq = FindRegNameValueSplit(line);
                if (eq < 0) continue;
                string namePart = line.Substring(0, eq).Trim();
                string valPart  = line.Substring(eq + 1).Trim();

                string name;
                if (namePart == "@") name = "";
                else if (namePart.Length >= 2 && namePart.StartsWith("\"") && namePart.EndsWith("\""))
                    name = RegUnescape(namePart.Substring(1, namePart.Length - 2));
                else name = namePart.Trim('"');

                if (valPart == "-") continue;   // value deletion, not represented in the table

                var (mtype, mdata, ok) = ParseRegData(valPart);
                if (!ok) { skipped++; continue; }

                var nr = regSt.Data.NewRow();
                nr["Registry"] = UniqueKey(regSt.Data, "Registry", SanitizeKey("reg_" + (name.Length > 0 ? name : key)));
                if (regSt.Data.Columns.Contains("Root"))       nr["Root"]       = root.ToString();
                if (regSt.Data.Columns.Contains("Key"))        nr["Key"]        = key;
                if (regSt.Data.Columns.Contains("Name"))       nr["Name"]       = name;
                if (regSt.Data.Columns.Contains("Value"))      nr["Value"]      = EncodeRegValue(mtype, mdata);
                if (regSt.Data.Columns.Contains("Component_")) nr["Component_"] = comp;
                regSt.Data.Rows.Add(nr); added++; keyHadValue = true;
            }
            FlushEmptyKey();

            if (added == 0)
            {
                MstMessage(skipped > 0 ? "Nothing was imported. The file may use unsupported hives." : "Nothing was imported.",
                    "Import Registry", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            _regRoots = null; _regTreeBuiltFor = "\0";
            ShowRegistryForm(regSt);
            UpdateEditCount();
            TxtStatus.Text = skipped > 0
                ? $"Imported {added} registry entries, skipped {skipped} unsupported."
                : $"Imported {added} registry entries.";
        }

        // Find the '=' that separates a .reg name from its value, skipping any
        // '=' that sits inside the quoted name.
        private static int FindRegNameValueSplit(string line)
        {
            if (line.StartsWith("@")) return line.IndexOf('=');
            if (!line.StartsWith("\"")) return line.IndexOf('=');
            bool esc = false;
            for (int i = 1; i < line.Length; i++)
            {
                char c = line[i];
                if (esc) { esc = false; continue; }
                if (c == '\\') { esc = true; continue; }
                if (c == '"') return line.IndexOf('=', i);
            }
            return -1;
        }

        // Parse a .reg right-hand value into an MSI (type, data) pair.
        private (string type, string data, bool ok) ParseRegData(string v)
        {
            v = v.Trim();
            if (v.StartsWith("\""))
            {
                int end = v.LastIndexOf('"');
                string inner = end > 0 ? v.Substring(1, end - 1) : "";
                return ("REG_SZ", RegUnescape(inner), true);
            }
            if (v.StartsWith("dword:", StringComparison.OrdinalIgnoreCase))
            {
                string hx = v.Substring(6).Trim();
                return uint.TryParse(hx, System.Globalization.NumberStyles.HexNumber,
                        System.Globalization.CultureInfo.InvariantCulture, out uint dw)
                    ? ("REG_DWORD", dw.ToString(), true)
                    : ("REG_DWORD", "0", true);
            }
            if (v.StartsWith("hex(2):", StringComparison.OrdinalIgnoreCase))
                return ("REG_EXPAND_SZ", BytesToUtf16(HexStringToBytes(v.Substring(7))), true);
            if (v.StartsWith("hex(7):", StringComparison.OrdinalIgnoreCase))
                return ("REG_MULTI_SZ", string.Join("\n", Utf16MultiToList(HexStringToBytes(v.Substring(7)))), true);
            if (v.StartsWith("hex(", StringComparison.OrdinalIgnoreCase))
            {
                int colon = v.IndexOf(':');
                return colon > 0 ? ("REG_BINARY", HexNormalize(v.Substring(colon + 1)), true) : ("", "", false);
            }
            if (v.StartsWith("hex:", StringComparison.OrdinalIgnoreCase))
                return ("REG_BINARY", HexNormalize(v.Substring(4)), true);
            return ("", "", false);
        }

        private static string BytesToUtf16(byte[] b)
        {
            string s = System.Text.Encoding.Unicode.GetString(b);
            int z = s.IndexOf('\0');
            return z >= 0 ? s.Substring(0, z) : s;
        }

        private static System.Collections.Generic.List<string> Utf16MultiToList(byte[] b)
        {
            var list = new System.Collections.Generic.List<string>();
            foreach (var part in System.Text.Encoding.Unicode.GetString(b).Split('\0'))
                if (part.Length > 0) list.Add(part);
            return list;
        }

        // MSI Registry Value encoding: "#x"=binary(hex), "#%"=expandable string,
        // "##"=literal leading '#', "#"=DWORD, "[~]"=multi-string separator, else string.
        private static (string type, string data) DecodeRegValue(string v)
        {
            if (v.StartsWith("#x", StringComparison.Ordinal)) return ("REG_BINARY",    v.Substring(2));
            if (v.StartsWith("#%", StringComparison.Ordinal)) return ("REG_EXPAND_SZ", v.Substring(2));
            if (v.StartsWith("##", StringComparison.Ordinal)) return ("REG_SZ",        "#" + v.Substring(2));
            if (v.StartsWith("#",  StringComparison.Ordinal)) return ("REG_DWORD",     v.Substring(1));
            if (v.Contains("[~]"))                            return ("REG_MULTI_SZ",  v.Replace("[~]", "\n"));
            return ("REG_SZ", v);
        }

        private static string EncodeRegValue(string type, string data) => type switch
        {
            "REG_BINARY"    => "#x" + data.Replace(" ", "").Replace("\n", "").Replace("\r", ""),
            "REG_EXPAND_SZ" => "#%" + data,
            "REG_DWORD"     => "#" + data.Trim(),
            "REG_MULTI_SZ"  => data.Replace("\r\n", "\n").Replace("\n", "[~]"),
            _               => data.StartsWith("#", StringComparison.Ordinal) ? "#" + data : data
        };

        // Value editor: Name, Type (dropdown) and Data. Returns null if cancelled.
        private (string name, string type, string data)? PromptRegValue(
            string title, string name, string type, string data)
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);

            int r = 0;
            void AddLabel(string text, FrameworkElement field)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(0, 10, 0, 0)
                };
                field.Margin = new Thickness(0, 6, 0, 0);
                Grid.SetRow(lbl, r);   Grid.SetColumn(lbl, 0);
                Grid.SetRow(field, r); Grid.SetColumn(field, 1);
                cg.Children.Add(lbl); cg.Children.Add(field);
                r++;
            }

            var (nameField, nameBox) = MakeRoundedField(name, boxBg, boxBdr, valFg, false, null);
            AddLabel("Name", nameField);

            var typeBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            (string token, string label)[] types =
            {
                ("REG_SZ",        "REG_SZ (String)"),
                ("REG_EXPAND_SZ", "REG_EXPAND_SZ (Expandable String)"),
                ("REG_DWORD",     "REG_DWORD (Number)"),
                ("REG_BINARY",    "REG_BINARY (Hex bytes)"),
                ("REG_MULTI_SZ",  "REG_MULTI_SZ (Multi-String)")
            };
            foreach (var (tok, lab) in types)
                typeBox.Items.Add(new ComboBoxItem { Content = lab, Tag = tok });
            int selIdx = Array.FindIndex(types, t => t.token == type);
            typeBox.SelectedIndex = selIdx >= 0 ? selIdx : 0;
            AddLabel("Type", RoundWrapControl(typeBox, boxBg, boxBdr));

            var (dataField, dataBox) = MakeRoundedField(data, boxBg, boxBdr, valFg, true, null);
            AddLabel("Data", dataField);

            NdAddSpacer(cg, r++);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            (string name, string type, string data)? result = null;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () =>
                {
                    string tok = (typeBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "REG_SZ";
                    result = (nameBox.Text, tok, dataBox.Text);
                    win.Close();
                }),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);

            nameBox.Loaded += (_, _) => { nameBox.SelectAll(); nameBox.Focus(); };
            win.ShowDialog();
            return result;
        }

        // ══ Shortcuts category (location tree + shortcut list + editor) ══════
        private System.Collections.ObjectModel.ObservableCollection<DirNode>? _scRoots;
        private string _scTreeBuiltFor = "\0";

        private sealed class ShortcutData
        {
            public string Name = "", Target = "", Arguments = "", Description = "",
                          WorkingDir = "", Icon = "", IconIndex = "", ShowCmd = "1";
            // Destination folder (Shortcut.Directory_). Only the create dialog sets it; the editor
            // leaves it empty because moving an existing shortcut is a tree operation, not a field.
            public string Directory = "";
            // Component the shortcut installs with (Shortcut.Component_). Create dialog only, for
            // the same reason: reassigning an existing shortcut is not one of the editor's fields.
            public string Component = "";
        }

        /// <summary>
        /// The destination-folder tree for a set of Shortcut rows, pruned to the folders that
        /// actually hold one. Passing a component name narrows it to that component's shortcuts,
        /// which is what the Features view needs: the same shape as the Shortcuts category, scoped
        /// to one component.
        /// </summary>
        private System.Collections.ObjectModel.ObservableCollection<DirNode> BuildScRoots(
            TableState scSt, string? componentFilter, out int total)
        {
            static string Cell(DataRow r, string c) =>
                r.Table.Columns.Contains(c) && r[c] != DBNull.Value ? r[c].ToString() ?? "" : "";

            var dirSt = EnsureTableCached("Directory");
            var nodes = new Dictionary<string, DirNode>(StringComparer.OrdinalIgnoreCase);
            if (dirSt != null)
                foreach (DataRow r in dirSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string key = Cell(r, "Directory");
                    if (key.Length == 0) continue;
                    nodes[key] = new DirNode { Key = key, DefaultDir = Cell(r, "DefaultDir"), ParentKey = Cell(r, "Directory_Parent"), DirRow = r };
                }

            // Shortcuts reference their install folder directly via Directory_.
            DirNode? orphan = null;
            total = 0;
            foreach (DataRow sr in scSt.Data.Rows)
            {
                if (sr.RowState == DataRowState.Deleted) continue;
                if (componentFilter != null && scSt.Data.Columns.Contains("Component_") &&
                    !string.Equals(Cell(sr, "Component_"), componentFilter, StringComparison.OrdinalIgnoreCase))
                    continue;
                total++;
                string dir = Cell(sr, "Directory_");
                if (dir.Length > 0 && nodes.TryGetValue(dir, out var node)) node.Files.Add(sr);
                else { orphan ??= new DirNode { Key = "(unknown)" }; orphan.Files.Add(sr); }
            }

            var roots = new System.Collections.ObjectModel.ObservableCollection<DirNode>();
            foreach (var node in nodes.Values)
            {
                node.Display = FriendlyDir(node.Key, node.LongName);
                bool isRoot = node.ParentKey.Length == 0
                    || string.Equals(node.ParentKey, node.Key, StringComparison.OrdinalIgnoreCase)
                    || !nodes.ContainsKey(node.ParentKey);
                if (!isRoot && nodes.TryGetValue(node.ParentKey, out var p) && !ReferenceEquals(p, node))
                    { p.Children.Add(node); node.Parent = p; }
                else
                    roots.Add(node);
            }
            if (orphan != null) { orphan.Display = "(unknown)"; roots.Add(orphan); }

            // Folders are pruned to the ones that actually hold a shortcut (with their ancestors),
            // except the standard destinations, which stay whether or not they hold one. Pruning
            // them too meant that creating the first shortcut made every other destination
            // disappear, leaving nowhere to put the second one.
            //
            // They are kept only in the category tree: the component-scoped tree in the Features
            // view answers "what does this component install", and folders it has nothing in would
            // be noise there.
            bool keepDestinations = componentFilter == null;
            for (int i = roots.Count - 1; i >= 0; i--)
                if (!PruneNoShortcuts(roots[i], keepDestinations)) roots.RemoveAt(i);

            if (keepDestinations) AddMissingScDestinations(roots, nodes);
            // Nothing to show prunes down to an empty tree, and an empty tree has no folder to
            // select - which would mean New Shortcut could never be reached. Fall back to the
            // standard shortcut destinations so there is always somewhere to attach one.
            else if (total == 0) roots = BuildScDestinationRoots(nodes);

            SortNodes(roots);
            foreach (var r in roots) AddShortcutLeaves(r);   // show each shortcut as a leaf node
            foreach (var r in roots) r.IsExpanded = true;
            return roots;
        }

        private void ShowShortcutsForm(TableState scSt)
        {
            if (_scRoots != null && _scTreeBuiltFor == _msiPath)
            {
                if (ScTree != null && ScTree.ItemsSource == null) ScTree.ItemsSource = _scRoots;
                if (FormShortcutsPanel != null) FormShortcutsPanel.Visibility = Visibility.Visible;
                SelectFirstShortcut();
                return;
            }

            var roots = BuildScRoots(scSt, null, out int total);

            _scRoots = roots;
            _scTreeBuiltFor = _msiPath;

            ScTree.ItemsSource = roots;
            if (ScCount != null) ScCount.Text = total == 1 ? "1 shortcut" : $"{total} shortcuts";
            if (FormShortcutsPanel != null) FormShortcutsPanel.Visibility = Visibility.Visible;
            if (total == 0) ShowScFolderState(null); else SelectFirstShortcut();
        }

        /// <summary>
        /// Destination folders offered when a package contains no shortcuts yet. These are the
        /// standard Windows Installer directory properties a shortcut is normally created in;
        /// only those the package actually defines can be used, because New Shortcut needs a real
        /// Directory row to attach to.
        /// </summary>
        private static readonly string[] ScDestinationKeys =
        {
            "DesktopFolder", "ProgramMenuFolder", "StartMenuFolder", "StartupFolder",
        };

        private System.Collections.ObjectModel.ObservableCollection<DirNode> BuildScDestinationRoots(
            System.Collections.Generic.Dictionary<string, DirNode> nodes)
        {
            var outp = new System.Collections.ObjectModel.ObservableCollection<DirNode>();

            foreach (string key in ScDestinationKeys)
            {
                if (nodes.TryGetValue(key, out var n) && n.DirRow != null)
                {
                    n.Children.Clear();          // nothing is nested under it while empty
                    n.Parent = null;
                    n.Display = FriendlyDir(n.Key, n.LongName);
                    outp.Add(n);
                }
                else
                {
                    // Listed even though the package has no such folder yet. Desktop is the common
                    // case: an MSI only carries a DesktopFolder row once something installs there,
                    // so leaving it out meant the one shortcut people most often want to add had
                    // nowhere to go. The row is created when a shortcut is actually placed here.
                    outp.Add(new DirNode { Key = key, Display = FriendlyDir(key, "") });
                }
            }

            SortNodes(outp);
            return outp;
        }

        /// <summary>
        /// The right-hand pane whenever a folder rather than a shortcut is selected: what that
        /// folder holds, and the same New Shortcut action the right-click menu offers, so the tree
        /// does not have to be discovered first.
        ///
        /// Shown for every folder, not only for a package with no shortcuts at all. The pane going
        /// blank on a folder click read as the page having lost its way, and it left the one
        /// package state where there is nothing to select - an empty folder - with nothing to act
        /// on either.
        /// </summary>
        /// <summary>Shortcuts held by a folder and everything under it.</summary>
        private static int ScSubtreeShortcutCount(DirNode n)
        {
            if (n.IsShortcut) return 0;
            int total = 0;
            foreach (var f in n.Files) if (f.RowState != DataRowState.Deleted) total++;
            foreach (var ch in n.Children) total += ScSubtreeShortcutCount(ch);
            return total;
        }

        private void ShowScFolderState(DirNode? folder)
        {
            if (ScEditorHost == null) return;
            ClearScEditor();

            Brush lblFg = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            // Counted twice: what sits in this folder, and what sits anywhere under it. A container
            // like Target Computer holds nothing itself, so counting only the first said "no
            // shortcuts" while the tree beside it plainly showed some.
            int here = 0, below = 0;
            if (folder != null)
            {
                foreach (var f in folder.Files)
                    if (f.RowState != DataRowState.Deleted) here++;
                foreach (var ch in folder.Children)
                    below += ScSubtreeShortcutCount(ch);
            }

            bool none = _scRoots == null || !ScTreeHasShortcut(_scRoots);
            string head = none                ? "This MSI has no shortcuts."
                        : folder == null      ? "No shortcut selected."
                        : here == 1           ? $"1 shortcut in {folder.Display}."
                        : here > 1            ? $"{here} shortcuts in {folder.Display}."
                        : below == 1          ? $"1 shortcut in a folder under {folder.Display}."
                        : below > 1           ? $"{below} shortcuts in folders under {folder.Display}."
                        :                       $"No shortcuts in {folder.Display}.";

            var panel = new StackPanel { Margin = new Thickness(16, 18, 16, 16) };
            panel.Children.Add(new TextBlock
            {
                Text = head, FontSize = 13,
                FontWeight = FontWeights.SemiBold, Foreground = valFg
            });
            panel.Children.Add(new TextBlock
            {
                Text = here + below > 0
                     ? "Pick one on the left to edit it, or create another one here."
                     : "Pick a destination folder on the left, then create the shortcut. "
                     + "Its fields open for editing as soon as it exists.",
                FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 6, 0, 12)
            });

            var btn = new Button
            {
                Content = "\u2795 New Shortcut", FontSize = 12, Padding = new Thickness(14, 6, 14, 6),
                HorizontalAlignment = HorizontalAlignment.Left
            };
            btn.Click += (_, _) =>
            {
                // Default to the first destination so the button works without a selection.
                if (ScTree != null && ScTree.SelectedItem == null && _scRoots is { Count: > 0 })
                    RevealTreeNode(ScTree, _scRoots[0]);
                ScNewShortcut_Click(btn, new RoutedEventArgs());
            };
            panel.Children.Add(btn);

            ScEditorHost.Content = panel;
        }

        private static bool ScTreeHasShortcut(System.Collections.Generic.IEnumerable<DirNode> nodes)
        {
            foreach (var n in nodes)
            {
                if (n.IsShortcut && n.ScRow != null) return true;
                if (ScTreeHasShortcut(n.Children)) return true;
            }
            return false;
        }

        private static string ScDisplayName(DataRow row)
        {
            string n = row.Table.Columns.Contains("Name") && row["Name"] != DBNull.Value ? row["Name"].ToString() ?? "" : "";
            int bar = n.IndexOf('|');
            string disp = bar >= 0 ? n.Substring(bar + 1) : n;
            if (disp.Length > 0) return disp;
            return row.Table.Columns.Contains("Shortcut") && row["Shortcut"] != DBNull.Value ? row["Shortcut"].ToString() ?? "(shortcut)" : "(shortcut)";
        }

        // Append a leaf node for each shortcut held in a folder, after its real subfolders.
        private void AddShortcutLeaves(DirNode node)
        {
            foreach (var ch in node.Children.Where(c => !c.IsShortcut).ToList())
                AddShortcutLeaves(ch);
            var leaves = new System.Collections.Generic.List<DirNode>();
            foreach (var row in node.Files)
            {
                if (row.RowState == DataRowState.Deleted) continue;
                leaves.Add(new DirNode { IsShortcut = true, ScRow = row, Parent = node, Display = ScDisplayName(row) });
            }
            leaves.Sort((a, b) => string.Compare(a.Display, b.Display, StringComparison.OrdinalIgnoreCase));
            foreach (var lf in leaves) node.Children.Add(lf);
        }

        private void RebuildScTree()
        {
            // Both trees are built over the same table, so whichever one is not on screen is
            // discarded and rebuilt when it next opens rather than left showing the old shape.
            _scRoots = null; _scTreeBuiltFor = "\0";
            if (ScTree != null) ScTree.ItemsSource = null;

            if (FeatScTree is { IsVisible: true } && _detailComp.Length > 0)
            { ShowComponentShortcuts(_detailComp); return; }

            var scSt = EnsureTableCached("Shortcut");
            if (scSt != null) ShowShortcutsForm(scSt);
        }

        // True if this node or any descendant holds a shortcut; prunes empty children. A standard
        // destination counts as worth keeping on its own, so an empty Desktop or Startup survives
        // and can still be created in. So does a folder whose Directory row was added in this
        // session: New Folder makes an empty one on purpose, and pruning it away between the
        // folder being created and the first shortcut going into it left nothing to aim at.
        private static bool PruneNoShortcuts(DirNode n, bool keepDestinations)
        {
            bool any = n.Files.Any(f => f.RowState != DataRowState.Deleted)
                    || (keepDestinations && ScDestinationKeys.Contains(n.Key, StringComparer.OrdinalIgnoreCase))
                    || (keepDestinations && n.DirRow != null && n.DirRow.RowState == DataRowState.Added);
            for (int i = n.Children.Count - 1; i >= 0; i--)
            {
                if (PruneNoShortcuts(n.Children[i], keepDestinations)) any = true;
                else n.Children.RemoveAt(i);
            }
            return any;
        }

        /// <summary>
        /// Adds any standard destination the package has no Directory row for, so all four folders
        /// a shortcut is normally created in are offered. Desktop is the common case: an MSI only
        /// carries a DesktopFolder row once something installs there. The row itself is created
        /// when a shortcut is actually placed in the folder (see EnsureDirectoryRow).
        /// </summary>
        private void AddMissingScDestinations(
            System.Collections.ObjectModel.ObservableCollection<DirNode> roots,
            System.Collections.Generic.Dictionary<string, DirNode> nodes)
        {
            var present = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            void Walk(System.Collections.Generic.IEnumerable<DirNode> ns)
            {
                foreach (var n in ns)
                {
                    if (n.Key.Length > 0) present.Add(n.Key);
                    Walk(n.Children);
                }
            }
            Walk(roots);

            // The added folders hang where the real ones do, under Target Computer, so the tree
            // keeps one shape whether the package defines them or not. A package whose tree pruned
            // away entirely gets that root back rather than four loose folders.
            DirNode? host = null;
            foreach (var n in roots)
                if (string.Equals(n.Key, "TARGETDIR", StringComparison.OrdinalIgnoreCase)) { host = n; break; }
            if (host == null && nodes.TryGetValue("TARGETDIR", out var target))
            {
                host = target;
                host.Parent = null;
                host.Display = FriendlyDir(host.Key, host.LongName);
                roots.Add(host);
            }

            foreach (string key in ScDestinationKeys)
            {
                if (present.Contains(key)) continue;
                var node = new DirNode { Key = key, Display = FriendlyDir(key, "") };
                if (host != null) { node.Parent = host; host.Children.Add(node); }
                else roots.Add(node);
            }
        }

        /// <summary>The shortcut tree the actions apply to: the component-scoped one in the
        /// Features view when it is on screen, otherwise the Shortcuts category tree.</summary>
        private System.Windows.Controls.TreeView? ActiveScTree()
            => FeatScTree is { IsVisible: true } ? FeatScTree : ScTree;

        private DirNode? SelectedSc() => ActiveScTree()?.SelectedItem as DirNode;

        // The selected folder, or the parent folder when a shortcut leaf is selected.
        private DirNode? SelectedScFolder()
        {
            var n = SelectedSc();
            if (n == null) return null;
            return n.IsShortcut ? n.Parent : n;
        }

        private DirNode? _scEditNode;
        private bool _scEditorLoading;

        private void ScTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is DirNode node && node.IsShortcut && node.ScRow != null)
                ShowScEditor(node);
            else
                ShowScFolderState(e.NewValue as DirNode);
        }

        private void ClearScEditor()
        {
            _scEditNode = null;
            if (ScEditorHost != null) ScEditorHost.Content = null;
        }

        // Auto-select the first shortcut leaf so its editor shows on open. If a
        // shortcut is already selected, just (re)show its editor.
        private void SelectFirstShortcut()
        {
            if (_scRoots == null || ScTree == null) return;
            if (FeatScTree is { IsVisible: true }) return;   // the Features pane drives its own selection
            if (ScTree.SelectedItem is DirNode sel && sel.IsShortcut && sel.ScRow != null)
            { ShowScEditor(sel); return; }
            DirNode? First(System.Collections.Generic.IEnumerable<DirNode> nodes)
            {
                foreach (var n in nodes)
                {
                    if (n.IsShortcut && n.ScRow != null) return n;
                    var f = First(n.Children);
                    if (f != null) return f;
                }
                return null;
            }
            var leaf = First(_scRoots);
            if (leaf == null) { ShowScFolderState(ScTree.SelectedItem as DirNode); return; }
            for (var p = leaf.Parent; p != null; p = p.Parent) p.IsExpanded = true;
            RevealTreeNode(ScTree, leaf);   // selects it (fires the editor) with layout retries
        }

        private void SelectScLeaf(DataRow row)
        {
            if (_scRoots == null || ScTree == null) return;
            DirNode? Find(System.Collections.Generic.IEnumerable<DirNode> nodes)
            {
                foreach (var n in nodes)
                {
                    if (n.IsShortcut && ReferenceEquals(n.ScRow, row)) return n;
                    var f = Find(n.Children);
                    if (f != null) return f;
                }
                return null;
            }
            var leaf = Find(_scRoots);
            if (leaf == null) return;
            for (var p = leaf.Parent; p != null; p = p.Parent) p.IsExpanded = true;
            ScTree.Dispatcher.BeginInvoke(new Action(() =>
            {
                try
                {
                    ScTree.UpdateLayout();
                    var tvi = FindRealizedTreeItem(ScTree, leaf);
                    if (tvi != null) { tvi.IsSelected = true; tvi.BringIntoView(); }
                }
                catch { }
            }), System.Windows.Threading.DispatcherPriority.Background);
        }

        // Builds the editable shortcut form directly in the right-hand panel.
        // Text fields commit on focus loss; the window-style combo commits immediately.
        private void ShowScEditor(DirNode leaf)
        {
            if (ScEditorHost == null || leaf.ScRow == null) return;
            _scEditorLoading = true;
            _scEditNode = leaf;
            var row = leaf.ScRow;
            var data = ReadShortcutData(row);

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")      as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")   as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(110) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            TextBlock Lbl(string t) => new TextBlock
            {
                Text = t, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
            };
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = Lbl(label);
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }
            void AddRead(string label, string text) => AddRow(label, new TextBlock
            {
                Text = text.Length > 0 ? text : "(none)", FontSize = 12, Foreground = valFg,
                VerticalAlignment = VerticalAlignment.Center
            });

            string keyName = row.Table.Columns.Contains("Shortcut") ? Cv(row["Shortcut"]) : "";
            string comp    = row.Table.Columns.Contains("Component_") ? Cv(row["Component_"]) : "";
            AddRead("Key name", keyName);
            AddRead("Component", comp);

            var (nameField, nameBox) = MakeRoundedField(data.Name, boxBg, boxBdr, valFg, false, null);
            AddRow("Display name", nameField);

            // ── Advertise ────────────────────────────────────────────────────────────────
            // Not a column: a shortcut is advertised when Target names a Feature rather than a
            // file, so the dropdown reads that state and, when changed, rewrites Target to match.
            //   Yes -> the feature that publishes this shortcut's component
            //   No  -> [#KeyPathFile] of that component
            // If the package gives us nothing to rewrite to, Target is left exactly as it was and
            // the dropdown snaps back on the next refresh rather than writing something invented.
            string scComp = row.Table.Columns.Contains("Component_") ? Cv(row["Component_"]) : "";
            bool advertised = IsFeatureName(data.Target);
            var advBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            advBox.Items.Add(new ComboBoxItem { Content = "No",  Tag = "No" });
            advBox.Items.Add(new ComboBoxItem { Content = "Yes", Tag = "Yes" });
            advBox.SelectedIndex = advertised ? 1 : 0;
            AddRow("Advertise", RoundWrapControl(advBox, boxBg, boxBdr));

            var (tgtField, tgtBox) = MakeRoundedField(data.Target, boxBg, boxBdr, valFg, false,
                () => PickFileFromPackage("Select a file", data.Target));
            AddRow("Target", tgtField);

            // ── Target path (derived, read-only) ─────────────────────────────────────────
            // Resolved from Target, so it is shown rather than edited: editing it would mean
            // reverse-mapping a path back onto a File key, and Target is already the field that
            // controls this. Refreshed whenever Target changes.
            var (tgtPathField, tgtPathBox) = MakeRoundedField(
                ShortcutTargetPath(row, data.Target), boxBg, boxBdr, valFg, false, null);
            tgtPathBox.IsReadOnly = true;
            tgtPathBox.Cursor     = System.Windows.Input.Cursors.Arrow;
            AddRow("Target path", tgtPathField);

            // ── Location (derived, read-only) ────────────────────────────────────────────
            // The folder the shortcut itself is created in - the Shortcut table's Directory_
            // column - not the folder of the target executable. That is what the Location field
            // means in other MSI editors, e.g. [ProgramMenuFolder]FileCompare for a Start-menu entry.
            string scDir = row.Table.Columns.Contains("Directory_") ? Cv(row["Directory_"]) : "";
            var (locField, locBox) = MakeRoundedField(
                ResolveDirectoryPath(scDir), boxBg, boxBdr, valFg, false, null);
            locBox.IsReadOnly = true;
            locBox.Cursor     = System.Windows.Input.Cursors.Arrow;
            AddRow("Location", locField);

            var (argField, argBox) = MakeRoundedField(data.Arguments, boxBg, boxBdr, valFg, false, null);
            AddRow("Arguments", argField);

            var (descField, descBox) = MakeRoundedField(data.Description, boxBg, boxBdr, valFg, false, null);
            AddRow("Description", descField);

            var (wkField, wkBox) = MakeRoundedField(data.WorkingDir, boxBg, boxBdr, valFg, false,
                () => PickDirectoryKey("Select a folder", data.WorkingDir));
            AddRow("Working directory", wkField);

            var showBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            (string code, string label)[] cmds = { ("1", "Normal window"), ("3", "Maximized"), ("7", "Minimized") };
            foreach (var (code, lab) in cmds)
                showBox.Items.Add(new ComboBoxItem { Content = lab, Tag = code });
            int si = Array.FindIndex(cmds, c => c.code == data.ShowCmd);
            showBox.SelectedIndex = si >= 0 ? si : 0;
            AddRow("Window", RoundWrapControl(showBox, boxBg, boxBdr));

            var (iconField, iconBox) = MakeRoundedField(data.Icon, boxBg, boxBdr, valFg, false,
                () => PickFromPackage("Select an icon", PackageIcons(), AddIconFromDisk, IconPreview, data.Icon));
            AddRow("Icon", iconField);

            var (idxField, idxBox) = MakeRoundedField(data.IconIndex, boxBg, boxBdr, valFg, false, null);
            AddRow("Icon index", idxField);

            ShortcutData ReadControls() => new ShortcutData
            {
                Name = nameBox.Text, Target = tgtBox.Text, Arguments = argBox.Text,
                Description = descBox.Text, WorkingDir = wkBox.Text,
                Icon = iconBox.Text, IconIndex = idxBox.Text,
                ShowCmd = (showBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "1"
            };

            void Commit()
            {
                if (_scEditorLoading || _scEditNode?.ScRow == null) return;
                var d = ReadControls();
                try { WriteShortcutData(_scEditNode.ScRow, d); } catch { }
                UpdateEditCount();
                string disp = d.Name.Length > 0 ? d.Name : ScDisplayName(_scEditNode.ScRow);
                _scEditNode.Display = disp;
            }

            foreach (var b in new[] { nameBox, tgtBox, argBox, descBox, wkBox, iconBox, idxBox })
                b.LostFocus += (_, _) => Commit();
            showBox.SelectionChanged += (_, _) => Commit();

            // tgtPathBox and locBox are deliberately absent from the commit list above: both are
            // derived and read-only, so there is nothing of theirs to write back.

            // Target path follows Target as it is typed or picked.
            tgtBox.TextChanged += (_, _) =>
            {
                if (_scEditNode?.ScRow == null) return;
                tgtPathBox.Text = ShortcutTargetPath(_scEditNode.ScRow, tgtBox.Text);
            };

            // Advertise rewrites Target, because that is where the state actually lives.
            advBox.SelectionChanged += (_, _) =>
            {
                if (_scEditorLoading) return;
                bool wantAdv = ((advBox.SelectedItem as ComboBoxItem)?.Tag as string) == "Yes";
                bool isAdv   = IsFeatureName(tgtBox.Text);
                if (wantAdv == isAdv) return;

                string kp = ComponentKeyPathFile(scComp);
                string replacement = wantAdv ? FeatureForComponent(scComp)
                                             : (kp.Length > 0 ? "[#" + kp + "]" : "");

                if (replacement.Length == 0)
                {
                    // Nothing in the package to point at: a component with no KeyPath file, or one
                    // no feature publishes. Leave Target untouched and put the dropdown back rather
                    // than writing an invented value into the table.
                    _scEditorLoading = true;
                    try { advBox.SelectedIndex = isAdv ? 1 : 0; }
                    finally { _scEditorLoading = false; }
                    return;
                }

                tgtBox.Text = replacement;   // TextChanged refreshes Target path
                Commit();                    // Commit is LostFocus-driven, so do it explicitly
            };

            ScEditorHost.Content = grid;
            _scEditorLoading = false;
        }

        private void ScTree_RightDown(object sender, MouseButtonEventArgs e)
        {
            DependencyObject? d = e.OriginalSource as DependencyObject;
            while (d != null && d is not TreeViewItem) d = VisualTreeHelper.GetParent(d);
            if (d is TreeViewItem tvi) { tvi.IsSelected = true; tvi.Focus(); }
        }

        private void ScExpand_Click(object sender, RoutedEventArgs e)
        { if (SelectedSc() is { } n) SetExpanded(n, true); }

        private void ScCollapse_Click(object sender, RoutedEventArgs e)
        {
            if (SelectedSc() is not { } n) return;
            foreach (var ch in n.Children) SetExpanded(ch, false);
            n.IsExpanded = false;
        }

        // A component to offer for a new shortcut in this folder: one a shortcut here already uses,
        // else one that installs into the folder. Never creates one - the dialog asks instead, so
        // the package does not end up carrying a component that installs nothing.
        private string? ScComponentFor(DirNode node)
        {
            foreach (var r in node.Files)
                if (r.RowState != DataRowState.Deleted && r.Table.Columns.Contains("Component_"))
                { string c = Cv(r["Component_"]); if (c.Length > 0) return c; }
            return ComponentInDirectory(node.Key);
        }

        /// <summary>
        /// The component that installs the file a shortcut target points at, for a target of the
        /// form [#FileKey] or [!FileKey]. Returns "" for a feature name (an advertised shortcut) or
        /// anything else, since neither names a file to follow.
        /// </summary>
        private string ComponentForTarget(string target)
        {
            string t = (target ?? "").Trim();
            if (t.Length <= 3 || t[0] != '[' || t[^1] != ']' || (t[1] != '#' && t[1] != '!')) return "";
            var fr = FindTableRow("File", "File", t.Substring(2, t.Length - 3));
            return fr != null && fr.Table.Columns.Contains("Component_") ? Cv(fr["Component_"]) : "";
        }

        /// <summary>
        /// Returns the Directory row for a key, creating it when the package does not define one
        /// of the standard shortcut destinations.
        ///
        /// This is what makes "create a Desktop shortcut" possible in a package that never had one:
        /// an MSI only carries a DesktopFolder row if something already installs there, so without
        /// this the folder simply does not exist to attach to. The row is the standard form for
        /// these property-backed folders - parented to TARGETDIR with a DefaultDir of "." - so
        /// Windows Installer resolves it to the real Desktop at install time.
        ///
        /// Returns null for a non-standard key that does not exist, rather than inventing folders.
        /// </summary>
        private DataRow? EnsureDirectoryRow(string dirKey)
        {
            if (string.IsNullOrWhiteSpace(dirKey)) return null;

            var existing = FindTableRow("Directory", "Directory", dirKey);
            if (existing != null) return existing;

            if (!ScDestinationKeys.Contains(dirKey, StringComparer.OrdinalIgnoreCase)) return null;

            var dirSt = EnsureTableCached("Directory");
            if (dirSt == null || !dirSt.Data.Columns.Contains("Directory")) return null;

            var nr = dirSt.Data.NewRow();
            nr["Directory"] = dirKey;
            if (dirSt.Data.Columns.Contains("Directory_Parent")) nr["Directory_Parent"] = "TARGETDIR";
            if (dirSt.Data.Columns.Contains("DefaultDir"))       nr["DefaultDir"]       = ".";
            dirSt.Data.Rows.Add(nr);
            return nr;
        }

        private void ScNewShortcut_Click(object sender, RoutedEventArgs e)
        {
            var scSt = EnsureTableCached("Shortcut");
            if (scSt == null)
            { MstMessage("This MSI has no Shortcut table.", "New Shortcut", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            // The destination now comes from the dialog's Location field rather than from the tree
            // selection. A package with no shortcuts has little or nothing to select, and Desktop in
            // particular is often absent entirely, so requiring a selection made the common case
            // impossible.
            var node = SelectedScFolder();
            var seed = new ShortcutData
            {
                Name = "New Shortcut",
                Directory = node?.Key ?? "DesktopFolder",
                // Whatever is already in use here, so adding a second shortcut beside an existing
                // one needs no choice at all.
                Component = (node != null ? ScComponentFor(node) : null) ?? ""
            };

            var res = PromptShortcut("New Shortcut", seed);
            if (res == null) return;

            string dirKey = res.Directory.Length > 0 ? res.Directory : (node?.Key ?? "");
            if (EnsureDirectoryRow(dirKey) == null)
            { MstMessage($"The folder \u201C{dirKey}\u201D is not defined in this package and is not a standard shortcut location.", "New Shortcut", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            // The component comes from the dialog, and has to be one the package already has.
            // Creating one per destination folder left the package carrying a component that
            // installs nothing of its own, which is not what the shortcut belongs to.
            string comp = res.Component.Trim();
            if (comp.Length == 0) comp = ComponentInDirectory(dirKey) ?? "";
            if (comp.Length == 0)
            {
                MstMessage("Choose the component the shortcut installs with.\n\n"
                         + "Windows Installer creates a shortcut when its component installs and "
                         + "removes it when that component goes, so a shortcut has to name one. "
                         + "Choosing a target file fills it in by itself.",
                    "New Shortcut", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            if (FindTableRow("Component", "Component", comp) == null)
            {
                MstMessage($"\u201C{comp}\u201D is not a component in this package.\n\n"
                         + "Pick one from the list.",
                    "New Shortcut", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            var nr = scSt.Data.NewRow();
            string nm = res.Name.Length > 0 ? res.Name : "Shortcut";
            nr["Shortcut"] = UniqueKey(scSt.Data, "Shortcut", SanitizeKey("sc_" + nm));
            if (scSt.Data.Columns.Contains("Directory_")) nr["Directory_"] = dirKey;
            if (scSt.Data.Columns.Contains("Component_")) nr["Component_"] = comp;
            WriteShortcutData(nr, res);
            scSt.Data.Rows.Add(nr);

            UpdateEditCount();
            RebuildScTree();
            SelectScLeaf(nr);
        }

        /// <summary>
        /// Creates a subfolder of the selected shortcut destination, which is how a package gets a
        /// Start-menu group of its own: a Directory row parented to ProgramMenuFolder, with the
        /// shortcuts then pointed at it rather than at the menu root.
        ///
        /// The parent may be one of the standard destinations the package has no row for yet, so it
        /// is materialised once the name is confirmed - the same row creating a shortcut straight
        /// into that destination would make.
        /// </summary>
        private void ScNewFolder_Click(object sender, RoutedEventArgs e)
        {
            var n = SelectedScFolder();
            if (n == null)
            { MstMessage("Select the folder to create the new one inside.", "New Folder", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var dirSt = EnsureTableCached("Directory");
            if (dirSt == null || !dirSt.Data.Columns.Contains("Directory"))
            { MstMessage("This MSI has no Directory table.", "New Folder", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            // Nothing is written until the name is confirmed. Materialising the parent first meant
            // a cancelled prompt still left a new Directory row in the package.
            string? typed = PromptText("New Folder", "Name", "New Folder");
            if (string.IsNullOrWhiteSpace(typed)) return;
            string name = typed.Trim();

            if (EnsureDirectoryRow(n.Key) == null)
            {
                MstMessage($"The folder \u201C{n.Key}\u201D is not defined in this package and is "
                         + "not a standard shortcut location, so nothing can be nested inside it.",
                    "New Folder", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            string key = UniqueKey(dirSt.Data, "Directory", SanitizeKey(name));
            var nr = dirSt.Data.NewRow();
            nr["Directory"] = key;
            if (dirSt.Data.Columns.Contains("Directory_Parent")) nr["Directory_Parent"] = n.Key;
            if (dirSt.Data.Columns.Contains("DefaultDir"))       nr["DefaultDir"]       = MakeDefaultDir(name, "");
            dirSt.Data.Rows.Add(nr);

            UpdateEditCount();
            RebuildScTree();
            SelectScFolder(key);
        }

        /// <summary>Selects a folder in the shortcut tree by its Directory key, after a rebuild.</summary>
        private void SelectScFolder(string dirKey)
        {
            if (_scRoots == null || ScTree == null || dirKey.Length == 0) return;
            DirNode? Find(System.Collections.Generic.IEnumerable<DirNode> nodes)
            {
                foreach (var nd in nodes)
                {
                    if (!nd.IsShortcut && string.Equals(nd.Key, dirKey, StringComparison.OrdinalIgnoreCase)) return nd;
                    var f = Find(nd.Children);
                    if (f != null) return f;
                }
                return null;
            }
            var node = Find(_scRoots);
            if (node == null) return;
            for (var p = node.Parent; p != null; p = p.Parent) p.IsExpanded = true;
            RevealTreeNode(ScTree, node);
        }

        /// <summary>
        /// The folders a shortcut can be created in: the four standard destinations, plus any
        /// folder the package nests under one of them. Everything else in the Directory table is
        /// left out - INSTALLDIR, TARGETDIR, a generated dir* key - because a shortcut put there is
        /// one Windows never surfaces in any menu.
        ///
        /// The nested ones matter because New Folder creates exactly that: a Start-menu group of
        /// the package's own. Listing only the four would make a folder that cannot be aimed at.
        /// Each is shown as its path down from the destination, since the key alone does not say
        /// which menu it is under.
        /// </summary>
        private System.Collections.Generic.List<(string key, string display)> ScLocationKeys()
        {
            var outp = new System.Collections.Generic.List<(string key, string display)>();
            foreach (string k in ScDestinationKeys) outp.Add((k, k));

            var dirSt = EnsureTableCached("Directory");
            if (dirSt == null || !dirSt.Data.Columns.Contains("Directory")
                              || !dirSt.Data.Columns.Contains("Directory_Parent")) return outp;

            var parent = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            var label  = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (DataRow row in dirSt.Data.Rows)
            {
                if (row.RowState == DataRowState.Deleted) continue;
                string k = Cv(row["Directory"]);
                if (k.Length == 0 || parent.ContainsKey(k)) continue;
                parent[k] = Cv(row["Directory_Parent"]);
                string nm = MsiLongDirName(dirSt.Data.Columns.Contains("DefaultDir") ? Cv(row["DefaultDir"]) : "");
                label[k] = nm.Length > 0 ? nm : k;
            }

            // The path down from the destination, or "" when this folder is not under one. The hop
            // limit is what stops a Directory table that loops back on itself from spinning here.
            string PathFromDestination(string k)
            {
                string tail = "";
                for (int hops = 0; hops < 64; hops++)
                {
                    if (!parent.TryGetValue(k, out var p) || p.Length == 0) return "";
                    if (string.Equals(p, k, StringComparison.OrdinalIgnoreCase)) return "";
                    tail = tail.Length == 0 ? label[k] : label[k] + "\\" + tail;
                    if (ScDestinationKeys.Contains(p, StringComparer.OrdinalIgnoreCase)) return p + "\\" + tail;
                    k = p;
                }
                return "";
            }

            foreach (string k in parent.Keys)
            {
                if (ScDestinationKeys.Contains(k, StringComparer.OrdinalIgnoreCase)) continue;
                string path = PathFromDestination(k);
                if (path.Length > 0) outp.Add((k, path));
            }
            return outp;
        }

        /// <summary>
        /// True for a folder the package does not own: a synthetic node with no Directory row, or a
        /// Windows Installer system folder property - TARGETDIR, ProgramFilesFolder, FontsFolder,
        /// the four standard shortcut destinations and the rest. Renaming, deleting or copying one
        /// is meaningless: the key is a location Windows resolves on the target machine, not a name
        /// this package chose, so a copy would be a second name for the same place and a delete
        /// would only take the folder out of the tree. Used by both the Files and Shortcuts trees.
        /// </summary>
        private static bool IsFixedFolder(DirNode n)
            => n.DirRow == null || MsiSystemFolders.Contains(n.Key);

        /// <summary>
        /// The tree's menu is built for whatever was right-clicked, because the three kinds of node
        /// support different things:
        ///
        ///   shortcut         Rename / Delete / Copy
        ///   own folder       New Folder / New Shortcut / Rename / Delete / Copy
        ///   fixed folder     New Folder / New Shortcut / Expand / Collapse
        ///
        /// Paste joins any of them while something is on the clipboard, since a copy has to be able
        /// to land in a standard destination too - putting a shortcut on the Desktop is the whole
        /// point of copying one. Hiding rather than disabling: a menu of greyed-out entries is a
        /// menu you have to read before you can use it.
        /// </summary>
        private void ScTree_ContextMenuOpening(object sender, ContextMenuEventArgs e)
        {
            if (SelectedSc() is not { } n) { e.Handled = true; return; }   // nothing to act on

            bool ownFolder = !n.IsShortcut && !IsFixedFolder(n);
            bool groupNew  = !n.IsShortcut;                     // New Folder / New Shortcut
            bool groupEdit = n.IsShortcut || ownFolder;         // Rename / Delete / Copy
            bool groupView = !n.IsShortcut && !ownFolder;       // Expand / Collapse
            bool paste     = ScClipboardHasItem && SelectedScFolder() != null;

            static void Show(UIElement? el, bool on)
            { if (el != null) el.Visibility = on ? Visibility.Visible : Visibility.Collapsed; }

            Show(ScMenuNewFolder,   groupNew);
            Show(ScMenuNewShortcut, groupNew);
            Show(ScMenuRename,      groupEdit);
            Show(ScMenuDelete,      groupEdit);
            Show(ScMenuCopy,        groupEdit);
            Show(ScMenuPaste,       paste);
            Show(ScMenuExpand,      groupView);
            Show(ScMenuCollapse,    groupView);

            // A separator earns its place only with something visible on both sides of it.
            Show(ScMenuSep1, groupNew && (groupEdit || paste));
            Show(ScMenuSep2, (groupNew || groupEdit || paste) && groupView);
        }

        private void ScRename_Click(object sender, RoutedEventArgs e)
        {
            if (SelectedSc() is not { } n) return;

            if (n.IsShortcut && n.ScRow != null)
            {
                string? typed = PromptText("Rename Shortcut", "Name", n.Display);
                if (string.IsNullOrWhiteSpace(typed)) return;
                string name = typed.Trim();
                if (!n.ScRow.Table.Columns.Contains("Name")) return;
                // Name is a file name field, so it carries a short|long pair like one.
                n.ScRow["Name"] = FileNameField(name);
                n.Display = name;
                UpdateEditCount();
                return;
            }

            if (n.DirRow == null || IsFixedFolder(n))
            {
                MstMessage($"\u201C{n.Display}\u201D is a folder Windows Installer resolves for "
                         + "itself, so it has no name of this package's to change.",
                    "Rename", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            string? typedDir = PromptText("Rename Folder", "Name", n.Display);
            if (string.IsNullOrWhiteSpace(typedDir)) return;
            string dirName = typedDir.Trim();
            if (n.DirRow.Table.Columns.Contains("DefaultDir"))
                n.DirRow["DefaultDir"] = MakeDefaultDir(dirName, Cv(n.DirRow["DefaultDir"]));
            n.Display = dirName;
            UpdateEditCount();
        }

        private void ScDelete_Click(object sender, RoutedEventArgs e)
        {
            if (SelectedSc() is not { } n) return;

            if (n.IsShortcut && n.ScRow != null)
            {
                if (MstMessage($"Delete shortcut \u201C{n.Display}\u201D?",
                        "Delete", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
                if (n.ScRow.RowState != DataRowState.Deleted) n.ScRow.Delete();
                UpdateEditCount();
                RebuildScTree();
                return;
            }

            if (n.DirRow == null || IsFixedFolder(n))
            {
                MstMessage($"\u201C{n.Display}\u201D is a standard destination, not a folder this "
                         + "package created, so it cannot be deleted here.",
                    "Delete", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            var folders = ScFolderSubtree(n);

            // A folder something installs into is not this view's to remove: its Directory row is
            // load-bearing for a component, and deleting it would strand the files that go there.
            foreach (var d in folders)
                if (ComponentInDirectory(d.Key) is { Length: > 0 } comp)
                {
                    MstMessage($"\u201C{d.Display}\u201D is where component \u201C{comp}\u201D "
                             + "installs, so it holds more than shortcuts and cannot be deleted "
                             + "from this view.",
                        "Delete", MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }

            int scCount = 0;
            foreach (var d in folders) scCount += d.Files.Count(f => f.RowState != DataRowState.Deleted);

            string ask = scCount == 0
                ? $"Delete folder \u201C{n.Display}\u201D?"
                : scCount == 1
                ? $"Delete folder \u201C{n.Display}\u201D and the 1 shortcut in it?"
                : $"Delete folder \u201C{n.Display}\u201D and the {scCount} shortcuts in it?";
            if (MstMessage(ask, "Delete", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;

            foreach (var d in folders)
            {
                foreach (var row in d.Files)
                    if (row.RowState != DataRowState.Deleted && row.RowState != DataRowState.Detached) row.Delete();
                if (d.DirRow != null && d.DirRow.RowState != DataRowState.Deleted
                                     && d.DirRow.RowState != DataRowState.Detached) d.DirRow.Delete();
            }

            UpdateEditCount();
            RebuildScTree();
        }

        // What Copy set aside, held as the row rather than the tree node: the tree is rebuilt after
        // every edit, so a node captured now would be a dead object by the time Paste runs, while
        // the row behind it is the same row the table still holds. At most one is ever set.
        private DataRow? _scClipShortcut;
        private DataRow? _scClipFolder;

        private static bool ScClipLive(DataRow? r)
            => r != null && r.RowState != DataRowState.Deleted && r.RowState != DataRowState.Detached;

        private bool ScClipboardHasItem => ScClipLive(_scClipShortcut) || ScClipLive(_scClipFolder);

        /// <summary>
        /// Sets the item aside for Paste rather than duplicating it on the spot. Copying into the
        /// folder you copied from is one destination out of several, and it was the only one this
        /// could reach; where the copy lands is Paste's decision now.
        /// </summary>
        private void ScCopy_Click(object sender, RoutedEventArgs e)
        {
            if (SelectedSc() is not { } n) return;

            if (n.IsShortcut && n.ScRow != null)
            { _scClipShortcut = n.ScRow; _scClipFolder = null; return; }

            if (n.DirRow == null || IsFixedFolder(n))
            {
                MstMessage($"\u201C{n.Display}\u201D is a standard destination, so a copy of it "
                         + "would be a second name for the same folder.",
                    "Copy", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            _scClipFolder = n.DirRow; _scClipShortcut = null;
        }

        /// <summary>
        /// Drops what Copy set aside into the selected folder, or into the folder holding the
        /// selected shortcut. Works off the tables rather than the tree nodes, since the tree has
        /// been rebuilt since Copy ran and its nodes are no longer the ones Copy saw.
        /// </summary>
        private void ScPaste_Click(object sender, RoutedEventArgs e)
        {
            if (!ScClipboardHasItem) return;
            if (SelectedScFolder() is not { } target) return;

            var scSt  = EnsureTableCached("Shortcut");
            var dirSt = EnsureTableCached("Directory");
            if (scSt == null || dirSt == null) return;

            // The destination may be a standard folder the package has no row for yet.
            if (EnsureDirectoryRow(target.Key) == null)
            {
                MstMessage($"The folder \u201C{target.Key}\u201D is not defined in this package and "
                         + "is not a standard shortcut location, so nothing can be pasted into it.",
                    "Paste", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            DataTable scData = scSt.Data, dirData = dirSt.Data;

            if (ScClipLive(_scClipShortcut) && _scClipShortcut is { } srcSc)
            {
                var copy = scData.NewRow();
                foreach (DataColumn c in scData.Columns) copy[c.ColumnName] = srcSc[c.ColumnName];
                string name = UniqueNameIn(ScNamesIn(target.Key), ScDisplayName(srcSc));
                if (scData.Columns.Contains("Shortcut"))
                    copy["Shortcut"] = UniqueKey(scData, "Shortcut", SanitizeKey("sc_" + name));
                if (scData.Columns.Contains("Directory_")) copy["Directory_"] = target.Key;
                if (scData.Columns.Contains("Name"))       copy["Name"]       = FileNameField(name);
                scData.Rows.Add(copy);

                UpdateEditCount();
                RebuildScTree();
                SelectScLeaf(copy);
                return;
            }

            if (_scClipFolder is not { } srcDir) return;
            string srcKey = Cv(srcDir["Directory"]);

            // Pasting a folder into itself or into its own subfolder would copy forever, so the
            // destination's ancestry is walked first. Explorer refuses the same thing.
            if (ScIsSelfOrDescendant(target.Key, srcKey))
            {
                MstMessage("A folder cannot be pasted into itself or into one of its own subfolders.",
                    "Paste", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            // Rows are duplicated column for column and then given their own keys, so whatever the
            // package put on them survives the paste. Children are snapshotted before anything is
            // added, or the rows being written would be walked as if they were rows to copy.
            string PasteFolder(DataRow src, string parentKey, string name)
            {
                string key = UniqueKey(dirData, "Directory", SanitizeKey(name));
                var nr = dirData.NewRow();
                foreach (DataColumn c in dirData.Columns) nr[c.ColumnName] = src[c.ColumnName];
                nr["Directory"] = key;
                if (dirData.Columns.Contains("Directory_Parent")) nr["Directory_Parent"] = parentKey;
                if (dirData.Columns.Contains("DefaultDir"))
                    nr["DefaultDir"] = MakeDefaultDir(name, dirData.Columns.Contains("DefaultDir") ? Cv(src["DefaultDir"]) : "");
                dirData.Rows.Add(nr);

                string fromKey = Cv(src["Directory"]);
                foreach (var row in ScRowsIn(fromKey))
                {
                    var sr = scData.NewRow();
                    foreach (DataColumn c in scData.Columns) sr[c.ColumnName] = row[c.ColumnName];
                    if (scData.Columns.Contains("Shortcut"))
                        sr["Shortcut"] = UniqueKey(scData, "Shortcut", SanitizeKey("sc_" + ScDisplayName(row)));
                    // The copies live in the pasted folder, not the one they came from.
                    if (scData.Columns.Contains("Directory_")) sr["Directory_"] = key;
                    scData.Rows.Add(sr);
                }

                foreach (var child in ScChildDirRows(fromKey))
                {
                    string childName = MsiLongDirName(dirData.Columns.Contains("DefaultDir") ? Cv(child["DefaultDir"]) : "");
                    if (childName.Length == 0) childName = Cv(child["Directory"]);
                    PasteFolder(child, key, childName);
                }
                return key;
            }

            string srcName = MsiLongDirName(dirData.Columns.Contains("DefaultDir") ? Cv(srcDir["DefaultDir"]) : "");
            if (srcName.Length == 0) srcName = srcKey;
            string newKey = PasteFolder(srcDir, target.Key, UniqueNameIn(ScDirNamesIn(target.Key), srcName));

            UpdateEditCount();
            RebuildScTree();
            SelectScFolder(newKey);
        }

        /// <summary>True when dirKey is ancestorKey or sits somewhere beneath it.</summary>
        private bool ScIsSelfOrDescendant(string dirKey, string ancestorKey)
        {
            string k = dirKey;
            for (int hops = 0; hops < 64 && k.Length > 0; hops++)
            {
                if (string.Equals(k, ancestorKey, StringComparison.OrdinalIgnoreCase)) return true;
                var row = FindTableRow("Directory", "Directory", k);
                string p = row != null && row.Table.Columns.Contains("Directory_Parent") ? Cv(row["Directory_Parent"]) : "";
                if (string.Equals(p, k, StringComparison.OrdinalIgnoreCase)) return false;
                k = p;
            }
            return false;
        }

        /// <summary>Shortcut rows sitting in a folder, snapshotted so the caller can add rows.</summary>
        private System.Collections.Generic.List<DataRow> ScRowsIn(string dirKey)
        {
            var outp = new System.Collections.Generic.List<DataRow>();
            var st = EnsureTableCached("Shortcut");
            if (st == null || !st.Data.Columns.Contains("Directory_")) return outp;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Directory_"]), dirKey, StringComparison.OrdinalIgnoreCase)) outp.Add(r);
            }
            return outp;
        }

        /// <summary>Directory rows parented to a folder, snapshotted for the same reason.</summary>
        private System.Collections.Generic.List<DataRow> ScChildDirRows(string dirKey)
        {
            var outp = new System.Collections.Generic.List<DataRow>();
            var st = EnsureTableCached("Directory");
            if (st == null || !st.Data.Columns.Contains("Directory_Parent")
                           || !st.Data.Columns.Contains("Directory")) return outp;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Directory"]), dirKey, StringComparison.OrdinalIgnoreCase)) continue;
                if (string.Equals(Cv(r["Directory_Parent"]), dirKey, StringComparison.OrdinalIgnoreCase)) outp.Add(r);
            }
            return outp;
        }

        /// <summary>Shortcut names already used in a folder.</summary>
        private HashSet<string> ScNamesIn(string dirKey)
        {
            var used = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var r in ScRowsIn(dirKey)) used.Add(ScDisplayName(r));
            return used;
        }

        /// <summary>Folder names already used directly under a folder.</summary>
        private HashSet<string> ScDirNamesIn(string dirKey)
        {
            var used = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var r in ScChildDirRows(dirKey))
                used.Add(MsiLongDirName(r.Table.Columns.Contains("DefaultDir") ? Cv(r["DefaultDir"]) : ""));
            return used;
        }

        /// <summary>This folder and every folder under it, deepest last, shortcut leaves left out.</summary>
        private static System.Collections.Generic.List<DirNode> ScFolderSubtree(DirNode root)
        {
            var outp = new System.Collections.Generic.List<DirNode>();
            void Walk(DirNode d)
            {
                if (d.IsShortcut) return;
                outp.Add(d);
                foreach (var c in d.Children) Walk(c);
            }
            Walk(root);
            return outp;
        }

        /// <summary>
        /// A name none of the used ones matches, as "Name (2)", "Name (3)" and so on. Two shortcuts
        /// with one name in one folder would be two files with one path on the target machine, and
        /// the same goes for two folders.
        /// </summary>
        private static string UniqueNameIn(HashSet<string> used, string name)
        {
            if (name.Length == 0) name = "Item";
            if (!used.Contains(name)) return name;
            for (int i = 2; i < 1000; i++)
            {
                string cand = name + " (" + i + ")";
                if (!used.Contains(cand)) return cand;
            }
            return name;
        }

        // ══════════════════════════════════════════════════════════════════════════════════
        //  SHORTCUT PATH RESOLUTION
        // ══════════════════════════════════════════════════════════════════════════════════
        // The Shortcut table stores keys, not paths. Target is either a Feature name (an
        // advertised shortcut) or a formatted reference such as [#FileKey]; the folder the
        // shortcut is created in is a Directory key in Directory_. These helpers turn those keys
        // into the bracketed paths an MSI author expects to read, e.g.
        //
        //   Target        [#_7zFM.exe]
        //   Target path   [ProgramFiles64Folder]FileCompare\filecompare.exe
        //   Location      [ProgramMenuFolder]FileCompare

        /// <summary>
        /// The long name out of a DefaultDir cell. The column may hold "SHORTNM|Long Name", and may
        /// additionally carry a source name after a colon ("target:source"); only the target side
        /// matters here. "." means "same folder as the parent" and yields no segment.
        /// </summary>
        private static string MsiLongDirName(string defaultDir)
        {
            if (string.IsNullOrEmpty(defaultDir)) return "";
            int colon = defaultDir.IndexOf(':');
            string target = colon >= 0 ? defaultDir.Substring(0, colon) : defaultDir;
            int bar = target.IndexOf('|');
            string name = bar >= 0 ? target.Substring(bar + 1) : target;
            return name == "." ? "" : name;
        }

        private DataRow? FindTableRow(string table, string keyCol, string keyValue)
        {
            if (string.IsNullOrEmpty(keyValue)) return null;
            var st = EnsureTableCached(table);
            if (st == null || !st.Data.Columns.Contains(keyCol)) return null;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r[keyCol]), keyValue, StringComparison.OrdinalIgnoreCase)) return r;
            }
            return null;
        }

        /// <summary>
        /// Walks Directory_Parent up to the root and returns "[RootKey]sub\sub". The root is the
        /// last directory before TARGETDIR (or before the chain ends), which is the one that is a
        /// property resolved at install time, so it stays bracketed rather than being expanded.
        /// </summary>
        private string ResolveDirectoryPath(string dirKey)
        {
            if (string.IsNullOrWhiteSpace(dirKey)) return "";
            var segs = new System.Collections.Generic.List<string>();
            string cur = dirKey, root = dirKey;

            for (int guard = 0; guard < 64 && cur.Length > 0; guard++)
            {
                var row = FindTableRow("Directory", "Directory", cur);
                if (row == null) break;

                root = cur;
                string parent = row.Table.Columns.Contains("Directory_Parent") ? Cv(row["Directory_Parent"]) : "";
                if (parent.Length == 0 || string.Equals(parent, "TARGETDIR", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(parent, cur, StringComparison.OrdinalIgnoreCase))
                    break;   // cur is the bracketed root

                string seg = MsiLongDirName(row.Table.Columns.Contains("DefaultDir") ? Cv(row["DefaultDir"]) : "");
                if (seg.Length > 0) segs.Insert(0, seg);
                cur = parent;
            }

            string tail = string.Join("\\", segs);
            return tail.Length > 0 ? "[" + root + "]" + tail : "[" + root + "]";
        }

        /// <summary>Full bracketed path of a File-table key, or "" when it cannot be resolved.</summary>
        private string ResolveFilePath(string fileKey)
        {
            var fr = FindTableRow("File", "File", fileKey);
            if (fr == null) return "";

            string fileName = fr.Table.Columns.Contains("FileName") ? Cv(fr["FileName"]) : "";
            int bar = fileName.IndexOf('|');
            if (bar >= 0) fileName = fileName.Substring(bar + 1);

            string comp = fr.Table.Columns.Contains("Component_") ? Cv(fr["Component_"]) : "";
            var cr = FindTableRow("Component", "Component", comp);
            string dir = cr != null && cr.Table.Columns.Contains("Directory_") ? Cv(cr["Directory_"]) : "";

            string dirPath = ResolveDirectoryPath(dir);
            if (dirPath.Length == 0) return fileName;
            return fileName.Length > 0 ? dirPath + "\\" + fileName : dirPath;
        }

        /// <summary>True when the name is a row in the Feature table, which is what makes a shortcut advertised.</summary>
        private bool IsFeatureName(string name)
            => name.Length > 0 && FindTableRow("Feature", "Feature", name) != null;

        /// <summary>The File key a component uses as its KeyPath, or "" if it has none.</summary>
        private string ComponentKeyPathFile(string compKey)
        {
            var cr = FindTableRow("Component", "Component", compKey);
            if (cr == null || !cr.Table.Columns.Contains("KeyPath")) return "";
            string kp = Cv(cr["KeyPath"]);
            return FindTableRow("File", "File", kp) != null ? kp : "";
        }

        /// <summary>First feature that publishes a component, used when switching a shortcut to advertised.</summary>
        private string FeatureForComponent(string compKey)
        {
            if (compKey.Length == 0) return "";
            var st = EnsureTableCached("FeatureComponents");
            if (st == null || !st.Data.Columns.Contains("Feature_") || !st.Data.Columns.Contains("Component_"))
                return "";
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Component_"]), compKey, StringComparison.OrdinalIgnoreCase))
                    return Cv(r["Feature_"]);
            }
            return "";
        }

        /// <summary>
        /// The executable a shortcut ultimately points at, as a bracketed path.
        ///
        /// A non-advertised shortcut names the file directly ([#FileKey]). An advertised one names a
        /// feature, and the file is whatever its own component uses as a KeyPath - which is how
        /// Windows Installer resolves it at run time.
        /// </summary>
        private string ShortcutTargetPath(DataRow scRow, string target)
        {
            target = (target ?? "").Trim();

            // [#FileKey] and [!FileKey] both name a File row; they differ only in short/long form.
            if (target.Length > 3 && target[0] == '[' && target[^1] == ']'
                && (target[1] == '#' || target[1] == '!'))
            {
                string fileKey = target.Substring(2, target.Length - 3);
                string p = ResolveFilePath(fileKey);
                if (p.Length > 0) return p;
            }

            string comp = scRow.Table.Columns.Contains("Component_") ? Cv(scRow["Component_"]) : "";
            if (IsFeatureName(target) || target.Length == 0)
            {
                string kp = ComponentKeyPathFile(comp);
                if (kp.Length > 0)
                {
                    string p = ResolveFilePath(kp);
                    if (p.Length > 0) return p;
                }
            }
            return "";
        }

        private static ShortcutData ReadShortcutData(DataRow row)
        {
            string Get(string c) =>
                row.Table.Columns.Contains(c) && row[c] != DBNull.Value ? row[c].ToString() ?? "" : "";
            string nm = Get("Name");
            int bar = nm.IndexOf('|');
            return new ShortcutData
            {
                Name        = bar >= 0 ? nm.Substring(bar + 1) : nm,
                Target      = Get("Target"),
                Arguments   = Get("Arguments"),
                Description = Get("Description"),
                WorkingDir  = Get("WkDir"),
                Icon        = Get("Icon_"),
                IconIndex   = Get("IconIndex"),
                ShowCmd     = Get("ShowCmd").Length > 0 ? Get("ShowCmd") : "1"
            };
        }

        private static void WriteShortcutData(DataRow row, ShortcutData d)
        {
            void Set(string c, string v, bool required)
            {
                if (!row.Table.Columns.Contains(c)) return;
                row[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
            }
            if (row.Table.Columns.Contains("Name"))
                row["Name"] = FileNameField(d.Name.Length > 0 ? d.Name : "Shortcut");
            Set("Target",      d.Target,      true);
            Set("Arguments",   d.Arguments,   false);
            Set("Description", d.Description, false);
            Set("WkDir",       d.WorkingDir,  false);
            Set("Icon_",       d.Icon,        false);
            Set("IconIndex",   d.IconIndex,   false);
            Set("ShowCmd",     d.ShowCmd,     false);
        }

        // Shortcut editor: the common fields plus the window style. Returns null on cancel.
        private ShortcutData? PromptShortcut(string title, ShortcutData init)
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 480; win.MaxWidth = 480;

            int r = 0;
            void AddStacked(string text, FrameworkElement field, bool first = false)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, Margin = new Thickness(0, first ? 0 : 10, 0, 4)
                };
                Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0); Grid.SetColumnSpan(lbl, 2);
                cg.Children.Add(lbl); r++;

                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(field, r); Grid.SetColumn(field, 0); Grid.SetColumnSpan(field, 2);
                cg.Children.Add(field); r++;
            }

            var (nameField, nameBox) = MakeRoundedField(init.Name, boxBg, boxBdr, valFg, false, null);
            AddStacked("Name", nameField, true);

            // ── Location ─────────────────────────────────────────────────────────────────
            // The folder the shortcut is created in. Offered as a list rather than free text
            // because it must be a Directory key, and the four standard destinations are always
            // listed even when the package does not define them yet - a package with no shortcuts
            // usually has no DesktopFolder row, and that is exactly the shortcut people want to add.
            // Choosing one that is missing creates it (see EnsureDirectoryRow).
            //
            // Only shortcut destinations are offered: the four standard ones, plus any folder the
            // package nests under them (New Folder creates exactly that). Every other Directory key
            // is a place a shortcut does not belong - INSTALLDIR, TARGETDIR, a generated dir* key -
            // and putting one there produces a shortcut Windows never surfaces in any menu.
            // Whether the row already exists is not shown either: the four are always valid
            // choices, so the distinction was noise at the point of choosing.
            var locBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            var locKeys = ScLocationKeys();
            foreach (var (key, display) in locKeys)
                locBox.Items.Add(new ComboBoxItem { Content = display, Tag = key });
            int li = locKeys.FindIndex(k => string.Equals(k.key, init.Directory, StringComparison.OrdinalIgnoreCase));
            locBox.SelectedIndex = li >= 0 ? li : 0;
            AddStacked("Location (folder the shortcut is created in)", RoundWrapControl(locBox, boxBg, boxBdr));

            var (tgtField, tgtBox) = MakeRoundedField(init.Target, boxBg, boxBdr, valFg, false,
                () => PickFileFromPackage("Select a file", init.Target));
            AddStacked("Target (e.g. [#FileKey] or a feature name)", tgtField);

            // ── Advertise + Target path ─────────────────────────────────────────────────
            // Advertise is not a column of its own: a shortcut is advertised when Target names a
            // Feature rather than a file, so the dropdown reads that state out of Target and, when
            // changed, rewrites Target to match - the same thing the editor does for an existing
            // shortcut.
            //   Yes -> the feature that publishes the chosen component
            //   No  -> [#KeyPathFile] of that component
            // It is switchable here now that the dialog carries a Component field. That is what the
            // rewrite works from, and it was the missing piece that kept this read-only before.
            // Target path stays derived; both follow Target as it is typed or picked.
            bool advSyncing = false;
            var advBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            advBox.Items.Add(new ComboBoxItem { Content = "No",  Tag = "No"  });
            advBox.Items.Add(new ComboBoxItem { Content = "Yes", Tag = "Yes" });
            advBox.SelectedIndex = IsFeatureName(init.Target) ? 1 : 0;
            AddStacked("Advertise (Yes when Target names a feature)",
                       RoundWrapControl(advBox, boxBg, boxBdr));

            var (tpField, tpBox) = MakeRoundedField("", boxBg, boxBdr, valFg, false, null);
            tpBox.IsReadOnly = true;
            tpBox.Cursor     = System.Windows.Input.Cursors.Arrow;
            AddStacked("Target path", tpField);

            // ── Component ───────────────────────────────────────────────────────────────
            // Windows Installer creates a shortcut when its component installs and removes it when
            // that component goes, so every shortcut belongs to one. The package's own components
            // are listed rather than a new one being invented per destination folder: that left the
            // package carrying an empty comp_DesktopFolder that installs nothing of its own, and
            // what an author almost always wants is the component that installs the target file.
            // Picking a target therefore fills this in, unless it has already been set by hand.
            string autoComp = init.Component;
            var compBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr, Text = init.Component,
                ToolTip = "The component the shortcut is installed and uninstalled with. "
                        + "Choosing a target fills this in from the file's own component."
            };
            foreach (var (value, _) in KeysFrom("Component", "Component")) compBox.Items.Add(value);
            AddStacked("Component (the shortcut installs and uninstalls with it)",
                       RoundWrapControl(compBox, boxBg, boxBdr));

            tgtBox.TextChanged += (_, _) =>
            {
                string t = tgtBox.Text.Trim();
                bool isAdv = IsFeatureName(t);
                advSyncing = true;
                try { advBox.SelectedIndex = isAdv ? 1 : 0; }
                finally { advSyncing = false; }

                // [#FileKey] resolves straight to a file. A feature target names no file at all, so
                // the path comes from the chosen component's KeyPath, which is what Windows
                // Installer itself resolves an advertised shortcut to - and is why switching
                // Advertise to Yes no longer empties this field.
                string path = "";
                if (t.Length > 3 && t[0] == '[' && t[^1] == ']' && (t[1] == '#' || t[1] == '!'))
                    path = ResolveFilePath(t.Substring(2, t.Length - 3));
                else if (isAdv)
                {
                    string kpFile = ComponentKeyPathFile(compBox.Text.Trim());
                    if (kpFile.Length > 0) path = ResolveFilePath(kpFile);
                }
                tpBox.Text = path;

                string fileComp = ComponentForTarget(t);
                if (fileComp.Length > 0 && compBox.Text.Trim() == autoComp)
                { autoComp = fileComp; compBox.Text = fileComp; }
            };

            // Advertise rewrites Target, because that is where the state actually lives.
            advBox.SelectionChanged += (_, _) =>
            {
                if (advSyncing) return;
                bool wantAdv = ((advBox.SelectedItem as ComboBoxItem)?.Tag as string) == "Yes";
                bool isAdv   = IsFeatureName(tgtBox.Text.Trim());
                if (wantAdv == isAdv) return;

                string comp = compBox.Text.Trim();
                string kp   = ComponentKeyPathFile(comp);
                string replacement = wantAdv ? FeatureForComponent(comp)
                                             : (kp.Length > 0 ? "[#" + kp + "]" : "");

                if (replacement.Length == 0)
                {
                    // Nothing in the package for Target to name, so it is left exactly as it was
                    // and the dropdown goes back, rather than an invented value being written into
                    // the row. Which of the three reasons it is decides what to say.
                    string why = comp.Length == 0
                        ? "Choose a target or a component first.\n\n"
                        + "Advertise is stored in Target, so switching it has to rewrite Target "
                        + "from the component the shortcut installs with."
                        : wantAdv
                        ? $"No feature in this package publishes \u201C{comp}\u201D, so there is "
                        + "no feature for Target to name."
                        : $"\u201C{comp}\u201D has no KeyPath file, so there is no file for Target "
                        + "to point at.";
                    MstMessage(why, title, MessageBoxButton.OK, MessageBoxImage.Warning);

                    advSyncing = true;
                    try { advBox.SelectedIndex = isAdv ? 1 : 0; }
                    finally { advSyncing = false; }
                    return;
                }

                tgtBox.Text = replacement;   // TextChanged refreshes Target path and this dropdown
            };

            var (argField, argBox) = MakeRoundedField(init.Arguments, boxBg, boxBdr, valFg, false, null);
            AddStacked("Arguments", argField);
            var (descField, descBox) = MakeRoundedField(init.Description, boxBg, boxBdr, valFg, false, null);
            AddStacked("Description (tooltip)", descField);
            var (wkField, wkBox) = MakeRoundedField(init.WorkingDir, boxBg, boxBdr, valFg, false,
                () => PickDirectoryKey("Select a folder", init.WorkingDir));
            AddStacked("Working directory (a directory key or property)", wkField);

            var showBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            (string code, string label)[] cmds =
            {
                ("1", "Normal window"), ("3", "Maximized"), ("7", "Minimized")
            };
            foreach (var (code, lab) in cmds)
                showBox.Items.Add(new ComboBoxItem { Content = lab, Tag = code });
            int si = Array.FindIndex(cmds, c => c.code == init.ShowCmd);
            showBox.SelectedIndex = si >= 0 ? si : 0;
            AddStacked("Window", RoundWrapControl(showBox, boxBg, boxBdr));

            var (iconField, iconBox) = MakeRoundedField(init.Icon, boxBg, boxBdr, valFg, false,
                () => PickFromPackage("Select an icon", PackageIcons(), AddIconFromDisk, IconPreview, init.Icon));
            AddStacked("Icon (Icon-table key, optional)", iconField);
            var (idxField, idxBox) = MakeRoundedField(init.IconIndex, boxBg, boxBdr, valFg, false, null);
            AddStacked("Icon index (optional)", idxField);

            NdAddSpacer(cg, r++);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            ShortcutData? result = null;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () =>
                {
                    // Checked before the dialog closes, so a missing component does not cost
                    // everything else that was typed into the form.
                    if (compBox.Text.Trim().Length == 0)
                    {
                        MstMessage("Choose the component the shortcut installs with.\n\n"
                                 + "Windows Installer creates a shortcut when its component "
                                 + "installs and removes it when that component goes, so a "
                                 + "shortcut has to name one. Choosing a target file fills it in "
                                 + "by itself.",
                            title, MessageBoxButton.OK, MessageBoxImage.Warning);
                        return;
                    }
                    result = new ShortcutData
                    {
                        Name = nameBox.Text, Target = tgtBox.Text, Arguments = argBox.Text,
                        Description = descBox.Text, WorkingDir = wkBox.Text,
                        Icon = iconBox.Text, IconIndex = idxBox.Text,
                        ShowCmd = (showBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "1",
                        Directory = (locBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "",
                        Component = compBox.Text.Trim()
                    };
                    win.Close();
                }),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 0); Grid.SetColumnSpan(btns, 2); cg.Children.Add(btns);

            nameBox.Loaded += (_, _) => { nameBox.SelectAll(); nameBox.Focus(); };
            win.ShowDialog();
            return result;
        }

        // ══ Features category (feature tree + component membership + editor) ═
        private System.Collections.ObjectModel.ObservableCollection<FeatureNode>? _featRoots;
        private string _featTreeBuiltFor = "\0";
        private string? _propsComp;   // component whose editable properties are shown, else null
        private string _detailComp = "";       // component backing the detail grid (files/registry/shortcuts)
        private string _compDetailKind = "";   // "files" | "registry" | "shortcuts" | "feature"

        private sealed class FeatureData
        {
            public string Title = "", Description = "", Level = "1",
                          Display = "Expanded", Directory = "", Install = "Local";
        }

        private sealed class ComponentData
        {
            public string Directory = "", ComponentId = "", KeyPath = "", Condition = "";
            public string Location = "Local";   // Local / Source / Optional
            public bool RegKeyPath, SharedDll, Permanent, Odbc, Transitive,
                        NeverOverwrite, Bit64, DisableReflection, UninstallOnSupersede, Shared;
        }

        private sealed class CustomActionData
        {
            public string Action = "", Source = "", Target = "";
            public int BaseType = 18;          // template (code + source location)
            public string Execution = "Immediate";   // Immediate / Deferred / Rollback / Commit
            // How many times the action runs. Only meaningful for an immediate action: the same
            // two bits mean rollback and commit once the in-script bit is set, which is why the
            // control for it is disabled for anything deferred.
            public string Scheduling = "Always";     // Always / Once / OncePerProcess / ClientRepeat
            public bool Continue, Async, NoImpersonate, TSAware, Bit64, HideTarget, PatchUninstall;
        }

        private sealed class UpgradeData
        {
            public string UpgradeCode = "", VersionMin = "", VersionMax = "",
                          Language = "", ActionProperty = "", Remove = "";
            public bool MigrateFeatures, OnlyDetect, IgnoreRemoveFailure,
                        MinInclusive, MaxInclusive, LanguagesExclusive;
        }

        private void ShowFeaturesForm(TableState featSt)
        {
            if (_featRoots != null && _featTreeBuiltFor == _msiPath)
            {
                if (FeatTree != null && FeatTree.ItemsSource == null) FeatTree.ItemsSource = _featRoots;
                if (FormFeaturesPanel != null) FormFeaturesPanel.Visibility = Visibility.Visible;
                SelectFirstFeature();
                return;
            }

            var nodes = new Dictionary<string, FeatureNode>(StringComparer.OrdinalIgnoreCase);
            foreach (DataRow r in featSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string key = Cv(r["Feature"]);
                if (key.Length == 0) continue;
                nodes[key] = new FeatureNode { Key = key, ParentKey = Cv(r["Feature_Parent"]), FeatRow = r };
            }

            var roots = new System.Collections.ObjectModel.ObservableCollection<FeatureNode>();
            foreach (var node in nodes.Values)
            {
                string title = Cv(node.FeatRow!["Title"]);
                node.Display = node.Key;
                node.Subtitle = (title.Length > 0 && !string.Equals(title, node.Key, StringComparison.Ordinal)) ? title : "";
                bool isRoot = node.ParentKey.Length == 0
                    || string.Equals(node.ParentKey, node.Key, StringComparison.OrdinalIgnoreCase)
                    || !nodes.ContainsKey(node.ParentKey);
                if (!isRoot && nodes.TryGetValue(node.ParentKey, out var p) && !ReferenceEquals(p, node))
                    { p.Children.Add(node); node.Parent = p; }
                else
                    roots.Add(node);
            }

            SortFeatNodes(roots);

            // Attach each feature's components, and under each component the
            // Files / Registry Data / Shortcuts buckets (InstallShield Setup Design style).
            var featComps = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
            var fcSt0 = EnsureTableCached("FeatureComponents");
            if (fcSt0 != null)
                foreach (DataRow r in fcSt0.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string f = Cv(r["Feature_"]), c = Cv(r["Component_"]);
                    if (f.Length == 0 || c.Length == 0) continue;
                    if (!featComps.TryGetValue(f, out var lst)) { lst = new List<string>(); featComps[f] = lst; }
                    lst.Add(c);
                }
            foreach (var fn in nodes.Values)
            {
                if (!featComps.TryGetValue(fn.Key, out var comps)) continue;
                comps.Sort(StringComparer.OrdinalIgnoreCase);
                foreach (var comp in comps) fn.Children.Add(MakeComponentNode(fn, comp));
            }

            foreach (var rt in roots) rt.IsExpanded = true;
            _featRoots = roots;
            _featTreeBuiltFor = _msiPath;

            FeatTree.ItemsSource = roots;
            int total = nodes.Count;
            if (FeatCount != null) FeatCount.Text = total == 1 ? "1 feature" : $"{total} features";
            if (FormFeaturesPanel != null) FormFeaturesPanel.Visibility = Visibility.Visible;
            SelectFirstFeature();
        }

        // Auto-select the first feature so its editor shows on open; if a node is
        // already selected, just refresh its detail view.
        private void SelectFirstFeature()
        {
            if (_featRoots == null || FeatTree == null) return;
            if (FeatTree.SelectedItem is FeatureNode) { RefreshFeatSelection(); return; }
            var first = _featRoots.FirstOrDefault();
            if (first == null) { ClearDetail(); if (FeatCompTitle != null) FeatCompTitle.Text = "Select a feature"; return; }
            RevealTreeNode(FeatTree, first);
        }

        private static void SortFeatNodes(System.Collections.ObjectModel.ObservableCollection<FeatureNode> list)
        {
            var ordered = list.OrderBy(n => n.Display, StringComparer.OrdinalIgnoreCase).ToList();
            list.Clear();
            foreach (var n in ordered) { SortFeatNodes(n.Children); list.Add(n); }
        }

        private FeatureNode? SelectedFeat() => FeatTree?.SelectedItem as FeatureNode;

        private static FeatureNode? NearestFeature(FeatureNode? n)
        {
            while (n != null && n.Kind != FeatNodeKind.Feature) n = n.Parent;
            return n;
        }

        private static FeatureNode MakeComponentNode(FeatureNode feature, string comp)
        {
            var cnode = new FeatureNode { Kind = FeatNodeKind.Component, ComponentKey = comp, Display = comp, Parent = feature };
            cnode.Children.Add(new FeatureNode { Kind = FeatNodeKind.FilesCat,     ComponentKey = comp, Display = "Files",         Parent = cnode });
            cnode.Children.Add(new FeatureNode { Kind = FeatNodeKind.RegistryCat,  ComponentKey = comp, Display = "Registry Data", Parent = cnode });
            cnode.Children.Add(new FeatureNode { Kind = FeatNodeKind.ShortcutsCat, ComponentKey = comp, Display = "Shortcuts",     Parent = cnode });
            return cnode;
        }

        private void FeatTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is FeatureNode node) ShowFeatNode(node);
            else { ClearDetail(); if (FeatCompTitle != null) FeatCompTitle.Text = "Select a feature"; }
        }

        private void ClearDetail()
        {
            _propsComp = null;
            ShowGridView();
            if (FeatCompList == null) return;
            FeatCompList.Columns.Clear();
            FeatCompList.ItemsSource = null;
        }

        private void RefreshFeatSelection()
        {
            if (FeatTree?.SelectedItem is FeatureNode node) ShowFeatNode(node);
            else ClearDetail();
        }

        private void ShowFeatNode(FeatureNode node)
        {
            switch (node.Kind)
            {
                case FeatNodeKind.Feature:      ShowFeatureEditor(node);                                  break;
                case FeatNodeKind.Component:    ShowComponentForm(node.ComponentKey);                     break;
                case FeatNodeKind.FilesCat:     ShowGridView(); ShowComponentFiles(node.ComponentKey);     break;
                case FeatNodeKind.RegistryCat:  ShowComponentRegistry(node.ComponentKey);  break;
                case FeatNodeKind.ShortcutsCat: ShowComponentShortcuts(node.ComponentKey); break;
            }
        }

        // Toggle the component detail area between the read-only grid (feature
        // summary / files / registry / shortcuts) and the editable component form.
        // The registry and shortcut trees share one slot beside the detail grid rather than
        // replacing it, so the slot is shown and hidden by collapsing its column. "" hides both.
        private void SetFeatSideTree(string kind)
        {
            bool reg = kind == "registry";
            bool sc  = kind == "shortcuts";
            bool on  = reg || sc;

            if (FeatSideCol != null)      FeatSideCol.Width      = new GridLength(on ? 250 : 0);
            if (FeatSideSplitCol != null) FeatSideSplitCol.Width = new GridLength(on ? 4 : 0);
            if (FeatSideSplit != null) FeatSideSplit.Visibility = on  ? Visibility.Visible : Visibility.Collapsed;
            if (FeatRegTree != null)   FeatRegTree.Visibility   = reg ? Visibility.Visible : Visibility.Collapsed;
            if (FeatScTree != null)    FeatScTree.Visibility    = sc  ? Visibility.Visible : Visibility.Collapsed;
        }

        private void ShowGridView()
        {
            SetFeatSideTree("");
            if (FeatCompForm != null) FeatCompForm.Visibility = Visibility.Collapsed;
            if (FeatFeatureForm != null) FeatFeatureForm.Visibility = Visibility.Collapsed;
            if (FeatCompList != null) FeatCompList.Visibility = Visibility.Visible;
        }

        // The grid with a tree beside it (fourth state of the detail area).
        private void ShowSideTreeView(string kind)
        {
            if (FeatCompForm != null) FeatCompForm.Visibility = Visibility.Collapsed;
            if (FeatFeatureForm != null) FeatFeatureForm.Visibility = Visibility.Collapsed;
            if (FeatCompList != null) FeatCompList.Visibility = Visibility.Visible;
            SetFeatSideTree(kind);
        }

        private void ShowRegTreeView() => ShowSideTreeView("registry");
        private void ShowScTreeView()  => ShowSideTreeView("shortcuts");

        private void ShowFormView()
        {
            SetFeatSideTree("");
            if (FeatCompList != null) FeatCompList.Visibility = Visibility.Collapsed;
            if (FeatFeatureForm != null) FeatFeatureForm.Visibility = Visibility.Collapsed;
            if (FeatCompForm != null) FeatCompForm.Visibility = Visibility.Visible;
        }

        // Show the inline editable feature form (third state of the detail area).
        private void ShowFeatFormView()
        {
            SetFeatSideTree("");
            if (FeatCompList != null) FeatCompList.Visibility = Visibility.Collapsed;
            if (FeatCompForm != null) FeatCompForm.Visibility = Visibility.Collapsed;
            if (FeatFeatureForm != null) FeatFeatureForm.Visibility = Visibility.Visible;
        }

        // Rebuild the detail grid's columns to match the content being shown.
        private void SetDetailColumns(params (string header, string bind, double star)[] cols)
        {
            if (FeatCompList == null) return;
            FeatCompList.Columns.Clear();
            foreach (var (header, bind, star) in cols)
                FeatCompList.Columns.Add(new DataGridTextColumn
                {
                    Header = header,
                    Binding = new System.Windows.Data.Binding(bind),
                    Width = new DataGridLength(star, DataGridLengthUnitType.Star)
                });
        }

        // Flag each file/registry row that is its component's KeyPath, so the grid can
        // show a key-path icon on that row (the same idea as InstallShield's key column).
        private void MarkKeyPathFiles(System.Collections.Generic.IEnumerable<FileRow> rows)
        {
            var info = ComponentInfoMap();
            foreach (var fr in rows)
                fr.IsKeyPath = info.TryGetValue(fr.Component, out var ci)
                               && ci.key.Length > 0 && string.Equals(ci.key, fr.Key, StringComparison.Ordinal);
        }

        private void MarkKeyPathReg(System.Collections.Generic.IEnumerable<RegValueRow> rows)
        {
            var info = ComponentInfoMap();
            foreach (var rv in rows)
                rv.IsKeyPath = info.TryGetValue(rv.Component, out var ci)
                               && ci.key.Length > 0 && string.Equals(ci.key, rv.Key, StringComparison.Ordinal);
        }

        // Component -> (Directory, KeyPath), built fresh from the cached Component table.
        private Dictionary<string, (string dir, string key)> ComponentInfoMap()
        {
            var map = new Dictionary<string, (string, string)>(StringComparer.OrdinalIgnoreCase);
            var compSt = EnsureTableCached("Component");
            if (compSt != null)
                foreach (DataRow r in compSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string c = Cv(r["Component"]);
                    if (c.Length > 0) map[c] = (Cv(r["Directory_"]), Cv(r["KeyPath"]));
                }
            return map;
        }

        private DataRow? _featEditRow;
        private FeatureNode? _featEditNode;
        private bool _featEditorLoading;

        // Inline editable feature form, shown in the third column when a feature is
        // selected (replaces the old "Edit Feature" popup). Compact label-beside-field
        // layout; text fields commit on focus loss, combos commit immediately.
        private void ShowFeatureEditor(FeatureNode node)
        {
            if (FeatFeatureForm == null || node.FeatRow == null) { ShowGridView(); ShowFeatureSummary(node); return; }
            _featEditorLoading = true;
            _featEditNode = node;
            _featEditRow = node.FeatRow;
            var data = ReadFeatureData(node.FeatRow);

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")      as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")   as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(96) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            TextBlock Lbl(string t) => new TextBlock
            {
                Text = t, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
            };
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = Lbl(label);
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }
            ComboBox Combo((string tag, string label)[] opts, string sel)
            {
                var cb = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
                };
                foreach (var (tag, label) in opts)
                    cb.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
                int si = Array.FindIndex(opts, o => o.tag == sel);
                cb.SelectedIndex = si >= 0 ? si : 0;
                return cb;
            }

            var (titleField, titleBox) = MakeRoundedField(data.Title, boxBg, boxBdr, valFg, false, null);
            AddRow("Title", titleField);
            var (descField, descBox) = MakeRoundedField(data.Description, boxBg, boxBdr, valFg, false, null);
            AddRow("Description", descField);
            var (lvlField, lvlBox) = MakeRoundedField(data.Level, boxBg, boxBdr, valFg, false, null);
            AddRow("Install level", lvlField);
            var visCombo = Combo(new[] { ("Hidden", "Hidden"), ("Collapsed", "Collapsed"), ("Expanded", "Expanded") }, data.Display);
            AddRow("Visibility", RoundWrapControl(visCombo, boxBg, boxBdr));
            var (dirField, dirBox) = MakeRoundedField(data.Directory, boxBg, boxBdr, valFg, false,
                () => PickDirectoryKey("Select a folder", data.Directory));
            AddRow("Directory", dirField);
            var instCombo = Combo(new[]
            {
                ("Local", "Install locally"), ("Source", "Run from source"), ("Advertise", "Advertised (install on demand)")
            }, data.Install);
            AddRow("Install option", RoundWrapControl(instCombo, boxBg, boxBdr));

            FeatureData ReadControls() => new FeatureData
            {
                Title = titleBox.Text, Description = descBox.Text, Level = lvlBox.Text,
                Directory = dirBox.Text,
                Display = (visCombo.SelectedItem as ComboBoxItem)?.Tag as string ?? "Expanded",
                Install = (instCombo.SelectedItem as ComboBoxItem)?.Tag as string ?? "Local"
            };

            void Commit()
            {
                if (_featEditorLoading || _featEditRow == null) return;
                var d = ReadControls();
                try { WriteFeatureData(_featEditRow, d); } catch { }
                UpdateEditCount();
                if (_featEditNode != null)
                    _featEditNode.Subtitle = (d.Title.Length > 0 && !string.Equals(d.Title, _featEditNode.Key, StringComparison.Ordinal)) ? d.Title : "";
            }

            foreach (var b in new[] { titleBox, descBox, lvlBox, dirBox })
                b.LostFocus += (_, _) => Commit();
            visCombo.SelectionChanged  += (_, _) => Commit();
            instCombo.SelectionChanged += (_, _) => Commit();

            FeatFeatureForm.Content = grid;
            if (FeatCompTitle != null)
                FeatCompTitle.Text = (node.Display.Length > 0 ? node.Display : node.Key) + "  ·  feature";
            ShowFeatFormView();
            _featEditorLoading = false;
        }

        private void ShowFeatureSummary(FeatureNode node)
        {
            _propsComp = null; _detailComp = ""; _compDetailKind = "feature";
            SetDetailColumns(("Component", "C0", 1.2), ("Directory", "C1", 1), ("Key Path", "C2", 1.4));
            var info = ComponentInfoMap();
            var fcSt = EnsureTableCached("FeatureComponents");
            var rows = new System.Collections.Generic.List<SetupRow>();
            if (fcSt != null)
                foreach (DataRow r in fcSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (!string.Equals(Cv(r["Feature_"]), node.Key, StringComparison.OrdinalIgnoreCase)) continue;
                    string comp = Cv(r["Component_"]);
                    var (dir, kp) = info.TryGetValue(comp, out var v) ? v : ("", "");
                    rows.Add(new SetupRow(comp, dir, kp));
                }
            if (FeatCompList != null) FeatCompList.ItemsSource = rows;
            string head = node.Subtitle.Length > 0 ? node.Subtitle : node.Display;
            if (FeatCompTitle != null) FeatCompTitle.Text = $"{head}  ·  {rows.Count} component(s)";
        }

        private void ShowComponentProperties(string comp)
        {
            SetDetailColumns(("Property", "C0", 1), ("Value", "C1", 1.6));
            var rows = new System.Collections.Generic.List<SetupRow>();
            var compSt = EnsureTableCached("Component");
            DataRow? cr = null;
            if (compSt != null)
                foreach (DataRow r in compSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (string.Equals(Cv(r["Component"]), comp, StringComparison.OrdinalIgnoreCase)) { cr = r; break; }
                }
            if (cr != null)
            {
                static string YN(bool b) => b ? "Yes" : "No";
                int attr = int.TryParse(Cv(cr["Attributes"]), out var a) ? a : 0;
                // Run-from bits: 1 = source, 2 = optional (either), else local.
                string location = (attr & 2) != 0 ? "Optional (local or source)"
                                : (attr & 1) != 0 ? "Run from source" : "Run local";

                string destKey = Cv(cr["Directory_"]);
                rows.Add(new SetupRow("Destination", destKey));
                rows.Add(new SetupRow("Destination path", DirectoryKeyPath(destKey)));
                rows.Add(new SetupRow("Component GUID", Cv(cr["ComponentId"])));
                rows.Add(new SetupRow("Key path", Cv(cr["KeyPath"])));
                rows.Add(new SetupRow("Condition", Cv(cr["Condition"])));
                rows.Add(new SetupRow("Install location", location));
                rows.Add(new SetupRow("Permanent", YN((attr & 16) != 0)));
                rows.Add(new SetupRow("Never overwrite", YN((attr & 128) != 0)));
                rows.Add(new SetupRow("64-bit", YN((attr & 256) != 0)));
                rows.Add(new SetupRow("Uninstall on supersedence", YN((attr & 1024) != 0)));
                rows.Add(new SetupRow("Shared component", YN((attr & 2048) != 0)));
                rows.Add(new SetupRow("Attributes (raw value)", attr.ToString()));
            }
            _propsComp = comp;
            if (FeatCompList != null) FeatCompList.ItemsSource = rows;
            if (FeatCompTitle != null) FeatCompTitle.Text = $"{comp}  ·  component";
        }

        private void ShowComponentFiles(string comp)
        {
            _propsComp = null; _detailComp = comp; _compDetailKind = "files";
            SetDetailColumns(("Name", "C0", 1.4), ("Size", "C1", 0.6), ("Destination", "C2", 1), ("Key", "C3", 1));
            ComponentInfoMap().TryGetValue(comp, out var ci);
            string dest = ci.dir ?? ""; string keyPath = ci.key ?? "";
            var rows = new System.Collections.Generic.List<SetupRow>();
            var fSt = EnsureTableCached("File");
            if (fSt != null)
                foreach (DataRow r in fSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (!string.Equals(Cv(r["Component_"]), comp, StringComparison.OrdinalIgnoreCase)) continue;
                    string fileKey = Cv(r["File"]);
                    string fn = Cv(r["FileName"]); int b = fn.IndexOf('|');
                    string lng = b >= 0 ? fn.Substring(b + 1) : fn;
                    string nm = lng.Length > 0 ? lng : fileKey;
                    bool isKey = keyPath.Length > 0 && string.Equals(fileKey, keyPath, StringComparison.OrdinalIgnoreCase);
                    rows.Add(new SetupRow((isKey ? "🔑 " : "") + nm, FmtSize(Cv(r["FileSize"])), dest, fileKey) { Row = r });
                }
            if (FeatCompList != null) FeatCompList.ItemsSource = rows;
            if (FeatCompTitle != null) FeatCompTitle.Text = $"{comp}  ·  {rows.Count} file(s)";
        }

        // The component-scoped registry tree shown beside the value list, and which of its keys
        // is currently narrowing that list (null = every value in the component).
        private System.Collections.ObjectModel.ObservableCollection<RegNode>? _featRegRoots;

        /// <summary>
        /// A component's registry data as a hive-and-key tree with the values beside it, the way a
        /// registry editor shows it, rather than one flat list of every value in the component.
        /// The value list is the same grid the other component views use, so Set Keypath and
        /// Delete Value keep working on it unchanged.
        /// </summary>
        private void ShowComponentRegistry(string comp)
        {
            _propsComp = null; _detailComp = comp; _compDetailKind = "registry";
            SetDetailColumns(("Name", "C0", 1), ("Type", "C1", 0.8), ("Data", "C2", 1.6));

            var rSt = EnsureTableCached("Registry");
            _featRegRoots = rSt == null
                ? new System.Collections.ObjectModel.ObservableCollection<RegNode>()
                : BuildRegRoots(rSt, comp, out _);

            // Counted off the tree rather than taken from the build, so the header follows the same
            // rule the grid does. The build's own tally is every Registry row it placed, and a key
            // operation marker is one of those without being a value the grid can show.
            int total = 0;
            foreach (var h in _featRegRoots) total += CountRegRows(h);

            // Start collapsed, expand on demand - the same as the Registry category. Opening the
            // path to every key that holds a value sounded helpful and, on a package like VLC that
            // writes into a dozen keys, unfolded the whole tree at once.
            foreach (var h in _featRegRoots) h.IsExpanded = false;

            if (FeatRegTree != null)
            {
                // The same menu object, not a copy: the two trees offer identical actions, and the
                // handlers already work on whichever tree is on screen. Sharing it also keeps the
                // x:Name'd items (Rename, Delete, Permissions) in the page's namescope, which a
                // menu declared in a resource dictionary would not be.
                if (FeatRegTree.ContextMenu == null && RegTree != null)
                    FeatRegTree.ContextMenu = RegTree.ContextMenu;

                FeatRegTree.ItemsSource = null;
                FeatRegTree.ItemsSource = _featRegRoots;
            }
            ShowRegTreeView();

            // Nothing selected, so nothing in the grid. Selecting a key for the user would mean
            // expanding the tree down to it, which is the thing being avoided here.
            FillComponentRegistry(comp, null, total);
        }

        /// <summary>
        /// Fills the value list with the selected key's own values, and with nothing at all when no
        /// key is selected.
        ///
        /// It used to list every value in the component when nothing was selected, and everything
        /// at or under a key when something was. Both meant values appeared beside a key that does
        /// not hold them - the two DefaultUpdatesPeriod / DefaultCollectUsage rows live in
        /// WinSCP 2, and were showing against SOFTWARE and against no key at all. A value is shown
        /// against the key that writes it, or not shown.
        ///
        /// A Registry row named "+", "-" or "*" is the key-operation marker for the key itself
        /// rather than a value under it, so it stays out of the grid and out of the count. The tree
        /// node already represents that key, and the row has nothing to edit.
        /// </summary>
        private void FillComponentRegistry(string comp, RegNode? scope, int totalWhenUnscoped)
        {
            ComponentInfoMap().TryGetValue(comp, out var ci);
            string keyPath = ci.key ?? "";

            var rows = new System.Collections.Generic.List<SetupRow>();
            foreach (var r in scope?.Values ?? Enumerable.Empty<DataRow>())
            {
                if (r.RowState == DataRowState.Deleted || IsRegKeyOp(r)) continue;
                string regPk = Cv(r["Registry"]);
                string name = Cv(r["Name"]);
                string nameDisp = name.Length == 0 ? "(Default)" : name;
                var (typeDisp, d) = DecodeRegValue(Cv(r["Value"]));
                string dataDisp = d.Replace("\n", "  \u00B7  ");
                bool isKey = keyPath.Length > 0 && string.Equals(regPk, keyPath, StringComparison.OrdinalIgnoreCase);
                rows.Add(new SetupRow((isKey ? "\uD83D\uDD11 " : "") + nameDisp, typeDisp, dataDisp) { Row = r });
            }

            if (FeatCompList != null) FeatCompList.ItemsSource = rows;
            if (FeatCompTitle != null)
                FeatCompTitle.Text =
                      scope != null           ? $"{comp}  \u00B7  {RootHiveName(scope.Root)}"
                                                + (scope.FullPath.Length > 0 ? "\\" + scope.FullPath : "")
                                                + $"  \u00B7  {rows.Count} value(s)"
                    : totalWhenUnscoped == 0  ? $"{comp}  \u00B7  no registry values"
                    :                           $"{comp}  \u00B7  {totalWhenUnscoped} registry value(s)"
                                                + "  \u00B7  select a key to see them";
        }

        private void FeatRegTree_SelectionChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (_compDetailKind != "registry" || _detailComp.Length == 0) return;
            var node = FeatRegTree?.SelectedItem as RegNode;
            int total = 0;
            if (_featRegRoots != null) foreach (var h in _featRegRoots) total += CountRegRows(h);
            FillComponentRegistry(_detailComp, node, total);
        }

        /// <summary>
        /// A Registry row that marks an operation on the key itself rather than a value under it.
        /// The one rule, shared by the grid and the counts that label it, so a header can never
        /// promise a row the grid does not show.
        /// </summary>
        private static bool IsRegKeyOp(DataRow r)
        {
            if (r.RowState == DataRowState.Deleted || r.RowState == DataRowState.Detached) return false;
            if (!r.Table.Columns.Contains("Name")) return false;
            string n = Cv(r["Name"]);
            return n == "+" || n == "-" || n == "*";
        }

        private static int CountRegRows(RegNode n)
        {
            int c = 0;
            foreach (var r in n.Values)
                if (r.RowState != DataRowState.Deleted && !IsRegKeyOp(r)) c++;
            foreach (var k in n.Children) c += CountRegRows(k);
            return c;
        }

        // The component-scoped shortcut tree shown beside the value list.
        private System.Collections.ObjectModel.ObservableCollection<DirNode>? _featScRoots;

        /// <summary>
        /// A component's shortcuts as a destination-folder tree with the list beside it, the same
        /// shape the Shortcuts category uses. The list is the shared detail grid, so nothing that
        /// reads it has to change.
        /// </summary>
        private void ShowComponentShortcuts(string comp)
        {
            _propsComp = null; _detailComp = comp; _compDetailKind = "shortcuts";
            SetDetailColumns(("Name", "C0", 1), ("Target", "C1", 1.4), ("Arguments", "C2", 1));

            var sSt = EnsureTableCached("Shortcut");
            int total = 0;
            _featScRoots = sSt == null
                ? new System.Collections.ObjectModel.ObservableCollection<DirNode>()
                : BuildScRoots(sSt, comp, out total);

            if (FeatScTree != null)
            {
                // The same menu object as the Shortcuts category tree, for the reasons given on
                // the registry tree: identical actions, and x:Name'd items stay in this namescope.
                if (FeatScTree.ContextMenu == null && ScTree != null)
                    FeatScTree.ContextMenu = ScTree.ContextMenu;

                FeatScTree.ItemsSource = null;
                FeatScTree.ItemsSource = _featScRoots;
            }
            ShowScTreeView();
            FillComponentShortcuts(comp, null, total);
        }

        private static void CollectScRows(DirNode n, System.Collections.Generic.List<DataRow> into)
        {
            foreach (var r in n.Files) if (r.RowState != DataRowState.Deleted) into.Add(r);
            foreach (var c in n.Children) if (!c.IsShortcut) CollectScRows(c, into);
        }

        /// <summary>
        /// Fills the list: every shortcut in the component when nothing is selected, the one
        /// shortcut when a leaf is selected, otherwise everything in the selected folder.
        /// </summary>
        private void FillComponentShortcuts(string comp, DirNode? scope, int totalWhenUnscoped)
        {
            var source = new System.Collections.Generic.List<DataRow>();
            if (scope != null && scope.IsShortcut)
            { if (scope.ScRow != null) source.Add(scope.ScRow); }
            else if (scope != null) CollectScRows(scope, source);
            else if (_featScRoots != null) foreach (var r in _featScRoots) CollectScRows(r, source);

            var rows = new System.Collections.Generic.List<SetupRow>();
            foreach (var r in source)
            {
                string nm = Cv(r["Name"]); int b = nm.IndexOf('|');
                string lng = b >= 0 ? nm.Substring(b + 1) : nm;
                rows.Add(new SetupRow(lng, Cv(r["Target"]), Cv(r["Arguments"])) { Row = r });
            }

            if (FeatCompList != null) FeatCompList.ItemsSource = rows;
            if (FeatCompTitle != null)
                FeatCompTitle.Text = scope == null
                    ? $"{comp}  ·  {totalWhenUnscoped} shortcut(s)"
                    : $"{comp}  ·  {scope.Display}  ·  {rows.Count} shortcut(s)";
        }

        private void FeatScTree_SelectionChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (_compDetailKind != "shortcuts" || _detailComp.Length == 0) return;
            int total = 0;
            if (_featScRoots != null) foreach (var r in _featScRoots) total += CountScRows(r);
            FillComponentShortcuts(_detailComp, FeatScTree?.SelectedItem as DirNode, total);
        }

        private static int CountScRows(DirNode n)
        {
            int c = 0;
            foreach (var r in n.Files) if (r.RowState != DataRowState.Deleted) c++;
            foreach (var k in n.Children) if (!k.IsShortcut) c += CountScRows(k);
            return c;
        }


        // Right-click selects the row under the cursor so the menu acts on it.
        private void FeatCompList_RightDown(object sender, MouseButtonEventArgs e)
        {
            DependencyObject? d = e.OriginalSource as DependencyObject;
            while (d != null && d is not DataGridRow) d = VisualTreeHelper.GetParent(d);
            if (d is DataGridRow row)
            { row.IsSelected = true; if (FeatCompList != null) FeatCompList.SelectedItem = row.Item; }
        }

        // The detail grid is shared, so the file/registry actions only apply in the
        // Files and Registry views; elsewhere (feature summary, shortcuts) suppress
        // the menu. Labels adapt to the view.
        private void FeatCompList_MenuOpening(object sender, ContextMenuEventArgs e)
        {
            bool files = _compDetailKind == "files";
            bool reg   = _compDetailKind == "registry";
            if (!files && !reg) { e.Handled = true; return; }
            if (FeatCompList?.SelectedItem is not SetupRow) { e.Handled = true; return; }

            if (MiCompDelete != null) MiCompDelete.Header = files ? "Delete File" : "Delete Value";
        }

        private void CompSetKeyPath_Click(object sender, RoutedEventArgs e)
        {
            if (FeatCompList?.SelectedItem is not SetupRow sr || sr.Row == null || _detailComp.Length == 0) return;
            var cr = ComponentRow(_detailComp);
            if (cr == null || !cr.Table.Columns.Contains("KeyPath"))
            { MstMessage("The Component table has no KeyPath column.", "Set Keypath", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            bool reg = _compDetailKind == "registry";
            string key = reg ? Cv(sr.Row["Registry"]) : Cv(sr.Row["File"]);
            if (key.Length == 0) return;

            if (Cv(cr["KeyPath"]) == key)
            { TxtStatus.Text = $"{key} is already the key path for {_detailComp}."; return; }

            if (!ConfirmReplaceKeyPath(cr, "Set Keypath")) return;

            cr["KeyPath"] = key;
            if (cr.Table.Columns.Contains("Attributes"))
            {
                int a = int.TryParse(Cv(cr["Attributes"]), out var av) ? av : 0;
                if (reg) a |= 4; else a &= ~4;   // registry-keypath attribute bit
                cr["Attributes"] = a.ToString();
            }
            UpdateEditCount();
            if (reg) ShowComponentRegistry(_detailComp); else ShowComponentFiles(_detailComp);
            TxtStatus.Text = $"Key path for {_detailComp} set to {key}.";
        }

        private void CompDelete_Click(object sender, RoutedEventArgs e)
        {
            if (FeatCompList?.SelectedItem is not SetupRow sr || sr.Row == null) return;
            bool files = _compDetailKind == "files";
            bool reg   = _compDetailKind == "registry";
            if (!files && !reg) return;

            string label;
            if (files)
            {
                string fn = Cv(sr.Row["FileName"]); int b = fn.IndexOf('|');
                label = b >= 0 ? fn.Substring(b + 1) : fn;
            }
            else
            {
                string nm = Cv(sr.Row["Name"]);
                label = nm.Length == 0 ? "(Default)" : nm;
            }

            if (MstMessage($"Delete {(files ? "file" : "registry value")} \u201C{label}\u201D?",
                    files ? "Delete File" : "Delete Value", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;

            if (sr.Row.RowState != DataRowState.Deleted) sr.Row.Delete();
            UpdateEditCount();
            if (files) ShowComponentFiles(_detailComp); else ShowComponentRegistry(_detailComp);
            TxtStatus.Text = files ? "Deleted file." : "Deleted registry value.";
        }

        private static string FmtSize(string raw)
        {
            if (!long.TryParse(raw, out long b) || b < 0) return "";
            string[] u = { "B", "KB", "MB", "GB", "TB" };
            double v = b; int i = 0;
            while (v >= 1024 && i < u.Length - 1) { v /= 1024; i++; }
            return i == 0 ? $"{b} B" : $"{v:0.#} {u[i]}";
        }

        // ══ Custom actions (list + decoded detail + editor) ═════════════════
        // CustomAction.Type packs the code kind, the source location, the
        // scheduling, and option flags into one integer; these decode it.
        // The label is the wording the New menu uses for the same thing, so an action reads back as
        // what was picked to create it. They used to differ - the menu offered "Stored in Binary
        // table" and the editor called the result "(from Binary)" - which left nothing in the
        // editor to match against the entry the action came from.
        private static readonly (int baseType, string label, string sourceKind)[] CaTemplates =
        {
            (2,  "EXE - command line (stored in Binary table)",       "Binary"),
            (18, "EXE - command line (installed with product)",       "File"),
            (34, "EXE - command line (path referencing a directory)", "Directory"),
            (50, "EXE - command line (path in property value)",       "Property"),
            (1,  "DLL function (stored in Binary table)",             "Binary"),
            (17, "DLL function (installed with product)",             "File"),
            (5,  "JScript (stored in Binary table)",                  "Binary"),
            (21, "JScript (installed with product)",                  "File"),
            (37, "JScript (stored in custom action)",                 "None"),
            (53, "JScript (stored in property value)",                "Property"),
            (6,  "VBScript (stored in Binary table)",                 "Binary"),
            (22, "VBScript (installed with product)",                 "File"),
            (38, "VBScript (stored in custom action)",                "None"),
            (54, "VBScript (stored in property value)",               "Property"),
            (51, "Set property",                                      "Property"),
            (35, "Set directory",                                     "Directory"),
            (19, "Display error / abort",                             "None"),
            // The three nested-install variants, the way the reference tools split them. None of
            // the three sources is a table this editor can pick from: a substorage name, a path
            // relative to the source media, and a ProductCode respectively.
            (7,  "Nested install (inside this package)",              "None"),
            (23, "Nested install (on source location)",               "None"),
            (39, "Nested install (advertised or installed)",          "None"),
        };

        private static string CaTemplateLabel(int baseType)
        {
            foreach (var t in CaTemplates) if (t.baseType == baseType) return t.label;
            return $"Type {baseType}";
        }

        private static string CaSourceKind(int baseType)
        {
            foreach (var t in CaTemplates) if (t.baseType == baseType) return t.sourceKind;
            return "";
        }

        private static string CaExecution(int type) =>
            (type & 0x400) != 0
                ? ((type & 0x100) != 0 ? "Deferred (rollback)"
                 : (type & 0x200) != 0 ? "Deferred (commit)" : "Deferred")
                : "Immediate";

        private static string CaKindShort(int type)
        {
            string s = CaTemplateLabel(type & 0x3F);
            string exec = CaExecution(type);
            return exec == "Immediate" ? s : s + "  ·  " + exec.ToLowerInvariant();
        }

        private TableState? _caSt;

        private void ShowCustomActionsForm(TableState caSt)
        {
            _caSt = caSt;
            var items = new List<CaItem>();
            foreach (DataRow r in caSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string action = Cv(r["Action"]);
                if (action.Length == 0) continue;
                int type = int.TryParse(Cv(r["Type"]), out var v) ? v : 0;
                items.Add(new CaItem(r, action, CaKindShort(type)));
            }
            items.Sort((a, b) => string.Compare(a.Action, b.Action, StringComparison.OrdinalIgnoreCase));

            // One "Custom Actions" root with the actions under it, the way the reference tools
            // show them. The root is what carries the New menu.
            var root = new CaItem(null, "Custom Actions",
                items.Count == 1 ? "1 action" : $"{items.Count} actions")
            { IsRoot = true, IsExpanded = true };
            foreach (var it in items) root.Children.Add(it);
            _caAll = root.Children;

            if (CaList != null)
                CaList.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<CaItem> { root };
            if (CaCount != null) CaCount.Text = root.Kind;
            ApplyCaFind();
            ClearCaEditor();
            if (FormCustomActionsPanel != null) FormCustomActionsPanel.Visibility = Visibility.Visible;
            if (root.Children.Count > 0) root.Children[0].IsSelected = true;
        }

        private void CaTree_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (e.NewValue is CaItem it && !it.IsRoot && it.Row != null) ShowCaEditor(it.Row);
            else ClearCaEditor();
        }

        /// <summary>
        /// The menu is two menus sharing one surface: the root (or empty space) offers only the
        /// ways to create an action, an action offers only Rename and Delete.
        /// </summary>
        private void CaMenu_Opened(object sender, RoutedEventArgs e)
        {
            bool onAction = CaList?.SelectedItem is CaItem sel && !sel.IsRoot;
            void V(MenuItem? m, bool show)
            { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }

            V(MiCaNewExe, !onAction);
            V(MiCaNewDll, !onAction);
            V(MiCaNewVbs, !onAction);
            V(MiCaNewJs, !onAction);
            V(MiCaNewSetProp, !onAction);
            V(MiCaNewSetDir, !onAction);
            V(MiCaNewNested, !onAction);
            V(MiCaNewError, !onAction);
            V(MiCaNewChoose, !onAction);
            if (SepCaNew != null)
                SepCaNew.Visibility = onAction ? Visibility.Collapsed : Visibility.Visible;
            V(MiCaRename, onAction);
            V(MiCaDelete, onAction);
        }

        private void CaRename_Click(object sender, RoutedEventArgs e)
        {
            if (CaList?.SelectedItem is not CaItem it || it.IsRoot || it.Row == null) return;
            var caSt = _caSt ?? EnsureTableCached("CustomAction");
            if (caSt == null) return;

            string oldName = Cv(it.Row["Action"]);
            string? typed = PromptText("Rename Custom Action", "Name", oldName);
            if (string.IsNullOrWhiteSpace(typed)) return;
            string newName = SanitizeKey(typed.Trim());
            if (string.Equals(newName, oldName, StringComparison.Ordinal)) return;
            if (FindLiveRow(caSt, "Action", newName) != null)
            {
                MstMessage($"{newName} is already used by another custom action.",
                    "Rename Custom Action", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            it.Row["Action"] = newName;
            // The sequence tables point at the action by name; the schedule follows the rename.
            foreach (var (table, _) in CaSequenceTables)
            {
                var st = EnsureTableCached(table);
                var r = st == null ? null : FindCaSeqRow(st, oldName);
                if (r != null) r["Action"] = newName;
            }

            UpdateEditCount();
            ShowCustomActionsForm(caSt);
            SelectCaByAction(newName);
        }

        private DataRow? _caEditRow;
        private bool _caEditorLoading;

        private void ClearCaEditor()
        {
            _caEditRow = null;
            if (CaEditorHost != null) CaEditorHost.Content = null;
        }

        // Builds the editable custom-action form directly in the right-hand panel.
        // Every field writes straight back to the underlying CustomAction row, so edits
        // are saved automatically (no separate dialog). The Action key is committed when
        // its box loses focus; all other fields commit as they change.
        private void ShowCaEditor(DataRow row)
        {
            if (CaEditorHost == null) return;
            _caEditorLoading = true;
            _caEditRow = row;
            var data = ReadCustomActionData(row);

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")      as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")   as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(96) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            TextBlock Lbl(string t) => new TextBlock
            {
                Text = t, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
            };
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = Lbl(label);
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }

            // Action name
            var (acField, acBox) = MakeRoundedField(data.Action, boxBg, boxBdr, valFg, false, null);
            AddRow("Action name", acField);

            // Type of action
            var typeBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            foreach (var t in CaTemplates)
                typeBox.Items.Add(new ComboBoxItem { Content = t.label, Tag = t.baseType });
            int ti = Array.FindIndex(CaTemplates, x => x.baseType == data.BaseType);
            typeBox.SelectedIndex = ti >= 0 ? ti : 0;
            AddRow("Type of action", RoundWrapControl(typeBox, boxBg, boxBdr));
            int SelectedBase() => typeBox.SelectedItem is ComboBoxItem ci && ci.Tag is int b ? b : 18;

            // Source type (read-only, follows the chosen type)
            var srcTypeText = new TextBlock { Text = CaSourceKind(SelectedBase()), FontSize = 12, Foreground = valFg };
            AddRow("Source type", srcTypeText);

            // Source (with per-type package picker)
            var (srcField, srcBox) = MakeRoundedField(data.Source, boxBg, boxBdr, valFg, false, () =>
            {
                string sk = CaSourceKind(SelectedBase());
                return sk switch
                {
                    "File"      => PickFromPackage("Select a file",      KeysFrom("File", "File")),
                    "Directory" => PickFromPackage("Select a directory", PackageDirs()),
                    "Property"  => PickFromPackage("Select a property",  KeysFrom("Property", "Property")),
                    "Binary"    => PickFromPackage("Select a binary",    KeysFrom("Binary", "Name"), AddBinaryFromDisk),
                    _           => null
                };
            });
            AddRow("Source", srcField);

            // Target, under whatever that column actually means for this action type.
            var (tgtField, tgtBox) = MakeRoundedField(data.Target, boxBg, boxBdr, valFg, true, null);
            var tgtLabel = Lbl(CaTargetLabel(SelectedBase()));
            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            tgtField.Margin = new Thickness(0, 4, 0, 4);
            Grid.SetRow(tgtLabel, rr); Grid.SetColumn(tgtLabel, 0);
            Grid.SetRow(tgtField, rr); Grid.SetColumn(tgtField, 1);
            grid.Children.Add(tgtLabel); grid.Children.Add(tgtField);
            rr++;

            // Execution, combined with the context it runs in, the way the reference editors
            // list it: the context bits only mean anything on a deferred action, so a separate
            // "run as system" checkbox allowed combinations the type cannot express.
            (string label, string exec, bool noImp, bool ts)[] execOpts =
            {
                ("Immediate",                          "Immediate",           false, false),
                ("Deferred (user context)",            "Deferred",            false, false),
                ("Rollback (user context)",            "Deferred (rollback)", false, false),
                ("Commit (user context)",              "Deferred (commit)",   false, false),
                ("Deferred (system context)",          "Deferred",            true,  false),
                ("Rollback (system context)",          "Deferred (rollback)", true,  false),
                ("Commit (system context)",            "Deferred (commit)",   true,  false),
                ("Deferred (terminal server aware)",   "Deferred",            false, true),
                ("Rollback (terminal server aware)",   "Deferred (rollback)", false, true),
                ("Commit (terminal server aware)",     "Deferred (commit)",   false, true),
            };
            var execBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            for (int i = 0; i < execOpts.Length; i++)
                execBox.Items.Add(new ComboBoxItem { Content = execOpts[i].label, Tag = i });
            int ei = data.Execution == "Immediate" ? 0
                : Array.FindIndex(execOpts, x => x.exec == data.Execution
                                              && x.noImp == data.NoImpersonate && x.ts == data.TSAware);
            execBox.SelectedIndex = ei >= 0 ? ei : (data.Execution == "Immediate" ? 0 : 1);
            AddRow("Execution", RoundWrapControl(execBox, boxBg, boxBdr));
            (string exec, bool noImp, bool ts) SelectedExec()
                => execBox.SelectedItem is ComboBoxItem ci && ci.Tag is int i2
                    ? (execOpts[i2].exec, execOpts[i2].noImp, execOpts[i2].ts)
                    : ("Immediate", false, false);

            // Return processing as the single four-way choice every reference editor shows,
            // instead of two checkboxes whose combinations had to be worked out.
            (string label, bool cont, bool async)[] retOpts =
            {
                ("Synchronous, check exit code",             false, false),
                ("Synchronous, ignore exit code",            true,  false),
                ("Asynchronous, wait for exit code",         false, true),
                ("Asynchronous, no wait (ignore exit code)", true,  true),
            };
            var retBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            for (int i = 0; i < retOpts.Length; i++)
                retBox.Items.Add(new ComboBoxItem { Content = retOpts[i].label, Tag = i });
            int ri = Array.FindIndex(retOpts, x => x.cont == data.Continue && x.async == data.Async);
            retBox.SelectedIndex = ri >= 0 ? ri : 0;
            AddRow("Return processing", RoundWrapControl(retBox, boxBg, boxBdr));
            (bool cont, bool async) SelectedRet()
                => retBox.SelectedItem is ComboBoxItem ci && ci.Tag is int i3
                    ? (retOpts[i3].cont, retOpts[i3].async) : (false, false);

            // How often it runs. Greyed for a deferred action, because the bits this writes are
            // the rollback and commit bits once the action is in-script - the setting cannot be
            // expressed there at all, rather than being merely unusual.
            var schedBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            (string tag, string label)[] scheds =
            {
                ("Always",         "Always execute"),
                ("Once",           "Execute only once"),
                ("OncePerProcess", "Execute only once per process"),
                ("ClientRepeat",   "Execute only if running on client after UI sequence"),
            };
            foreach (var (tag, label) in scheds)
                schedBox.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
            int si = Array.FindIndex(scheds, x => x.tag == data.Scheduling);
            schedBox.SelectedIndex = si >= 0 ? si : 0;
            var schedWrap = RoundWrapControl(schedBox, boxBg, boxBdr);
            AddRow("Scheduling", schedWrap);

            // Options. No fixed width: at 230 apiece the three could not share a line and wrapped
            // into a block two rows deep. Sized to their own text they fit across, and the panel
            // still wraps if the pane is dragged narrow enough to need it.
            CheckBox Chk(string label, bool on) => new CheckBox
            {
                Content = label, IsChecked = on, Foreground = lblFg, FontSize = 12,
                Margin = new Thickness(0, 4, 20, 4), VerticalContentAlignment = VerticalAlignment.Center
            };
            var c64    = Chk("64-bit script", data.Bit64);
            var cHide  = Chk("Hide target in log", data.HideTarget);
            var cPatch = Chk("Run during patch uninstall", data.PatchUninstall);
            var opts = new WrapPanel { Orientation = Orientation.Horizontal };
            foreach (var c in new[] { c64, cHide, cPatch }) opts.Children.Add(c);
            AddRow("Options", opts);

            // The number that actually goes in the Type column, and where the action is scheduled.
            // Both are read-only: they are what the choices above add up to, shown so the result
            // can be checked against the documentation rather than inferred.
            var typeNumText = new TextBlock
            {
                FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = lblFg,
                Margin = new Thickness(0, 6, 0, 0)
            };
            AddRow("MSI type", typeNumText);

            // Where the action is scheduled, editable per sequence table the way the reference
            // editors present it. "After X" places at X's number plus one, shifting later rows
            // only when the numbers are packed solid; the tables ship with gaps for exactly this.
            var seqCombos = new Dictionary<string, ComboBox>(StringComparer.OrdinalIgnoreCase);
            var seqConds  = new Dictionary<string, TextBox>(StringComparer.OrdinalIgnoreCase);
            bool seqSyncing = false;

            foreach (var (table, shortName) in CaSequenceTables)
            {
                var combo = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
                };
                // The builder needs whatever is in the box at the moment it opens, and the box is
                // created by this same statement, so the reference is filled in just after.
                TextBox? condRef = null;
                var (condField, condBox) = MakeRoundedField("", boxBg, boxBdr, valFg, false,
                    () => PromptCondition("Condition Builder", condRef?.Text ?? ""),
                    "\uD83D\uDDD4", "Build this condition");
                condRef = condBox;
                condBox.FontSize = 11;
                condBox.ToolTip = "Condition for this sequence entry. Blank runs unconditionally.";

                string tbl = table;
                combo.SelectionChanged += (_, _) =>
                {
                    if (seqSyncing || _caEditorLoading || _caEditRow == null) return;
                    if (combo.SelectedItem is not ComboBoxItem ci || ci.Tag is not string choice) return;
                    ScheduleCa(tbl, Cv(_caEditRow["Action"]), choice);
                    UpdateEditCount();
                    seqSyncing = true;
                    ReflectCaSequence(tbl, Cv(_caEditRow["Action"]), combo, condBox);
                    seqSyncing = false;
                    if (CaList?.SelectedItem is CaItem it2 && !it2.IsRoot)
                        it2.Update(Cv(_caEditRow["Action"]), CaKindShort(int.TryParse(Cv(_caEditRow["Type"]), out var tv) ? tv : 0));
                };
                condBox.TextChanged += (_, _) =>
                {
                    if (seqSyncing || _caEditorLoading || _caEditRow == null) return;
                    var st2 = EnsureTableCached(tbl);
                    var row2 = st2 == null ? null : FindCaSeqRow(st2, Cv(_caEditRow["Action"]));
                    if (row2 == null || !row2.Table.Columns.Contains("Condition")) return;
                    string v = condBox.Text.Trim();
                    row2["Condition"] = v.Length > 0 ? (object)v : DBNull.Value;
                    UpdateEditCount();
                };

                seqCombos[table] = combo;
                seqConds[table]  = condBox;
                AddRow(shortName, RoundWrapControl(combo, boxBg, boxBdr));
                // The box under each sequence is that entry's condition, which nothing on the form
                // said. It gets its own labelled row rather than a caption inside the field, so it
                // reads the way every other field on the form does.
                AddRow("Condition", condField);
            }

            void RefreshSequences()
            {
                if (_caEditRow == null) return;
                seqSyncing = true;
                string act = Cv(_caEditRow["Action"]);
                foreach (var (table, _) in CaSequenceTables)
                    ReflectCaSequence(table, act, seqCombos[table], seqConds[table]);
                seqSyncing = false;
            }

            CustomActionData ReadControls() => new CustomActionData
            {
                Action = acBox.Text.Trim(),
                Source = srcBox.Text,
                Target = tgtBox.Text,
                BaseType = SelectedBase(),
                Execution = SelectedExec().exec,
                NoImpersonate = SelectedExec().noImp,
                TSAware = SelectedExec().ts,
                Scheduling = (schedBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "Always",
                Continue = SelectedRet().cont, Async = SelectedRet().async,
                Bit64 = c64.IsChecked == true,
                HideTarget = cHide.IsChecked == true, PatchUninstall = cPatch.IsChecked == true
            };

            void RefreshReadouts(CustomActionData d)
            {
                int raw = ComputeCaType(d);
                srcTypeText.Text = CaSourceKind(d.BaseType);
                tgtLabel.Text = CaTargetLabel(d.BaseType);

                // Only an inline script is a block of text. A function name, a command line or a
                // property value is one line, and a box five lines deep for them pushed the rest
                // of the form down for nothing.
                bool longTarget = d.BaseType is 37 or 38;
                tgtBox.MinHeight = longTarget ? 58 : 0;
                tgtBox.AcceptsReturn = longTarget;
                tgtBox.VerticalContentAlignment = longTarget ? VerticalAlignment.Top : VerticalAlignment.Center;
                tgtBox.TextWrapping = longTarget ? TextWrapping.Wrap : TextWrapping.NoWrap;

                bool immediate = d.Execution == "Immediate";
                schedBox.IsEnabled = immediate;
                schedWrap.Opacity  = immediate ? 1.0 : 0.5;
                schedWrap.ToolTip  = immediate
                    ? "How many times the action runs."
                    : "Only an immediate action can carry this: the bits it uses are the rollback "
                    + "and commit bits once the action is deferred.";

                typeNumText.Text = $"{raw}  (0x{raw:X})";
                if (CaList?.SelectedItem is CaItem it && !it.IsRoot) it.Update(d.Action, CaKindShort(raw));
            }

            // Commit everything except the Action key (key is committed on focus loss).
            void CommitRest()
            {
                if (_caEditorLoading || _caEditRow == null) return;
                var d = ReadControls();
                d.Action = Cv(_caEditRow["Action"]);   // keep the current key
                try { WriteCustomActionData(_caEditRow, d); } catch { }
                UpdateEditCount();
                RefreshReadouts(d);
            }

            // Commit the Action key (rename) when the box loses focus.
            void CommitName()
            {
                if (_caEditorLoading || _caEditRow == null) return;
                string newName = acBox.Text.Trim();
                string oldName = Cv(_caEditRow["Action"]);
                if (newName.Length == 0) { acBox.Text = oldName; return; }
                if (string.Equals(newName, oldName, StringComparison.Ordinal)) return;
                var d = ReadControls();
                d.Action = newName;
                try { WriteCustomActionData(_caEditRow, d); }
                catch { acBox.Text = oldName; return; }   // e.g. duplicate key rejected

                // The sequence tables point at the action by name, so a rename that stops here
                // leaves the schedule attached to a name that no longer exists.
                foreach (var (table, _) in CaSequenceTables)
                {
                    var st3 = EnsureTableCached(table);
                    var row3 = st3 == null ? null : FindCaSeqRow(st3, oldName);
                    if (row3 != null) row3["Action"] = newName;
                }

                UpdateEditCount();
                RefreshReadouts(d);
                RefreshSequences();
            }

            acBox.LostFocus  += (_, _) => CommitName();
            srcBox.TextChanged += (_, _) => CommitRest();
            tgtBox.TextChanged += (_, _) => CommitRest();
            typeBox.SelectionChanged += (_, _) => CommitRest();
            execBox.SelectionChanged += (_, _) => CommitRest();
            retBox.SelectionChanged  += (_, _) => CommitRest();
            schedBox.SelectionChanged += (_, _) => CommitRest();
            foreach (var c in new[] { c64, cHide, cPatch })
            { c.Checked += (_, _) => CommitRest(); c.Unchecked += (_, _) => CommitRest(); }

            CaEditorHost.Content = grid;
            _caEditorLoading = false;
            RefreshReadouts(data);
            RefreshSequences();
        }

        // The five sequence tables an action can be scheduled in, with the labels the editor
        // shows for them.
        private static readonly (string table, string shortName)[] CaSequenceTables =
        {
            ("InstallUISequence",    "Install UI"),
            ("InstallExecuteSequence","Install Exec"),
            ("AdvtExecuteSequence",  "Advertise"),
            ("AdminUISequence",      "Admin UI"),
            ("AdminExecuteSequence", "Admin Exec"),
        };

        /// <summary>This action's live row in one sequence table, or null when it is not there.</summary>
        private static DataRow? FindCaSeqRow(TableState st, string action)
        {
            if (!st.Data.Columns.Contains("Action")) return null;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Action"]), action, StringComparison.OrdinalIgnoreCase)) return r;
            }
            return null;
        }

        /// <summary>
        /// Every other entry in a sequence table that occupies an ordered position, sorted by
        /// number. A negative or zero Sequence is a termination flag - the row runs on exit, not
        /// at a place in the order - so ExitDialog at -1 must neither be offered as an After
        /// anchor (its number plus one is nonsense) nor counted as anything's predecessor.
        /// </summary>
        private static List<(string Action, int Seq, DataRow Row)> CaSeqEntries(TableState st, string except)
        {
            var list = new List<(string, int, DataRow)>();
            if (!st.Data.Columns.Contains("Action")) return list;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string a = Cv(r["Action"]);
                if (string.Equals(a, except, StringComparison.OrdinalIgnoreCase)) continue;
                int.TryParse(st.Data.Columns.Contains("Sequence") ? Cv(r["Sequence"]) : "", out int q);
                if (q <= 0) continue;
                list.Add((a, q, r));
            }
            list.Sort((x, y) => x.Item2.CompareTo(y.Item2));
            return list;
        }

        /// <summary>
        /// Puts an action where the choice says in one sequence table: "ABSENT" removes its row,
        /// "FIRST" numbers it ahead of everything, and an action name places it at that action's
        /// number plus one, shifting the rows above only when they are packed with no room.
        /// </summary>
        private void ScheduleCa(string table, string action, string choice)
        {
            var st = EnsureTableOrCreate(table);
            if (st == null || action.Length == 0) return;

            var self = FindCaSeqRow(st, action);
            if (choice == "KEEP") return;   // the termination-flag display item; nothing to move
            if (choice == "ABSENT")
            {
                if (self != null) self.Delete();
                return;
            }

            var others = CaSeqEntries(st, action);
            int newSeq;
            if (choice == "FIRST")
            {
                int min = others.Count > 0 ? others[0].Seq : 2;
                if (min <= 1)
                {
                    // No room below the first entry: everything moves up one to make it.
                    foreach (var (_, q, r) in others) r["Sequence"] = (q + 1).ToString();
                    newSeq = 1;
                }
                else newSeq = min - 1;
            }
            else
            {
                int i = others.FindIndex(x => string.Equals(x.Action, choice, StringComparison.OrdinalIgnoreCase));
                if (i < 0) return;
                int baseSeq = others[i].Seq;
                bool packed = i + 1 < others.Count && others[i + 1].Seq <= baseSeq + 1;
                if (packed)
                    foreach (var (_, q, r) in others)
                        if (q > baseSeq) r["Sequence"] = (q + 2).ToString();
                newSeq = baseSeq + 1;
            }

            if (self == null)
            {
                self = st.Data.NewRow();
                self["Action"] = action;
                st.Data.Rows.Add(self);
            }
            if (st.Data.Columns.Contains("Sequence")) self["Sequence"] = newSeq.ToString();
        }

        /// <summary>
        /// Makes one sequence combo and condition box say where the action currently sits:
        /// absent, first, or after whichever entry precedes it by number.
        /// </summary>
        private void ReflectCaSequence(string table, string action, ComboBox combo, TextBox condBox)
        {
            var st = _msiTableNames.Contains(table, StringComparer.OrdinalIgnoreCase) || _tables.ContainsKey(table)
                ? EnsureTableCached(table) : null;
            var self = st == null ? null : FindCaSeqRow(st, action);
            var others = st == null
                ? new List<(string Action, int Seq, DataRow Row)>()
                : CaSeqEntries(st, action);

            combo.Items.Clear();
            combo.Items.Add(new ComboBoxItem { Content = "Absent from sequence", Tag = "ABSENT" });
            combo.Items.Add(new ComboBoxItem { Content = "First action", Tag = "FIRST" });
            foreach (var (a, q, _) in others)
                combo.Items.Add(new ComboBoxItem { Content = $"After {a}  ({q})", Tag = a });

            int sel = 0;
            if (self != null)
            {
                int.TryParse(st!.Data.Columns.Contains("Sequence") ? Cv(self["Sequence"]) : "", out int mySeq);
                if (mySeq <= 0)
                {
                    // A termination flag: the row runs on install exit, outside the order the rest
                    // of this list describes. Shown as its own state; picking any other choice
                    // moves the action to a real position.
                    combo.Items.Add(new ComboBoxItem
                    {
                        Content = $"On termination  ({mySeq})", Tag = "KEEP"
                    });
                    sel = combo.Items.Count - 1;
                }
                else
                {
                    string? pred = null;
                    foreach (var (a, q, _) in others) { if (q < mySeq) pred = a; else break; }
                    sel = pred == null ? 1
                        : 2 + others.FindIndex(x => string.Equals(x.Action, pred, StringComparison.OrdinalIgnoreCase));
                }
            }
            combo.SelectedIndex = sel;

            condBox.IsEnabled = self != null;
            condBox.Text = self != null && st!.Data.Columns.Contains("Condition") ? Cv(self["Condition"]) : "";
        }

        private static int ComputeCaType(CustomActionData d)
        {
            int t = d.BaseType & 0x3F;
            bool inScript = d.Execution != "Immediate";
            t |= d.Execution switch
            {
                "Deferred"            => 0x400,
                "Deferred (rollback)" => 0x400 | 0x100,
                "Deferred (commit)"   => 0x400 | 0x200,
                _                     => 0
            };

            // 0x100 and 0x200 carry the scheduling only while the in-script bit is clear; with it
            // set they already mean rollback and commit, so scheduling cannot be written at all.
            if (!inScript)
                t |= d.Scheduling switch
                {
                    "Once"           => 0x100,
                    "OncePerProcess" => 0x200,
                    "ClientRepeat"   => 0x300,
                    _                => 0
                };

            if (d.Continue)       t |= 0x40;
            if (d.Async)          t |= 0x80;
            // Both context bits belong to a deferred action; on an immediate one they say nothing
            // and would only make the type number lie about what runs.
            if (d.NoImpersonate && inScript) t |= 0x800;
            if (d.TSAware && inScript)       t |= 0x4000;
            if (d.Bit64)          t |= 0x1000;
            if (d.HideTarget)     t |= 0x2000;
            if (d.PatchUninstall) t |= 0x8000;
            return t;
        }

        /// <summary>How often the action runs, read back from the two bits that only mean that
        /// while the in-script bit is clear.</summary>
        private static string CaScheduling(int type)
        {
            if ((type & 0x400) != 0) return "Always";      // those bits are rollback/commit here
            return (type & 0x300) switch
            {
                0x100 => "Once",
                0x200 => "OncePerProcess",
                0x300 => "ClientRepeat",
                _     => "Always"
            };
        }

        /// <summary>
        /// What the Target column actually holds for a given action type. Calling it "Target"
        /// everywhere hid what it wants: for a DLL action it is the exported function name, which
        /// is what every other MSI editor labels it, and for a script stored elsewhere it is an
        /// optional entry point rather than the script itself.
        /// </summary>
        private static string CaTargetLabel(int baseType) => baseType switch
        {
            1 or 17                 => "Function name",     // DLL entry point
            2 or 18 or 34 or 50     => "Command line",      // EXE arguments
            37 or 38                => "Script",            // script written inline in Target
            5 or 6 or 21 or 22
               or 53 or 54          => "Entry point",       // script lives elsewhere; blank runs it all
            7 or 23 or 39           => "Properties (name=value)",   // nested install settings
            19                      => "Message",           // display error / abort
            35                      => "Directory path",    // set directory
            51                      => "Property value",    // set property
            _                       => "Target"
        };

        private CustomActionData ReadCustomActionData(DataRow r)
        {
            int t = int.TryParse(Cv(r["Type"]), out var v) ? v : 0;
            return new CustomActionData
            {
                Action = Cv(r["Action"]),
                Source = Cv(r["Source"]),
                Target = Cv(r["Target"]),
                BaseType = t & 0x3F,
                Execution = CaExecution(t),
                Scheduling = CaScheduling(t),
                Continue = (t & 0x40) != 0,
                Async = (t & 0x80) != 0,
                NoImpersonate = (t & 0x800) != 0,
                TSAware = (t & 0x4000) != 0,
                Bit64 = (t & 0x1000) != 0,
                HideTarget = (t & 0x2000) != 0,
                PatchUninstall = (t & 0x8000) != 0
            };
        }

        private void WriteCustomActionData(DataRow r, CustomActionData d)
        {
            void Set(string c, string val, bool required)
            {
                if (!r.Table.Columns.Contains(c)) return;
                r[c] = (val.Length > 0 || required) ? (object)val : DBNull.Value;
            }
            Set("Action", d.Action, true);
            Set("Source", d.Source, false);
            Set("Target", d.Target, false);
            if (r.Table.Columns.Contains("Type")) r["Type"] = ComputeCaType(d).ToString();
        }

        private void CaNew_Click(object sender, RoutedEventArgs e)
        {
            var caSt = _caSt ?? EnsureTableOrCreate("CustomAction");
            if (caSt == null)
            { MstMessage("This MSI has no CustomAction table.", "New Custom Action", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            var res = PromptCustomAction("New Custom Action", new CustomActionData());
            if (res == null) return;
            var nr = caSt.Data.NewRow();
            string baseKey = SanitizeKey(res.Action.Length > 0 ? res.Action : "CustomAction");
            res.Action = UniqueKey(caSt.Data, "Action", baseKey);
            WriteCustomActionData(nr, res);
            caSt.Data.Rows.Add(nr);
            UpdateEditCount();
            ShowCustomActionsForm(caSt);
            SelectCaByAction(res.Action);
        }

        /// <summary>
        /// Creates an action of the type carried on the menu item, named and selected so the
        /// editor opens on it ready for the source and target - the menu has already answered
        /// what kind it is, so no dialog stands in between.
        /// </summary>
        private void CaNewTyped_Click(object sender, RoutedEventArgs e)
        {
            if (sender is not MenuItem mi || mi.Tag is not string tag || !int.TryParse(tag, out int baseType)) return;
            var caSt = _caSt ?? EnsureTableOrCreate("CustomAction");
            if (caSt == null)
            { MstMessage("This MSI has no CustomAction table.", "New Custom Action", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            var d = new CustomActionData { BaseType = baseType };
            d.Action = UniqueKey(caSt.Data, "Action", "NewCustomAction");
            var nr = caSt.Data.NewRow();
            WriteCustomActionData(nr, d);
            caSt.Data.Rows.Add(nr);
            UpdateEditCount();
            ShowCustomActionsForm(caSt);
            SelectCaByAction(d.Action);
            if (TxtStatus != null)
                TxtStatus.Text = $"Added {d.Action} ({CaTemplateLabel(baseType)}). Fill in its source and target, then schedule it.";
        }

        private void CaDelete_Click(object sender, RoutedEventArgs e)
        {
            if (CaList?.SelectedItem is not CaItem it || it.IsRoot || it.Row == null) return;
            var caSt = _caSt ?? EnsureTableCached("CustomAction");
            if (caSt == null) return;
            if (MstMessage($"Delete custom action \u201C{it.Action}\u201D?",
                    "Delete Custom Action", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
            if (it.Row.RowState != DataRowState.Deleted) it.Row.Delete();
            UpdateEditCount();
            ShowCustomActionsForm(caSt);
        }

        private void SelectCaByAction(string action)
        {
            if (CaList?.ItemsSource is not System.Collections.IEnumerable roots) return;
            foreach (var o in roots)
            {
                if (o is not CaItem root) continue;
                root.IsExpanded = true;
                foreach (var ci in root.Children)
                    if (string.Equals(ci.Action, action, StringComparison.OrdinalIgnoreCase))
                    { ci.IsSelected = true; return; }
            }
        }

        // Raw key listers for the source picker (CA Source is a bare foreign key).
        private System.Collections.Generic.List<(string value, string display)> KeysFrom(string table, string col)
        {
            var outp = new System.Collections.Generic.List<(string value, string display)>();
            var st = EnsureTableCached(table);
            if (st != null && st.Data.Columns.Contains(col))
                foreach (DataRow r in st.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string k = Cv(r[col]);
                    if (k.Length > 0) outp.Add((k, k));
                }
            outp.Sort((a, b) => string.Compare(a.display, b.display, StringComparison.OrdinalIgnoreCase));
            return outp;
        }

        // Custom-action editor. Returns the edited data, or null on cancel.
        private CustomActionData? PromptCustomAction(string title, CustomActionData init)
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 560; win.MaxWidth = 560;

            int r = 0;
            void AddStacked(string text, FrameworkElement field, bool first = false)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, Margin = new Thickness(0, first ? 0 : 10, 0, 4)
                };
                Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0); Grid.SetColumnSpan(lbl, 2);
                cg.Children.Add(lbl); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(field, r); Grid.SetColumn(field, 0); Grid.SetColumnSpan(field, 2);
                cg.Children.Add(field); r++;
            }
            CheckBox Chk(string label, bool on) => new CheckBox
            {
                Content = label, IsChecked = on, Foreground = lblFg, FontSize = 12,
                Width = 250, Margin = new Thickness(0, 4, 12, 4), VerticalContentAlignment = VerticalAlignment.Center
            };

            var (acField, acBox) = MakeRoundedField(init.Action, boxBg, boxBdr, valFg, false, null);
            AddStacked("Action name", acField, true);

            var typeBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            foreach (var t in CaTemplates)
                typeBox.Items.Add(new ComboBoxItem { Content = t.label, Tag = t.baseType });
            int ti = Array.FindIndex(CaTemplates, x => x.baseType == init.BaseType);
            typeBox.SelectedIndex = ti >= 0 ? ti : 0;
            AddStacked("Type of action", RoundWrapControl(typeBox, boxBg, boxBdr));

            int SelectedBase() => typeBox.SelectedItem is ComboBoxItem ci && ci.Tag is int b ? b : 18;
            var (srcField, srcBox) = MakeRoundedField(init.Source, boxBg, boxBdr, valFg, false, () =>
            {
                string sk = CaSourceKind(SelectedBase());
                return sk switch
                {
                    "File"      => PickFromPackage("Select a file",      KeysFrom("File", "File")),
                    "Directory" => PickFromPackage("Select a directory", PackageDirs()),
                    "Property"  => PickFromPackage("Select a property",  KeysFrom("Property", "Property")),
                    "Binary"    => PickFromPackage("Select a binary",    KeysFrom("Binary", "Name"), AddBinaryFromDisk),
                    _           => null
                };
            });
            var srcLbl = new TextBlock
            {
                Text = "Source" + (CaSourceKind(init.BaseType) is { Length: > 0 } sk0 && sk0 != "None" ? $"  ({sk0} key)" : ""),
                FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, Margin = new Thickness(0, 10, 0, 4)
            };
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Grid.SetRow(srcLbl, r); Grid.SetColumn(srcLbl, 0); Grid.SetColumnSpan(srcLbl, 2);
            cg.Children.Add(srcLbl); r++;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Grid.SetRow(srcField, r); Grid.SetColumn(srcField, 0); Grid.SetColumnSpan(srcField, 2);
            cg.Children.Add(srcField); r++;
            typeBox.SelectionChanged += (_, _) =>
                srcLbl.Text = "Source" + (CaSourceKind(SelectedBase()) is { Length: > 0 } sk1 && sk1 != "None" ? $"  ({sk1} key)" : "");

            // Target, under whatever that column actually means for the chosen type. Updated
            // when the type changes, so picking a DLL action relabels this to Function name.
            var (tgtField, tgtBox) = MakeRoundedField(init.Target, boxBg, boxBdr, valFg, true, null);
            var tgtLbl = new TextBlock
            {
                Text = CaTargetLabel(init.BaseType), FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, Margin = new Thickness(0, 10, 0, 4)
            };
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Grid.SetRow(tgtLbl, r); Grid.SetColumn(tgtLbl, 0); Grid.SetColumnSpan(tgtLbl, 2);
            cg.Children.Add(tgtLbl); r++;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Grid.SetRow(tgtField, r); Grid.SetColumn(tgtField, 0); Grid.SetColumnSpan(tgtField, 2);
            cg.Children.Add(tgtField); r++;
            typeBox.SelectionChanged += (_, _) => tgtLbl.Text = CaTargetLabel(SelectedBase());

            // Same execution list as the inline editor: context folded in, because the context
            // bits only exist on a deferred action.
            (string label, string exec, bool noImp, bool ts)[] execOpts =
            {
                ("Immediate",                          "Immediate",           false, false),
                ("Deferred (user context)",            "Deferred",            false, false),
                ("Rollback (user context)",            "Deferred (rollback)", false, false),
                ("Commit (user context)",              "Deferred (commit)",   false, false),
                ("Deferred (system context)",          "Deferred",            true,  false),
                ("Rollback (system context)",          "Deferred (rollback)", true,  false),
                ("Commit (system context)",            "Deferred (commit)",   true,  false),
                ("Deferred (terminal server aware)",   "Deferred",            false, true),
                ("Rollback (terminal server aware)",   "Deferred (rollback)", false, true),
                ("Commit (terminal server aware)",     "Deferred (commit)",   false, true),
            };
            var execBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            for (int i = 0; i < execOpts.Length; i++)
                execBox.Items.Add(new ComboBoxItem { Content = execOpts[i].label, Tag = i });
            int ei = init.Execution == "Immediate" ? 0
                : Array.FindIndex(execOpts, x => x.exec == init.Execution
                                              && x.noImp == init.NoImpersonate && x.ts == init.TSAware);
            execBox.SelectedIndex = ei >= 0 ? ei : (init.Execution == "Immediate" ? 0 : 1);
            AddStacked("Execution", RoundWrapControl(execBox, boxBg, boxBdr));
            (string exec, bool noImp, bool ts) SelectedExec()
                => execBox.SelectedItem is ComboBoxItem ci2 && ci2.Tag is int i2
                    ? (execOpts[i2].exec, execOpts[i2].noImp, execOpts[i2].ts)
                    : ("Immediate", false, false);

            (string label, bool cont, bool async)[] retOpts =
            {
                ("Synchronous, check exit code",             false, false),
                ("Synchronous, ignore exit code",            true,  false),
                ("Asynchronous, wait for exit code",         false, true),
                ("Asynchronous, no wait (ignore exit code)", true,  true),
            };
            var retBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            for (int i = 0; i < retOpts.Length; i++)
                retBox.Items.Add(new ComboBoxItem { Content = retOpts[i].label, Tag = i });
            int ri = Array.FindIndex(retOpts, x => x.cont == init.Continue && x.async == init.Async);
            retBox.SelectedIndex = ri >= 0 ? ri : 0;
            AddStacked("Return processing", RoundWrapControl(retBox, boxBg, boxBdr));
            (bool cont, bool async) SelectedRet()
                => retBox.SelectedItem is ComboBoxItem ci3 && ci3.Tag is int i3
                    ? (retOpts[i3].cont, retOpts[i3].async) : (false, false);

            (string tag, string label)[] scheds =
            {
                ("Always",         "Always execute"),
                ("Once",           "Execute only once"),
                ("OncePerProcess", "Execute only once per process"),
                ("ClientRepeat",   "Execute only if running on client after UI sequence"),
            };
            var schedBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            foreach (var (tag, label) in scheds)
                schedBox.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
            int si = Array.FindIndex(scheds, x => x.tag == init.Scheduling);
            schedBox.SelectedIndex = si >= 0 ? si : 0;
            var schedWrap = RoundWrapControl(schedBox, boxBg, boxBdr);
            AddStacked("Scheduling", schedWrap);
            void SyncSched()
            {
                bool immediate = SelectedExec().exec == "Immediate";
                schedBox.IsEnabled = immediate;
                schedWrap.Opacity  = immediate ? 1.0 : 0.5;
            }
            execBox.SelectionChanged += (_, _) => SyncSched();
            SyncSched();

            var c64     = Chk("64-bit script", init.Bit64);
            var cHide   = Chk("Hide target in log", init.HideTarget);
            var cPatch  = Chk("Run during patch uninstall", init.PatchUninstall);
            var opts = new WrapPanel { Orientation = Orientation.Horizontal };
            foreach (var c in new[] { c64, cHide, cPatch }) opts.Children.Add(c);
            AddStacked("Options", opts);

            NdAddSpacer(cg, r++);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            CustomActionData? result = null;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () =>
                {
                    result = new CustomActionData
                    {
                        Action = acBox.Text.Trim(),
                        Source = srcBox.Text,
                        Target = tgtBox.Text,
                        BaseType = SelectedBase(),
                        Execution = SelectedExec().exec,
                        NoImpersonate = SelectedExec().noImp,
                        TSAware = SelectedExec().ts,
                        Scheduling = (schedBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "Always",
                        Continue = SelectedRet().cont, Async = SelectedRet().async,
                        Bit64 = c64.IsChecked == true,
                        HideTarget = cHide.IsChecked == true,
                        PatchUninstall = cPatch.IsChecked == true
                    };
                    win.Close();
                }),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 0); Grid.SetColumnSpan(btns, 2); cg.Children.Add(btns);

            acBox.Loaded += (_, _) => { acBox.Focus(); };
            win.ShowDialog();
            return result;
        }

        // ══ Sequences (sequence-table selector + order-sorted action grid) ═══
        private static readonly string[] SequenceTables =
        {
            "InstallExecuteSequence", "InstallUISequence",
            "AdminExecuteSequence", "AdminUISequence", "AdvtExecuteSequence"
        };
        private string _seqComboBuiltFor = "\0";
        private bool _seqPopulating;

        private void ShowSequencesForm()
        {
            if (SeqTableBox != null && _seqComboBuiltFor != _msiPath)
            {
                _seqPopulating = true;
                SeqTableBox.Items.Clear();
                int defIdx = -1, idx = 0;
                foreach (var tbl in SequenceTables)
                {
                    if (EnsureTableCached(tbl) == null) continue;
                    SeqTableBox.Items.Add(new ComboBoxItem { Content = tbl, Tag = tbl });
                    if (tbl == "InstallExecuteSequence") defIdx = idx;
                    idx++;
                }
                if (SeqTableBox.Items.Count > 0) SeqTableBox.SelectedIndex = defIdx >= 0 ? defIdx : 0;
                _seqComboBuiltFor = _msiPath;
                _seqPopulating = false;
            }
            RefreshSeqList();
            if (FormSequencesPanel != null) FormSequencesPanel.Visibility = Visibility.Visible;
        }

        private string CurrentSeqTable() => (SeqTableBox?.SelectedItem as ComboBoxItem)?.Tag as string ?? "";

        private void SeqTableBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (_seqPopulating) return;
            RefreshSeqList();
        }

        private void RefreshSeqList()
        {
            string table = CurrentSeqTable();
            var st = table.Length > 0 ? EnsureTableCached(table) : null;
            if (st == null)
            {
                _seqAll = null;
                if (SeqList != null) SeqList.ItemsSource = null;
                if (SeqCount != null) SeqCount.Text = SeqTableBox != null && SeqTableBox.Items.Count == 0 ? "No sequence tables" : "";
                ClearSeqEditor();
                return;
            }
            _placeholderTable = table;
            bool hasCond = st.Data.Columns.Contains("Condition");
            var tmp = new System.Collections.Generic.List<(int order, SeqRow row)>();
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string action = Cv(r["Action"]);
                if (action.Length == 0) continue;
                string seq = Cv(r["Sequence"]);
                string cond = hasCond ? Cv(r["Condition"]) : "";
                int order = int.TryParse(seq, out var sv) ? sv : int.MaxValue;
                tmp.Add((order, new SeqRow(r, seq, action, cond)));
            }
            var ordered = new System.Collections.ObjectModel.ObservableCollection<SeqRow>(
                tmp.OrderBy(x => x.order).Select(x => x.row));
            _seqAll = ordered;
            if (SeqList != null) SeqList.ItemsSource = ordered;
            if (SeqCount != null) SeqCount.Text = ordered.Count == 1 ? "1 action" : $"{ordered.Count} actions";
            ApplySeqFind();
            ClearSeqEditor();
            if (SeqList != null && SeqList.Items.Count > 0 && SeqList.SelectedItem == null)
                SeqList.SelectedIndex = 0;
        }

        // ── Form-view find: highlight and step through matches in place ──────
        private System.Collections.ObjectModel.ObservableCollection<CaItem>? _caAll;
        private System.Collections.ObjectModel.ObservableCollection<SeqRow>? _seqAll;

        // One find per panel: an ordered list of jumps, one per match.
        private sealed class FindNav
        {
            public System.Collections.Generic.List<Action> Go = new();
            public int Pos = -1;
        }
        private readonly FindNav _caFind = new(), _seqFind = new(), _featFind = new(), _regFind = new(), _fileFind = new(), _propFind = new();

        private static void SearchPh(System.Windows.Controls.TextBox? tb, System.Windows.Controls.TextBlock? ph)
        { if (tb != null && ph != null) ph.Visibility = string.IsNullOrEmpty(tb.Text) ? Visibility.Visible : Visibility.Collapsed; }

        private static bool Hit(string hay, string q) => hay.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0;

        private static void FindCounter(FindNav nav, TextBlock? counter)
        { if (counter != null) counter.Text = nav.Go.Count == 0 ? "" : $"{nav.Pos + 1}/{nav.Go.Count}"; }

        // After (re)building a match list: jump to the first match.
        private void FindReset(FindNav nav, TextBlock? counter)
        {
            nav.Pos = nav.Go.Count > 0 ? 0 : -1;
            if (nav.Pos == 0) nav.Go[0]();
            FindCounter(nav, counter);
        }

        // Previous / next / Enter; prompts to start over past the last match.
        private void FindStep(FindNav nav, TextBlock? counter, int dir)
        {
            if (nav.Go.Count == 0) { if (counter != null) counter.Text = "0/0"; return; }
            if (dir > 0)
            {
                if (nav.Pos < nav.Go.Count - 1) nav.Pos++;
                else if (MstMessage("Search completed. Do you want to search again?", "Search",
                             MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes) nav.Pos = 0;
            }
            else nav.Pos = nav.Pos > 0 ? nav.Pos - 1 : nav.Go.Count - 1;
            if (nav.Pos >= 0 && nav.Pos < nav.Go.Count) nav.Go[nav.Pos]();
            FindCounter(nav, counter);
        }

        // Realize the path to a tree node, select it, and scroll it into view.
        // These trees virtualize their rows, so a match that is currently scrolled
        // out of view has no generated container yet: looking it up returns null and
        // BringIntoView cannot act on it. To handle that, first scroll the viewport
        // proportionally to the match's position (which generates the row), then on
        // the following layout pass grab the now-realized container, select it and
        // centre it. The proportional scroll is unit-agnostic (it scales by the
        // scroll viewer's own scrollable range), so it works whether the panel scrolls
        // by item or by pixel and regardless of how many roots the tree has.
        // The match's ancestors are already expanded on their models by the caller.
        // These trees realize a container for every node under an expanded branch, so
        // once layout settles the target's container exists regardless of scroll
        // position. Find it in the visual tree, select it, and bring it into view.
        // Retry across a few layout passes in case container generation lags a frame.
        private static void RevealTreeNode(TreeView tree, object target) => SelectRealizedNode(tree, target, 8);

        private static void SelectRealizedNode(TreeView tree, object target, int attemptsLeft)
        {
            tree.Dispatcher.BeginInvoke(new Action(() =>
            {
                try
                {
                    tree.UpdateLayout();
                    var t = FindRealizedTreeItem(tree, target);
                    if (t == null)
                    {
                        if (attemptsLeft > 1) SelectRealizedNode(tree, target, attemptsLeft - 1);
                        return;
                    }
                    t.IsSelected = true;
                    t.BringIntoView();
                }
                catch { }
            }), System.Windows.Threading.DispatcherPriority.Background);
        }

        // Depth-first search of the visual tree for the realized TreeViewItem container
        // whose bound data item is exactly the target node.
        private static TreeViewItem? FindRealizedTreeItem(DependencyObject root, object dataItem)
        {
            int n = VisualTreeHelper.GetChildrenCount(root);
            for (int i = 0; i < n; i++)
            {
                var child = VisualTreeHelper.GetChild(root, i);
                if (child is TreeViewItem tvi && ReferenceEquals(tvi.DataContext, dataItem))
                    return tvi;
                var found = FindRealizedTreeItem(child, dataItem);
                if (found != null) return found;
            }
            return null;
        }

        private void RevealFeat(FeatureNode n)
        {
            if (FeatTree == null) return;
            for (var p = n.Parent; p != null; p = p.Parent) p.IsExpanded = true;   // open the path on the model
            RevealTreeNode(FeatTree, n);
        }
        private void RevealReg(RegNode n)
        {
            if (RegTree == null) return;
            for (var p = n.Parent; p != null; p = p.Parent) p.IsExpanded = true;
            RevealTreeNode(RegTree, n);
        }
        private void RevealDir(DirNode n)
        {
            if (DirTree == null) return;
            for (var p = n.Parent; p != null; p = p.Parent) p.IsExpanded = true;
            RevealTreeNode(DirTree, n);
        }

        // ----- Type-to-find on the Features tree -----
        // A package can carry hundreds of components with generated names, and scrolling to one is
        // the slow way to reach it. Typing jumps to the next node whose name starts with what was
        // typed, the way Explorer does: keep typing to narrow, or press the same letter again to
        // step through the matches.
        private string _featTypeBuf = "";
        private DateTime _featTypeAt = DateTime.MinValue;

        private void FeatTree_TextInput(object sender, TextCompositionEventArgs e)
        {
            if (FeatTree?.ItemsSource == null) return;
            string ch = e.Text;
            // Space would otherwise start a buffer that matches nothing, and it is the key that
            // toggles expansion, so it is left to the tree.
            if (ch.Length != 1 || char.IsControl(ch[0]) || ch == " ") return;

            // A pause means a new search rather than a continuation, which is what makes typing
            // "pu" find puttygen while pressing "p" twice steps p -> p.
            bool lapsed = (DateTime.UtcNow - _featTypeAt).TotalMilliseconds > 1000;
            bool repeat = !lapsed && _featTypeBuf.Length == 1
                          && string.Equals(_featTypeBuf, ch, StringComparison.OrdinalIgnoreCase);
            _featTypeBuf = lapsed || repeat ? ch : _featTypeBuf + ch;
            _featTypeAt  = DateTime.UtcNow;

            // Flattened in display order, so "next" means the next one down the screen.
            var flat = new List<FeatureNode>();
            void Walk(System.Collections.Generic.IEnumerable<FeatureNode> list)
            {
                foreach (var nd in list) { flat.Add(nd); Walk(nd.Children); }
            }
            if (FeatTree.ItemsSource is System.Collections.IEnumerable roots)
                Walk(roots.OfType<FeatureNode>());
            if (flat.Count == 0) return;

            // Start after whatever is selected so a repeated letter advances instead of sticking.
            int from = 0;
            if (FeatTree.SelectedItem is FeatureNode sel)
            {
                int ix = flat.IndexOf(sel);
                if (ix >= 0) from = repeat ? ix + 1 : ix;
            }

            FeatureNode? hit = null;
            for (int i = 0; i < flat.Count; i++)
            {
                var nd = flat[(from + i) % flat.Count];
                if (nd.Display.StartsWith(_featTypeBuf, StringComparison.OrdinalIgnoreCase)) { hit = nd; break; }
            }
            if (hit == null) return;

            for (var p = hit.Parent; p != null; p = p.Parent) p.IsExpanded = true;
            RevealTreeNode(FeatTree, hit);
            e.Handled = true;
        }

        // ----- Custom actions (list) -----
        private void CaSearch_Changed(object sender, TextChangedEventArgs e) => ApplyCaFind();
        private void CaSearch_Key(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { FindStep(_caFind, CaSearchCount, 1); e.Handled = true; } }
        private void CaPrev_Click(object sender, RoutedEventArgs e) => FindStep(_caFind, CaSearchCount, -1);
        private void CaNext_Click(object sender, RoutedEventArgs e) => FindStep(_caFind, CaSearchCount, 1);
        private void ApplyCaFind()
        {
            SearchPh(CaSearch, CaSearchPh);
            _caFind.Go.Clear();
            string q = CaSearch?.Text.Trim() ?? "";
            if (_caAll != null && q.Length > 0)
                for (int i = 0; i < _caAll.Count; i++)
                {
                    var it = _caAll[i];
                    if (Hit(it.Action, q) || Hit(it.Kind, q))
                        _caFind.Go.Add(() => it.IsSelected = true);
                }
            FindReset(_caFind, CaSearchCount);
            if (q.Length == 0 && CaSearchCount != null) CaSearchCount.Text = "";
        }

        // ----- Sequences (grid) -----
        private void SeqSearch_Changed(object sender, TextChangedEventArgs e) => ApplySeqFind();
        private void SeqSearch_Key(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { FindStep(_seqFind, SeqSearchCount, 1); e.Handled = true; } }
        private void SeqPrev_Click(object sender, RoutedEventArgs e) => FindStep(_seqFind, SeqSearchCount, -1);
        private void SeqNext_Click(object sender, RoutedEventArgs e) => FindStep(_seqFind, SeqSearchCount, 1);
        private void ApplySeqFind()
        {
            SearchPh(SeqSearch, SeqSearchPh);
            _seqFind.Go.Clear();
            string q = SeqSearch?.Text.Trim() ?? "";
            if (_seqAll != null && q.Length > 0)
                for (int i = 0; i < _seqAll.Count; i++)
                {
                    var it = _seqAll[i]; int idx = i;
                    if (Hit(it.Action, q) || Hit(it.Condition, q) || Hit(it.Seq, q))
                        _seqFind.Go.Add(() => { if (SeqList != null && idx < SeqList.Items.Count) { SeqList.SelectedIndex = idx; SeqList.ScrollIntoView(SeqList.Items[idx]); } });
                }
            FindReset(_seqFind, SeqSearchCount);
            if (q.Length == 0 && SeqSearchCount != null) SeqSearchCount.Text = "";
        }

        // ----- Features (tree) -----
        private void FeatSearch_Changed(object sender, TextChangedEventArgs e)
        {
            SearchPh(FeatSearch, FeatSearchPh);
            _featFind.Go.Clear();
            string q = FeatSearch?.Text.Trim() ?? "";
            if (q.Length > 0 && _featRoots != null)
                foreach (var root in _featRoots) CollectFeatFind(root, q);
            FindReset(_featFind, FeatSearchCount);
            if (q.Length == 0 && FeatSearchCount != null) FeatSearchCount.Text = "";
        }
        private void FeatSearch_Key(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { FindStep(_featFind, FeatSearchCount, 1); e.Handled = true; } }
        private void FeatPrev_Click(object sender, RoutedEventArgs e) => FindStep(_featFind, FeatSearchCount, -1);
        private void FeatNext_Click(object sender, RoutedEventArgs e) => FindStep(_featFind, FeatSearchCount, 1);
        private void CollectFeatFind(FeatureNode node, string q)
        {
            bool m = node.Kind == FeatNodeKind.Feature ? Hit(node.Display, q)
                   : node.Kind == FeatNodeKind.Component && (Hit(node.ComponentKey, q) || Hit(node.Display, q) || Hit(node.Subtitle, q));
            if (m) { var n = node; _featFind.Go.Add(() => RevealFeat(n)); }
            foreach (var ch in node.Children) CollectFeatFind(ch, q);
        }

        // ----- Registry (tree) -----
        private void RegSearch_Changed(object sender, TextChangedEventArgs e)
        {
            SearchPh(RegSearch, RegSearchPh);
            _regFind.Go.Clear();
            string q = RegSearch?.Text.Trim() ?? "";
            if (q.Length > 0 && _regRoots != null)
                foreach (var root in _regRoots) CollectRegFind(root, q);
            FindReset(_regFind, RegSearchCount);
            if (q.Length == 0 && RegSearchCount != null) RegSearchCount.Text = "";
        }
        private void RegSearch_Key(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { FindStep(_regFind, RegSearchCount, 1); e.Handled = true; } }
        private void RegPrev_Click(object sender, RoutedEventArgs e) => FindStep(_regFind, RegSearchCount, -1);
        private void RegNext_Click(object sender, RoutedEventArgs e) => FindStep(_regFind, RegSearchCount, 1);
        private void CollectRegFind(RegNode node, string q)
        {
            if (Hit(node.Display, q) || Hit(node.FullPath, q))
            { var n = node; _regFind.Go.Add(() => RevealReg(n)); }
            foreach (var v in node.Values)
                if (v.RowState != DataRowState.Deleted && (Hit(Cv(v["Name"]), q) || Hit(Cv(v["Value"]), q)))
                { var n = node; var vr = v; _regFind.Go.Add(() => { RevealReg(n); RefreshRegValues(n); SelectRegValueRow(vr); }); }
            foreach (var ch in node.Children) CollectRegFind(ch, q);
        }

        private void SelectRegValueRow(System.Data.DataRow row)
        {
            if (RegValueList?.ItemsSource is not System.Collections.IEnumerable items) return;
            foreach (var o in items)
                if (o is RegValueRow rv && ReferenceEquals(rv.Row, row))
                {
                    RegValueList.SelectedItem = o;
                    RegValueList.UpdateLayout();
                    RegValueList.ScrollIntoView(o);
                    return;
                }
        }

        // ----- Files (folder tree) -----
        private void FileSearch_Changed(object sender, TextChangedEventArgs e)
        {
            SearchPh(FileSearch, FileSearchPh);
            _fileFind.Go.Clear();
            string q = FileSearch?.Text.Trim() ?? "";
            if (q.Length > 0 && _dirRoots != null)
                foreach (var root in _dirRoots) CollectDirFind(root, q);
            FindReset(_fileFind, FileSearchCount);
            if (q.Length == 0 && FileSearchCount != null) FileSearchCount.Text = "";
        }
        private void FileSearch_Key(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { FindStep(_fileFind, FileSearchCount, 1); e.Handled = true; } }
        private void FilePrev_Click(object sender, RoutedEventArgs e) => FindStep(_fileFind, FileSearchCount, -1);
        private void FileNext_Click(object sender, RoutedEventArgs e) => FindStep(_fileFind, FileSearchCount, 1);
        private void CollectDirFind(DirNode node, string q)
        {
            if (Hit(node.Display, q) || Hit(node.Key, q))
            { var n = node; _fileFind.Go.Add(() => RevealDir(n)); }
            foreach (var f in node.Files)
                if (f.RowState != DataRowState.Deleted)
                {
                    string fn = Cv(f["FileName"]); int b = fn.IndexOf('|');
                    string lng = b >= 0 ? fn.Substring(b + 1) : fn;
                    string key = Cv(f["File"]);
                    if (Hit(lng, q) || Hit(key, q))
                    { var n = node; var fk = key; _fileFind.Go.Add(() => { RevealDir(n); PopulateDirFiles(n); SelectDirFileRow(fk); }); }
                }
            foreach (var ch in node.Children) CollectDirFind(ch, q);
        }

        private void PopulateDirFiles(DirNode node)
        {
            var rows = new System.Collections.ObjectModel.ObservableCollection<FileRow>();
            foreach (var dr in node.Files)
                if (dr.RowState != DataRowState.Deleted) rows.Add(new FileRow(dr, UpdateEditCount));
            _dirFileRows = rows;
            if (DirFileList != null) DirFileList.ItemsSource = rows;
        }

        private void SelectDirFileRow(string fileKey)
        {
            if (DirFileList?.ItemsSource is not System.Collections.IEnumerable items) return;
            foreach (var o in items)
                if (o is FileRow fr && string.Equals(fr.Key, fileKey, StringComparison.OrdinalIgnoreCase))
                {
                    DirFileList.SelectedItem = o;
                    DirFileList.UpdateLayout();
                    DirFileList.ScrollIntoView(o);
                    return;
                }
        }

        private void SeqList_RightDown(object sender, MouseButtonEventArgs e)
        {
            DependencyObject? d = e.OriginalSource as DependencyObject;
            while (d != null && d is not DataGridRow) d = VisualTreeHelper.GetParent(d);
            if (d is DataGridRow row)
            {
                row.IsSelected = true;
                if (SeqList != null) SeqList.SelectedItem = row.Item;
            }
        }

        private void SelectSeqByAction(string action)
        {
            if (SeqList?.ItemsSource is not System.Collections.IEnumerable items) return;
            foreach (var o in items)
                if (o is SeqRow s && string.Equals(s.Action, action, StringComparison.OrdinalIgnoreCase))
                { SeqList.SelectedItem = s; SeqList.ScrollIntoView(s); break; }
        }

        private void SeqNew_Click(object sender, RoutedEventArgs e)
        {
            string table = CurrentSeqTable();
            var st = table.Length > 0 ? EnsureTableCached(table) : null;
            if (st == null)
            { MstMessage("Select a sequence table first.", "New Action", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            int maxSeq = 0;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (int.TryParse(Cv(r["Sequence"]), out var s) && s > maxSeq) maxSeq = s;
            }
            var res = PromptSequence("New Action", "", (maxSeq + 100).ToString(), "");
            if (res == null) return;
            var (action, seq, cond) = res.Value;
            action = action.Trim();
            if (action.Length == 0)
            { MstMessage("Enter an action name.", "New Action", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Action"]), action, StringComparison.OrdinalIgnoreCase))
                { MstMessage($"\u201C{action}\u201D is already in this sequence.", "New Action", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            }
            var nr = st.Data.NewRow();
            nr["Action"] = action;
            if (st.Data.Columns.Contains("Sequence"))  nr["Sequence"]  = seq.Trim().Length > 0 ? (object)seq.Trim() : DBNull.Value;
            if (st.Data.Columns.Contains("Condition")) nr["Condition"] = cond.Length > 0 ? (object)cond : DBNull.Value;
            st.Data.Rows.Add(nr);
            UpdateEditCount();
            RefreshSeqList();
            SelectSeqByAction(action);
        }

        private void SeqList_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (SeqList?.SelectedItem is SeqRow sr) ShowSeqEditor(sr);
            else ClearSeqEditor();
        }

        private SeqRow? _seqEditItem;
        private bool _seqEditorLoading;

        private void ClearSeqEditor()
        {
            _seqEditItem = null;
            if (SeqEditorHost != null) SeqEditorHost.Content = null;
        }

        // Builds the editable sequenced-action form directly in the right-hand panel.
        // Fields commit on focus loss. The Action name is kept unique within the current
        // sequence table (a duplicate reverts). Changing the Sequence number updates the
        // value in place; use Move Up / Move Down (or reopen) to reorder the list.
        private void ShowSeqEditor(SeqRow sr)
        {
            if (SeqEditorHost == null) return;
            _seqEditorLoading = true;
            _seqEditItem = sr;

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")      as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")   as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(72) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            TextBlock Lbl(string t) => new TextBlock
            {
                Text = t, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
            };
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = Lbl(label);
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }

            var (acField, acBox) = MakeRoundedField(sr.Action, boxBg, boxBdr, valFg, false,
                () => PickFromPackage("Select an action", SeqActionChoices()));
            AddRow("Action", acField);

            var (seqField, seqBox) = MakeRoundedField(sr.Seq, boxBg, boxBdr, valFg, false, null);
            AddRow("Sequence #", seqField);

            var (condField, condBox) = MakeRoundedField(sr.Condition, boxBg, boxBdr, valFg, true, null);
            AddRow("Condition", condField);

            void CommitAction()
            {
                if (_seqEditorLoading || _seqEditItem == null) return;
                var row = _seqEditItem.Row;
                if (!row.Table.Columns.Contains("Action")) return;
                string newAction = acBox.Text.Trim();
                string oldAction = Cv(row["Action"]);
                if (newAction.Length == 0) { acBox.Text = oldAction; return; }
                if (string.Equals(newAction, oldAction, StringComparison.OrdinalIgnoreCase)) return;
                string tbl = CurrentSeqTable();
                var st = tbl.Length > 0 ? EnsureTableCached(tbl) : null;
                if (st != null)
                    foreach (DataRow r in st.Data.Rows)
                    {
                        if (r.RowState == DataRowState.Deleted || ReferenceEquals(r, row)) continue;
                        if (string.Equals(Cv(r["Action"]), newAction, StringComparison.OrdinalIgnoreCase))
                        { acBox.Text = oldAction; return; }   // already in this sequence: revert
                    }
                try { row["Action"] = newAction; }
                catch { acBox.Text = oldAction; return; }
                _seqEditItem.UpdateAction(newAction);
                UpdateEditCount();
            }

            void CommitSeq()
            {
                if (_seqEditorLoading || _seqEditItem == null) return;
                var row = _seqEditItem.Row;
                if (!row.Table.Columns.Contains("Sequence")) return;
                string v = seqBox.Text.Trim();
                if (string.Equals(v, Cv(row["Sequence"]), StringComparison.Ordinal)) return;
                try { row["Sequence"] = v.Length > 0 ? (object)v : DBNull.Value; }
                catch { return; }
                _seqEditItem.UpdateSeq(v);
                UpdateEditCount();
            }

            void CommitCondition()
            {
                if (_seqEditorLoading || _seqEditItem == null) return;
                var row = _seqEditItem.Row;
                if (!row.Table.Columns.Contains("Condition")) return;
                string v = condBox.Text;
                if (string.Equals(v, Cv(row["Condition"]), StringComparison.Ordinal)) return;
                try { row["Condition"] = v.Length > 0 ? (object)v : DBNull.Value; }
                catch { return; }
                _seqEditItem.UpdateCondition(v);
                UpdateEditCount();
            }

            acBox.LostFocus   += (_, _) => CommitAction();
            seqBox.LostFocus  += (_, _) => CommitSeq();
            condBox.LostFocus += (_, _) => CommitCondition();

            SeqEditorHost.Content = grid;
            _seqEditorLoading = false;
        }

        private void SeqDelete_Click(object sender, RoutedEventArgs e)
        {
            if (SeqList?.SelectedItem is not SeqRow sr) return;
            if (MstMessage($"Remove \u201C{sr.Action}\u201D from this sequence?",
                    "Delete Action", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
            if (sr.Row.RowState != DataRowState.Deleted) sr.Row.Delete();
            UpdateEditCount();
            RefreshSeqList();
        }

        private void SeqMoveUp_Click(object sender, RoutedEventArgs e)   => SeqMove(-1);
        private void SeqMoveDown_Click(object sender, RoutedEventArgs e) => SeqMove(+1);

        // Reorder by swapping the selected row's Sequence number with its neighbour
        // in display order; equal numbers are nudged so the move always takes effect.
        private void SeqMove(int dir)
        {
            if (SeqList?.SelectedItem is not SeqRow sr) return;
            if (SeqList.ItemsSource is not System.Collections.IEnumerable src) return;
            var list = src.Cast<SeqRow>().ToList();
            int idx = list.FindIndex(x => ReferenceEquals(x, sr));
            int j = idx + dir;
            if (idx < 0 || j < 0 || j >= list.Count) return;
            var other = list[j];
            if (!sr.Row.Table.Columns.Contains("Sequence")) return;

            int sa = int.TryParse(sr.Seq, out var x) ? x : 0;
            int sb = int.TryParse(other.Seq, out var y) ? y : 0;
            if (sa == sb)
                sr.Row["Sequence"] = (sb + (dir < 0 ? -1 : 1)).ToString();
            else
            {
                sr.Row["Sequence"]    = sb.ToString();
                other.Row["Sequence"] = sa.ToString();
            }
            UpdateEditCount();
            RefreshSeqList();
            SelectSeqByAction(sr.Action);
        }

        // Actions worth picking from the package: custom actions and dialogs. Standard
        // action names (InstallFiles, etc.) can simply be typed into the Action field.
        private System.Collections.Generic.List<(string value, string display)> SeqActionChoices()
        {
            var outp = new System.Collections.Generic.List<(string value, string display)>();
            var ca = EnsureTableCached("CustomAction");
            if (ca != null)
                foreach (DataRow r in ca.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string k = Cv(r["Action"]);
                    if (k.Length > 0) outp.Add((k, k + "   (custom action)"));
                }
            var dlg = EnsureTableCached("Dialog");
            if (dlg != null && dlg.Data.Columns.Contains("Dialog"))
                foreach (DataRow r in dlg.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string k = Cv(r["Dialog"]);
                    if (k.Length > 0) outp.Add((k, k + "   (dialog)"));
                }
            outp.Sort((a, b) => string.Compare(a.display, b.display, StringComparison.OrdinalIgnoreCase));
            return outp;
        }

        private (string action, string seq, string condition)? PromptSequence(
            string title, string action, string seq, string condition)
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 500; win.MaxWidth = 500;

            int r = 0;
            void AddLabel(string text, FrameworkElement field)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(0, 10, 0, 0)
                };
                field.Margin = new Thickness(0, 6, 0, 0);
                Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0);
                Grid.SetRow(field, r); Grid.SetColumn(field, 1);
                cg.Children.Add(lbl); cg.Children.Add(field); r++;
            }

            var (acField, acBox) = MakeRoundedField(action, boxBg, boxBdr, valFg, false,
                () => PickFromPackage("Select an action", SeqActionChoices()));
            AddLabel("Action", acField);
            var (seqField, seqBox) = MakeRoundedField(seq, boxBg, boxBdr, valFg, false, null);
            AddLabel("Sequence #", seqField);
            var (condField, condBox) = MakeRoundedField(condition, boxBg, boxBdr, valFg, true, null);
            AddLabel("Condition", condField);

            NdAddSpacer(cg, r++);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            (string, string, string)? result = null;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () => { result = (acBox.Text, seqBox.Text, condBox.Text); win.Close(); }),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);

            acBox.Loaded += (_, _) => { acBox.Focus(); };
            win.ShowDialog();
            return result;
        }

        // ══ Upgrade (related-product detection rules: list + decoded detail) ═
        private TableState? _upgSt;

        private static string UpgRangeText(DataRow r)
        {
            string Cl(string c) => r.Table.Columns.Contains(c) && r[c] != DBNull.Value ? r[c].ToString() ?? "" : "";
            string lo = Cl("VersionMin"), hi = Cl("VersionMax");
            int a = int.TryParse(Cl("Attributes"), out var av) ? av : 0;
            bool loInc = (a & 0x100) != 0, hiInc = (a & 0x200) != 0;
            if (lo.Length == 0 && hi.Length == 0) return "any version";
            if (lo.Length > 0 && hi.Length > 0)
            {
                string open = loInc ? "[" : "(";
                string close = hiInc ? "]" : ")";
                return open + lo + " - " + hi + close;
            }
            if (lo.Length > 0) return (loInc ? "\u2265" : ">") + " " + lo;
            return (hiInc ? "\u2264" : "<") + " " + hi;
        }

        /// <summary>
        /// The arrow shown beside an Upgrade row. A row with a minimum and no maximum matches
        /// versions at or above this build, which can only be a NEWER product already installed:
        /// that is the downgrade guard, so it gets a down arrow. Anything with a maximum covers
        /// older builds and is a real upgrade. Read from the range rather than from the
        /// ActionProperty name, since WIX_DOWNGRADE_DETECTED is a WiX convention and a
        /// hand-authored package is free to call it anything.
        /// </summary>
        private static string UpgArrow(DataRow r)
        {
            string Cl(string c) => r.Table.Columns.Contains(c) && r[c] != DBNull.Value ? r[c].ToString() ?? "" : "";
            bool hasLo = Cl("VersionMin").Length > 0, hasHi = Cl("VersionMax").Length > 0;
            return hasLo && !hasHi ? "\u2B07" : "\u2B06";
        }

        private void ShowUpgradeForm(TableState upgSt)
        {
            _upgSt = upgSt;
            var items = new System.Collections.ObjectModel.ObservableCollection<UpgItem>();
            foreach (DataRow r in upgSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                string code = Cv(r["UpgradeCode"]);
                string ap = upgSt.Data.Columns.Contains("ActionProperty") ? Cv(r["ActionProperty"]) : "";
                string title = ap.Length > 0 ? ap : (code.Length > 0 ? code : "(upgrade)");
                string sub = UpgRangeText(r) + (ap.Length > 0 && code.Length > 0 ? "   ·   " + code : "");
                items.Add(new UpgItem(r, title, sub, UpgArrow(r)));
            }
            if (UpgList != null) UpgList.ItemsSource = items;
            if (UpgCount != null) UpgCount.Text = items.Count == 1 ? "1 entry" : $"{items.Count} entries";
            ClearUpgEditor();
            if (FormUpgradePanel != null) FormUpgradePanel.Visibility = Visibility.Visible;
            if (UpgList != null && UpgList.Items.Count > 0 && UpgList.SelectedItem == null)
                UpgList.SelectedIndex = 0;
        }

