        // Builds the editable upgrade-entry form directly in the right-hand panel.
        // Text fields commit on focus loss (the Upgrade key is composite, so we avoid
        // rewriting it on every keystroke); the option checkboxes commit immediately.
        private void ShowUpgEditor(UpgItem item)
        {
            if (UpgEditorHost == null) return;
            _upgEditorLoading = true;
            _upgEditRow = item.Row;
            var data = ReadUpgradeData(item.Row);

            Brush boxBg  = (Application.Current.TryFindResource("InputBgBrush")      as Brush) ?? Brushes.White;
            Brush boxBdr = (Application.Current.TryFindResource("BorderMainBrush")   as Brush) ?? Brushes.Gray;
            Brush lblFg  = (Application.Current.TryFindResource("TextSecondaryBrush") as Brush) ?? Brushes.Gray;
            Brush valFg  = (Application.Current.TryFindResource("TextPrimaryBrush")   as Brush) ?? Brushes.Black;

            var grid = new Grid { Margin = new Thickness(12, 10, 12, 10) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(112) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            TextBlock Lbl(string t) => new TextBlock
            {
                Text = t, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                Margin = new Thickness(0, 9, 8, 0), VerticalAlignment = VerticalAlignment.Top
            };
            int rr = 0;
            void AddRow(string label, FrameworkElement field)
            {
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = Lbl(label);
                field.Margin = new Thickness(0, 4, 0, 4);
                Grid.SetRow(l, rr); Grid.SetColumn(l, 0);
                Grid.SetRow(field, rr); Grid.SetColumn(field, 1);
                grid.Children.Add(l); grid.Children.Add(field);
                rr++;
            }

            var (codeField, codeBox) = MakeRoundedField(data.UpgradeCode, boxBg, boxBdr, valFg, false, null);
            AddRow("Upgrade code", codeField);
            var (apField, apBox) = MakeRoundedField(data.ActionProperty, boxBg, boxBdr, valFg, false, null);
            AddRow("Action property", apField);
            var (minField, minBox) = MakeRoundedField(data.VersionMin, boxBg, boxBdr, valFg, false, null);
            AddRow("Version minimum", minField);
            var (maxField, maxBox) = MakeRoundedField(data.VersionMax, boxBg, boxBdr, valFg, false, null);
            AddRow("Version maximum", maxField);
            var (langField, langBox) = MakeRoundedField(data.Language, boxBg, boxBdr, valFg, false, null);
            AddRow("Language", langField);
            var (remField, remBox) = MakeRoundedField(data.Remove, boxBg, boxBdr, valFg, false, null);
            AddRow("Features to remove", remField);

            CheckBox Chk(string label, bool on) => new CheckBox
            {
                Content = label, IsChecked = on, Foreground = lblFg, FontSize = 12,
                Width = 230, Margin = new Thickness(0, 4, 12, 4), VerticalContentAlignment = VerticalAlignment.Center
            };
            var cMig   = Chk("Migrate features", data.MigrateFeatures);
            var cDet   = Chk("Detect only (do not remove)", data.OnlyDetect);
            var cIgn   = Chk("Ignore remove failure", data.IgnoreRemoveFailure);
            var cMinI  = Chk("Minimum version inclusive", data.MinInclusive);
            var cMaxI  = Chk("Maximum version inclusive", data.MaxInclusive);
            var cLangX = Chk("Languages exclusive", data.LanguagesExclusive);
            var opts = new WrapPanel { Orientation = Orientation.Horizontal };
            foreach (var c in new[] { cMig, cDet, cIgn, cMinI, cMaxI, cLangX }) opts.Children.Add(c);
            AddRow("Options", opts);

            UpgradeData ReadControls() => new UpgradeData
            {
                UpgradeCode = codeBox.Text.Trim(),
                ActionProperty = apBox.Text.Trim(),
                VersionMin = minBox.Text.Trim(),
                VersionMax = maxBox.Text.Trim(),
                Language = langBox.Text.Trim(),
                Remove = remBox.Text.Trim(),
                MigrateFeatures = cMig.IsChecked == true,
                OnlyDetect = cDet.IsChecked == true,
                IgnoreRemoveFailure = cIgn.IsChecked == true,
                MinInclusive = cMinI.IsChecked == true,
                MaxInclusive = cMaxI.IsChecked == true,
                LanguagesExclusive = cLangX.IsChecked == true
            };

            void Commit()
            {
                if (_upgEditorLoading || _upgEditRow == null) return;
                var d = ReadControls();
                try { WriteUpgradeData(_upgEditRow, d); } catch { }
                UpdateEditCount();
                string title = d.ActionProperty.Length > 0 ? d.ActionProperty
                             : (d.UpgradeCode.Length > 0 ? d.UpgradeCode : "(upgrade)");
                string sub = UpgRangeText(_upgEditRow) + (d.ActionProperty.Length > 0 && d.UpgradeCode.Length > 0 ? "   ·   " + d.UpgradeCode : "");
                // The arrow follows the range: clearing Version maximum on an upgrade row turns it
                // into a downgrade guard, and the icon has to say so without a reload.
                item.Update(title, sub, UpgArrow(_upgEditRow));
            }

            foreach (var b in new[] { codeBox, apBox, minBox, maxBox, langBox, remBox })
                b.LostFocus += (_, _) => Commit();
            foreach (var c in new[] { cMig, cDet, cIgn, cMinI, cMaxI, cLangX })
            { c.Checked += (_, _) => Commit(); c.Unchecked += (_, _) => Commit(); }

            UpgEditorHost.Content = grid;
            _upgEditorLoading = false;
        }

        private void UpgList_RightDown(object sender, MouseButtonEventArgs e)
        {
            DependencyObject? d = e.OriginalSource as DependencyObject;
            while (d != null && d is not ListBoxItem) d = VisualTreeHelper.GetParent(d);
            if (d is ListBoxItem li) { li.IsSelected = true; li.Focus(); }
        }

        private UpgradeData ReadUpgradeData(DataRow r)
        {
            string Cl(string c) => r.Table.Columns.Contains(c) && r[c] != DBNull.Value ? r[c].ToString() ?? "" : "";
            int a = int.TryParse(Cl("Attributes"), out var av) ? av : 0;
            return new UpgradeData
            {
                UpgradeCode = Cl("UpgradeCode"),
                VersionMin = Cl("VersionMin"),
                VersionMax = Cl("VersionMax"),
                Language = Cl("Language"),
                ActionProperty = Cl("ActionProperty"),
                Remove = Cl("Remove"),
                MigrateFeatures = (a & 0x001) != 0,
                OnlyDetect = (a & 0x002) != 0,
                IgnoreRemoveFailure = (a & 0x004) != 0,
                MinInclusive = (a & 0x100) != 0,
                MaxInclusive = (a & 0x200) != 0,
                LanguagesExclusive = (a & 0x400) != 0
            };
        }

        private static int ComputeUpgradeAttributes(UpgradeData d)
        {
            int a = 0;
            if (d.MigrateFeatures)     a |= 0x001;
            if (d.OnlyDetect)          a |= 0x002;
            if (d.IgnoreRemoveFailure) a |= 0x004;
            if (d.MinInclusive)        a |= 0x100;
            if (d.MaxInclusive)        a |= 0x200;
            if (d.LanguagesExclusive)  a |= 0x400;
            return a;
        }

        private void WriteUpgradeData(DataRow r, UpgradeData d)
        {
            void Set(string c, string v, bool required)
            {
                if (!r.Table.Columns.Contains(c)) return;
                r[c] = (v.Length > 0 || required) ? (object)v : DBNull.Value;
            }
            Set("UpgradeCode",    d.UpgradeCode,    true);
            Set("VersionMin",     d.VersionMin,     false);
            Set("VersionMax",     d.VersionMax,     false);
            Set("Language",       d.Language,       false);
            Set("ActionProperty", d.ActionProperty, true);
            Set("Remove",         d.Remove,         false);
            if (r.Table.Columns.Contains("Attributes")) r["Attributes"] = ComputeUpgradeAttributes(d).ToString();
        }

        private void UpgNew_Click(object sender, RoutedEventArgs e)
        {
            var upgSt = _upgSt ?? EnsureTableCached("Upgrade");
            if (upgSt == null)
            { MstMessage("This MSI has no Upgrade table.", "New Upgrade Entry", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            var init = new UpgradeData { MigrateFeatures = true, MinInclusive = true };
            var res = PromptUpgrade("New Upgrade Entry", init);
            if (res == null) return;
            if (res.UpgradeCode.Trim().Length == 0)
            { MstMessage("Enter an upgrade code.", "New Upgrade Entry", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            var nr = upgSt.Data.NewRow();
            WriteUpgradeData(nr, res);
            upgSt.Data.Rows.Add(nr);
            UpdateEditCount();
            ShowUpgradeForm(upgSt);
            SelectUpg(nr);
        }

        private void UpgDelete_Click(object sender, RoutedEventArgs e)
        {
            if (UpgList?.SelectedItem is not UpgItem it) return;
            var upgSt = _upgSt ?? EnsureTableCached("Upgrade");
            if (upgSt == null) return;
            if (MstMessage($"Delete this upgrade entry ({it.Title})?",
                    "Delete Upgrade Entry", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
            if (it.Row.RowState != DataRowState.Deleted) it.Row.Delete();
            UpdateEditCount();
            ShowUpgradeForm(upgSt);
        }

        private void SelectUpg(DataRow row)
        {
            if (UpgList?.ItemsSource is not System.Collections.IEnumerable items) return;
            foreach (var o in items)
                if (o is UpgItem u && ReferenceEquals(u.Row, row))
                { UpgList.SelectedItem = u; UpgList.ScrollIntoView(u); break; }
        }

        private UpgradeData? PromptUpgrade(string title, UpgradeData init)
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 540; win.MaxWidth = 540;

            int r = 0;
            void AddStacked(string text, FrameworkElement field, bool first = false)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, Margin = new Thickness(0, first ? 0 : 10, 0, 4)
                };
                Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0); Grid.SetColumnSpan(lbl, 2);
                cg.Children.Add(lbl); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(field, r); Grid.SetColumn(field, 0); Grid.SetColumnSpan(field, 2);
                cg.Children.Add(field); r++;
            }
            CheckBox Chk(string label, bool on) => new CheckBox
            {
                Content = label, IsChecked = on, Foreground = lblFg, FontSize = 12,
                Width = 250, Margin = new Thickness(0, 4, 12, 4), VerticalContentAlignment = VerticalAlignment.Center
            };

            var (codeField, codeBox) = MakeRoundedField(init.UpgradeCode, boxBg, boxBdr, valFg, false, null);
            AddStacked("Upgrade code (GUID of the related product)", codeField, true);
            var (apField, apBox) = MakeRoundedField(init.ActionProperty, boxBg, boxBdr, valFg, false, null);
            AddStacked("Action property (receives found product codes)", apField);
            var (minField, minBox) = MakeRoundedField(init.VersionMin, boxBg, boxBdr, valFg, false, null);
            AddStacked("Version minimum (optional)", minField);
            var (maxField, maxBox) = MakeRoundedField(init.VersionMax, boxBg, boxBdr, valFg, false, null);
            AddStacked("Version maximum (optional)", maxField);
            var (langField, langBox) = MakeRoundedField(init.Language, boxBg, boxBdr, valFg, false, null);
            AddStacked("Language (optional)", langField);
            var (remField, remBox) = MakeRoundedField(init.Remove, boxBg, boxBdr, valFg, false, null);
            AddStacked("Features to remove (blank = all features)", remField);

            var cMig   = Chk("Migrate features", init.MigrateFeatures);
            var cDet   = Chk("Detect only (do not remove)", init.OnlyDetect);
            var cIgn   = Chk("Ignore remove failure", init.IgnoreRemoveFailure);
            var cMinI  = Chk("Minimum version inclusive", init.MinInclusive);
            var cMaxI  = Chk("Maximum version inclusive", init.MaxInclusive);
            var cLangX = Chk("Languages exclusive", init.LanguagesExclusive);
            var opts = new WrapPanel { Orientation = Orientation.Horizontal };
            foreach (var c in new[] { cMig, cDet, cIgn, cMinI, cMaxI, cLangX }) opts.Children.Add(c);
            AddStacked("Options", opts);

            NdAddSpacer(cg, r++);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            UpgradeData? result = null;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () =>
                {
                    result = new UpgradeData
                    {
                        UpgradeCode = codeBox.Text.Trim(),
                        ActionProperty = apBox.Text.Trim(),
                        VersionMin = minBox.Text.Trim(),
                        VersionMax = maxBox.Text.Trim(),
                        Language = langBox.Text.Trim(),
                        Remove = remBox.Text.Trim(),
                        MigrateFeatures = cMig.IsChecked == true,
                        OnlyDetect = cDet.IsChecked == true,
                        IgnoreRemoveFailure = cIgn.IsChecked == true,
                        MinInclusive = cMinI.IsChecked == true,
                        MaxInclusive = cMaxI.IsChecked == true,
                        LanguagesExclusive = cLangX.IsChecked == true
                    };
                    win.Close();
                }),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 0); Grid.SetColumnSpan(btns, 2); cg.Children.Add(btns);

            codeBox.Loaded += (_, _) => { codeBox.Focus(); };
            win.ShowDialog();
            return result;
        }

        private void FeatTree_RightDown(object sender, MouseButtonEventArgs e)
        {
            DependencyObject? d = e.OriginalSource as DependencyObject;
            while (d != null && d is not TreeViewItem) d = VisualTreeHelper.GetParent(d);
            if (d is TreeViewItem tvi) { tvi.IsSelected = true; tvi.Focus(); }
        }

        // Show only the actions that make sense for the right-clicked node:
        // feature actions on a feature, component actions on a component / category.
        private void FeatMenu_Opened(object sender, RoutedEventArgs e)
        {
            var node = SelectedFeat();
            // Each branch offers only what belongs to it. Registry Data and Shortcuts are absent
            // because the menu is suppressed on them entirely: each has its own tree, with its own
            // menu, in the pane beside this one.
            bool isFeature = node?.Kind == FeatNodeKind.Feature;
            bool isComp    = node?.Kind == FeatNodeKind.Component;
            bool isFiles   = node?.Kind == FeatNodeKind.FilesCat;

            void V(MenuItem? m, bool show) { if (m != null) m.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }
            void S(Separator? s, bool show) { if (s != null) s.Visibility = show ? Visibility.Visible : Visibility.Collapsed; }

            V(MiNewFeature, isFeature);
            V(MiEditFeature, isFeature);
            V(MiDeleteFeature, isFeature);
            V(MiRenameFeature, isFeature);
            S(SepFeat, isFeature);

            // Both live on the feature: New authors a component, Add links one the package already
            // has, and neither means anything with a component already selected.
            V(MiNewComponent, isFeature);
            V(MiAddComponent, isFeature);
            V(MiEditComponent, isComp);
            V(MiRemoveComponent, isComp);
            V(MiRenameComponent, isComp);

            // Adding files is a Files action, not a component-wide one, so it lives on that branch
            // alone. The Files branch is a leaf, so expanding and collapsing it means nothing.
            V(MiAddFiles, isFiles);
            S(SepFeatView, !isFiles);
            V(MiFeatExpand, !isFiles);
            V(MiFeatCollapse, !isFiles);
        }

        /// <summary>
        /// Suppresses the tree's own menu on the Registry Data and Shortcuts branches. Both now
        /// show a real tree in the pane beside this one, each carrying the same menu as its
        /// category, and a second different menu on the branch label only invited the wrong one.
        /// </summary>
        private void FeatTree_MenuOpening(object sender, ContextMenuEventArgs e)
        {
            var node = SelectedFeat();
            if (node != null && (node.Kind == FeatNodeKind.RegistryCat
                              || node.Kind == FeatNodeKind.ShortcutsCat))
                e.Handled = true;
        }

        // ── Editable component form (radio buttons / dropdown / text boxes) ──
        // No Apply/Revert: every edit writes straight back to the Component row.
        private string? _formComp;
        private string _compDirsBuiltFor = "\0";
        private bool _compFormLoading;     // true while populating, to suppress auto-save
        private bool _compHooked;          // change handlers wired once

        private DataRow? ComponentRow(string comp)
        {
            var compSt = EnsureTableCached("Component");
            if (compSt == null) return null;
            foreach (DataRow r in compSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Component"]), comp, StringComparison.OrdinalIgnoreCase)) return r;
            }
            return null;
        }

        private void HookComponentForm()
        {
            if (_compHooked) return;
            void Text(System.Windows.Controls.TextBox? t) { if (t != null) t.TextChanged += (_, _) => CommitIfEditing(); }
            void Check(System.Windows.Controls.Primitives.ToggleButton? c)
            { if (c != null) { c.Checked += (_, _) => CommitIfEditing(); c.Unchecked += (_, _) => CommitIfEditing(); } }

            Text(CompGuid); Text(CompKey); Text(CompCond);
            if (CompDest != null)
            {
                CompDest.AddHandler(System.Windows.Controls.Primitives.TextBoxBase.TextChangedEvent,
                    new System.Windows.Controls.TextChangedEventHandler((_, _) =>
                        { UpdateCompDestPath(); CommitIfEditing(); }));
                CompDest.SelectionChanged += (_, _) => { UpdateCompDestPath(); CommitIfEditing(); };
            }
            Check(CompLocLocal); Check(CompLocSource); Check(CompLocOptional);
            Check(CompPerm); Check(CompNever); Check(Comp64); Check(CompUninst); Check(CompShared);
            _compHooked = true;
        }

        /// <summary>
        /// A directory key resolved to where it actually installs, walking the Directory table up
        /// to the predefined folder at the top of the chain: MyLang becomes
        /// [ProgramFiles64Folder]FileCompare\Lang. Returns a plain note when the key is not a directory
        /// this package defines, because bracketing it would read as a root property that exists.
        /// </summary>
        private string DirectoryKeyPath(string dirKey)
        {
            string key = (dirKey ?? "").Trim();
            if (key.Length == 0) return "";
            if (FindTableRow("Directory", "Directory", key) == null)
                return key + " is not in the Directory table.";
            return ResolveDirectoryPath(key);
        }

        private void UpdateCompDestPath()
        {
            if (CompDestPath == null) return;
            CompDestPath.Text = DirectoryKeyPath(CompDest?.Text ?? "");
        }

        private void CommitIfEditing()
        {
            if (_compFormLoading) return;
            CommitComponentForm();
        }

        private void ShowComponentForm(string comp)
        {
            HookComponentForm();
            _formComp = comp;
            var cr = ComponentRow(comp);
            if (cr == null) { ShowGridView(); ShowComponentProperties(comp); return; }

            _compFormLoading = true;   // suppress auto-save while populating
            try
            {
                if (CompDest != null && _compDirsBuiltFor != _msiPath)
                {
                    CompDest.Items.Clear();
                    foreach (var d in PackageDirs()) CompDest.Items.Add(d.value);
                    _compDirsBuiltFor = _msiPath;
                }

                int a = int.TryParse(Cv(cr["Attributes"]), out var av) ? av : 0;
                if (CompDest != null) CompDest.Text = Cv(cr["Directory_"]);
                UpdateCompDestPath();
                if (CompGuid != null) CompGuid.Text = Cv(cr["ComponentId"]);
                if (CompKey  != null) CompKey.Text  = Cv(cr["KeyPath"]);
                if (CompCond != null) CompCond.Text = Cv(cr["Condition"]);
                if (CompLocOptional != null) CompLocOptional.IsChecked = (a & 2) != 0;
                if (CompLocSource   != null) CompLocSource.IsChecked   = (a & 2) == 0 && (a & 1) != 0;
                if (CompLocLocal    != null) CompLocLocal.IsChecked    = (a & 3) == 0;
                if (CompPerm   != null) CompPerm.IsChecked   = (a & 16)   != 0;
                if (CompNever  != null) CompNever.IsChecked  = (a & 128)  != 0;
                if (Comp64     != null) Comp64.IsChecked     = (a & 256)  != 0;
                if (CompUninst != null) CompUninst.IsChecked = (a & 1024) != 0;
                if (CompShared != null) CompShared.IsChecked = (a & 2048) != 0;
            }
            finally { _compFormLoading = false; }

            if (FeatCompTitle != null) FeatCompTitle.Text = $"{comp}  ·  component";
            ShowFormView();
        }

        // Write the live form state back to the component (called on every edit).
        private void CommitComponentForm()
        {
            if (_formComp == null) return;
            var cr = ComponentRow(_formComp);
            if (cr == null) return;
            int a = int.TryParse(Cv(cr["Attributes"]), out var av) ? av : 0;   // preserve hidden flags

            var d = new ComponentData
            {
                Directory   = CompDest?.Text?.Trim() ?? "",
                ComponentId = CompGuid?.Text?.Trim() ?? "",
                KeyPath     = CompKey?.Text?.Trim() ?? "",
                Condition   = CompCond?.Text?.Trim() ?? "",
                Location    = CompLocOptional?.IsChecked == true ? "Optional"
                            : CompLocSource?.IsChecked == true ? "Source" : "Local",
                Permanent            = CompPerm?.IsChecked == true,
                NeverOverwrite       = CompNever?.IsChecked == true,
                Bit64                = Comp64?.IsChecked == true,
                UninstallOnSupersede = CompUninst?.IsChecked == true,
                Shared               = CompShared?.IsChecked == true,
                // Flags not exposed in this form are preserved as they were.
                RegKeyPath        = (a & 4)   != 0,
                SharedDll         = (a & 8)   != 0,
                Odbc              = (a & 32)  != 0,
                Transitive        = (a & 64)  != 0,
                DisableReflection = (a & 512) != 0
            };
            WriteComponentData(cr, d);
            UpdateEditCount();
        }

        private static void SetFeatExpanded(FeatureNode n, bool ex)
        {
            n.IsExpanded = ex;
            foreach (var ch in n.Children) SetFeatExpanded(ch, ex);
        }

        private void FeatExpand_Click(object sender, RoutedEventArgs e)
        { if (SelectedFeat() is { } n) SetFeatExpanded(n, true); }

        private void FeatCollapse_Click(object sender, RoutedEventArgs e)
        {
            if (SelectedFeat() is not { } n) return;
            foreach (var ch in n.Children) SetFeatExpanded(ch, false);
            n.IsExpanded = false;
        }

        private void FeatNew_Click(object sender, RoutedEventArgs e)
        {
            var featSt = EnsureTableCached("Feature");
            if (featSt == null)
            { MstMessage("This MSI has no Feature table.", "New Feature", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            var parent = NearestFeature(SelectedFeat());   // may be null -> a root feature

            var res = PromptFeature("New Feature", new FeatureData());
            if (res == null) return;

            string title = res.Title.Length > 0 ? res.Title : "Feature";
            var nr = featSt.Data.NewRow();
            string key = UniqueKey(featSt.Data, "Feature", SanitizeKey("Feature_" + title));
            nr["Feature"] = key;
            if (featSt.Data.Columns.Contains("Feature_Parent") && parent != null) nr["Feature_Parent"] = parent.Key;
            WriteFeatureData(nr, res);
            featSt.Data.Rows.Add(nr);

            var child = new FeatureNode { Key = key, ParentKey = parent?.Key ?? "", FeatRow = nr,
                                          Display = key, Parent = parent };
            child.Subtitle = (title.Length > 0 && !string.Equals(title, key, StringComparison.Ordinal)) ? title : "";
            var siblings = parent?.Children ?? _featRoots;
            if (siblings != null)
            {
                int idx = 0;   // place among feature-kind siblings, before any components
                while (idx < siblings.Count && siblings[idx].Kind == FeatNodeKind.Feature &&
                       string.Compare(siblings[idx].Display, key, StringComparison.OrdinalIgnoreCase) < 0) idx++;
                siblings.Insert(idx, child);
            }
            if (parent != null) parent.IsExpanded = true;
            UpdateEditCount();
        }

        private void FeatEdit_Click(object sender, RoutedEventArgs e)
        {
            var node = NearestFeature(SelectedFeat());
            if (node?.FeatRow == null)
            { MstMessage("Select a feature to edit.", "Edit Feature", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            var res = PromptFeature("Edit Feature", ReadFeatureData(node.FeatRow));
            if (res == null) return;
            WriteFeatureData(node.FeatRow, res);
            node.Subtitle = (res.Title.Length > 0 && !string.Equals(res.Title, node.Key, StringComparison.Ordinal)) ? res.Title : "";
            UpdateEditCount();
            RefreshFeatSelection();
        }

        private void FeatDelete_Click(object sender, RoutedEventArgs e)
        {
            var node = NearestFeature(SelectedFeat());
            if (node?.FeatRow == null)
            { MstMessage("Select a feature to delete.", "Delete Feature", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            string nm = node.Subtitle.Length > 0 ? node.Subtitle : node.Display;
            if (MstMessage($"Delete feature \u201C{nm}\u201D, its subfeatures and their component links?",
                    "Delete Feature", MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;

            var fcSt = EnsureTableCached("FeatureComponents");
            DeleteFeatureSubtree(node, fcSt);
            if (node.Parent != null) node.Parent.Children.Remove(node);
            else _featRoots?.Remove(node);
            ClearDetail();
            if (FeatCompTitle != null) FeatCompTitle.Text = "Select a feature";
            UpdateEditCount();
        }

        private static void DeleteFeatureSubtree(FeatureNode n, TableState? fcSt)
        {
            // Remove this feature's component links.
            if (fcSt != null)
                foreach (DataRow r in fcSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (string.Equals(Cv(r["Feature_"]), n.Key, StringComparison.OrdinalIgnoreCase)) r.Delete();
                }
            foreach (var ch in n.Children) DeleteFeatureSubtree(ch, fcSt);
            if (n.FeatRow != null && n.FeatRow.RowState != DataRowState.Deleted) n.FeatRow.Delete();
        }

        /// <summary>
        /// Authors a new component and links it to the selected feature. Distinct from Add
        /// Component, which links one the package already has: this writes a Component row of its
        /// own, with a fresh GUID, the way InstallShield's New Component does.
        /// </summary>
        /// <summary>
        /// Renames a primary key and follows it through every column that points at it, using the
        /// schema's own foreign keys rather than a hand-written list of tables: Component alone is
        /// referenced by File, Registry, Shortcut, CreateFolder, Environment, ServiceInstall and a
        /// dozen others, and a rename that misses one leaves the package broken in a way nothing
        /// on screen would show. Only tables the package actually has are touched, and Feature's
        /// self-reference is picked up the same way, so renaming a parent repoints its children.
        /// Returns how many referencing rows moved.
        /// </summary>
        private int RenameKeyCascade(string table, string keyColumn, string oldKey, string newKey)
        {
            string target = table + "." + keyColumn;
            int touched = 0;

            foreach (string other in _msiTableNames)
            {
                if (!MsiTableSchemas.TryGetValue(other, out string? schema)) continue;

                TableState? st = null;
                foreach (var (col, _, _, fk) in ParseTableSchema(schema))
                {
                    if (!string.Equals(fk, target, StringComparison.OrdinalIgnoreCase)) continue;

                    st ??= EnsureTableCached(other);
                    if (st == null || !st.Data.Columns.Contains(col)) continue;

                    foreach (DataRow r in st.Data.Rows)
                    {
                        if (r.RowState == DataRowState.Deleted) continue;
                        if (!string.Equals(Cv(r[col]), oldKey, StringComparison.Ordinal)) continue;
                        r[col] = newKey;
                        touched++;
                    }
                }
            }
            return touched;
        }

        /// <summary>Asks for a new key, checked for emptiness, no change, and collision. Returns ""
        /// when the rename should not go ahead.</summary>
        private string AskNewKey(string title, string oldKey, TableState st, string keyColumn)
        {
            string? typed = PromptText(title, "Name", oldKey);
            if (string.IsNullOrWhiteSpace(typed)) return "";

            string newKey = SanitizeKey(typed.Trim());
            if (string.Equals(newKey, oldKey, StringComparison.Ordinal)) return "";

            if (FindLiveRow(st, keyColumn, newKey) != null)
            {
                MstMessage($"{newKey} is already used by another row in the {keyColumn} table.",
                    title, MessageBoxButton.OK, MessageBoxImage.Warning);
                return "";
            }
            return newKey;
        }

        private void FeatRenameFeature_Click(object sender, RoutedEventArgs e)
        {
            var node = SelectedFeat();
            if (node?.Kind != FeatNodeKind.Feature || node.FeatRow == null)
            { MstMessage("Select a feature to rename.", "Rename Feature", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var featSt = EnsureTableCached("Feature");
            if (featSt == null) return;

            string oldKey = node.Key;
            string newKey = AskNewKey("Rename Feature", oldKey, featSt, "Feature");
            if (newKey.Length == 0) return;

            node.FeatRow["Feature"] = newKey;
            int refs = RenameKeyCascade("Feature", "Feature", oldKey, newKey);

            node.Key = newKey;
            node.Display = newKey;
            foreach (var ch in node.Children)
                if (ch.Kind == FeatNodeKind.Feature) ch.ParentKey = newKey;

            UpdateEditCount();
            RefreshFeatSelection();
            if (TxtStatus != null)
                TxtStatus.Text = $"Renamed feature {oldKey} to {newKey}, repointing {refs} reference(s).";
        }

        private void FeatRenameComponent_Click(object sender, RoutedEventArgs e)
        {
            var node = SelectedFeat();
            if (node?.Kind != FeatNodeKind.Component || node.ComponentKey.Length == 0)
            { MstMessage("Select a component to rename.", "Rename Component", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var compSt = EnsureTableCached("Component");
            if (compSt == null) return;
            string oldKey = node.ComponentKey;
            var cr = FindLiveRow(compSt, "Component", oldKey);
            if (cr == null)
            { MstMessage($"{oldKey} is not in the Component table.", "Rename Component", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            string newKey = AskNewKey("Rename Component", oldKey, compSt, "Component");
            if (newKey.Length == 0) return;

            cr["Component"] = newKey;
            int refs = RenameKeyCascade("Component", "Component", oldKey, newKey);

            node.ComponentKey = newKey;
            node.Display = newKey;
            foreach (var ch in node.Children) ch.ComponentKey = newKey;   // Files / Registry / Shortcuts

            UpdateEditCount();
            RefreshFeatSelection();
            if (TxtStatus != null)
                TxtStatus.Text = $"Renamed component {oldKey} to {newKey}, repointing {refs} reference(s).";
        }

        private void FeatNewComponent_Click(object sender, RoutedEventArgs e)
        {
            var node = NearestFeature(SelectedFeat());
            if (node == null)
            { MstMessage("Select a feature first.", "New Component", MessageBoxButton.OK, MessageBoxImage.Information); return; }

            var compSt = EnsureTableOrCreate("Component");
            var fcSt   = EnsureTableOrCreate("FeatureComponents");
            if (compSt == null || fcSt == null || !compSt.Data.Columns.Contains("Component"))
            { MstMessage("This MSI has no Component table.", "New Component", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            string? name = PromptText("New Component", "Name", "NewComponent");
            if (string.IsNullOrWhiteSpace(name)) return;
            string key = UniqueKey(compSt.Data, "Component", SanitizeKey(name.Trim()));

            // A component has to install somewhere and needs its own GUID, so both start filled in
            // rather than blank; everything else is chosen in the dialog.
            var init = new ComponentData
            {
                Directory   = DetectInstallDirectoryKey(),
                ComponentId = "{" + Guid.NewGuid().ToString().ToUpperInvariant() + "}",
            };
            var res = PromptComponent($"New Component  -  {key}", init);
            if (res == null) return;

            var nr = compSt.Data.NewRow();
            nr["Component"] = key;
            WriteComponentData(nr, res);
            compSt.Data.Rows.Add(nr);

            var link = fcSt.Data.NewRow();
            if (fcSt.Data.Columns.Contains("Feature_"))   link["Feature_"]   = node.Key;
            if (fcSt.Data.Columns.Contains("Component_")) link["Component_"] = key;
            fcSt.Data.Rows.Add(link);

            // Sorted in after any subfeatures, the same way Add Component places one.
            var cnode = MakeComponentNode(node, key);
            int idx = 0;
            while (idx < node.Children.Count && node.Children[idx].Kind == FeatNodeKind.Feature) idx++;
            while (idx < node.Children.Count && node.Children[idx].Kind == FeatNodeKind.Component &&
                   string.Compare(node.Children[idx].Display, key, StringComparison.OrdinalIgnoreCase) < 0) idx++;
            node.Children.Insert(idx, cnode);
            node.IsExpanded = true;

            UpdateEditCount();
            RefreshFeatSelection();
            if (TxtStatus != null) TxtStatus.Text = $"Added component {key} to {node.Key}.";
        }

        private void FeatAddComponent_Click(object sender, RoutedEventArgs e)
        {
            var node = NearestFeature(SelectedFeat());
            if (node == null)
            { MstMessage("Select a feature first.", "Add Component", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            var fcSt = EnsureTableCached("FeatureComponents");
            if (fcSt == null)
            { MstMessage("This MSI has no FeatureComponents table.", "Add Component", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            // Components not already linked to this feature.
            var already = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (DataRow r in fcSt.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals(Cv(r["Feature_"]), node.Key, StringComparison.OrdinalIgnoreCase))
                    already.Add(Cv(r["Component_"]));
            }
            var info = ComponentInfoMap();
            var items = new System.Collections.Generic.List<(string value, string display)>();
            foreach (var kv in info)
                if (!already.Contains(kv.Key))
                    items.Add((kv.Key, kv.Value.dir.Length > 0 ? $"{kv.Key}   ({kv.Value.dir})" : kv.Key));
            items.Sort((a, b) => string.Compare(a.display, b.display, StringComparison.OrdinalIgnoreCase));

            string? comp = PickFromPackage("Add a component to the feature", items);
            if (comp == null) return;

            var nr = fcSt.Data.NewRow();
            if (fcSt.Data.Columns.Contains("Feature_"))   nr["Feature_"]   = node.Key;
            if (fcSt.Data.Columns.Contains("Component_")) nr["Component_"] = comp;
            fcSt.Data.Rows.Add(nr);

            // Add the component (with its category buckets) to the tree, sorted after subfeatures.
            var cnode = MakeComponentNode(node, comp);
            int idx = 0;
            while (idx < node.Children.Count && node.Children[idx].Kind == FeatNodeKind.Feature) idx++;
            while (idx < node.Children.Count && node.Children[idx].Kind == FeatNodeKind.Component &&
                   string.Compare(node.Children[idx].Display, comp, StringComparison.OrdinalIgnoreCase) < 0) idx++;
            node.Children.Insert(idx, cnode);
            node.IsExpanded = true;
            UpdateEditCount();
            RefreshFeatSelection();
        }

        private void FeatRemoveComponent_Click(object sender, RoutedEventArgs e)
        {
            var sel = SelectedFeat();
            FeatureNode? compNode = sel?.Kind == FeatNodeKind.Component ? sel
                : (sel != null && (sel.Kind == FeatNodeKind.FilesCat || sel.Kind == FeatNodeKind.RegistryCat
                                   || sel.Kind == FeatNodeKind.ShortcutsCat) ? sel.Parent : null);
            if (compNode?.Parent == null)
            { MstMessage("Select a component to remove from its feature.", "Remove Component", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            var feature = compNode.Parent;
            var fcSt = EnsureTableCached("FeatureComponents");
            if (fcSt != null)
                foreach (DataRow r in fcSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (string.Equals(Cv(r["Feature_"]), feature.Key, StringComparison.OrdinalIgnoreCase) &&
                        string.Equals(Cv(r["Component_"]), compNode.ComponentKey, StringComparison.OrdinalIgnoreCase))
                        r.Delete();
                }
            feature.Children.Remove(compNode);
            ClearDetail();
            if (FeatCompTitle != null) FeatCompTitle.Text = "Select a feature";
            UpdateEditCount();
        }

        private void FeatEditComponent_Click(object sender, RoutedEventArgs e)
        {
            var sel = SelectedFeat();
            FeatureNode? compNode = sel?.Kind == FeatNodeKind.Component ? sel
                : (sel != null && (sel.Kind == FeatNodeKind.FilesCat || sel.Kind == FeatNodeKind.RegistryCat
                                   || sel.Kind == FeatNodeKind.ShortcutsCat) ? sel.Parent : null);
            if (compNode == null)
            { MstMessage("Select a component to edit.", "Edit Component", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            var compSt = EnsureTableCached("Component");
            DataRow? cr = null;
            if (compSt != null)
                foreach (DataRow r in compSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (string.Equals(Cv(r["Component"]), compNode.ComponentKey, StringComparison.OrdinalIgnoreCase)) { cr = r; break; }
                }
            if (cr == null)
            { MstMessage("That component was not found in the Component table.", "Edit Component", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            var res = PromptComponent($"Edit Component  -  {compNode.ComponentKey}", ReadComponentData(cr));
            if (res == null) return;
            WriteComponentData(cr, res);
            UpdateEditCount();
            RefreshFeatSelection();
        }

        // Double-click a property row in the component view to change it in place:
        // text fields prompt, the install-location cycles, flags toggle Yes/No.
        private void FeatProps_DoubleClick(object sender, MouseButtonEventArgs e)
        {
            if (_propsComp == null) return;
            if (FeatCompList?.SelectedItem is not SetupRow sr) return;
            string prop = sr.C0;

            var compSt = EnsureTableCached("Component");
            DataRow? cr = null;
            if (compSt != null)
                foreach (DataRow r in compSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (string.Equals(Cv(r["Component"]), _propsComp, StringComparison.OrdinalIgnoreCase)) { cr = r; break; }
                }
            if (cr == null) return;

            int attr = int.TryParse(Cv(cr["Attributes"]), out var a) ? a : 0;

            void SetText(string col, bool required)
            {
                if (!cr.Table.Columns.Contains(col)) return;
                string? v = PromptText("Edit " + prop, prop, Cv(cr[col]));
                if (v == null) return;
                cr[col] = (v.Length > 0 || required) ? (object)v : DBNull.Value;
            }
            void Toggle(int bit)
            {
                attr = (attr & bit) != 0 ? attr & ~bit : attr | bit;
                if (cr.Table.Columns.Contains("Attributes")) cr["Attributes"] = attr.ToString();
            }

            switch (prop)
            {
                case "Destination":     SetText("Directory_", true);  break;
                case "Component GUID":  SetText("ComponentId", false); break;
                case "Key path":        SetText("KeyPath", false);     break;
                case "Condition":       SetText("Condition", false);   break;
                case "Install location":
                {
                    int cur = (attr & 2) != 0 ? 2 : (attr & 1) != 0 ? 1 : 0;   // cycle local -> source -> optional
                    attr &= ~3;
                    attr |= cur == 0 ? 1 : cur == 1 ? 2 : 0;
                    if (cr.Table.Columns.Contains("Attributes")) cr["Attributes"] = attr.ToString();
                    break;
                }
                case "Permanent":                 Toggle(16);   break;
                case "Never overwrite":           Toggle(128);  break;
                case "64-bit":                    Toggle(256);  break;
                case "Uninstall on supersedence": Toggle(1024); break;
                case "Shared component":          Toggle(2048); break;
                case "Attributes (raw value)":
                {
                    string? v = PromptText("Edit raw Attributes", "Attributes", attr.ToString());
                    if (v == null) return;
                    if (int.TryParse(v.Trim(), out var nv) && cr.Table.Columns.Contains("Attributes"))
                        cr["Attributes"] = nv.ToString();
                    break;
                }
                default: return;
            }
            UpdateEditCount();
            ShowComponentProperties(_propsComp);
        }

        // The component a tree-menu action should target: the selected Component node,
        // or the parent component of a selected Files/Registry/Shortcuts bucket.
        private string? SelectedComponentKey()
        {
            var sel = SelectedFeat();
            if (sel == null) return null;
            if (sel.Kind == FeatNodeKind.Component || sel.Kind == FeatNodeKind.FilesCat
                || sel.Kind == FeatNodeKind.RegistryCat || sel.Kind == FeatNodeKind.ShortcutsCat)
                return sel.ComponentKey.Length > 0 ? sel.ComponentKey : null;
            return null;
        }

        private void FeatAddFiles_Click(object sender, RoutedEventArgs e)
        {
            string? comp = SelectedComponentKey();
            if (comp == null)
            { MstMessage("Select a component to add files to.", "Add Files", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            var fileSt = EnsureTableCached("File");
            if (fileSt == null)
            { MstMessage("This MSI has no File table.", "Add Files", MessageBoxButton.OK, MessageBoxImage.Warning); return; }

            var dlg = new OpenFileDialog { Title = "Add Files", Multiselect = true };
            if (dlg.ShowDialog() != true) return;

            FileMedia? media = AskFileMedia(dlg.FileNames.Length);
            if (media == null) return;

            int seq = NextSequence(fileSt.Data);
            int added = 0; string lastName = "", lastKey = "";
            foreach (string path in dlg.FileNames)
            {
                try
                {
                    var fi = new FileInfo(path);
                    string longName = fi.Name;
                    string key = UniqueKey(fileSt.Data, "File", FileKeyFromName(longName));
                    string ver = "";
                    try { ver = System.Diagnostics.FileVersionInfo.GetVersionInfo(path).FileVersion ?? ""; } catch { }

                    var nr = fileSt.Data.NewRow();
                    nr["File"] = key;
                    if (fileSt.Data.Columns.Contains("Component_")) nr["Component_"] = comp;
                    if (fileSt.Data.Columns.Contains("FileName"))   nr["FileName"]   = FileNameField(longName);
                    if (fileSt.Data.Columns.Contains("FileSize"))   nr["FileSize"]   = fi.Length.ToString();
                    if (fileSt.Data.Columns.Contains("Version") && ver.Length > 0) nr["Version"] = ver;
                    if (fileSt.Data.Columns.Contains("Attributes")) nr["Attributes"] = FileAttrsFor(media.Value);
                    if (fileSt.Data.Columns.Contains("Sequence"))   nr["Sequence"]   = (++seq).ToString();
                    fileSt.Data.Rows.Add(nr);
                    _addedFileSources[key] = path;
                    _addedFileMedia[key]   = media.Value;
                    added++; lastName = longName; lastKey = key;
                }
                catch { }
            }
            if (added > 0)
            {
                UpdateEditCount();
                RefreshFeatSelection();
                if (TxtStatus != null)
                    TxtStatus.Text = added == 1
                        ? $"Added {lastName} (File key {lastKey}) to {comp}."
                        : $"Added {added} files to {comp}.";
            }
        }


        private static ComponentData ReadComponentData(DataRow cr)
        {
            string Get(string c) =>
                cr.Table.Columns.Contains(c) && cr[c] != DBNull.Value ? cr[c].ToString() ?? "" : "";
            int a = int.TryParse(Get("Attributes"), out var av) ? av : 0;
            return new ComponentData
            {
                Directory   = Get("Directory_"),
                ComponentId = Get("ComponentId"),
                KeyPath     = Get("KeyPath"),
                Condition   = Get("Condition"),
                Location    = (a & 2) != 0 ? "Optional" : (a & 1) != 0 ? "Source" : "Local",
                RegKeyPath           = (a & 4)    != 0,
                SharedDll            = (a & 8)    != 0,
                Permanent            = (a & 16)   != 0,
                Odbc                 = (a & 32)   != 0,
                Transitive           = (a & 64)   != 0,
                NeverOverwrite       = (a & 128)  != 0,
                Bit64                = (a & 256)  != 0,
                DisableReflection    = (a & 512)  != 0,
                UninstallOnSupersede = (a & 1024) != 0,
                Shared               = (a & 2048) != 0
            };
        }

        private static void WriteComponentData(DataRow cr, ComponentData d)
        {
            void Set(string c, string v, bool required)
            {
                if (!cr.Table.Columns.Contains(c)) return;
                cr[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
            }
            Set("Directory_",  d.Directory,   true);
            Set("ComponentId", d.ComponentId, false);
            Set("KeyPath",     d.KeyPath,     false);
            Set("Condition",   d.Condition,   false);

            int a = d.Location == "Source" ? 1 : d.Location == "Optional" ? 2 : 0;
            if (d.RegKeyPath)           a |= 4;
            if (d.SharedDll)            a |= 8;
            if (d.Permanent)            a |= 16;
            if (d.Odbc)                 a |= 32;
            if (d.Transitive)           a |= 64;
            if (d.NeverOverwrite)       a |= 128;
            if (d.Bit64)                a |= 256;
            if (d.DisableReflection)    a |= 512;
            if (d.UninstallOnSupersede) a |= 1024;
            if (d.Shared)               a |= 2048;
            if (cr.Table.Columns.Contains("Attributes")) cr["Attributes"] = a.ToString();
        }

        // Component editor: install directory, GUID, key path, condition, run-from
        // location, and the Component-table attribute flags. Returns null on cancel.
        private ComponentData? PromptComponent(string title, ComponentData init)
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 520; win.MaxWidth = 520;

            int r = 0;
            void AddStacked(string text, FrameworkElement field, bool first = false)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, Margin = new Thickness(0, first ? 0 : 10, 0, 4)
                };
                Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0); Grid.SetColumnSpan(lbl, 2);
                cg.Children.Add(lbl); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(field, r); Grid.SetColumn(field, 0); Grid.SetColumnSpan(field, 2);
                cg.Children.Add(field); r++;
            }
            CheckBox Chk(string label, bool on) => new CheckBox
            {
                Content = label, IsChecked = on, Foreground = lblFg, FontSize = 12,
                Width = 230, Margin = new Thickness(0, 4, 12, 4), VerticalContentAlignment = VerticalAlignment.Center
            };

            var (dirField, dirBox) = MakeRoundedField(init.Directory, boxBg, boxBdr, valFg, false,
                () => PickDirectoryKey("Select a folder", init.Directory));
            AddStacked("Destination", dirField, true);
            var (idField, idBox) = MakeRoundedField(init.ComponentId, boxBg, boxBdr, valFg, false, null);
            AddStacked("Component GUID", idField);
            var (kpField, kpBox) = MakeRoundedField(init.KeyPath, boxBg, boxBdr, valFg, false, null);
            AddStacked("Key path", kpField);
            var (condField, condBox) = MakeRoundedField(init.Condition, boxBg, boxBdr, valFg, false, null);
            AddStacked("Condition (optional)", condField);

            var locBox = new ComboBox
            {
                FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
            };
            (string tag, string label)[] locs = { ("Local", "Run local"), ("Source", "Run from source"), ("Optional", "Optional (local or source)") };
            foreach (var (tag, label) in locs)
                locBox.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
            int li = Array.FindIndex(locs, x => x.tag == init.Location);
            locBox.SelectedIndex = li >= 0 ? li : 0;
            AddStacked("Install location", RoundWrapControl(locBox, boxBg, boxBdr));

            var cPerm     = Chk("Permanent", init.Permanent);
            var cNever    = Chk("Never overwrite", init.NeverOverwrite);
            var c64       = Chk("64-bit", init.Bit64);
            var cUninst   = Chk("Uninstall on supersedence", init.UninstallOnSupersede);
            var cShared   = Chk("Shared component", init.Shared);
            var opts = new WrapPanel { Orientation = Orientation.Horizontal };
            foreach (var c in new[] { cPerm, cNever, c64, cUninst, cShared })
                opts.Children.Add(c);
            AddStacked("Options", opts);

            NdAddSpacer(cg, r++);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            ComponentData? result = null;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () =>
                {
                    result = new ComponentData
                    {
                        Directory = dirBox.Text, ComponentId = idBox.Text, KeyPath = kpBox.Text, Condition = condBox.Text,
                        Location = (locBox.SelectedItem as ComboBoxItem)?.Tag as string ?? "Local",
                        // Flags not exposed in this dialog are preserved as-is.
                        RegKeyPath = init.RegKeyPath, SharedDll = init.SharedDll, Odbc = init.Odbc,
                        Transitive = init.Transitive, DisableReflection = init.DisableReflection,
                        Permanent = cPerm.IsChecked == true, NeverOverwrite = cNever.IsChecked == true,
                        Bit64 = c64.IsChecked == true,
                        UninstallOnSupersede = cUninst.IsChecked == true, Shared = cShared.IsChecked == true
                    };
                    win.Close();
                }),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 0); Grid.SetColumnSpan(btns, 2); cg.Children.Add(btns);

            dirBox.Loaded += (_, _) => { dirBox.Focus(); };
            win.ShowDialog();
            return result;
        }

        private static FeatureData ReadFeatureData(DataRow row)
        {
            string Get(string c) =>
                row.Table.Columns.Contains(c) && row[c] != DBNull.Value ? row[c].ToString() ?? "" : "";
            int disp = int.TryParse(Get("Display"), out var dv) ? dv : 1;
            int attr = int.TryParse(Get("Attributes"), out var av) ? av : 0;
            return new FeatureData
            {
                Title       = Get("Title"),
                Description = Get("Description"),
                Level       = Get("Level").Length > 0 ? Get("Level") : "1",
                Directory   = Get("Directory_"),
                Display     = disp == 0 ? "Hidden" : (disp % 2 == 1 ? "Expanded" : "Collapsed"),
                Install     = (attr & 1) != 0 ? "Source" : ((attr & 4) != 0 ? "Advertise" : "Local")
            };
        }

        private static void WriteFeatureData(DataRow row, FeatureData d)
        {
            void Set(string c, string v, bool required)
            {
                if (!row.Table.Columns.Contains(c)) return;
                row[c] = (v.Length > 0 || required) ? v : (object)DBNull.Value;
            }
            Set("Title",       d.Title,       false);
            Set("Description", d.Description, false);
            Set("Directory_",  d.Directory,   false);

            if (row.Table.Columns.Contains("Level"))
                row["Level"] = int.TryParse(d.Level, out var lv) ? lv.ToString() : "1";

            if (row.Table.Columns.Contains("Display"))
            {
                int cur = int.TryParse(row["Display"] == DBNull.Value ? "" : row["Display"]?.ToString(), out var c) ? c : 0;
                int nd = d.Display switch
                {
                    "Hidden"    => 0,
                    "Collapsed" => (cur > 1 && cur % 2 == 0) ? cur : 2,
                    _           => (cur > 0 && cur % 2 == 1) ? cur : 1   // Expanded
                };
                row["Display"] = nd.ToString();
            }

            if (row.Table.Columns.Contains("Attributes"))
            {
                int cur = int.TryParse(row["Attributes"] == DBNull.Value ? "" : row["Attributes"]?.ToString(), out var c) ? c : 0;
                int baseA = cur & ~5;   // clear FavorSource (1) and FavorAdvertise (4)
                int na = d.Install switch { "Source" => baseA | 1, "Advertise" => baseA | 4, _ => baseA };
                row["Attributes"] = na.ToString();
            }
        }

        // Feature properties editor. Returns null on cancel.
        private FeatureData? PromptFeature(string title, FeatureData init)
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 480; win.MaxWidth = 480;

            int r = 0;
            void AddStacked(string text, FrameworkElement field, bool first = false)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = new TextBlock
                {
                    Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, Margin = new Thickness(0, first ? 0 : 10, 0, 4)
                };
                Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0); Grid.SetColumnSpan(lbl, 2);
                cg.Children.Add(lbl); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(field, r); Grid.SetColumn(field, 0); Grid.SetColumnSpan(field, 2);
                cg.Children.Add(field); r++;
            }
            ComboBox Combo((string tag, string label)[] opts, string sel)
            {
                var cb = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4),
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr
                };
                foreach (var (tag, label) in opts)
                    cb.Items.Add(new ComboBoxItem { Content = label, Tag = tag });
                int si = Array.FindIndex(opts, o => o.tag == sel);
                cb.SelectedIndex = si >= 0 ? si : 0;
                return cb;
            }

            var (titleField, titleBox) = MakeRoundedField(init.Title, boxBg, boxBdr, valFg, false, null);
            AddStacked("Title", titleField, true);
            var (descField, descBox) = MakeRoundedField(init.Description, boxBg, boxBdr, valFg, false, null);
            AddStacked("Description", descField);
            var (lvlField, lvlBox) = MakeRoundedField(init.Level, boxBg, boxBdr, valFg, false, null);
            AddStacked("Install level (1 installs by default, 0 disables)", lvlField);

            var visCombo = Combo(new[] { ("Hidden", "Hidden"), ("Collapsed", "Collapsed"), ("Expanded", "Expanded") }, init.Display);
            AddStacked("Visibility in the feature tree", RoundWrapControl(visCombo, boxBg, boxBdr));

            var (dirField, dirBox) = MakeRoundedField(init.Directory, boxBg, boxBdr, valFg, false,
                () => PickDirectoryKey("Select a folder", init.Directory));
            AddStacked("Default directory (optional)", dirField);

            var instCombo = Combo(new[]
            {
                ("Local", "Install locally"), ("Source", "Run from source"), ("Advertise", "Advertised (install on demand)")
            }, init.Install);
            AddStacked("Install option", RoundWrapControl(instCombo, boxBg, boxBdr));

            NdAddSpacer(cg, r++);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            FeatureData? result = null;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () =>
                {
                    result = new FeatureData
                    {
                        Title = titleBox.Text, Description = descBox.Text, Level = lvlBox.Text,
                        Directory = dirBox.Text,
                        Display = (visCombo.SelectedItem as ComboBoxItem)?.Tag as string ?? "Expanded",
                        Install = (instCombo.SelectedItem as ComboBoxItem)?.Tag as string ?? "Local"
                    };
                    win.Close();
                }),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 0); Grid.SetColumnSpan(btns, 2); cg.Children.Add(btns);

            titleBox.Loaded += (_, _) => { titleBox.SelectAll(); titleBox.Focus(); };
            win.ShowDialog();
            return result;
        }

        private static string UniqueKey(DataTable t, string col, string baseKey)
        {
            var used = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (t.Columns.Contains(col))
                foreach (DataRow r in t.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string v = r[col]?.ToString() ?? "";
                    if (v.Length > 0) used.Add(v);
                }
            if (!used.Contains(baseKey)) return baseKey;
            for (int i = 1; i < 100000; i++)
            {
                string cand = baseKey + "_" + i;
                if (!used.Contains(cand)) return cand;
            }
            return baseKey + "_" + Guid.NewGuid().ToString("N").Substring(0, 6);
        }

        private static string FileNameField(string longName) => ShortName(longName) + "|" + longName;

        private static string ShortName(string name)
        {
            string b   = System.IO.Path.GetFileNameWithoutExtension(name);
            string ext = System.IO.Path.GetExtension(name).TrimStart('.');
            string Clean(string s)
            {
                var sb = new System.Text.StringBuilder();
                foreach (char c in s) if (char.IsLetterOrDigit(c)) sb.Append(char.ToUpperInvariant(c));
                return sb.ToString();
            }
            string cb = Clean(b), ce = Clean(ext);
            string sb2 = cb.Length > 6 ? cb.Substring(0, 6) + "~1" : (cb.Length > 0 ? cb + "~1" : "FILE~1");
            return ce.Length > 0 ? sb2 + "." + (ce.Length > 3 ? ce.Substring(0, 3) : ce) : sb2;
        }

        // A rounded input box (a transparent TextBox inside a rounded Border). When a
        // picker is supplied, a browse glyph sits inside the box and fills it on pick.
        private (Border field, TextBox box) MakeRoundedField(
            string text, Brush bg, Brush bdr, Brush fg, bool multiline, Func<string?>? picker,
            string pickerGlyph = "\uD83D\uDCC1", string pickerTip = "Browse")
        {
            var box = new TextBox
            {
                Text = text, FontSize = 12, Foreground = fg, Background = Brushes.Transparent,
                // The caret does not follow Foreground: left alone it stays black, which on the
                // dark theme's input background is invisible and reads as a dead text box.
                CaretBrush = fg,
                SelectionBrush = new SolidColorBrush(Color.FromArgb(0x66, 0x6C, 0x63, 0xFF)),
                BorderThickness = new Thickness(0), Padding = new Thickness(8, 5, 8, 5),
                VerticalContentAlignment = multiline ? VerticalAlignment.Top : VerticalAlignment.Center,
                AcceptsReturn = multiline,
                TextWrapping = multiline ? TextWrapping.Wrap : TextWrapping.NoWrap,
                MinHeight = multiline ? 58 : 0
            };
            var border = new Border
            {
                Background = bg, BorderBrush = bdr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true
            };
            if (picker != null)
            {
                var dock = new DockPanel { LastChildFill = true };
                var btn = new Button
                {
                    Content = pickerGlyph, FontSize = 13, Cursor = Cursors.Hand, Foreground = fg,
                    Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                    Padding = new Thickness(4, 0, 8, 0), VerticalAlignment = VerticalAlignment.Center,
                    ToolTip = pickerTip
                };
                btn.Click += (_, _) => { var v = picker(); if (v != null) box.Text = v; };
                DockPanel.SetDock(btn, Dock.Right);
                dock.Children.Add(btn);
                dock.Children.Add(box);
                border.Child = dock;
            }
            else border.Child = box;
            return (border, box);
        }

        // Wrap a control in a rounded border for a consistent look. A ComboBox already
        // carries its own rounded border (page template) and only needs sizing, so it is
        // returned as-is at the single-line text-field height (no second border).
        private static FrameworkElement RoundWrapControl(Control inner, Brush bg, Brush bdr)
        {
            if (inner is ComboBox cb)
            {
                cb.Height = 28;   // match the rounded single-line text fields
                cb.VerticalContentAlignment = VerticalAlignment.Center;
                return cb;
            }
            inner.Background = Brushes.Transparent;
            inner.BorderThickness = new Thickness(0);
            return new Border
            {
                Background = bg, BorderBrush = bdr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true, Child = inner
            };
        }

        /// <summary>
        /// The bytes of a stream column, or null when there are none to be had. Used for the Icon
        /// table's icons and the Binary table's bitmaps, which are the same shape: a key column and
        /// a Data column holding the bytes.
        ///
        /// Read through the flat msi.dll API rather than automation: a stream comes back as a byte
        /// buffer, and the automation route would hand it over as a string and mangle anything that
        /// is not text. Reads the file on disk, so a row added in this session has nothing to read
        /// yet and the caller falls back to whatever it was built from.
        /// </summary>
        private static byte[]? ReadTableStream(string msiPath, string table, string keyCol, string key,
            out string why)
        {
            // why names the stage that produced nothing. The read has several ways to come back
            // empty that all looked identical from the outside, and a preview that only ever said
            // "no image" gave nothing to fix.
            why = "";
            if (msiPath.Length == 0 || key.Length == 0 || !File.Exists(msiPath))
            { why = "no saved package to read from"; return null; }

            uint hDb = 0, hView = 0, hRec = 0;
            uint rc;
            try
            {
                rc = MsiApi.MsiOpenDatabaseW(msiPath, IntPtr.Zero, out hDb);
                if (rc != MsiApi.ERROR_SUCCESS) { why = $"the package could not be opened (error {rc})"; return null; }
                string sql = $"SELECT `Data` FROM `{table}` WHERE `{keyCol}` = '" + key.Replace("'", "''") + "'";
                rc = MsiApi.MsiDatabaseOpenViewW(hDb, sql, out hView);
                if (rc != MsiApi.ERROR_SUCCESS) { why = $"the {table} table could not be queried (error {rc})"; return null; }
                rc = MsiApi.MsiViewExecute(hView, 0);
                if (rc != MsiApi.ERROR_SUCCESS) { why = $"the {table} query would not run (error {rc})"; return null; }
                rc = MsiApi.MsiViewFetch(hView, out hRec);
                if (rc != MsiApi.ERROR_SUCCESS)
                { why = $"the {table} table has no row named \u201C{key}\u201D (error {rc})"; return null; }

                uint size = MsiApi.MsiRecordDataSize(hRec, 1);
                if (size == 0)
                {
                    // The documented way to size a stream is a read with no buffer. DataSize is
                    // usually the same number, but a zero from it is ambiguous between "empty" and
                    // "would not say", so the probe settles it.
                    uint probe = 0;
                    if (MsiApi.MsiRecordReadStream(hRec, 1, null, ref probe) == MsiApi.ERROR_SUCCESS)
                        size = probe;
                }
                // Something that size is not an icon or a dialog bitmap, and a preview is not worth
                // reading it to find out. Packages do sometimes park an executable in these tables.
                if (size == 0) { why = "the row's stream is empty"; return null; }
                if (size > 8 * 1024 * 1024) { why = "the stream is larger than 8 MB"; return null; }

                var buf = new byte[size];
                uint got = size;
                rc = MsiApi.MsiRecordReadStream(hRec, 1, buf, ref got);
                if (rc != MsiApi.ERROR_SUCCESS) { why = $"the stream could not be read (error {rc})"; return null; }
                if (got != size) Array.Resize(ref buf, (int)got);
                return buf;
            }
            catch (Exception ex) { why = ex.Message; return null; }
            finally
            {
                if (hRec  != 0) MsiApi.MsiCloseHandle(hRec);
                if (hView != 0) { MsiApi.MsiViewClose(hView); MsiApi.MsiCloseHandle(hView); }
                if (hDb   != 0) MsiApi.MsiCloseHandle(hDb);
            }
        }

        /// <summary>
        /// The picture for an Icon-table row, or null when it cannot be decoded.
        ///
        /// An .ico holds several sizes in one file, and WPF hands back every one of them as a
        /// frame. The largest is the one worth showing: the 16px frame scaled up to fill a preview
        /// box looks like a mistake, while the 256px frame scaled down does not.
        ///
        /// Null rather than an exception for anything that is not a decodable image, because the
        /// Icon table is allowed to hold an .exe and the shape of the answer should not depend on
        /// which of those a package chose.
        /// </summary>
        private System.Windows.Media.ImageSource? IconPreview(string iconName)
        {
            try
            {
                byte[]? bytes = null;
                if (_addedIconSources.TryGetValue(iconName, out var src) && File.Exists(src))
                    bytes = File.ReadAllBytes(src);          // added this session, not yet in the file
                bytes ??= ReadTableStream(_msiPath, "Icon", "Name", iconName, out _);
                if (bytes == null || bytes.Length == 0) return null;

                using var ms = new System.IO.MemoryStream(bytes);
                var dec = System.Windows.Media.Imaging.BitmapDecoder.Create(ms,
                    System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,
                    System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);
                if (dec.Frames.Count == 0) return null;

                var best = dec.Frames[0];
                foreach (var f in dec.Frames)
                    if (f.PixelWidth * f.PixelHeight > best.PixelWidth * best.PixelHeight) best = f;
                best.Freeze();                               // read on the UI thread after the stream closes
                return best;
            }
            catch { return null; }
        }

        // A simple list picker over package items; returns the chosen value or null. When onBrowse
        // is supplied the dialog also carries a Browse button, for the lists where the answer may
        // simply not be in the package yet and has to be brought in from this machine. When preview
        // is supplied the selected item is drawn under the list, because a name like Icon.ico says
        // nothing about what will actually appear beside the product. current is the value the
        // field already holds, which is what the dialog opens on.
        private string? PickFromPackage(string title,
            System.Collections.Generic.List<(string value, string display)> items,
            Func<string?>? onBrowse = null,
            Func<string, System.Windows.Media.ImageSource?>? preview = null,
            string current = "")
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);

            int r = 0;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var lbl = new TextBlock
            {
                Text = "Select", FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, VerticalAlignment = VerticalAlignment.Top, Margin = new Thickness(0, 6, 0, 0)
            };
            var list = new ListBox
            {
                FontSize = 12, Background = boxBg, Foreground = valFg, BorderBrush = boxBdr,
                BorderThickness = new Thickness(1), Height = 260, Margin = new Thickness(0, 6, 0, 0)
            };
            // Items must use the dialog's themed foreground, not a hardcoded black.
            //
            // A ListBox renders its items inline, directly on the ListBox's own background, and that
            // background is boxBg from the theme. In dark mode boxBg is dark, so black item text was
            // effectively invisible.
            //
            // The ComboBoxes elsewhere in these dialogs are a genuinely different case and are left
            // alone: their items render inside the default WPF dropdown popup, which stays light
            // because the themed ComboBox style lives in Page.Resources and these dialogs are
            // separate Windows that never see it. Black is correct there.
            foreach (var (value, display) in items)
                list.Items.Add(new ListBoxItem { Content = display, Tag = value, Foreground = valFg });
            if (items.Count == 0)
                list.Items.Add(new ListBoxItem { Content = "(nothing available)", IsEnabled = false, Foreground = Brushes.Gray });

            // Opens on the value the field already holds, and on the first item when it holds none
            // or names something the package no longer has. Nothing selected meant the preview
            // opened empty, which is the one state a preview cannot explain.
            int start = -1;
            if ((current ?? "").Length > 0)
                for (int i = 0; i < items.Count; i++)
                    if (string.Equals(items[i].value, current, StringComparison.OrdinalIgnoreCase))
                    { start = i; break; }
            if (start < 0 && items.Count > 0) start = 0;
            if (start >= 0) list.SelectedIndex = start;

            Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0);
            Grid.SetRow(list, r); Grid.SetColumn(list, 1);
            cg.Children.Add(lbl); cg.Children.Add(list);
            r++;

            if (preview != null)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var shot = new Image
                {
                    Width = 64, Height = 64, Stretch = Stretch.Uniform,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                };
                // An .ico frame is smaller than the box more often than not, and the default
                // scaling makes a 32px icon blown up to 64 look like a smear.
                RenderOptions.SetBitmapScalingMode(shot, BitmapScalingMode.HighQuality);

                var caption = new TextBlock
                {
                    FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap,
                    VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(12, 0, 0, 0)
                };
                var inner = new StackPanel { Orientation = Orientation.Horizontal };
                inner.Children.Add(shot);
                inner.Children.Add(caption);

                var shotHost = new Border
                {
                    Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true,
                    Padding = new Thickness(10), Margin = new Thickness(0, 8, 0, 0),
                    MinHeight = 88, Child = inner
                };
                var previewLbl = new TextBlock
                {
                    Text = "Preview", FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(0, 16, 0, 0)
                };
                Grid.SetRow(previewLbl, r); Grid.SetColumn(previewLbl, 0);
                Grid.SetRow(shotHost, r);   Grid.SetColumn(shotHost, 1);
                cg.Children.Add(previewLbl); cg.Children.Add(shotHost);
                r++;

                void ShowPreview()
                {
                    string key = list.SelectedItem is ListBoxItem sel && sel.Tag is string v ? v : "";
                    var img = key.Length > 0 ? preview(key) : null;
                    shot.Source = img;
                    // PixelWidth, not Width: Width is in device-independent units and would report
                    // an icon authored at a non-96 DPI as a size it does not have.
                    string size = img is System.Windows.Media.Imaging.BitmapSource bs
                        ? bs.PixelWidth + " x " + bs.PixelHeight + " px"
                        : "";
                    caption.Text =
                          items.Count == 0 ? "Nothing here to preview."
                        : key.Length == 0  ? "Select an item to see it here."
                        : img == null      ? key + "\nNo preview: this row does not hold a picture "
                                           + "Windows can decode."
                        : key + "\n" + size;
                }
                list.SelectionChanged += (_, _) => ShowPreview();
                ShowPreview();
            }

            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            string? result = null;
            void Accept()
            {
                if (list.SelectedItem is ListBoxItem it && it.Tag is string v) { result = v; win.Close(); }
            }
            // Browse adds the item to the package and answers with it, so the dialog is done: there
            // is nothing left to choose once the thing you went looking for has just been brought in.
            void Browse()
            {
                string? added = onBrowse?.Invoke();
                if (added == null) return;
                result = added;
                win.Close();
            }
            var btns = onBrowse == null
                ? NdMakeButtons(sec,
                    ("\u2714 OK", Accept),
                    ("\u2715 Cancel", () => { result = null; win.Close(); }))
                : NdMakeButtons(sec,
                    ("\uD83D\uDCC1 Browse", Browse),
                    ("\u2714 OK", Accept),
                    ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);
            list.MouseDoubleClick += (_, _) => Accept();

            win.ShowDialog();
            return result;
        }

        /// <summary>
        /// Picks a file out of the package and returns it as [#FileKey], or null when cancelled.
        ///
        /// Shown as the Directory tree with the selected folder's files beside it, the way an MSI
        /// editor does it, rather than as one flat alphabetical list. A package of any size puts
        /// hundreds of entries in that list with nothing to separate three same-named copies of a
        /// file from one another, and the folder is exactly what tells them apart - so the folder
        /// is what gets picked first.
        ///
        /// Falls back to the flat list when the package has no Directory table: there is then no
        /// tree to draw, and the files are still worth offering.
        /// </summary>
        private string? PickFileFromPackage(string title, string current)
        {
            var roots = BuildInstallDirTree();
            if (roots.Count == 0) return PickFromPackage(title, PackageFiles());

            // The File-table key off a row, guarding the column and the row's state the way
            // FileRow does, since a row deleted this session is still sitting in the table.
            static string FileKeyOf(DataRow fr) =>
                fr.RowState != DataRowState.Deleted && fr.RowState != DataRowState.Detached
                && fr.Table.Columns.Contains("File") && fr["File"] != DBNull.Value
                    ? fr["File"].ToString() ?? "" : "";

            var placed = new HashSet<DataRow>();
            void Collect(InstallDirNode n)
            {
                foreach (var fr in n.FileRows) placed.Add(fr);
                foreach (var c in n.Children) Collect(c);
            }
            foreach (var root in roots) Collect(root);

            // A file whose component names a folder the Directory table does not carry hangs off no
            // node at all and would simply be unreachable here, so whatever is left over after the
            // tree is filled gets a bucket of its own rather than disappearing.
            var loose = new InstallDirNode { Key = "(no folder)", Display = "(no folder)" };
            var looseSt = EnsureTableCached("File");
            if (looseSt != null && looseSt.Data.Columns.Contains("File"))
                foreach (DataRow fr in looseSt.Data.Rows)
                    if (fr.RowState != DataRowState.Deleted && !placed.Contains(fr)) loose.FileRows.Add(fr);
            loose.Files = loose.FileRows.Count;
            if (loose.Files > 0) roots.Add(loose);

            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 760; win.MaxWidth = 760;

            int r = 0;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var intro = new TextBlock
            {
                Text = "Pick the folder on the left, then the file inside it. The number beside a "
                     + "folder is how many files land in it and everything under it.",
                FontSize = 12, TextWrapping = TextWrapping.Wrap, Foreground = valFg,
                Margin = new Thickness(0, 2, 0, 8)
            };
            Grid.SetRow(intro, r); Grid.SetColumn(intro, 0); Grid.SetColumnSpan(intro, 2);
            cg.Children.Add(intro); r++;

            // The selection colours the page's own trees use. A dialog is a separate Window, so it
            // never sees them and would otherwise fall back to the system highlight, which is the
            // one colour the theme has no say over.
            var selBg = new SolidColorBrush(Color.FromArgb(0x55, 0x6C, 0x63, 0xFF));
            void ThemeSelection(FrameworkElement c)
            {
                c.Resources[SystemColors.HighlightBrushKey]                      = selBg;
                c.Resources[SystemColors.InactiveSelectionHighlightBrushKey]     = selBg;
                c.Resources[SystemColors.HighlightTextBrushKey]                  = Brushes.White;
                c.Resources[SystemColors.InactiveSelectionHighlightTextBrushKey] = Brushes.White;
            }

            var tree = new TreeView
            {
                FontSize = 12, Foreground = valFg,
                Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                Padding = new Thickness(4)
            };
            tree.SetValue(ScrollViewer.HorizontalScrollBarVisibilityProperty, ScrollBarVisibility.Auto);
            ThemeSelection(tree);

            var list = new ListView
            {
                FontSize = 12, Foreground = valFg,
                Background = Brushes.Transparent, BorderThickness = new Thickness(0)
            };
            ThemeSelection(list);
            var gv = new GridView();
            gv.Columns.Add(new GridViewColumn
            { Header = "Name", Width = 220, DisplayMemberBinding = new System.Windows.Data.Binding("LongName") });
            gv.Columns.Add(new GridViewColumn
            { Header = "Size", Width = 80, DisplayMemberBinding = new System.Windows.Data.Binding("SizeText") });
            gv.Columns.Add(new GridViewColumn
            { Header = "Component", Width = 160, DisplayMemberBinding = new System.Windows.Data.Binding("Component") });
            list.View = gv;

            var iconBrush = new SolidColorBrush(Color.FromRgb(0x4C, 0x9A, 0xFF));
            var items = new List<TreeViewItem>();

            TreeViewItem AddNode(InstallDirNode n, ItemCollection into)
            {
                var head = new StackPanel { Orientation = Orientation.Horizontal };
                head.Children.Add(new System.Windows.Shapes.Path
                {
                    Data = MsiIcons.Folder, Stroke = iconBrush, Fill = Brushes.Transparent,
                    StrokeThickness = 2, StrokeLineJoin = PenLineJoin.Round,
                    Width = 15, Height = 15, Stretch = Stretch.Uniform,
                    Margin = new Thickness(0, 0, 7, 0), VerticalAlignment = VerticalAlignment.Center
                });
                head.Children.Add(new TextBlock { Text = n.Display, VerticalAlignment = VerticalAlignment.Center });
                // Opacity rather than a second brush, so the count dims with the row's own colour
                // instead of staying grey against the selection highlight.
                head.Children.Add(new TextBlock
                {
                    Text = "  [" + n.Files + "]", FontSize = 11, Opacity = 0.65,
                    VerticalAlignment = VerticalAlignment.Center
                });

                var tvi = new TreeViewItem { Header = head, Tag = n, Padding = new Thickness(2) };
                into.Add(tvi);
                items.Add(tvi);
                foreach (var c in n.Children) AddNode(c, tvi.Items);
                return tvi;
            }

            foreach (var root in roots) AddNode(root, tree.Items);

            var panes = new Grid { Height = 320 };
            panes.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(300) });
            panes.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(8) });
            panes.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            var treeHost = RoundWrapControl(tree, boxBg, boxBdr);
            var listHost = RoundWrapControl(list, boxBg, boxBdr);
            Grid.SetColumn(treeHost, 0); Grid.SetColumn(listHost, 2);
            panes.Children.Add(treeHost); panes.Children.Add(listHost);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Grid.SetRow(panes, r); Grid.SetColumn(panes, 0); Grid.SetColumnSpan(panes, 2);
            cg.Children.Add(panes); r++;

            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var lbl = new TextBlock
            {
                Text = "Target", FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, VerticalAlignment = VerticalAlignment.Center
            };
            var box = new TextBox
            {
                FontSize = 12, Padding = new Thickness(8, 5, 8, 5), IsReadOnly = true,
                Background = Brushes.Transparent, Foreground = valFg, BorderThickness = new Thickness(0),
                VerticalContentAlignment = VerticalAlignment.Center,
                Cursor = System.Windows.Input.Cursors.Arrow,
                ToolTip = "The File-table key of the selected file. This is what the shortcut points at."
            };
            var boxField = new Border
            {
                Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true, Child = box
            };
            Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0);
            Grid.SetRow(boxField, r); Grid.SetColumn(boxField, 1);
            cg.Children.Add(lbl); cg.Children.Add(boxField); r++;

            // Filling the list is a call rather than only an event handler, because the initial
            // selection is made before the window is shown and a routed event out of a container
            // that is not laid out yet cannot be counted on to reach the tree.
            void ShowFolder(InstallDirNode? node)
            {
                var rows = new List<FileRow>();
                if (node != null)
                    foreach (var fr in node.FileRows)
                        if (fr.RowState != DataRowState.Deleted && fr.RowState != DataRowState.Detached)
                            rows.Add(new FileRow(fr, UpdateEditCount));
                rows.Sort((a, b) => string.Compare(a.LongName, b.LongName, StringComparison.OrdinalIgnoreCase));
                list.ItemsSource = rows;
                box.Text = "";
            }
            tree.SelectedItemChanged += (_, ev) =>
                ShowFolder((ev.NewValue as TreeViewItem)?.Tag as InstallDirNode);
            list.SelectionChanged += (_, _) =>
                box.Text = list.SelectedItem is FileRow f && f.Key.Length > 0 ? "[#" + f.Key + "]" : "";

            // Open on the file the field already names, so reopening the picker shows where that
            // file lives instead of starting over. Only [#Key] and [!Key] name one; a feature name
            // or a blank field lands on the first folder that actually holds files.
            string want = (current ?? "").Trim();
            string wantKey = want.Length > 3 && want[0] == '[' && want[^1] == ']'
                             && (want[1] == '#' || want[1] == '!')
                           ? want.Substring(2, want.Length - 3) : "";

            TreeViewItem? selected = null;
            if (wantKey.Length > 0)
                foreach (var item in items)
                {
                    if (item.Tag is not InstallDirNode node) continue;
                    foreach (var fr in node.FileRows)
                        if (string.Equals(FileKeyOf(fr), wantKey, StringComparison.OrdinalIgnoreCase))
                        { selected = item; break; }
                    if (selected != null) break;
                }
            if (selected == null)
                foreach (var item in items)
                    if (item.Tag is InstallDirNode node && node.FileRows.Count > 0) { selected = item; break; }

            foreach (var top in tree.Items.OfType<TreeViewItem>()) top.IsExpanded = true;
            if (selected != null)
            {
                for (var p = selected.Parent as TreeViewItem; p != null; p = p.Parent as TreeViewItem)
                    p.IsExpanded = true;
                selected.IsSelected = true;
                ShowFolder(selected.Tag as InstallDirNode);
                if (wantKey.Length > 0)
                    foreach (var hit in list.Items.OfType<FileRow>())
                        if (string.Equals(hit.Key, wantKey, StringComparison.OrdinalIgnoreCase))
                        { list.SelectedItem = hit; break; }
                var focusOn = selected;
                win.ContentRendered += (_, _) => { try { focusOn.BringIntoView(); focusOn.Focus(); } catch { } };
            }

            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            string? result = null;
            void Accept()
            {
                if (list.SelectedItem is not FileRow f || f.Key.Length == 0)
                {
                    MstMessage("Select a file on the right.\n\n"
                             + "The tree on the left holds the package's folders; choosing one "
                             + "shows the files that install into it.",
                        title, MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                result = "[#" + f.Key + "]";
                win.Close();
            }
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", Accept),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);
            list.MouseDoubleClick += (_, _) => { if (list.SelectedItem is FileRow) Accept(); };

            win.ShowDialog();
            return result;
        }

        /// <summary>
        /// Picks one of the package's folders and returns its Directory-table key, or null when
        /// cancelled. The key is what comes back, not the bracketed path PickInstallDirectory
        /// returns, because these fields hold "a directory key or property".
        ///
        /// Shown as the Directory tree rather than a flat list of keys, since a key on its own says
        /// nothing about where it is. dir54C14FE300C39E643B67195A84937EF9 is unidentifiable in a
        /// list and obvious once it is sitting under Program Files with a name and a file count.
        ///
        /// Falls back to the flat list when the package has no Directory table.
        /// </summary>
        private string? PickDirectoryKey(string title, string current)
        {
            var roots = BuildInstallDirTree();
            if (roots.Count == 0) return PickFromPackage(title, PackageDirs());

            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 560; win.MaxWidth = 560;

            int r = 0;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var intro = new TextBlock
            {
                Text = "The package's folders. The number beside each one is how many files land "
                     + "in it and everything under it.",
                FontSize = 12, TextWrapping = TextWrapping.Wrap, Foreground = valFg,
                Margin = new Thickness(0, 2, 0, 8)
            };
            Grid.SetRow(intro, r); Grid.SetColumn(intro, 0); Grid.SetColumnSpan(intro, 2);
            cg.Children.Add(intro); r++;

            var tree = new TreeView
            {
                Height = 300, FontSize = 12, Foreground = valFg,
                Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                Padding = new Thickness(4)
            };
            tree.SetValue(ScrollViewer.HorizontalScrollBarVisibilityProperty, ScrollBarVisibility.Auto);

            // The selection colours the page's own trees use. A dialog is a separate Window, so it
            // never sees them and would otherwise fall back to the system highlight.
            var selBg = new SolidColorBrush(Color.FromArgb(0x55, 0x6C, 0x63, 0xFF));
            tree.Resources[SystemColors.HighlightBrushKey]                      = selBg;
            tree.Resources[SystemColors.InactiveSelectionHighlightBrushKey]     = selBg;
            tree.Resources[SystemColors.HighlightTextBrushKey]                  = Brushes.White;
            tree.Resources[SystemColors.InactiveSelectionHighlightTextBrushKey] = Brushes.White;

            var iconBrush = new SolidColorBrush(Color.FromRgb(0x4C, 0x9A, 0xFF));
            var items = new List<TreeViewItem>();

            TreeViewItem AddNode(InstallDirNode n, ItemCollection into)
            {
                var head = new StackPanel { Orientation = Orientation.Horizontal };
                head.Children.Add(new System.Windows.Shapes.Path
                {
                    Data = MsiIcons.Folder, Stroke = iconBrush, Fill = Brushes.Transparent,
                    StrokeThickness = 2, StrokeLineJoin = PenLineJoin.Round,
                    Width = 15, Height = 15, Stretch = Stretch.Uniform,
                    Margin = new Thickness(0, 0, 7, 0), VerticalAlignment = VerticalAlignment.Center
                });
                head.Children.Add(new TextBlock { Text = n.Display, VerticalAlignment = VerticalAlignment.Center });
                head.Children.Add(new TextBlock
                {
                    Text = "  [" + n.Files + "]", FontSize = 11, Opacity = 0.65,
                    VerticalAlignment = VerticalAlignment.Center
                });

                var tvi = new TreeViewItem
                {
                    Header = head, Tag = n, Padding = new Thickness(2),
                    ToolTip = n.Key + "   " + n.Bracketed
                };
                into.Add(tvi);
                items.Add(tvi);
                foreach (var c in n.Children) AddNode(c, tvi.Items);
                return tvi;
            }

            foreach (var root in roots) AddNode(root, tree.Items);

            var host = RoundWrapControl(tree, boxBg, boxBdr);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Grid.SetRow(host, r); Grid.SetColumn(host, 0); Grid.SetColumnSpan(host, 2);
            cg.Children.Add(host); r++;

            NdAddSpacer(cg, r++);

            // Two lines rather than one: the key is the value the field takes, and the path is what
            // says which folder that key actually is. A generated key tells you nothing on its own.
            TextBox AddReadRow(string label, string tip)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var l = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lblFg, VerticalAlignment = VerticalAlignment.Center
                };
                var tb = new TextBox
                {
                    FontSize = 12, Padding = new Thickness(8, 5, 8, 5), IsReadOnly = true,
                    Background = Brushes.Transparent, Foreground = valFg,
                    BorderThickness = new Thickness(0), ToolTip = tip,
                    VerticalContentAlignment = VerticalAlignment.Center,
                    Cursor = System.Windows.Input.Cursors.Arrow
                };
                var bd = new Border
                {
                    Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true,
                    Margin = new Thickness(0, 2, 0, 2), Child = tb
                };
                Grid.SetRow(l, r); Grid.SetColumn(l, 0);
                Grid.SetRow(bd, r); Grid.SetColumn(bd, 1);
                cg.Children.Add(l); cg.Children.Add(bd); r++;
                return tb;
            }
            var keyBox  = AddReadRow("Folder", "The Directory-table key, which is the value this field takes.");
            var pathBox = AddReadRow("Resolves to", "Where that key installs to.");

            tree.SelectedItemChanged += (_, ev) =>
            {
                var node = (ev.NewValue as TreeViewItem)?.Tag as InstallDirNode;
                keyBox.Text  = node?.Key ?? "";
                pathBox.Text = node?.Bracketed ?? "";
            };

            // Open on the folder the field already names, so reopening shows where that key is.
            string want = (current ?? "").Trim();
            TreeViewItem? selected = null;
            if (want.Length > 0)
                foreach (var item in items)
                    if (item.Tag is InstallDirNode node
                        && string.Equals(node.Key, want, StringComparison.OrdinalIgnoreCase))
                    { selected = item; break; }

            foreach (var top in tree.Items.OfType<TreeViewItem>()) top.IsExpanded = true;
            if (selected != null)
            {
                for (var p = selected.Parent as TreeViewItem; p != null; p = p.Parent as TreeViewItem)
                    p.IsExpanded = true;
                selected.IsSelected = true;
                if (selected.Tag is InstallDirNode node)
                { keyBox.Text = node.Key; pathBox.Text = node.Bracketed; }
                var focusOn = selected;
                win.ContentRendered += (_, _) => { try { focusOn.BringIntoView(); focusOn.Focus(); } catch { } };
            }

            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            string? result = null;
            void Accept()
            {
                string v = keyBox.Text.Trim();
                if (v.Length == 0)
                {
                    MstMessage("Select a folder in the tree.", title,
                        MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                result = v;
                win.Close();
            }
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", Accept),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);
            tree.MouseDoubleClick += (_, _) => { if (keyBox.Text.Trim().Length > 0) Accept(); };

            win.ShowDialog();
            return result;
        }

        private System.Collections.Generic.List<(string value, string display)> PackageFiles()
        {
            var outp = new System.Collections.Generic.List<(string value, string display)>();
            var fst = EnsureTableCached("File");
            // The component is shown beside each file because it is what a shortcut ends up
            // attached to, so the choice of target is also the choice of component.
            bool hasComp = fst != null && fst.Data.Columns.Contains("Component_");
            if (fst != null)
                foreach (DataRow r in fst.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string key = Cv(r["File"]);
                    if (key.Length == 0) continue;
                    string fn = Cv(r["FileName"]); int b = fn.IndexOf('|');
                    string lng = b >= 0 ? fn.Substring(b + 1) : fn;
                    string comp = hasComp ? Cv(r["Component_"]) : "";
                    outp.Add(("[#" + key + "]",
                              (lng.Length > 0 ? lng : key) + "   [#" + key + "]"
                              + (comp.Length > 0 ? "   " + comp : "")));
                }
            outp.Sort((a, b) => string.Compare(a.display, b.display, StringComparison.OrdinalIgnoreCase));
            return outp;
        }

        private System.Collections.Generic.List<(string value, string display)> PackageDirs()
        {
            var outp = new System.Collections.Generic.List<(string value, string display)>();
            var dst = EnsureTableCached("Directory");
            if (dst != null)
                foreach (DataRow r in dst.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string key = Cv(r["Directory"]);
                    if (key.Length == 0) continue;
                    outp.Add((key, key));
                }
            outp.Sort((a, b) => string.Compare(a.display, b.display, StringComparison.OrdinalIgnoreCase));
            return outp;
        }

        /// <summary>
        /// Adds a file from this machine to a table whose data column is a stream, and returns the
        /// key it went in under, or null when nothing was chosen. The row goes in now and its bytes
        /// are written at save time by EmbedAddedStreams, the same two-step the Files view uses for
        /// the files it adds.
        ///
        /// EnsureTableOrCreate rather than EnsureTableCached: a package with no custom actions
        /// carries no Binary table at all, and that is exactly the package someone is adding the
        /// first binary to.
        /// </summary>
        private string? AddStreamRowFromDisk(string title, string filter, string table,
            string keyCol, string fallbackName, Dictionary<string, string> pending)
        {
            var dlg = new OpenFileDialog { Title = title, Filter = filter, CheckFileExists = true };
            if (dlg.ShowDialog() != true) return null;
            string path = dlg.FileName;

            var st = EnsureTableOrCreate(table);
            if (st == null || !st.Data.Columns.Contains(keyCol))
            {
                MstMessage($"This package has no {table} table and one could not be created, so "
                         + "there is nowhere for the file to go.",
                    title, MessageBoxButton.OK, MessageBoxImage.Warning);
                return null;
            }

            // Whatever uses the row points at it by name, so the name is the key and has to be
            // unique. The file's own name is what an author expects to find in the table, run
            // through the identifier rules first: these key columns are identifiers, so a space or
            // a dash cannot stay in one.
            string leaf = System.IO.Path.GetFileName(path);
            string key = UniqueKey(st.Data, keyCol, FileKeyFromName(leaf.Length > 0 ? leaf : fallbackName));

            var nr = st.Data.NewRow();
            nr[keyCol] = key;
            st.Data.Rows.Add(nr);
            pending[key] = path;

            UpdateEditCount();
            return key;
        }

        private string? AddIconFromDisk() => AddStreamRowFromDisk(
            "Select an icon",
            "Icon files (*.ico)|*.ico"
            + "|Programs and libraries (*.exe;*.dll)|*.exe;*.dll"
            + "|All files (*.*)|*.*",
            "Icon", "Name", "Icon.ico", _addedIconSources);

        private string? AddBinaryFromDisk() => AddStreamRowFromDisk(
            "Select a binary",
            "Programs and libraries (*.dll;*.exe)|*.dll;*.exe"
            + "|Scripts (*.vbs;*.js)|*.vbs;*.js"
            + "|All files (*.*)|*.*",
            "Binary", "Name", "Binary.dll", _addedBinarySources);

        private System.Collections.Generic.List<(string value, string display)> PackageIcons()
        {
            var outp = new System.Collections.Generic.List<(string value, string display)>();
            var ist = EnsureTableCached("Icon");
            if (ist != null)
                foreach (DataRow r in ist.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string key = Cv(r["Name"]);
                    if (key.Length == 0) continue;
                    outp.Add((key, key));
                }
            outp.Sort((a, b) => string.Compare(a.display, b.display, StringComparison.OrdinalIgnoreCase));
            return outp;
        }

        // Small styled text-input dialog (reuses the shared dialog shell). Returns
        // the entered text, or null if cancelled.
        private string? PromptText(string title, string label, string initial)
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);

            int r = 0;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var lbl = new TextBlock
            {
                Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, VerticalAlignment = VerticalAlignment.Center
            };
            var box = new TextBox
            {
                Text = initial, FontSize = 12, Padding = new Thickness(8, 5, 8, 5),
                Background = Brushes.Transparent, Foreground = valFg, BorderThickness = new Thickness(0),
                VerticalContentAlignment = VerticalAlignment.Center
            };
            var boxField = new Border
            {
                Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true, Child = box
            };
            Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0);
            Grid.SetRow(boxField, r); Grid.SetColumn(boxField, 1);
            cg.Children.Add(lbl); cg.Children.Add(boxField);
            r++;
            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            string? result = null;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK",     () => { result = box.Text; win.Close(); }),
                ("\u2715 Cancel", () => { result = null;     win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);

            box.Loaded   += (_, _)  => { box.SelectAll(); box.Focus(); };
            box.KeyDown  += (_, ev) => { if (ev.Key == Key.Enter) { result = box.Text; win.Close(); } };

            win.ShowDialog();
            return result;
        }

        // ── Read / write helpers (all go through the cached DataTables) ──────
        private TableState? EnsureTableCached(string name)
        {
            if (_msiPath.Length == 0) return null;
            if (_tables.TryGetValue(name, out var st)) return st;
            st = LoadTable(name);
            if (st != null) _tables[name] = st;
            return st;
        }

        private static DataRow? FindLiveRow(TableState st, string keyCol, string keyVal)
        {
            if (!st.Data.Columns.Contains(keyCol)) return null;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted) continue;
                if (string.Equals((r[keyCol] ?? "").ToString(), keyVal, StringComparison.Ordinal)) return r;
            }
            return null;
        }

        private string GetProperty(string prop)
        {
            var st = EnsureTableCached("Property");
            if (st == null || !st.Data.Columns.Contains("Value")) return "";
            var r = FindLiveRow(st, "Property", prop);
            return r == null ? "" : (r["Value"] ?? "").ToString();
        }

        // Stages a Property value: edits the existing row, adds one if missing, or
        // (when value is blank) removes a row that exists. All as tracked edits.
        private void SetProperty(string prop, string value)
        {
            var st = EnsureTableCached("Property");
            if (st == null || !st.Data.Columns.Contains("Property") || !st.Data.Columns.Contains("Value")) return;
            value ??= "";
            var r = FindLiveRow(st, "Property", prop);
            if (r != null)
            {
                if ((r["Value"] ?? "").ToString() == value) return;     // no-op
                if (value.Length == 0 && r.RowState == DataRowState.Added)
                    r.Delete();                                         // a row we just added → drop it
                else
                    r["Value"] = value;                                 // → Modified
            }
            else
            {
                if (value.Length == 0) return;                          // nothing to add
                var nr = st.Data.NewRow();
                nr["Property"] = prop; nr["Value"] = value;
                st.Data.Rows.Add(nr);                                   // → Added
            }
            UpdateEditCount();
        }

        /// <summary>
        /// Directory keys authoring tools conventionally use for the application folder. Checked
        /// before falling back to counting files.
        /// </summary>
        private static readonly string[] InstallDirKeys =
        {
            "INSTALLDIR", "INSTALLFOLDER", "INSTALLLOCATION", "APPLICATIONFOLDER", "APPDIR", "TARGETDIR",
        };

        /// <summary>
        /// Where the package actually installs its files, as a bracketed path such as
        /// [ProgramFiles64Folder]FileCompare.
        ///
        /// The INSTALLDIR field shows the INSTALLDIR property, which is how a transform overrides
        /// the install location - but plenty of packages never define it at all: nothing is
        /// wrong, the location simply lives in the Directory table instead, and the field looked
        /// empty as though the information were missing.
        ///
        /// Detection prefers a directory whose key is one of the conventional names, and otherwise
        /// takes whichever directory holds the most files, which is the application folder in every
        /// normal package. Returns "" when the package has no File table to judge by.
        /// </summary>
        private string DetectInstallDirectory()
        {
            string key = DetectInstallDirectoryKey();
            return key.Length > 0 ? ResolveDirectoryPath(key) : "";
        }

        /// <summary>
        /// The Directory table key behind the folder above. This is the row that has to move when
        /// the install location changes, so detection has to yield the key and not only the path.
        /// Returns "" when the package gives nothing to go on.
        /// </summary>
        private string DetectInstallDirectoryKey()
        {
            foreach (string key in InstallDirKeys)
                if (!string.Equals(key, "TARGETDIR", StringComparison.OrdinalIgnoreCase)
                    && FindTableRow("Directory", "Directory", key) != null)
                    return key;

            // Component -> its directory, so file counts can be attributed to a folder.
            var compDir = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            var compSt = EnsureTableCached("Component");
            if (compSt != null && compSt.Data.Columns.Contains("Component") && compSt.Data.Columns.Contains("Directory_"))
                foreach (DataRow r in compSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string c = Cv(r["Component"]);
                    if (c.Length > 0) compDir[c] = Cv(r["Directory_"]);
                }

            var counts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            var fileSt = EnsureTableCached("File");
            if (fileSt != null && fileSt.Data.Columns.Contains("Component_"))
                foreach (DataRow r in fileSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (!compDir.TryGetValue(Cv(r["Component_"]), out var dir) || dir.Length == 0) continue;
                    counts[dir] = counts.TryGetValue(dir, out var n) ? n + 1 : 1;
                }

            if (counts.Count == 0) return "";
            string best = ""; int bestCount = -1;
            foreach (var kv in counts)
                if (kv.Value > bestCount) { best = kv.Key; bestCount = kv.Value; }

            return best;
        }

        /// <summary>
        /// Shows the detected install folder behind the box while no INSTALLDIR property is set, so
        /// the location is visible without a property being invented for it. Setting or browsing a
        /// value hides the hint, because then the field speaks for itself.
        /// </summary>
        private void RefreshInstallDirHint()
        {
            if (FpInstallDirHint == null) return;
            bool empty = string.IsNullOrWhiteSpace(FpInstallDir?.Text);
            if (!empty) { FpInstallDirHint.Visibility = Visibility.Collapsed; return; }

            string detected = "";
            try { detected = DetectInstallDirectory(); } catch { }
            FpInstallDirHint.Text = detected;
            FpInstallDirHint.ToolTip = detected.Length > 0
                ? "Detected from the Directory table. This package defines no INSTALLDIR property; browse to set one."
                : null;
            FpInstallDirHint.Visibility = detected.Length > 0 ? Visibility.Visible : Visibility.Collapsed;
        }

        // ── INSTALLDIR path tokens ──────────────────────────────────────────────────────
        // A folder picker can only hand back a path on this machine, such as
        // C:\Program Files (x86)\FileCompare. Stored as-is, that pins the package to one machine's
        // layout: a different drive letter, a localised Windows, or the 32-bit tree on a 64-bit
        // box all break it. Windows Installer already has a property for each of these roots, so
        // a picked folder is written back as [ProgramFilesFolder]FileCompare instead, which resolves
        // to the right place wherever the package lands.

        /// <summary>
        /// Standard Windows folders and the MSI property that stands for each, longest path first
        /// so the most specific root wins (Common Files sits inside Program Files). Built once,
        /// from the machine doing the packaging, since that is the machine whose paths the folder
        /// picker returns.
        /// </summary>
        private static List<KeyValuePair<string, string>>? _msiFolderRoots;

        private static string MsiEnvDir(string variable)
        {
            try { return Environment.GetEnvironmentVariable(variable) ?? ""; }
            catch { return ""; }
        }

        private static string MsiSpecialDir(Environment.SpecialFolder folder)
        {
            try { return Environment.GetFolderPath(folder) ?? ""; }
            catch { return ""; }
        }

        /// <summary>
        /// A path with surrounding quotes and trailing separators removed. "C:\" becomes "C:",
        /// which is how the volume root is stored so that prefix matching stays uniform.
        /// </summary>
        private static string MsiTrimDirSep(string? path)
        {
            string s = (path ?? "").Trim().Trim('"');
            while (s.Length > 0 && (s[s.Length - 1] == '\\' || s[s.Length - 1] == '/'))
                s = s.Substring(0, s.Length - 1);
            return s;
        }

        /// <summary>Adds a root, ignoring anything unusable and keeping the first token claimed
        /// for a given path (the specific variables are added before the generic ones).</summary>
        private static void MsiAddFolderRoot(List<KeyValuePair<string, string>> list, string path, string token)
        {
            string p = MsiTrimDirSep(path);
            if (p.Length < 2) return;
            foreach (var e in list)
                if (string.Equals(e.Key, p, StringComparison.OrdinalIgnoreCase)) return;
            list.Add(new KeyValuePair<string, string>(p, token));
        }

        private static List<KeyValuePair<string, string>> MsiFolderRoots()
        {
            if (_msiFolderRoots != null) return _msiFolderRoots;

            var list = new List<KeyValuePair<string, string>>();

            // Program Files. On a 64-bit OS, ProgramFilesFolder is the (x86) tree and
            // ProgramFiles64Folder is the native one. The plain variables are the 32-bit-OS
            // fallback and drop out as duplicates when the specific ones already matched.
            MsiAddFolderRoot(list, MsiEnvDir("CommonProgramW6432"),      "CommonFiles64Folder");
            MsiAddFolderRoot(list, MsiEnvDir("CommonProgramFiles(x86)"), "CommonFilesFolder");
            MsiAddFolderRoot(list, MsiEnvDir("CommonProgramFiles"),      "CommonFilesFolder");
            MsiAddFolderRoot(list, MsiEnvDir("ProgramW6432"),            "ProgramFiles64Folder");
            MsiAddFolderRoot(list, MsiEnvDir("ProgramFiles(x86)"),       "ProgramFilesFolder");
            MsiAddFolderRoot(list, MsiEnvDir("ProgramFiles"),            "ProgramFilesFolder");

            // Machine-wide and per-user data.
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.CommonApplicationData), "CommonAppDataFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.LocalApplicationData),  "LocalAppDataFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.ApplicationData),       "AppDataFolder");

            // Shell folders.
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.DesktopDirectory), "DesktopFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.Programs),         "ProgramMenuFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.StartMenu),        "StartMenuFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.Startup),          "StartupFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.MyDocuments),      "PersonalFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.MyPictures),       "MyPicturesFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.Favorites),        "FavoritesFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.Templates),        "TemplateFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.AdminTools),       "AdminToolsFolder");
            MsiAddFolderRoot(list, MsiSpecialDir(Environment.SpecialFolder.Fonts),            "FontsFolder");

            // Windows itself. System32 is composed from the Windows folder rather than read via
            // SpecialFolder.System, which a 32-bit process would see redirected to SysWOW64.
            string windows = MsiTrimDirSep(MsiSpecialDir(Environment.SpecialFolder.Windows));
            if (windows.Length == 0) windows = MsiTrimDirSep(MsiEnvDir("SystemRoot"));
            if (windows.Length > 0)
            {
                if (Environment.Is64BitOperatingSystem)
                {
                    MsiAddFolderRoot(list, windows + "\\System32", "System64Folder");
                    MsiAddFolderRoot(list, windows + "\\SysWOW64", "SystemFolder");
                }
                else
                {
                    MsiAddFolderRoot(list, windows + "\\System32", "SystemFolder");
                }
                MsiAddFolderRoot(list, windows + "\\System", "System16Folder");
                MsiAddFolderRoot(list, windows, "WindowsFolder");
            }

            // Last resort for anything else on the Windows drive: [WindowsVolume]Apps\Tool at
            // least keeps the value off a hard-coded drive letter.
            try
            {
                string vol = MsiTrimDirSep(Path.GetPathRoot(windows.Length > 0 ? windows : "C:\\") ?? "");
                MsiAddFolderRoot(list, vol, "WindowsVolume");
            }
            catch { }

            list.Sort((a, b) => b.Key.Length.CompareTo(a.Key.Length));
            _msiFolderRoots = list;
            return list;
        }

        /// <summary>
        /// True when the path is the root or sits under it. Whole segments only, so
        /// "C:\Program FilesX" is not mistaken for a folder inside "C:\Program Files".
        /// </summary>
        private static bool MsiPathHasRoot(string path, string root, out string tail)
        {
            tail = "";
            if (root.Length == 0 || path.Length < root.Length) return false;
            if (!path.StartsWith(root, StringComparison.OrdinalIgnoreCase)) return false;
            if (path.Length == root.Length) return true;                 // exactly the root
            char sep = path[root.Length];
            if (sep != '\\' && sep != '/') return false;
            tail = path.Substring(root.Length + 1).Replace('/', '\\');
            return true;
        }

        /// <summary>
        /// A picked folder as a bracketed MSI path, so
        /// C:\Program Files (x86)\FileCompare becomes [ProgramFilesFolder]FileCompare. A value that is
        /// already bracketed is left alone, and a path no standard folder covers (D:\Apps\Tool)
        /// comes back unchanged, because there is no portable way to express it.
        /// </summary>
        private static string MsiTokenizePath(string? absolute)
        {
            string path = MsiTrimDirSep(absolute);
            if (path.Length == 0 || path[0] == '[') return path;
            foreach (var root in MsiFolderRoots())
                if (MsiPathHasRoot(path, root.Key, out string tail))
                    return tail.Length > 0 ? "[" + root.Value + "]" + tail : "[" + root.Value + "]";
            return path;
        }

        /// <summary>
        /// The reverse of MsiTokenizePath, used to open the picker where the current value points.
        /// Returns "" for a token that is not one of the standard folders, since nothing local can
        /// be pointed at in that case.
        /// </summary>
        private static string MsiExpandPath(string? bracketed)
        {
            string s = (bracketed ?? "").Trim();
            if (s.Length == 0) return "";
            if (s[0] != '[') return s;                                   // already a real path
            int close = s.IndexOf(']');
            if (close < 2) return "";
            string token = s.Substring(1, close - 1);
            string tail  = s.Substring(close + 1).TrimStart('\\', '/');
            foreach (var root in MsiFolderRoots())
                if (string.Equals(root.Value, token, StringComparison.OrdinalIgnoreCase))
                    return tail.Length > 0 ? root.Key + "\\" + tail : root.Key + "\\";
            return "";
        }

        // ── Install location edits ──────────────────────────────────────────────────────
        // Windows Installer does not expand brackets in a Property value. A directory override
        // read from the Property table is taken as a literal folder name, which is why
        // INSTALLDIR=[ProgramFilesFolder]FileCompare fails at install time with "could not access
        // network location [ProgramFilesFolder]FileCompare". The place that does resolve is the
        // Directory table, so a bracketed path is staged there: the install folder's row is
        // re-parented to the root property and its DefaultDir renamed. An absolute path has no
        // Directory table equivalent, so that, and only that, still goes to the property.

        /// <summary>
        /// Folder properties Windows Installer defines by itself, so a Directory row for one can
        /// be created when the package happens not to have it.
        /// </summary>
        private static readonly HashSet<string> MsiSystemFolders = new(StringComparer.OrdinalIgnoreCase)
        {
            "TARGETDIR", "WindowsVolume", "ProgramFilesFolder", "ProgramFiles64Folder",
            "CommonFilesFolder", "CommonFiles64Folder", "AppDataFolder", "LocalAppDataFolder",
            "CommonAppDataFolder", "DesktopFolder", "StartMenuFolder", "ProgramMenuFolder",
            "StartupFolder", "PersonalFolder", "MyPicturesFolder", "FavoritesFolder",
            "TemplateFolder", "AdminToolsFolder", "FontsFolder", "SystemFolder", "System64Folder",
            "System16Folder", "WindowsFolder", "TempFolder", "NetHoodFolder", "PrintHoodFolder",
            "RecentFolder", "SendToFolder"
        };

        /// <summary>True for a name that already fits 8.3, so DefaultDir needs no short|long pair.</summary>
        private static bool MsiIsShortName(string name)
        {
            if (name.Length == 0 || name.Length > 12) return false;
            int dot = name.IndexOf('.');
            if (dot != name.LastIndexOf('.')) return false;              // at most one extension
            string stem = dot < 0 ? name : name.Substring(0, dot);
            string ext  = dot < 0 ? ""   : name.Substring(dot + 1);
            if (stem.Length == 0 || stem.Length > 8 || ext.Length > 3) return false;
            foreach (char c in name)
                if (c == ' ' || "\\?|><:/*\"+,;=[]".IndexOf(c) >= 0) return false;
            return true;
        }

        /// <summary>A short name for the left half of a DefaultDir pair.</summary>
        private static string MsiShortName(string name)
        {
            var sb = new System.Text.StringBuilder();
            foreach (char c in name.ToUpperInvariant())
                if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || "_-$#&!%(){}@^'".IndexOf(c) >= 0)
                    sb.Append(c);
            string s = sb.ToString();
            if (s.Length > 6) s = s.Substring(0, 6);
            if (s.Length == 0) s = "FOLDER";
            return s + "~1";
        }

        /// <summary>
        /// A DefaultDir cell for a folder name, keeping any ":source" half the row already carried
        /// because that side describes the source layout rather than where the files land.
        /// </summary>
        private static string MsiDefaultDirValue(string folderName, string existing)
        {
            string source = "";
            int colon = (existing ?? "").IndexOf(':');
            if (colon >= 0) source = existing.Substring(colon);
            string target = MsiIsShortName(folderName)
                ? folderName
                : MsiShortName(folderName) + "|" + folderName;
            return target + source;
        }

        /// <summary>An unused Directory key derived from a folder name.</summary>
        private string MsiNewDirectoryKey(string folderName)
        {
            var sb = new System.Text.StringBuilder("D_");
            foreach (char c in folderName)
                sb.Append((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ? c : '_');
            string stem = sb.ToString();
            if (stem.Length > 60) stem = stem.Substring(0, 60);
            string key = stem;
            for (int i = 2; i < 1000 && FindTableRow("Directory", "Directory", key) != null; i++)
                key = stem + "_" + i;
            return key;
        }

        private void MsiAddDirectoryRow(string key, string parent, string defaultDir)
        {
            var st = EnsureTableCached("Directory");
            if (st == null || !st.Data.Columns.Contains("Directory")) return;
            var nr = st.Data.NewRow();
            nr["Directory"] = key;
            if (st.Data.Columns.Contains("Directory_Parent")) nr["Directory_Parent"] = parent;
            if (st.Data.Columns.Contains("DefaultDir"))       nr["DefaultDir"]       = defaultDir;
            st.Data.Rows.Add(nr);                                        // -> Added
            UpdateEditCount();
        }

        /// <summary>
        /// Points a Directory row at a parent under a name, adding the row when it is missing.
        /// Cells are only touched when they differ, so re-applying the value the package already
        /// has stages nothing.
        /// </summary>
        private void MsiSetDirectoryRow(string key, string parent, string defaultDir)
        {
            var row = FindTableRow("Directory", "Directory", key);
            if (row == null) { MsiAddDirectoryRow(key, parent, defaultDir); return; }

            bool changed = false;
            if (row.Table.Columns.Contains("Directory_Parent") && Cv(row["Directory_Parent"]) != parent)
            { row["Directory_Parent"] = parent; changed = true; }
            if (row.Table.Columns.Contains("DefaultDir") && Cv(row["DefaultDir"]) != defaultDir)
            { row["DefaultDir"] = defaultDir; changed = true; }
            if (changed) UpdateEditCount();
        }

        /// <summary>
        /// The key of the child of parentKey called folderName, creating the row when no such
        /// child exists. skipKey is the install folder itself, which must never end up as its own
        /// parent when the new path passes through a folder of the same name.
        /// </summary>
        private string MsiChildDirectoryKey(string parentKey, string folderName, string skipKey)
        {
            var st = EnsureTableCached("Directory");
            if (st != null && st.Data.Columns.Contains("Directory")
                && st.Data.Columns.Contains("Directory_Parent") && st.Data.Columns.Contains("DefaultDir"))
                foreach (DataRow r in st.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string k = Cv(r["Directory"]);
                    if (k.Length == 0 || string.Equals(k, skipKey, StringComparison.OrdinalIgnoreCase)) continue;
                    if (!string.Equals(Cv(r["Directory_Parent"]), parentKey, StringComparison.OrdinalIgnoreCase)) continue;
                    if (string.Equals(MsiLongDirName(Cv(r["DefaultDir"])), folderName, StringComparison.OrdinalIgnoreCase))
                        return k;
                }

            string key = MsiNewDirectoryKey(folderName);
            MsiAddDirectoryRow(key, parentKey, MsiDefaultDirValue(folderName, ""));
            return key;
        }

        /// <summary>
        /// Stages the install location. A bracketed path goes into the Directory table, which is
        /// the only form the installer resolves; an absolute path can only be said as a property
        /// override and is stored that way. A bracketed value never reaches the Property table,
        /// because the installer would create a folder of that literal name.
        /// </summary>
        private void ApplyInstallDirPath(string value)
        {
            string v = (value ?? "").Trim();

            // Cleared: drop any override and leave the Directory table as the package has it.
            if (v.Length == 0) { SetProperty("INSTALLDIR", ""); return; }

            // D:\Apps\Tool and the like. No Directory row can name a volume the package knows
            // nothing about, so the property override is the only way to say it - and it only
            // holds on machines laid out like this one.
            if (v[0] != '[') { SetProperty("INSTALLDIR", v); return; }

            int close = v.IndexOf(']');
            string root = close > 1 ? v.Substring(1, close - 1).Trim() : "";
            string tail = close > 1 ? v.Substring(close + 1).Replace('/', '\\').Trim().Trim('\\') : "";
            if (root.Length == 0)
            {
                MstMessage("That is not a location this package can resolve.\n\n" +
                           "Use a form such as [ProgramFilesFolder]MyApp, or browse for a folder.",
                           "Install location", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            string dirKey = "";
            try { dirKey = DetectInstallDirectoryKey(); } catch { }
            if (dirKey.Length == 0)
            {
                MstMessage("This package has no install folder in its Directory table, so there " +
                           "is nothing to point somewhere else.", "Install location",
                           MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            // Already installs there: nothing to stage. This is what makes simply leaving the
            // field, which commits it, harmless when the value was not touched.
            string want = tail.Length > 0 ? "[" + root + "]" + tail : "[" + root + "]";
            if (GetProperty("INSTALLDIR").Length == 0
                && string.Equals(ResolveDirectoryPath(dirKey), want, StringComparison.OrdinalIgnoreCase))
                return;

            if (FindTableRow("Directory", "Directory", root) == null)
            {
                if (!MsiSystemFolders.Contains(root))
                {
                    MstMessage("[" + root + "] is neither a folder this package defines nor one " +
                               "Windows Installer provides.", "Install location",
                               MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
                MsiAddDirectoryRow(root, "TARGETDIR", ".");
            }

            // Folders between the root and the install folder, reusing rows that already exist.
            string parent = root;
            string[] segs = tail.Length > 0 ? tail.Split('\\') : Array.Empty<string>();
            for (int i = 0; i + 1 < segs.Length; i++)
                if (segs[i].Length > 0)
                    parent = MsiChildDirectoryKey(parent, segs[i], dirKey);

            string leaf   = segs.Length > 0 ? segs[segs.Length - 1] : "";
            var    dirRow = FindTableRow("Directory", "Directory", dirKey);
            string had    = dirRow != null && dirRow.Table.Columns.Contains("DefaultDir")
                            ? Cv(dirRow["DefaultDir"]) : "";
            MsiSetDirectoryRow(dirKey, parent, leaf.Length > 0 ? MsiDefaultDirValue(leaf, had) : ".");

            // A property named after the directory overrides everything above, so an override
            // staged earlier (including one this page wrote before) is cleared.
            SetProperty("INSTALLDIR", "");
            if (!string.Equals(dirKey, "INSTALLDIR", StringComparison.OrdinalIgnoreCase))
                SetProperty(dirKey, "");
        }

        /// <summary>
        /// Shows the location the package will actually use: the property override when one is
        /// set, otherwise the folder its Directory table resolves to.
        /// </summary>
        private void RefreshInstallDirField()
        {
            if (FpInstallDir == null) return;

            string v = "";
            try
            {
                v = GetProperty("INSTALLDIR");
                if (v.Length == 0) v = DetectInstallDirectory();
            }
            catch { }

            bool prior = _loadingForm;
            _loadingForm = true;
            try { FpInstallDir.Text = v; }
            finally { _loadingForm = prior; }
            RefreshInstallDirHint();
        }

        // Browse picks a destination folder out of the package itself and stages it as the install
        // location. The folder that matters here lives in the Directory table, not on this machine,
        // so the picker shows that tree rather than the local disk.
        private void BtnBrowseInstallDir_Click(object sender, RoutedEventArgs e)
        {
            if (_msiPath.Length == 0) return;

            string current = (FpInstallDir?.Text ?? "").Trim();
            if (current.Length == 0) current = (FpInstallDirHint?.Text ?? "").Trim();

            string? picked = PickInstallDirectory(current);
            if (picked == null || picked.Length == 0) return;

            ApplyInstallDirPath(picked);
            RefreshInstallDirField();
        }

        // ── Install folder picker ───────────────────────────────────────────────────────
        // A shell folder picker can only offer folders that exist on the machine doing the
        // packaging, which is the wrong set twice over: it lists folders the package knows nothing
        // about, hides the ones it actually defines, and leaves the bracketed value to be guessed
        // back from a local path. The package already carries the tree that is wanted - the
        // Directory table - so that is what the picker shows, the way an MSI editor does.

        /// <summary>
        /// One folder in the picker: its Directory-table key, the bracketed path it resolves to,
        /// and how many files land in it and everything below it.
        /// </summary>
        private sealed class InstallDirNode
        {
            public string Key = "";        // Directory-table key
            public string Name = "";       // folder name from DefaultDir ("" when it adds none)
            public string Display = "";    // label shown in the tree
            public string Bracketed = "";  // [ProgramFilesFolder]MyApp
            public int    Files;           // this folder plus everything under it
            // The File rows landing in this folder itself. Files ends up a subtree total and so
            // cannot be read back as a list, and the file picker needs the rows, not a number.
            public readonly List<DataRow> FileRows = new();
            public readonly List<InstallDirNode> Children = new();
        }

        /// <summary>
        /// The Directory table as a tree. TARGETDIR sits at the top the way the table has it, and a
        /// row whose parent is missing hangs there too rather than being dropped, so nothing in the
        /// table is hidden from the picker.
        /// </summary>
        private List<InstallDirNode> BuildInstallDirTree()
        {
            var roots = new List<InstallDirNode>();
            var st = EnsureTableCached("Directory");
            if (st == null || !st.Data.Columns.Contains("Directory")) return roots;

            var nodes   = new Dictionary<string, InstallDirNode>(StringComparer.OrdinalIgnoreCase);
            var parents = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted || st.MarkedDelete.Contains(r)) continue;
                string key = Cv(r["Directory"]);
                if (key.Length == 0 || nodes.ContainsKey(key)) continue;
                nodes[key] = new InstallDirNode
                {
                    Key  = key,
                    Name = MsiLongDirName(st.Data.Columns.Contains("DefaultDir") ? Cv(r["DefaultDir"]) : "")
                };
                parents[key] = st.Data.Columns.Contains("Directory_Parent") ? Cv(r["Directory_Parent"]) : "";
            }
            if (nodes.Count == 0) return roots;

            // A file belongs to a component, and a component names the folder it installs to, so
            // the count has to come through that pair rather than off the File row.
            var compDir = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            var compSt  = EnsureTableCached("Component");
            if (compSt != null && compSt.Data.Columns.Contains("Component") && compSt.Data.Columns.Contains("Directory_"))
                foreach (DataRow r in compSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string c = Cv(r["Component"]);
                    if (c.Length > 0) compDir[c] = Cv(r["Directory_"]);
                }

            var fileSt = EnsureTableCached("File");
            if (fileSt != null && fileSt.Data.Columns.Contains("Component_"))
                foreach (DataRow r in fileSt.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (compDir.TryGetValue(Cv(r["Component_"]), out var dir)
                        && dir.Length > 0 && nodes.TryGetValue(dir, out var n))
                    { n.Files++; n.FileRows.Add(r); }
                }

            foreach (var kv in nodes)
            {
                string parent = parents[kv.Key];
                if (parent.Length > 0
                    && !string.Equals(parent, kv.Key, StringComparison.OrdinalIgnoreCase)
                    && nodes.TryGetValue(parent, out var p))
                    p.Children.Add(kv.Value);
                else
                    roots.Add(kv.Value);
            }

            foreach (var n in roots) ResolveInstallDirNode(n, "");
            SortInstallDirNodes(roots);
            return roots;
        }

        /// <summary>
        /// Labels a folder, works out the bracketed path it stands for, and does the same for
        /// everything under it. A path starts at the nearest folder Windows Installer resolves on
        /// its own and appends the folder names below it, so what the tree shows for a folder is
        /// the value that would install there. Returns the file count for the whole subtree, which
        /// each folder keeps, so a root can say how much of the package lands under it.
        ///
        /// The nearest such folder is not always the one directly under TARGETDIR: authoring tools
        /// nest CommonFilesFolder inside ProgramFilesFolder because that is where it physically
        /// sits, yet it is still a property in its own right and resolves to Common Files wherever
        /// the table happens to put it.
        /// </summary>
        private static int ResolveInstallDirNode(InstallDirNode node, string parentPath)
        {
            if (parentPath.Length == 0 || MsiSystemFolders.Contains(node.Key))
            {
                // A root: its key is the property, which is both the label and the path.
                node.Display   = "[" + node.Key + "]";
                node.Bracketed = "[" + node.Key + "]";
            }
            else if (node.Name.Length == 0)
            {
                // DefaultDir "." means the same folder as the parent, so it adds no segment.
                node.Display   = "[" + node.Key + "]";
                node.Bracketed = parentPath;
            }
            else
            {
                node.Display   = node.Name;
                node.Bracketed = parentPath.EndsWith("]", StringComparison.Ordinal)
                               ? parentPath + node.Name
                               : parentPath + "\\" + node.Name;
            }

            // TARGETDIR is the volume the package installs to and never appears in a bracketed
            // path, so its children each start one of their own.
            string childPath = string.Equals(node.Key, "TARGETDIR", StringComparison.OrdinalIgnoreCase)
                             ? "" : node.Bracketed;

            int total = node.Files;
            foreach (var c in node.Children) total += ResolveInstallDirNode(c, childPath);
            node.Files = total;
            return total;
        }

        private static void SortInstallDirNodes(List<InstallDirNode> list)
        {
            list.Sort((a, b) => string.Compare(a.Display, b.Display, StringComparison.OrdinalIgnoreCase));
            foreach (var n in list) SortInstallDirNodes(n.Children);
        }

        /// <summary>
        /// Shows the package's destination folders and returns the bracketed path of the one
        /// chosen, or null when the dialog is cancelled. The box under the tree carries the
        /// selection and stays editable, so a folder the package does not define yet is reached by
        /// typing a name onto the end of one it does - which is what the shell picker was for.
        /// </summary>
        private string? PickInstallDirectory(string current)
        {
            var roots = BuildInstallDirTree();
            if (roots.Count == 0)
            {
                MstMessage("This package has no Directory table, so there are no install folders to choose from.",
                           "Select install folder", MessageBoxButton.OK, MessageBoxImage.Warning);
                return null;
            }

            const string title = "Select install folder";
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 560; win.MaxWidth = 560;

            int r = 0;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var intro = new TextBlock
            {
                Text = "Folders this package installs to. The number beside each one is how many "
                     + "files land in it and everything under it.",
                FontSize = 12, TextWrapping = TextWrapping.Wrap, Foreground = valFg,
                Margin = new Thickness(0, 2, 0, 8)
            };
            Grid.SetRow(intro, r); Grid.SetColumn(intro, 0); Grid.SetColumnSpan(intro, 2);
            cg.Children.Add(intro); r++;

            var tree = new TreeView
            {
                Height = 300, FontSize = 12, Foreground = valFg,
                Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                Padding = new Thickness(4)
            };
            tree.SetValue(ScrollViewer.HorizontalScrollBarVisibilityProperty, ScrollBarVisibility.Auto);

            // The selection colours the page's own trees use. A dialog is a separate Window, so it
            // never sees them and would otherwise fall back to the system highlight, which is the
            // one colour the theme has no say over.
            var selBg = new SolidColorBrush(Color.FromArgb(0x55, 0x6C, 0x63, 0xFF));
            tree.Resources[SystemColors.HighlightBrushKey]                        = selBg;
            tree.Resources[SystemColors.InactiveSelectionHighlightBrushKey]       = selBg;
            tree.Resources[SystemColors.HighlightTextBrushKey]                    = Brushes.White;
            tree.Resources[SystemColors.InactiveSelectionHighlightTextBrushKey]   = Brushes.White;

            var iconBrush = new SolidColorBrush(Color.FromRgb(0x4C, 0x9A, 0xFF));
            var items = new List<TreeViewItem>();

            TreeViewItem AddNode(InstallDirNode n, ItemCollection into)
            {
                var head = new StackPanel { Orientation = Orientation.Horizontal };
                head.Children.Add(new System.Windows.Shapes.Path
                {
                    Data = MsiIcons.Folder, Stroke = iconBrush, Fill = Brushes.Transparent,
                    StrokeThickness = 2, StrokeLineJoin = PenLineJoin.Round,
                    Width = 15, Height = 15, Stretch = Stretch.Uniform,
                    Margin = new Thickness(0, 0, 7, 0), VerticalAlignment = VerticalAlignment.Center
                });
                head.Children.Add(new TextBlock { Text = n.Display, VerticalAlignment = VerticalAlignment.Center });
                // Opacity rather than a second brush, so the count dims with the row's own colour
                // instead of staying grey against the selection highlight.
                head.Children.Add(new TextBlock
                {
                    Text = "  [" + n.Files + "]", FontSize = 11, Opacity = 0.65,
                    VerticalAlignment = VerticalAlignment.Center
                });

                var tvi = new TreeViewItem { Header = head, Tag = n, Padding = new Thickness(2) };
                into.Add(tvi);
                items.Add(tvi);
                foreach (var c in n.Children) AddNode(c, tvi.Items);
                return tvi;
            }

            foreach (var root in roots) AddNode(root, tree.Items);

            var host = RoundWrapControl(tree, boxBg, boxBdr);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Grid.SetRow(host, r); Grid.SetColumn(host, 0); Grid.SetColumnSpan(host, 2);
            cg.Children.Add(host); r++;

            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var lbl = new TextBlock
            {
                Text = "Folder", FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, VerticalAlignment = VerticalAlignment.Center
            };
            var box = new TextBox
            {
                FontSize = 12, Padding = new Thickness(8, 5, 8, 5),
                Background = Brushes.Transparent, Foreground = valFg, BorderThickness = new Thickness(0),
                VerticalContentAlignment = VerticalAlignment.Center,
                ToolTip = "Where the package installs. Add a name onto the end to install into a "
                        + "subfolder of the selected folder."
            };
            var boxField = new Border
            {
                Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true, Child = box
            };
            Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0);
            Grid.SetRow(boxField, r); Grid.SetColumn(boxField, 1);
            cg.Children.Add(lbl); cg.Children.Add(boxField); r++;

            tree.SelectedItemChanged += (_, ev) =>
            {
                if (ev.NewValue is TreeViewItem sel && sel.Tag is InstallDirNode node) box.Text = node.Bracketed;
            };

            // Open on the folder the package installs to now: by path when one of them resolves to
            // the current value, otherwise by the Directory row detection picked out, which is what
            // an INSTALLDIR override or an absolute path leaves to go on.
            string want = (current ?? "").Trim();
            TreeViewItem? selected = null;
            foreach (var item in items)
                if (item.Tag is InstallDirNode node
                    && string.Equals(node.Bracketed, want, StringComparison.OrdinalIgnoreCase))
                { selected = item; break; }
            if (selected == null)
            {
                string key = "";
                try { key = DetectInstallDirectoryKey(); } catch { }
                if (key.Length > 0)
                    foreach (var item in items)
                        if (item.Tag is InstallDirNode node
                            && string.Equals(node.Key, key, StringComparison.OrdinalIgnoreCase))
                        { selected = item; break; }
            }

            foreach (var top in tree.Items.OfType<TreeViewItem>()) top.IsExpanded = true;
            if (selected != null)
            {
                for (var p = selected.Parent as TreeViewItem; p != null; p = p.Parent as TreeViewItem)
                    p.IsExpanded = true;
                selected.IsSelected = true;                       // fills the box through the handler
                var target = selected;
                win.ContentRendered += (_, _) => { try { target.BringIntoView(); target.Focus(); } catch { } };
            }
            // Selecting overwrote the box, so the value being edited goes back in: an override the
            // tree cannot represent is still what the field holds, and is still what OK would keep.
            if (want.Length > 0) box.Text = want;

            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            string? result = null;
            void Accept()
            {
                string v = box.Text.Trim();
                if (v.Length == 0) return;              // nothing to apply; leave the dialog open
                // A local path typed or pasted into the box is tokenized the way the shell picker's
                // result used to be, so C:\Program Files\MyApp still becomes [ProgramFilesFolder]MyApp.
                result = MsiTokenizePath(v);
                win.Close();
            }
            var btns = NdMakeButtons(sec,
                ("\u2714 OK",     Accept),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);

            box.KeyDown += (_, ev) => { if (ev.Key == Key.Enter) Accept(); };

            win.ShowDialog();
            return result;
        }

        // ── Install condition (the LaunchCondition table) ────────────────────────────────
        // Windows Installer stops the install when a LaunchCondition row evaluates to false and
        // shows that row's Description. InstallShield surfaces the same table as the install
        // condition on its General Information page, which is what this mirrors.

        /// <summary>
        /// Live LaunchCondition rows. Deleted rows and ones staged for deletion are left out, so
        /// the count reflects what the package would ship with rather than what it started with.
        /// </summary>
        private List<DataRow> LaunchConditionRows()
        {
            var rows = new List<DataRow>();
            var st = EnsureTableCached("LaunchCondition");
            if (st == null || !st.Data.Columns.Contains("Condition")) return rows;
            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState == DataRowState.Deleted || st.MarkedDelete.Contains(r)) continue;
                rows.Add(r);
            }
            return rows;
        }

        private void RefreshLaunchConditionField()
        {
            if (FpLaunchCond == null) return;
            int n = 0;
            try { n = LaunchConditionRows().Count; } catch { }
            FpLaunchCond.Text = n == 0 ? "None" : n == 1 ? "1 condition" : n + " conditions";
        }

        /// <summary>Stages a cell edit, leaving the row untouched when the text did not actually
        /// change so that clicking through the fields cannot invent an edit.</summary>
        private void LaunchCondSet(DataRow row, string column, string value)
        {
            if (row.RowState == DataRowState.Deleted || !row.Table.Columns.Contains(column)) return;
            if (Cv(row[column]) == (value ?? "")) return;
            row[column] = value ?? "";
            UpdateEditCount();
        }

        /// <summary>
        /// Refuses to close on a row that could not be written. Condition is the table's primary
        /// key, so it can be neither blank nor a duplicate, and finding that out at Save time
        /// would be far too late.
        /// </summary>
        private bool LaunchCondCommitOk()
        {
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (DataRow row in LaunchConditionRows())
            {
                string c = Cv(row["Condition"]).Trim();
                if (c.Length == 0)
                {
                    MstMessage("One of the conditions is blank. Fill it in, or remove that row.",
                        "Install condition", MessageBoxButton.OK, MessageBoxImage.Warning);
                    return false;
                }
                if (!seen.Add(c))
                {
                    MstMessage("Two rows carry the condition:\n\n" + c + "\n\nThe condition is the "
                             + "table's key, so it has to be unique.",
                        "Install condition", MessageBoxButton.OK, MessageBoxImage.Warning);
                    return false;
                }
            }
            return true;
        }

        // ── Condition builder ───────────────────────────────────────────────────────────
        // A launch condition is an expression over installer properties, and the property names
        // are the part nobody remembers: Privileged, VersionNT64, MsiNTProductType. An MSI editor
        // answers that with two lists next to the condition, one of properties and one of
        // operators, each with an Add that drops the token into the condition being written. That
        // is what the dialog offers, so a condition can be assembled without typing a name from
        // memory or leaving to look one up.

        /// <summary>
        /// Standard Windows Installer properties worth writing a launch condition against. The
        /// installer sets these itself, so a package that tests them does not define them and they
        /// would never appear from the Property table alone.
        /// </summary>
        private static readonly string[] MsiConditionProperties =
        {
            "AdminUser", "ALLUSERS", "ComputerName", "Installed", "Intel", "Intel64", "LogonUser",
            "MsiNTProductType", "MsiNTSuitePersonal", "MsiNetAssemblySupport",
            "MsiSystemRebootPending", "MsiWin32AssemblySupport", "OriginalDatabase",
            "PhysicalMemory", "Privileged", "REINSTALL", "REMOVE", "RemoveExistingProducts",
            "ScreenX", "ScreenY", "ServicePackLevel", "SystemLanguageID", "TARGETDIR",
            "TerminalServer", "UILevel", "UpgradingProductCode", "Version9X", "VersionMsi",
            "VersionNT", "VersionNT64", "WindowsBuild",
        };

        /// <summary>
        /// What the builder's property list offers: the standard properties above together with
        /// every property this package defines, since a condition just as often tests one the
        /// package set for itself. Sorted and de-duplicated, so a package that defines a standard
        /// name appears once.
        /// </summary>
        private List<string> ConditionProperties()
        {
            var all = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string p in MsiConditionProperties) all.Add(p);

            var st = EnsureTableCached("Property");
            if (st != null && st.Data.Columns.Contains("Property"))
                foreach (DataRow r in st.Data.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    string p = Cv(r["Property"]);
                    if (p.Length > 0) all.Add(p);
                }

            return new List<string>(all);
        }

        /// <summary>
        /// The operators a condition can use, each with what it means. Only the token before the
        /// first space is inserted, so the explanation can travel with it in the list.
        /// </summary>
        private static readonly string[] MsiConditionOperators =
        {
            "=  equal",
            "<>  not equal",
            ">  greater than",
            ">=  greater than or equal",
            "<  less than",
            "<=  less than or equal",
            "><  contains",
            "<<  starts with",
            ">>  ends with",
            "~=  equal, ignoring case",
            "AND",
            "OR",
            "NOT",
            "XOR",
            "EQV  equivalent",
            "IMP  implies",
            "(  open bracket",
            ")  close bracket",
        };

        private void BtnEditLaunchCond_Click(object sender, RoutedEventArgs e)
        {
            if (_msiPath.Length == 0) return;

            var st = EnsureTableCached("LaunchCondition");
            if (st == null || !st.Data.Columns.Contains("Condition") || !st.Data.Columns.Contains("Description"))
            {
                MstMessage("This package has no LaunchCondition table, so it has no install "
                         + "condition to edit. Conditions can be edited in packages that already "
                         + "define the table.",
                    "Install condition", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            ShowLaunchConditionDialog(st);
            RefreshLaunchConditionField();
        }

        /// <summary>
        /// The condition list. Edits go straight into the cached LaunchCondition rows, so they
        /// stage exactly like a grid edit and reach View Changes, Create MST and Save unchanged.
        /// </summary>
        private void ShowLaunchConditionDialog(TableState st)
        {
            var win = BuildNewDialog("Install condition");
            win.Width = 720; win.MaxWidth = 720;
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, "Install condition");

            int r = 0;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var intro = new TextBlock
            {
                Text = "The install stops when one of these evaluates to false, and that row's "
                     + "message is shown. An empty list lets the package install unconditionally.",
                FontSize = 11, TextWrapping = TextWrapping.Wrap, Foreground = lblFg,
                Margin = new Thickness(0, 2, 0, 8)
            };
            Grid.SetRow(intro, r); Grid.SetColumn(intro, 1); cg.Children.Add(intro);
            r++;

            // A right margin keeps the cards clear of the scrollbar gutter, so the last column
            // never ends up under it once the list grows past the visible height.
            var list = new StackPanel { Margin = new Thickness(0, 0, 4, 0) };
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var listLbl = new TextBlock
            {
                Text = "Conditions", FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, VerticalAlignment = VerticalAlignment.Top,
                Margin = new Thickness(0, 4, 8, 0)
            };
            var scroll = new ScrollViewer
            {
                Content = list, MaxHeight = 340, Margin = new Thickness(0, 0, 0, 8),
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
            };
            Grid.SetRow(listLbl, r); Grid.SetColumn(listLbl, 0);
            Grid.SetRow(scroll, r);  Grid.SetColumn(scroll, 1);
            cg.Children.Add(listLbl); cg.Children.Add(scroll);
            r++;

            // The builder writes into whichever condition is being edited, so the list has to say
            // which one that is: the card holding the caret takes the accent border, the rest stay
            // plain. Rebuilding replaces every card, so the tracking is cleared with it.
            var cards = new List<(Border border, TextBox box)>();
            TextBox? active = null;
            TextBox? lastCond = null;
            Brush accent = Application.Current.TryFindResource("DlgBtnBlueBorderBrush") as Brush
                           ?? new SolidColorBrush(Color.FromRgb(0x42, 0x9B, 0xF5));

            void HighlightActive()
            {
                foreach (var (border, tb) in cards)
                {
                    bool on = ReferenceEquals(tb, active);
                    border.BorderBrush     = on ? accent : boxBdr;
                    border.BorderThickness = new Thickness(on ? 1.6 : 1);
                }
            }

            void Rebuild()
            {
                list.Children.Clear();
                cards.Clear();
                active = null; lastCond = null;
                var rows = LaunchConditionRows();
                if (rows.Count == 0)
                {
                    list.Children.Add(new TextBlock
                    {
                        Text = "No conditions. The package installs unconditionally.",
                        FontSize = 11, Foreground = lblFg, Margin = new Thickness(0, 4, 0, 4)
                    });
                    return;
                }

                foreach (DataRow row in rows)
                {
                    DataRow captured = row;                 // one row per closure, not the loop cursor
                    var card = new Border
                    {
                        BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                        CornerRadius = new CornerRadius(6), Padding = new Thickness(8),
                        Margin = new Thickness(0, 0, 0, 6)
                    };
                    var g = new Grid();
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                    g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                    g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                    var condLbl = new TextBlock
                    {
                        Text = "Condition", FontSize = 11, FontWeight = FontWeights.SemiBold,
                        Foreground = lblFg, Margin = new Thickness(0, 9, 8, 0),
                        VerticalAlignment = VerticalAlignment.Top
                    };
                    var (condField, condBox) = MakeRoundedField(
                        Cv(captured["Condition"]), boxBg, boxBdr, valFg, true, null);
                    condBox.MinHeight = 40;
                    condBox.FontFamily = new FontFamily("Consolas");
                    condField.Margin = new Thickness(0, 4, 0, 4);
                    condBox.LostFocus += (_, _) => LaunchCondSet(captured, "Condition", condBox.Text);
                    condBox.GotFocus  += (_, _) => { active = condBox; HighlightActive(); };
                    cards.Add((card, condBox));
                    lastCond = condBox;

                    var msgLbl = new TextBlock
                    {
                        Text = "Message", FontSize = 11, FontWeight = FontWeights.SemiBold,
                        Foreground = lblFg, Margin = new Thickness(0, 9, 8, 0),
                        VerticalAlignment = VerticalAlignment.Top
                    };
                    var (msgField, msgBox) = MakeRoundedField(
                        Cv(captured["Description"]), boxBg, boxBdr, valFg, true, null);
                    msgBox.MinHeight = 40;
                    msgField.Margin = new Thickness(0, 4, 0, 4);
                    msgBox.LostFocus += (_, _) => LaunchCondSet(captured, "Description", msgBox.Text);

                    // No shared Style and no fixed size. SecondaryButtonStyle carries the padding
                    // and minimum width meant for the wide dialog buttons at the bottom, which
                    // pushed the glyph out of a 32px box and the box past the card edge. This is
                    // the borderless icon button MakeRoundedField already uses for its browse
                    // glyph, so it sizes to its own content and cannot be clipped.
                    var del = new Button
                    {
                        Content = "🗑", FontSize = 14, Cursor = Cursors.Hand,
                        Foreground = valFg, Background = Brushes.Transparent,
                        BorderThickness = new Thickness(0), MinWidth = 0,
                        Padding = new Thickness(6, 0, 6, 0),
                        Margin = new Thickness(6, 8, 0, 0),
                        VerticalAlignment = VerticalAlignment.Top,
                        ToolTip = "Remove this condition"
                    };
                    del.Click += (_, _) =>
                    {
                        // Same rule the grid uses: a row added in this session is dropped
                        // outright, an existing one becomes a staged delete.
                        if (captured.RowState == DataRowState.Added) captured.Delete();
                        else st.MarkedDelete.Add(captured);
                        UpdateEditCount();
                        Rebuild();
                    };

                    Grid.SetRow(condLbl, 0);   Grid.SetColumn(condLbl, 0);
                    Grid.SetRow(condField, 0); Grid.SetColumn(condField, 1);
                    Grid.SetRow(del, 0);       Grid.SetColumn(del, 2);
                    Grid.SetRow(msgLbl, 1);    Grid.SetColumn(msgLbl, 0);
                    Grid.SetRow(msgField, 1);  Grid.SetColumn(msgField, 1);
                    g.Children.Add(condLbl); g.Children.Add(condField); g.Children.Add(del);
                    g.Children.Add(msgLbl);  g.Children.Add(msgField);
                    card.Child = g;
                    list.Children.Add(card);
                }
                HighlightActive();
            }
            Rebuild();

            // ── Builder ─────────────────────────────────────────────────────────────────
            // Pick a property or an operator and Add drops it into the condition at the caret.
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var buildLbl = new TextBlock
            {
                Text = "Build", FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, VerticalAlignment = VerticalAlignment.Top,
                Margin = new Thickness(0, 2, 8, 0)
            };
            var builder = new Grid { Margin = new Thickness(0, 0, 4, 8) };
            builder.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            builder.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            builder.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            for (int i = 0; i < 3; i++)
                builder.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Grid.SetRow(buildLbl, r); Grid.SetColumn(buildLbl, 0);
            Grid.SetRow(builder, r);  Grid.SetColumn(builder, 1);
            cg.Children.Add(buildLbl); cg.Children.Add(builder);
            r++;

            var buildHint = new TextBlock
            {
                Text = "Add properties and operators to the condition you are editing. "
                     + "Click into a condition first; it takes a highlighted border.",
                FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 6)
            };
            Grid.SetRow(buildHint, 0); Grid.SetColumn(buildHint, 0); Grid.SetColumnSpan(buildHint, 3);
            builder.Children.Add(buildHint);

            void InsertToken(string token)
            {
                if (token.Length == 0) return;
                if (active == null)
                {
                    MstMessage("Click into the condition you want to build first, then add to it.",
                        "Install condition", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                // At the caret, not at the end: a property is as often dropped into the middle of
                // an expression as onto the end of one. Spaces are added only where the text does
                // not already have them, so tokens never run together.
                var tb = active;
                int caret = Math.Min(tb.CaretIndex, tb.Text.Length);
                string before = tb.Text.Substring(0, caret);
                string after  = tb.Text.Substring(caret);
                string lead   = before.Length > 0 && !char.IsWhiteSpace(before[before.Length - 1]) ? " " : "";
                string trail  = after.Length  > 0 && !char.IsWhiteSpace(after[0])                  ? " " : "";
                tb.Text = before + lead + token + trail + after;
                tb.CaretIndex = caret + lead.Length + token.Length;
                tb.Focus();
            }

            // firstWordOnly: the operator list carries "<>  not equal" so the meaning is readable,
            // and only the token itself belongs in the condition.
            void AddPickerRow(int row, string label, string tip, IEnumerable<string> options, bool firstWordOnly)
            {
                var pickLbl = new TextBlock
                {
                    Text = label, FontSize = 11, Foreground = lblFg,
                    VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 6)
                };
                var pick = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                    Height = 28, VerticalContentAlignment = VerticalAlignment.Center,
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr,
                    ToolTip = tip, Margin = new Thickness(0, 0, 0, 6)
                };
                foreach (string o in options) pick.Items.Add(o);
                if (pick.Items.Count > 0) pick.SelectedIndex = 0;

                var addBtn = new Button
                {
                    Content = "\u2795 Add", Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Height = 28, Padding = new Thickness(10, 0, 10, 0),
                    Margin = new Thickness(8, 0, 0, 6), Cursor = Cursors.Hand,
                    ToolTip = "Insert this into the condition being edited"
                };
                addBtn.Click += (_, _) =>
                {
                    string text = (pick.Text ?? "").Trim();
                    if (firstWordOnly)
                    {
                        int sp = text.IndexOf(' ');
                        if (sp > 0) text = text.Substring(0, sp);
                    }
                    InsertToken(text);
                };

                Grid.SetRow(pickLbl, row); Grid.SetColumn(pickLbl, 0);
                Grid.SetRow(pick, row);    Grid.SetColumn(pick, 1);
                Grid.SetRow(addBtn, row);  Grid.SetColumn(addBtn, 2);
                builder.Children.Add(pickLbl); builder.Children.Add(pick); builder.Children.Add(addBtn);
            }

            AddPickerRow(1, "Properties", "Properties this package defines, plus the standard ones "
                       + "Windows Installer sets itself. A name can also be typed in.",
                       ConditionProperties(), false);
            AddPickerRow(2, "Operators", "Comparison and logical operators a condition can use.",
                       MsiConditionOperators, true);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var rowIcon = NdDecisionIcon();
            Grid.SetRow(rowIcon, r); Grid.SetColumn(rowIcon, 0); cg.Children.Add(rowIcon);

            var btnGrid = NdMakeButtons(sec,
                ("➕ Add condition", () =>
                {
                    var nr = st.Data.NewRow();
                    nr["Condition"]   = "";
                    nr["Description"] = "";
                    st.Data.Rows.Add(nr);
                    UpdateEditCount();
                    Rebuild();

                    // The card that just appeared is the one to build in, so it takes the caret
                    // once it has been laid out, which also scrolls the list down to it.
                    var target = lastCond;
                    if (target != null)
                        win.Dispatcher.BeginInvoke(new Action(() =>
                        {
                            try { scroll.ScrollToEnd(); target.Focus(); } catch { }
                        }), System.Windows.Threading.DispatcherPriority.Loaded);
                }),
                ("✔ Done", () => { if (LaunchCondCommitOk()) win.Close(); }));
            Grid.SetRow(btnGrid, r); Grid.SetColumn(btnGrid, 1); cg.Children.Add(btnGrid);

            win.ShowDialog();
        }

        /// <summary>
        /// Builds one condition expression and returns it, or null when cancelled. The same two
        /// lists the launch-condition editor offers, over a single condition instead of a table of
        /// them, so a sequence entry's condition can be assembled without typing a property name
        /// from memory.
        ///
        /// The box stays editable throughout: Add is a way to get a name in without misspelling it,
        /// not the only way in. A misspelt property is not an error Windows Installer reports - the
        /// condition just evaluates false forever and the action silently never runs.
        /// </summary>
        private string? PromptCondition(string title, string current)
        {
            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            win.Width = 560; win.MaxWidth = 560;

            int r = 0;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var capt = new TextBlock
            {
                Text = "Condition", FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, Margin = new Thickness(0, 2, 0, 4)
            };
            Grid.SetRow(capt, r); Grid.SetColumn(capt, 0); Grid.SetColumnSpan(capt, 2);
            cg.Children.Add(capt); r++;

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            // Wraps but does not accept Return: the Condition column holds one expression, and a
            // newline in it is not something Windows Installer will parse.
            var condBox = new TextBox
            {
                Text = current ?? "", FontSize = 12, FontFamily = new FontFamily("Consolas"),
                Height = 96, TextWrapping = TextWrapping.Wrap, AcceptsReturn = false,
                VerticalContentAlignment = VerticalAlignment.Top,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                Padding = new Thickness(8, 6, 8, 6), Foreground = valFg,
                Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                CaretBrush = valFg,
                SelectionBrush = new SolidColorBrush(Color.FromArgb(0x66, 0x6C, 0x63, 0xFF))
            };
            var condHost = new Border
            {
                Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true, Child = condBox
            };
            Grid.SetRow(condHost, r); Grid.SetColumn(condHost, 0); Grid.SetColumnSpan(condHost, 2);
            cg.Children.Add(condHost); r++;

            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var hint = new TextBlock
            {
                Text = "Add properties and operators to the condition. Each one goes in at the "
                     + "caret, so it can be dropped into the middle of an expression as easily as "
                     + "onto the end. Leave the box empty to run unconditionally.",
                FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 8)
            };
            Grid.SetRow(hint, r); Grid.SetColumn(hint, 0); Grid.SetColumnSpan(hint, 2);
            cg.Children.Add(hint); r++;

            void InsertToken(string token)
            {
                if (token.Length == 0) return;
                int caret = Math.Min(condBox.CaretIndex, condBox.Text.Length);
                string before = condBox.Text.Substring(0, caret);
                string after  = condBox.Text.Substring(caret);
                string lead   = before.Length > 0 && !char.IsWhiteSpace(before[before.Length - 1]) ? " " : "";
                string trail  = after.Length  > 0 && !char.IsWhiteSpace(after[0])                  ? " " : "";
                condBox.Text = before + lead + token + trail + after;
                condBox.CaretIndex = caret + lead.Length + token.Length;
                condBox.Focus();
            }

            // firstWordOnly: the operator list carries "<>  not equal" so the meaning is readable,
            // and only the token itself belongs in the condition.
            void AddPickerRow(string label, string tip,
                System.Collections.Generic.IEnumerable<string> options, bool firstWordOnly)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var pickLbl = new TextBlock
                {
                    Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg,
                    VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 6)
                };
                var pick = new ComboBox
                {
                    FontSize = 12, Padding = new Thickness(8, 4, 8, 4), IsEditable = true,
                    Height = 28, VerticalContentAlignment = VerticalAlignment.Center,
                    Background = boxBg, Foreground = valFg, BorderBrush = boxBdr,
                    ToolTip = tip, Margin = new Thickness(0, 0, 0, 6)
                };
                foreach (string o in options) pick.Items.Add(o);
                if (pick.Items.Count > 0) pick.SelectedIndex = 0;

                var addBtn = new Button
                {
                    Content = "\u2795 Add", Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Height = 28, Padding = new Thickness(10, 0, 10, 0),
                    Margin = new Thickness(8, 0, 0, 6), Cursor = Cursors.Hand,
                    ToolTip = "Insert this into the condition"
                };
                addBtn.Click += (_, _) =>
                {
                    string text = (pick.Text ?? "").Trim();
                    if (firstWordOnly)
                    {
                        int sp = text.IndexOf(' ');
                        if (sp > 0) text = text.Substring(0, sp);
                    }
                    InsertToken(text);
                };

                var row = new Grid();
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                Grid.SetColumn(pick, 0); Grid.SetColumn(addBtn, 1);
                row.Children.Add(pick); row.Children.Add(addBtn);

                Grid.SetRow(pickLbl, r); Grid.SetColumn(pickLbl, 0);
                Grid.SetRow(row, r);     Grid.SetColumn(row, 1);
                cg.Children.Add(pickLbl); cg.Children.Add(row); r++;
            }

            AddPickerRow("Properties", "Properties this package defines, plus the standard ones "
                       + "Windows Installer sets itself. A name can also be typed in.",
                       ConditionProperties(), false);
            AddPickerRow("Operators", "Comparison and logical operators a condition can use.",
                       MsiConditionOperators, true);

            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            string? result = null;
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () => { result = condBox.Text.Trim(); win.Close(); }),
                ("\u2715 Cancel", () => { result = null; win.Close(); }));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);

            win.ContentRendered += (_, _) => { try { condBox.Focus(); condBox.CaretIndex = condBox.Text.Length; } catch { } };
            win.ShowDialog();
            return result;
        }

        private void PopulateProductInfo()
        {
            if (FpProductName == null) return;   // form not built yet
            _loadingForm = true;
            try
            {
                bool open = _msiPath.Length > 0 && EnsureTableCached("Property") != null;

                FpProductName.Text    = GetProperty("ProductName");
                FpProductVersion.Text = GetProperty("ProductVersion");
                FpManufacturer.Text   = GetProperty("Manufacturer");
                FpProductCode.Text    = GetProperty("ProductCode");
                FpUpgradeCode.Text    = GetProperty("UpgradeCode");

                FaProductIcon.Text = GetProperty("ARPPRODUCTICON");
                FaContact.Text    = GetProperty("ARPCONTACT");
                FaPhone.Text      = GetProperty("ARPTELEPHONE");
                FaSupportUrl.Text = GetProperty("ARPURLINFOABOUT");
                FaUpdateUrl.Text  = GetProperty("ARPURLUPDATEINFO");
                FaHelpLink.Text   = GetProperty("ARPHELPLINK");

                ChkHideModify.IsChecked      = GetProperty("ARPNOMODIFY") == "1";
                ChkHideRepair.IsChecked      = GetProperty("ARPNOREPAIR") == "1";
                ChkHideRemove.IsChecked      = GetProperty("ARPNOREMOVE") == "1";
                ChkSystemComponent.IsChecked = GetProperty("ARPSYSTEMCOMPONENT") == "1";

                // Install location: the property override when the package sets one, otherwise
                // the folder its Directory table resolves to.
                RefreshInstallDirField();
                FpInstallDir.IsEnabled      = open;
                BtnBrowseInstallDir.IsEnabled = open;

                // Install condition: a summary of the LaunchCondition table, edited in its own
                // dialog because a condition is an expression plus a message.
                RefreshLaunchConditionField();
                if (FpLaunchCond != null)      FpLaunchCond.IsEnabled      = open;
                if (BtnEditLaunchCond != null) BtnEditLaunchCond.IsEnabled = open;

                // Summary Information (read from the stream; edits apply on Save).
                PopulateSummaryInfo(open);

                // Enable/disable the editable fields as a group.
                foreach (var tb in new[] { FpProductName, FpProductVersion, FpManufacturer,
                                           FpProductCode, FpUpgradeCode, FaProductIcon, FaContact,
                                           FaPhone, FaSupportUrl, FaUpdateUrl, FaHelpLink })
                    tb.IsEnabled = open;
                BtnRegenProduct.IsEnabled = open;
                BtnRegenUpgrade.IsEnabled = open;
                if (BtnBrowseArpIcon != null) BtnBrowseArpIcon.IsEnabled = open;
                foreach (var cb in new[] { ChkHideModify, ChkHideRepair, ChkHideRemove, ChkSystemComponent })
                    cb.IsEnabled = open;
            }
            finally { _loadingForm = false; }
        }

        private void FormField_Commit(object sender, RoutedEventArgs e)
        {
            if (_loadingForm) return;
            if (sender is not TextBox tb || tb.Tag is not string map) return;
            string val = tb.Text ?? "";
            if (ReferenceEquals(tb, FpInstallDir))
            {
                // Not a plain property: a bracketed path belongs in the Directory table, since
                // the installer would take it literally out of the Property table.
                ApplyInstallDirPath(val);
                RefreshInstallDirField();
                return;
            }
            if (ReferenceEquals(tb, FsLanguage))
            {
                // Not a property of its own: the language sits in the second half of Template.
                SetSummary(MsiApi.PID_TEMPLATE, TemplateWithLanguage(val));
                return;
            }
            if (ReferenceEquals(tb, FsPackageCode))
            {
                // A package code that is not a GUID is not a package code. Windows Installer would
                // store the text without complaint and then fail to match the package against
                // itself later, so it is checked here where the mistake is still visible.
                string t = val.Trim();
                if (t.Length > 0)
                {
                    if (!Guid.TryParse(t, out var pg))
                    {
                        MstMessage("The package code has to be a GUID, written as "
                                 + "{XXXXXXXX-XXXX-XXXX-XXXX-XXXXXXXXXXXX}.",
                            "Package code", MessageBoxButton.OK, MessageBoxImage.Warning);
                        if (!_summaryEdits.TryGetValue(MsiApi.PID_REVNUMBER, out var back))
                            _summaryOriginal.TryGetValue(MsiApi.PID_REVNUMBER, out back);
                        tb.Text = back ?? "";
                        return;
                    }
                    // Normalised to the braced upper-case form the rest of the platform writes.
                    t = "{" + pg.ToString().ToUpperInvariant() + "}";
                }
                tb.Text = t;
                SetSummary(MsiApi.PID_REVNUMBER, t);
                return;
            }
            if (map.StartsWith("prop:")) SetProperty(map.Substring(5), val);
            else if (map.StartsWith("sum:")) SetSummary(uint.Parse(map.Substring(4)), val);
        }

        private void FormField_KeyDown(object sender, System.Windows.Input.KeyEventArgs e)
        {
            if (e.Key == System.Windows.Input.Key.Enter || e.Key == System.Windows.Input.Key.Return)
            {
                FormField_Commit(sender, e);
                e.Handled = true;
            }
        }

        private void ChkArp_Click(object sender, RoutedEventArgs e)
        {
            if (_loadingForm) return;
            if (sender is not System.Windows.Controls.CheckBox cb || cb.Tag is not string map) return;
            bool isChecked = cb.IsChecked == true;
            if (map.StartsWith("noflag:"))           // checked = allow = "0", unchecked = hide = "1"
                SetProperty(map.Substring(7), isChecked ? "0" : "1");
            else if (map.StartsWith("flag:"))        // checked = "1", unchecked = "0"
                SetProperty(map.Substring(5), isChecked ? "1" : "0");
        }

        /// <summary>
        /// Picks the icon Add / remove programs shows against this product. ARPPRODUCTICON holds an
        /// Icon-table key rather than a path, which is why this goes through the package's icon
        /// picker instead of a file dialog; the picker's own Browse is what brings a file in from
        /// this machine and gives it a key first.
        /// </summary>
        private void BtnBrowseArpIcon_Click(object sender, RoutedEventArgs e)
        {
