            string? picked = PickFromPackage("Select an icon", PackageIcons(), AddIconFromDisk, IconPreview,
                                             FaProductIcon.Text ?? "");
            if (picked == null) return;
            FaProductIcon.Text = picked;
            SetProperty("ARPPRODUCTICON", picked);
        }

