        /// <summary>
        /// Multi-select language picker for the Template property. Check boxes rather than a
        /// single-choice list because Template genuinely holds a comma-separated set - a
        /// multi-language package names every language it carries.
        /// </summary>
        private void BtnPickLanguage_Click(object sender, RoutedEventArgs e)
        {
            if (_msiPath.Length == 0 || FsLanguage == null) return;

            // What the field holds now, kept in hand so unlisted codes survive the round trip: a
            // package naming 1063 keeps 1063 checked and returned even though nothing here
            // documents it.
            var current = new HashSet<int>();
            foreach (string part in (FsLanguage.Text ?? "").Split(new[] { ',', ';', ' ' },
                         StringSplitOptions.RemoveEmptyEntries))
                if (int.TryParse(part.Trim(), out int c)) current.Add(c);

            var win = BuildNewDialog("Languages");
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, "Languages");
            win.Width = 470; win.MaxWidth = 470;

            int r = 0;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var hint = new TextBlock
            {
                Text = "Languages this package declares in its Template summary property. More "
                     + "than one may be checked for a multi-language package.",
                FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 2, 0, 8)
            };
            Grid.SetRow(hint, r); Grid.SetColumn(hint, 0); Grid.SetColumnSpan(hint, 2);
            cg.Children.Add(hint); r++;

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var listPanel = new StackPanel();
            var checks = new List<(int code, CheckBox box)>();
            void AddEntry(int code, string name)
            {
                var cb = new CheckBox
                {
                    Content = code + " - " + name, FontSize = 12, Foreground = valFg,
                    Margin = new Thickness(2, 3, 2, 3), IsChecked = current.Contains(code)
                };
                checks.Add((code, cb));
                listPanel.Children.Add(cb);
            }
            // Codes in the field but not in the list go first, named for what they are, so what
            // was typed is never silently dropped by opening the picker and pressing OK.
            foreach (int c in current)
                if (!SummaryLanguages.Any(l => l.code == c)) AddEntry(c, "language ID not in this list");
            foreach (var (code, name) in SummaryLanguages) AddEntry(code, name);

            var scroll = new ScrollViewer
            {
                Content = listPanel, Height = 340,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto
            };
            var listHost = new Border
            {
                Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6), SnapsToDevicePixels = true,
                Padding = new Thickness(8, 6, 8, 6), Child = scroll
            };
            Grid.SetRow(listHost, r); Grid.SetColumn(listHost, 0); Grid.SetColumnSpan(listHost, 2);
            cg.Children.Add(listHost); r++;

            NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var dIcon = NdDecisionIcon(); Grid.SetRow(dIcon, r); Grid.SetColumn(dIcon, 0); cg.Children.Add(dIcon);
            var btns = NdMakeButtons(sec,
                ("\u2714 OK", () =>
                {
                    var picked = checks.Where(c => c.box.IsChecked == true)
                                       .Select(c => c.code).ToList();
                    // Nothing checked means language neutral, and neutral is spelt 0 rather than
                    // an empty Template half.
                    string text = picked.Count == 0 ? "0" : string.Join(",", picked);
                    FsLanguage.Text = text;
                    SetSummary(MsiApi.PID_TEMPLATE, TemplateWithLanguage(text));
                    win.Close();
                }),
                ("\u2715 Cancel", () => win.Close()));
            Grid.SetRow(btns, r); Grid.SetColumn(btns, 1); cg.Children.Add(btns);

            win.ShowDialog();
        }

        /// <summary>
        /// Stamps a fresh package code. Windows Installer treats two packages sharing one package
        /// code as the same package, so a rebuilt or repackaged MSI needs a new one or the cached
        /// original will be used in its place.
        /// </summary>
        private void BtnRegenPackageCode_Click(object sender, RoutedEventArgs e)
        {
