        // ── Summary Information (the package summary stream) ─────────────────
        // Read straight from the stream; edits are staged separately from the
        // table edits and applied when saving a new MSI (transforms do not carry
        // the package summary stream, so these are intentionally Save-only).
        private readonly Dictionary<uint, string> _summaryEdits    = new();
        private readonly Dictionary<uint, string> _summaryOriginal = new();

        private void PopulateSummaryInfo(bool open)
        {
            if (FsTitle == null) return;
            _summaryEdits.Clear();
            _summaryOriginal.Clear();
            var vals = open ? ReadSummary(_msiPath) : new Dictionary<uint, string>();
            foreach (uint pid in SummaryPids)
            {
                vals.TryGetValue(pid, out var v);
                _summaryOriginal[pid] = v ?? "";
            }
            FsTitle.Text    = _summaryOriginal[MsiApi.PID_TITLE];
            FsSubject.Text  = _summaryOriginal[MsiApi.PID_SUBJECT];
            FsAuthor.Text   = _summaryOriginal[MsiApi.PID_AUTHOR];
            FsKeywords.Text = _summaryOriginal[MsiApi.PID_KEYWORDS];
            FsComments.Text = _summaryOriginal[MsiApi.PID_COMMENTS];
            FsSchema.Text   = _summaryOriginal[MsiApi.PID_PAGECOUNT];

            // Package code is a property of its own. Language is not: it is the second half of
            // Template, whose first half is the platform, so it is split out for display and put
            // back together on commit.
            if (FsPackageCode != null) FsPackageCode.Text = _summaryOriginal[MsiApi.PID_REVNUMBER];
            if (FsLanguage != null)    FsLanguage.Text    = SummaryLanguage(_summaryOriginal[MsiApi.PID_TEMPLATE]);

            // Filling a dropdown moves its selection, and a moved selection is indistinguishable
            // from the user choosing something. Saved and restored rather than simply set, because
            // the usual caller has already set it and would not expect it cleared underneath.
            bool wasLoading = _loadingForm;
            _loadingForm = true;
            try
            {
                // The code pages a summary stream is realistically written in, by number and name
                // because the number alone tells you nothing. Not the full Windows list: the point
                // is to stop an invalid one being typed, which a hundred unused entries would not
                // help with.
                if (FsCodePage != null)
                {
                    FsCodePage.Items.Clear();
                    foreach (var (code, name) in SummaryCodePages)
                        FsCodePage.Items.Add(code + " - " + name);

                    int sel = -1;
                    if (int.TryParse(_summaryOriginal[MsiApi.PID_CODEPAGE], out int cp))
                    {
                        for (int i = 0; i < SummaryCodePages.Length; i++)
                            if (SummaryCodePages[i].code == cp) { sel = i; break; }
                        // A package may carry one this list does not name. Shown as its own number
                        // rather than left blank, so the package does not appear to have none.
                        if (sel < 0) { FsCodePage.Items.Insert(0, cp + " - not a listed code page"); sel = 0; }
                    }
                    FsCodePage.SelectedIndex = sel;
                }

                // Platform is the other half of Template. Selection maps to _platformValues by
                // index, which is filled here in step with the items.
                if (FsPlatform != null)
                {
                    FsPlatform.Items.Clear();
                    _platformValues.Clear();
                    foreach (var (value, label) in SummaryPlatforms)
                    { FsPlatform.Items.Add(label); _platformValues.Add(value); }

                    string plat = SummaryPlatform(_summaryOriginal[MsiApi.PID_TEMPLATE]);
                    int pi = -1;
                    for (int i = 0; i < _platformValues.Count; i++)
                        if (string.Equals(_platformValues[i], plat, StringComparison.OrdinalIgnoreCase))
                        { pi = i; break; }
                    // A package may name a platform this list does not, and rewriting it to the
                    // nearest match would be a change nobody asked for.
                    if (pi < 0)
                    {
                        FsPlatform.Items.Insert(0, plat + " - not a listed platform");
                        _platformValues.Insert(0, plat);
                        pi = 0;
                    }
                    FsPlatform.SelectedIndex = pi;
                }

                // UAC is one bit of Word Count, not a property of its own. Nothing is selected when
                // the package has no Word Count at all, rather than implying an answer it never gave.
                if (FsUac != null)
                    FsUac.SelectedIndex =
                        int.TryParse(_summaryOriginal[MsiApi.PID_WORDCOUNT], out int wc)
                            ? ((wc & MsiApi.SUMINFO_NO_ELEVATE) != 0 ? 1 : 0)
                            : -1;
            }
            finally { _loadingForm = wasLoading; }

            foreach (var tb in new[] { FsTitle, FsSubject, FsAuthor, FsKeywords,
                                       FsComments, FsSchema, FsPackageCode, FsLanguage })
                if (tb != null) tb.IsEnabled = open;
            if (FsCodePage != null) FsCodePage.IsEnabled = open;
            if (FsPlatform != null) FsPlatform.IsEnabled = open;
            if (FsUac != null) FsUac.IsEnabled = open;
            if (BtnRegenPackageCode != null) BtnRegenPackageCode.IsEnabled = open;
            if (BtnPickLanguage != null) BtnPickLanguage.IsEnabled = open;
        }

        /// <summary>Code pages offered for the summary stream, in numeric order.</summary>
        private static readonly (int code, string name)[] SummaryCodePages =
        {
            (0,     "Neutral, ASCII only"),
            (437,   "OEM United States"),
            (850,   "OEM Multilingual Latin 1"),
            (874,   "ANSI/OEM Thai"),
            (932,   "ANSI/OEM Japanese, Shift-JIS"),
            (936,   "ANSI/OEM Simplified Chinese, GBK"),
            (949,   "ANSI/OEM Korean"),
            (950,   "ANSI/OEM Traditional Chinese, Big5"),
            (1250,  "ANSI Central European"),
            (1251,  "ANSI Cyrillic"),
            (1252,  "ANSI Latin 1, Western European"),
            (1253,  "ANSI Greek"),
            (1254,  "ANSI Turkish"),
            (1255,  "ANSI Hebrew"),
            (1256,  "ANSI Arabic"),
            (1257,  "ANSI Baltic"),
            (1258,  "ANSI/OEM Vietnamese"),
            (65001, "UTF-8"),
        };

        /// <summary>
        /// Stages the code page off the chosen entry, which reads "1252 - ANSI Latin 1, Western
        /// European". Only the number in front of the dash goes into the stream.
        /// </summary>
        private void FsCodePage_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (_loadingForm || FsCodePage == null) return;
            if (FsCodePage.SelectedItem is not string s) return;
            int sp = s.IndexOf(' ');
            if (int.TryParse(sp > 0 ? s.Substring(0, sp) : s, out int cp))
                SetSummary(MsiApi.PID_CODEPAGE, cp.ToString());
        }

        /// <summary>
        /// The language half of the Template summary property. Template is "platform;langid", with
        /// more than one language allowed after the semicolon in a multi-language package.
        /// </summary>
        private static string SummaryLanguage(string template)
        {
            int semi = (template ?? "").IndexOf(';');
            return semi >= 0 ? template.Substring(semi + 1) : "";
        }

        /// <summary>The platform half. No semicolon at all means the whole string is the platform.</summary>
        private static string SummaryPlatform(string template)
        {
            int semi = (template ?? "").IndexOf(';');
            return semi >= 0 ? template.Substring(0, semi) : (template ?? "");
        }

        /// <summary>
        /// Template as it stands, staged edit first. Both halves are edited by their own control,
        /// so each has to start from what the other one last wrote rather than from the file.
        /// </summary>
        private string CurrentTemplate()
        {
            _summaryOriginal.TryGetValue(MsiApi.PID_TEMPLATE, out var tmpl);
            if (_summaryEdits.TryGetValue(MsiApi.PID_TEMPLATE, out var staged)) tmpl = staged;
            return tmpl ?? "";
        }

        /// <summary>
        /// Template rebuilt around a new language, keeping the platform. Writing one half on its
        /// own would drop the other, and "x64;1033" becoming ";1033" silently retargets a 64-bit
        /// package at 32-bit.
        /// </summary>
        private string TemplateWithLanguage(string language)
            => SummaryPlatform(CurrentTemplate()) + ";" + (language ?? "").Trim();

        /// <summary>Template rebuilt around a new platform, keeping the language, for the same reason.</summary>
        private string TemplateWithPlatform(string platform)
            => (platform ?? "").Trim() + ";" + SummaryLanguage(CurrentTemplate());

        /// <summary>
        /// The platforms Template accepts, with the value written to the stream beside the label.
        /// An empty platform is legal and means the same as Intel, so both are offered rather than
        /// one being silently rewritten as the other.
        /// </summary>
        private static readonly (string value, string label)[] SummaryPlatforms =
        {
            ("Intel",   "Intel - 32-bit (x86)"),
            ("x64",     "x64 - 64-bit"),
            ("Arm64",   "Arm64 - 64-bit ARM"),
            ("Arm",     "Arm - 32-bit ARM"),
            ("Intel64", "Intel64 - Itanium"),
            ("",        "(unspecified) - runs as 32-bit"),
        };

        // The value behind each entry of the platform dropdown, in the order the entries were
        // added. An index rather than the item's text, because one of the values is the empty
        // string and there is no text to parse it back out of.
        private readonly System.Collections.Generic.List<string> _platformValues = new();

        private void FsPlatform_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (_loadingForm || FsPlatform == null) return;
            int i = FsPlatform.SelectedIndex;
            if (i < 0 || i >= _platformValues.Count) return;

            string platform = _platformValues[i];
            SetSummary(MsiApi.PID_TEMPLATE, TemplateWithPlatform(platform));

            // Said out loud because the field looks like it decides the bit-ness and does not. It
            // is the gate Windows Installer checks before running the package at all; what the
            // package then installs where is decided by the components' 64-bit attribute and the
            // folders they point at.
            bool wide = platform.Equals("x64", StringComparison.OrdinalIgnoreCase)
                     || platform.Equals("Arm64", StringComparison.OrdinalIgnoreCase)
                     || platform.Equals("Intel64", StringComparison.OrdinalIgnoreCase);
            if (TxtStatus != null)
                TxtStatus.Text = wide
                    ? "Platform set to " + platform + ". This lets the package run on that "
                    + "processor; it does not by itself make its components 64-bit."
                    : "Platform set to " + (platform.Length == 0 ? "unspecified" : platform) + ".";
        }

        /// <summary>Summary stream properties this page reads and can stage.</summary>
        private static readonly uint[] SummaryPids =
        {
            MsiApi.PID_CODEPAGE, MsiApi.PID_TITLE, MsiApi.PID_SUBJECT, MsiApi.PID_AUTHOR,
            MsiApi.PID_KEYWORDS, MsiApi.PID_COMMENTS, MsiApi.PID_TEMPLATE, MsiApi.PID_REVNUMBER,
            MsiApi.PID_PAGECOUNT, MsiApi.PID_WORDCOUNT,
        };

        /// <summary>
        /// Flips bit 3 of Word Count. The other bits describe the source image (short names,
        /// compression, admin image) and have nothing to do with elevation, so they are carried
        /// through untouched rather than rewritten from scratch.
        /// </summary>
        private void FsUac_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (_loadingForm || FsUac == null || FsUac.SelectedIndex < 0) return;
            _summaryOriginal.TryGetValue(MsiApi.PID_WORDCOUNT, out var orig);
            if (!int.TryParse(orig, out int wc)) wc = 0;
            int updated = FsUac.SelectedIndex == 1
                ? wc | MsiApi.SUMINFO_NO_ELEVATE       // installs without elevation
                : wc & ~MsiApi.SUMINFO_NO_ELEVATE;     // elevation required
            SetSummary(MsiApi.PID_WORDCOUNT, updated.ToString());
        }

        private static Dictionary<uint, string> ReadSummary(string path)
        {
            var result = new Dictionary<uint, string>();
            uint h = 0;
            try
            {
                if (MsiApi.MsiGetSummaryInformationW(0, path, 0, out h) != MsiApi.ERROR_SUCCESS || h == 0)
                    return result;
                foreach (uint pid in SummaryPids)
                {
                    uint dt; int iv; long ft = 0; uint cch = 0;
                    uint rc = MsiApi.MsiSummaryInfoGetPropertyW(h, pid, out dt, out iv, ref ft, null, ref cch);
                    if (dt == MsiApi.VT_I2 || dt == MsiApi.VT_I4)
                    {
                        result[pid] = iv.ToString();
                    }
                    else if (dt == MsiApi.VT_LPSTR && (rc == MsiApi.ERROR_MORE_DATA || rc == MsiApi.ERROR_SUCCESS))
                    {
                        cch++;   // room for the terminating null
                        var sb = new System.Text.StringBuilder((int)cch);
                        if (MsiApi.MsiSummaryInfoGetPropertyW(h, pid, out dt, out iv, ref ft, sb, ref cch) == MsiApi.ERROR_SUCCESS)
                            result[pid] = sb.ToString();
                    }
                }
            }
            catch { }
            finally { if (h != 0) MsiApi.MsiCloseHandle(h); }
            return result;
        }

        // Stages a summary edit (or clears it when reverted to the original value).
        private void SetSummary(uint pid, string val)
        {
            val ??= "";
            _summaryOriginal.TryGetValue(pid, out var orig);
            if ((orig ?? "") == val) _summaryEdits.Remove(pid);
            else _summaryEdits[pid] = val;
            if (_summaryEdits.Count > 0)
                TxtStatus.Text = $"{_summaryEdits.Count} summary information edit(s) pending - applied when saving a new MSI.";
        }

        // Writes staged summary edits to a finished .msi file (called after the COM
        // database has been committed and released, so the file is unlocked).
        private void WriteSummaryToFile(string path)
        {
            if (_summaryEdits.Count == 0) return;
            uint h = 0;
            try
            {
                if (MsiApi.MsiGetSummaryInformationW(0, path, (uint)_summaryEdits.Count, out h) != MsiApi.ERROR_SUCCESS || h == 0)
                    return;
                long ft = 0;
                foreach (var kv in _summaryEdits)
                {
                    // Code page, Schema and Word Count are integer properties. Writing them as
                    // text would either fail or land a string where a number is expected.
                    if (kv.Key == MsiApi.PID_CODEPAGE || kv.Key == MsiApi.PID_PAGECOUNT
                        || kv.Key == MsiApi.PID_WORDCOUNT)
                    {
                        if (int.TryParse(kv.Value, out int n))
                            MsiApi.MsiSummaryInfoSetPropertyW(h, kv.Key, MsiApi.VT_I4, n, ref ft, null);
                    }
                    else
                    {
                        MsiApi.MsiSummaryInfoSetPropertyW(h, kv.Key, MsiApi.VT_LPSTR, 0, ref ft, kv.Value);
                    }
                }
                MsiApi.MsiSummaryInfoPersist(h);
            }
            catch { }
            finally { if (h != 0) MsiApi.MsiCloseHandle(h); }
        }

        // ── Phase 2: view an MSI with an MST applied (read-only preview) ─
        private bool _viewingTransform = false;
        private string _transformOriginalMsi = "";   // real MSI behind a transform view
        private string _appliedMstPath = "";          // the .mst currently applied

        // Per-table set of primary-key signatures whose rows differ from the
        // original MSI (added or modified). Used to paint changed rows yellow in
        // transformed view. Cleared when editing a plain MSI.
        private Dictionary<string, HashSet<string>> _diffKeys =
            new(StringComparer.OrdinalIgnoreCase);

        // Tables whose transform diff has already been computed (cached), so each
        // table is compared against the original MSI at most once.
        private HashSet<string> _diffComputed = new(StringComparer.OrdinalIgnoreCase);

        /// <summary>Snapshots one table using an already-open database handle.</summary>
        private static Dictionary<string, string>? SnapshotTableFrom(dynamic db, string table)
        {
            dynamic? view = null;
            try
            {
                view = db.OpenView($"SELECT * FROM `{table}`");
                view.Execute();

                dynamic namesRec = view.ColumnInfo[0];
                dynamic typesRec = view.ColumnInfo[1];
                int cols = (int)namesRec.FieldCount;
                var colNames = new string[cols + 1];
                var isBinary = new bool[cols + 1];
                for (int i = 1; i <= cols; i++)
                {
                    colNames[i] = (string)namesRec.StringData(i);
                    string ctype = (string)typesRec.StringData(i);
                    char k = char.ToLowerInvariant(ctype.Length > 0 ? ctype[0] : 's');
                    isBinary[i] = (k == 'v' || k == 'o');
                }
                Release(namesRec); Release(typesRec);

                // Primary key columns
                var keyIdx = new List<int>();
                try
                {
                    dynamic keys = db.PrimaryKeys[table];
                    int kc = (int)keys.FieldCount;
                    var keyNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    for (int i = 1; i <= kc; i++) keyNames.Add((string)keys.StringData(i));
                    Release(keys);
                    for (int i = 1; i <= cols; i++) if (keyNames.Contains(colNames[i])) keyIdx.Add(i);
                }
                catch { }
                if (keyIdx.Count == 0 && cols >= 1) keyIdx.Add(1);

                var map = new Dictionary<string, string>(StringComparer.Ordinal);
                while (true)
                {
                    dynamic? rec = view.Fetch();
                    if (rec == null) break;
                    var keyParts = new List<string>();
                    var rowParts = new List<string>();
                    for (int i = 1; i <= cols; i++)
                    {
                        string cell = isBinary[i] ? "(binary)" : (string)rec.StringData(i);
                        rowParts.Add(cell);
                        if (keyIdx.Contains(i)) keyParts.Add(cell);
                    }
                    map[string.Join("\u001F", keyParts)] = string.Join("\u001F", rowParts);
                    Release(rec);
                }
                return map;
            }
            catch { return null; }
            finally
            {
                try { view?.Close(); } catch { }
                Release(view);
            }
        }

        /// <summary>Builds the primary-key signature for a grid row in the current table.</summary>
        private string RowKeySignature(TableState st, DataRow r)
        {
            var keys = st.KeyCols.Count > 0
                ? st.KeyCols
                : (st.Data.Columns.Count > 0 ? new List<string> { st.Data.Columns[0].ColumnName } : new List<string>());
            var parts = keys.Where(k => st.Data.Columns.Contains(k))
                            .Select(k => (r[k] ?? "").ToString());
            return string.Join("\u001F", parts);
        }

        private void BtnViewMst_Click(object sender, RoutedEventArgs e)
        {
            if (string.IsNullOrWhiteSpace(_msiPath)) return;

            // Applying a transform rebuilds the view from a fresh temp copy, which drops every
            // staged row, so the same question has to be asked here.
            if (!ConfirmSaveBeforeLeaving("applying a transform")) return;

            // Block incomplete manually-added rows before applying a transform.
            if (!CommitGridAndValidate()) return;

            var dlg = new OpenFileDialog
            { Title = "Select transform to view", Filter = "Transform (*.mst)|*.mst" };
            if (dlg.ShowDialog() != true) return;

            string original = _viewingTransform ? TxtMsiPath.Tag as string ?? _msiPath : _msiPath;
            EnterTransformView(original, dlg.FileName);
        }

        /// <summary>
        /// Applies <paramref name="mstPath"/> onto a temp copy of
        /// <paramref name="originalMsi"/>, switches the page into read-only
        /// transformed view, and highlights rows that differ from the original
        /// MSI in yellow.
        /// </summary>
        private void EnterTransformView(string originalMsi, string mstPath)
        {
            string temp = Path.Combine(Path.GetTempPath(),
                "SwiftPackMstView_" + Guid.NewGuid().ToString("N") + ".msi");

            // Show progress and disable input while the COM work runs.
            SetTransformBusy(true);
            TxtStatus.Text = "Applying transform…";

            System.Threading.Tasks.Task.Run(() =>
            {
                Exception? error = null;
                List<string>? vtables = null;
                List<TransformChange>? appliedChanges = null;
                dynamic? inst = null, db = null;
                try
                {
                    File.Copy(originalMsi, temp, true);
                    File.SetAttributes(temp, File.GetAttributes(temp) & ~FileAttributes.ReadOnly);
                    inst = NewInstaller();
                    db = inst.OpenDatabase(temp, 1);
                    db.ApplyTransform(mstPath, 63 /* ignore all merge-error conditions */);
                    db.Commit();
                    Release(db); db = null; Release(inst); inst = null;
                    GC.Collect(); GC.WaitForPendingFinalizers();

                    vtables = ReadTableNames(temp);
                    // Diff the original MSI against the transformed copy so the panel
                    // can show the transform's own added/modified/deleted rows. Done
                    // here (off the UI thread) so the window stays responsive.
                    appliedChanges = ComputeAppliedTransformChangesCore(originalMsi, temp, vtables);
                    // The per-table yellow-highlight diff is computed lazily when each
                    // table is opened (see EnsureDiffForTable), so applying stays fast.
                }
                catch (Exception ex)
                {
                    error = ex;
                    try { Release(db); Release(inst); } catch { }
                    try { if (File.Exists(temp)) File.Delete(temp); } catch { }
                }

                // Marshal the UI update back onto the dispatcher.
                Dispatcher.BeginInvoke(new Action(() =>
                {
                    SetTransformBusy(false);
                    if (error != null)
                    {
                        MstMessage("Could not apply the transform:\n\n" + error.Message,
                            "Apply MST", MessageBoxButton.OK, MessageBoxImage.Error);
                        return;
                    }
                    ShowTransformResult(originalMsi, mstPath, temp, vtables!,
                                        appliedChanges ?? new List<TransformChange>());
                }));
            });
        }

        /// <summary>Applies the transform view to the UI (runs on the dispatcher).</summary>
        private void ShowTransformResult(string originalMsi, string mstPath, string temp,
                                         List<string> vtables, List<TransformChange> appliedChanges)
        {
            _diffKeys = new(StringComparer.OrdinalIgnoreCase);
            _diffComputed = new(StringComparer.OrdinalIgnoreCase);
            TxtMsiPath.Tag = originalMsi;               // remember the real MSI
            _transformOriginalMsi = originalMsi;
            _appliedMstPath = mstPath;
            _msiPath = temp; _viewingTransform = true;
            _watchedAddedRow = null;
            _tables.Clear(); _changes.Clear();
            GridRows.ItemsSource = null;
            LstTables.ItemsSource = BuildTableListing(vtables);
            UpdateTablesHeader();
            LstTables.SelectedItem = null;
            _preloadComplete = true;                    // transform view loads tables on demand
            string vfirst = vtables.Contains("Property") ? "Property" : (vtables.FirstOrDefault() ?? "");
            if (vfirst.Length > 0)
            {
                LstTables.SelectedItem = vfirst;
                if (GridRows.ItemsSource == null)
                {
                    _currentTable = vfirst;
                    EnsureDiffForTable(vfirst);
                    var stv = LoadTable(vfirst);
                    if (stv != null)
                    {
                        _tables[vfirst] = stv;
                        GridRows.ItemsSource = stv.Data.DefaultView;
                    }
                }
            }
            // Transform view is editable — edits stack on the applied transform.
            SetEditingLocked(false);
            BtnViewMst.IsEnabled = true;
            BtnValidate.IsEnabled = true;
            if (BtnViewChanges != null) BtnViewChanges.IsEnabled = true;
            BtnExportPanel.IsEnabled = true;
            ClearValidation();                            // prior validation no longer applies

            // The Visual form reads the package through the cached tables, and applying a transform
            // replaced both the package and the cache. Nothing rebuilt the panel already on screen,
            // so it went on showing the values from before the transform until the category was
            // switched away and back, which is what rebuilds it. Done here, before the change panel
            // is summarised below, so anything the rebuild stages is counted in that summary. The
            // open-MSI path does the same, for the same reason.
            if (_formMode) ShowCategory();

            // Surface the transform's own changes (MSI vs MST) in the panel and
            // switch to that view automatically, so the differences show up the moment
            // the transform is applied.
            _appliedTransformChanges = appliedChanges;
            ShowBottomPanel();
            if (_panelCollapsed) SetPanelCollapsed(false);
            if (TabTransform != null) TabTransform.IsChecked = true;
            RefreshTransformChanges();                    // applied changes (+ any staged edits)
            int adds = _transformChanges.Count(c => c.Action == "Add");
            int mods = _transformChanges.Count(c => c.Action == "Modify");
            int dels = _transformChanges.Count(c => c.Action == "Delete");
            if (TxtPanelSummary != null)
                TxtPanelSummary.Text = _transformChanges.Count == 0
                    ? "No changes."
                    : $"{_transformChanges.Count} change(s) · {adds} add · {mods} modify · {dels} delete";

            DeferRefreshVisuals();
            TxtMsiPath.Text = originalMsi + "  +  " + Path.GetFileName(mstPath) + "   (transformed - editable)";
            TxtStatus.Text = "Transform applied. Yellow rows are the transform's changes; you can edit on top if you want. " +
                             "Save writes the transform (.mst) against the original MSI. " +
                             "Create MST is optional - it makes a separate second-layer transform of only your new edits. " +
                             "Browse the original MSI to start over.";
        }

        /// <summary>
        /// Computes (once, cached) the changed-row set for a single table in the
        /// current transformed view by comparing it against the original MSI.
        /// </summary>
        private void EnsureDiffForTable(string table)
        {
            if (!_viewingTransform) return;
            if (_diffComputed.Contains(table)) return;
            _diffComputed.Add(table);
            try
            {
                var orig = SnapshotOneTable(_transformOriginalMsi, table);
                var tran = SnapshotOneTable(_msiPath, table);
                if (tran == null) return;

                var changed = new HashSet<string>(StringComparer.Ordinal);
                foreach (var row in tran)
                    if (orig == null || !orig.TryGetValue(row.Key, out var orow) || orow != row.Value)
                        changed.Add(row.Key);
                if (changed.Count > 0) _diffKeys[table] = changed;
            }
            catch { /* best-effort highlight */ }
        }

        /// <summary>Opens a database and snapshots a single table. Returns null on failure.</summary>
        private static Dictionary<string, string>? SnapshotOneTable(string msiPath, string table)
        {
            // Fast flat-API snapshot first; fall back to automation only if it fails.
            var native = SnapshotOneTableNative(msiPath, table);
            if (native != null) return native;

            dynamic? inst = null, db = null;
            try
            {
                inst = NewInstaller();
                db   = inst.OpenDatabase(msiPath, 0);
                return SnapshotTableFrom(db, table);
            }
            catch { return null; }
            finally { Release(db); Release(inst); }
        }

        // One table's snapshot: key→row-signature map plus column and key-column
        // names, all read in a single native pass.
        private sealed class TableSnap
        {
            public Dictionary<string, string> Rows = new(StringComparer.Ordinal);
            public List<string> Cols = new();
            public List<string> KeyCols = new();
        }

        // Snapshot every requested table from a database opened only once. Reopening
        // the database per table (and per side of the diff) was the bulk of the time
        // spent applying a transform; one open per database removes it.
        private static Dictionary<string, TableSnap> SnapshotDatabaseNative(string msiPath, IEnumerable<string> tables)
        {
            var result = new Dictionary<string, TableSnap>(StringComparer.OrdinalIgnoreCase);
            uint hDb = 0;
            try
            {
                if (MsiApi.MsiOpenDatabaseW(msiPath, IntPtr.Zero, out hDb) != MsiApi.ERROR_SUCCESS)
                    return result;
                foreach (var table in tables)
                {
                    var snap = SnapshotTableOnDb(hDb, table);
                    if (snap != null) result[table] = snap;
                }
                return result;
            }
            catch { return result; }
            finally { if (hDb != 0) MsiApi.MsiCloseHandle(hDb); }
        }

        // Read one table from an already-open database handle. Mirrors
        // SnapshotTableFrom exactly (column order, "(binary)" placeholder, key
        // detection, U+001F separators) so signatures compare equal across paths.
        private static TableSnap? SnapshotTableOnDb(uint hDb, string table)
        {
            uint hView = 0, hNames = 0, hTypes = 0;
            try
            {
                if (MsiApi.MsiDatabaseOpenViewW(hDb, $"SELECT * FROM `{table}`", out hView) != MsiApi.ERROR_SUCCESS)
                    return null;
                if (MsiApi.MsiViewExecute(hView, 0) != MsiApi.ERROR_SUCCESS)
                    return null;
                if (MsiApi.MsiViewGetColumnInfo(hView, MsiApi.MSICOLINFO_NAMES, out hNames) != MsiApi.ERROR_SUCCESS)
                    return null;
                if (MsiApi.MsiViewGetColumnInfo(hView, MsiApi.MSICOLINFO_TYPES, out hTypes) != MsiApi.ERROR_SUCCESS)
                    return null;

                int cols = (int)MsiApi.MsiRecordGetFieldCount(hNames);
                if (cols <= 0) return null;
                var snap = new TableSnap();
                var colNames = new string[cols + 1];
                var isBinary = new bool[cols + 1];
                for (int i = 1; i <= cols; i++)
                {
                    colNames[i] = MsiGetString(hNames, (uint)i);
                    snap.Cols.Add(colNames[i]);
                    string ctype = MsiGetString(hTypes, (uint)i);
                    char k = char.ToLowerInvariant(ctype.Length > 0 ? ctype[0] : 's');
                    isBinary[i] = (k == 'v' || k == 'o');
                }

                var keyIdx = new List<int>();
                if (MsiApi.MsiDatabaseGetPrimaryKeysW(hDb, table, out uint hKeys) == MsiApi.ERROR_SUCCESS && hKeys != 0)
                {
                    int kc = (int)MsiApi.MsiRecordGetFieldCount(hKeys);
                    var keyNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    for (int i = 1; i <= kc; i++)
                    {
                        string kn = MsiGetString(hKeys, (uint)i);
                        snap.KeyCols.Add(kn); keyNames.Add(kn);
                    }
                    MsiApi.MsiCloseHandle(hKeys);
                    for (int i = 1; i <= cols; i++) if (keyNames.Contains(colNames[i])) keyIdx.Add(i);
                }
                if (keyIdx.Count == 0 && cols >= 1)
                {
                    keyIdx.Add(1);
                    if (snap.KeyCols.Count == 0) snap.KeyCols.Add(colNames[1]);
                }

                while (true)
                {
                    if (MsiApi.MsiViewFetch(hView, out uint hRec) != MsiApi.ERROR_SUCCESS || hRec == 0)
                        break;
                    var keyParts = new List<string>();
                    var rowParts = new List<string>();
                    for (int i = 1; i <= cols; i++)
                    {
                        string cell = isBinary[i] ? "(binary)" : MsiGetString(hRec, (uint)i);
                        rowParts.Add(cell);
                        if (keyIdx.Contains(i)) keyParts.Add(cell);
                    }
                    snap.Rows[string.Join("\u001F", keyParts)] = string.Join("\u001F", rowParts);
                    MsiApi.MsiCloseHandle(hRec);
                }
                return snap;
            }
            catch { return null; }
            finally
            {
                if (hNames != 0) MsiApi.MsiCloseHandle(hNames);
                if (hTypes != 0) MsiApi.MsiCloseHandle(hTypes);
                if (hView  != 0) { MsiApi.MsiViewClose(hView); MsiApi.MsiCloseHandle(hView); }
            }
        }

        // Single-table convenience wrapper (used by the per-table highlight diff).
        private static Dictionary<string, string>? SnapshotOneTableNative(string msiPath, string table)
        {
            uint hDb = 0;
            try
            {
                if (MsiApi.MsiOpenDatabaseW(msiPath, IntPtr.Zero, out hDb) != MsiApi.ERROR_SUCCESS)
                    return null;
                return SnapshotTableOnDb(hDb, table)?.Rows;
            }
            catch { return null; }
            finally { if (hDb != 0) MsiApi.MsiCloseHandle(hDb); }
        }

        /// <summary>Enables/disables the toolbar while a transform is being applied.</summary>
        private void SetTransformBusy(bool busy)
        {
            AppBusy.SetManual("Edit MSI (transform)", busy);
            BtnOpenMsi.IsEnabled   = !busy;
            BtnViewMst.IsEnabled   = !busy;
            BtnSaveMsi.IsEnabled   = !busy && (_viewingTransform || BtnSaveMsi.IsEnabled);
            BtnCreateMst.IsEnabled = !busy && (_viewingTransform || BtnCreateMst.IsEnabled);
            BtnAddRow.IsEnabled    = !busy && BtnAddRow.IsEnabled;
            BtnDeleteRow.IsEnabled = !busy && BtnDeleteRow.IsEnabled;
            LstTables.IsEnabled    = !busy;
            GridRows.IsEnabled     = !busy;
            System.Windows.Input.Mouse.OverrideCursor =
                busy ? System.Windows.Input.Cursors.Wait : null;
        }

        private static string SqlVal(char kind, string v)
        {
            if (kind == 'i')
                return string.IsNullOrWhiteSpace(v) ? "NULL" : v.Trim();
            return "'" + Esc(v) + "'";
        }

        // ── Tables view Find & Replace (Ctrl+H) ─────────────────────────────
        private Window? _replaceWin;
        private TextBox? _frFind, _frReplace;
        private CheckBox? _frWhole, _frCase, _frCurrentOnly;
        private Button? _frNext, _frRep, _frRepAll;
        private string _frTable = ""; private int _frRow = -1; private string _frColName = "";

        private void TablesViewRoot_PreviewKeyDown(object sender, System.Windows.Input.KeyEventArgs e)
        {
            bool ctrl = (System.Windows.Input.Keyboard.Modifiers & System.Windows.Input.ModifierKeys.Control) == System.Windows.Input.ModifierKeys.Control;
            if (ctrl && !_formMode && (e.Key == System.Windows.Input.Key.H || e.Key == System.Windows.Input.Key.F))
            {
                OpenFindReplaceDialog(e.Key == System.Windows.Input.Key.H);   // Ctrl+H = Replace, Ctrl+F = Search
                e.Handled = true;
                return;
            }

            // Row shortcuts only when the grid is usable and the focus is NOT inside a cell text
            // editor - so Ctrl+C / Ctrl+V keep their normal in-cell text behaviour while typing.
            if (_formMode || !_editingUnlocked || GridRows.IsReadOnly) return;
            bool editingCell = System.Windows.Input.Keyboard.FocusedElement is TextBox;
            if (editingCell) return;

            if (ctrl && e.Key == System.Windows.Input.Key.C)
            {
                if (BtnCopyRow.IsEnabled) { BtnCopyRow_Click(BtnCopyRow, new RoutedEventArgs()); e.Handled = true; }
            }
            else if (ctrl && e.Key == System.Windows.Input.Key.V)
            {
                if (BtnPasteRow.IsEnabled) { BtnPasteRow_Click(BtnPasteRow, new RoutedEventArgs()); e.Handled = true; }
            }
            else if (ctrl && e.Key == System.Windows.Input.Key.N)
            {
                if (BtnAddRow.IsEnabled) { BtnAddRow_Click(BtnAddRow, new RoutedEventArgs()); e.Handled = true; }
            }
            else if (e.Key == System.Windows.Input.Key.Delete)
            {
                if (BtnDeleteRow.IsEnabled && GridRows.SelectedItem is DataRowView)
                { BtnDeleteRow_Click(BtnDeleteRow, new RoutedEventArgs()); e.Handled = true; }
            }
        }

        private bool _frReplaceMode = true;
        private void OpenFindReplaceDialog(bool replaceMode)
        {
            if (_replaceWin != null)
            {
                if (_frReplaceMode == replaceMode)
                { try { _replaceWin.Activate(); _frFind?.Focus(); _frFind?.SelectAll(); } catch { } return; }
                try { _replaceWin.Close(); } catch { }   // switching mode: rebuild the dialog
            }
            _frReplaceMode = replaceMode;

            _frTable = ""; _frRow = -1; _frColName = "";

            const string tplNs = " xmlns=\"http://schemas.microsoft.com/winfx/2006/xaml/presentation\" xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\"";
