                "<ControlTemplate TargetType=\"Button\"" + tplNs + ">" +
                  "<Border x:Name=\"bd\" CornerRadius=\"6\" Background=\"{TemplateBinding Background}\" BorderBrush=\"{TemplateBinding BorderBrush}\" BorderThickness=\"{TemplateBinding BorderThickness}\" SnapsToDevicePixels=\"True\">" +
                    "<ContentPresenter HorizontalAlignment=\"Center\" VerticalAlignment=\"Center\" RecognizesAccessKey=\"True\"/>" +
                  "</Border>" +
                  "<ControlTemplate.Triggers>" +
                    "<Trigger Property=\"IsMouseOver\" Value=\"True\"><Setter TargetName=\"bd\" Property=\"Background\" Value=\"#E8ECF3\"/></Trigger>" +
                    "<Trigger Property=\"IsPressed\" Value=\"True\"><Setter TargetName=\"bd\" Property=\"Background\" Value=\"#D5DBE6\"/></Trigger>" +
                    "<Trigger Property=\"IsEnabled\" Value=\"False\"><Setter TargetName=\"bd\" Property=\"Opacity\" Value=\"0.5\"/></Trigger>" +
                  "</ControlTemplate.Triggers>" +
                "</ControlTemplate>");
            var txtTpl = (System.Windows.Controls.ControlTemplate)System.Windows.Markup.XamlReader.Parse(
                "<ControlTemplate TargetType=\"TextBox\"" + tplNs + ">" +
                  "<Border CornerRadius=\"6\" Background=\"{TemplateBinding Background}\" BorderBrush=\"{TemplateBinding BorderBrush}\" BorderThickness=\"{TemplateBinding BorderThickness}\" SnapsToDevicePixels=\"True\">" +
                    "<ScrollViewer x:Name=\"PART_ContentHost\" Margin=\"6,0\" VerticalAlignment=\"Center\"/>" +
