            _frReplace     = replaceMode ? new TextBox { Width = 210, Height = 26, VerticalContentAlignment = VerticalAlignment.Center, Background = System.Windows.Media.Brushes.White, BorderBrush = edgeBrush, BorderThickness = new Thickness(1), Template = txtTpl } : null;
