            _frNext   = new Button { Content = "Search Next", Width = 100, Height = 28, Margin = new Thickness(0, 0, 0, 6), IsDefault = true, Background = btnBg, BorderBrush = edgeBrush, BorderThickness = new Thickness(1), Template = btnTpl, Cursor = System.Windows.Input.Cursors.Hand };
            _frRep    = replaceMode ? new Button { Content = "Replace",     Width = 100, Height = 28, Margin = new Thickness(0, 0, 0, 6), Background = btnBg, BorderBrush = edgeBrush, BorderThickness = new Thickness(1), Template = btnTpl, Cursor = System.Windows.Input.Cursors.Hand } : null;
            _frRepAll = replaceMode ? new Button { Content = "Replace All", Width = 100, Height = 28, Margin = new Thickness(0, 0, 0, 6), Background = btnBg, BorderBrush = edgeBrush, BorderThickness = new Thickness(1), Template = btnTpl, Cursor = System.Windows.Input.Cursors.Hand } : null;
