            if (replaceMode && lblRepl != null && _frReplace != null)
            {
                AddFormRow();
                Grid.SetRow(lblRepl, fr);    Grid.SetColumn(lblRepl, 0);    form.Children.Add(lblRepl);
                Grid.SetRow(_frReplace, fr); Grid.SetColumn(_frReplace, 1); form.Children.Add(_frReplace);
                fr++;
            }
            AddFormRow(); Grid.SetRow(_frWhole, fr);       Grid.SetColumnSpan(_frWhole, 2);       form.Children.Add(_frWhole);       fr++;
            AddFormRow(); Grid.SetRow(_frCase, fr);        Grid.SetColumnSpan(_frCase, 2);        form.Children.Add(_frCase);        fr++;
            AddFormRow(); Grid.SetRow(_frCurrentOnly, fr); Grid.SetColumnSpan(_frCurrentOnly, 2); form.Children.Add(_frCurrentOnly); fr++;

            var btns = new StackPanel { Orientation = Orientation.Vertical, VerticalAlignment = VerticalAlignment.Top };
            btns.Children.Add(_frNext);
            if (_frRep != null)    btns.Children.Add(_frRep);
            if (_frRepAll != null) btns.Children.Add(_frRepAll);
            btns.Children.Add(btnCancel);

            var rootPanel = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(16) };
            rootPanel.Children.Add(form); rootPanel.Children.Add(btns);

            _replaceWin = new Window
            {
                Title = replaceMode ? "Replace" : "Search",
                SizeToContent = SizeToContent.WidthAndHeight,
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = Window.GetWindow(this),
                ShowInTaskbar = false,
                Content = rootPanel,
            };
            _replaceWin.Closed += (_, __) => { _replaceWin = null; };
            FrUpdateButtons();
            _replaceWin.Show();
            _frFind.Focus();
        }

        private void FrUpdateButtons()
        {
            bool has = (_frFind?.Text ?? "").Length > 0;
            if (_frNext != null)   _frNext.IsEnabled   = has;
            if (_frRep != null)    _frRep.IsEnabled     = has;
            if (_frRepAll != null) _frRepAll.IsEnabled  = has;
        }

        private System.Text.RegularExpressions.Regex? FrRegex()
        {
            string term = _frFind?.Text ?? "";
            if (term.Length == 0) return null;
            var opts = System.Text.RegularExpressions.RegexOptions.None;
            if (!(_frCase?.IsChecked == true)) opts |= System.Text.RegularExpressions.RegexOptions.IgnoreCase;
            string pat = System.Text.RegularExpressions.Regex.Escape(term);
            if (_frWhole?.IsChecked == true) pat = "(?<![A-Za-z0-9_])" + pat + "(?![A-Za-z0-9_])";
            try { return new System.Text.RegularExpressions.Regex(pat, opts); } catch { return null; }
        }

        private static List<string> FrSearchableCols(DataTable dt)
        {
            var l = new List<string>();
            foreach (DataColumn c in dt.Columns)
                if (c.DataType == typeof(string) || c.DataType == typeof(object)) l.Add(c.ColumnName);
            return l;
        }

        // Tables to scan, in the order the user sees them (current-table-only honoured).
        private List<string> FrTables()
        {
            var list = new List<string>();
            if (_frCurrentOnly?.IsChecked == true)
            {
                if (_currentTable.Length > 0 && _tables.ContainsKey(_currentTable)) list.Add(_currentTable);
                return list;
            }
            foreach (var it in LstTables.Items)
                if (it is string s && _tables.ContainsKey(s) && !list.Contains(s)) list.Add(s);
            foreach (var k in _tables.Keys) if (!list.Contains(k)) list.Add(k);
            return list;
        }

        private List<(string table, int row, string col)> FrAllCells()
        {
            var list = new List<(string, int, string)>();
            foreach (var t in FrTables())
            {
                if (!_tables.TryGetValue(t, out var st)) continue;
                var cols = FrSearchableCols(st.Data);
                int rc = st.Data.Rows.Count;
                for (int r = 0; r < rc; r++)
                    foreach (var col in cols)
                        list.Add((t, r, col));
            }
            return list;
        }

        private void FrFindNext()
        {
            var rx = FrRegex(); if (rx == null) return;
            var cells = FrAllCells();
            if (cells.Count == 0) { FrInfo("Nothing to search."); return; }
            int start = -1;
            for (int i = 0; i < cells.Count; i++)
                if (cells[i].row == _frRow && cells[i].col == _frColName &&
                    string.Equals(cells[i].table, _frTable, StringComparison.OrdinalIgnoreCase)) { start = i; break; }
            for (int step = 1; step <= cells.Count; step++)
            {
                int idx = ((start < 0 ? -1 : start) + step) % cells.Count;
                if (idx < 0) idx += cells.Count;
                var cell = cells[idx];
                if (!_tables.TryGetValue(cell.table, out var st)) continue;
                if (cell.row >= st.Data.Rows.Count) continue;
                var row = st.Data.Rows[cell.row];
                if (row.RowState == DataRowState.Deleted) continue;
                if (!st.Data.Columns.Contains(cell.col)) continue;
                string val = Cv(row[cell.col]);
                if (val.Length > 0 && rx.IsMatch(val))
                {
                    _frTable = cell.table; _frRow = cell.row; _frColName = cell.col;
                    FrNavigate(cell.table, cell.row, cell.col);
                    return;
                }
            }
            FrInfo("Cannot find \"" + (_frFind?.Text ?? "") + "\".");
        }

        private void FrReplace()
        {
            var rx = FrRegex(); if (rx == null) return;
            if (_frTable.Length > 0 && _frRow >= 0 && _frColName.Length > 0 &&
                _tables.TryGetValue(_frTable, out var st) && _frRow < st.Data.Rows.Count &&
                st.Data.Columns.Contains(_frColName))
            {
                var row = st.Data.Rows[_frRow];
                if (row.RowState != DataRowState.Deleted)
                {
                    string cell = Cv(row[_frColName]);
                    if (rx.IsMatch(cell))
                    {
                        string repl = _frReplace?.Text ?? "";
                        string nv = rx.Replace(cell, _ => repl);
                        if (nv != cell) { try { row[_frColName] = nv; } catch { } UpdateEditCount(); DeferRefreshVisuals(); }
                    }
                }
            }
            FrFindNext();
        }

        private void FrReplaceAll()
        {
            var rx = FrRegex(); if (rx == null) return;
            string repl = _frReplace?.Text ?? "";
            int count = 0;
            foreach (var t in FrTables())
            {
                if (!_tables.TryGetValue(t, out var st)) continue;
                var cols = FrSearchableCols(st.Data);
                foreach (DataRow row in st.Data.Rows)
                {
                    if (row.RowState == DataRowState.Deleted) continue;
                    foreach (var col in cols)
                    {
                        string cell = Cv(row[col]);
                        if (cell.Length == 0) continue;
                        int n = rx.Matches(cell).Count;
                        if (n == 0) continue;
                        string nv = rx.Replace(cell, _ => repl);
                        if (nv != cell) { try { row[col] = nv; count += n; } catch { } }
                    }
                }
            }
            UpdateEditCount(); DeferRefreshVisuals();
            FrInfo(count == 0 ? "Nothing to replace." : "Replaced " + count + " occurrence(s).");
        }

        private void FrNavigate(string table, int rowIdx, string col)
        {
            try
            {
                if (!string.Equals(_currentTable, table, StringComparison.OrdinalIgnoreCase))
                {
                    _suppressTableValidation = true;
                    LstTables.SelectedItem = table;
                    _suppressTableValidation = false;
                }
                if (!_tables.TryGetValue(table, out var st)) return;
                if (rowIdx < 0 || rowIdx >= st.Data.Rows.Count) return;
                var target = st.Data.Rows[rowIdx];
                if (GridRows.ItemsSource is DataView dv)
                {
                    foreach (DataRowView drv in dv)
                    {
                        if (drv.Row == target)
                        {
                            GridRows.SelectedItem = drv;
                            GridRows.ScrollIntoView(drv);
                            var dgc = GridRows.Columns.FirstOrDefault(cc => string.Equals(Cv(cc.Header), col, StringComparison.Ordinal));
                            if (dgc != null) GridRows.CurrentCell = new DataGridCellInfo(drv, dgc);
                            break;
                        }
                    }
                }
            }
            catch { }
        }

        private void FrInfo(string msg)
        {
            try { System.Windows.MessageBox.Show(_replaceWin ?? Window.GetWindow(this), msg, "Replace", MessageBoxButton.OK, MessageBoxImage.Information); }
            catch { }
        }

        // DBNull-safe cell-to-string. Newly added rows leave unset columns as DBNull
        // (not null and not ""), so a plain (string) cast throws; this normalizes them.
        private static string Cv(object? o) => o is null || o is DBNull ? "" : o.ToString() ?? "";

        /// <summary>
        /// The WHERE clause that finds a row by its primary key, using the values the row carried
        /// when it was read. An empty key value is NULL in the database - Windows Installer stores
        /// no empty strings - so it has to be matched with IS NULL. Comparing it to '' finds
        /// nothing, which is how a delete or an update could quietly do neither.
        /// </summary>
        private static string SqlKeyWhere(TableState st, DataRow r)
        {
            return string.Join(" AND ", st.KeyCols.Select(k =>
            {
                string v = Cv(r[k, DataRowVersion.Original]);
                return v.Length == 0 ? $"`{k}` IS NULL"
                                     : $"`{k}`={SqlVal(st.ColKind[k], v)}";
            }));
        }

        /// <summary>An INSERT carrying the row's current values. Stream columns are left out,
        /// since their bytes do not travel through SQL.</summary>
        private static string SqlInsertRow(string table, TableState st, DataRow r)
        {
            var cols = st.Data.Columns.Cast<DataColumn>()
                .Where(c => st.ColKind[c.ColumnName] != 'v').ToList();
            return $"INSERT INTO `{table}` (" +
                   string.Join(", ", cols.Select(c => $"`{c.ColumnName}`")) + ") VALUES (" +
                   string.Join(", ", cols.Select(c => SqlVal(st.ColKind[c.ColumnName], Cv(r[c])))) + ")";
        }

        /// <summary>Applies all tracked grid edits to the writable temp database.</summary>
        private void ApplyTableEdits(dynamic dbMod)
        {
            foreach (var (table, st) in _tables.Select(kv => (kv.Key, kv.Value)))
            {
                // A table the package does not have has to exist before anything can go into it.
                // Only worth creating when something actually is going in: an empty table would be
                // a difference the transform records for nothing. A failure here is swallowed on
                // purpose - if the table turns out to exist after all the inserts below succeed,
                // and if it genuinely could not be made they fail with a message naming the table.
                if (st.CreateSql.Length > 0 &&
                    st.Data.Rows.Cast<DataRow>().Any(r => r.RowState == DataRowState.Added))
                {
                    dynamic? cv = null;
                    try { cv = dbMod.OpenView(st.CreateSql); cv.Execute(); }
                    catch { }
                    finally { try { cv?.Close(); } catch { } Release(cv); }
                }

                foreach (DataRow r in st.Data.Rows.Cast<DataRow>().ToList())
                {
                    var statements = new List<string>();

                    // A row marked for deletion becomes a DELETE - regardless of any
                    // edits it carries. A marked row is always Unchanged or Modified
                    // (added rows are dropped outright, not marked), so its Original
                    // key values exist and match the row currently in the MSI.
                    if (st.MarkedDelete.Contains(r) || r.RowState == DataRowState.Deleted)
                    {
                        statements.Add($"DELETE FROM `{table}` WHERE {SqlKeyWhere(st, r)}");
                    }
                    else if (r.RowState == DataRowState.Added)
                    {
                        // A stream's bytes cannot travel through SQL, and these rows are nothing
                        // without them, so a row waiting on a stream is inserted whole by
                        // EmbedAddedStreams instead - key and stream in one statement.
                        var pending = PendingStreamRows(table, out string streamKeyCol);
                        if (pending != null && st.Data.Columns.Contains(streamKeyCol)
                            && pending.ContainsKey(Cv(r[streamKeyCol]))) continue;
                        statements.Add(SqlInsertRow(table, st, r));
                    }
                    else if (r.RowState == DataRowState.Modified)
                    {
                        var changed = st.Data.Columns.Cast<DataColumn>()
                            .Where(c => st.ColKind[c.ColumnName] != 'v')
                            .Where(c => !Equals(r[c, DataRowVersion.Original], r[c, DataRowVersion.Current]))
                            .ToList();
                        if (changed.Count == 0) continue;

                        // Windows Installer will not UPDATE a primary key column, so a row whose
                        // key changed has to be replaced rather than updated. The Upgrade table
                        // keeps Attributes in its key, which is why ticking one of its options
                        // failed outright instead of saving.
                        if (changed.Any(c => st.KeyCols.Contains(c.ColumnName, StringComparer.OrdinalIgnoreCase)))
                        {
                            if (st.ColKind.Values.Any(k => k == 'v'))
                                throw new InvalidOperationException(
                                    "A row in the " + table + " table has had a key column changed, and that " +
                                    "table stores a stream which cannot be carried across the rewrite. Undo the " +
                                    "key change and edit the row's other columns instead.");

                            statements.Add($"DELETE FROM `{table}` WHERE {SqlKeyWhere(st, r)}");
                            statements.Add(SqlInsertRow(table, st, r));
                        }
                        else
                        {
                            var sets = changed
                                .Select(c => $"`{c.ColumnName}`={SqlVal(st.ColKind[c.ColumnName], Cv(r[c]))}");
                            statements.Add(
                                $"UPDATE `{table}` SET {string.Join(", ", sets)} WHERE {SqlKeyWhere(st, r)}");
                        }
                    }

                    foreach (string sql in statements)
                    {
                        dynamic? v = null;
                        try { v = dbMod.OpenView(sql); v.Execute(); }
                        finally { try { v?.Close(); } catch { } Release(v); }
                    }
                }
            }
        }

        // Bakes the bytes of files added via the Files view into a new embedded
        // cabinet so they actually install. Runs after ApplyTableEdits and before
        // Commit, while the writable database is open. Throws on failure, in which
        // case Save reports it and nothing is committed.
        // ── Where added files live ───────────────────────────────────────────────────────
        // Adding a file is really two decisions: which component it belongs to, and where its
        // bytes sit on the source media. The second one has to be made before Save, because it
        // decides the File attributes and the shape of the Media row.

        /// <summary>Vital, plus the compression bit that matches where the bytes will be.</summary>
        private static string FileAttrsFor(FileMedia media)
            => media == FileMedia.Uncompressed
                ? "8704"      // 512 Vital + 8192 Noncompressed
                : "16896";    // 512 Vital + 16384 Compressed

        /// <summary>
        /// The folder the package sits in, which is where anything not embedded goes. In
        /// transformed view _msiPath is a temp copy, so the original MSI is what counts: a
        /// cabinet written beside a temp file would vanish with it.
        /// </summary>
        private string PackageFolder()
        {
            string basis = _viewingTransform && _transformOriginalMsi.Length > 0
                ? _transformOriginalMsi : _msiPath;
            try { return Path.GetDirectoryName(basis) ?? ""; } catch { return ""; }
        }

        /// <summary>
        /// Asks where added file bytes should live. Returns null when the user backs out, so the
        /// caller stages nothing rather than leaving File rows with no bytes behind them.
        /// </summary>
        private FileMedia? AskFileMedia(int fileCount)
        {
            var win = BuildNewDialog("Add files");
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, "Add files");

            int r = 0;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var intro = new TextBlock
            {
                Text = (fileCount == 1 ? "Where should the file sit" : $"Where should these {fileCount} files sit")
                     + " once the package is saved?",
                FontSize = 12, TextWrapping = TextWrapping.Wrap, Foreground = valFg,
                Margin = new Thickness(0, 2, 0, 8)
            };
            Grid.SetRow(intro, r); Grid.SetColumn(intro, 1); cg.Children.Add(intro);
            r++;

            var panel = new StackPanel();
            RadioButton Opt(string head, string note, bool on)
            {
                var sp = new StackPanel();
                sp.Children.Add(new TextBlock
                {
                    Text = head, FontSize = 12, FontWeight = FontWeights.SemiBold,
                    Foreground = valFg, TextWrapping = TextWrapping.Wrap
                });
                sp.Children.Add(new TextBlock
                {
                    Text = note, FontSize = 11, Foreground = lblFg,
                    TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 1, 0, 0)
                });
                var rb = new RadioButton
                {
                    GroupName = "swpkFileMedia", IsChecked = on, Content = sp,
                    Foreground = valFg, Margin = new Thickness(0, 0, 0, 10)
                };
                panel.Children.Add(rb);
                return rb;
            }

            Opt("Inside the package",
                "A new cabinet is built and stored in the MSI itself, so the package stays one "
              + "self-contained file. This is what Intune needs.", true);
            var rbCab = Opt("In a cabinet beside the package",
                "A new .cab is written next to the MSI. The two files have to travel together.", false);
            var rbLoose = Opt("Uncompressed beside the package",
                "The files are copied to wherever this package makes the installer look for loose "
              + "files, which for most packages is the folder the MSI sits in. Everything has to "
              + "travel together.", false);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var lbl = new TextBlock
            {
                Text = "Location", FontSize = 11, FontWeight = FontWeights.SemiBold,
                Foreground = lblFg, VerticalAlignment = VerticalAlignment.Top,
                Margin = new Thickness(0, 2, 8, 0)
            };
            Grid.SetRow(lbl, r);   Grid.SetColumn(lbl, 0);
            Grid.SetRow(panel, r); Grid.SetColumn(panel, 1);
            cg.Children.Add(lbl); cg.Children.Add(panel);
            r++;

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var rowIcon = NdDecisionIcon();
            Grid.SetRow(rowIcon, r); Grid.SetColumn(rowIcon, 0); cg.Children.Add(rowIcon);

            FileMedia? picked = null;                       // closing the window adds nothing
            var btnGrid = NdMakeButtons(sec,
                ("✔ Add", () =>
                {
                    picked = rbCab.IsChecked == true   ? FileMedia.ExternalCab
                           : rbLoose.IsChecked == true ? FileMedia.Uncompressed
                           :                             FileMedia.StreamedCab;
                    win.Close();
                }),
                ("Cancel", () => win.Close()));
            Grid.SetRow(btnGrid, r); Grid.SetColumn(btnGrid, 1); cg.Children.Add(btnGrid);

            win.ShowDialog();
            return picked;
        }

        /// <summary>The source half of a DefaultDir cell, long name where the cell holds a pair.
        /// A row with no source half uses its target name on the source side too.</summary>
        private static string MsiSourceDirName(string defaultDir)
        {
            if (string.IsNullOrEmpty(defaultDir)) return "";
            int colon = defaultDir.IndexOf(':');
            string half = colon >= 0 ? defaultDir.Substring(colon + 1) : defaultDir;
            if (half.Length == 0) half = defaultDir;
            int bar = half.IndexOf('|');
            string name = bar >= 0 ? half.Substring(bar + 1) : half;
            return name == "." ? "" : name;
        }

        /// <summary>The folder an uncompressed file sits in, relative to the package.</summary>
        private string ResolveSourceDirPath(string dirKey)
        {
            var segs = new List<string>();
            string cur = dirKey;
            for (int guard = 0; guard < 64 && cur.Length > 0; guard++)
            {
                var row = FindTableRow("Directory", "Directory", cur);
                if (row == null) break;
                string parent = row.Table.Columns.Contains("Directory_Parent") ? Cv(row["Directory_Parent"]) : "";
                if (parent.Length == 0 || string.Equals(parent, cur, StringComparison.OrdinalIgnoreCase)) break;
                string seg = MsiSourceDirName(row.Table.Columns.Contains("DefaultDir") ? Cv(row["DefaultDir"]) : "");
                if (seg.Length > 0) segs.Insert(0, seg);
                if (string.Equals(parent, "TARGETDIR", StringComparison.OrdinalIgnoreCase)) break;
                cur = parent;
            }
            return segs.Count > 0 ? string.Join("\\", segs) : "";
        }

        private string ComponentDirectoryKey(string component)
        {
            if (component.Length == 0) return "";
            var row = FindTableRow("Component", "Component", component);
            return row != null && row.Table.Columns.Contains("Directory_") ? Cv(row["Directory_"]) : "";
        }

        /// <summary>The long half of a FileName cell, which is the name an uncompressed source
        /// layout uses.</summary>
        private static string SourceFileName(DataRow? fileRow)
        {
            if (fileRow == null || !fileRow.Table.Columns.Contains("FileName")) return "";
            string fn = Cv(fileRow["FileName"]);
            int bar = fn.IndexOf('|');
            return bar >= 0 ? fn.Substring(bar + 1) : fn;
        }

        /// <summary>Added files whose bytes would have to live inside the package.</summary>
        private int PendingEmbeddedFileCount()
        {
            if (_addedFileSources.Count == 0) return 0;
            if (!_tables.TryGetValue("File", out var fst)) return 0;

            int n = 0;
            foreach (DataRow r in fst.Data.Rows)
            {
                if (r.RowState != DataRowState.Added) continue;
                string key = Cv(r["File"]);
                if (key.Length == 0 || !_addedFileSources.ContainsKey(key)) continue;
                if (!_addedFileMedia.TryGetValue(key, out var media)) media = FileMedia.StreamedCab;
                if (media == FileMedia.StreamedCab) n++;
            }
            return n;
        }

        /// <summary>
        /// The rows waiting on a stream in a given table, with the column that keys them. Icon and
        /// Binary both hold their data in an Object column, and both are filled the same way: the
        /// picker's Browse puts the row in and records where the bytes came from.
        /// </summary>
        private Dictionary<string, string>? PendingStreamRows(string table, out string keyCol)
        {
            keyCol = "Name";
            if (string.Equals(table, "Icon",   StringComparison.OrdinalIgnoreCase)) return _addedIconSources;
            if (string.Equals(table, "Binary", StringComparison.OrdinalIgnoreCase)) return _addedBinarySources;
            keyCol = "";
            return null;
        }

        /// <summary>
        /// Writes the bytes of icons and binaries added through a picker's Browse.
        ///
        /// The row and its stream go in together rather than the row arriving first and the bytes
        /// following it: neither has a loose-file option the way a File row does, so a row without
        /// its stream is a shortcut pointing at nothing or a custom action with no code to run. The
        /// key goes in the SQL literal and only the bytes bind to the record, which is the shape
        /// the dynamic COM view accepts.
        ///
        /// Run on the transform paths too. These live in their own table's Object column rather
        /// than in _Streams, so they are not the case a transform cannot carry - and inserting them
        /// means the worst a transform can do is carry the row without its bytes, rather than leave
        /// a reference to a row that was never written at all.
        /// </summary>
        private void EmbedAddedStreams(dynamic db, dynamic inst)
        {
            EmbedStreamRows(db, inst, "Icon");
            EmbedStreamRows(db, inst, "Binary");
        }

        private void EmbedStreamRows(dynamic db, dynamic inst, string table)
        {
            var pending = PendingStreamRows(table, out string keyCol);
            if (pending == null || pending.Count == 0) return;
            if (!_tables.TryGetValue(table, out var st)) return;
            if (!st.Data.Columns.Contains(keyCol)) return;

            foreach (DataRow r in st.Data.Rows)
            {
                if (r.RowState != DataRowState.Added) continue;
                string key = Cv(r[keyCol]);
                if (key.Length == 0) continue;
                if (!pending.TryGetValue(key, out var src) || !File.Exists(src)) continue;

                dynamic? rec = null, v = null;
                try
                {
                    rec = inst.CreateRecord(1);
                    rec.SetStream(1, src);
                    v = db.OpenView($"INSERT INTO `{table}` (`{keyCol}`, `Data`) VALUES ('" + Esc(key) + "', ?)");
                    v.Execute(rec);
                }
                finally { try { v?.Close(); } catch { } Release(v); Release(rec); }
            }
        }

        /// <summary>
        /// Writes the bytes behind added files and the Media rows that describe them.
        /// <paramref name="embedStreams"/> is false on the transform path: a generated transform
        /// carries no _Streams, so a cabinet embedded in the package cannot travel in one. A
        /// cabinet or loose files beside the package can, since those are real files on disk and
        /// the transform only has to carry the Media row that points at them.
        /// </summary>
        private void EmbedAddedFiles(dynamic db, dynamic inst, bool embedStreams = true)
        {
            if (_addedFileSources.Count == 0) return;
            if (!_tables.TryGetValue("File", out var fst)) return;

            // Grouped by where the user chose to put each batch. A file with no recorded choice
            // falls back to the streamed cabinet, which is what this always did.
            var groups = new Dictionary<FileMedia, List<(string key, string src)>>();
            foreach (DataRow r in fst.Data.Rows)
            {
                if (r.RowState != DataRowState.Added) continue;
                string key = Cv(r["File"]);
                if (key.Length == 0) continue;
                if (!_addedFileSources.TryGetValue(key, out var src) || !File.Exists(src)) continue;
                if (!_addedFileMedia.TryGetValue(key, out var media)) media = FileMedia.StreamedCab;
                if (media == FileMedia.StreamedCab && !embedStreams) continue;
                if (!groups.TryGetValue(media, out var list))
                    groups[media] = list = new List<(string, string)>();
                list.Add((key, src));
            }
            if (groups.Count == 0) return;

            // Each group gets its own contiguous sequence range and its own Media row, since one
            // Media row can only describe one place the bytes came from.
            var mediaSt   = EnsureTableCached("Media");
            int maxFile   = MaxIntInColumn(fst.Data, "Sequence");
            int maxMedia  = mediaSt != null ? MaxIntInColumn(mediaSt.Data, "LastSequence") : 0;
            int maxDiskId = mediaSt != null ? MaxIntInColumn(mediaSt.Data, "DiskId") : 0;
            int next      = Math.Max(maxFile, maxMedia) + 1;
            int diskId    = maxDiskId;

            foreach (var group in groups)
            {
                var items = group.Value;
                for (int i = 0; i < items.Count; i++)
                    ExecSql(db, $"UPDATE `File` SET `Sequence`={next + i} WHERE `File`='{Esc(items[i].key)}'");
                int lastSeq = next + items.Count - 1;
                next = lastSeq + 1;
                diskId++;

                if (group.Key == FileMedia.Uncompressed)
                {
                    CopyFilesBesidePackage(items);
                    // No Cabinet: the installer reads these from SourceDir at install time.
                    ExecSql(db, $"INSERT INTO `Media` (`DiskId`, `LastSequence`) VALUES ({diskId}, {lastSeq})");
                }
                else if (group.Key == FileMedia.ExternalCab)
                {
                    string cabName = "swpk" + Guid.NewGuid().ToString("N").Substring(0, 6) + ".cab";
                    string built   = BuildCabinet(items, cabName);
                    try
                    {
                        string folder = PackageFolder();
                        if (folder.Length == 0)
                            throw new Exception("The package folder could not be worked out, so the cabinet has nowhere to go.");
                        File.Copy(built, Path.Combine(folder, cabName), true);
                    }
                    finally { try { Directory.Delete(Path.GetDirectoryName(built) ?? "", true); } catch { } }

                    ExecSql(db, $"INSERT INTO `Media` (`DiskId`, `LastSequence`, `Cabinet`) " +
                                $"VALUES ({diskId}, {lastSeq}, '{Esc(cabName)}')");
                }
                else
                {
                    string streamName = "swpk" + Guid.NewGuid().ToString("N").Substring(0, 6);
                    string built      = BuildCabinet(items, streamName + ".cab");
                    try
                    {
                        // The name goes in the SQL literal and only the stream data binds to the
                        // record (methods only, dynamic-COM safe).
                        dynamic? rec = null, v = null;
                        try
                        {
                            rec = inst.CreateRecord(1);
                            rec.SetStream(1, built);
                            v = db.OpenView("INSERT INTO `_Streams` (`Name`, `Data`) VALUES ('" + Esc(streamName) + "', ?)");
                            v.Execute(rec);
                        }
                        finally { try { v?.Close(); } catch { } Release(v); Release(rec); }
                    }
                    finally { try { Directory.Delete(Path.GetDirectoryName(built) ?? "", true); } catch { } }

                    ExecSql(db, $"INSERT INTO `Media` (`DiskId`, `LastSequence`, `Cabinet`) " +
                                $"VALUES ({diskId}, {lastSeq}, '#{streamName}')");
                }
            }
        }

        /// <summary>
        /// True when the package's Word Count says its source is compressed (bit 1). That changes
        /// where the installer looks for a file that is not in a cabinet: beside the package with
        /// no source tree at all, rather than down the layout the Directory table spells out.
        /// Defaults to true when the summary cannot be read, because a compressed source is what
        /// nearly every package a transform targets actually is.
        /// </summary>
        private bool SourceIsCompressed()
        {
            // A staged edit is what the saved package will carry, so it wins over the file.
            if (_summaryEdits.TryGetValue(MsiApi.PID_WORDCOUNT, out var staged)
                && int.TryParse(staged, out int sv))
                return (sv & 2) != 0;
            try
            {
                var vals = ReadSummary(_msiPath);
                if (vals.TryGetValue(MsiApi.PID_WORDCOUNT, out var wc) && int.TryParse(wc, out int n))
                    return (n & 2) != 0;
            }
            catch { }
            return true;
        }

        /// <summary>
        /// Copies uncompressed files to where the installer will look for them, beside the
        /// package. Anything already there is replaced.
        /// </summary>
        private void CopyFilesBesidePackage(List<(string key, string src)> items)
        {
            string root = PackageFolder();
            if (root.Length == 0)
                throw new Exception("The package folder could not be worked out, so uncompressed files have nowhere to go.");

            // A compressed-source package has no source tree: the installer expects a file that
            // is not in a cabinet to sit flat next to the MSI. Only a package whose source is
            // uncompressed resolves the Directory table's source names into a folder layout.
            bool flat = SourceIsCompressed();

            foreach (var it in items)
            {
                var row     = FindTableRow("File", "File", it.key);
                string comp = row != null && row.Table.Columns.Contains("Component_") ? Cv(row["Component_"]) : "";
                string rel  = flat ? "" : ResolveSourceDirPath(ComponentDirectoryKey(comp));
                string name = SourceFileName(row);
                if (name.Length == 0) name = Path.GetFileName(it.src);

                string folder = rel.Length > 0 ? Path.Combine(root, rel) : root;
                Directory.CreateDirectory(folder);
                File.Copy(it.src, Path.Combine(folder, name), true);
            }
        }

        /// <summary>
        /// Builds a cabinet from the given files and returns its path; the caller deletes the
        /// folder it sits in. Each file is copied to a temp file named exactly its File key and
        /// added by that basename, so the cab member name equals the File key, which is how the
        /// installer locates it. (Relying on a makecab rename token is unreliable.)
        /// </summary>
        private static string BuildCabinet(List<(string key, string src)> items, string cabName)
        {
            string work = Path.Combine(Path.GetTempPath(), "swpkadd_" + Guid.NewGuid().ToString("N").Substring(0, 8));
            Directory.CreateDirectory(work);
            try
            {
                // Everything in the directive file is relative to the working directory, which is
                // this staging folder. Absolute paths there break the moment the temp folder has a
                // space in it, while the File keys used as member names are MSI identifiers and
                // cannot.
                var ddf = new System.Text.StringBuilder();
                ddf.AppendLine(".OPTION EXPLICIT");
                ddf.AppendLine(".Set Cabinet=on");
                ddf.AppendLine(".Set Compress=on");
                ddf.AppendLine(".Set MaxDiskSize=0");
                ddf.AppendLine(".Set CabinetName1=" + cabName);
                ddf.AppendLine(".Set DiskDirectory1=.");
                foreach (var it in items)
                {
                    File.Copy(it.src, Path.Combine(work, it.key), true);
                    ddf.AppendLine("\"" + it.key + "\"");
                }
                string ddfPath = Path.Combine(work, "files.ddf");
                File.WriteAllText(ddfPath, ddf.ToString());

                var psi = new System.Diagnostics.ProcessStartInfo("makecab.exe", $"/F \"{ddfPath}\"")
                {
                    WorkingDirectory = work, CreateNoWindow = true, UseShellExecute = false,
                    RedirectStandardOutput = true, RedirectStandardError = true
                };

                var log = new System.Text.StringBuilder();
                using (var proc = System.Diagnostics.Process.Start(psi))
                {
                    if (proc == null) throw new Exception("makecab could not be started.");

                    // Both pipes have to be drained while the process runs. Waiting on makecab
                    // while it blocks writing into a pipe buffer nobody is emptying is a deadlock,
                    // and anything larger than a small file writes more than enough progress
                    // output to fill one. These handlers are raised on pool threads, so they carry
                    // none of the reentrancy that awaiting the streams here would.
                    proc.OutputDataReceived += (_, ea) => { if (ea.Data != null) lock (log) log.AppendLine(ea.Data); };
                    proc.ErrorDataReceived  += (_, ea) => { if (ea.Data != null) lock (log) log.AppendLine(ea.Data); };
                    proc.BeginOutputReadLine();
                    proc.BeginErrorReadLine();

                    if (!proc.WaitForExit(10 * 60 * 1000))
                    {
                        try { proc.Kill(true); } catch { }
                        throw new Exception("Building the cabinet gave up after ten minutes. "
                                          + "makecab was still running and has been stopped.");
                    }
                    proc.WaitForExit();      // lets the readers finish, as the timed overload does not
                }

                string cabPath = Path.Combine(work, cabName);
                if (!File.Exists(cabPath))
                {
                    string tail;
                    lock (log) tail = log.ToString();
                    if (tail.Length > 600) tail = tail.Substring(tail.Length - 600);
                    throw new Exception("Could not build the cabinet for the added files."
                                      + (tail.Trim().Length > 0 ? "\n\nmakecab said:\n" + tail.Trim() : ""));
                }
                return cabPath;
            }
            catch
            {
                try { Directory.Delete(work, true); } catch { }
                throw;
            }
        }

        private static void ExecSql(dynamic db, string sql)
        {
            dynamic? v = null;
            try { v = db.OpenView(sql); v.Execute(); }
            finally { try { v?.Close(); } catch { } Release(v); }
        }

        private static int MaxIntInColumn(DataTable t, string col)
        {
            int max = 0;
            if (t.Columns.Contains(col))
                foreach (DataRow r in t.Rows)
                {
                    if (r.RowState == DataRowState.Deleted) continue;
                    if (r[col] != DBNull.Value && int.TryParse(r[col].ToString(), out int v) && v > max) max = v;
                }
            return max;
        }

        /// <summary>
        /// Writes the staged Property change straight into the cached Property
        /// table so it appears in the grid. Updates the existing row when the
        /// property is already present, otherwise adds a new one.
        /// </summary>
        /// <returns>True when a real change was staged; false when the property
        /// already held the requested value (a no-op the transform would not record).</returns>
        private bool ApplyChangeToPropertyGrid(string name, string val)
        {
            // Ensure the Property table is loaded into the cache.
            if (!_tables.TryGetValue("Property", out var st))
            {
                st = LoadTable("Property");
                if (st == null) return false;
                _tables["Property"] = st;
            }

            // Resolve the Property/Value column names (handles unusual casing).
            string nameCol = st.Data.Columns.Contains("Property") ? "Property"
                            : (st.Data.Columns.Count > 0 ? st.Data.Columns[0].ColumnName : "");
            string valCol  = st.Data.Columns.Contains("Value") ? "Value"
                            : (st.Data.Columns.Count > 1 ? st.Data.Columns[1].ColumnName : "");
            if (nameCol.Length == 0 || valCol.Length == 0) return false;

            DataRow? existing = st.Data.Rows.Cast<DataRow>().FirstOrDefault(r =>
                r.RowState != DataRowState.Deleted && !st.MarkedDelete.Contains(r) &&
                string.Equals((r[nameCol] ?? "").ToString(), name, StringComparison.OrdinalIgnoreCase));

            DataRow? target;
            bool changed = true;
            if (existing != null)
            {
                existing[valCol] = val;
                target = existing;

                // Setting a property to the value it already holds is not a transform
                // change: GenerateTransform records only differences, so it would never
                // appear in the .mst. Leaving the row "modified" would still flag it in
                // the grid and the pending-edit count while the Transform changes panel
                // (correctly) stayed empty - an inconsistency. Revert the no-op so the
                // grid, the count, the panel, and the generated transform all agree.
                if (existing.RowState == DataRowState.Modified && !RowHasRealEdit(st, existing))
                {
                    existing.RejectChanges();
                    changed = false;
                }
            }
            else
            {
                var row = st.Data.NewRow();
                foreach (DataColumn c in st.Data.Columns) row[c] = "";
                row[nameCol] = name;
                row[valCol]  = val;
                st.Data.Rows.Add(row);
                target = row;
            }

            // In Visual view the Tables navigation below moves a grid that is not on screen, so
            // show the row in the friendly Properties list as well. Either way the property that
            // was just staged ends up selected and scrolled to, so it is clear where it landed.
            RevealPropertyInFormView(target);

            // Navigate the Tables list to the Property table so the user sees the
            // change land there, then select and scroll to the affected row.
            if (!string.Equals(_currentTable, "Property", StringComparison.OrdinalIgnoreCase))
            {
                _suppressTableValidation = true;     // don't trip empty-row checks on the switch
                LstTables.SelectedItem = "Property"; // fires LstTables_SelectionChanged → loads grid
                _suppressTableValidation = false;
            }

            // Defer selection until the grid has bound to the Property table's view.
            Dispatcher.BeginInvoke(new Action(() =>
            {
                if (GridRows.ItemsSource is DataView dv)
                {
                    foreach (DataRowView drv in dv)
                        if (ReferenceEquals(drv.Row, target))
                        {
                            GridRows.SelectedItem = drv;
                            GridRows.ScrollIntoView(drv);
                            break;
                        }
                }
                DeferRefreshVisuals();
            }), System.Windows.Threading.DispatcherPriority.Background);

            return changed;
        }

        /// <summary>True when a modified row actually differs from its loaded value
        /// in at least one column (i.e. it is a real edit, not a no-op set).</summary>
        private static bool RowHasRealEdit(TableState st, DataRow r)
        {
            if (r.RowState != DataRowState.Modified) return r.RowState != DataRowState.Unchanged;
            foreach (DataColumn c in st.Data.Columns)
                if ((r[c, DataRowVersion.Original] ?? "").ToString() !=
                    (r[c, DataRowVersion.Current]  ?? "").ToString())
                    return true;
            return false;
        }

        private bool PropertyExists(string prop)
        {
            dynamic? inst = null, db = null, view = null;
            try
            {
                inst = NewInstaller();
                db   = inst.OpenDatabase(_msiPath, 0);
                view = db.OpenView($"SELECT `Value` FROM `Property` WHERE `Property`='{Esc(prop)}'");
                view.Execute();
                dynamic? rec = view.Fetch();
                bool exists = rec != null;
                Release(rec);
                return exists;
            }
            catch { return false; }
            finally
            {
                try { view?.Close(); } catch { }
                Release(view); Release(db); Release(inst);
            }
        }

        // ── Create MST ───────────────────────────────────────────────────
        private void BtnCreateMst_Click(object sender, RoutedEventArgs e)
        {
            if (string.IsNullOrWhiteSpace(_msiPath)) return;

            // Block incomplete manually-added rows before they reach the database.
            if (!CommitGridAndValidate()) return;

            // A generated transform carries no _Streams, so a cabinet embedded in the package
            // cannot travel in one. Saying so beats writing a .mst whose File rows name bytes
            // that are nowhere to be found.
            int embedded = PendingEmbeddedFileCount();
            if (embedded > 0)
            {
                MstMessage(
                    (embedded == 1 ? "A file was added" : embedded + " files were added")
                  + " with its bytes inside the package, and a transform cannot carry an embedded "
                  + "cabinet.\n\nEither use Save to write them into the MSI, or remove them and add "
                  + "them again choosing a cabinet or uncompressed files beside the package, which "
                  + "a transform can point at.",
                    "Create MST", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            // In transformed view _msiPath is a temp file; base the suggested name
            // and folder on the original MSI instead of %temp%.
            string mstBase = _viewingTransform && _transformOriginalMsi.Length > 0
                ? _transformOriginalMsi : _msiPath;
            var dlg = new SaveFileDialog
            {
                Title    = "Save transform as",
                Filter   = "Transform (*.mst)|*.mst",
                FileName = Path.GetFileNameWithoutExtension(mstBase)
                           + (_viewingTransform ? "_edits.mst" : ".mst"),
                InitialDirectory = SafeDir(mstBase),
                OverwritePrompt = false
            };
            if (dlg.ShowDialog() != true) return;
            string mstPath = dlg.FileName;
            if (!ConfirmOverwrite(mstPath, "Create MST")) return;

            string tempCopy = Path.Combine(Path.GetTempPath(),
                "SwiftPackMst_" + Guid.NewGuid().ToString("N") + ".msi");

            bool created = false;

            dynamic? inst = null, dbRef = null, dbMod = null;
            Mouse.OverrideCursor = Cursors.Wait;     // cabbing a large file is not instant
            try
            {
                File.Copy(_msiPath, tempCopy, true);
                var ro = File.GetAttributes(tempCopy);
                File.SetAttributes(tempCopy, ro & ~FileAttributes.ReadOnly);

                inst  = NewInstaller();
                dbRef = inst.OpenDatabase(_msiPath, 0 /* read-only reference */);
                dbMod = inst.OpenDatabase(tempCopy, 1 /* msiOpenDatabaseModeTransact */);

                // Staged property changes are already written into the Property
                // table grid (see ApplyChangeToPropertyGrid) and are applied below
                // by ApplyTableEdits, so they are not replayed separately here.
                ApplyTableEdits(dbMod);
                // Bytes that live beside the package: the files are written to disk now and the
                // Media row lands in the temp copy, so the transform picks it up below.
                EmbedAddedStreams(dbMod, inst);
                EmbedAddedFiles(dbMod, inst, false);
                dbMod.Commit();

                if (File.Exists(mstPath)) File.Delete(mstPath);
                bool different = (bool)dbMod.GenerateTransform(dbRef, mstPath);
                if (!different)
                {
                    TxtStatus.Text = "No differences between the MSI and your edits - an empty transform has nothing to record, so no .mst was written.";
                    MstMessage(
                        "There are no differences to capture - the tables match the original MSI, " +
                        "so an empty transform was not written.\n\n" +
                        "Edit a cell or stage a property change, then create the MST.",
                        "Create MST", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                // 0x0937 condition mask ≈ Orca default: error on AddExistingRow/Table etc. off,
                // validate ProductCode + version range. Keep permissive defaults: none/none.
                dbMod.CreateTransformSummaryInfo(dbRef, mstPath, 0, 0);

                TxtStatus.Text = _viewingTransform
                    ? $"Second-layer MST created: {mstPath} ({PendingEditCount()} new row edit(s)). " +
                      "It applies on top of the already-applied transform."
                    : $"MST created: {mstPath} ({PendingEditCount()} table row edit(s)).";
                created = true;
                if (_summaryEdits.Count > 0)
                    TxtStatus.Text += " Note: Summary Information edits are not carried by a transform - use Save to write them into a new MSI.";
            }
            catch (Exception ex)
            {
                Mouse.OverrideCursor = null;
                MstMessage("Creating the transform failed:\n\n" + ex.Message,
                    "Create MST", MessageBoxButton.OK, MessageBoxImage.Error);
            }
            finally
            {
                Mouse.OverrideCursor = null;
                Release(dbMod); Release(dbRef); Release(inst);
                GC.Collect(); GC.WaitForPendingFinalizers();   // release COM file locks
                try { if (File.Exists(tempCopy)) File.Delete(tempCopy); } catch { }
            }

            if (created)
            {
                MstMessage(
                    (_viewingTransform
                        ? "Second-layer transform created (applies on top of the transform you already applied):\n\n"
                        : "Transform created successfully:\n\n") + mstPath,
                    "Create MST", MessageBoxButton.OK, MessageBoxImage.Information);

                // After creating a first-layer transform from a plain MSI, switch into
                // the transformed (editable) view so the path bar shows
                // "<msi>  +  <mst>   (transformed - editable)".
                if (!_viewingTransform)
                    EnterTransformView(mstBase, mstPath);
            }
        }

        // ══ Styled dialogs ════════════════════════════════════════════════
        // Ported verbatim from the Create Package page so both pages share the
        // identical "— …" dialog look (dark rounded window, title bar, labelled
        // rows, custom buttons) instead of the stock Windows MessageBox.

        private Window BuildNewDialog(string title)
        {
            // Use a visually distinct background so the dialog stands out from the page
            var winBg     = Application.Current.TryFindResource("NavBarBgBrush")   as Brush
                            ?? new SolidColorBrush(Color.FromRgb(0xE8, 0xEA, 0xF5));
            var borderClr = new SolidColorBrush(Color.FromRgb(0x53, 0x56, 0x63));
            var win = new Window
            {
                Title = title, Width = 460, MaxWidth = 460,
                SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = Window.GetWindow(this),
                ResizeMode = ResizeMode.NoResize,
                WindowStyle = WindowStyle.None,
                AllowsTransparency = true,
                Background = Brushes.Transparent,
                FontFamily = new FontFamily("Segoe UI"),
                ShowInTaskbar = false
            };

            // The page restyles ComboBox (and friends) through implicit styles in its own
            // resources, which a separate Window never inherits. Without this merge a dialog
            // combo falls back to the default light chrome while keeping the theme's light
            // foreground, which in dark mode is white text on a white face. The dictionary is
            // shared, not copied, so a theme switch keeps reaching the dialogs too.
            win.Resources.MergedDictionaries.Add(Resources);

            var outer = new Border
            {
                Background = winBg, BorderBrush = borderClr,
                BorderThickness = new Thickness(1.5), CornerRadius = new CornerRadius(10),
                Effect = new System.Windows.Media.Effects.DropShadowEffect
                {
                    BlurRadius = 24, ShadowDepth = 4, Opacity = 0.35, Color = Colors.Black
                }
            };
            win.Content = outer;
            return win;
        }

        private (Grid outerGrid, Grid contentGrid,
                 Brush boxBg, Brush boxBdr, Brush lblFg, Brush valFg, Style? sec)
            BuildNewDialogShell(Window win, string titleText)
        {
            var borderClr  = Application.Current.TryFindResource("BorderMainBrush") as Brush ?? Brushes.LightGray;
            var titleBarBg = new SolidColorBrush(Color.FromRgb(0x53, 0x56, 0x63));
            // Use white text on the dark title bar for contrast
            Brush titleTxtBrush = Brushes.White;
            Brush titleSecBrush = new SolidColorBrush(Color.FromArgb(0xCC, 0xFF, 0xFF, 0xFF));
            var outer      = (Border)win.Content;
            var og = new Grid();
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            og.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            outer.Child = og;
            var tb = new Border { Background = titleBarBg, BorderBrush = borderClr, BorderThickness = new Thickness(0,0,0,1), CornerRadius = new CornerRadius(10,10,0,0), Padding = new Thickness(16,6,12,6) };
            tb.MouseLeftButtonDown += (_, _) => win.DragMove();
            Grid.SetRow(tb, 0);
            var tg = new Grid();
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            var ti  = new TextBlock { Text = "🛠", FontSize = 14, Foreground = titleTxtBrush, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,0,8,0) };
            var tt  = new TextBlock { Text = titleText, FontSize = 13, FontWeight = FontWeights.SemiBold, Foreground = titleTxtBrush, VerticalAlignment = VerticalAlignment.Center };
            var tcl = new Button   { Content = "✕", FontSize = 11, Foreground = titleSecBrush, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = Cursors.Hand, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(6,2,6,2) };
            tcl.Click += (_, _) => win.Close();
            Grid.SetColumn(ti, 0); Grid.SetColumn(tt, 1); Grid.SetColumn(tcl, 2);
            tg.Children.Add(ti); tg.Children.Add(tt); tg.Children.Add(tcl);
            tb.Child = tg; og.Children.Add(tb);
            var cg = new Grid { Margin = new Thickness(8), Background = Brushes.Transparent };
            cg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(72) });
            cg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            // A dialog sizes itself to its content, so a long form grows taller than the screen and
            // takes its own buttons down under the taskbar, where they cannot be reached at all.
            // The content sits in a scroller and the window is capped to the work area, so a form
            // that long scrolls instead. A form that fits is untouched: the scroller measures to
            // its content and no bar appears. The title bar stays outside it, so dragging the
            // window still works while the form is scrolled.
            var cgHost = new ScrollViewer
            {
                Content = cg, Background = Brushes.Transparent,
                VerticalScrollBarVisibility   = ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
            };
            Grid.SetRow(cgHost, 1); og.Children.Add(cgHost);
            win.MaxHeight = Math.Max(360, SystemParameters.WorkArea.Height - 80);
            // Use WindowBgBrush for boxes so they appear light against the darker dialog bg
            var boxBg  = Application.Current.TryFindResource("WindowBgBrush")      as Brush ?? new SolidColorBrush(Color.FromRgb(0xFF, 0xFF, 0xFF));
            var boxBdr = Application.Current.TryFindResource("BorderMainBrush")    as Brush ?? new SolidColorBrush(Color.FromRgb(0xDD, 0xDF, 0xEA));
            var lblFg  = Application.Current.TryFindResource("TextPrimaryBrush")   as Brush ?? new SolidColorBrush(Color.FromRgb(0x1A, 0x1D, 0x2E));
            var valFg  = Application.Current.TryFindResource("TextPrimaryBrush")   as Brush ?? new SolidColorBrush(Color.FromRgb(0x1A, 0x1D, 0x2E));
            var sec    = Application.Current.TryFindResource("SecondaryButtonStyle") as Style;
            return (og, cg, boxBg, boxBdr, lblFg, valFg, sec);
        }

        private static void NdAddRow(Grid g, int row, string label, string value,
            Brush lblFg, Brush boxBg, Brush boxBdr, Brush valFg, bool mono = true)
        {
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var lbl = new TextBlock { Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg, VerticalAlignment = VerticalAlignment.Center };
            var box = new Border { Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(10,6,10,6) };
            box.Child = new TextBlock { Text = value, FontSize = 11, TextWrapping = TextWrapping.Wrap, Foreground = valFg, FontFamily = new FontFamily(mono ? "Consolas" : "Segoe UI") };
            Grid.SetRow(lbl, row); Grid.SetColumn(lbl, 0);
            Grid.SetRow(box, row); Grid.SetColumn(box, 1);
            g.Children.Add(lbl); g.Children.Add(box);
        }

        private static void NdAddSpacer(Grid g, int row, double h = 8)
        {
            g.RowDefinitions.Add(new RowDefinition { Height = new GridLength(h) });
        }

        private static System.Windows.Controls.Primitives.UniformGrid NdMakeButtons(
            Style? sec, params (string label, Action onClick)[] buttons)
        {
            // Highlight one button as the default action so every dialog has a
            // clear, consistent look (matching the Publish Package dialog). The
            // affirmative button is the one carrying the check glyph; when none
            // does, fall back to the first button so exactly one is highlighted.
            int primary = 0;
            for (int i = 0; i < buttons.Length; i++)
            {
                if (buttons[i].label.IndexOf('\u2714') >= 0) { primary = i; break; }
            }
            var ug = new System.Windows.Controls.Primitives.UniformGrid { Rows = 1, Columns = buttons.Length };
            for (int i = 0; i < buttons.Length; i++)
            {
                var margin = i == 0 ? new Thickness(0,0,4,0) : i == buttons.Length-1 ? new Thickness(4,0,0,0) : new Thickness(4,0,4,0);
                var b = new Button { Content = buttons[i].label, Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28, Padding = new Thickness(6,0,6,0), Margin = margin };
                if (i == primary) NdApplyPrimaryLook(b);
                var action = buttons[i].onClick;
                b.Click += (_, _) => action();
                ug.Children.Add(b);
            }
            return ug;
        }

        // Give a dialog button the highlighted "primary action" look: a filled
        // accent background, rounded corners and a subtle hover. Theme resources
        // keep it readable in both light and dark modes, mirroring the Publish
        // Package dialog. Applied on top of any existing Style (local values win
        // in WPF), so callers keep their own sizing.
        private static void NdApplyPrimaryLook(Button b)
        {
            Brush bg     = Application.Current.TryFindResource("DlgBtnBlueBgBrush")     as Brush ?? new SolidColorBrush(Color.FromRgb(0x42, 0x9B, 0xF5));
            Brush fg     = Application.Current.TryFindResource("DlgBtnBlueFgBrush")     as Brush ?? Brushes.White;
            Brush border = Application.Current.TryFindResource("DlgBtnBlueBorderBrush") as Brush ?? bg;

            b.Background      = bg;
            b.Foreground      = fg;
            b.BorderBrush     = border;
            b.BorderThickness = new Thickness(1);
            b.Cursor          = Cursors.Hand;

            var tpl = new ControlTemplate(typeof(Button));
            var bd  = new FrameworkElementFactory(typeof(Border));
            bd.SetValue(Border.BackgroundProperty,      bg);
            bd.SetValue(Border.BorderBrushProperty,     border);
            bd.SetValue(Border.BorderThicknessProperty, new Thickness(1));
            bd.SetValue(Border.CornerRadiusProperty,    new CornerRadius(6));
            var cp = new FrameworkElementFactory(typeof(ContentPresenter));
            cp.SetValue(FrameworkElement.MarginProperty, new Thickness(12, 0, 12, 0));
            cp.SetValue(ContentPresenter.HorizontalAlignmentProperty, HorizontalAlignment.Center);
            cp.SetValue(ContentPresenter.VerticalAlignmentProperty,   VerticalAlignment.Center);
            bd.AppendChild(cp);
            tpl.VisualTree = bd;
            var hov = new Trigger { Property = UIElement.IsMouseOverProperty, Value = true };
            hov.Setters.Add(new Setter(UIElement.OpacityProperty, 0.85));
            tpl.Triggers.Add(hov);
            b.Template = tpl;
        }

        // Uniform "make a choice" icon for a dialog's action row: a blue question
        // glyph matching the Publish Package dialog exactly (same glyph, colour
        // and size) so every popup looks the same. The title bar still carries
        // the page context icon. A monochrome glyph with an explicit Foreground
        // is used so the blue tint always applies in both themes.
        private static TextBlock NdDecisionIcon()
            => new TextBlock
            {
                Text = "\u2753",
                FontSize = 22,
                Foreground = new SolidColorBrush(Color.FromRgb(0x42, 0x9B, 0xF5)),
                HorizontalAlignment = HorizontalAlignment.Left,
                VerticalAlignment   = VerticalAlignment.Center
            };

        // ══ Touchpad / touch scrolling ════════════════════════════════════
        // Precision-touchpad two-finger scroll arrives as manipulation input,
        // which a ScrollViewer ignores unless PanningMode is set. Setting it on
        // the control's real (template-internal) ScrollViewer is reliable; an
        // implicit style does not always reach it. (Horizontal mouse-wheel is
        // handled app-wide in App.xaml.cs.)
        private bool _panWired;
        private ScrollViewer? _panSv;
        private bool _panActive;
        private Point _panStart, _panLast;
        private double _panAccumY;

        // ══ Keyboard shortcuts ════════════════════════════════════════════
        // Delete, F2 and Ctrl+C / Ctrl+V across the editors, so these trees and grids behave the
        // way every other Windows tree does. They call the same handlers the context menus do
        // rather than a second copy of the logic, so the guards, prompts and confirmations are the
        // same ones - a key press can never do more than the menu entry it stands for.
        //
        // Wired in code rather than as XAML attributes: it is one list to keep in step instead of
        // twenty attributes spread through the markup, and a control that grows a menu later only
        // has to be named here.
        private bool _keysWired;

        private void WireEditorKeys()
        {
            if (_keysWired) return;
            _keysWired = true;
            foreach (UIElement? c in new UIElement?[]
                     {
                         DirTree, DirFileList, RegTree, RegValueList, ScTree, FeatScTree, FeatTree,
                         FeatCompList, CaList, EnvTree, SvcTree, IniTree, SrchTree, OdbcTree,
                         DlgTree, TaskTree, CertTree, DrvTree, FwTree, SeqList, UpgList
                     })
                if (c != null) c.PreviewKeyDown += EditorKey_Down;
        }

        private void EditorKey_Down(object sender, KeyEventArgs e)
        {
            // A field being typed into owns the keyboard: Delete has to reach the text rather than
            // the row, and a grid cell in edit mode is exactly that.
            if (e.OriginalSource is System.Windows.Controls.Primitives.TextBoxBase) return;

            bool Is(object? ctl) => ReferenceEquals(sender, ctl);
            void Run(Action<object, RoutedEventArgs> h)
            { h(sender, new RoutedEventArgs()); e.Handled = true; }

            bool plain = Keyboard.Modifiers == ModifierKeys.None;
            bool ctrl  = Keyboard.Modifiers == ModifierKeys.Control;

            if (e.Key == Key.Delete && plain)
            {
                if      (Is(DirTree))      Run(DirDeleteFolder_Click);
                else if (Is(DirFileList))  Run(DirFileDelete_Click);
                else if (Is(RegTree))      Run(RegDeleteKey_Click);
                else if (Is(RegValueList)) Run(RegDeleteValue_Click);
                else if (Is(ScTree) || Is(FeatScTree)) Run(ScDelete_Click);
                else if (Is(FeatCompList)) Run(CompDelete_Click);
                else if (Is(CaList))       Run(CaDelete_Click);
                else if (Is(EnvTree))      Run(EnvDelete_Click);
                else if (Is(SvcTree))      Run(SvcDelete_Click);
                else if (Is(IniTree))      Run(IniDelete_Click);
                else if (Is(SrchTree))     Run(SrchDelete_Click);
                else if (Is(OdbcTree))     Run(OdbcDelete_Click);
                else if (Is(DlgTree))      Run(DlgDelete_Click);
                else if (Is(TaskTree))     Run(TaskDelete_Click);
                else if (Is(CertTree))     Run(CertDelete_Click);
                else if (Is(DrvTree))      Run(DrvDelete_Click);
                else if (Is(FwTree))       Run(FwDelete_Click);
                else if (Is(SeqList))      Run(SeqDelete_Click);
                else if (Is(UpgList))      Run(UpgDelete_Click);
                // The feature tree carries two kinds of row, and Delete means a different thing on
                // each: a component is removed from its feature, a feature is deleted outright.
                else if (Is(FeatTree))
                {
                    if (SelectedFeat()?.Kind == FeatNodeKind.Component) Run(FeatRemoveComponent_Click);
                    else Run(FeatDelete_Click);
                }
                return;
            }

            if (e.Key == Key.F2 && plain)
            {
                if      (Is(DirTree)) Run(DirRenameFolder_Click);
                else if (Is(RegTree)) Run(RegRenameKey_Click);
                else if (Is(ScTree))  Run(ScRename_Click);
                else if (Is(IniTree)) Run(IniRename_Click);
                else if (Is(CaList))  Run(CaRename_Click);
                else if (Is(FeatTree))
                {
                    if (SelectedFeat()?.Kind == FeatNodeKind.Component) Run(FeatRenameComponent_Click);
                    else Run(FeatRenameFeature_Click);
                }
                return;
            }

            // Copy and paste exist only where there is somewhere to paste to, which today is the
            // shortcut tree. Left off the others rather than bound to a handler that would tell the
            // user it cannot help.
            if (ctrl && e.Key == Key.C && Is(ScTree)) Run(ScCopy_Click);
            else if (ctrl && e.Key == Key.V && Is(ScTree)) Run(ScPaste_Click);
        }

        private void EditMSIPage_Loaded(object sender, RoutedEventArgs e)
        {
            WireEditorKeys();
            // Defer to Loaded priority so the controls' template scrollviewers are
            // realized before we look for them.
            Dispatcher.BeginInvoke(new Action(SetupTouchScrolling),
                System.Windows.Threading.DispatcherPriority.Loaded);
        }

        private void SetupTouchScrolling()
        {
            foreach (DependencyObject? ctrl in new DependencyObject?[]
                         { GridRows, LstTables, LstValidation, LstTransform })
            {
                var sv = FindDescendantScrollViewer(ctrl);
                if (sv == null) continue;
                sv.PanningMode = PanningMode.Both;
                sv.PanningRatio = 1.0;
                sv.PanningDeceleration = 0.001;
                if (!_panWired)
                {
                    sv.PreviewMouseLeftButtonDown += OnPanDown;
                    sv.PreviewMouseMove           += OnPanMove;
                    sv.PreviewMouseLeftButtonUp   += OnPanUp;
                }
            }
            _panWired = true;
        }

        // Press on the content and drag to scroll it (hand-grab panning). Works
        // through plain mouse press/move events, so it responds to the touchpad
        // regardless of how the touchpad routes wheel/scroll input. A small move
        // threshold keeps a plain click working as a normal select.
        private void OnPanDown(object sender, MouseButtonEventArgs e)
        {
            var sv = sender as ScrollViewer;
            _panSv = sv;
            _panActive = false;
            if (sv == null) return;
            // Ignore presses that start on a scrollbar or a column header.
            for (DependencyObject? d = e.OriginalSource as DependencyObject; d != null && d != sv; )
            {
                if (d is System.Windows.Controls.Primitives.ScrollBar ||
                    d is System.Windows.Controls.Primitives.DataGridColumnHeader)
                { _panSv = null; return; }
                d = VisualTreeHelper.GetParent(d);
            }
            _panStart = _panLast = e.GetPosition(sv);
            _panAccumY = 0;
        }

        private void OnPanMove(object sender, MouseEventArgs e)
        {
            if (_panSv == null || e.LeftButton != MouseButtonState.Pressed) return;
            Point pos = e.GetPosition(_panSv);
            if (!_panActive)
            {
                if (Math.Abs(pos.X - _panStart.X) < 6 && Math.Abs(pos.Y - _panStart.Y) < 6) return;
                _panActive = true;
                _panSv.CaptureMouse();
                Mouse.OverrideCursor = Cursors.ScrollAll;
            }
            double ddx = pos.X - _panLast.X;
            double ddy = pos.Y - _panLast.Y;
            _panLast = pos;
            if (_panSv.ScrollableWidth > 0)
                _panSv.ScrollToHorizontalOffset(
                    Math.Max(0, Math.Min(_panSv.ScrollableWidth, _panSv.HorizontalOffset - ddx)));
            _panAccumY += ddy;
            while (_panAccumY >= 18) { _panSv.LineUp();   _panAccumY -= 18; }
            while (_panAccumY <= -18) { _panSv.LineDown(); _panAccumY += 18; }
            e.Handled = true;
        }

        private void OnPanUp(object sender, MouseButtonEventArgs e)
        {
            if (_panActive)
            {
                _panSv?.ReleaseMouseCapture();
                Mouse.OverrideCursor = null;
                e.Handled = true;
            }
            _panActive = false;
            _panSv = null;
        }

        private static ScrollViewer? FindDescendantScrollViewer(DependencyObject? root)
        {
            if (root == null) return null;
            if (root is ScrollViewer sv) return sv;
            int n = VisualTreeHelper.GetChildrenCount(root);
            for (int i = 0; i < n; i++)
            {
                var found = FindDescendantScrollViewer(VisualTreeHelper.GetChild(root, i));
                if (found != null) return found;
            }
            return null;
        }

        private static ScrollViewer? ScrollViewerUnderMouse()
        {
            DependencyObject? d = Mouse.DirectlyOver as DependencyObject;
            while (d != null)
            {
                if (d is ScrollViewer sv) return sv;
                d = d is Visual || d is System.Windows.Media.Media3D.Visual3D
                    ? VisualTreeHelper.GetParent(d)
                    : (d as FrameworkContentElement)?.Parent
                      ?? (d as FrameworkElement)?.Parent;
            }
            return null;
        }

        // Vertical wheel handled at the page root (tunneling) so it scrolls even if
        // a child swallows the bubbling event or the wheel never reaches the grid's
        // own ScrollViewer. LineUp/LineDown work in both pixel and item scroll modes.
        private void OnPreviewMouseWheel(object sender, MouseWheelEventArgs e)
        {
            if (e.Handled || e.Delta == 0) return;
            var sv = ScrollViewerUnderMouse();
            if (sv == null || sv.ScrollableHeight <= 0) return;
            int lines = Math.Max(1, Math.Abs(e.Delta) / 40);
            for (int i = 0; i < lines; i++)
            {
                if (e.Delta > 0) sv.LineUp(); else sv.LineDown();
            }
            e.Handled = true;
        }

        /// <summary>Styled replacement for the file picker's native overwrite
        /// prompt. Returns true when it is OK to write to <paramref name="path"/>.</summary>
        private bool ConfirmOverwrite(string path, string caption)
        {
            if (!File.Exists(path)) return true;
            return MstMessage(
                $"\u201C{path}\u201D already exists.\n\nDo you want to replace it?",
                caption, MessageBoxButton.YesNo, MessageBoxImage.Warning) == MessageBoxResult.Yes;
        }

        /// <summary>
        /// Drop-in replacement for MessageBox.Show using the shared styled dialog.
        /// Same signature/return so existing Yes/No branches keep working.
        /// </summary>
        /// <summary>
        /// The themed three-way prompt used before staged edits would be thrown away. Yes means
        /// save, No means discard, Cancel means stay where we are. Built like MstMessage so it
        /// carries the same shell and the single highlighted primary button.
        /// </summary>
        private MessageBoxResult AskSaveDiscardCancel(string text, string caption)
        {
            string title = string.IsNullOrEmpty(caption) ? "SwiftPack Studio" : caption;

            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            int r = 0;
            NdAddRow(cg, r++, "Warning", text, lblFg, boxBg, boxBdr, valFg, false); NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var rowIcon = NdDecisionIcon();
            Grid.SetRow(rowIcon, r); Grid.SetColumn(rowIcon, 0); cg.Children.Add(rowIcon);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            MessageBoxResult result = MessageBoxResult.Cancel;      // closing the window stays put
            var btnGrid = NdMakeButtons(sec,
                ("✔ Save",    () => { result = MessageBoxResult.Yes;    win.Close(); }),
                ("✕ No",   () => { result = MessageBoxResult.No;     win.Close(); }),
                ("Cancel",    () => { result = MessageBoxResult.Cancel; win.Close(); }));
            Grid.SetRow(btnGrid, r); Grid.SetColumn(btnGrid, 1); cg.Children.Add(btnGrid);

            win.ShowDialog();
            return result;
        }

        private MessageBoxResult MstMessage(string text, string caption,
            MessageBoxButton buttons, MessageBoxImage image)
        {
            string title = string.IsNullOrEmpty(caption) ? "SwiftPack Studio" : caption;
            string label = image == MessageBoxImage.Error ? "Error"
                         : image == MessageBoxImage.Warning ? "Warning"
                         : (buttons == MessageBoxButton.YesNo ? "Action" : "Status");

            var win = BuildNewDialog(title);
            var (_, cg, boxBg, boxBdr, lblFg, valFg, sec) = BuildNewDialogShell(win, title);
            int r = 0;
            NdAddRow(cg, r++, label, text, lblFg, boxBg, boxBdr, valFg, false); NdAddSpacer(cg, r++);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var rowIcon = NdDecisionIcon();
            Grid.SetRow(rowIcon, r); Grid.SetColumn(rowIcon, 0); cg.Children.Add(rowIcon);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            MessageBoxResult result = buttons == MessageBoxButton.YesNo ? MessageBoxResult.No
                                    : buttons == MessageBoxButton.OKCancel ? MessageBoxResult.Cancel
                                    : MessageBoxResult.OK;
            var btnGrid = buttons switch
            {
                MessageBoxButton.YesNo => NdMakeButtons(sec,
                    ("✔ Yes", () => { result = MessageBoxResult.Yes; win.Close(); }),
                    ("✕ No",  () => { result = MessageBoxResult.No;  win.Close(); })),
                MessageBoxButton.OKCancel => NdMakeButtons(sec,
                    ("✔ OK",     () => { result = MessageBoxResult.OK;     win.Close(); }),
                    ("✕ Cancel", () => { result = MessageBoxResult.Cancel; win.Close(); })),
                _ => NdMakeButtons(sec,
                    ("✕ Close", () => { result = MessageBoxResult.OK; win.Close(); }))
            };
            Grid.SetRow(btnGrid, r); Grid.SetColumn(btnGrid, 1); cg.Children.Add(btnGrid);

            win.ShowDialog();
            return result;
        }
    }

    /// <summary>
    /// A directory node in the Files tree (one per Directory-table row). Holds the
    /// File rows that install into this directory plus its child directories.
    /// Implements change notification so expand/rename can update the tree live.
    /// </summary>
    public sealed class DirNode : System.ComponentModel.INotifyPropertyChanged
    {
        public string Key = "";
        public string DefaultDir = "";
        public string ParentKey = "";
        public System.Data.DataRow? DirRow;     // Directory-table row (null for synthetic)
        public DirNode? Parent;
        public bool IsShortcut;                  // true for a shortcut leaf node
        public System.Data.DataRow? ScRow;       // Shortcut-table row (shortcut leaves only)
        public System.Windows.Media.Geometry IconGeometry =>
            IsShortcut ? MsiIcons.Shortcut : MsiIcons.Folder;
        public System.Collections.Generic.List<System.Data.DataRow> Files { get; } =
            new System.Collections.Generic.List<System.Data.DataRow>();
        public System.Collections.ObjectModel.ObservableCollection<DirNode> Children { get; } =
            new System.Collections.ObjectModel.ObservableCollection<DirNode>();

        private string _display = "";
        public string Display
        {
            get => _display;
            set { if (_display != value) { _display = value; OnChanged(nameof(Display)); } }
        }

        private bool _isExpanded;
        public bool IsExpanded
        {
            get => _isExpanded;
            set { if (_isExpanded != value) { _isExpanded = value; OnChanged(nameof(IsExpanded)); } }
        }

        // DefaultDir is "target[:source]" where target may be "short|long"; the long
        // target part is the folder name ("." means same path as the parent).
        public string LongName
        {
            get
            {
                string dd = DefaultDir;
                if (string.IsNullOrEmpty(dd)) return "";
                int colon = dd.IndexOf(':');
                string target = colon >= 0 ? dd.Substring(0, colon) : dd;
                int bar = target.IndexOf('|');
                return bar >= 0 ? target.Substring(bar + 1) : target;
            }
        }

        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
        private void OnChanged(string n) =>
            PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(n));
    }

    /// <summary>
    /// View-model for one row of the File table in the friendly Files view. Display
    /// fields are read straight from the underlying DataRow; a Version edit writes
    /// back into it so it stages like any other change.
    /// </summary>
    public sealed class FileRow : System.ComponentModel.INotifyPropertyChanged
    {
        private readonly System.Data.DataRow _row;
        private readonly System.Action _onEdited;
        public FileRow(System.Data.DataRow row, System.Action onEdited) { _row = row; _onEdited = onEdited; }
        public System.Data.DataRow Row => _row;

        // The File-table primary key (used as the component's KeyPath value).
        public string Key => Get("File");

        // True when this file is its component's KeyPath; drives the key-path icon.
        private bool _isKeyPath;
        public bool IsKeyPath
        {
            get => _isKeyPath;
            set { if (_isKeyPath != value) { _isKeyPath = value; PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(nameof(KeyPathGlyph))); } }
        }
        public string KeyPathGlyph => IsKeyPath ? "\uD83D\uDD11" : "";

        // Deleting a row that was added in this session detaches it outright, and any wrapper
        // still pointing at it would throw on the next read rather than come back empty.
        // Wrappers outlive their rows for a moment whenever a bound list is rebuilt.
        private string Get(string c) =>
            _row.RowState == System.Data.DataRowState.Detached
            || _row.RowState == System.Data.DataRowState.Deleted ? ""
            : _row.Table.Columns.Contains(c) && _row[c] != System.DBNull.Value ? _row[c].ToString() ?? "" : "";

        // FileName is stored as "short|long"; show the long (friendly) part.
        public string LongName
        {
            get { string fn = Get("FileName"); int p = fn.IndexOf('|'); return p >= 0 ? fn.Substring(p + 1) : fn; }
        }

        public string Component => Get("Component_");

        public string SizeText => FormatSize(Get("FileSize"));

        public string Attributes => Get("Attributes");

        public string Meta
        {
            get
            {
                string c = Component, s = FormatSize(Get("FileSize"));
                if (c.Length > 0 && s.Length > 0) return $"{c}  ·  {s}";
                return c.Length > 0 ? c : s;
            }
        }

        public string Version
        {
            get => Get("Version");
            set
            {
                string v = value ?? "";
                if (!_row.Table.Columns.Contains("Version") || Get("Version") == v) return;
                _row["Version"] = v;
                _onEdited();
                PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(nameof(Version)));
            }
        }

        private static string FormatSize(string raw)
        {
            if (!long.TryParse(raw, out long b) || b < 0) return "";
            string[] u = { "B", "KB", "MB", "GB", "TB" };
            double v = b; int i = 0;
            while (v >= 1024 && i < u.Length - 1) { v /= 1024; i++; }
            return i == 0 ? $"{b} B" : $"{v:0.#} {u[i]}";
        }

        // Rename the file: replace the long part of FileName, keeping any short token.
        public void Rename(string newLong)
        {
            if (!_row.Table.Columns.Contains("FileName")) return;
            string fn = Get("FileName");
            int bar = fn.IndexOf('|');
            string shortPart = bar >= 0 ? fn.Substring(0, bar) : "";
            _row["FileName"] = shortPart.Length > 0 ? shortPart + "|" + newLong : newLong;
            _onEdited();
            PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(nameof(LongName)));
        }

        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
    }

