    // A row in the registry values grid. Decodes the MSI Value encoding for display;
    // Name "+", "-" and "*" are key operations rather than values.
    public sealed class RegValueRow : System.ComponentModel.INotifyPropertyChanged
    {
        private readonly System.Data.DataRow _row;
        public RegValueRow(System.Data.DataRow row) { _row = row; }
        public System.Data.DataRow Row => _row;

        // Re-read the underlying row so the grid cells refresh after an inline edit.
        public void Refresh()
        {
            OnChanged(nameof(NameDisplay));
            OnChanged(nameof(TypeText));
            OnChanged(nameof(DataText));
            OnChanged(nameof(Component));
        }
        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
        private void OnChanged(string n) => PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(n));

        // See FileRow.Get: a detached or deleted row must read as empty, not throw.
        private string Get(string c) =>
            _row.RowState == System.Data.DataRowState.Detached
            || _row.RowState == System.Data.DataRowState.Deleted ? ""
            : _row.Table.Columns.Contains(c) && _row[c] != System.DBNull.Value ? _row[c].ToString() ?? "" : "";

        private string RawName  => Get("Name");
        private string RawValue => Get("Value");

        public bool IsKeyOp => RawName == "+" || RawName == "-" || RawName == "*";

        // The Registry-table primary key (used as the component KeyPath value).
        public string Key => Get("Registry");

        // True when this value is its component's KeyPath; drives the key-path icon.
        private bool _isKeyPath;
        public bool IsKeyPath
        {
            get => _isKeyPath;
            set { if (_isKeyPath != value) { _isKeyPath = value; OnChanged(nameof(KeyPathGlyph)); } }
        }
        public string KeyPathGlyph => IsKeyPath ? "\uD83D\uDD11" : "";

        public string NameDisplay => IsKeyOp ? "(key)" : (RawName.Length == 0 ? "(Default)" : RawName);

        public string Component => Get("Component_");

        public string TypeText => RawName switch
        {
            "+" => "Key (create)",
            "-" => "Key (remove)",
            "*" => "Key (create+remove)",
            _   => DecodeType(RawValue)
        };

        public string DataText => IsKeyOp ? "" : DecodeData(RawValue);

        private static string DecodeType(string v)
        {
            if (v.StartsWith("#x", System.StringComparison.Ordinal)) return "REG_BINARY";
            if (v.StartsWith("#%", System.StringComparison.Ordinal)) return "REG_EXPAND_SZ";
            if (v.StartsWith("##", System.StringComparison.Ordinal)) return "REG_SZ";
            if (v.StartsWith("#",  System.StringComparison.Ordinal)) return "REG_DWORD";
            if (v.Contains("[~]")) return "REG_MULTI_SZ";
            return "REG_SZ";
        }

        private static string DecodeData(string v)
        {
            if (v.StartsWith("#x", System.StringComparison.Ordinal)) return v.Substring(2);
            if (v.StartsWith("#%", System.StringComparison.Ordinal)) return v.Substring(2);
            if (v.StartsWith("##", System.StringComparison.Ordinal)) return "#" + v.Substring(2);
            if (v.StartsWith("#",  System.StringComparison.Ordinal)) return v.Substring(1);
            if (v.Contains("[~]")) return v.Replace("[~]", "  ·  ");
            return v;
        }
    }

