    // one of the Files / Registry / Shortcuts category buckets under a component.
    public enum FeatNodeKind { Feature, Component, FilesCat, RegistryCat, ShortcutsCat }

    public sealed class FeatureNode : System.ComponentModel.INotifyPropertyChanged
    {
        public string Key = "";
        public string ParentKey = "";
        public System.Data.DataRow? FeatRow;
        public FeatureNode? Parent;
        public FeatNodeKind Kind = FeatNodeKind.Feature;
        public string ComponentKey = "";   // for Component and category nodes
        public System.Collections.ObjectModel.ObservableCollection<FeatureNode> Children { get; } =
            new System.Collections.ObjectModel.ObservableCollection<FeatureNode>();

        // Vector icons rather than emoji. The file-cabinet and arrow characters fall back to thin
        // monochrome outlines in Segoe UI Symbol, which is why they read as smudges beside the
        // colour glyphs. These are stroked paths in a 24x24 box: crisp at any size, the same in
        // both themes, and each one an actual drawing of the thing rather than the nearest
        // character that happened to exist.
        public System.Windows.Media.Geometry IconGeometry => Kind switch
        {
            FeatNodeKind.Component    => MsiIcons.Component,
            FeatNodeKind.FilesCat     => MsiIcons.Files,
            FeatNodeKind.RegistryCat  => MsiIcons.Registry,
            FeatNodeKind.ShortcutsCat => MsiIcons.Shortcut,
            _                         => MsiIcons.Feature
        };

        public System.Windows.Media.Brush IconBrush => Kind switch
        {
            FeatNodeKind.Component    => MsiIcons.ComponentBrush,
            FeatNodeKind.FilesCat     => MsiIcons.FilesBrush,
            FeatNodeKind.RegistryCat  => MsiIcons.RegistryBrush,
            FeatNodeKind.ShortcutsCat => MsiIcons.ShortcutBrush,
            _                         => MsiIcons.FeatureBrush
        };

