        public bool IsExpanded { get => _isExpanded; set { if (_isExpanded != value) { _isExpanded = value; OnChanged(nameof(IsExpanded)); } } }
        public bool IsSelected { get => _isSelected; set { if (_isSelected != value) { _isSelected = value; OnChanged(nameof(IsSelected)); } } }

        private string _name, _summary;
        public string Name    { get => _name;    private set { if (_name    != value) { _name    = value; OnChanged(nameof(Name)); } } }
        public string Summary { get => _summary; private set { if (_summary != value) { _summary = value; OnChanged(nameof(Summary)); } } }
        public void Update(string name, string summary) { Name = name; Summary = summary; }
        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
        private void OnChanged(string n) => PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(n));
    }

    public enum IniLevel { Root, File, Section, Entry }

    // A node in the INI tree: the file/section/entry shape of an .ini, over rows that carry all
    // three in every row. Row is set only on an entry.
    public sealed class IniItem : System.ComponentModel.INotifyPropertyChanged
    {
        public IniItem(IniLevel level, string name, string summary)
        { Level = level; _name = name; _summary = summary; }
        public IniLevel Level { get; }
        public System.Data.DataRow? Row { get; set; }
        public bool InRemoveTable { get; set; }
        public string FileName = "", DirProperty = "", Section = "";
        public System.Collections.ObjectModel.ObservableCollection<IniItem> Children { get; } = new();

        // Level never changes once the node is built, so these need no change notification.
        public System.Windows.Media.Geometry IconGeometry => Level switch
        {
            IniLevel.Root    => MsiIcons.IniFiles,
            IniLevel.File    => MsiIcons.IniFile,
            IniLevel.Section => MsiIcons.IniSection,
            _                => MsiIcons.IniEntry,
        };
        public System.Windows.Media.Brush IconBrush => Level switch
        {
            IniLevel.Root    => MsiIcons.IniFilesBrush,
            IniLevel.File    => MsiIcons.IniFileBrush,
            IniLevel.Section => MsiIcons.IniSectionBrush,
            _                => MsiIcons.IniEntryBrush,
        };

        private bool _isExpanded, _isSelected;
        public bool IsExpanded { get => _isExpanded; set { if (_isExpanded != value) { _isExpanded = value; OnChanged(nameof(IsExpanded)); } } }
        public bool IsSelected { get => _isSelected; set { if (_isSelected != value) { _isSelected = value; OnChanged(nameof(IsSelected)); } } }

        private string _name, _summary;
        public string Name    { get => _name;    private set { if (_name    != value) { _name    = value; OnChanged(nameof(Name)); } } }
        public string Summary { get => _summary; private set { if (_summary != value) { _summary = value; OnChanged(nameof(Summary)); } } }
        public void Update(string name, string summary) { Name = name; Summary = summary; }
        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
        private void OnChanged(string n) => PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(n));
    }

    // A node in the services tree: one service name, with whichever of its two rows exist.
    public sealed class SvcItem : System.ComponentModel.INotifyPropertyChanged
    {
        public SvcItem(string name, string summary) { _name = name; _summary = summary; }
        public System.Data.DataRow? InstallRow { get; set; }
        public System.Data.DataRow? ControlRow { get; set; }
        public int ExtraControlRows { get; set; }
        public bool IsRoot { get; set; }
        public System.Collections.ObjectModel.ObservableCollection<SvcItem> Children { get; } = new();

        private bool _isExpanded, _isSelected;
        public bool IsExpanded { get => _isExpanded; set { if (_isExpanded != value) { _isExpanded = value; OnChanged(nameof(IsExpanded)); } } }
        public bool IsSelected { get => _isSelected; set { if (_isSelected != value) { _isSelected = value; OnChanged(nameof(IsSelected)); } } }

        private string _name, _summary;
        public string Name    { get => _name;    private set { if (_name    != value) { _name    = value; OnChanged(nameof(Name)); } } }
        public string Summary { get => _summary; private set { if (_summary != value) { _summary = value; OnChanged(nameof(Summary)); } } }
        public void Update(string name, string summary) { Name = name; Summary = summary; }
        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
        private void OnChanged(string n) => PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(n));
    }

    // A node in the environment-variables tree. Row is null only for the root.
    public sealed class EnvItem : System.ComponentModel.INotifyPropertyChanged
    {
        public EnvItem(System.Data.DataRow? row, string name, string summary)
        { Row = row; _name = name; _summary = summary; }
        public System.Data.DataRow? Row { get; }
        public bool IsRoot { get; set; }
