        public bool IsSelected { get => _isSelected; set { if (_isSelected != value) { _isSelected = value; OnChanged(nameof(IsSelected)); } } }

        private string _name, _summary;
        public string Name    { get => _name;    private set { if (_name    != value) { _name    = value; OnChanged(nameof(Name)); } } }
        public string Summary { get => _summary; private set { if (_summary != value) { _summary = value; OnChanged(nameof(Summary)); } } }
        public void Update(string name, string summary) { Name = name; Summary = summary; }
        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
        private void OnChanged(string n) => PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(n));
    }

    // A row in a sequence table (ordering number, action, condition).
    public sealed class SeqRow : System.ComponentModel.INotifyPropertyChanged
    {
        public SeqRow(System.Data.DataRow row, string seq, string action, string condition)
        { Row = row; _seq = seq; _action = action; _condition = condition; }
        public System.Data.DataRow Row { get; }
        private string _seq, _action, _condition;
        public string Seq       { get => _seq;       private set { if (_seq       != value) { _seq       = value; OnChanged(nameof(Seq)); } } }
        public string Action    { get => _action;    private set { if (_action    != value) { _action    = value; OnChanged(nameof(Action)); } } }
        public string Condition { get => _condition; private set { if (_condition != value) { _condition = value; OnChanged(nameof(Condition)); } } }
        public void UpdateSeq(string v) => Seq = v;
        public void UpdateAction(string v) => Action = v;
        public void UpdateCondition(string v) => Condition = v;
        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
        private void OnChanged(string n) => PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(n));
    }

    /// <summary>
    /// Every line-art icon the Visual view draws, in one place so the categories list and the four
    /// trees beside it cannot drift apart. All are 24x24 outlines meant for a 2px round-capped
    /// stroke, and the colour says which category a node belongs to rather than what shape it is.
    /// </summary>
    public static class MsiIcons
    {
        private static System.Windows.Media.Geometry Geo(string data)
        {
            var g = System.Windows.Media.Geometry.Parse(data);
            g.Freeze();
            return g;
        }

        private static System.Windows.Media.Brush Br(string hex)
        {
            var b = new System.Windows.Media.SolidColorBrush(
                (System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(hex)!);
            b.Freeze();
            return b;
        }

        // A set of things chosen together.
        public static readonly System.Windows.Media.Geometry Feature = Geo(
            "M12,3 L21,7.5 L12,12 L3,7.5 Z M3,12 L12,16.5 L21,12 M3,16.5 L12,21 L21,16.5");
        // The closed box that actually gets installed.
        public static readonly System.Windows.Media.Geometry Component = Geo(
            "M12,2.5 L21,7 L21,17 L12,21.5 L3,17 L3,7 Z M3,7 L12,11.5 L21,7 M12,11.5 L12,21.5");
        // A page with a folded corner and a few lines of content.
        public static readonly System.Windows.Media.Geometry Files = Geo(
            "M6.5,2.5 H14 L18,6.5 V21.5 H6.5 Z M14,2.5 V6.5 H18 M9.5,11 H15 M9.5,14.5 H15 M9.5,18 H13");
        // An editor window, key pane on the left and values on the right.
        public static readonly System.Windows.Media.Geometry Registry = Geo(
            "M3,4.5 H21 V19.5 H3 Z M3,8.5 H21 M9.5,8.5 V19.5 M5.5,12 H7.5 M5.5,15.5 H7.5 "
          + "M12.5,12 H18 M12.5,15.5 H18");
        // A window with the arrow Windows overlays on a shortcut leaving its corner.
        public static readonly System.Windows.Media.Geometry Shortcut = Geo(
            "M13,4 H5 V19 H20 V11 M14,10 L20.5,3.5 M15.5,3.5 H20.5 V8.5");
        // A tabbed folder, for every branch node in the Files, Registry and Shortcuts trees.
        public static readonly System.Windows.Media.Geometry Folder = Geo(
            "M3,18.5 V5.5 H9.5 L11.5,8 H21 V18.5 Z");

        // The INI tree has four kinds of node and used to draw one glyph for all of them, so a
        // file, a section and an entry were told apart only by how far they were indented. A stack
        // of pages for the set, one page for a file, brackets for a [Section], and the lines of a
        // settings entry for the key itself.
        public static readonly System.Windows.Media.Geometry IniFiles = Geo(
            "M8,6 H20.5 V21.5 H8 Z M4.5,18 V2.5 H17 V6");
        public static readonly System.Windows.Media.Geometry IniFile = Geo(
            "M6.5,2.5 H17.5 V21.5 H6.5 Z M11,7.5 H9.5 V12 H11 M13,7.5 H14.5 V12 H13 M9.5,16.5 H14.5");
        public static readonly System.Windows.Media.Geometry IniSection = Geo(
            "M10,4 H6 V20 H10 M14,4 H18 V20 H14");
        public static readonly System.Windows.Media.Geometry IniEntry = Geo(
            "M4,7 H20 M4,13 H13 M4,19 H20");

        public static readonly System.Windows.Media.Brush FeatureBrush   = Br("#A78BFA");
        public static readonly System.Windows.Media.Brush ComponentBrush = Br("#7C6CF0");
        public static readonly System.Windows.Media.Brush FilesBrush     = Br("#4C9AFF");
        public static readonly System.Windows.Media.Brush RegistryBrush  = Br("#2FB3A3");
        public static readonly System.Windows.Media.Brush ShortcutBrush  = Br("#E8912D");

        // One colour per INI level as well as one shape, so the level reads before the glyph does.
        public static readonly System.Windows.Media.Brush IniFilesBrush   = Br("#7C6CF0");
        public static readonly System.Windows.Media.Brush IniFileBrush    = Br("#4C9AFF");
        public static readonly System.Windows.Media.Brush IniSectionBrush = Br("#E8912D");
        public static readonly System.Windows.Media.Brush IniEntryBrush   = Br("#2FB3A3");
    }

    // An entry in the Upgrade table (a related-product detection rule).
    public sealed class UpgItem : System.ComponentModel.INotifyPropertyChanged
    {
        public UpgItem(System.Data.DataRow row, string title, string sub, string arrow = "\u2B06")
        { Row = row; _title = title; _sub = sub; _arrow = arrow; }
        public System.Data.DataRow Row { get; }
        private string _title, _sub, _arrow;
        public string Title { get => _title; private set { if (_title != value) { _title = value; OnChanged(nameof(Title)); } } }
        public string Sub   { get => _sub;   private set { if (_sub   != value) { _sub   = value; OnChanged(nameof(Sub)); } } }
        /// <summary>Up for an upgrade range, down for the downgrade guard. Bound by the list template.</summary>
        public string Arrow { get => _arrow; private set { if (_arrow != value) { _arrow = value; OnChanged(nameof(Arrow)); } } }
        public void Update(string title, string sub) { Title = title; Sub = sub; }
        public void Update(string title, string sub, string arrow) { Title = title; Sub = sub; Arrow = arrow; }
        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
        private void OnChanged(string n) => PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(n));
    }
}
